Object.assign(window.__TXT,{"17500": "（案3）赵，左。左臂瘦削，屈伸不利，酸痛之势由肩及项，甚至上连头额。营虚生风，风入于络，久防偏枯。脉见细弦，治以和养。", "17501": "（案5）龚，右，十九。四肢麻痹，肌肤发痒，脉见细弦。治以和养。", "17502": "（案6）王，右。风痹走窜，去年腰以下酸而且痛，近则胸背牵引，脉象沉弦。拟以和养。", "17503": "（案7）胡，右，三十一。产前受风，风郁感邪，腰俞下酸痛无度，近乎半身不遂，脉见细弦。治以温养。", "17504": "（案8）沈，右。血亏生风，腕后上升及背，皆为不利，脉见细弦。治以疏和。", "17505": "复诊：示及舌腻渐退，根苔尚厚，胃纳略开，仍未如常。久有风患，屈伸虽利，步履欠稳。湿由脾生，风从肝发，两者互扰，外则走窜络脉，内则阻遏中宫，外偏于风，内偏于湿，新旧病皆根于此。拟方即候政行。", "17506": "复诊：气虚生痰，营虚生风，风邪挟痰走窜经隧，偏左肢骱酸痛，手则不能高举，足则开步不利，脉右部滑大、左部细弦，舌苔黄腻，纳食欠旺，禀体丰腴。气分早亏，以脉合症，又属气虚于营。《经》云：卫气虚则不用，营气虚则不仁。拟宗此旨立方调理，谅无不合，录方即候政行。", "17507": "（案11）顾，右，五十六。喉痹起因痰热，又复挟风，渐至手痉面麻，言语舌强，脉见弦滑。治以清熄。", "17508": "（案12）朱，左。风中廉泉，口不能言，舌则为短，割而又为长伸，四肢掣动，脉息弦滑。拟以和养。", "17509": "（案13）陈，左。中风偏左，左者为瘫，手足屈伸不利，抽搐无度，舌音不清，脉见细弦。拟温降熄风。", "17510": "（案14）汤，右。左瘫右痪，现属于右，手足麻木不仁，皆由营虚生风，风痰走窜，络脉不能流利机关。脉见细弦，拟以温养。", "17511": "复：偏风于右，肢节骱皆为肿痛，痛甚于夜。营阴不足，内风袭络所致，脉见沉弦。再以和养。", "17512": "（案15）徐，左。气虚生痰，阴虚生风，风邪挟痰走窜经隧，不能流利机关。始起右臂屈而不伸，继则由手及足，由右及左，四肢皆为不利。考肝生风，脾生痰，肝邪侮脾。近时腹膨筋露，脉来弦滑，恐成瘫痪，宜加意调理。", "17513": "（案1）金，右。肝阴不足，肝阳有余，阳化内风，上扰清空，两目起星，渐近失明。关系者又在头眩屡发，厥阴冲犯阳明、太阴，当要呕逆，泛痰每每牵连并作，脉见细弦，舌苔中剥，气与阴亏，风与痰盛，久防类中。拟以和养。", "17514": "（案2）胡，左。上重下轻，头蒙发眩，两足酸软，脉细而弦，最防类中。", "17515": "（案1）高，左。头疼时冲，或呕或溏，脉见细弦，治以疏和。", "17516": "（案4）陶，左，三十二。头风有根，每发必为泛恶，脉弦舌腻，治以疏和。", "17517": "复：头风痛发额筋抽搐，夜甚于昼，冲犯中焦，并为呕泛，脉息沉弦。治以和降。", "17518": "（案5）冯，左，廿四。头风有根，受凉易发，发甚肝邪犯中，即为呕吐，脉息沉弦。治以调降。", "17519": "（案6）傅，左。真水素亏，肝邪上扰，头痛与牙痛时作而时伏，脉左弦于右，属木凌土位，纳呆神倦，有由来也。拟以和养。", "17520": "（案7）任，左。肝阳胃热挟风扰动，牙痛甚，发连及头额。现在痛势虽平，尚牙龈浮肿，齿亦动摇，脉见弦数。半虚半实，虚属阴分素亏，实为余邪未尽。拟以清泄。", "17521": "（案8）沈，左。真阴内亏，气火为炽，火本热，热生风，上扰清空，头蒙烘烘，耳鸣目涩，甚至风从外越，时起风块，风火走窜，肉𥆧不宁，腹痛热炽。种种肝肾内虚，龙雷失潜，脉见细弦，治以镇养。", "17522": "（案9）费，右。左颊酸疼，牙床开合不利，脉见细滑。治以和养。", "17523": "（案10）杨，右。营阴内亏，肝邪化风，头痛频仍，右部为多，甚则满顶皆痛，脉息沉弦。并无感冒，证情皆由内发，久防目损。治以和养。", "17524": "（案11）张，左。肝风入络，由于阳化内风，左面部抽搐无度，脉见细弦。治以和养。", "17525": "（案1）王，右。历节风走窜遍体，头痛耳鸣，肝阳挟痰，颈项成疬，脉见细弦。属营虚生风，气虚生痰。治以和养。", "17526": "复：历节风象，逢骱皆痛，脉细舌光。治以和养。", "17527": "（案2）裘，右，五十四。历节风痛，由足及手，由右及左，脉细舌光。属营虚生风。治以和养。", "17528": "（案3）何，右，四十七。逢骱酸痛，且麻且肿，防成历节风痛，脉见细弦。治以疏和，兼顾脘胀纳呆。", "17529": "（案1）朱，左。湿热挟风，外达肌表，发为游风，起瘰发痒，脉见沉弦。治以宣化。", "17530": "（案3）陈，左。游风之类遍体滋窜，脉见细弦。治以清养。", "17531": "（案4）秦，右，四十。游风遍体，发痒无度，脉见细弦。治以清降。", "17532": "（案6）冷，左，五十六。游风渐成，上下体俱为滋蔓，脉见沉弦，治以清化。", "17533": "（案1）顾，右，五十六。冷麻风且冷且麻，甚于右手左足，脉细弦。治以和养。", "17534": "（案1）薛，左。肩风发于腰痛之后，本元为虚，属水不涵木，指甲枯脱，脉见细弦。治以和养。", "17535": "（案2）骆，左。体倦绵延，肩胛酸痛，纳呆，脉细，防成肩风。", "17536": "（案3）陈，左，三十二。肩风酸痛，脉见细弦。拟以和养。", "17537": "（案4）汪，右。肩风之处结核不一，气与营早亏，风与痰用事，脉见细弦。拟调气化痰，和营熄风。", "17538": "（案1）尤，左。紫云风根尚未脱体，现在胁痛目赤，脉见细弦。治以清降。", "17539": "（案1）钱，左，四十六。四弯风肢酸发痒，脉见细弦，肺脾为患。", "17540": "（案2）徐，右，三十六。四弯风拳至不仁，脉见细弦，属气痹营伤，拟药酒方。", "17541": "（案3）唐，右，廿二。产后营亏生风，风邪挟湿走窜经隧，两足酸软，膝盖肿势虽退，仍伸而难屈，两手亦为发麻，将成四弯风，脉见细弦。治以疏和。", "17542": "（案1）杨，左，十四。驴唇风根，向春又发，脉见细弦。治以和养。", "17543": "（案2）博，右。禀体阴虚郁热蒸痰，发于少阳部则为子母疬，发于阳明部则为驴唇风，脉见弦数。自痧疹后阴分更伤，肌肤皆为枯燥。拟以清养。", "17544": "（案2）梁，左。足跟酸痛，防成漏蹄风。气虚生湿，营虚生风，风邪湿邪流窜络脉，脉见沉弦带滑，防上盛下轻，头眩耳鸣。治以镇养。", "17545": "（案1）徐，左。昔年痞散下血，血下过多，络脉失养，颈项转侧不利，两足骨粗肉削，渐成鹤膝风象，脉见沉弦。拟以和养。", "17546": "（案1）徐，右。肝气犯中，中焦积痰蓄饮，当脘痛胀，吞酸吐沫，气入于络，腰背胁部以及手足络脉皆为牵引，奇经遂失禀丽，产后经久不行，脉见细弦。治以和养。", "17547": "复：久有肝气，自产后营阴大伤，厥阴更为失养，皆以春令应肝，肝邪遂为鸱张，既犯中，又入络，脘腹胀满，遍体络脉牵引不和。肝通于心，心亦为悸，奇经因之失丽。癸事不行已经连月，种种营亏气痹，木土不协，脉见细弦。治以调降。", "17548": "（案2）殷，右。昔年产后血晕受伤，奇经不调，自崩放后经事二年未行，带脉反为不固。营阴日亏，肝木失养，化气侮中，或呕或胀，少腹痞攻，化风上扰，或痛或晕，头目昏沉。脉见细弦，舌苔前半光剥。种种营虚气痹，木土不协，拟以调养。", "17549": "（案3）粟，右。连次偏产，营亏气痹，当脘作胀，纳食久呆，脉见细弦。拟以和养。", "17550": "（案4）费，右。脉息滑数，怀麟有兆，适当手厥阴司胎，胎火上升则面热，胎络下损则腰楚。由手经病及足经，肝气又为内扰，或胀或痛，吞酸发嗳。拟以调养，藉防滑胎。", "17551": "（案5）包，右。气郁动肝，肝邪充斥，中焦受侮，当脘作痛，痛势扰腰及背，皆为牵引，脉见细弦。治以调降。", "17552": "（案6）王，右。血不养肝，肝气充斥，犯于胃则呕逆无度，侮于脾则大便溏薄，关系者尤在脘宇结痞，痞攻无度，甚则大如覆盘，脉见细弦。治以疏和。", "17553": "（案7）缪，左。淋浊止后，精溺未曾分清，肾为胃关，以致中焦失运，吞酸吐沫，结痞作胀，脉见沉细。拟固肾以养肝，柔肝以保胃。", "17554": "（案8）沈，左。当脘满闷，屡屡发嗳，多纳即为作胀，属脾失其使，胃失其市，中焦升降失职，水谷不化精华，而生痰饮，久防反胃，脉见沉弦。治以调降。", "17555": "（案1）凌，右。环跳酸痛，背脊酸软，尾闾尤甚，脉见弦数。最恐由损经而进劳径，有人身缩短之虞。", "17556": "（案3）程，右，廿八。咳呛绵延，连次失血，一伤于产乳，再伤于殴打，以致头眩艰寐，潮热形寒，胸胁肩背皆为引痛，脉见芤弦。治以和养。", "17557": "（案4）高，左。季胁乃脏会之所，内络受伤，胁痛频仍，形黄便血。脉见沉弦，治以疏和。", "17558": "（案5）胡，右，三十八。迸力伤气，气不摄血，血为暴吐，咳嗽神疲，脉见细弦。治以疏和。", "17559": "（案6）颜，左，十八。跌仆受伤，左胁作痛，腹部痞攻，或隐或见，逢节每为发动，近复纳食呆钝，且有胀满，脉息弦滑。阴虚之体，气分不调。拟以和养。", "17560": "（案1）俞，左。春温挟湿，身热微寒，有汗不解，脉见浮滑，舌色带灰。治以分泄。", "17561": "（案4）刘，左。春温之邪扰于阳明营分，牙衄口臭，脉息滑大。拟以清降，兼顾痘毒未清。", "17562": "复：身热渐除，仍咳呛脘闷，脉息细弦。再以分泄。", "17563": "（案1）杨，左。身热不解，头痛口渴，温邪郁蒸，势将发㾦，脉见浮弦。治以分泄。", "17564": "（案3）吴，左，廿四。旧伤新感，寒热咳呛，胁旁引痛，脉见浮弦。治以和降。", "17565": "（案4）叶，左。身热少许，脘痛便秘，表解而里未通，仍防神志昏迷，脉浮。拟以清泄。", "17566": "（案5）张，左。风温之邪，首先犯肺，郁热蒸痰，煽烁不解，咳嗽喉鸣，气逆胁痛，关系者在舌苔罩灰质红起腐，势将劫津为变，脉两手弦数。拟以清解。", "17567": "（案6）孔，左。脉两手数大，舌尖绛且有芒削，肌灼少汗，脘腹胀痛，痛而拒按，便闭口渴，谵语手痉。此乃邪入营分，食滞中焦，颇为棘手，难许无虞。", "17568": "（案1）陈，左。霉令将临，湿邪内动，郁于阳则形寒形热，郁于阴则便涩溺短，脉见沉弦。治以疏和。", "17569": "（案2）顾，左，廿八。湿邪稍泄，湿蒸未除，口内或甜或咸，脘宇似闷非闷。现在纳呆便艰，阳明机关大为不利，浑身痹痛，脉见细弦。拟以疏和。", "17570": "（案3）龚，左。湿邪分布三焦，头眩肢酸，脘腹胀闷，气道不通，所谓清不升而浊不降，大便艰涩，舌黄脉细弦。拟芳香调中，分化上下。", "17571": "（案4）金，左，四十。身热淹缠，形寒头痛，脘闷肢酸，脉见弦滑。治以分泄。", "17572": "（案5）王，左，四十三。寒热渐除，尚肢酸脘闷，二便少畅，脉见细弦。治以疏泄。", "17573": "（案7）王，左，二十四。身热不扬，寒少热多，脘满舌白，口渴不甚引饮，脉见细弦。治以分泄。", "17574": "（案8）沈，右，四十一。脘宇胀满，肝气又复感邪，寒寒热热，防发疹㾦，脉见浮弦。治以分泄。", "17575": "（案9）唐，左，三十二。身热不扬，头痛便溏，下血伤体，感受湿温，脉见芤大。治以分泄。", "17576": "（案10）刘，左，四十。头痛肢酸，外寒内热，风暑湿邪三者互缠，脉见沉弦。治以疏和。", "17577": "（案11）朱，左，廿七。体倦绵延，霉令又复感邪，脘满纳呆，头痛溺赤，身热虽除，表里尚欠宣通，脉见浮大，舌腻。治以分泄。", "17578": "（案12）王，右。身热头痛，咳呛鼻衄，脉数口渴，风暑互感。治以分泄。", "17579": "（案13）王，左，廿八。湿浊困中，当脘懊𢙐，口苦舌腻，脉见沉弦。治以疏和。", "17580": "（案14）朱，右，四十五。当脘心痛，痛连腰背，时时泛水，脉见弦滑。寒热后治以疏和。", "17581": "（案15）王，左，廿八。中气不足，湿浊未清，纳少神倦，脘嘈气怯，脉细弦。再疏和。", "17582": "（案16）朱，右。㾦后又发细瘰，肢体满布，湿温之邪渐得清彻。惟中气受伤，神疲肢倦，纳食未得如常，脉见弦滑。拟从半虚半实调之。", "17583": "（案17）丁，左，三十七。便溏后腹痛纳少，脉见沉弦。治以疏和。", "17584": "（案18）杨，左。身热少汗，五日不解，胸脘满闷，并作恶心，神昏谵语，舌胖言强。外受风寒，内热湿温，郁邪无从出路，表汗不多，里便不爽，三焦弥漫，势防厥逆，脉见濡细。若隐疹不透，证非稳当。", "17585": "（案19）马，右，三十八。寒热未除，得汗不解，脘闷耳聋，渴不多饮，脉见滑大，舌苔带灰。湿温郁蒸，表里解而未畅，经后营舍空虚，防劫津为变。", "17586": "复：表得汗透，里得两便通行，湿温之邪已有出路，耳聋较减，神志较清，惟舌苔仍然灰腻，脉右部尚大，左部带数。再从清化。", "17587": "（案2）徐，左。身热出㾦，脘闷便溏，脉见浮弦。治以分泄。", "17588": "（案3）包，左。疹㾦密布，脘闷神烦，寒热或轻或重，脉见细弦。治以分泄。", "17589": "（案4）窦，左。寒热连日未解，脘闷气急，上为呕逆，下为溏稀，邪势仍未宣化，脉数而滑，两寸独不应指。上焦不能宣物，虽有疹㾦不能由里达表，治以清泄。", "17590": "（案6）邵，右。身热白㾦先起，脘闷呕逆，脉见细弦，肺胃受病。治以分泄。", "17591": "（案9）周，左，十八。痧㾦后内热未清，纳呆咳呛，耳聋盗汗，脉见弦滑。治以清养。", "17592": "复：疹痧后阴伤热炽，耳聋盗汗，咳呛肌灼，脉见弦数。再以清养。", "17593": "（案10）宋，左。㾦后内热未除，口渴纳少，脉见沉弦。治以和养。", "17594": "（案11）陈，左，十一。身热出㾦，㾦色枯白，上为口渴无度，下为大便溏薄，脉见细弦。治以分泄，兼顾咳呛耳聋。", "17595": "（案12）顾，左。㾦随汗，汗随热，呕恶绵延，肺胃之病，脉见细弦。治以和养。", "17596": "（案13）沈，左。寒少热多，白㾦出没，脘腹痛胀亦未见轻。邪入气分，逗留不解，脉左弦右滑，舌苔前半脱液根腻，属虚中挟实，实中挟虚。拟分化三焦，略兼存津养液法。", "17597": "（案2）吴，右，十四。湿温身热，㾦随汗布，耳聋口渴，舌苔灰黄。以上见证属时邪应有之义，尚不关系。吃紧者，误服下剂，胃阴胃气两为受伤，纳食不思，肢清气怯，睡中露睛，汗多发冷，脉左部模糊，右大至数不匀。防正不胜邪，由闭而脱。", "17598": "复：昨投清营养胃法，便溏已止，舌灰略退。阴液有上升之势，四肢虽清，热来尚暖，脾阳有灌溉之机。关系者，误下伤阴，胃无醒豁之象，纳食不思，汗出淋漓。心失营液为养，神志倦怠，脉象如昨，再以前意增损，未识然否。", "17599": "（案1）钱，左，三十六。身热脘闷，痱疹满发，脉见弦滑。治以分泄。", "17600": "（案1）汪，左，四十八。初起身热不扬，至第二日热甚，神志模糊，不知人事，舌光红根灰，脉右部如无，左部细数。吸烟之体，益以发病前一夜通宵不寐，故邪入里最速。用犀角四分、鲜菖蒲、竹沥、连翘、竹芯、桑叶、杭菊花、薄荷尖、西瓜翠等药一剂，神志已清，诸恙均松，接后方。", "17601": "复：昨投宣窍涤痰峻利，神志已得清楚，惟身热未清，有汗不多，口渴无度，大便虽通，脘宇略有窒塞。脉右部已起，且滑且大，微带数象，左部一律如是，舌灰色已退，仍根带黄腻，尖光绛。风暑挟痰，尚少清彻，再从清解，候政。", "17602": "（案1）徐，左，十九。身热头痛咳呛，舌光，口渴无度，脉见浮弦。治以分泄。", "17603": "（案3）朱，左。寒热之后，燥邪未得清彻，客于肺胃，牙龈浮肿，咳呛无度，脉见弦大，舌苔光红。治以清泄。", "17604": "（案4）富，左，廿八。燥邪客于上焦，牙肿喉痛，咳呛不爽。脉息浮大，治以辛凉。", "17605": "（案5）顾，左，九。会厌为吸门，系七冲之一。痰热内阻，呼吸不利，哮声如锯。脉见弦数。拟宣肺窍而化痰热。", "17606": "（案6）浦，左，十七。咽喉红痛，身寒发热，咳嗽口渴，脉息数大。治以辛凉分泄。", "17607": "（案1）顾，右。冬温郁蒸表里解而未解，有汗不多，大便不畅，呃忒口渴，当脘胀满，邪势方张，精液渐为劫烁，舌苔质红色灰薄如烟煤。脉两手滑大，左右寸重按模糊。温邪愈趋愈深，犯包络已有神昏，动肝风又将痉厥，高年正虚邪炽，势防内闭外脱。拟清阴泄邪，以图弋获。", "17608": "（案2）盛，左。身热无汗，咳呛口渴，入夜谵语，防冬温内陷为变，脉见浮弦。治以辛凉。", "17609": "（案1）王，右，廿。咽喉红痛，内热脉大，染苔舌灰。风暑挟痰，郁于上焦，当清凉分泄。", "17610": "复：咽喉红痛，减而未除，脉大身热，再以分泄。", "17611": "（案2）仇，右。风暑挟痰，项肿咽痛，口疳满布，脉浮大。治以分泄。", "17612": "（案1）冯，左。身热微寒，咳嗽头痛，势将发痧，脉见浮大。治以分泄。", "17613": "复：风痧已发，布于四肢头面，咳呛口干，咽喉红肿，脉见浮大，治以清解。", "17614": "复：热毒烁肺，喉腐，脉数大，治以清化。", "17615": "（案1）李，左，十一。痧后食复，身热有汗。向来脾胃失健，又有腹痛便溏，脉见细弦。治以疏和。", "17616": "（案1）蒋，左，十九。寒热后胃气为逆，呃忒频仍，纳呆脘闷，脉见细弦。治以疏和。", "17617": "（案2）汪，左，三十四。寒热不扬，神迷发痉，口渴无度，呃忒频仍，右脉模糊，左脉细弦。阴寒外束，湿热内蒸，从此邪无出路，急防闭脱。", "17618": "（案1）姜，右。挥霍扰乱，泻而兼呕，脉见细弦，治以苦辛通降。", "17619": "（案2）徐，左。上吐下泻，汗冷肢清，脉细兼弦，治以疏和。", "17620": "（案3）朱，左。挥霍扰乱，勃然上吐下泻，当脘懊𢙐，汗多肢清，脉来沉细。治以分疏。", "17621": "（案4）费，左，四十。霍然扰乱，吐泻脘闷，脉见沉弦，治以分泄。", "17622": "游风多年，变为囊风，流滋发痒，甚于下部，脉来弦滑。治以清化。", "17623": "（案1）左，一岁。惊风挟痰，气逆音嘶，脉弦。治以清泄。", "17624": "（案2）王，左。哮喘重发，痰不爽吐，且带腥臭，脉见浮弦。治以宣解，兼顾形寒形热。", "17625": "（案1）左。久咳不已，娇脏受伤，痰中带血，其色不一，或黄或绿，肺痿渐成，脉见细弦。治以清养。", "17626": "（案2）左。内有痰饮，外感风寒，哮嗽有根，发而较重，胸次痹闷，气逆喉鸣，脉见细弦。治以和降。", "17627": "（案3）左。胸痹喉鸣，哮喘又发，脉息细弦。治以和降。", "17628": "（案4）左。哮嗽重发，喉鸣气逆，寒热脉细。属旧病新邪，治以和养。", "17629": "（案5）左。哮嗽重发，即为肺胀，喉痰呜呜，未能爽吐，脉息沉弦。治以疏降。", "17630": "复：肺胀频仍，咳痰稍松，脉息细弦。宣肺气而豁痰饮。", "17631": "（案6）右。痰沫涌吐，哮嗽日进日深，脉见细弦。拟以和降。", "17632": "（案1）左。咳减喘轻，肺肾渐有相生之势，平日操心过度。考心居肺肾之间，有时艰寐，有时懊𢙐，侵晨出汗，脉见细软，左关较弦。拟甘缓调降，藉摄心神。", "17633": "（案2）右。上虚生痰，下虚生饮，积痰蓄饮，咳嗽多年，或平或发。近时薄有感冒，咳势较重，喘不能睡，属肺俯肾仰，两为失司。考女科以肝为先天，种种气痹营亏，冲海无权，月事多年未行，并非干血成劳，以致诸虚杂出，头蒙心悸，腰酸肢倦。脉息细弦，虚多感少。拟以甘缓调降。", "17634": "（案3）左。痰饮内积，肺肾气道失宣，咳呛无度，痰多气喘，脉息细弦。治以和降。", "17635": "（案4）左。冲失坐镇，气从腹旁上冲，咳嗽甚于早起，有时发呕，脉息细软，从虚多邪少调之。", "17636": "（案1）咳嗽有根，与年俱进，每发先为寒热，属气虚积饮，肺失卫外，以致气喘痰沫，屡屡发呕，脉见沉弦。治以和降。", "17637": "（案2）右。气虚生痰，阴虚生饮，痰饮咳嗽，肺俯肾仰，两为失司，脉见细弦。日后慎防络伤失血，拟以和养。", "17638": "（案3）右。痰饮伤中，中主表里之权。咳嗽未减而寒热交作，肢冷背寒，神疲嗜卧，两日稍解而未清。前诊脉之细弦、舌之黄剥，显属表失卫外，里失主中。", "17639": "（案4）左。两脉俱静，左静则根本无损，右静则感冒渐清。寒热已止，大便通畅，惟侵晨尚有咳痰，白沫中略有黏腻，最恐扰动肺痿旧根。当长夏炎热方兴未艾，最宜保护气脏。再须清热和阴，新旧病兼顾为宜。", "17640": "（案5）左。咳嗽绵延，音嘶痰沫，肉落气逆，脉左细右弦，气虚见症为多。拟以和养。", "17641": "（案6）左。咳嗽绵延，背脊酸痛，恶风神倦。春季虽为失血，血尚不多，脉见细弦，脱力内伤，气与阴两为不足，治以和养。", "17642": "（案7）左。咳嗽未减，夜重于日，痰多气怯，关系者形寒潮热，营卫之伤最难调护。脉芤，拟以和养。", "17643": "（案8）左。肝升太过，肺降无权，咳呛绵延，气逆无痰，两胁每每引痛，时时面部火升，势防天热失血。脉息沉弦，治以清降。", "17644": "（案10）左。因感起咳，咳而无痰，胁痛气逆，脉息细弦。最防失血成劳，拟以和养。", "17645": "（案11）左。脉左部弦大甚于关位，属春令应肝，肝邪为炽，加以素有遗泄，水不涵木，厥阴更为失养，以致有升少降，上烁娇脏，咳呛虽属不甚，行动即为气逆。关系又在失血，血发连次，所吐甚红，由阴伤气，气分渐为不调，食后每每腹胀。防进而足肿便溏，即属过中难治，拟以和养。", "17646": "（案12）孔，左。失血渐止，痰中尚为带溢，肝肺两虚，肺失降为咳呛，肝不和为胁痛。脉见数滑。青年最防入损，再从清养。", "17647": "复：失血已平，肝升肺降仍属未知，痰胶气逆咳呛之势，夜甚于日，脉见数滑。再从清养，兼和中以开胃纳。", "17648": "（案13）梅，左。连年见血，每每逢节而发，发时或多或少，整口色鲜。由阳明损及肝肺，肺不降为咳呛，肝不和为胁痛，渐至音嘶盗汗，潮热形寒，关系尤在便溏，有损而过中之势。脉息弦滑，拟以和养。", "17649": "（案14）王，左。英发太早，湿热下注，肛痈未敛，内管渐成。肺肠为表里，咳嗽绵延，痰薄且黏，夏令防失血成损。治以清养急和，左脉弦数。", "17650": "（案15）左。早有遗泄，近发失血，遂致肝升肺降，两为失司，咳嗽气逆。穷则伤肾，诸虚杂出，形寒潮热，咽干艰寐，肢腰酸楚，盗汗淋漓。脉见芤数，右部为甚，治以和养。", "17651": "复：遗泄不发，失血亦不见重，惟关系者尤在咳嗽气怯，喘须高枕，痰多成罐。营卫早为偏胜，形寒潮热，且又出汗，心烦神倦。脉见细软，根本大伤，夏令能否有减无损，再拟甘平清降。", "17652": "（案1）沈，左。跌仆受伤，左胁迸痛，呕血又发，脉沉弦。治以和降。", "17653": "（案1）左。勃然吐血，两胁作痛，脉见沉弦。治以和降。", "17654": "（案2）左。血随气沸，勃然吐血，当脘发迸，两胁引痛，内伤胃络显然。脉见沉弦，治以和降。", "17655": "（案3）左。无端失血，整口色鲜。由胃络而伤肝肺，渐加咳嗽。脉见芤大，治以清降。", "17656": "（案4）左。吐血连日未止，由阳明而传肝肺，渐加咳嗽。脉见芤弦，治以和降。", "17657": "（案5）左。咳呛失血，内热脉数，治以清降。", "17658": "（案6）左。阳明为多气多血之经，血随气沸，或紫或红，皆属整口。久防损及肝肺，渐加咳嗽。脉见弦数，治以和降。", "17659": "（案7）左。素有遗泄，以致龙相失潜，燥灼之势上冲于胃，阳明之血随气火上腾，每发血时心烦神躁，坐立不安。热迫营阴，气火用事。脉见芤弦，治以和养。", "17660": "（案1）左。咳呛失血，口鼻俱溢，脉见弦滑。治以清降。", "17661": "复：口鼻之血，再和咳嗽，脉细。", "17662": "（案1）左。腹痞胀满，阴阳络两为受伤，鼻血便血，形黄内热。脉见弦滑，治以疏和。", "17663": "（案2）陆，左。腹痞攻胀，阴阳络伤，吐血虽止，便血未除。脉见沉弦，再以调降。", "17664": "（案3）柴，左。腹痞肢肿，形黄神倦，脉见细弦。阴阳络伤，鼻血虽止，便血未除。治以疏和。", "17665": "（案6）陈，左。腹痛痞攻，便血澼澼，脉息细弦，治以疏和。", "17666": "（案7）周，左。便血体肝脾早伤，右腹结痞攻动作痛，痛连腰部，脉来细软。治以温通。", "17667": "（案8）左。腹痛痞攻，内热肌灼，脉数。拟清阴调中。", "17668": "（案9）左。腹痞痛胀，咳呛肢肿，属旧伤新邪，肺脾同病。脉见细弦。拟以疏和。", "17669": "（案11）左。中焦气痹，积痰蓄饮，当脘屡屡作痛，两痞交攻，溏泄亦因之而发，脉见沉弦。久防痰饮常扰，再加呕吐，拟以温通。", "17670": "（案12）右。腹痞便溏，经事应通未通，转为鼻血屡溢。脉见沉弦，治以疏和。", "17671": "（案13）左。肝脾肺三者俱伤，肝为胁痛，脾为痞胀，肺为咳呛。脉见沉弦，治以疏和。", "17672": "（案14）右。痞痛旧根，近发连及腰胁。脉见沉弦，治以疏和。", "17673": "（案1）袁，左。痰饮内阻，晨起咳嗽，胸痹气逆，痰沫不爽。脉见细弦，拟以和降。", "17674": "（案2）右。肝为之升，肺失其降，肝肺两病，此平彼作，咳嗽频仍，痰色不一，金不制木，肝邪益炽，胸痹脘满，痰沫涌吐，咽喉且痛。脉见沉弦，拟以通降。", "17675": "（案3）方，左。早有失血，去年复发。近日又有胸痹不舒，少腹结痞，肝肺久为受伤，脘宇窒塞，略有咳嗽。燔灼之令，恐血再来。脉风细弦，治以和降。", "17676": "（案2）右。吐血咳嗽，近来虽不加重，病情杂出，潮热盗汗，胃纳甚微，大便多次。上损及脾，月事渐枯；下损过胃，脾胃两伤，过中最险。脉见细软，舌光属虚多邪少，治以和养。", "17677": "（案3）左。肺脾两伤，上为咳嗽，下为便血，渐至肉落纳少，形寒潮热，势将由伤成劳。脉见弦滑，治以和养。", "17678": "（案3）右。红白痢，昼夜百计，脉见细弦。治以疏和。", "17679": "（案4）左。酒客湿热伤营，每便干结，带下赤痢，脉见细弦。由阳明而损肝脾，渐为腹痛形黄。拟以疏和。", "17680": "（案5）右。休息久痢新积，色白，脉见沉弦。拟苦辛固养。", "17681": "（案6）左。痢疾，小腹发迸，肛门气坠，欲便不利，属半虚半实。脉见沉弦，治以和养。", "17682": "（案8）右。肝脾失协，赤痢屡发，小腹迸痛，得食欠运。脉见细弦，拟以和养。", "17683": "（案9）右。休息痢有赤无白，腹痞攻痛，脉息濡细。阴虚之体，舌苔光剥。拟以和养。", "17684": "（案10）左。赤痢久而不止，腹痛肛痛，肢肿纳少，脉见细弦。拟以温养。", "17685": "（案11）左。赤白痢减，肛坠里急，脉见细弦。拟升清降浊。", "17686": "（案1）徐，左。幼年间鼻血吐血，阴分早亏，虚热内炽。现在热迫大肠，肠风绵延，血下如射。每便坚涩，肛痔外凸。关系者在梦泄，精血两伤，诸恙从此蜂集，神烦少寐，头眩目花，惊悸不宁，脉见弦大。治以清养。", "17687": "（案2）左。早有痰血，脏热移腑，传为肠风，血下如注，大便艰涩。由阴伤气，渐至纳少，神疲气逆肢倦。脉见弦滑，虚多邪少，治以和养。", "17688": "（案3）左。便燥带血，属肠风为多，久则损及肝脾，形黄腹痛，脉见沉弦。拟以和养。", "17689": "（案4）沈，左，四十二。阳明郁热，肝脾统脏两为失司，以致气陷为肛坠，营虚为肠风。脉息沉弦，舌苔微灰。嗜烟体气阴两伤，调理不可偏阴偏阳，治以和养。", "17690": "复：肠风绵延，或轻或重，血下如水，甚则后重，脉见沉弦。阳明郁热，肝脾又失统脏，以致营不为守，再以和养。", "17691": "（案1）左。痔血受伤，营虚热炽，阳明传送无权，大便坚结，数天一行，行而不畅，脉见弦大，舌苔光红。拟以清养。", "17692": "复：阳明郁热，痔血频仍，大便每每艰行。脉息弦细，虚多邪少，治以清养。", "17693": "（案1）左。痢久渐成便血，便之前后俱溢，昼夜六七行，腹痛里急，脉见沉弦，形黄肢肿，应月枯少。能否得复，治以和养。", "17694": "（案2）刘，左。肢腿之病尚不见发，惟湿火内蒸，随气下陷，阴分已伤，脱肛类痔，便艰下血，病滋水交流。阳明湿火触发，肝邪气逆作呕，上焦为患属阳明胃府，下焦为患属阳明大肠，邪热俱在阳明，遂至雷龙失潜。头胀频仍，少寐多梦，纳谷尚少，大便尚涩，所以左脉细弦，右脉弦大不静。属邪正相搏，治宜兼顾。", "17695": "（案3）左。便血绵延，脱肛腹痛，脉息濡细。治以疏和。", "17696": "（案4）孩。受凉伤中，洞泄无度，脉弦。拟以疏和。", "17697": "（案5）左。泄泻渐止，脘闷纳呆，脉见沉细，属半虚半实。拟以调中化邪。", "17698": "（案6）右。由血转痢，由痢转泻，纳呆，舌光，脉息沉弦。拟以和养。", "17699": "（案7）左。久泻不止，大腹膨满，得食作胀。向有遗泄便溏，由阴伤气，现在病寓中焦。脉象细弦，拟以调养。", "17700": "（案8）右。久泻不止，由脾及胃，胃纳作胀，土衰关乎火弱，舌剥肢肿，咳呛气逆。脉见细弦，治以疏和。", "17701": "（案9）右。生冷伤中，中焦积滞，腹部隐痛，便溏纳呆，防转为痢疾，脉来沉细。治以疏和。", "17702": "（案1）左。肺虚生痰，肾虚生饮，内扰咳嗽，绵延渐加气怯，上下摄纳无权，中焦亦失砥柱，纳食欠旺，两足浮肿，脉见沉弦。拟以和养。", "17703": "（案2）左。中气不振，积痰生饮，阻遏升降道路，脘宇攻动，漉漉有声，必得嗳气，然后松软。脉见沉弦，治以调降。", "17704": "（案3）朱，左。封藏早亏，水不涵木，木邪扰中，中焦积痰蓄饮，以致脐腹间似痞非痞，有时下陷转而上升，即为胸次窒塞，又复凌心，心悸艰寐，迫肾为之梦遗。种种升降失司，阴阳造偏，头眩耳鸣，鼻衄疝坠。脉见细弦，舌苔滑腻。虚中挟实，实即痰饮，拟交坎离而调木土。", "17705": "（案4）费，右。下虚生饮，气虚生痰，喘肿多年，痰不从咳而化，饮不从便而达，以致肢面皆肿，先为胁痛，由络脉泛滥肌肤，高年防气不归元。", "17706": "（案1）王，左。能食无力，大便屡解，有时当脘作痛，痛行臀部，得一转矢气较松。脉见沉弦，治以调养。", "17707": "（案1）朱，左，十六。暑风客邪，内伏募原，营卫不和，致发疟疾。少热多寒，脘闷头眩，脉见弦数。治以分泄，兼顾便坚腹痛，舌黄口渴。", "17708": "（案2）张，左。间日发疟，寒少热多，有时但热不寒，脘闷头痛，渴不多饮，便涩溺赤，脉见弦滑，舌苔黄腻。属风暑痰湿四邪交并，表里因之失宣，拟以疏和。", "17709": "（案1）刘，右，六十三。咳嗽痰薄，类疟寒热，脉见弦滑。治以分疏。", "17710": "复：类疟较轻，仍咳嗽痰多，当脘满闷，脉见弦滑。治以分泄。", "17711": "复：类疟已止，咳喘未除，脉见弦滑，治以疏和。", "17712": "（案1）左。间日发疟寒热满闷，咳嗽泛恶，脉见细弦。治以分疏。", "17713": "（案1）徐，左。三疟五年，劳动即发，寒热从中，营卫受伤。脉见濡细，属虚而非实，治以和养。", "17714": "（案2）左。劳倦成疟，是为劳疟。微寒微热，盗汗纳少，脉见濡细。拟和表里，兼顾咳嗽。", "17715": "（案3）左。三疟阵乱。呕泻仍作，脉见沉弦。治以疏和。", "17716": "（案1）左。疟母攻胀，肢酸脘闷，脉见细弦。治以疏和。", "17717": "（案2）左。疟母内损，头眩肢倦，便溏带血，脉见细弦。恐其成劳。", "17718": "（案1）左。狐疝出没无常，少腹牵引作痛，脉见沉弦。治以疏和。", "17719": "（案2）左。七疝中之狐疝，出没无常，其声呜呜然，属肝肾内虚，气为下陷，脉弦。治以和养。", "17720": "（案1）左。水疝胀大出水，脉见濡细，治以疏和。", "17721": "（案1）左。疝气两月未止，恐成𤻊疝。尾闾结核，亦属湿痰，脉见细弦，治以疏和。", "17722": "（案2）左。右部睪丸坚结不和，渐成𤻊象，惟目赤屡发。肝家素有郁热，一切过温之药似在禁例。脉见弦滑，治以清养。", "17723": "（案1）脚气疲软，朝退暮重，少腹发麻，气逆上升。脉见沉弦，再以通阳益气。", "17724": "（案3）左。干脚气，两足软不能行，手亦发麻，颇有上升之势，犯胃冲心皆能传变。脉见沉细，急须调治。", "17725": "复：脚气疲软难行，两手亦麻，脘闷纳少，脉见细弦。属脾肾致虚，风寒湿袭入络脉，仍从温养。", "17726": "（案4）左。脚气将成，恐上升为变。脉见细弦，拟去寒湿。", "17727": "（案5）程，左，五十一。脚气渐成，有升少降，少腹窒塞，手指发麻。塞湿之邪实少去路，二便又为失利，脉见沉弦，舌糙，急宜疏导。", "17728": "（案6）左。脚气暴起，两足见肿亮，手麻发痉，有积水上冲之势，脉浮弦。拟先开降。", "17729": "（案7）左。脚气将升，酸软不和，少腹、手指皆为发麻，恐其上冲为变。脉见沉细，治以和养。", "17730": "（案3）左。臌胀伤气易治，耗阴者最不易调。腹臌脐平，两便少行，脉左弦数，舌剥口渴。拟通关导水。", "17731": "（案4）右。肝脾内伤已成，臌胀两便失利，上逆为咳，脉见细弦。治以和降。", "17732": "（案5）左。单腹胀属脾胃，受伤不同，积水遏湿，通行即解，脉见沉弦。治以疏和。", "17733": "（案6）高，左，廿九。脘腹胀满，甚至肾囊俱肿，气急发呛，三焦不能分化，防成臌胀。脉见细弦，治以疏和。", "17734": "（案8）左。臌胀受温，温则气通逐水。脉见细弦，肝脾久伤。治以温通。", "17735": "（案9）左。肢肿腹满，肿势由下升上，咳呛不爽，舌苔粉白，脉息濡细。治以温通。", "17736": "（案10）左。痞散成臌，大腹发热，愈热愈大，脉芤无度。阴伤气痹，恐有不得了之势。", "17737": "（案11）左。水势狂溢，肿胀渐成，膨满腹大，囊肿色亮，泛滥之势上及高原，气喘有痰。脉息沉弦，拟通导沟渠。", "17738": "（案13）沈，左。皮水屡发，溺闭即肿，肿势上中下三焦俱到，脉见沉弦。治以通降。", "17739": "（案15）顾，左，五十四。肝脾久伤，腹膨放后，纳呆形黄，便多溺少。脉见细弦，治以疏和。", "17740": "顾复：两次放臌，腹满虽平，肝脾未免受伤，形黄疲倦，纳食不多，脉见细软。再从和养。", "17741": "（案2）左。阴耗阳结，谓之关格，随食随吐，更衣艰涩，攻补不受，大致气与液两亏，痰与饮用事。脉见细濡，调理为难。", "17742": "（案4）左。上格下关，谓之关格。所食无多尚欲吐出，吞酸吐沫，脘宇或痛或胀，更衣十余日一行，粪如羊矢，脉左右沉濡。气痹液耗，用药不可偏阴偏阳，拟以和降调中。", "17743": "（案5）李，左，三十四。关格数年，一饮一食皆难停留，必得吐尽后已，渐至气久不能升降。现在阴液亦为枯槁，呕甚见血，脘腹通连梗痛，脉六部细微。无六淫外感，亦无七情内发，昨晚形寒发热，寒暖不调所致，拟调中降逆。", "17744": "（案6）左。随食随吐，名曰上膈，脉见细弦，治以通降。", "17745": "（案7）左。上格为呕逆，下关为便闭，上下不和，由于中焦窒塞，当脘满闷，时发懊𢙐。脉见弦涩，弦主阴耗，涩主气痹，久延恐难调复。", "17746": "（案8）左。肝邪侮中，中有积饮，当脘作痛兼胀，吞酸吐沫，脉见细弦。中焦升降失调，厥阴遂为充斥，更衣不利，上格下关之势。", "17747": "（案9）右。上呕不止，下便不利，是为关格，脉见沉弦。老年阴耗阳结，难许调复。", "17748": "（案1）张，左。昔年痢后受伤，久而不复，大便有溏有结，溏时每为带血。营虚生风，气虚生湿，风湿之邪外游肌表，或寒或热，或为发瘰。关系者肛门发麻，有时上升，可及遍体。脉见细弦，治以疏和。", "17749": "复：休息痢后，有时下血作泻，由阳明垢滞，随去随生，以至肝脾受伤，生风挟湿，忽寒忽热，遍身发麻。最虑者，上至巅顶，下至肛门。脉见细弦，治以和养。", "17750": "（案1）艾，左，三十四。阳明、太阳之间，小肠之下，垢秽不能分化，当时满腹攻痛，渐至大便鲜通，囊为出粪，年余淹缠。脉见沉弦，拟分清降浊。", "17751": "复：大便失行，舍正路而不由，阴囊膜破，粪即由此而行，脉见濡软。证情淹缠，一时难复，拟以疏导。", "17752": "（案2）右。迸伤气分，膀胱失司，不约又为不利，下窍发坠，每溺作痛，所下且有血丝，脉见沉弦。治以和养。", "17753": "（案3）江，右。五淋中之劳淋，劳伤气迸，发为淋浊，赤白交下，每解痛苦非常。脉见沉弦，治以和养。", "17754": "（案4）左。高年阳盛阴热，向来便血，今复血渗膀胱，渐成尿血，连发未止。脉见细数，治以清养。", "17755": "（案1）王，左，四十。气虚下陷，小便先为不利，继以淋浊，遂至分化无权，其气由前向后，更衣欲通不通，气坠矢气难转。脉见细弦，舌苔黄白，拟以升补。", "17756": "（案2）左。气陷脱力，溲时仿佛精坠，发酸不禁，脉见濡细。拟以升补。", "17757": "（案3）左。精溺浑淆，小便不禁，且带白垢。脉见弦滑，治以和养。", "17758": "（案4）左。精溺未得分清，小便色浊，每解似有阻隔。脉见细弦，拟以清解。", "17759": "（案5）左，三十二。久则为淋，精溺窍两属受伤，溺为不禁，精为遗滑。脉见细软，拟以和养。", "17760": "（案7）邢，左，三十六。初则为浊，继则为淋。溺数微痒，热毒未清，脉见细弦，治以清降。", "17761": "（案8）左。迸伤为淋，便痛茎肿，囊筋牵引。脉见细弦，治以和养。", "17762": "（案9）左，廿九。湿热下注，溺痛如淋，且带浮肿，脉见细弦。治以通降，兼顾牙痛口疳。", "17763": "（案10）邢，左。初则为浊，溺痛发痒，郁邪未清。脉见细弦，治以通降。", "17764": "（案1）陈，左，三十四。脉禀六阳，阳充则阴不为守，久有遗泄，有梦渐为无梦。向春发而较勤，且有盗汗，种种心肾两亏，治以清养。", "17765": "（案2）左。遗泄有梦属心，无梦属肾，心虚于肾，梦泄频仍，有时艰寐，有时惊悸，诸恙交集，多属心肾两亏。脉见弦滑，拟以清养。", "17766": "（案4）姚，左。精关不固，梦泄复发，甚至小便不禁，脉见细弦。治以清养。", "17767": "（案6）程，左，三十四。外感渐清，诸恙轻减，惟心肾两为不济，肝主相火，跃跃欲动，艰寐稍平，仍关门不固，常常自遗。素有头眩耳鸣，皆属上盛下虚。脉见细弦，治以清养。", "17768": "（案7）左。精溺管混淆，出口管内微痛，似淋非淋，牵连肝胃，脘宇满闷，腹部鸣响，有时虚阳上升，头亦为蒙，脉见细弦。治以和养。", "17769": "（案8）左。著寒泛水，牵连脘胀，受热鼻血，又复遗精，遂至心跳气喘，神疲肢倦，脉见细软。治以和养。", "17770": "（案1）顾，左，十八。膀胱不纳，每每遗溺，脉见细弦，再从丸剂调理。", "17771": "（案1）右。肝邪为炽，溺数且痛，尊年有虚为多，不外三阴内虚，八脉郁热。现在薄有外感，脉见细弦，治以分泄。", "17772": "（案2）右。本有痛经，现在小溲频数，脉见细弦，拟以升补。", "17773": "（案3）左。小溲迸痛，久为不禁不约，溺数无度。现在脉沉，能否支持。", "17774": "（案1）左，十三。癃闭有根。近发较甚，每溺痛而不利。脉见细弦，治以通降。", "17775": "（案1）王，左，四十一。示及心烦足软，目赤颧红，盗汗频仍，小溺数解，舌苔少液，脉象见弦。肝邪者，尤在阳刚易举，有时泄精。考精藏于肾，汗属于心，心肾之阴不足，虚阳有升少降，诸恙因之蜂焦，拟以清养。至滋腻峻补，霉令不甚相宜，是否即候政行。", "17776": "（案2）俞，左，十五。少年以精血为宝，早有遗泄，又为吐血，精血两伤，以致虚损之象。病情纷沓，头痛发眩，耳聋面麻。关系者，龙雷不熄，阳刚发动，即为不固，咳嗽亦然。惟虚证而见实脉，若亢阳不潜，真阴何以得复？拟以清养，并调胃纳。", "17777": "（案1）顾，左。肾为作强之官，心为济之，肝为辅之，始得举而能坚，坚而能久，全仗关门之固。脉见细弦，拟固摄为要，补阳助火之药皆在禁例。", "17778": "（案1）高，右，五十八。气痹液枯，大便燥结，四、五、十日一行。脉见细弦，痛势上行后腰前腹，治以和养。", "17779": "（案2）右。营阴素亏，亏则生热，大肠为津液之腑，遂为燥结难行，每每五六日一解，解时脱而外翻，脉息细滑。怀麟佐脾胃司胎，拟以清降。", "17780": "（案3）右。禀体阴亏，郁火蒸痰，痰扰于肺，肺失清肃，咳呛绵延；火迫于肠，肠失通润，更衣艰涩。肺与肠本为表里，以致上下见证相因而发。脉见弦滑，拟以清降。", "17781": "（案4）汪，右。温邪先受，发于产后。当时寒热厥逆，疹疮俱发，现在脘嘈频仍，心悸怕繁，更衣四五日一行，素体血热多痰。脉见细弦，治以清养。", "17782": "（案1）潘，右，十八。产虚不复，咳嗽屡发，脬坠溺数。早有便血，脉见细涩，肢腰酸楚，经来腹痛。治以和养。", "17783": "（案1）徐，左，三十四。触毒起因，先发袖口疳，每溺作痛。现在左胯肿痛，将成鱼口，脉见滑大。疮兼病发，身热焦灼，口渴便闭，拟以通降。", "17784": "（案1）顾，左。毒疮阴分受伤，余热未清，煽烁肝肾，目为肝窍，耳为肾窍，以致两耳发鸣，左甚于右，两目发赤，左及于右。脉见数大，拟以清化。", "17785": "（案2）王，左。杨梅风逢骱酸痛，屈伸不利，脉见细数。治以清养。", "17786": "（案1）王，左，十五。禀体内热，挟风郁湿，清窍蒙蔽，右耳失聪，有时流脓，有时痛胀。脉见弦滑，拟以疏和。", "17787": "（案2）何，左，廿一。风邪挟湿，两耳为聋。脉见沉弦，治以和养。", "17788": "（案4）朱，左，三十八。头蒙渐减，耳仍鸣响，脉见弦滑，治以清养。", "17789": "（案5）王，左，三十四。下疳受伤，肝肾之阴不足，耳为肾窍，肝阳上扰，头部鸣响，两耳渐为失聪。脉见弦滑，治以清养。", "17790": "（案6）朱，右，四十七。头痛多年，渐致耳鸣目花，颈项牵引。木旺者必侮土，有时脘痛纳呆。脉见沉弦，治以和降。", "17791": "（案1）周，右。五聤者，脓分五色，总名谓之耳聤。现在并无血出，青脓、白脓交溢，脑髓受伤，肝阳为炽，渐至颊车，闭而难开，颈项头目皆牵引为痛，清空之虚难于著枕，脉见细弦。体本丰腴，内痰与内风有升少降，拟以镇养。", "17792": "（案2）周，右。耳聤溢血，血止又复溢脓，脓薄如水，或多或少，以致清空受伤，头部鸣响，两额作痛，牵连诸虚，喉痹哽痛，脘闷纳少，有时腹痛，有时便溏。脉见弦滑，治以和养。", "17793": "（案1）孙，左。耳菌溃烂，脓血交溢，久防失聪，脉见细弦。治以清化。", "17794": "（案2）左。目属肝窍，眼眶上下发红，属脾湿肝风所致。脉象细弦，治以清泄。", "17795": "（案3）左。头痛未止，目仍蒙赤，脉见细滑。拟从熄养。", "17796": "（案2）赵，左。咬牙疳满口腐烂，两腮痛胀，脉见浮滑。温毒客于上焦，治以清泄。", "17797": "（案1）左。腿部青色，退而未尽。现在牙疳腐烂或轻或重，总未平复。脉见数滑，舌滑腻，拟清阴而化湿热。", "17798": "复：痰色屡破屡结，血水或裹痰涎，心脾部位无非郁热蒸痰。脉息细弦，治以和养。", "17799": "（案1）高，左，十八。禀体虚热，牙宣溢血，旋平旋覆，寒热头疼，有感即来。脉见细弦，拟以疏和。", "17800": "（案2）右。营阴不足，气火有余，心肝两经燔灼，阳明郁热，牙宣半年，诸虚杂出，脘胀发嘈，头蒙艰寐，脉见细弦。急宜调理牙宣，以冀血减，则诸病皆除。", "17801": "（案3）宋，右，二十。牙宣连年，阳明郁热，肝风为之上扰，头发眩晕，脘闷心悸。脉见细弦，治以清养。", "17802": "（案1）右。阳络受伤，鼻衄狂溢。薄而有红者，属热为多。脉见细弦，治以清降。", "17803": "（案2）左。阳络受伤，鼻衄倾注，甚至痰中亦带，脉见细弦，不加咳嗽，总可调复。", "17804": "（案3）赵，左。鼻衄狂溢，营伤气痹，两胁作胀，当脘发迸。脉见沉弦，拟以和养。", "17805": "（案2）高，右。鼻疳复发，并溢清水，鼻骨酸麻。考鼻为肺窍，由于肝邪烁肺，肺失清肃。脉见细弦，拟肝肺两调。", "17806": "复：鼻渊稍减，咳嗽有痰，头蒙腰楚，脉见细弦。治以清降。", "17807": "（案1）张，左。喉闭较通，蒂丁未曾收敛，肝肺不和。脉见细弦，郁热尚未清楚，汗出津津，拟从和养。", "17808": "（案2）左。将成喉痹，咽哽音嘶，脉见弦滑。治以和养。", "17809": "（案3）夏，左，二十九。疙瘩红肿，肺肾阴伤，郁热挟痰，为之上下不摄，甚至溺多色黄，夜寐不宁，龙雷之势有升少降，夏令与病不合，恐失血失音。脉见细弦，急宜调护。", "17810": "（案6）张，左，四十四。失血后咳，肺阴大伤。咽为外候，且哽且痛，渐成喉痹。脉见细弦，治以和养。", "17811": "（案2）左。嗜饮伤肺，痰热内阻，咽为之外候，痰扰为肿，热炽为哽，将成喉痹。脉息弦滑，拟以清化。", "17812": "（案3）杨，左。治咽红发哽，脉息浮弦。", "17813": "（案4）王，左。咳嗽绵延，咽哽发呕，音嘶痰少，脉见细弦。阴伤气痹，治以和养。", "17814": "（案5）沈，左。咳嗽失音，虚而非实，属金破不鸣，脉见细弦。肺肾两为失司，音之根、声之户受伤非浅，拟以和降。", "17815": "（案1）俞，左，五十四。风痰互扰，肢骱抽搐，面麻舌强，甚则神迷跌仆，属五痫之一。脉弦且滑，治以熄化。", "17816": "复：痫厥有根，不发时舌亦为强，肢麻头，脉见弦滑。再从熄风化痰。", "17817": "（案2）徐，左，十。痫厥有根，发时神迷手痉，目瞪口呆，喉似曳锯，脉来弦滑。当熄风化痰，以冀除根。", "17818": "（案3）王，左，十八。猪痫屡发，喉鸣痰响，项斜肢痉，脉见细弦，从中惊痰入络。急拟开降。", "17819": "（案1）徐，左。癫痫复发，仍言语喃喃，有时默默，彻夜不寐，脉见细弦。属痰热内蒙，机关失利，治以镇养。", "17820": "复：界乎癫痫之间，有根屡发，发则神迷喉鸣，言语反常，属痰邪蒙蔽机关，脉弦滑。拟镇养，先冀艰寐得和。", "17821": "（案1）郑，左，十四。痫厥不平，轻发神志模糊，重发手足颤动，一日数十次，甚至身热胃呆。脉息弦细，治以镇养。", "17822": "（案1）金，左，四十二。阳并于阴为癫。癫象有根，每发神呆目瞪，当脘懊𢙐，言语亦为错落。脉见弦滑，拟以开降。", "17823": "（案3）范，左。癫厥屡发，口吐白沫，手痉目瞪，痰邪入络，心阴不足，肝火有余，脉见弦数。拟以清降。", "17824": "（案3）范，左，五岁。寒湿互扰，幼年谓之河白，又名肿胀。脉见细弦，治以疏导。", "17825": "（案1）孙，左，廿七。黄疸渐成，形黄脘闷，脉见细弦。治以疏和。", "17826": "（案1）左。自汗盗汗久而未止，脉见细弦。治以固养。", "17827": "（案1）徐，右，廿六。屡屡内热，咳呛频仍，热复蒸痰，痰流于络，颈项左右皆有结核，脉见细数。治以清养。", "17828": "（案2）左。禀体阴虚，郁热蒸痰，阻于络脉，项筋牵引，结核虽小，久而成疬，脉见细弦。治以清养。", "17829": "（案3）右。久有结核，发于耳后，属少阳部位，阳亢火化，煅凝成痰，痰流于络，以致溃久不敛，屡屡抽搐。外疡由内因而发，诸恙因之蜂集，有时头痛，有时耳鸣，面为之赤，目为之花，脉见弦滑。拟以清化。", "17830": "（案5）右。经事久为不调，后期而少，营虚生热，热复蒸痰，阻于少阳部分，耳后结核渐形胀大，防成十八疬之一，脉见沉弦。拟以和养。", "17831": "（案6）左。马刀现将穿溃，余者皆欲成未成。体虚挟热，热则生痰，流于络脉，坚红而痛，拟以宣化。", "17832": "（案1）右。饮一溲二，上渴下消，从此肉落肌灼，脉数舌红。治以清养。", "17833": "复：消渴绵延，饮水无度，溺亦无度，脉数。拟清上以和阴，摄下以固窍。", "17834": "（案2）左。饮一溲二，渐成消渴，脉象濡细。治以和养。", "17835": "（案3）朱，左，廿五。饮一溲二，将成消渴，脉右细左弦。治以和养。", "17836": "（案1）全，左。肺脾受毒，棉花疮生生化化，遍体皆到，脉见细弦。肾囊发胀，淋浊虽止，近发寒热，郁邪上攻下注，有不得了之势。", "17837": "（案1）张，左，六十三。流火红肿，溢脓未透，形寒，脉细。治以疏托。", "17838": "（案2）叶，右，三十三。流火坚肿，脉见沉弦，恐其发头穿溃。", "17839": "（案2）陆，左，三十一。骑梁发背，红晕四散，中腐色青，属半阴半阳。脉见细弦，险重之至。", "17840": "（案1）左。流注三处，曲池已溃，腋下臂上亦欲蒸脓，脉见细弦。治以宣化。", "17841": "（案2）褚，左。流注溃处不一，现在两眼未收。疮由虚发，营液从此受伤，两足软弱，络脉拘挛。脉见弦滑，治以和养。", "17842": "（案3）左。痰注不一，眼细中空，久而不敛，渐至营卫受伤，营争为寒，卫争为热，寒热频仍，防成疮劳。脉见弦滑，治以和养。", "17843": "（案4）右。产后新血已伤，旧瘀入络，左腹旁结块有形，防成败瘀流注。脉左细右弦，治以疏和。", "17844": "（案1）陈，右，十六。右肩流痰，身热纳微，防天热难支。脉见细弦，治以宣化。", "17845": "（案2）左。流痰发于臂部，高肿色变，势难消退。脉见弦滑，治以疏和。", "17846": "（案4）左。环跳流痰高肿之势，渐滋暗长，久防蒸脓穿溃。脉见细弦，治以疏化。", "17847": "（案6）沈，右，二十九。身热脘闷，环跳肿痛，防成流痰。脉见沉弦。治以疏降。", "17848": "（案7）左。膻中流痰，久溃未收，中孔甚大，渐至本元更伤。连次失血，又为咳嗽，脉见细涩。阴伤气痹，内外证皆属损象，早宜护持。", "17849": "（案2）张，右，三十八。股阴毒溃脓孔深，筋络先伤，半身抽搐疼痛。因疮成病，气逆汗多，心悸神疲，纳微发呕，大便失行。脉见濡细，势防痉变。", "17850": "（案3）李，右，三十四。股阴高肿，将成流痰，脉见弦细。治以疏和。", "17851": "复：膝眼痈流脓不止，因疮发病，脉数将劳。", "17852": "（案1）右。乳痈蒸脓，色红兼肿，脉浮舌白，并有表症，微寒微热。治以疏和。", "17853": "（案1）左。肾囊肿痛，疝气起因，将变子痈，形寒形热，蒸脓之势。脉息沉弦，治以疏和。", "17854": "（案1）张，左，三十九。脏毒绵延，内缩不见，脉象浮弦。治以和养。", "17855": "（案1）右。肝气充斥，挟痰入络为乳癖，挟饮扰中为吐沫，脉见细弦。治以和养。", "17856": "（案3）叶，右，三十四。乳癖起因，癖久不消，渐为胀大，肌肤板滞，按之坚结，属由癖成岩之势，若抽搐作痛，痛而色红，即能穿溃，溃后有血无脓，尤为可虑。考厥阴、阳明之脉皆绕于乳，虽属外疡，由内因而发，血不养肝，肝邪犯胃，当脘久有胀满，屡屡头眩火升，脉息弦大。拟以和化。", "17857": "复：乳癖潜滋暗长，坚结不解，已成岩象，有时抽痛，有时色红。近复上为咯血，下为便闭。营阴久亏，痰热互扰，触感新邪，又有微寒微热，热势复甚，神烦心悸，脘胀纳呆，头眩火升，诸恙从此交集，脉息弦大。再从调气清阴，化痰热而和内外。", "17858": "又复：乳岩散漫，内胀外肿，四旁红晕又添。厥阴充斥，阳明内络大伤，以致纳食呆钝，食后作胀，肢体浮肿，心悸艰寐。种种营虚气痹，恐孔囊结盖之处溢脓为出血，脉见细弦，舌糙。从中挟痰郁湿，与肝邪为之互扰，拟清营和络。", "17859": "（案1）柯，左。肠痈将成，少腹肿痛，大便不行。脉见沉弦，治以通降。", "17860": "（案2）陆，右。脐肠痈脐凸红肿，腹膨作痛，大便已通，能否不为外溃。脉数内热，治以清降。", "17861": "（案4）张，右，三十一。缩脚肠痈，小产后仍未减，肢骱酸痛，脉见细弦。治以分疏。", "17862": "（案1）沙，右，廿四。月事过期四月，脉见细滑，怀麟之兆。惟阳明营事初停，脘宇懊𢙐，纳谷渐减，腹疼腰楚。皆属胎元不足，治以和养。", "17863": "（案1）王。便血之后，结痞内攻，脐上四旁常常跳动，甚至小便不利，脘腹坚结。奔豚症肾气有伤，牵连肝肺。脉见弦细，治以温通。", "17864": "（案1）左。健忘之证，西医谓之脑气筋，中医谓之心血受亏。现在遇事善忘，由昔年痢下之虚。脉见弦滑，治以和养。", "17865": "（案1）左。心阴不足，肝阳有余，两耳发鸣，头蒙肢麻，多梦少寐，心悸肉𥆧，证属怔忡。脉偏弦细，右滑。从中积痰蓄饮，拟以镇养。", "17866": "（案2）右。病后心气心阴两为受伤，心悸艰寐，多思多虑，怔忡之象。脉息弦细，镇养清养。", "17867": "（案3）左。彻夜不寐，将成怔忡，属操劳过度，肝阳内扰，以致神不守舍，痰热内蒙。脉见细弦，拟以镇养。", "17868": "（案4）邱，左，五十一。遗泄目前不发，封藏早亏，遂致诸虚杂出。肝藏魂，又主风，心藏神，又主血。诸窍出风，畏光怕亮，胸脘之间气攻无度，脉沉弦。拟驯龙雷而静肝阳。", "17869": "（案1）刘，左，十二。脘腹作痛，甚于脐眼，扰上为呕，下便如脓，防成内痈之势。幼年食积为多，常常痛者为滞，作阵痛者为虫。脉息细弦，治以疏和。", "17870": "（案2）右。漏经三月，腰酸腹痛，心跳头蒙，种种营亏气痹。脉见沉弦，治以和补。", "17871": "（案3）梅，右。奇经不摄，崩放后又为经漏，应月淋漓。营阴大伤，诸虚杂出，头眩耳鸣，心悸腰楚。脉见弦滑，治以和养。", "17872": "（案4）高，右。老年崩放，绵延未止，脉息濡细。冲海不摄，气营两亏，肢腰酸楚。治以和养。", "17873": "复：崩放减而未止，向有失血，老年营阴不摄，内络已损。脉见芤细，炎夏急宜调和。", "17874": "（案5）右。操劳过度，有伤奇经，经漏三月，绵延不止，以致统藏不摄，血海愈涸。脉见细弦，当温养八脉，兼补气血，栽培火土，以固其根本，涵养乙癸，以充其渊源，俾得天癸有恒，阴顺阳和为法。", "17875": "（案1）右。常常气怯神倦，属中气受伤，失于砥柱，遂致肝阳内扰，头眩耳鸣，月事反为趱前。女科以肝为先天，皆以营阴失养，气无以摄。脉见濡细，舌腻，拟轻重调补。", "17876": "（案2）王，右。月事早而且多，每每零落不止，且带下淋漓，奇经久为不摄，以致头眩耳鸣。脉见细弦，左关尺俱涩，拟以和养。", "17877": "（案3）窦，右。当脘作痛，头眩腰楚，脉息细弦。治以疏和，兼调月事腹痛。", "17878": "（案4）杨，右。营亏气痹，奇经失职，月事不调，衍后为多，且少色泽。营失养肝，肝气转为充斥，侮中则腹部攻痛，入络则两乳发胀，甚至晨起为之发呕。脉见细弦，拟以调养。", "17879": "杨，复：月事衍后，渐得准期，惟逢月之前，或为腹胀，或为腰楚。脉见弦滑，营亏气痹，再从和养。", "17880": "（案6）刘，右。经事向来后期，忽又先期，总由冲任不摄，未能生育。脉见细弦，治以和养。", "17881": "（案7）右。气痹营滞，腹部胀满，经事五月未行。脉见弦滑，治以和养。", "17882": "（案8）右。经事不调，或一二月一行，或四五月一行，营滞由于气痹，脘胀腰楚，形黄肢肿。脉息濡细，治以疏和。", "17883": "（案9）王，右，三十八。肌灼腹满，经事七月未行。脉见弦数，拟以疏和。", "17884": "九月二十六日，诊得脉来如弦，灼热无汗，午后尤甚，面上浮肿，色青黄，鼻黑暗，口苦而渴，时作咳嗽，痰色青白，有沫如珠，口内流涎，舌苔滑腻，前半色白，后半灰黑，唇口焦裂，神气昏沉，日夜寤而不寐。是内伏秋燥之气，外受冷露之寒，病延两旬，燥气化热，表里未能通达，邪气深入，灼热日多，阴液所存无几，渐至内陷，证属险危，非喻氏逆流挽舟法，恐难奏效，以四逆散合增液汤加减，若能得汗，方是佳兆。", "17885": "初二日，真武汤连服两剂，兼以猪胆蜂蜜导入谷道，夜半下燥粪甚多，脉静身凉，稀粥稍进，口中流涎作苦，灰黑之苔，已转白腻而滑矣，面上浮肿，喉痒咳嗽，痰吐不出，色青如胶，白沫如珠，尚未松动，内伏秋燥之气已化，外受冷露之寒未宣，遏塞肺窍。若不早除，愈后恐成痰饮，致有咳嗽气喘之疾。惟小青龙汤，能直入病所，适达肺窍，非此方不为功。", "17886": "初七日，两手关脉见弦，阴阳不和，夜半大便，易于受凉。时将未初，骤然寒热两时，汗出直至足底，被褥皆湿，夜半又下软粪一次。窃思病后汗多，恐阳气衰微，拟参附汤以扶阳固气。予谓治病难，而养病亦不易也。", "17887": "初八日，连日寅刻大便，起坐床上，天尚未明，而寒气更甚，又泄泻三次，体虚之人，焉能不受寒凉。随看两手关脉，弦而有力，是虚疟来派。幸而寒热时候不大，只胸腹时觉膨胀，小便混浊黄色。以补中益气汤，升清降浊，待疟疾转正，再议。", "17888": "初九日，脉弦不平，阴阳未调，已转间日疟疾，先寒后热，约两时许，热退汗收，被褥全行汗湿，而手指冰冷，特恐汗多亡阳。幸喜泄泻已止，寒渐化热，日夜食稀粥汤数次。惜无人参调补，只好重用党参以代之，兼固阳气，庶将来病愈后，真元易于充复，参附汤主之。", "17889": "十一月十五日，予切脉，幼得《太素》之传，仲侯品格清高，容止谦顺，将来福泽，未可限量。惟大病甫痊，精气未复，务当慎风寒，节饮食，则天地六淫之气，自然不侵于内。予自十月二十八日，由凤回邗，仲侯半月以来，连下宿粪大小百余枚，惟日间多坐，夜间两足微肿，虚汗频有，大便间或有血。是水寒土湿木郁风动之故，当补火燥土，暖血温肝，即痔血亦以此法通之。", "17890": "辛巳夏四月中浣，武少尉巨川，方驾部伯融来寓，出方子严观察专信见示，始知观察喆嗣揖赵患证，属余医治。余恐才识不逮，托其善为我辞。是晚二次信至，词意谆切，实难再却，当料理行装，次早乘舆赴八宝。即夕至高邮，舆人困乏，遂易舟乘顺风夜行，十九日午初，抵观察寓，诊视揖赵之病。热将内陷，危险之至。先进紫雪丹驱其热，继以犀角地黄汤救其阴，周身汗出，其热解去。于是专用育阴法，舌苔回津。又用导法，燥粪两下，胃开神静，惟右手经络为湿邪所窜，致软弱不便。本古贤治痿弱独取阳明法，始获转运自如。旁观谓余是岐黄神手，余曰：命也，非人力所至。既承观察信任，自不能不竭尽心力，用副见委。兹将所开脉案药方，钞录一帙，冀同道君子正之。并书数语，以志颠末。", "17891": "二十日，昨诊两寸关脉如弦，舌短硬，其苔干黑，边底光红如镜，唇破，口臭牙紧，言语不清，头热，而手足心胸腹按之尤觉火灼，睡觉不沉，神气昏滞。肠胃津液，皆为邪热耗顿，以致肌肤如鳞。病已十三日曾未出汗，邪气从何而走。当进紫雪丹犀角地黄汤，夜间甫得浑身微汗，仅至大腿，脉自稍平，肌肤渐通，舌尖光红转淡，但津液未回。所饮汤水，皆要热服，经所谓内热极则外自生寒也。前方加重，添生白芍、麦冬。", "17892": "二十三日，昨进育阴重剂，始能脉静身和，眠安便浊，惟燥粪凝结腹中，舌条仍然干燥。自十九日起，二十三日止，津液尚未得回，可见水为火涸，今日始见瘦容。仿增液汤，加以淡渗之品，引热邪从小肠而出，非此不为功也。", "17893": "二十四日，昨进增液汤，佐以淡渗，小便昼清夜浊，舌条中间干燥，红色花开，边底皆有潮润之意，右手筋脉软痿，不能运动，似乎作酸。是邪化火逼入经络。仍宗前法，方能内液充复，则舌上自然生津矣。", "17894": "初八日，八珍加黄耆，服后胃气已苏，稠粥加倍，右手骨节，捏之知痛，肩臂手指均觉酸麻。经云：四肢为诸阳之本。邪气客于经络之中，阳气内衰，不能荣养筋脉，若不及早治，则日久必延蔓为患，为虺勿摧为蛇。将若何，宗前方，双固气血，加附子以通其阳，桑枝以引入手臂。", "17895": "十二日，三十、初六两日，燥粪下尽，进八珍汤，双补气血，右手掌指，稍能伸缩。细思初病头疼背板，病从太阳而入，太阳本属寒水之经，行身之背，闻问日久，始悉前因病重热甚，用烧酒湿纸贴胸，意在拔出火邪，讵知火未引出，而邪气已窜入太阳经络。是夜右手脉息，忽伏两三刻方起，因此软弱也。当于初八、初九两日，加附子共一分五厘，服后热甚，似乎经络中之邪，为附子冲动。十一日又进小柴胡汤，以枢转其邪，从太阳外达，汗出一身，其热解去。八珍加附子，小柴胡汤，相为掎角，夺门革鼎，各有专功，胆怯焉能建补天浴日之功。仍宗前法，减轻柴胡，和解表里为法。", "17896": "十三日，诊得脉息平静，虚热退清，身常带汗，胃气日健，小便清利，是脏腑之病均无矣。惟右手不能悬起，其病全在经络，专以扶正化湿治之。", "17897": "十五日，脉静神安，仿古贤独取阳明法，以治右手。", "17898": "十九日，自初六日大便后，已十有三日矣，脉来弦紧，燥粪塞于肛门，今日又用导法，下宿粪二三十团，尚有宿粪，杜于谷道，缘正气未充，不能送出，仿保元汤当归补血汤。", "17899": "二十一日，昨下宿粪时，头汗如珠，皆因病久正气未充，一派虚弱之象，幸而眠食安宁。今诊两关脉见涩，病粪虽有，亦属无几矣。仿八珍汤去川芎、茯苓，加黄耆固表，苏子降气润肠，桑寄生引入手经络。", "17900": "初四日，大便如条，下来不少，脏腑无病，可以弗药，饮食以五味调和，气血自然充复，背脊肩臂，亦可因之自如矣。是日始能吃干饭，床上靠坐。初六日，移坐椅上。初十日，能自立起，举步尚须人扶。十二日，步履自如，起坐亦便。是病由三月二十四日出诊起，至六月初四日止，计六十九日，余于四月十九日按治至是，四十四日也。四十四日之中，病变各殊，方亦层易，是时始占勿药，可谓世疾矣。斯曰：固由观察任人不疑，余始得竭尽心力。然余于观察居久，见其事亲孝，得人厚，其庭训家法，皆可楷模当世。后嗣蕃昌，理所固有，揖赵世兄，天姿早荦，历金门，上玉堂，指顾间事耳，疾虽重，乌足心困之，余所以任之而不辞者也。至谓用方选药，皆能中病，此观察之谬赏，非余所敢承也。因汇集脉案药方，乞方君长孺书之，爰跋数语归之揖赵，以为他日之左券焉。登阶又记。", "17901": "方大人喆嗣仲侯，同予讲究医术之友也，其令正患乳射。舟广陵，就正于予，知其所患是干奶乳栗乳节之类也。肩舆至舟，见其右乳坚硬，如石重坠，乳头缩入，七处溃出黄水，疮口翻出，头昏眼赤羞明，舌灰焦厚，业已昏晕，按乳有十二穰，今已窜七穰，如再迟延，全行窜破，势必翻花，成为乳岩，扁鹊复生，亦难挽回。予遂进疏肝解郁重剂，乳头伸出，疮口肉平，头目清爽。又夹进膏丸，坚硬消软，而遍身透出鲜红脓窠疮，幸矣哉。予独不解一乳核，何以转到如此之险，而旬余竟能收功，实力始念所不及，此皆仰赖大人洪福，故能得心应手。因思有谓予治病价大者，不知世俗不晓医之贤愚，病之轻重，此予之所以活而不活也。病固是大手笔，然士为知己者用，重以相知之诚，仅取药资，够敷药品，管仲无鲍叔，其名不彰，知己知后可耳。夫看病全在识证，不求对证用药，但拘执偏僻，鲜有不成大患者。予年逾古稀，阅历虽多，究于岐黄之术，尚克克焉而不敢自信。总之，生死定数，大病能愈，亦是定数。予非能生死人也，此自当生者，予能使之起耳。吴淮安曰：人不死于病，而死于医。诚为痛快语，予深慕之。聊记数语，并附脉案药方于后，留为仲侯阅看云尔。丙戌二月上潮，濑江沈青芝识。吴子圣教服阳和汤二十余剂以致如此。", "17902": "丁亥八月初二日，万秋圃分转，招余为令媳大少奶奶看病。问及病形，原于七月二十日，生一女孩，上床即血晕数刻方省，朝朝请医诊治，愈治愈剧，将近十日。于二十九日，忽然昏倒不省，诸明公束手无策，坐任其败而已。延至初二日下午，已有三日，身后之衣穿好，鼻无呼吸，挺直僵卧，惟腹大而高，上半身温和，下半截冰冷，脉息未绝，诊之并无七恶形状。大凡产后肚腹当小而软，不应不而高。忆经云：产后血已尽倾，心无血养，血舍空虚，止存微气，所剩残血，非正血，不可归经，而离经之血，既不能归经，又不下行，必至上攻心胸，因有此变。思维至再，遂用黑龙丹，去瘀生新，继以华佗再生丹，大豆酒徐徐灌下。夜半恶露大行，至初三日，手能动，眼能开，似乎有转机矣。然此证病情已极，百难愈一，得以如法奏效者，只求对证用药，尚无错误。此亦大少奶奶之鸿福，鄙人岂能挽回天哉，所谓药用当而通神也。转危而安，借以仰副分转谆嘱之意，不负委托而已。", "17903": "八月初二日清晨，万竹轩兄来寓云：侄媳大少奶奶，于七月二十日生一女孩，至二十九日忽然昏厥，目闭，牙关紧急，鼻无声息，惟心胸气动，腹大，从大腿至脚，若冰，上身及两手，尚温。余询其病状，与黑龙丹一粒，嘱其速回灌下，看其动静。至午后又来招余往诊，偻指厥已三日，殓衣皆著，僵卧不动，待死而已。细问灌下黑龙丹之后，有瘀血大行，幸天转新凉，两手脉无七恶状，或者可救。速用华佗再生丹，大豆紫酒循序灌下，至夜半，恶露大行，两手微动，腹大渐平，但声息未出耳。", "17904": "初四日，大早往诊，手足活动，能出舌尖看苔，尚未能言，近午始能语，声微无力。遂易方用独活一味，大豆酒和童便服之。近晚来字云：病人口渴要吃茶。又云：浑身发烧，摸其皮肤，似乎有热，头上身上有汗，病人云：虽汗不嫌暖。窃思酒系发暖之物，故未敢与服等语，余曰：惜哉，未厥之前，服药何其胆大如天，今既苏醒，何以胆小如豆。殊不知独活去风，黑豆酒消血结，且有童便滋阴降火，如若早服，可以立见阴阳经脉流通。经云：药到病除，一汗而愈，此之谓也。余恐产后致病，遇天时阴雨，难免浑身有困痛之病，病及时怕用，良可惜也。", "17905": "初五日，脉象稍敛而不浮散，舌苔白腻，舌中至根灰黑，口渴舌潮不干，身汗不离，两脚和暖潮润，声音微细，精神疲困，面上时有虚火上炎，夜睡不沉，的是产后气血双亏本证。谚云：药医不死病。其信然欤。", "17906": "丁亥八月中旬，方果卿明府如夫人，由如皋雇舟来扬诊视。询及病情，是五月间，咽喉肿痛而起，月余，自觉在乳下虚里，其脉贯鬲上络于肺，其气上塞喉管，嗌中干燥，或痒或痛，时要吐痰一口，喉中稍爽，渐添肉𥆧筋惕，睡中惊掣，则心中筑筑然摇动，而不得安静，似乎浑身百病皆作矣。细看咽喉左右傍两条起肿，结久成核，其气上窒，则咽塞，气下则咽通，似乎是梅核气，人亦疑是梅核气。但咽门内，上下红丝缠绕，中起颗粒，垒若虾蟆皮，中关将近下关，如浮萍略高而厚，或有如茅草，常刺喉中，又如硬物，隘于咽下，直至下关肺管，看之不见，咽中干燥，或痛或痒，其气时通时塞。遍查古书，梅核气，吐之不出，咽之不下，咽门内无颗粒红丝形状，且病者咽中，自觉有气如珠，直贯心下作痛，亦与梅核气殊。《内经》云：少阴少阳，君相二火，其脉皆经络于喉，手少阴心脉挟咽，足少阴肾脉循喉咙，一阴一阳结，则痰气凝滞于喉间，皆因思虑过度，中气不足，肺气不能中护，虚火易于上炎，致有此患，难治之证也。仿金燥不能生水为法，煎药、膏滋药、丸药、吹药并用，以观动静。", "17907": "八月十六日，病因抑郁不遂，佗傺无聊而成，精神恍惚，言语错乱，夜不能寐，或笑或怒，或耳闻人语，目中时见鬼神，脉见乍大乍小，大有狂意，而狂甚则不避亲疏矣。仿猪心血丸。", "17908": "初五日，诊左手脉软而细，右手脉洪而弦，二便通畅，中脘时闷时宽，神气乍明乍暗，口㖞舌歪，口流涎，鼻孔干燥。经云：中府者多著四肢，中藏者多滞九窍。前用转舌膏，胆蜜导大便通，继以柔润息风化痰法，鼻孔潮润有涕，胸中神气渐清。年高之人，涸荣耗卫之药，似乎不可用也，膏方内加沙参、葛根，煎方无庸更改。若要日日换方，治病无此法也。", "17909": "二十五日，诊两手脉渐和，惟左手稍大而弦，精神日渐健旺。但舌红犹未起苔，心经之郁热未化也。仿加味转舌膏。", "17910": "廖兄和轩，粤东人，余之十余年友也。突于戊子五月二十九日来寓云：老太太七旬有四，五月二十二日，忽觉项间不舒，夜半遂中风不语，延至二十九日，易医数人，服药无效。问及病情，中脘昏闷，神气不清，口眼㖞斜，口中流涎，大便不通。余思易曰：风自火出。谚云：热极生风。乃知类中风，无有不由心腹中风热两作也。仿用吐法导法及下法，转舌膏等法。至六月初七日，始能出声，神气渐清，仍用柔润息风化痰之法，加减熬膏，日日服之。至二十三日，渐能言语，至十多句，四音亦分，而其舌伸出尚斜未正，舌红无苔。是心络中热炽，无形之火，以灼有形之痰，故舌红而无苔也。观河间内火召风之论，用苦泄辛降，吐之下之。余仿其法，易以柔润甘寒，折其上腾之威，使诸窍清空，浊痰不能蒙蔽。此宗经旨，风淫于内，治以甘寒法也。但年高之人，得此大证，尤属难治。余因和翁孺慕之诚，形于颜色，知侍母至孝，孝且可格天，余敢畏其难而不任其责耶。故尽心推求病源，竭力省察病理，所用之药，似皆平淡无奇，而竟能对证暗中，定有神佑，殆亦孝感所致也。余第不负孝子之诚，敢谓药之窃能应手哉，今将脉案方药录记，并书数语，以志颠末。", "17911": "二月初四日，前月二十四日服青州白丸子共十天，其为平安。近复检阅各家议论，痛痹之证，以臂痛不举，叙于半身不遂之下，谓风从上入，臂先受之。世俗谓，大指麻者，三年后定然中风，抑知风善行而数变。有热风寒风之别，风之中人，必从营卫而入，因人之藏府虚实寒热而变证也。《内经》云：脉微而数。微者指阳之微，数者指风之炽也。所出诸脉，字字皆本阳虚而言。其人必血舍空虚，而气分热炽，风之繇来，匪伊朝夕也。经又言：不问其虚，安问其余，偏枯病阳盛阴不足者有之。历节证，阳气痹而不通者尤多。前刘李二公之论，有攻补之别。刘以人禀天赋，本无亏欠，因邪入搅乱其气而后成病，邪退则正气自安，故以攻邪为要。李以人之真气，营养百骸，周于性命，凡真气失调，少有所亏，则五邪六淫，乘间而入，正复则邪自却，故以补正为要。二公深得上古圣贤立方之奥妙，明理识证，著书各成名手，盖遵古人之规矩，对证用药，当补当攻，调治得宜，自然有效。予用攻冲之法，虽然侥幸获效，亦是二少奶奶之洪福也。现痹痛已愈，行走如常，而右手大拇指中二指之病，恐不易尽除，以后能于调养真气，销去病根，则大妙矣。余年届八旬，自问见识短浅，恐不能胜任，或再遍访高明治之，余之幸也。", "17912": "咯血胁痛，项下有核，脉数恶热，咽痛便溏。此肝火乘脾之证，反能食者，脾求助于食，而又不能胜之则痞耳。治在制肝益脾。", "17913": "肝脏失调，侵脾则腹痛，侮肺则干咳，病从内生，非外感客邪之比。是宜内和脏气，不当外夺卫气者也。但脉弱而数，形瘦色槁，上热下寒，根本已漓，恐难全愈。", "17914": "形盛脉充，两尺独虚，下体麻痹，火浮气急。此根本不固，枝叶虽盛，未足恃也。", "17915": "诒按：如此脉证，似可参用肾气法以温摄之。", "17916": "类中偏左，于法为逆，犹幸病势尚轻，可以缓图取效。原方补少通多，最为合理。惟是阳脉则缓，阴脉则急，所以指节能屈不能伸，此亦病之关键处，不可忽也。经云：肝苦急，宜食甘以缓之。于前方中增进阴药之甘润者一二，更为美备。", "17917": "脉虚而涩，左半手足麻痹，食不知味。此气血不能运行周体，乃类中之渐也。", "17918": "方书每以左瘫属血虚，右痪属气虚。据述频年已来，齿疼舌赤，常有精浊。纳谷如昔，卒然右偏，肢痿舌强，口㖞语謇，脉浮数动。此乃肝肾两虚，水不涵木，肝风暴动，神必昏迷。河间所谓肝肾气厥，舌喑不语，足痱无力之证。但肾属坎水，真阳内藏，宜温以摄纳，而肝藏相火内寄，又宜凉以清之。温肾之方，参入凉肝，是为复方之用。", "17919": "诒按：即古法而化裁之。参详脉证，斟酌尽善。", "17920": "脉濡，按之则弦，右肩及手指麻木，两腿酸痒，难以名状。此脾饮肝风，相合为病，乃类中之渐，不可不慎。", "17921": "脉虚而数，两膝先软后肿，不能屈伸。此湿热乘阴气之虚而下注，久则成鹤膝风矣。", "17922": "惊悸易泄，腰疼足软，有似虚象，而实因痰火。盖脉不弱数，形不枯瘁，未可遽与补也。", "17923": "肝风与痰饮相搏，内壅脏腑，外闭窍隧，以致不寐不饥，肢体麻痹。迄今经年，脉弱色悴，不攻则病不除，攻之则正益虚，最为棘手。", "17924": "久嗽脉不数，口不干，未必即成损证。此为肺饮，郁伏不达故也。", "17925": "体虚邪滞，肺络不清，脉弦而细，幸不数耳。", "17926": "肺病以中气健旺，能食便坚为佳。兹喘咳已久，而大便易溏，能食难运，殊非所宜。诊得脉象与前无异，但能节饮食，慎寒暖，犹可无虞。", "17927": "久嗽便溏，脉虚而数。脾肺俱病，培补中气为要。恐后泄不食，则瘦削日增也。", "17928": "脉细数促，是肝肾精血内耗，咳嗽必吐呕清涎浊沫。此冲脉气逆，自下及上，气不收纳，喘而汗出，根本先拔，药难奏功。医若见血为热，见嗽治肺，是速其凶矣。", "17929": "脉虚数，颧红声低，咳甚吐食。晡时热升，多烦躁。此肝肾阴亏，阳浮于上，精液变化痰沫。病已三年，是为内损，非消痰治嗽可愈。固摄下焦，必须绝欲。以饮食如故，经年可望其愈。", "17930": "脉微小，形寒，久嗽失音。是气馁阳损，议固胃阳，取甘温之属。", "17931": "用复脉甘润法。呛止音出，得益水濡润之力也。无如胃弱便溏，此药不宜再用。仿金匮麦门冬汤义，取养土之阴，以生肺金。", "17932": "久咳，便溏腹满。脾肺同病，已属难治。况脉数口干潮热，肝肾之阴，亦不足耶。", "17933": "脉寸关大而尺小，口干，上气不下，足冷不温。此阳气不潜。当用阴中阳药治之。", "17934": "脉数减，咳亦缓。但浮气不得全归根本。宜补益下焦。以为吸受之地。", "17935": "气喘足冷至膝，唇口干，鼻塞，脉虚小。下气上逆，病在根本。勿以结痰在项，而漫用清克也。", "17936": "吐血得劳与怒即发，脉小数微呛。病在肝心，得之思虑劳心，宜早图之，勿使延及肺家则吉。", "17937": "失血咳逆，心下痞满，暮则发厥，血色黯，大便黑，肝脉独大。此有瘀血，积留不去。勿治其气，宜和其血。", "17938": "脉寸静尺动，屡经失血，觉气从下焦上冲则呛，劳动则气促不舒。此病不在肺而在肾。治嗽无益，宜滋肾阴。", "17939": "心脉独大，口干易汗，善怒血逆。此心阴不足，心阳独亢。宜犀角地黄汤。", "17940": "劳伤失血，心下痛闷，不当作阴虚证治。但脉数咳嗽潮热，恐其渐入阴损一途耳。", "17941": "阴不足而阳有余，肝善逆而肺多郁。脉数气喘咳逆，见血胁痛。治宜滋降，更宜静养，不尔，恐其血逆不已也。", "17942": "再诊：热渐减，头中时痛，脉数不退，喉中痰滞不清。", "17943": "三诊：体虽不热，脉仍细数，宜养阴气。", "17944": "面黧形瘦，脉虚而数，咳嗽气促，腰膝无力，大便时溏。此先后天俱虚，虑其延成虚损。清润治肺之品，能戕中气，勿更投也。", "17945": "络脉空隙，气必游行作痛，最虑春末夏初，地中阳气上升，血随气溢，趁此绸缪，当填精益髓。盖阴虚咳嗽，是他脏累及于肺，若治以清凉，不独病不去而胃伤食减，立成虚损，难为力矣。", "17946": "汗出偏沮，脉来不柔，时自歇止。知肝阳有余，而胃阴不足，于是稠痰浊火，扰动于中，壅滞于外。目前虽尚安和，然古人治未病，不治已病。知者见微知著，须加意调摄为当。", "17947": "四诊：大便通，脉和。惟宜滋养。", "17948": "下既不通，势必上逆而为呕，所谓幽门之气，上冲吸门是也，治法自当疗下。但脉小目陷，中气大伤，宜先安中止呕。呕定再商。", "17949": "痛呕之余，脉当和缓，而反搏大，头运欲呕，胸满不食，神倦欲卧，虑其土𬯎木张，渐致痉厥。法当安胃清肝，亦古人先事预防之意。", "17950": "气郁痰凝，阻隔胃脘，食入则噎，脉涩，难治。", "17951": "诒按：旋覆代赭为噎膈正方。食入则噎，肺气先郁，故加郁、贝、枇杷叶，惟脉涩者正虚，可加人参。", "17952": "脉疾徐不常，食格不下。中气大衰，升降失度。", "17953": "中气叠伤，不能健运，朝食暮吐，完谷不腐。诊得脉虚色黑，腰脚少力，知不独胃病，肾亦病矣，此岂细故哉。", "17954": "肝阴素亏，温邪扰之，发为痉病，神昏骱齿，瘛疭不定。法当滋养肝阴，以荣筋脉，清涤痰热，以安神明者也。若能应手，尚可无虑。", "17955": "热伤津液，脉细口干，难治。", "17956": "诒按：此存阴泄热之正法，所云难治，想因脉细之故。", "17957": "舌干脉数，汗为热隔，虽发之亦不得，惟宜甘寒养液。虽不发汗，汗当自出，然必足温，而后热退乃吉。", "17958": "风温郁于肺胃，咳而胸满，痰多胁下痛，脉数口干。", "17959": "脉右大，舌黄不渴，呕吐黏痰，神躁语言不清，身热不解。此劳倦内伤，更感湿温之邪，须防变端。", "17960": "脐中时有湿液腥臭，按脉素大。此少阴有湿热也。六味能除间湿热，宜加减用之。", "17961": "面黑目黄，脉数而微，足寒至膝，皮肤爪甲不仁。其病深入少阴，而其邪则仍自酒湿得之及女劳也。", "17962": "诒按：寒袭于肾，而气上逆，故用温养。胀及腰背者，督阳不用也。鹿茸温通督脉，麝香开泄浊阴，故以之为君。", "17963": "脉弦小腹痛，食后胃脘痛，上至咽嗌。肝火乘胃。宜泄厥阴、和阳明。", "17964": "心腹痛，脉弦，色青，是肝病也。", "17965": "脉虚数，色白不泽，左胁有块杯大，大便小便自利。病在肝家，营血不和，此为虚中有实，补必兼通。", "17966": "大腹右有形为聚，脉大，食入即作胀，治在六腑。", "17967": "脉迟胃冷，腹胀，气攻胸胁，恶心少食泄泻。宜振脾胃之阳。", "17968": "脉微迟，左胁宿痞，腹渐胀大，便溏溺少。此是浊阴上攻，当与通阳。", "17969": "脉弦中满，病在肝脾。", "17970": "脉证合参，乃气结在上，津不运行，蒸变浊痰，由无形渐变有形。徐之才谓轻可去实，非胶固阴药所宜。", "17971": "头疼偏左，耳重听，目不明，脉寸大尺小。风火在上，姑为清解。", "17972": "脾肾寒湿下注，右膝肿痛，而色不赤，其脉当迟缓而小促，食少辄呕，中气之衰，亦已甚矣。此当以和养中气为要，肿痛姑置勿论。盖未有中气不复，而膝得愈者也。", "17973": "背脊为督脉所过之处，风冷乘之，脉不得通，则恶寒而痛。法宜通阳。", "17974": "脉数、耳鸣、吐痰，天柱与腰膝酸痛，两足常冷。病属阴亏阳升。法当填补实下。", "17975": "少阳之脉，循耳外，走耳中。是经有风火，则耳脓而鸣。治宜清散。", "17976": "形伟体丰，脉得小缓。凡阳气发泄Z之人，外似有余，内实不足，水谷之气，不得阳运，酿湿下注，而为浊病，已三四年矣。气坠宜升阳为法，非比少壮阴火自灼之病。", "17977": "恼怒伤中，湿热乘之，脾气不运，水谷并趋大肠，而为泄。腹中微疼，脉窒不和，治在中焦。", "17978": "又按：案中脉窒句，不甚明了。", "17979": "气郁不行，津枯不泽，饮食少大便难，形瘦脉涩。未可概与通下。宜以养液顺气之剂治之。", "17980": "下血后，大便燥闭不爽，继而自利，白滑胶黏，日数十行，形衰脉沉。必因久伏水谷之湿。府病宜通，以温下法。", "17981": "鼻痒心辣，大便下血，形瘦，脉小而数，已经数年。", "17982": "脉虚细数，阴不足也。鼠漏未愈，热在大肠。", "17983": "诒按：此肛门漏也。名为鼠漏，未知所本。脉证已属损象，故以滋补肝肾为主。", "17984": "胎前病子肿，产后四日即大泄，泄已一笑而厥，不省人事，及厥回神清，而左胁前后痛满，至今三月余矣。形瘦，脉虚，食少，少腹满，足肿，小便不利。此脾病传心，心不受邪，即传之于肝，肝受病而更传之于脾也。此为五脏相贼，与六腑食气水血成胀者不同。所以攻补递进，而绝无一效也。宜泄肝和脾法治之。", "17985": "（案1）女，产后弥月，形凛身热，津津汗出，脉细濡数，来去靡定，舌红渴饮。此因营阴内亏，冬令过暖，温邪袭匿于痰中，相交为患。治法和阳化温，清降痰气。", "17986": "女，寒热互作，有汗不止，渴饮舌绛，脉濡空软，痰吐不爽。产后阴分本亏，冬温挟痰内伏，营气不与卫气和谐，若再缠绵不已，恐致阴伤风动。拟和阳益阴化温除痰，阳旦、温胆、交加三方出入之所。", "17987": "女，寒热之势已缓，而仍漐漐有汗，体痛偏左，咳嗽，痰不易出，脉弦滑数。冬温兼挟痰气，阻痹肺之络。当理络化痰，宣通气机。", "17988": "荆芥炭楂炭谷芽陈皮炙甘草茯神（此方与脉案不合疑有错误）", "17989": "（案2）女，经居四月，脉象虚弱，内热食少，腰酸腹痛膨胀。营虚气滞。防其暴下虚波，拟和养肝脾气血。", "17990": "（案3）女，心悸，头鸣，咳呛，食少作胀，脉形细数。素体亏弱，气火上升。恐增寒热，且先清肺和胃。", "17991": "（案4）两脉濡数无力，脾阳久虚，聚湿生痰，胃气失和，足浮，痰多，纳少，无寐。疟后营卫失谐，元气益虚。拟和养脾胃，安神化痰。", "17992": "（案5）女，经居五十余日，奔走劳力，动络下血，一日颇多腰酸腹支急，饮食减少，脉形濡数。冲任营络损伤，防其腹痛暴下。拟和养健脾。", "17993": "（案6）女，失音半载，咽干口燥，经阻两月，脉形细数。阴伤肺热，恐入损途。", "17994": "（案7）咳嗽头胀皆减，耳鸣惊惕，中指发麻，痰多食少，脉虚细弦。血虚肝阳化风，静养慎调。", "17995": "（案8）女，血虚脾弱，经阻半载，腹痛便溏，耳鸣食少，脉形细涩。病颇深，损怯可虞也，理之不易。", "17996": "（案9）肝气挟痰上扰，头痛心悸，痰咳呕恶，腹痛食减，脉细弦数，舌黄口干。病久体虚，恐有痉象。", "17997": "（案10）湿热伤脾，便血泄泻，腹膨食减，舌白脉濡。恐增腹满之虚，拟清脾和湿。", "17998": "（案11）女，产后四十余日，下血如崩，营伤脾弱，遍体浮肿，舌白便溏，脉形濡细无力，气急鼻衄。阴阳两伤，防喘塞泄浊虚变。", "17999": "女，产后月余，下血如崩，营伤脾弱，肢体肿胀，气急便溏，咳呛舌白，脉形濡细。脾肺肾三焦皆病，防喘塞虚波，病机险重之症。", "18000": "女，产后去血过多，营伤脾弱，肢体浮肿，咳嗽气喘，食少便溏，舌白脉细。三焦皆病，喘塞可虞，不可忽视。", "18001": "（案13）女，七月妊躯，腿足肿胀，面浮溲少，脉形细濡，咳嗽头胀，舌白食少。脾虚湿胜，防骤产虚波。", "18002": "（案15）女，产未满月，瘀尽，白带颇多，少腹痛而腰酸，咳嗽食少，舌白脉细。营虚寒凝气阻，防其增重。", "18003": "（案17）女，自乳体虚，伏邪留恋，寒热间两日一发，左胁背部作痛，咳嗽食少，脉息小弦，最淹缠也。", "18004": "（案21）身热肢冷，去来无定，得微汗或止或不止，脉数左弦，舌苔白，神倦呓语，头疼体痛。邪兼太少两阳，若明日一候不解，恐其内陷。", "18005": "平旦更衣之后，寒热势缓，而脉未静，舌绛苔白，温邪挟湿，蒸中不化，病情尚未定著，且与和解化痰，以消息之。", "18006": "夜来先形寒，逾时而热，后热后得汗而解，脉弦数，邪伏少阳阳明，竟有疟状。柴胡温胆，未知可否。", "18007": "屡屡得汗，热已退解，但脉沉细数，舌绛，苔微黄，咳嗽，痰不易出，胸胁隐痛。且与理肺和胃化痰，以视明日动静。", "18008": "漐漐汗出，脉渐和平，此时只宜和胃养阴，使其神安加谷，宜《内经》法。", "18009": "多梦纷纭，神倦谵语，舌尖红，苔薄白，脉数空弦。谷食不加，此乃汗解之后，心阴内耗，肺胃热邪又留未尽。再拟养心安神，清痰热，和胃经法。", "18010": "寝食皆安，脉亦和平。扶正安神，一定成则。", "18011": "（案24）素体阴亏，烦劳阳伤，冬温乘袭，身热九日，咳呛气喘，自利烦渴，彻夜无寐，口不仁面垢，唇焦齿干，舌浊脉数濡。深恐正亏邪陷，当从肺胃清泄。", "18012": "（案25）妊娠八月，陡然昏厥，甚至上窍血溢，扬手掷足，发热神昏，咬牙脉乱。冬温挟痰，陷入厥阴，肝阳挟胎气上迫，势极危急，无从著手，不得已勉与暴厥应下之法，参入熄风化痰，以冀万一。", "18013": "女，又，损胎既下，仍然昏痉晕厥，手臂强直，脉弦滑数。此邪痰恶血，蒙闭心胞，正在险津也，谨防陡变。", "18014": "（案26）未老先衰，劳倦感温，身热八日，热退，面青肢冷，额汗津津，神倦呃忒，痰喘如锯，脉滑细如丝，舌浊而干。邪热匿于痰中，中气交脱之象。其势不得不补，然须得补耐补乃幸。", "18015": "（案27）温邪九日，身热不扬，瞀闷不扬，燥扰，舌绛苔白，气喘耳聋，痰咳不爽，斑发紫黯，隐约不出肉，脉细，濡数而伏。此属邪陷膻中，有昏厥立危之势。急急清营透表，邪达乃幸。", "18016": "身微热，四肢不温，神蒙耳聋，舌红渴饮，瞀闷呓语，斑发不掀，脉浮不出。温邪痰热，内扰蒙闭，渐入心营之势，恐陡然昏痉厥闭。今拟清营解表，辛香开泄，以冀转机。", "18017": "身热不扬，昏狂叫喊，呓语喃喃，脉数不出，烦渴引饮。阳明邪火极炽，仍虑昏痉厥闭。再拟清营辛开，甘寒化热，扶过两候方可。", "18018": "又，夜来得汗之后，昏狂烦热似定，舌色亦少淡薄，但大便连行，而脉甚细软，神志倦怠。最恐邪去未净，而正气先虚，今宜清解和胃安神养阴方。", "18019": "病情如昨，泄泻数减，脉来细数，而寸不出。乃太阳邪热入太阳阳明，舌红苔黑，深恐昏厥。", "18020": "热势退缓，舌红苔浊，脉数口干，阳明之邪未净，小溲短赤，是湿热癃闭州都所致。", "18021": "（案30）温病八日，身热不扬，脉左空弦，右模糊，膺闷呃忒，面赤如醉，舌红苔白，邪热苔白。痰湿混阻，其势颇危。", "18022": "大战一昼夜，邪热势猛，几危屡次，幸而肤黄斑透得解，转致咽喉微痛，颊车失开，舌绛口干，面油目昏，脉数左弦。乃阳明之经犹热，少阳之气内亏，湿反化燥之时，犹恐泛而复聚。今当清营滋化，理咽除痰，不致再生更张乃吉。", "18023": "（案31）身热不扬，气逆咳嗽，痰中映红，脉数，左细软，右浮滑。冬令过暖，温邪蕴伏肺中，呛伤营络，恐增喘急。阴分本亏，只宜轻济清泄，慎勿辛温发散。", "18024": "（案32）身微热，畏风恶寒，瞀闷气喘，体痛右甚，脉浮滑数。劳倦感邪，气痹不宣，恐其厥逆。", "18025": "（案33）肝气挟痰塞逆，心脘掣痛，陡然寒颤，壮热痉厥，洊至汗出如雨，肤冷如石，脉细如发，语言不出。是痰邪内伏，肝风鸱张，正气欲脱，危如朝露，无可奈何。勉拟扶正涤痰，回阳救逆，以冀万一。", "18026": "（案34）冬温九日，身热不扬，神烦瞀闷，脉数不畅，舌红苔黄，手腕搐搦，痰邪内伏，肝风欲动，恐其复厥。", "18027": "（案37）形寒身热，面赤戴阳，呕恶舌浊，脉沉细，少腹拘急，终宵不寐，气上冲心。高年湿热内盛，冬温深入厥少。其势危笃，勉与仲圣厥阴治法。", "18028": "（案39）脉浮，头项强而恶寒，此太阳病也。病后阴虚，宜兼滋养。", "18029": "（案42）湿热肝气内郁，风寒外遏，心中懊𢙐不食，目黄，舌绛唇干，脉不通畅。治当疏达。", "18030": "（案48）风寒壅遏，食滞停积，肝气上逆，寒热昏躁，胸闷脉伏，势将昏痉厥闭。若此重症，如何来此就医？勉拟方速载归，而勿再来也。", "18031": "（案50）肢冷身热，烦躁呻吟，脉沉数。冬温，食滞阻中，暴寒外遏。其势棘手。", "18032": "（案52）女，产后营虚，温邪乘袭，寒热匝月，咳呛气短，腹膨，脉细，神倦。恐其邪正两脱，至险至险，勉拟一方。", "18033": "（案54）冬温九日，形凛身热，脉细数，舌绛苔白。阴亏不能运泄，将恐邪陷昏愦。", "18034": "身热夜重，自利渴饮，舌绛苔黄，脉细，呕恶不食。阴亏之体，冬温内伏，防其昏陷。", "18035": "（案56）身热旬余，微汗不解，脉细数不出，舌绛苔黄，渴饮便闭。温邪夹食也，恐其内陷转重。", "18036": "（案57）冬温八日，瞀闷脉伏，邪食并重，恐其内陷。", "18037": "热退不净，咳呛呕吐，脉弦而数，寐则呓语，肝胆之阳挟温邪而上升也。", "18038": "（案60）身热不扬，遍体浮肿，脉紧，舌黄口干，咽哽胸闷。冬温内伏，严寒外遏，肺不清达，最恐喘急，不是小病。", "18039": "（案61）身热去来靡定，得汗解而旋覆燥渴引饮，舌白中浊，脉濡数，不食不寐。此暑风湿热混蒸阳明太阳，居素交虚，惟恐里走，或得转而为疟乃幸。", "18040": "夜来热退不净，神烦无寐，脉数软，舌干微黄。暑热蕴伏，惟恐复热，拟从肺胃达泄。", "18041": "果然复热，昏谵鼻衄，烦渴引饮，脉数不畅，舌红苔白，小溲短赤，烦躁无寐。暑伤心，寒伤气，肺胃邪火鸱张，惟恐阴伤风动，已届一候，病情未定。今拟清解达泄，冀其转疟如何。", "18042": "热缓不退，脉细数不出，舌红苔黄，鼻衄盈盏，烦渴引饮，彻夜无寐。暑热深伏阳明营分，将恐热迫阴伤，当清营滋泄，得转瘅疟乃幸，仍不可泛视也。", "18043": "夜来热甚神昏，平旦醒而热退不净，似乎疟象而未准者，但症阳脉阴，深恐正不胜邪，转虚迅速，颇难立法，拟清气热和胃阴法。", "18044": "昨午表热不壮，而自觉心中甚热，阳亢阴亏所致。脉象模糊，神烦无寐，额热不退，舌心剥落，口苦吞酸，阳明湿热不化，心肝气火内盛，必须耐性以调之，如躁急心热更张或多失。仍拟扶正养阴、和胃安神以消息之。", "18045": "身凉额亦不热，脉象稍出，左弦右空，舌苔腻白。暑湿若有未楚者，然尚虑散而复聚。烦渴渐减，正亦渐弱，宜未雨绸缪，勿使虚态毕集。", "18046": "昨身热至晓退解，脉左弦右数，舌红苔白。究是暑湿伏于阳明而为瘅疟，扶正安神，化痰清热，一定成则。", "18047": "昨发疟得汗而解，兹诊其脉，仍依旧弦数，得毋欲变日至乎？仍与扶正养阴，化痰和胃。", "18048": "热甚而长退时，汗少口干，舌红脉数空弦。肺胃之邪尚蕴，心肾之阴已耗。急宜壮水以制阳光，咸苦入阴法。", "18049": "忽凉忽热，汗出不彻，舌转浊白，脉数不畅，究是热蒸湿蕴。清滋养阴之中，兼渗三焦分利。", "18050": "热自里发，值于暑湿交蒸之时，且夺精于病前，今为期三候，寒热不定，多于申酉之间。脉静脉大则身和，脉大则身热，最易液涸风动。", "18051": "昨热尽退，兹诊脉，仍数，额微热，口苦耳聋，悉属少阳阳明见症，暑湿未能尽化，而阴气孤绝，阳气独发也。与仲景方，清气热养胃阴。", "18052": "（案64）少阴之脉循喉咙，挟舌本，兼兹以里邪兼发，又被暑湿交蒸叠进，清解暑湿退热，邪之流弊未楚，是以咽痛嗌干，脉不数而少纳，四肢清凉也。拟少阴立法。", "18053": "（案65）七夕表热已解，而转增咽哽阻咽，咳呛痰稠，脉数右大。少阴本亏，真阳上燔。咸苦滋救，仲景成法也。公议方。", "18054": "热不复来，利亦减缓，惟舌本绛而苔花，搭脉右甚数。肺胃余热未清，心肾之阴颇亏，此时尚须清肺和胃，滋养心肾，为善后之计。", "18055": "倦怠不嗜食，寤寐纷纭，脉细软数。皆属邪去正虚，心阴内亏之故。拟安神补心，和胃养阴，然后再商峻补。", "18056": "形神色脉，悉属转虚，必须扶正养阴。", "18057": "（案66）夜来小便，寤寐不安，口干舌燥，背脊轰热，脉数右大。皆系心肾内亏，阳亢阴虚。权宜摄阴潜阳。", "18058": "（案67）深秋凉风触动暑湿伏邪，初起间日瘅疟，已属阳明见症，尔来热无定时，脉空数，两关独大尺短，舌绛边碎，口糜气秽，咽哽塞。胃中邪热内蒸，阴液日渐告涸。不但虑其病久正脱，抑恐毒气内陷，则胃败不食。姑拟彻热救阴、清胃解毒之法，以消息病机。", "18059": "平旦潮热又发，燥而渴饮，胸痞气粗，口糜气秽，鼻痒舌干，脉数。悉属肺胃蕴热，阴液内涸之象。喻西昌为的对之方，但其热势猖狂，深恐鞭长莫及。", "18060": "连进苦泄滋阴，甘寒化热，津液不回，神识模糊，脉数无力。邪热匿于痰中，蒙闭心营，正气不得振托，明日三候陡然昏厥，将何料理？不忍束手，竭蹶拟方，以冀弋获。", "18061": "夜来得微汗，神醒而倦怠懒言，脉右弦数，唇仍干，身热暂解。目前之急，痰邪终未能出，虑其明日复然，治法不外清营化痰，公议方损益。", "18062": "晚诊：更衣不畅，渴饮脉数，邪火之势未衰也，胃中津液大亏。若明晨忽然风动，将何以御之？此时滋清熄风之外，无他道也。", "18063": "病情如昨，脉象稍逊，寤言不寐，邪热逗留不去，正气日渐消除磨，假使今晚复热，岂不大费踌躇也乎？公议清阴中之热，和胆胃之热。", "18064": "晚诊：热不复发，固属转机，然脉软少神，更衣怯力，口干舌蹇，阴液颇亏，伏热不清，怕其骤虚，口疳糜烂。责在专司滋阴和胃，以熄余焰。", "18065": "脉形虽软，病情未减，即古云难成而易亏者，阴气也。口糜不除，胃中自觉热气上升，乃余焰未熄。宗前法滋阴清化，和胃生津。", "18066": "夜来又作潮热，热时神蒙，幸喜为刻无多，脉形仍数，翻覆不已，究属余邪留恋。拟清骨散以搜剔之，佐以清胃。", "18067": "（案69）脉数，左关弦，右关大，蒸蒸潮热，莫往莫来，邪诚在阳明，若云不涉少阳者，恐未必然也。然病久阴液已涸，岂仅和解可溉？自应清滋化热，少佐宣达，亦迎其机而导之之法也。", "18068": "潮热两度退而不尽，渴饮舌干，脉弦数。暂停滋腻，独取阳明。", "18069": "（案70）漐漐汗出，且发白疹，莫非伏邪外达，然神倦，脉软，口秽舌干。邪热未去，正气已虚，最恐陡然转虚，成败未卜也。用和胃养阴、扶正化邪法。", "18070": "热退脉小缓，热来则数大，此邪之聚散也，舌苔稍润，渴饮溺赤，斑发未艾。清滋解泄，一定成则，昨宵法合当，继之。", "18071": "身凉脉静，不比昨日，其邪若有未净者。然养阴和胃为主，清泄少阳为佐。", "18072": "（案73）病已逾月，舌红苔黄，脉数关大，渴饮溲赤，痰浊口腻，不更衣者六日。虽未可云腑实，而阳明之热究属未清。须得便通之后，舌淡脉静，方可填纳。然乎？否乎？方未录。", "18073": "湿温病后，饮食不节，复热十余日，战汗不解，遍体红紫，蓝斑密布，齿衄成流，脉芤涩。湿温热毒，深伤阳明，营分血得热而沸腾也，势极危笃。", "18074": "（案74）暑风湿热夹痰食交蒸，十六日不得汗解，神志昏蒙，唇肿舌强，脉沉滑数。邪结膜膈，渐入心营，大势棘手。勉拟清营泄热，开窍豁痰，以冀万一。", "18075": "（案76）湿温疫邪九日，神呆，脉伏，斑点模糊，内陷之象，其势棘手。", "18076": "退而复热，脉芤舌绛。阴阳邪复伏，若至两候不解，势必内陷风动。", "18077": "（案78）壮热气喘，头汗如蒸笼水，脉数不畅。暑湿热三气蒸蕴阳明太阳，恐其昏厥。", "18078": "（案79）女，身热十九日，乍重乍轻，既汗既下，热仍不退，神志恍惚，手肢搐搦，脉数模糊。此属暑湿热三气交蒸，产后营虚不克，振拓以致热甚生风，液亏成痉，颇难立法，勉拟一方。", "18079": "（案80）身热不扬，忽轻忽重，濈然汗出，舌红苔黄，目赤面垢，脉右软左弦，渴不多饮，呕恶吞酸，初起胸满引背，继发疹点。少阳而兼阳明也。神倦声少，两候之内，不致虚波陡起，乃幸。", "18080": "（案81）胸痞呃忒，面赤戴阳，肢冷自汗，脉软尺空。暑湿内闭，阴浊上干，阳气外脱，生脉八味极当。僭拟白通继进。", "18081": "（服白通汤后脉得微续，可否继进？）", "18082": "（案82）疟来呃忒烦冤，瞀闷躁扰，退则汗出，肤冷神惫，脉微。此正不敌邪，若今夕再来，恐其虚脱，姑与摄纳，亦既竭吾才，欲罢不能也。", "18083": "生脉散加熟地、牡蛎、茯神、乌梅肉", "18084": "（案84）温湿交蒸，身热有汗不解，腹膨满胁，腹泄，全不思谷，脉细而数。肝肾内伤，大势棘手。若曰播逃，则我不敢。勉拟培中泄热。", "18085": "（案85）暑湿伤气，体倦脉软。", "18086": "（案88）女，产后腹痛偏右，虚中有瘀，身热咳呛，音哑脉数，兼夹客感，防其内陷昏愦。（此亦女科套方）", "18087": "（案89）暑湿热三气交蒸，身热脉数，烦渴溲赤，匝月不已，恐其转重。", "18088": "（案93）阴分本亏，暑湿伏邪触动深秋凉风，而发寒热，不能成疟，舌红苔黄脉濡，烦渴咳呛，恶心鼻衄。邪火甚炽，恐其内陷风动，不可泛视。拟喻西昌法。", "18089": "（案94）阳微湿胜之体，夏病缠绵未复，将交寒露，寒热复作，二便失司，脘痞呃忒，自汗鼻冷，神疲脉微。中下无阳，阴霾痰浊混阻上干，形神色脉，无一不脱，兼不进谷食，将何恃而不恐？拟扶正通阳，涤痰泄浊，以冀弋获。", "18090": "（案105）失血损体，伏邪晚发，热解肢冷，汗出呃忒，脉微细。虚波不测，最防其脱。", "18091": "伏邪晚发，似疟似痢，舌绛苔干，脉细数。日中少安，夜多烦躁。阴伤已极，正气不支，最恐虚脱。扶正救阴泄热，一定成则，舍此之外，无他道也。", "18092": "（案107）体倦，肤黄，足软，舌白，脉迟而空。中下阳微，暑湿内困，当与扶阳理湿。", "18093": "（案108）女，小产之后，下血过多，暑湿热邪内蕴，遍体浮肿，微热咳呛，头胀脉数，口干，舌苔白腻。虚中有热，恐成蓐痨。", "18094": "（案109）伏邪初秋即发，类乎瘅疟，序将入冬，热不了了，口淡食少，干咳气短，脉空数，舌绛苔白。正气受伐，而虚热仍伏肺胃。只宜轻剂化解，若恣意疏散，药过病所矣。仿孙真人法。", "18095": "（案110）伏邪恰发霜降，表热不壮，心中烦灼如焚，舌绛渴饮，脉空数。阴液被劫，势将风动昏厥。此非人力所能为也。拟兼顾。", "18096": "（案111）伏邪发在秋初，身热屡汗不解，闷烦自汗，脉象濡数，舌绛苔白。其邪蕴于少阳阳明，正气欲虚，恐其变痢。", "18097": "（案114）表热不壮，痞胀不食，少腹隐隐攻痛，舌苔黄浊，脉不流畅。此必阳邪陷入阴经，肺气不通所致，颇为费手。仿仲景法，兼佐以浊泄浊。", "18098": "（案115）伏邪发于秋杪，淹缠半月，形凛身热，日晡则甚，平旦则减，脉弦细数，舌黄无苔。烦劳素虚之体，不但阳伤，阴气亦伤，自难送邪外达，复脉法如何？", "18099": "复脉散去人参、麻仁，加丹皮", "18100": "（案116）伏邪至两月，胸腹灼热始终未退，而复发寒热，热后大便瘕泄，痰嗽气逆，嘈杂如饥，寤言不寐，舌绛干，苔黄腻，脉空数。酒客平素湿热蕴蓄中焦，扶外邪必逆满，病久正虚邪痹，最恐阴阳风动，议用泻心法。", "18101": "（案117）胸胀闷热，咳嗽痰塞，大便频泄，邪踞中下二焦，但脉数空软，舌伸发抖，下真自空。陡然虚波，不敢不虑。", "18102": "伏邪廿四日，肤黄不解，邪蒙语杂，脉空大滑数。咳喘痰血，舌苔浊干，大便仍泄。病久五脏之阴皆伤，痰热蒙蔽心营，肺胃势必内闭外脱，危如朝露。不得已勉拟清营滋泄合喻西昌法，以冀弋获。", "18103": "（案118）伏邪晚发，湿热内蒸，腹痛胁胀，肤黄，舌黑，右脉如丝。恐其邪结正脱，至险至险。", "18104": "（案119）伏暑发在秋杪，是以辛温伤阴，以致形削色痿，今虽渐回，尚未恢复。诊得脉左弦数，右软细。是肝升太过，肺虚降令不及，使之然耳。", "18105": "（案8）阴疟淹缠百日，近增咳呛，形神色脉空虚，项背筋惕，病在冲督。历来守不服药，为中医之戒，恐其因循成怯，不得不为熟筹之。", "18106": "（案10）三疟邪伏在阴也，便溏脉迟。脾肾之阳已衰，当先温阳截药。", "18107": "（案11）三疟淹缠，正气日渐消磨，脉左弦右滑，舌绛，肤黄，遍身瘙痒。湿热风痰混伏扰乱。若不疏风涤痰，其正焉能支持？", "18108": "（案12）疟发三阴，缠淹四月，脉细数，胸闷舌红，神倦形削，正气已虚，邪又未达，理之不易。", "18109": "（案16）疟疾几及三月，形神色脉皆虚。若再淹缠反复，骤然脱厥可虞。", "18110": "（案19）暑风湿热为疟，体盛脉小，阳气虚也。舌如傅粉，胸痞脘闷，其邪未离膜原，惟恐疟来昏厥。", "18111": "（案22）中秋伏邪，疟后元气未恢，脉细数，形神削夺，上咳下泻。肺脾同病，土不生金，恐不成疟痨。", "18112": "（案24）疟来深秋，三翻四复，延至冬半，左胁结痞，脉弦细数，形神削夺，面色㿠白。伏邪久踞，正虚不敌，洵可畏也。", "18113": "（案25）疟不了了，咳呛脉数。当补肺阴。", "18114": "（案2）伏邪为痢，缠绵五旬，近因寒热而痢顿减，脉细数，唇红舌白，形削色㿠。暑去湿存，中阳式微矣。急急扶正，惟恐不及。", "18115": "（案7）身热腹痛，块攻下痢频频，脉微神倦。邪从下陷，正气不守，颇为棘手，勉拟逆流挽舟法。", "18116": "（案13）伏邪疟后，自不慎守，里陷为痢，形脉皆虚，饮食减少，将何恃而不恐？", "18117": "（案14）素居阴亏营热，肝气抑郁，秋初半产之时，以后寒热如疟，邪传太阴，则腹胀消而变痢。痢无休息，复又寒热互作，骨瘦如豺，脉微如丝，舌光如镜，皱纹如纱，此属阴液干涸、阳气外脱、营卫分争之势。正秋冬之交，历历危惧竭蹶。拟方：", "18118": "（案15）由疟变痢，起自半秋，缠绵休息，近冬不瘳，腹中微痛，面黄不泽，舌苔白腻，脉左关弦右濡，下痢红白相兼，大便不实。此因湿暑伤中，气分有湿，血分有热，脾虚肝盛所致。治以扶中养肝，清热利湿。", "18119": "（案17）女，久痢命门酸坠，脉细数，舌红，腹痛后重。恐阴亏气陷，暑湿黏著，最恐妨胎之险。", "18120": "（案8）少阴咽哽，遍体浮肿，肤黄，舌浊，脉细弦数。阴亏肝郁之体，湿热内蒸也。当以养阴泄热，疥疮存而不论。", "18121": "（案11）恍惚惊悸，眩晕怔忡，脉芤涩，形疲，色不华。皆由心阴过亏，暗吸肾真，水不涵木，则无风而自动矣。", "18122": "（案15）心营内耗，暗吸肾阴，少寐气短似喘。孤阳上冒，面赤足冷，肝逆犯胃，吞酸妒谷，表阳外薄，汗出津津。色脉皆虚，非补不可，更须息心静养，庶几药力奏功。", "18123": "（案19）脉细左弦右涩，营虚水亏，肝木失涵，虚风内动，所以见症若此。当养肝肾之阴，佐以滋镇熄风。", "18124": "（案23）头痛满蒙，右半尤甚，鼻塞涕浊，脉数弦滑。肝阳挟痰火上升无制，治当清降化痰。用风药升散，无怪其难忍矣。", "18125": "（案25）脉涩右空左细，四肢麻木，形容不泽。心肾阴亏，肝木失涵，风阳窃动，当乙癸同源。", "18126": "（案28）脉象病情并无进退，而终岁哓哓，心阴暗耗，阳岂能潜？今当秋冬，自宜养阴，不必炼真说假。", "18127": "六诊：迩日脉形细软，两尺微数，面黄肌瘦，舌起刺。心肾之火不靖，脾阳不运，肝气升逆，肺失肃降。治宜运中固下，勿拘拘于养阴，若杂乱无章，焉能向愈？系痛痒相关，敢不沥忱苦告候，诸同学印可。", "18128": "（案6）中下阳微，痰气上泛，神惫脉缓。", "18129": "（案8）午后呛甚痰稠，脉弦滑数，是肺火上浮。以轻剂清苦降之。", "18130": "（案9）饮食之后，舌蹇，言语不清，脉弦数，是水谷之气挟痰火上升。法宜养胃并治，再仿温胆之意。", "18131": "（案12）中下阳微，阴浊寒痰上升，呕吐涎沫，心中嘈杂，脉濡细舌白。序届冬至，阴阳交潜之时，恐其不相维系。世兄方甚合，僭加附子一钱。", "18132": "脉如蛇行，遍体漉漉有声，胸膺瞀闷，咳呛不爽。此必痰饮水湿，凝结经络，补之固属无益，而峻攻又恐伐元，极难取效者。", "18133": "（案13）高年不惮勤动，从高坠下，趺痛，左肋艰于转侧，脉有歇止，气喘咳嗽，呃忒频频，寝食皆少，是阴亏内热，肝升肺不降也，最恐呃而致痰塞气厥。", "18134": "（案3）病后邪伏不清，元不复反，烦劳以致肝气逆胃，不饥不便，色脉皆虚。若不进谷，何恃而不恐？", "18135": "（案6）胃气受寒，脘痛呕吐，脉迟而滑，老年阳衰所致。", "18136": "（案14）腰痛腹胀，呕吐酸水，脉弦左小，舌绛苔白，面赤足冷，肝气贯膈入胃，肾病善胀使然。当与苦辛泄降，咸凉内沁，分头而治。", "18137": "（案21）攻药伤中，肝木乘脾，元气受戕，以致形神削夺，脉空数，左胁痛引及背，缠绵日久，气营并亏，又自不能节劳，极难恢复。当和脾养肝。", "18138": "（案26）虚里穴痛，引及胸胁，饮食阻咽，脉芤涩。肝气抑郁，营络空虚，未老先衰，恐成膈症。辛燥开气，清凉凝滞，皆与病左。", "18139": "（案27）心痛彻背，时发时止，脉细涩。中焦营虚，肝气贯膈入卫。当和营养血，柔肝利络，不可香燥克气。拟膏方。", "18140": "（案28）脉细数弦滑，肝气素盛，酒醴湿热化火化痰。木火横逆，则胁胀背酸；肺金不肃，则痰塞咳呛。治当化肝降肺。", "18141": "（案3）痛在脐下，形寒怯冷，脉数，舌干白，春寒袭入厥阴，深虑发厥，与仲圣方。", "18142": "（案3）气血皆虚，肝阳化风内煽，恰至冬至大节，陡然昏晕神迷，右肢不用，脉细滑数。此偏中也，七日以内，谨防昏厥汗越，非指日可愈者，不敢泛视。", "18143": "（案7）牙龈不肿而痛，脉数左细右大，阳明有余，少阴不足，右股痹痛，亦属阳明络热，非寒也。", "18144": "（案9）脉细数，此阴亏肾热症也。又误投刚剂燥，形疲肉消。古人云：人火无物不消。渐渐骨痿，不起于床矣。奈何奈何？急进咸苦滋泄，犹恐鞭长莫及。", "18145": "（案10）病在左臂，昼轻夜重，脉滑疾。自必气血两虚，风痰袭络。法宜补气养血，熄风化痰，兼通营络。拟膏方。", "18146": "（案20）右肱麻木痛楚，脉空右大。营气交虚，风湿痹络。", "18147": "（案11）秋初失血，吐之甚狂，癸水自此不至，逢节必发，脉细数，咳呛，形凛骨蒸，已成劳损矣。忧自乳子，何不惜身命若此？", "18148": "（案12）久病缠绵反复，形神色脉皆虚，当此一阳将萌，更何恃而不恐？不敢用药，勉拟饮食调养，以冀扶延。", "18149": "（案13）上吐下泻，脉软音瘖。法扶土生金。", "18150": "（案15）损怯而至音哑，喉痹。骨瘦如柴，色脉皆脱，已是末传，非草木能疗者。", "18151": "（案18）脉象左弦微细，右空若谷，何虚之如是？", "18152": "（案21）积劳阳伤之体，深秋痰嗽失血，缠淹百日，形脉皆衰，理之非易。", "18153": "（案22）冲年阴虚，疟后不复，咳呛痰稠，脉细空数，形神皆夺，是近怯之机，可不惧乎？", "18154": "（案5）风伤皮毛，热伤血脉，咳吐痰血，气腥，恐成肺痈。", "18155": "（案6）脉滑，舌白，因痰而咳。", "18156": "（案7）咳呛夜甚，嗽而欲呕，动则气喘，脉细数。肾阴下亏，肝火上逆，肺不肃降。必须养肝摄肾，和胃化痰，断不可开泄上焦矣。", "18157": "（案10）咳呛匝月，误服酸梅，以致咳吐，浊痰上泛如饮，背凛冽，呛甚，灼热不休，肌瘦脉数舌白，势将成痨矣。案云：温邪内郁，挟痰饮，蓄结于肺俞，所以背寒则咳呛，邪为酸敛，固结不解，热恋伤阴，肌肤焦灼，饮蓄于中，舌白不浊矣。此症近似劳怯而非怯也，断乎不可以补，若补，邪愈无出路，而成怯症矣。肺俞二字是看病眼目。", "18158": "（案10）失血咳呛，屡发不已，脉细涩。心肾之阴已竭，急宜平补。偏寒偏热，均未得其病之旨。", "18159": "（案11）春初咯血，较之冬半倍多，脉数，左空弦，舌颧赤。肝肾阴亏，孤阳上冒，最恐暴脱。拟乙癸同源。", "18160": "（案13）病后失调，咳呛痰血，脉数右空，肺已损伤，势难治也。", "18161": "（案19）驰骑习武，百脉震动，动则络逆为痛，血沸出口，纳食起居，无异平日，非虚损也。凡气为血帅，气顺血自循经，不必用沉降重药。", "18162": "（案1）足肿腹胀，筋见脐凸，舌白、脉沉细。此虚臌也，急切难治。", "18163": "（案4）脾肾阳虚，水湿浸渍，浮肿下甚，神倦脉微，最易虚脱。", "18164": "（案7）泄泻便溏，腹大筋见，脐突咳呛，脉数。膨胀痨损已成，甚为棘手。", "18165": "（案8）脐凸腹胀偏左，脉细数。肝气抑郁所致，不易速效者。", "18166": "（案11）茎衄甫止，遍体浮肿，脉细数涩。血化为水，邪热走入空窍也。", "18167": "（案16）泻后肿胀从下起，脉迟细，舌白。中下阳微，恐其悠悠忽忽而脱。", "18168": "白术桂枝炮姜椒目附子川朴茯苓牛膝（案17）脉细左弦右涩，腹大囊肿，筋青脐凸，此因郁怒伤肝、思虑伤脾所致。木来克土，血不归经，致成臌胀，苦寒温热皆与病左，且拟薛立斋法以消息之。", "18169": "（案2）脐腹起痞有形，略偏于左，脉细数，左弦右软，舌苔干质。高年气血两衰，思虑伤脾，郁怒伤肝，乃为中虚气痞之症，理之谅非易也。", "18170": "（案3）阳𫏋脉满，令人不寐。", "18171": "（案3）病逾百日，身热来去靡定，脉数舌绛，小便数欠。此属童年阴亏，湿热癃闭州都所致，气化失司。法当养阴利湿，使其热从小便而出。", "18172": "（案2）形寒身热，一载有余，便溏，脉细涩。表里皆亏，气虚下陷，拟东垣法。", "18173": "（案5）上咳下泻，形神削夺，脉细，舌白。肺脾虚寒，治在中焦。", "18174": "（案1）形伟，脉小细而且涩。心脾阴亏，血从下溢。", "18175": "（案4）嗜酒中气自虚，操劳过度，心脾阴伤，忿怒抑郁，肝阴亦伤。肝不藏血，脾不统血，血不归经，渗而为瘀。今留血上下皆溢而络空气痹，脘背两胁少腹连及腰走注疼痛，右脉芤涩，左寸空谷。面部浮黄，肌肤失泽，气营并病，有虚有实，理之非易。必须静养怡悦，多方调治。若躁急心热，药难奏效。公议益气养血，和营通络法。", "18176": "（案5）大便连行，粪黑居多，仍是瘀也。满肠皆痛，遍体浮黄，少食无寐，六脉空谷。二气交虚，精神失守，怕其悠悠忽忽而脱，急急补养平调，犹恐鞭长莫及。", "18177": "（案13）夏暑秋风伤肺，移热大肠，溏泄便血，湿阻州都，则为茎痛。治宜清热导湿。舌光脉数，阴液大亏，当兼顾之。", "18178": "（案4）心脾极虚，八脉损伤，崩漏不已，最恐虚波。", "18179": "（案6）病在八脉，急切难治。", "18180": "（案7）年届七七，癸水应绝而反，来日苦多，去日苦少，脉细数，语言窒塞，肝肾本亏，心脾复伤，气不摄血。拟黑归脾法，然非旦夕可愈。", "18181": "（案8）产后腹痛，癸水衍期，形神削夺，脉微细软。气营大亏，非补不可，从未服参，反为不对，是何言欤？", "18182": "（案9）春产徂腊，月事不来，脐下症瘕，隐隐作痛，吞酸谷少，脉数而虚。此属肝气抑郁，血不流行所致。今且和其肝胃，缓其腹痛，然后再商消痞。", "18183": "（案11）产后营虚，肝不疏泄，面浮足肿，少腹痞硬，天癸衍期，脉微细涩。急当温补气血以调达肝气。黑逍遥散。", "18184": "疔红肿便闭，脉实者，必须用鲜生地、黄连、木通、生军之类。", "18185": "额颅血痣翻花，上及腮门，下至眼胞，肉翻峥崚，振动出血，脉数细，左弦，阴伤，心肝火旺，宜犀角地黄汤治之。", "18186": "腮颊为手阳明所过之地，骨槽风症缘阳明湿热与外风迫结而成。其来必骤，盖火性急故也。今外溃已久，牙关不开，缘颊车中坚硬未消，开合不利。古之用中和汤者，因从病久脉虚，故用黄耆之补托，四物之养血，桂心、白芷以散结邪，银花、花粉、元参、贝母之清化蕴毒。前言所议极是。但阳明多气多血之经，温补过施恐有偏弊之患，拟照古之中和汤不增不减可也。", "18187": "骨槽风，溃后筋脉急缩，以致牙关紧强，兼之余蕴未清，腠理结核，两耳作鸣而音不聪，厥少不和，阳浮于上。拟养阴清肝，兼和脉络。", "18188": "骨槽风症，窦汉卿名穿珠穿腮，心法曰：牙上发、牙槽发，二者皆以手少阳三焦、足阳明胃二经风火是。夫手少阳之经系手走头，足之阳明系头走足。恙由手经而入，始则牙痛颐肿，面肿上过太阳，继入阳明，则由项及胸。初时先下于前，嗣又慢补于后，以致毒火蕴遏，伤阴耗气，不能去毒化脓，散漫无定，脉象左部散大，右部濡小，舌㖞目定，阳缩，头面无华，汗多，气血两败，已成陷症。药病不能医，命由天定，非人力所能挽也。拟方尽人事而已。", "18189": "昨晚进汤药虽有转机，脉仍未起，未可为恃。原方中加生地五钱。", "18190": "牙菌落而复生，肝阳火郁不解，幸软而不坚，可无足虑。惟营血素亏，肝阳化风，左半头痛，脾土又弱，腹痛便溏，右脉较起，脾肾渐有充旺之机。肝气虽强，水足而木自柔和，虚阳自不上潜。仍从脾肾进治。", "18191": "脉神较起，惟肉翻峥崚，左腮上腭出血数次，火郁阴伤。当养阴清肝。", "18192": "肾阴不足，心火肝阳上亢，发为舌疮。舌根破碎成窟，不时内热，舌为心苗，肾脉贯肝膈，循喉咙，挟舌本，肾阴不升，心火不降，未济之象也。恐酿成舌疳大患，法当滋水制阳为治。", "18193": "盘槽痈月余，自左及右间溃流脓，腮外坚肿，硬势又将破溃，发热便闭，食少哕恶，脉细神疲，阴伤胃热不化，症属不轻，拟以甘寒清解。", "18194": "肝火瘰疬颈项，自胛至胯发热，脉数，遍体经络擘痛，宜逍遥散加减主之。", "18195": "肝郁不舒，气火夹痰，凝结颈左，失荣坚肿，筋脉攀痛，宜清肝解郁。", "18196": "乳岩一年肿突，红紫甫溃，两目筋脉掣痛，难治之症。勉拟养阴清肝。", "18197": "暴怒伤阴，厥气火偏旺，与阳明之痰热交并于络，以致乳房坚肿，颈颜连结数核，或时掣痛，已成岩症，脉数右洪，气火不降，谨防破溃。急为养阴清肝。", "18198": "乳核掣痛已减，肝火未清，脉尚弦数，仍以前法。", "18199": "肝气夹痰凝滞，蔽骨发为痰疽，已溃，一头肿硬不消，又将破溃，脉来两尺弦数，荣血已亏，阳明痰气不清。宜养荣和卫，兼化痰软坚之治。", "18200": "抑郁伤肝，思虑伤脾，肝脾荣损，气动于中，木火夹痰上升，少阳经气郁结颈左，发为石疽。硬坚如石，肩项酸胀，牙紧喉痹，脉细神羸，已入沉疴，势难挽救。姑念远来，拟方回府调理。", "18201": "呕吐已止，饮食加增，石疽肿亦较退，似有转机。但牙紧未松，喉痹未舒，脉沉弦涩，阴伤木郁，痰气凝痹。上尚在险途，恐未为可恃。姑从原法治之。", "18202": "郁怒伤肝，气滞于络，络血因之留阻，胸胁作痛，继之乳根坚肿，石疽大症，脉来弦强，动劳喘气，自汗盗汗，肝阴伤，肾气不摄，症势极重。拟育阴柔肝，以化坚结。", "18203": "肛漏一年，阴气耗泄于下，阳伤于上，冬春咳嗽恶寒，肝气拂郁，肚腹作痛。入夏以来呛咳益加，咽痛妨食，痰多作恶，腹痛频频，大便时溏，脉来尺寸弱而急，肺肾并亏，肝木侮土，势入损门，殊属重候。拟养荣柔肝，兼补肺滋肾。", "18204": "肝痈背肋肿痛，一月迩来咳嗽气急，痰腥肢冷，汗多，或作蜕热，脉虚细，症势极重，碍方以望转机。", "18205": "肋痈即肝痈也，乃痰气血滞于肝络，肝胀成痈，外溃两月，肉腐外紫，胸背骨胀，内热咳嗽，短气，脉数，肝肺两伤，荣阴大损，势入损门。姑拟清养。", "18206": "《素问》以肝痈两胠满，卧则惊，不得小便。又曰：期门隐隐痛者，肝痈。其上肉微起者，肝痈。未能详言。后陈远公曰：人素多郁怒，致两胠胀满，发寒发热，继而胁疼，手不可按，火盛烁乎肝血，此肝叶生疮，在左不在右。左胁之皮必见红紫五色，以化肝消毒汤。丹溪治以复元通气散、柴胡清肝汤，溃后八珍、六味滋补脾肾法，致难稍备，究未详明确当。肝之脉从股阴入毛中，环阴起器，抵少腹，上贯肝膈，布胠，至期门而终。肝气壅滞，故胀满不得小便。肝病发惊骇，魂不藏，故卧则多惊，故肝盛则两胠痛，怒火动则烁肝血，血凝气壅则肝胀生痈，手不可按，毒聚而未成。若皮现红紫之色，内脓已成，发越于外之象也。嗜酒之人每多此患，酒入于胃则肝横胆浮，肝即横则气血不能顺行，胃中痰浊亦旁流于胁。痰气血交混，结而为痈。又有闪气之人，亦生此患。闪则气滞，而血亦滞，久而不愈，亦发痈疡。小儿亦见有之。小儿之生，乃因痰热入于肝络，先咳嗽而后胁助肿胀，但此症初生，病者因不生痈而医者总云肝气，十有八九一派辛香耗气，迨至胁肋肿胀，姑知生痈。必呼吸不利，转侧不能，手不可按，症明且确，医者岂可自恃万能，按脉即晓，以肝气治，贻误匪浅。肝火甚者，脉必弦数，挟瘀者脉弦涩，挟痰者脉弦兼滑，治与肝气迥殊。伤于此者，不知几何，故谆谆辨论，临症之时不可不审也。用特列方于后，并录治验数则，以便参观。", "18207": "四方六味地黄汤治肝痈溃后发热，虚羸脉数，服此以滋肝肾。", "18208": "五方八珍汤治肝痈溃久，气血俱虚，脉弱。", "18209": "肺痈一年，咳吐脓血，发热脉数，势入损门，当养阴清痰热。", "18210": "悲哀伤中，气凝血结，脐上脘下结硬作痛，已成漫心痰。寒热泻黄，脉弦，夹有暑邪，殊非小恙。姑拟宣畅气血，散结化痰之治。", "18211": "劳倦致伤，加复忧思，郁结颈左右，发为马刀。坚肿如石，痛掣头脑，脉细软，气血两亏，生气日残，极难调治。姑拟养荣扶土，以化坚结。", "18212": "血虚肝火，夹痰凝结，颈右发为马刀结核，坚肿，硬如石，发热，脉细。症势极重，宜和荣化痰，缓缓取效。", "18213": "脉弦右滑左关且劲，荣阴不足，厥阴气火内动，夹痰上升，凝结少阳之分。颈右发为马刀结核，坚肿，治调不易，拟养荣清肝化坚。", "18214": "少腹痈症有气血凝滞者，有湿热流注小肠者，有寒湿郁结而成者。恙起去夏，少腹梗硬，攻冲作痛。少腹乃广肠部位，肝脉游行之所，肝气拂郁，寒邪乘之，肠胃之气火失利，血随气阻，日久正虚邪凝愈甚。自冬及春，愈形高肿，色红而软，内脓已成，定须外溃。然肠膜受伤，恐粪秽并出，且饮食少进，溲出便闭，内热舌干，脉数，阴伤热郁，倘大脓后胃气不苏，元气不续，深为可虑。若论疡科治法，当补托毒之剂，然虚不受补，清则碍脾，治当舍外而从内。议调胃育阴，阴充便自通，胃和而食自进矣！", "18215": "肠痈外溃，已得微脓，且秽从孔出，浊气外泄，大非所宜，脉象难和，食难渐进，惟虑正气与浊气并出，有上下交脱之虑。急当原方加白芍、参须、熟地。", "18216": "肠痈溃后，脓少气多，肿平一半，脉静身凉，一夜神安熟寐，是属佳兆。黎明之际，外患复增，肿痛，卯时气虚滞于大肠，邪正交攻肠膜，损伤恐难完固。当阴阳并补，兼以护膜，保无更变乃佳。", "18217": "肠痈一年，内膜已伤，形衰脉弱，难治之证。", "18218": "脉象两关细弦而右兼涩，脾有湿痰，肝气大旺，荣卫不利，以致胸腹不舒，腰髀作痛，不能转侧，左肋痰注成漏，间日必服通利之剂，而胸腹顿舒。然取快一时，恐伤胃气，宜和荣卫化痰，兼平肝木。", "18219": "木旺水亏，脾多痰湿，肝风晕厥之疾数年，去冬渐至卧床不起，肝肾血液俱疲。春分后木挟相火用事，湿痰随风火之气充斥三焦，眩晕发热，遍体作痛。疑以旧恙复萌，讵知模骨之旁结为痈毒，约半月有余，是穴乃肝经部位火湿凝聚络中所致，肝热最易上升，湿火熏蒸胃腑，始则发热谵语，后渐热退神安。乃湿热之邪归并下焦，是外患之见，端非旧恙之复萌也。现已成脓半月，未得更衣，齿干苔燥，阴伤而湿火不化。症虽属外，而药饵尤当治内。幸脉冲和而关微弦象，似可无虞。拟用甘寒育阴，兼和中润下之治。", "18220": "背俞痰注痛，脓从肋缝而出，难以速愈，兼之发热面浮，胸腹饱胀，泄泻，脉滑数，痰湿滞脾症，非轻候，当先其内。", "18221": "玉茎者，即宗筋也，乃肾脏之主。又十二经络之总会马口，端属手少阴心经。肾脏阴虚火郁，心肝二脏之火复会于此。始时茎头马口痒碎，渐生坚肉，业已年余。今夏破溃翻花，出数次，火郁日久，必致外越，血得热而妄行。经云：实火可泻，虚火可补。且龙雷之火不宜直折，脉细数，阴分大伤，急当峻补真阴，兼介类潜阳之法。俾龙雷之火得以归窟，而外患方保无虞。", "18222": "脱囊黑腐，温邪内逼，哕恶泄泻，脉细，舌白，高年重症，慎防呃脱，先为和中止泄。", "18223": "伏兔痈漫肿内硬，已延两月，发热口干，脉虚数，宜养温通经络。", "18224": "脉来左部细弦，右部沉涩，荣血不足，肝气不强，脾气不利，气血与汁沫凝结肠外，结为肠覃，状如怀子。幸月事仍以时来，法宜养荣，兼流气化凝治之。", "18225": "鹤膝风症，前贤以足三阴亏损，风寒湿三气袭于经隧，其治皆以辛温开发，宣通经络。予谓又有不然。若肝肾阴亏，夹湿热者，岂可以辛温例治，如的系三气杂成，宗右法。又有湿痹一症，与鹤膝风相似，不可不明辨也。痹则两膝肿痛，或足踝不肿，虽三月五月之久而腿肉不消，筋脉不拘，鹤膝则二月后大肉枯细，屈不能伸，以此为辨。而治法亦殊。痹症属实，鹤膝夹虚，有单有双，如肝肾阴亏，阳明湿热下注，膝肿热痛。若进辛温，是助其热，亏其阴，必致肿溃为败症。始宜通络利湿，继以养阴清络。若初起肿痛，按之不热，虽寒热者以万灵丹汗之，用独活渗湿汤、防己桂枝汤。日久腿足枯细者，古之大防风汤、胜骏丸、三痹汤等方选用。脉见细数，虽风寒湿之症，过饵温热，恐湿寒化热，亦致酿脓。凭脉用药，认症分湿与热，最为的当。至外治者诸方，详载于后。", "18226": "麻风古称疠风。疠者，荣气热，脏气不清，故使鼻柱坏而色败，肌肤疡腐，风寒客络脉而不去，名曰疠风。方书俱以风药混治，又无先后之分，并有蕲蛇、虎骨、山甲走窜，蜈蚣温而有毒，服之未有不焮发者。予阅历多多，是症风湿、湿毒、毒疠诸种，有肌表经络之殊。肺司皮毛，胃主肌肉，肺虚则腠理不密，胃气薄则肌肉疏豁，易于触受，或暴露阴湿晦雾，或坐卧湿地，气血滞而不行。初起一点麻木，不知痛痒，毛窍闭塞，汗孔不透，渐次延及遍身，斑如云片，微微扛起，或白或红。然在上者多风，风为阳邪，阳从上受，白而红者风兼热也。在下多湿，湿为阴邪，从下袭红而扛者，湿兼热也。毒疠则由口鼻吸入，阳明独受其邪，血壅热蒸，初起身面疙瘩成块，扛起日久，脚指常起疱，鼻柱坏，节脱气移，肌肤疡腐。始时均宜汗解，开通腠理，用万灵丹汗之。风胜者消风散、蒺藜丸，湿胜者苦参丸、渗湿汤。毒甚者双解散、通圣散、羚羊角散、解毒汤俱可选用。以上皆发于肌表。肺胃受病居多，若在经络则四肢指节作麻，拘掣肉削，日久足破掌穿，上部面颊麻木，口㖞，目泪眼翻，皆风湿入于经络之见证。初起亦宜汗解，次以蒺藜丸、苦参丸、消风散、利湿汤、通经汤选用，忌辛辣炙煿酒醋等物，避风雨，戒房帏。十中犹可保全六七，病者勿以初起而忽诸。", "18227": "羚羊角散治肺胃吸受毒疠，斑红作肿，目赤泪多，四肢筋脉作痛，体虚者宜之。", "18228": "育阴化疠汤治阴虚湿热，毒疠蒸于阳明，斑红肿，脉虚数，不胜攻表者。", "18229": "补肺清金饮（自制）治鸡胸龟背，脉虚数，身热少食者。", "18230": "龟背乃先天肾亏，冷风入脊，或痰饮攻注，或闪挫折伤，或肾肝虚热，婴儿脊骨柔脆，强坐太早，皆能致之。背之中行属于督脉，旁开则足太阳膀胱，与肾为表里。腰为肾之外廓，肾脏亏虚，膀胱之府焉能自足。督脉为阳脉之海，其为病也，腰似折，髀不可以曲，督脉与膀胱之经皆取道于脊，一著风寒湿邪，则经气不行，腰脊板强，渐至脊庀成为龟背庀。于脊之第三椎者，肺脏受病已评于前，庀于第五椎以下者，厥阴肝经受病，十椎十一椎者，属太阴脾经，十二椎以下者，足少阴肾。其在肝者，脊背强痛，牵引胁肋，肝脉布于两胁也。疏肝流气饮。若兼咳嗽气粗，必兼治肺，在脾经者始悠悠腹痛，始所不觉，三日五日一作，三五月后腰背渐强，脊渐凸，行则伛偻，温脾饮主之。亦有腹不痛者，和脾通络散。在肾者，腰脊强痛，痛引股腿，日久精血衰夺，筋骨不荣，两足瘫软，独活汤、安肾丸主之。若痰饮攻注，兼于经隧而脊凸者，久之必发陈痰，脊两旁作肿，或串腰腿，漫肿不痛，脉象双弦，或兼缓滑，二陈竹茹汤。虚羸食少发热者，六君子汤合何首乌鳖甲煎。若肝肾虚热，阴精被耗，骨枯髓减，宜以地黄汤合二至丸。闪挫折伤，必瘀血凝滞经络，当活血通经络。但此症治之贵早，用药得宜，犹可保全，若成痰外溃，十无一愈。今之治者见脊庀腰背作强，总属虚寒，不分何脏，不究所因，一概温补。邪留不去，痰湿不行，变成残废，枉致夭亡者多多矣。有嗜欲伤肾之人，精衰血惫，腰痛脊庀者，非温补三阴不可。然宜辨阴中水亏、火亏，盖为水脏，在卦为坎，而真阳寓焉。水亏者，补元煎、左归丸之类，火亏者，归肾丸、赞化血余丹之类。填精养血，俾精来生气，气来生阴，精血充旺，庶无痿废之虞。", "18231": "导痰汤治湿痰攻注，背俞脊庀作痛，脉小滑者。", "18232": "脊曳酸痛，时时遗泄，督脉交亏也。", "18233": "扬州吴申锡，先天本弱，又不谨守，梦泄神虚，腿酸腰痛，肢软怔忡，丹田如降精之状，每泄后则丹田疼痛，四肢头项，摇动不宁，督脉常热，先据来字病源，订一清督养肝之方。", "18234": "复来诊脉，六脉软弱如游丝，订丸方。", "18235": "扬州汪焕臣，间日不寐，怔忡耳鸣，粪后便血紫色，小便多秘不等，大便或溏或泄，饮食多少不等，上四部脉软弱，两尺水火俱衰。脉诀云：软而弱者。湿家里恙。乃寒湿凝于血分，徒服养神安心之品，何益哉。", "18236": "泰兴潘有成，阴𤻊卵核之症，硬筋寸许，小便茎中痛，频频解带白浊，小腹胀坠。据脉肾肝两部弦数，必因已前阳痿时，服热药过多，阳虽举而有此病，后又服凉药，以致筋缩，皆做成之病也。", "18237": "梁垛场胡安明，咳嗽声哑，寒热往来，吐白沫，脐腹痛，小便赤，大便黄，去年十一月起，囟会不仁，本年八月来诊，按脉右尺寸不足，关滑大，左三部软数。据此乃脾胃有留滞之象，当先理之。", "18238": "弦象无矣，数尚有之，咳减卧安，但热耳，囟会已仁，督脉热不退。", "18239": "症随药减，可喜，但督脉热不除为虑。", "18240": "左手脉好，右关复数大，症见肚疼，寒热仍有，大便溏，日一次，小便红黄，脉大好些，症亦减，未全清，但体更弱。", "18241": "按咳嗽生痰，乃因痰致嗽，痰去嗽止，病责在脾，内热腰痛，不耐久坐，病责在肾，所以初诊即用理脾药，而腹痛减，再服而止。今脾胃脉虽和，而肾脉尚不足之甚，拟晚用资生丸，早服大造丸，自有后效。", "18242": "泰兴李福周，余脉俱好，惟肾脉独大，乃火居水位，为反常之病，所以梦遗多年。近今不梦亦遗，则为精滑矣。", "18243": "徽州吴希鲁，痹痛将十年矣，大筋短软拘挛，难于伸屈，咳噎牵引俱痛，症乃风寒湿三气杂至，相合而成，为时已久，不能解散，只可养血荣筋，徐徐调治。但此治法，见效纡缓，不能一时见功，脉肝肺劲急。", "18244": "六合王元昭，六阴脉左关尺更觉沉迟，右三部稍好。据症上年心事不遂，气恼皆有，继之患疟，疟虽止，而腹左成疟母未消，怔忡。近症督脉常冷，牵及心胸四肢，非大温补不效。", "18245": "八味加千年健。服前药诸症稍减，督脉知暖，仍怔忡作胀。", "18246": "扬州张名眉，痰饮十余年，每二三月，或四五月一发，发则人事糊涂，论脉沉小无力，乃水衰火盛，肾气不足，", "18247": "诊脉六部皆弱，而两寸关兼涩，是中宫之瘀滞使然，治法以和气化瘀为主。", "18248": "得食即吐知为火，停久而来却是寒，久病胃虚因不纳，或缘气逆与停痰，食填胃口多生呕，新谷如何得下关，欲辨热寒虚实候，大微迟数脉中参。今两寸关涩而弱，乃胃虚而有瘀故，治法不敢急攻，徐则可知。", "18249": "又诊，涩脉少退，瘀滞稍行，胸膈之胀达，小便酱色，紫黑之物尚未下净。", "18250": "又诊，右涩脉全退，大解已见黑色，初食上焦仍胀，吐一口则愈，胃冷，身亦恶寒，不知饥饿。", "18251": "又诊，六脉虚而迟。凡饮食入胃，必胀而吐，吐出之物极冷，小腹亦胀，据此仍属虚寒，前方服之。瘀虽下而未尽，今天气寒，背心怕冷而胀。", "18252": "天宁州贾凤来，血症五日一次，计患病五十五日，吐血十一次，其来也，先三日左胁作胀，至期则夹窠皆胀。发申酉戌三时，余诊其脉，左关弦数而结滞，问五十余日，曾发寒热否，曰：第一次有寒热，一吐而解。予曰：此外感邪热，客于少阳，留于募原，邪热与卫气相遇，夹血上行，故五日一次，如疟之应期至也，以血症药治之，故不应手。乃用小柴胡汤去半夏。", "18253": "朱姓，水邪射肺，喘急不得卧，前医投以苏子降气罔效，投麦冬、五味、沙参增剧，盖伊等初诊，以为肺邪有余。及不效，又见汗多，脉沉小，则认而为虚议补。不知汗多，乃因肺窍不利，阳不卫外，其沉小，正水饮之脉，乃用。", "18254": "一服而卧，调理半月全安，盖诸人为脉所误，而予之认定不疑者。亦即在右部寸脉也。", "18255": "天场岔港赵姓妇人，年五十余，因悲伤之后，头脑拘紧，耳中蝉鸣，不闻人声，其鸣高下，大小不齐，每一大鸣，则从脑后督脉经而起。病于乙酉八月起，至丙戌三月就诊。从前服过芎、芷、细辛、菖蒲、橘、半、麝香不效。右关微弦，尚未大败，左关虚微如毛。审是下焦真阴大亏，火无所恋，以至上炎，因用归、芍、夏枯草、龟板、地黄以养阴，山萸、五味、女贞以收敛肝气，磁石、朱砂、吸心火以下归于肾，一二服而头目已清，越半月余而症减八九，应对如故矣。乃照所服丸方，斟酌丸药，令其回籍调理。", "18256": "乙酉八月，应扬州西山林宅之招，病人号孝思，系时邪已十三日，初起发表，即投芩、连、栀、粉，继以石膏，以致元府外闭，表邪内陷，身热足痛，舌干如锅焦，舌强不圆，胸前至下午即胀不可忍，脉象左手三部皆洪弦而数，右三部亦然。但洪大之中，有结滞紧涩之状，乃为前大剂石膏所逼遏也。附录方案，足痛，肌肤燥，微喘，表未解也；舌枯口干，胃为心肺之征，邪热内陷也；胸满胀，痰滞结气不清，阳明之里症也。三者以存津液为急。经云：开腠理则津液通。解表以提出内陷之邪，尤为急中之急。又恐转手不及，兼用前人充拓胃阴之说，尤为清痰导气，方用。", "18257": "钱朴斋，失血呕吐，服甘寒之药而效，月余复吐，诊脉右寸洪滑，余俱沉弦，所食者少，而所吐者多，症属有寒有热。初用旋覆代赭汤加竹沥不效。继用二陈加木香、沉香不效。汤饮不留，半月遍身皆冷，六脉沉陷，夜半汗出欲脱，细思寒痰痼结中下二焦，非辛温不通，因用", "18258": "吴立夫，贫人也。患时邪四五日，寸关皆沉，手足逆冷，舌堆厚胎，腹大而痛，起卧不宁，虽诊脉时，片刻亦不自持，而人事甚清，乃阴燥也。以达原饮去芩，加桂枝、炮姜，一服而脉出肢温，三服而脉大。始复发热，待其壮热，复用小柴胡全方，一服而平。询其初起之时，前医已用凉剂，症乃因药制成，时邪瘟疫之中，本无阴症也。", "18259": "仁和布伙妹姓陈，寡居，夏日患刚痓，头足反张，口噤不语，身凉无汗，脉沉，其口当未噤时，曾言身痛异常，至此刻并无声音，只辗转床第而已。因用仲景葛根汤古方治之。一服能语言，次服汗出脉出。仲景之法，应如桴鼓，而世人每忽之。", "18260": "仪征南门外金月之，其人素患淋症，因小便不通，起卧辗转。数日后，小便全闭，间有涓滴微通，即周身寒战，四肢逆冷，六脉皆伏，诸医皆谓体质素虚，兼主膀胱不化之说，连投补中益气汤，人参加至七钱。予甫到榻前诊脉，后即问其人曰：胸膈饱闷乎。曰然。因遍告其亲友曰：症系厥阴少阴伏寒，投以补剂，寒未去而膈先满，三焦皆闭矣，若不急于温散，兼用消导，将来或为结胸，或为二痓，至于疝气囊痈，尚其祸之小者也。方用肉桂、元胡、山查、枳壳、青皮、陈皮、通草、泽泻。诸医聚讼，延至初八日深晚，同道中有起而置辨者曰：因寒，何以遇小便微通，而病即来，两症似不连贯，我等均主虚淋。予应之曰：《内经》论厥，皆主于肝。又曰：肝主疏泄，肾主闭藏。今小便微通，即便发厥，乃肝家伏邪，因疏泄而触动，与卫气相争，微汗而解，与阴之疟，同一理也。晚始进前药，至二鼓，小便微通，稍觉寒厥，至四鼓，小便不通，而厥去矣。但因向来出汗过多，正气虚弱，而数日前，参耆叠进，壅塞胃口，舌色深黄，此时攻补两难，乃用十味温胆汤去五味子，加郁金、元胡。左胁坚硬始化，而肾囊红肿，延及至茎。予初切嘱外科，只宜调养胃气为主。", "18261": "周妇人，产后月余，感寒，头痛身痛皆备，投以羌、独、芎、苏，三服。除前症不解，反增呕吐，呃逆，错语神昏。细审之曰：太阳病，服太阳药不效，必有故。询床侧老妪曰：生养时去血过多乎？曰然。连日尚有血下乎？曰：从前已净，连日复下些许。因立案云：汗因血夺，寒气无从泄越。非养血，则脉之涩弱者不活；非辛温，则血之凝泣者不流。因用羌、苏、陈、半、干姜、当归，一服，汗如注而解。", "18262": "李书彝令正，患小便不通，投入正散不效，询知头痛鼻塞，因用前胡、防风、半夏、细辛之剂不效。午刻复召，诊其脉，左寸关沉弦而细，右寸微洪，及验舌，色白如粉刺，始知厥阴家寒与气凝，而昨昔之制军，尚欠斟酌也。方用干姜、吴萸、桂枝、细辛、郁金、元胡、通草、麝香、沉香。虽夜间稍通，而腹大气逆，呕吐恶心，辗转烦躁，举室惊慌。次早诊其脉，右寸浮洪而数，左寸关沉细如无，因以左金丸服之。呕止，因连进二钱四分，至晚通利如注。", "18263": "吴，黄疸症，初服茵陈、苍术、赤苓、木通不效，改服茵陈栀子六黄汤，大小便通，目珠不变。询其自病以来无汗，因照原方去大黄，用茵陈、香薷、白术、黄芩、山栀、木通，加葱白二寸，桂枝六分。三服而目珠净白，黄色大减。此症始于风寒袭于肌表，初时经手之人，未曾解表，以致邪热留于经脉，故得桂枝、葱白，荣卫一和即解。", "18264": "刑部左侍郎钱为城公，下消症医案。肾虚不摄，自应温扶，但现在六脉浮洪，毕竟阳旺于阴，恐精耗肉削，渐成损弱，右寸关皆空软，左尺犹觉衰微，司气之官，未免失守，以致疏泄多而闭藏少，亦气化之使然，以益气养阴，兼静摄为主。", "18265": "颜丰濯之媳，经闭六十余日，虑其有娠，以烧酒定粉（即铅粉）下之。其人素有痰症，多年不发，自服酒粉后，便觉腹中微痛，痛渐甚。三日后，夜间忽然晕厥，牙关紧闭，口有痰涎，手足搐搦。三更后，求救于予，令其觅苏合香丸投之。讵料齿关不开，咽喉亦闭，主人云：明知其不可奉，烦卜其脉之迟早耳。乃至榻前，手屈而强，已难于诊脉，而诊脉三至，筋一惕，脉五至，而筋或四五惕，或五六惕。予乘其不惕之时，参知脉状，浮洪滑数，正知此厥也，非绝也。气达则生，气闭则死，若不加人力，则待毙而已。出至前厅，语主人曰：此症已预辨送终，可容我一医治否。主云：其如不能下咽？乃笑应之曰：我有下咽之药。乃用牛黄一分，沉香二分，黄连一钱，猪牙皂角、青黛各三分，干姜五分，乃以小匙投之入口，即大呛，后下咽数口。复以皂角未投之，连嚏数声，哼声继至。主人谓予，有回生之功？予曰：未也。铅粉之毒未除，人事未醒，非用大下之法，必将复变。乃进小承气汤加胆星、竹沥之药，人事稍明，自言腹中大痛，连进滚痰丸三日，下白物如油灰者，而人事大清矣。时有兴化之行，乃留以归、芍、枣、志、曲、谷、姜、贝之方，调理数日而安。", "18266": "蒋姓妇人，产后污浊不行，又因气郁相触，脐上人骨下，大如两拳，按之坚如石，四围充满，较之十月怀胎者而倍大。盖怀孕只腹大，而胸口不高。诸医以调气活血之药，投之不效。因用回生丹四丸，一丸分作三服，当其肺气喘逆，则配以疏肺之药，肝气冲逆，则兼用伐肝之品。三日后，胸前之坚者软，少腹及两胁之膨者亦消。其人始能起坐，犹以似八月怀胎之腹，忽添心慌意乱，汗出脉软，恶露少下，而大便无度，只得暂停攻伐，以八珍加沉香、木香固其正。三五日后，神气稍旺，又复以通逐而小其剂，初时只有浊物从二便出，至此始得浊气流通，渐消如三月之腹。又忽添少腹虚痛，小便不禁，竟似胞门大开之象，非峻补无以收功，又恐腹中余剩之坚，得补而固，甚为棘手。因与家传胎产金丹十丸赠之，令其每日服半丸，以黄丝绵汤送之。越半月，而神旺腹消，溲便如常矣。", "18267": "治产后转脬，小便不禁，精神倦怠，不思饮食，腹痛胀，寸关脉浮而芤，症系小肠痈。", "18268": "治寒热失血，头眩胁胀，心虚气喘，脉象细涩，方拟滋阴保肺汤。", "18269": "治积寒腹冷，因肝气郁结，脉象浮数，再延成膈。", "18270": "嘉庆丁巳，时年三十三岁，复贸汉镇，获遇超凡黄公老师，乃西昌喻嘉言之小门生，受业于舒驰远者也，幸得拜门于楚北武昌客邸。即示予曰：吾今者老矣，年已七十矣，久因劳攘风尘，日为人役，而未传于徒，观子颖敏，可当吾意。乃将数十年亲承于嘉言、驰远口授之秘旨，遂一一以传于慧。晨夕问难，分辨六经，阴阳表里，寒热虚实，条分缕晰，金针并度，罄传无隐，至详且尽。我师弟二人，依依三载，拜别回川。屏去营谋，志在济世，杜门乐饥，穷究医学。购求《黄帝内经》、《灵枢》、《素问》、《难经》、《脉诀》、元始、《纲目》、张刘李朱四大家之秘诀、喻氏《医门法律》、《尚论篇》、《寓意草》及《御纂金鉴》、《薛氏医案》、赵氏《医贯》、《冯氏锦囊》、《诊家正眼》、《密斋集解》、《龙宫方》、《石室秘录》等书，昼夜苦读，殚心悉虑，寝食研求。其中五行生克制化，一一辨明，字字领悟，于凡要妙疑关，会族肯綮，无不迎刃而解。嘻！有莫之为而为者，我今果知医耶？然虽发脱将尽，觉肌肤光泽，体健身轻，心中喜不尽言，言不尽意。于斯时也，城乡远近，府县厅州，送往迎来，医治咳嗽、吐痰、咳血、吐血、咯血、衄血、遗精、痨瘵、虚劳、痨虫，愈者十之八九。每治一人，即立一案，至今活人，已盈千累万。内选病之奇、医之良易易者百十案，附于熟习各条之下，商诸高明。佥曰：宜亟梓行世。慧何人斯？而敢妄为著书立说，以取画蛇添足之诮。况生于千百年成法大备之后，即有所说，又岂能出古人范围乎？恨禄山兵燹，真书淹没，后人以讹传讹，世多不分阴阳，不辨虚实，用方用药，鲜能中病。敢将数十年寤寐诚求，心得仲景、嘉言之蕴奥，立斋、养葵之秘旨，吾师超凡之心法，古今诸家之议论，乃为之畅发其义，针砭诸家，启迪后贤，俾不至有虚虚实实之害贻误后世。慧故于是编之所以作，要诀之所以明，足快偿吾生平之大愿也。知我罪我，又何计焉？是为序。", "18271": "纤毫脉息辨求明，灵素诸书伴短檠。", "18272": "昔长沙公教人以望、闻、问、切四法，妙哉其神矣。然庸工无传，遂谓此非长沙之圣不能知，何其所见之不广也？不知具有明征，显而易见。望者，望其人之颜面气色，以察形体之劳瘁，如青属肝病，赤属心病，白属肺病，黄属脾病，黑属肾病也；闻者，闻其语言声息，以审内气之盛衰；复问其病起于何时，得于何因，所见之证属于何经，于是再问其平日有何旧病与否，其本气宜寒宜热，则病之六经、阴阳、表里、寒热、虚实确有所据；而后切其脉以验证，不过再加详慎之意，并非尽得其证于脉息之中，倘脉证不符，犹必舍脉而从证，可见重在证，不重在脉，故以切为独后。彼不谙仲景之法，藉脉理之说而欺于世，至于望、闻、问三字，不得其传，则病之六经、表里、阴阳、寒热、虚实，懵然不识，求其不杀人者，几希矣。", "18273": "切脉须知", "18274": "余读雷真君曰：脉诀，《内经》已畅言矣，王叔和发明，沈微垣规正，余不可不一一论之。脉诀大约言愈多则旨愈晦，吾独尚简要以切脉，不必纷纷于七表八里也。切脉之最要者在浮沉，其次则迟数，其次则大小，又其次则虚实，又其次则滑涩而已。知此十脉，则凡人之病，不能出其范围，至于死脉，尤易观也，不过鱼虾之游、禽鸟之喙、屋漏、弹石、劈索、水流之异也。知十法之常，即可知六法之变，又何难知人之病哉？《灵枢》之形容脉象，万不可以为法。仲景曰：脉诀原不必多，多则反晦。真君之妙论，至简至要，可为万世切脉之定法。", "18275": "医以浮、沉、迟、数等脉，分别病之表、里、寒、热、虚、实，非以某脉专主某病，亦非以某病必无某脉。经云：阳病得阴脉者死，阴病得阳脉者生，是阴病有阳脉，阳病有阴脉也。又中风之脉，浮迟者吉，大数者危，是中风有浮迟，亦有大数也；吐衄之脉，洪大者危，沉小者吉，是吐衄有洪大，亦有沉小也。凡患病者，必先将病之始末细说与医，以脉证病，了然无疑，则药无不效也。今多有自隐病因，以脉困医，令其猜病，偶合则称为神手，不合则薄为庸才，不服其药，是以明医反不见信，良可慨也。彼不知古人治病，未有外望、闻、问三法，而独以切脉神其治者。东坡先生云：吾求愈病而已，岂以困医为事哉？且人生平有六阳脉者、六阴脉者，有左右偏盛者，有反关脉者，凡有疾病，难以合诊。又饥饱、房劳、惊醉之后，脉难作准。又寒热之病，寒时则脉衰，热时则脉盛，不可不辨。以上数端，医者临证时，以望色、闻声、问因审之，庶可以得病情而手到春生矣。", "18276": "余考《黄帝内经》经络图，以六经画成六象，注明某部、某脉、某经、某病主用何药，宜用何方，乃一定而不可易之法。此愚自悟而自制，实六经之至理，而曩哲所未发明者，余特表而出之，使业医者无分智愚，开卷了如指掌，不致叹于蒙混焉。太阳者，膀胱也，一名尿脬。阳明者，胃也，一名肚子。少阳者，胆也，一名青肠。太阳、阳明、少阳，此三阳也。太阴者，脾也，一名镰贴。少阴者，两肾也，一名腰子，是人身中一太极。厥阴者，肝也，为藏血之脏。太阴、少阴、厥阴，此三阴也。三阴、三阳合而为六经。岐伯曰：此人之所以参天地而应阴阳，不可不知。足太阳外合于清水，内属于膀胱，津液藏焉，气化则能出矣，为州都之官。足阳明外合于海，内属于胃，为水谷之海，职司受纳收藏之官。足少阳外合于渭水，内属于胆，胆善决断，为中正之官。足太阴外合于湖，内属于脾，腐熟水谷，为仓廪之官。足少阴外合于汝水，内属于两肾，主藏精与志，为作强之官。足厥阴外合于渑水，内属于肝，肝能谋虑，为将军之官。手太阳外合于淮水，内属于小肠，化物出焉，为受盛之官。手阳明外合于江水，内属于大肠，变化出焉，为传道之官。手少阳外合于漯水，内属于三焦，水道出焉，为决渎之官。手太阴外合于河水，内属于肺，治节出焉，为相傅之官。手少阴外合于济水，内属于心，神明出焉，为君主之官。手厥阴外合于漳水，内属于心包络，喜乐出焉，为臣使之官。故曰：主明则下安，主不明则十二官危。", "18277": "又一岁之中，自大寒至惊蛰，厥阴风木主气；自春分至立夏，少阴君火主气；自小满至小暑，少阳相火主气；自大暑至白露，太阴湿土主气；自秋分至立冬，阳明燥金主气；自小雪至小寒，太阳寒水主气。夫人身中之六经合天之六气，而经脉应地之经水，又合于天之六气而内属于脏腑。每一岁周天三百六十，而分四时之风、寒、暑、湿、燥、火，人感之而受病，其中轻重各有所因，明者知之，难为昧者道也。", "18278": "高曰：医治之源，肇自岐轩，而《内经》之书乃三坟之一，六经方药至仲景而始备，特著《杂病论》十六卷，起死回生，故为医中之圣。由汉至唐，苍苍生民，咸赖福庇。不幸后遭禄山兵燹，其书湮没不传，后人无有获见者，以至诸家各逞臆说，《局方》大行，鲜能分辨六经，按法治病。愚髫年习举业，常聆家庭之训诲，流览曩哲之名言，每见无传者，多执陈方，既无可凭之理，又乏通变之才，其贻害也，良非浅鲜。今是书将六经各绘一图，著明某经系属某病，某病宜用某药，诚欲学者不迷干所往也。由斯门者能信心而熟读之，则阴阳表里、寒热虚实、生克制化之理自得。又潜心考究喻氏、舒氏、薛氏、赵氏等书而会通之，则慧心日开，聪明日发，视病如镜照物，无一脉不贯通，无一理不融澈，毫发不紊，则信手拈来，头头是道，见一人救一人，到一方救一方，则功德无量。文正公云：不为良相，当为良医。又曰：医道通仙道，济世活人，此之谓也。", "18279": "太学黄子一清，余同庚也。其妻初患四肢烦疼，类中风而实非风，医家不识其证，谬用消风活血之剂。余遇，力止之，曰：不可，此太阴脾经溢饮之证，我见世医误作风治，而酿成痿废、鹤膝者恒多。不听，任他医治之，果成鹤膝，枯瘦如柴，形如鹄立，方求诊治。按之六脉沉迟而伏，余曰：风药误矣，病尚可治，但两脚终身不能履地。乃与理脾涤饮加川牛膝、虎胫骨、威灵仙，兼服八味地黄丸，后犹享寿十九年。", "18280": "曾医李解元尧宾之孙，里重于表者，其证身壮热而头重痛，又兼腹痛作泄，体重恶寒，起则眩晕。医家妄用发表，兼以分利，数剂而加剧，叫楚烦乱，日夜无宁，举室仓皇无措。予诊其脉浮虚无力，观其证里重于表，即用砂、半、耆、术、姜、附、肉桂、故纸一剂，而头痛即止，身微汗而热俱清。次日，群医请见。予语之曰：习医不得喻嘉言之传，虽皓首穷经，终归无用。此证乃少阴中寒，真阳不得上达，阴邪僭犯至高之处，故头痛如劈，重不可举，兼之腹痛作泄，其里证何等重也。里重于表，法当专主温里，虽有壮热，不可兼表，肆然乱表，非徒无益，而反害之。吾用干姜、附子以回其阳而御其阴，犹恐道远而效不速，故用黄耆以补胸中之阳，白术以助脾中之阳，接引真阳上达，速于置邮，所以一剂而头痛即止。前此各位乱用表药而汗不出，以阳虚不能作汗也。今得是剂则微汗而热解，盖温里则阳回，兼可托表也。群医羞惭而退。于是再投前药，腹痛作泄诸证渐减，但觉腹中发热。李君恐附子太过，予曰：最妙，阴病难于得热，热则阳回，在里之积寒、积滞从兹蒸化易易耳。又数剂而痊愈。", "18281": "门人舒帝锡问曰：昨看一证，脉浮而大，且弦而数，身大热而多汗，口苦，咽干，渴欲饮冷，小便短赤，恶热，腹满，不大便，头昏欲睡，少气而又息高，恐犯少阴经之脱证，不可为也。余曰：少阴病，法当脉沉迟、恶寒，今恶热、脉数，知非少阴。其浮属太阳，大属阳明，弦属少阳。身大热而多汗者，热越也，法宜白虎汤；口苦咽干者，少阳腑证也，宜加黄芩；小便短赤者，太阳腑证也，宜合五苓散去肉桂，加滑石；燥渴饮冷，便闭腹满者，阳明胃实也；头昏欲睡者，热盛神昏也；少气者，热伤气也；息高者，燥结阻塞，胃中浊气上干而喘，非肾气发动，宜合调胃承气汤；因其气弱，加人参。", "18282": "《千金方》云：阳毒汤，治伤寒一二日变成阳毒，或服药吐下后变成阳毒，身重，腰脊背痛，烦闷不安，狂言乱走，或见神鬼，或吐血，下利，其脉浮。", "18283": "土郁夺之，谓下夺之，如中满腹胀，势甚而不能顿除者，非力轻之剂可愈，则用咸寒峻下之剂，以劫夺其势，而使之平，此下夺之义也。愚意夺不止下，如胃亦土也，食塞胃中，下部有脉，上部无脉，法当用烧盐汤探吐法，不吐则死。《内经》所谓高者因而越之，以吐为上夺，而衰其胃土之郁，亦无不可。", "18284": "甜瓜蒂（炒黄）、赤小豆等分为末，熟水调饮，或用酸荠水更佳，量人虚实服之。良久不吐者，口含沙糖一块即吐。吐时须令闭目，紧束肚皮。若吐不止者，葱白汤解之。亡血虚家禁用。尺脉绝者，不宜服，恐损胃气。若胸中窒塞闷乱，以物探吐之，得吐即止。如探不出，方以此散吐之。", "18285": "伤寒如桂枝汤证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲喉不得息者，胸中有寒也，宜当吐之。如头额两侧痛者，令病人噙水一口，以此散一字吹入鼻中，立效。", "18286": "《十剂》曰：燥可去湿。桑白皮、赤小豆之属是也。赤豆、瓜蒂并能行水湿，痰涎头痛，胸满寒热，脉紧不大者，并宜此散吐之。", "18287": "本方除赤小豆名独圣散，治太阳中暑，身重痛而脉微弱。", "18288": "舒驰远曰：桂枝汤中用芍药以内护于营，而麻黄汤中用桂枝以外导于卫，此阴阳互根之妙者也。盖卫行脉外，营行脉中，营邪出表，必假道于卫，用麻黄发出营分之邪，用桂枝接引卫外。但用麻黄汤者，当察其人本气无亏乃可径用。若元阴不足，方中宜加归、地；真阳素虚，宜加附子；肺胃素有蓄热者，宜加石膏。何以见真阳素虚？其人平日恶寒喜热，爱服椒、姜；若其人不服辛燥，喜服寒凉生冷之物者，自必阴亏火旺也。", "18289": "又曰：伤寒有传经之邪，化热则传经，未化则不传。脉静者，邪未热也，故不传。然不但一日不传，虽数日而终不传也。若见欲吐，烦躁脉数，则寒邪化热之征，故为传也。虽一日太阳，二日阳明，三日少阳，然必以脉凭之。浮属太阳，大属阳明，弦属少阳。然不定限日期，必察其所见之证属于何经，所凭之脉与何证相合否，倘病不合脉，尤必舍脉而从证，看传至何经，又必转见何经之证，不然何所征验？故仲景复申之曰：伤寒二三日，阳明少阳证不见者，为不传也。总之六经皆各自有定法，参其伍而错其综，自无往而有不得之者矣。", "18290": "喻嘉言曰：天地郁蒸，得雨则和；人身烦躁，得汗则解。大青龙证，为太阳无汗而设，与麻黄汤证何异？因有烦躁一证兼见，则非此法不能解。盖风为烦，寒为躁，故用之发汗，以除其烦躁也。究竟本方，原无汗者取微似汗，若有汗者之躁与烦，其不藉汗解甚明，加以恶风，脉微弱，是则少阴亡阳之证，与此汤不相似也，误服此汤，而速之亡阳耶。仲景更立真武汤以救其误，特为大青龙对峙。见一不汗出之烦躁，兴云致雨，为阳亢者设；一则救汗不收之烦躁，燠土制水，为阴盛者设。烦躁一证，阴阳互关，不可不辨及毫厘之仔细也。", "18291": "又曰：或问青龙自为一队，即白虎且剔出另峙其后，然则脉证之纵横者，何与青龙事耶？答曰：伤寒中多有忽然自汗，突尔亡阳之候，虽不犯青龙之药，早已犯青龙之逆矣。盖屈蠖者，龙之所以伏也；纵横者，龙之所以飞也。纵横之脉证不同，刺穴用期门，期门肝木所主，东方青龙之位也，刺其穴者，正所以制其木，而预弭其亡阳之变。故一青龙方中，张大其施，则天行而为霖雨；挟小其制，则鼓浪而奔江海；驯制其性，则逾越女婢之卑柔；刺其经穴，则销弭灵幻于寂若。仲景于其奋鬣升天，万难把捉之时，尚以真武一方坐镇北方之水，俾地气不上，天气不下，所谓其雨其雨，杲杲出日。龙之既升于天者，不得不复返于渊，况未及升腾，可训可抚，顾无法以制伏之耶？此余所以有会于纵横之义也。倘其不然，匪但无与于青龙之事，亦并无与于伤寒之事矣。吾不知仲景制方之时，其为龙乎？其为仲景乎？必有倏焉雷雨满盈，倏焉密云不雨，倏焉波浪奔腾，倏焉天日开朗，以应其生心之经纶者。神哉！青龙汤等方，即拟为九天之龙经焉可矣。", "18292": "喻嘉言曰：发太阳经之汗，即当顾虑阳气，以膀胱主气化故也。发阳明经之汗，即当顾虑阴津，以胃中藏津液故也。所以阳明多有热越之证，胃中津液随热而尽越于外，汗出不止耳。然而阳明证，不论中风、伤寒，脉微、脉实，汗出少而邪将自解，汗出多阴津易至竭绝。业医者可不谨持其柄而用重剂发汗，以竭人之津液也。", "18293": "曾治白以采，患腹痛作泄，愈月不愈，姜、附服过无数。其人禀气素盛，善宴啖肉食，因自恃强壮，病中不节饮食而酿胃实之证，大便转闭，自汗出，昏愦不醒人事，谵语狂乱，心腹胀满，舌苔焦黄，干燥开裂，反通身冰凉，脉微如丝，寸脉更微，殊属可疑。予细察之，见其声音烈烈，扬手掷足，渴欲饮冷，而日夜不寐，参诸腹满等症，则胃实确无疑矣。更察遍身冰冷，厥热亢极，隔阴于外也。脉微者，结热阻结中焦，营气不达于四肢也，正所谓阳极似阴之证。急于大承气汤一剂无效，连服四剂无效。予因忖道，此证原从三阴而来，想有阴邪未尽，观其寸脉，其事著矣。竟于大承气汤中加附子三钱以破其阴，使各行其用，而共成其功。服一剂得大下，寸脉即出，狂反大发。予知其阴已去矣，附子可以不用，单投承气，病势略杀，连服四剂。前后芒硝、大黄各服半斤而安。可见三阴寒证，因有宿食，转属阳明而成结燥者，有如是之可畏也。", "18294": "曾治张天元，患腹胀不大便，来寓求治。诊其脉微而涩，舌润不渴。予告之曰：此里气虚，脱证已具，法当扶阳固肾，醒脾和气，使收藏之本固，则气化归元，而化自行，脾气有权则健运行而升降清，其患当自愈。其家以予言迂也，听医用下，大便暂通，腹胀因减，彼以为有效矣，予知其必死也。次日复闭，腹胀加甚，于是又下，闭胀愈加甚焉。更下之，卒不能通，则气壅而死矣。噫！庸医杀人，恬不知改，顽夫受杀，实可悯也。", "18295": "按：脾脉主缓，证本发黄，若小便利则湿行而黄可免。若大便硬则胃有夙燥，因复转阳明。", "18296": "曾医继唐魏舅氏，善人也，身举孝廉，形体素丰，谦恭仁厚，自谓六十后，多食则胀闷，今年七十有三，目精不慧，近视不明六七年矣，乃一日午膳后，县尊请商公事，时当酷热，过劝绿豆粥一碗，是夜下利数十次，不能起床，起则眩晕。明早诊视，按之六脉沉细而微，其粪内带清水。愚曰：此太少二阴鹜溏之证，而兼陷暑邪也。虽有外邪，不可清解，法当大补中气，扶脾固肾，温经御邪，回阳止泄，方可无虞。乃用耆、术、芡实、怀山各八钱，胡巴、故纸、苡仁、半夏各三钱，炮姜、附、桂各一钱，砂仁、白蔻各七分，连进五剂而利稍减。再进十剂，仍然昏沉。又服十全大补汤十剂，病微退而精神渐爽，饮食亦进，但四肢无力，难于转侧，利微下而卒不止。又与人参养营汤十剂，虽然起床，不能久坐，但见皮肤光泽，身轻易于转侧。又与理脾涤饮十剂，是夜不安，烦闷之甚。愚意日久虽在下利，而未见粪，更见胀闷不安，以此察之，定为热结旁流矣。遂以参耆附子汤加桔梗一钱、大黄二钱，服之不安，又用麸面炒熨，夜半稍安。次早复作更甚，自觉腹中气壅，十分危急。其间予为舅氏调理在五十余日，往返在二百余次，晨夕焦劳，又令前汤再进，炒麦麸再熨。自云目中出火，其心欲落，急令扶起，挣下一物，其状如茄子，不软不硬，良久病去如失，自出中堂，即进饮食言语如常。随即剃头，见须发内长出一层黑发约长数分。公闻之而喜曰：我之病难望保余生耳，今何以病愈而长黑发，目睛复明，竟能视细细字乎？神哉医也！此后之寿而康，皆赖吾甥之力也。赐酒浆脯醢领谢，孔方十万却之。", "18297": "阳脉涩，阳虚也；阴脉弦，阴盛也。阳虚阴盛，当腹中急痛。宜用耆、术、炮姜、附、桂以助阳御阴，小建中汤不中用也，小柴胡汤亦不合理。", "18298": "舒驰远曰：太阴经病，是必腹满而吐，腹痛自利矣，其证属里。阴脉虽浮，亦不宜于发汗。即令外兼太阳表证，惟当以理中为主，内加桂枝，两经合治，此一定之法也。若只据脉浮用桂枝，专顾太阳，不顾太阴，大不合法。", "18299": "汪昂曰：理中汤治伤寒太阴病，自利不渴，寒多而呕，腹痛鹜溏，脉沉无力，或厥冷拘急，或结胸吐蛔，及感寒霍乱。", "18300": "曾治大学士海山周大人六公郎州官桐峰者，患吐痰三十余年，自云少壮时，一年三五发，将发二三日左胁内胀，渐大如米瓜即吐，吐出之痰，状若破絮，形似痈脓，臭不可闻，待三五日，痰尽乃平，每发如是。至今年衰，一月数发，饮食不进，日夜无宁，来寓求诊。右寸关浮大，滑而弦甚，余脉如常。余曰：足下之恙，乃太阴脾经之患，巢囊之痰如蜂儿宿于房中、莲子嵌于蓬内，生长则易，剥落则难，吐尽又积，积满又吐。桐峰曰：先生明若观火，治之将何如？余曰：补正攻邪，方与理脾涤饮，加南星、草蔻温中散结，芫花、草果大破悬饮，更用斩关丸，以刬巢囊，荡涤湿痰，自必有效。彼闻之颜曰：先生良医也。即依其法，煎服二剂而痰活。又服二剂，是晚吞斩关丸五钱，次日乘舆来寓，顿首谢曰：妙哉！先生之药，何其神也？我三十余年之疾，昨晚得先生一剂服之，至二鼓，其痰自大便长驱而下，今早自觉右胁下毫无形迹矣，此后不发，皆君赐也，弟惟每饭不忘耳。", "18301": "曾治北关口王相，患咳嗽吐痰，右胁刺痛，胸膈不开，饮食无味，颜色枯槁，形神俱惫，自谓知医，服药无功，方求余诊。按之右寸关浮滑而紧，余脉如常。余曰：君之恙，乃脾经虚弱，痰饮由胃而旁流入胁，其病名曰悬饮也。法以黄耆以补胸中之阳；白术以助脾中之阳；砂、半醒脾开胃；姜、蔻温中逐饮，宣畅胸膈；芫花、草果搜剔胁缝之痰自愈。果服二剂而效。惟痰仍盛，乃与八味丸补而逐之乃安。", "18302": "病人脉阴阳俱紧，反出汗者，亡阳也，属少阴，法当咽痛而复吐利也。（法当二字疑误。）", "18303": "少阴病，下利脉微，干呕心烦，则为阴寒在下，阳烦在上。法宜姜、附以驱其阴，然必加入尿、胆汁，以制胸中错杂之阳邪，庶姜、附得以下行其用。其脉微续者，阳气已渐复也。暴出者，势必有雀啄、釜沸之象，又必主死也。", "18304": "脉不出者，用通脉四逆汤。", "18305": "通脉四逆汤", "18306": "利止脉不出者，加人参以生其阳而长其阴也。", "18307": "曾治汪少宰妻，腹中急痛，恶寒厥逆，呕吐下利，脉见微涩。予以四逆汤投之无效，其夫明日来寓告曰：昨夜依然作泄无度，然多空坐，醡胀异常，尤可奇者，前阴醡出一物，大如柚子，想是尿脬，老妇尚可生乎？予即踌躇良久，曰：是证不可温其下，以逼迫其阴，当用灸法温其上，以升其阳，而病自愈。用生姜一片，贴头顶中百会穴上，灸艾三壮，其脬自收。仍服四逆汤加黄耆、白术，二剂而愈。", "18308": "嘉言又曰：厥阴篇中次第不一，有纯阳无阴之证；有纯阴无阳之证；有阴阳差多差少之证；有阳进欲愈，阴进未愈之证；复有阴居八九，阳居一二之证。热而发厥，热深厥深，上攻而为喉痹，下攻而便脓血，此纯阳无阴之证也；脉微细欲绝，厥冷，灸之不温，恶寒，大汗，大利，躁不得卧，冷厥关元，此纯阴无阳之证也；厥三日，热亦三日，厥五日，热亦五日，手足厥冷，而热邪在胸，火热在胃，此阴阳差多差少之证也；渴欲饮水，饥欲得食，脉滑而数，手足自温，此阳进欲愈之证也；默默不欲食，呕吐涎沫，腹胀身疼，此阴进未愈之证也；下利清谷，里寒外热，呕吐下利，其脉微弱，复误吐下，面反戴赤，阴居八九，阳居一二之证也。大率阳脉阳证，当用三阳经治法；阴脉阴证，当用三阴经治法。厥阴病见阳为易愈，见阴为难痊。其表里错杂不分，又必先温其里，后攻其表。证见咽喉不利，咳唾脓血，则温法不可用，又宜分解其热，润泽其枯。世医遇厥阴诸证，如涉大洋，茫无边际可测，是以开口动手即错，我今不厌烦复，复阐其奥于厥阴篇末，俾后学奉为指南云。", "18309": "夫先天肾中有阳水，有阴水，有火中之水，有土中之水，有金中之水，有木中之水。阳水者，坎水也，气也。陈希夷论曰：坎以一阳陷于二阴，水气潜行地中，为万物受命根本。盖润液也，气之液也。《月令》于仲秋云杀气浸盛，阳气日衰，水始涸，是水之涸，地之死也；于仲冬云水泉动，是月一阳生，是水之动，地之生也。谓之火中之水，可也；谓之土中之水，可也。阴水者，兑泽也，形也。一阴上彻于二阳之上，以有形之水，普施万物，下降为资生之利泽，在上即可为雨露之水，在下即可为大溪之水。人之饮食入胃，命门之火蒸腐水谷，水谷之气上薰于肺，肺通百脉，水精四布，五经并行，上达皮毛，为汗、为涕、为唾、为津；下濡膀胱，为便、为液。至于血，亦水也，以随相火而行，故其色独红，周而复始，滚滚不竭，在其上则可为天河水，在下则可为长流水，始于西北天门，终于东南地户，正所谓黄河之水天上来，奔流到海不复回，故黄河、海水，皆同色也。金中之水，矿中之水，水银是也。在人身中为骨中之髓，至精至贵，人之宝也。木中水者，巽木入于坎水而上出，其水即木中之脂膏。人身足下有涌泉穴，肩上有肩井穴，此暗水潜行之道。凡津液润布于皮肤之内者，皆井泉水也。夫水有如许之不同，总之归于大海，天地之水，以海为宗，人身中之水，以肾为源，而其所以能昼夜不息者，以其有一元之干气为太极耳。此水中之五行也，明此水火之五行，而土木金可例推矣。", "18310": "易老云：八味丸治脉耗而虚，西北二方之剂也。金弱木盛，水少火亏：或脉鼓指，按之有力，服之亦效，何也？答曰：诸紧为寒，火亏也，为内虚；水少为木胜金弱，故服之亦效。", "18311": "前人之论水火既详，慧再约言而切指之。夫人之始生也，先生肾，肾有两肾，左为阴水，右为阳水，中间是命门之穴，真阳之火居焉。此火，即是人之命根也，火旺则精神强健，火微则精神衰弱，火息则无生矣。心赖命门之火而神明有主，能应事事，肝赖命门之火而能谋虑，胆赖命门之火而能决断，胃赖命门之火而能受纳，脾赖命门之火而能转输，肺赖命门之火而能治节，膻中赖命门之火而能喜乐，大肠赖命门之火而能传导，小肠赖命门之火而能布化，肾赖命门之火而能作强，三焦赖命门之火而能决渎，膀胱赖命门之火而能收藏，此十二官者全藉命门之火以养之也。经曰：劳者温之。八味地黄汤大剂与之是也。而肾中真阴之水亦无一脏不一取资也。肾水生肝木，肝木生心火，心火生胃土，相火生脾土，脾土生肺金，肺金生肾水，生生不已，故能长有天命。心得肾水而神明始涣发也，脾得肾水而精微始化导也，肺得肾水而清肃始下行也，肝胆得肾水而谋虑始决断也，六腑俱赖得肾水而后可分布之也。肾中无水，六味地黄汤丸大剂与之；肝中无水，四物汤中熟地用至一两；心中无水，天王补心丸中生地换熟地；膻中无水归脾汤；脾胃无水六君、四君；肺金无水生脉散，举一而类推之可也。凡人得失荣枯，察色便晓，有诸内者形诸外，不观之帝王之色，龙文凤彩；神仙之色，岳翠山光；荣华之色，珠明玉润；寿耇之色，柏古松苍；贫贱之色，薄削垢腻；疾病夭枉之色，重浊晦滞，枯索垩黧。故五脏各有正色，即以其色之呈于面者分生克，黑有黄色，土克水矣；红有黑色，水克火矣；黄有红色，火生土矣；黑有白色，金生水矣。相生则生，相克则死，克则救生，生则制克，其理一通，方称医杰，不学无术，何知生克？穷究六经，方知用药。即如内伤诸证，脾肾居多，脾虚者宜用参、苓、耆、术、砂、半、姜、蔻等药温醒脾胃，宣畅胸膈，饮食健运，诸病自愈；肾虚者宜用熟地、山茱、附、桂等药，无水者壮水之主，无火者益火之原，肾气收藏，元气自复。或问曰：常见凡人肾中之火，亦无一脏不焚烧也，肾火犯心而烦躁生焉，肾火犯肝而龙雷出焉，肾火犯脾而津液干焉，肾火犯肺而喘嗽病焉，肾火犯于六腑而燥渴枯竭之证，种种变生，然则治之之法奈何？余曰：明乎哉问也。夫肾中之真火起者，由于肾中之真水竭也，宜用六味地黄丸料加麦冬、五味，大剂煎饮，以大补肾中之水，水盛而火自潜藏，何病不愈？粗工不达此理，误用栀、柏、芩、连，杀人多矣。故经曰：知其要者，一言而终也。此论水火之妙用，实有至理存焉，学者苟能参悟而会通之，医不称神，吾未之能信也。", "18312": "补阴丸中，以黄柏、知母、天、麦门冬为佐，盖黄柏苦寒泻水，天冬寒冷损胃，服之者，不惟不能补水，而且有损于肾，故滋阴降火者，乃谓滋其阴而火自降，当串讲不必降火也。然二尺脉各有阴阳水火，互相生化，当于二脏中各分阴阳虚实，求其所属而平之。若左尺脉虚弱而细数者，是左肾之真阴不足也，用六味丸；右尺脉迟软，或沉细而数欲绝者，是命门之相火不足也，用八味丸。至于两尺微弱，是阴阳俱虚，用十补丸。治肾经虚冷，足寒膝软，即八味丸加五味子、嫩鹿茸。此皆滋其先天之化源，实万世无穷之利，世医之补阴者，多用黄柏、知母反戕脾胃，多致不起，不能无遗憾于世。予特表而出之，以广前人之未详，使病家医者，加意于六味、八味二方云。", "18313": "咳者，肺气伤而不清故咳；嗽者，脾湿动而生痰故嗽。虽分六气五脏，其要皆主于肺。尤须知心咳者火也，巳、午尤甚；肺咳者金也，申、酉尤甚；肾咳者水也，亥、子尤甚；肝咳者风也、木也，寅、卯尤甚；脾咳者土也，辰、戌、丑、未四时微咳，脉式歌曰阿阿缓若春杨柳是也。善治者，先问是咳是嗽，或是咳嗽，何时咳甚，即用何经之药加入咳嗽方中，分新久、寒热、虚实而施治之。", "18314": "又治一儒者患咳嗽，面红潮热，其脉洪数，予以黄连解毒汤治之而愈。", "18315": "曾治周嘉兴，每夏至患咳嗽，服降火化痰之药而益甚。诊之脾肺肾三部脉皆浮而洪，按之微细。予曰：此脾土虚不能生肺金，肺金不能生肾水，而虚火上炎也，朝用补中益气汤加麦、味，夕用八仙长寿丸而愈。", "18316": "曾治一儒者，夏月唾痰，用清火药不应。予曰：此火乘肺金。用前麦门冬汤而愈。后因劳复嗽，遂与补中益气汤加桔梗、黄芩、麦、味而愈。但体倦口干，小便赤涩，日服生脉散，夕服八仙长寿丸，其后遂不复发。", "18317": "又治一儒者咳嗽，壮热自汗，口干便赤，予诊其脉虚而洪。先与白虎汤以彻其热，热退，遂用补中益气汤加山栀、麦冬、五味煎服数剂，兼服八仙长寿丸而愈。", "18318": "曾治明经某，素称实学，举动狂傲，不善保养，忽饮食无味，口干吐痰，肚腹膨胀，二便不利，医家不问虚实，便与之化痰行气，转见胸满痞闷，痰饮愈甚。与之导痰，又与分消，腹胀胁痛，坐卧不安。又与破血耗气，两足浮肿。知予在英公署内，告急求治，即谓余曰：贱躯被诸医治坏，请问先生还可救否？予诊其脉，右寸大而无力，右关微弦，右尺倏有倏无，左三部软而无力。余曰：足下脾肾两伤之证。令以午前服补中益气汤，早晚服金匾肾气丸。初服数剂更胀，余曰：不妨，久服则不胀。果信余言，逾月而诸证尽退，饮食渐进。继服八味丸去附子加北味，兼服归脾汤去木香、甘草，加五味子、肉桂，半载而康，元气大复。", "18319": "按：痰饮由于脾虚，法属太阴脾经。盖凡人后天水谷所生津液，全藉脾中之阳传运敷布，营养筋骨脉络，设脾气衰乏，传布不尽，其所留者不得谓之津液，斯为留饮。留饮为患，十常八九。", "18320": "曾医幕友柯南，年五十，体素丰，患痰喘，每遇风寒即发，饮食不进，旦夕不寐，数日方安。余寓长邑，道经彼过，其证复作，较前更甚，就诊于余。按之右寸洪大而数，右关微弦滑甚，余脉无力。余曰：手足太阴二经亏损，以致痰饮益甚，兼之肾气涣散，气虚上干而喘。法宜黄耆、白术大补中气，砂、半、茯苓醒脾豁痰，白蔻、草蔻宣畅胸膈，且消滞气，干姜、草果温中逐饮。柯友曰：尝闻耆、术提气，我素畏服。余曰：分经用药，乃千古指南，一定而不可易之法，今君患太阴留饮，耆、术乃补中宫阳气之的药，足下畏如鸩毒，又何药之用乎？柯友顿首谢曰：我门外汉也，今幸遇明公教我，不然贱躯不知病至胡底。领服一剂而效，数剂而安。遂与补中益气汤加茯、半，兼服八仙长寿丸而痊。明年在兴邑署中，制锦轴撰诗赠曰：", "18321": "凡人忽患胸背、手足、腰项、筋骨牵引钓痛，走移不定，或手足冷痹，气脉不通，此是痰涎在胸膈上下，误认瘫痪，贻害匪轻。", "18322": "世间发热，类伤寒者数种，治各不同。伤寒、伤风即寒疫也，则用仲景法；瘟病即瘟疫也，则用河间法，此皆论外感者也。今人一见发热，便认作伤寒，率用汗药以发表，汗后不解，又用表药以凉其肌，柴胡汤、凉膈散、白虎汤、双解散，杂然并进，若是虚证，岂不殆哉？自东垣先生出而发明内伤之论，此用气药补气之不足者也。至于劳心好色，内伤真阴，真阴既伤，则阳无所附，故亦发热，其人必面赤烦躁，口渴引饮，骨痛，脉数而大，或尺数而无力者是也。惟朱丹溪发明补阴之说甚好，惜又以四物汤加知母、黄柏，盖因阴字认不真，误以血为阴耳，故屡用不效。何耶？要当作肾中之真阴即先天也。《内经》曰：诸寒之而热者取之阴，诸热之而寒者取之阳，所谓求其属也。王太仆注云：大寒而盛热之不热是无火也，大热而盛寒之不寒是无水也。又云：倏忽往来，时发时止，是无火也；昼见夜伏，夜见昼伏，时节而动，是无水也：当求属而主之。无火者宜八味丸，益火之原，以消阴翳；无水者宜六味丸，壮水之主，以镇阳光。必须六味、八味二丸出入增减，以补真阴，屡用屡效。若误用知母、黄柏苦寒，苦先入心，久而增气，反能助火，至于滑泄败胃，损伤脾阴而立毙者，不可胜数。大抵病热作渴，饮冷便秘，此属实热，人皆知之。或恶寒发热，引衣蜷卧，四肢逆冷，大便清利，此属真寒，人亦易晓。曾见狂扰烦越，不欲近衣，欲坐泥水中，此属假热之证。又有甚者，烦极发躁，渴饮不绝，舌如芒刺，两肾燥裂，面如涂朱，身如焚燎，足心如烙，吐痰如涌，喘急不宁，大便闭结，小便淋沥，三部脉洪大而无伦，当是时也，却似承气汤证，承气入口即毙，又似白虎汤证，白虎下咽立亡。若用二丸缓不济事，愚即以加减八味丸料一斤，入肉桂一两，以水熬煎六碗，调桂末冰冷与饮，诸证自退。翌日必畏寒脉脱，是无火也，当用八味倍附桂丸料煎服，以补真阳而愈。", "18323": "或问曰：先生之论则详矣，气虚、血虚均是内伤，何以辨之？余曰：明乎哉子之问也。阴血虚者面必赤，无根之火戴于上也；若是阳气虚者，火入于内，面必不赤。其口渴者，肾水干枯，引水自救也，但口虽渴，而舌必滑，脉虽数而尺脉必无力，其甚者，尺脉虽洪数而按之必不鼓，此为辨耳。然其人曾服过凉药、脉亦有力而鼓指矣。戴氏云：服凉药而脉加数者，火郁也，宜升宜补，切忌寒凉，犯之必死。临证之工，更宜详辨，毫厘之差，枉人性命，尚慎旃哉！", "18324": "或问曰：吐血多起于咳嗽，咳嗽吐血者，肺病也。方家多以止嗽药治肺兼治血而不效，何也？答曰：诸书虽分咳血、嗽血出于肺，咯血、唾血出于肾，余谓咳、嗽、咯、唾皆出于肾。盖肾脉入肺，循喉咙，挟舌本，其支者从肺出，络心注胸中，故二脏相连，病则俱病，而其根在肾。肾中有火有水，水干火燃，阴火刑金，故咳；水挟相火而上化为痰，入于肺，肺为清虚之府，一物不容，故嗽中有痰唾带血而出者，肾水从相火炎上之血也，岂可咳嗽独归之肺耶？褚氏《津润论》云：天地定位，水位乎中，人肖天地，亦有水居中焉，在上为痰，在下为水，伏皮肤内为血，出毛窍中为汗。可见痰也、水也、血也，一物也，均发源于肾也。又云：饮溲尿百不一死，服寒凉百不一生。童便一味，世传治血之要，然暴发之际用之，以为消瘀之急剂则可，若多服久服，大能损伤胃气。褚氏特甚言寒凉之不可用耳。曰：若是乎知、柏既在所禁，用童便又不宜多服，治之当何法？曰：惟六味丸独补肾水，性不寒凉，不损脾胃，久服则水升火降而愈。又须用人参救肺补胃药收功，使金能生水，盖滋其化源也。", "18325": "曾治宋豪士乃郎，患证如前，缘由内伤外感，医家不与温经解表，肆行发散，病已数旬，表证难罢，干犯阴血，愈治愈热，病者、医家无法可措，交相为苦，来寓求诊。按之六脉沉细而数，右关微弦。余曰：发散太过，血虚之甚，又被阴火逼迫，而其势不可缓。乃用当归、白芍、元参、生地各三钱，熟地五钱，知、柏、栀子、黄连、川芎各二钱，柴首三钱，如前法煎药，晚服而效。改服八珍汤八剂，诸证渐退。是日晴朗，走出街口观望，以致迎风复作，是夜较前更甚。豪士复延余问曰：是病复作，其热如火，扪之烙手，热若不退，此子危矣。余曰：足下勿忧，不过再多服药，可保无伤。又如前药二剂而热退，其身安矣。多服十全大补汤，体遂健旺。", "18326": "曾治邹姓者，素患咳嗽吐血，去秋大作，昼则发热，夜则安静，误服滋阴之药，卧床不起，饮食不进，诸医断以必死，伊表曾其恒，代请诊视。按之六脉沉微，惟右寸浮大而软。余曰：此阳虚之证，前医不知分辨阴阳，一见发热，寒凉肆投，转致阴愈长而阳愈消，不救之候也，犹幸脉小身温，许予数剂而安。遂以补中益气汤加黑姜、茯神、远志、熟地、麦、味，倍用耆、术，一剂而苏，明日不发热矣，即进饮食。再服十全大补汤兼龟鹿地黄丸，旬日而愈。", "18327": "按之脉浮而滑者易治，微细者难疗。", "18328": "曾治刘天全，年三十二，患齁喘证，每发则饮食不进，坐卧不安，日夜为苦，至三四日痰尽乃平，天将雨，偶感风寒又作，至今十余年矣，诸药不应，请余诊治。按之六脉沉微，惟右寸肺脉大而滑甚。乃与紫金丹九粒，令将欲发以冷茶吞服，一次稍轻，七次而愈。继以六味、补中兼服而康。", "18329": "证如烦渴喘呼，脉见数大有力者，当润肺为主，而扶脾佐之。证如食少善泄，脉见细数无力者，当扶脾为主，而保肺佐之，甚则保肺之药，不利于脾，当即去之，却宜补土之母，少火庶可冀其回春。医家全在分经辨证，则阴阳虚实确有所据，而后切其脉以治之，方无差误。", "18330": "丹溪云：实火可泻，虚火可补。试问痨瘵之火，属之虚乎？属之实乎？泄之可乎？昔有畏知母、黄柏如鸩毒者，曰恐戕吾命根耳，然如病初起而相火正隆，或燥渴而右尺脉滑大，偶投一二剂，亦可也，若多用之，则断乎不可。", "18331": "丹溪之论劳证，主于阴虚，未常非也。阴虚之热，以发在午后子前，谚云：朝凉暮热也。阴虚之汗，从寐时盗出。阴虚无以制火，则火气逆上，喘嗽而吐痰也。阴虚则脉浮大，或沉虚也。四物加知、柏主之，以四物润血，血为阴，又加知、柏降火，理固然也。不知后人不能分辨阴阳虚实，以此方概施，多致不察变通而累，丹溪有遗恨也。盖川芎上窜，非火炎者所宜；地黄腻滞，若痰多食少者必禁（地黄不依制法，又不知服法，无怪乎腻滞，制若精良，反为逐痰圣品）；知母易于滑肠；黄柏易于败胃，暂投尤可，多用必伤。", "18332": "予今拟一方，以苡仁、茯苓扶脾，且切降下之功；桔梗、陈皮行气，且有健脾之力；麦冬、五味保肺，而能滋化之源；骨皮、丹皮除蒸，而无寒凉之害；痰喘用桑皮、川贝；止血用童便、黑姜；泻泄则山药、芡实；燥结则人乳、梨汁。此以甘温之品，行降收之令，而为初病者设也。若久病而百脉空虚，虚火亢炎，非甘温之品不能复其真元，宜异功散、补中益气汤；非濡润之品不能泽其枯朽，宜六味地黄丸。", "18333": "若少气懒言，目昏面白，宜生脉散、甘桔汤频频啜之。若病久而积痰成积，腹胁常热，惟头面、手足于寅卯时乍凉，宜六君子汤加姜汁、竹沥送滚痰丸三钱，先以汤润丸，令其易化。", "18334": "至若形色尪羸，阳事不禁，脉细无根，且数而无伦者，旦夕必逝。", "18335": "男子二十前后色欲过度，损伤精血，必生阴虚火动之病，睡中盗汗，午后发热，哈哈咳嗽，倦怠无力，饮食少进，甚则痰涎带出，咯血，咳血，衄血，吐血，身热而脉沉数，肌肤消瘦，此名痨瘵最重，治疗难矣。轻者必服药数十剂，丸饵十数斤。重者问愈不可以月计期，以年许然，必须病者爱命，坚心定志，绝房室，息妄想，戒恼怒，节饮食，以自培其根。否则，虽有良医，亦无可如何也。此病治之，于早则易，若到肌肉销铄，昏睡床褥，脉至细数，则难为矣。今制一方，治酒色沉迷，初起潮热盗汗，咳嗽倦怠，趁早服之。方用生地、炙草、炮姜、川芎、熟地、酒芍、广皮、白术、当归、门冬、知母、黄柏、生姜，煎服一二剂，细心斟酌，切勿多服，慎之慎之。", "18336": "按：前方治阴虚火盛之法也。愚谓此证属三阴亏损，无火之证，故见虚热，昼发夜止，夜发昼止，不时而作，当用六味地黄丸为主，以补中益气汤调补脾胃。若脾胃先损者，当以补中益气汤为主，以六味地黄丸温补肝肾，多有得生者。若用知、柏之类，伤乎脾胃，饮食日少，诸脏愈虚，元气下陷，腹痞作泄，则不可救矣。又有疰夏之病，或少有老态，不耐寒暑，不胜劳役，四时迭病，皆因气血方长，而劳心亏损，或精血未满而早斲丧，故见其证难以名状。若左尺脉虚弱，或细数，是左肾之真阴不足也，宜六味地黄丸；右尺脉迟软，或沉细而数欲绝，是命门之相火不足也，用八味地黄丸。至于两尺微弱，是阴阳俱虚也，十补丸。此皆滋其化源也，仍参前发热及咳嗽诸法调治之，至于衄血、咳血、咯血，在《绛雪丹书》咳嗽吐血论中详之。", "18337": "又治方州同，色欲过度，烦热作渴，饮水不绝，小便淋漓，大便秘结，唾痰如涌，面目俱赤，满舌生刺，两唇燥裂，遍身发热，两足心如火烙。诊其脉，左三部洪数无伦。予曰：此肾中之真阴大虚，阳无依附而发越于外。经曰：大热而盛，寒之不寒，是无水也。极当峻补其阴。乃与加减八味丸料一斤，内肉桂一两，以水熬六碗，水冷与饮，熟睡半刻。至晚又温饮一碗，诸证悉退。翌日畏寒，四肢作逆，诸证仍至，是无火也，极当大补其阳，乃煎八味地黄汤四剂，诸证尽退。继服龟鹿地黄丸而痊。", "18338": "曾治州吏目宋豪士，为人清高，二代单传，年十八患前证，医家不识尸虫之害，误作虚劳治之，一味滋阴，以致阴愈长而阳愈亏，不竭力杀虫，反去养虫，则虫之子若孙，愈肆猖獗，不亡何待？乃叔肇堂延请诊之，六脉沉细而数，左关数甚，观其面黯色滞，肤无润泽，发焦耳枯，形神俱败，尸虫旺极之候。遂与人参、耆、术各五钱，星、半、姜、附各三钱，吴萸、川椒、枯矾各一钱。服十剂，觉神气稍清。又服十剂，皮肤光泽。又服三十剂，发润耳红，人事利爽，元气渐复，步履自如。乃为之竭力杀虫，兼以制鬼法，用室女顶门发一小团，皂角汤洗去垢，酒醋浸晒，同黄纸卷筒烧存性，川芎五钱，当归三钱，广香一钱，安息香、明雄各二钱，全蝎二枚，生活鲤鱼一尾取头（酒醋酥炙），共为粗末，分四服。每服入降真香末五分，书北斗符一道，火化入药中，如前法念北斗咒七遍。五更时井花水煎服务要，初旬治之乃灵。又另买大鳗鲡一尾去肠腹，用水清蒸，调和五味，汤肉任吃，留其全骨，以火炕干，入降真香、雷丸、大黄、川椒、吴萸、甘草、明雄各七钱，共为粗末，入当门子七分和匀，卷黄纸筒以药贮之。令患者高卧于大油纸内，覆好留头，面向外，燃纸筒薰之，熟睡半时，九窍作痒，醒则诸虫尽在油纸中矣，延余视之，形如针嘴，近人气犹作跳跃状，殊甚骇然，命除之。继服补中益气汤数百剂、龟鹿地黄丸数十斤，而元气大复，连生五子。", "18339": "曾治富商汤名扬，自谓体旺，酒色无度，行年四十，饮食渐减，形神尪羸，或教以每早进牛乳酒，初食似可，久之朝食至暮，酒乳结成羊屎形，一一吐去，其大小便日夜不过数滴，全无渣滓下行，卧床不起，告急请诊。按之两尺脉微如丝，右关弦紧，乍有乍无，两寸与左关洪大而散。余曰：足下之恙，乃本实先拨，先天之阴虚宜补水，先天之阳虚宜补火，水火既济，庶可得生。富商请方，乃用熟地一两，山茱、山药各四钱，茯苓、泽泻、丹皮、肉桂、附子各三钱，煎服一剂。明早令进牛乳酒，至暮则下行而不上吐矣。连服十剂，饮食渐进。遂以前方药料为丸，日服二次。嘱戒酒色，半载而康。", "18340": "曾治燮堂伍登相，病反胃，求治于余。诊之两寸关脉大而弱，两尺脉涩而小，乃气血不足，大虚之证。遂与旋覆代赭汤二剂，八味地黄汤八剂，继服八味丸而元气大复。", "18341": "曾治邑门丁陈二，患阳强不倒，延求诊治。按之右尺洪大而紧，余脉如常，视之满面红光，全无滞气，乃是肾中真阳之人飞越耳。遂与元参三两、麦冬三两，煎好取汁一大碗，入油桂末七分，调药水服。此方妙在用元参最重，以泄肾中浮游之火；尤妙在用桂末少许，以引其入宅，而招散其沸腾之火，同气相求，火自回舍；况麦冬能助肺金清肃之气下行，以生肾水，水足而火自得其养矣。此不求倒而自倒也，他日亦可重整戈矛，再图欢合耳。", "18342": "曾治邓隆太，冬月患中寒，初则四肢厥逆，耳心痛连少腹，冷厥关元，势在垂危，冒雪请诊。六脉俱伏，面青唇黑，舌卷阳缩。余曰：此正缩阳证也，阳缩属少阴，舌卷属厥阴，且耳心亦属少阴，是证乃因酒色过度而酿成耳。急用耆、术各五钱，砂、蔻各八分，干姜、附、桂各二钱，吴萸、川椒各一钱，煎服，一剂而效。再加芦巴、故纸各三钱收固肾气，四剂而安。继服八味地黄丸而元气大复。", "18343": "余读舒氏妙论，诚哉补前人之所未及，至于末年复刊所制理脾涤饮，与仲景黄耆建中、东垣补中、归脾、十全、养营、补血等汤，咸皆重用黄耆、白术而珍之如宝，医者明乎此诀，凡遇三阴虚寒诸证，依脉轻重变化，效如桴鼓。予非谬执臆说，屡用奏功，故重言以申明之同志君子，诚能推广而变通焉，于医道也，虽不及上工，亦在中工之列。", "18344": "岐伯曰：升治者，乃气虚下陷不能升而升之也。凡人饥饱劳役，内伤正气，以致气乃下行，脾胃不能克化，饮食不能运动，往往变成痨瘵。或疑饮食不进，谓是脾胃之火，或疑黍肉所伤，谓是水谷之积。轻则枳壳、砂仁、山楂、麦芽，重则芒硝、大黄、牵牛、巴豆，纷纷杂投，必至臌闷不已。倘先以升提之法治之，一切内伤饮食、饥饱劳役、内感风寒，有何不可治哉？世多昧此，不知李东垣补中益气汤实为对证之方，智者明乎此秘，依脉轻重变化，万病俱见神功。予特表而出之，欲学者奉为金丹也。", "18345": "凡人右手寸口脉大于左手寸口之脉者，即是内伤证也。无论左右关脉、尺脉大、小、浮、沉，即以此方投之，无不效如桴鼓。", "18346": "或疑参、耆大多，不可骤补，不妨竟为减少，不知二味略轻，则升、柴无力，譬如绳索细小，欲升重物于百尺之上难矣。或用参而不用耆，或用耆而不用参，则必至功力减半，然犹有尽去之者也。倘又以升、柴提气，或疑清气不升，浊阴之腾上者，此必左手寸口之脉大于右手寸口之脉者是也。可以借言，苟或不然，杀人无算，必是此人创说也。余最恶此辈似是而非，为吾道之乡原，须宜辞而避之也。东垣一生学问神而明之，千古之下，一人而已。", "18347": "《金匮要略》云：平人脉大为劳，脉极虚亦为劳。夫劳之为病，其脉浮大，手足烦热；春夏剧，秋冬瘥。以黄耆建中汤治之。方用人参、黄耆、白芍、甘草、肉桂、大枣、饴糖。此方亦温之之义也。", "18348": "夫胃气为水谷之海也。饮食入胃，游溢精气，上输于脾，脾气散精，上输于肺，通调水道，下输膀胱。水精四布，五经并行。合于四时五脏阴阳，揆度以为常也。若饮食失节，寒温不适，脾胃乃伤；喜怒忧恐，耗损元气。脾胃气衰，元气不足，而火独盛。火者阴火也，起于下焦，元气之贼也。壮火食气，少火生气，火与元气不两立，一胜则一负。脾胃气虚则下流肾肝，名曰重强，阴火得以乘其土位，故脾证始得则气高而喘，身热而烦，其脉洪大而头痛，或渴不止，其皮肤不任风寒而生寒热。盖脾胃之气下流，使谷气不得升浮，是春生之令不行，则无阳以护其营卫，遂不任风寒而生寒热。此皆脾胃之气不足所致也。然与外感风寒，证虽同而实则异，内伤脾胃，乃伤其气；外感风寒，乃伤其形。伤其外则有余，有余者泄之；伤其内则不足，不足者补之。汗之、吐之、下之、克之之类，皆泄也；温之、和之、调之、养之之类，皆补也。果是内伤不足之病，苟误认作外感有余之证而反泄之，则虚其虚也。实实虚虚之祸，如此死者，皆医杀之耳。然则奈何？惟当用辛热甘温之剂，补其中而升其阳则愈矣。经曰：劳者温之，损者温之。又曰：甘温能除大热。大忌苦寒之剂损其脾胃。故东垣先生立补中益气汤主之。", "18349": "夫因饥饱、劳役损伤脾胃，或专因饮食不调，或专因劳力过度，或劳力之后加之饥饱，或饥饱之后加之劳力，皆为内伤。脾胃一虚，肺气先绝，故用黄耆以益皮毛而闭腠理，不令自汗损其元气；上喘气短，人参以补之；心火乘脾，须炙草之甘以泄大热，而补脾胃中之元气，若脾胃急痛并大虚，腹中急缩者，宜多用之，经曰：急者缓之；白术苦甘温，除胃中热，利腰脐间血；胃中清气在下，必加升麻、柴胡以引之，引黄耆、甘草甘温之气味上升，能补卫气之解散，而实其表也，又缓带脉之缩急，二味皆苦平，味之薄者，阴中之阳，引胃中清气升于阳道，及诸经生发之气以滋春气之和也；气乱于胸中，为清浊相干，用去白陈皮以理之，清升而浊自降矣；胃气虚，不能升浮，为阴火伤其生发之气，营血大亏，荣气不营，阴火炽起，日渐熬煎，气血日减，心主血，减则心无所养，致使心乱而烦，故用当归以和之。如烦犹未止，加服地黄丸以补肾水，水旺而心火自降。以手扪之而肌表热者，表证也，只服补中益气汤一二剂，得微汗而已，非止发汗，乃阴阳气和，自然汗出也。", "18350": "如腹中痛，恶寒而脉弦者，是木来克土也，小建中汤主之。", "18351": "如脉沉细腹痛，以理中汤主之。干姜味热，于土中泻水以为主也。", "18352": "如体重肢节痛，或腹胀，自利，脉来濡缓者，湿胜也，加苍术、厚朴主之。", "18353": "如冬月恶寒，发热无汗，脉浮而紧，本方中酌加麻黄、桂枝。如用麻黄五分，参、耆各用二钱。", "18354": "如冬月恶风，发热有汗，脉浮而缓，加桂枝、芍药。", "18355": "右手气口脉大于左手人迎三部，其气脉急大而数，时一代而涩，涩是肺之本脉；代是气不相接，乃脾胃不足之脉；大是洪大，洪大而数，乃心脉刑肺；急是弦急，乃肝木挟心火刑肺金也。其右关脉属脾，此五脉独大而数，数中时显一代，此不甚劳役，是饮食不时，寒温失所，胃脉损弱，隐而不见，亦惟内显脾脉，乃是如此。", "18356": "若外感，则人迎脉大于气口也。", "18357": "东垣先生以手扪热有三法，以轻手扪之则热，重按之则不热，是热在皮毛血脉也；重按筋骨之间则热蒸手，轻扪之则不热，是热在骨髓也；轻手扪之不热，重手按之亦不热，不轻不重，按之而热者，是在筋骨之上、皮毛血肉之下，乃热在肌肉。肌肉间热，正内伤劳倦之热也。若余于内热真阴者，以手扪热亦有二，扪之烙手，骨中如炙者，肾中之真阴虚也；扪之烙手，按之筋骨之下反觉寒者，肾中之真阳虚也。面赤者，阴盛于下，逼阳于上也。口渴者，肾水干枯，引水自救也。若吐痰多如清水者，肾水泛上为痰，口必不渴也；咯痰如沫者，水拂为痰，阴火熬煎，口必渴也。腰胁痛者，肾肝虚也。足心如烙者，涌泉涸竭者也。膝以下冷者，命门衰绝，上气必喘也。尺脉数者，阴火旺也；尺脉数而无力，或欲绝者，真阳衰也。骨痛如折者，肾主骨，骨衰乘火也。此阳虚、阴虚之辨，而阴虚之中，又有真阳、真阴之不同，其治法详于先天要论中。", "18358": "又有食填太阴，名曰食厥者，上部有脉，下部无脉，不急治则死，即以阴阳水烧淡盐汤探吐之，即愈。如有食积，肠腹绞痛者，手不可按，不得不下，审知其为寒积，必用巴豆感应丸；审知其为热积，必用大承气汤急下之。否则死生立判，慎之慎之。", "18359": "河间、东垣，专治本而不治风，可为至当不易之论，学者必须以阴虚、阳虚为主。自后世医书歧出，而使后学犹豫狐疑。丹溪曰：有气虚，有血虚，有湿痰。左手脉不足，及左边半身不遂者，以四物汤补血之剂为主，而加以竹沥、姜汁；右手脉不足，及右边半身不遂者，以四君子汤补气之剂，而佐以竹沥、姜汁。如气血两虚者，且又挟痰，以八物汤为主，而加南星、半夏、竹沥、姜汁之类。丹溪之论，平正通达，宜世之人咸宗之。但持此法以治中风，而多不效，或少延而久必毙，何也？盖治气、血、痰之标，而不知治气、血、痰之本也。夫人之有四肢也，如木之有枝干也，人之气血营养于四体也，犹木之浆水灌溉于枝叶也。木有枝叶，木有本根，人之气血，岂无根本乎？人有半身不遂，而迁延不死者，如木之根本未甚枯，而一边之枝干先萎耳。人有形容肥壮，忽然倒仆而即毙者，如木之根本已绝，其枝叶虽荣，《易》曰：枯杨生华，何可久也？忽遇大风而摧折矣。观此则根本之论明矣。然所谓气血之根本者何？盖火为阳气之根，水为阴气之根，而火与水之总根，两肾间动气是也。此五脏六腑之本，十二经之源，呼吸之门，三焦之根，又曰守邪之神。经曰：根于中者，命曰神机，神去则机息；根于外者，名曰气立，气止则化绝。今人纵情嗜欲，以致肾气虚衰，根先绝矣，一或内伤劳役，或六淫七情，少有所触，皆能卒中，此阴虚阳暴绝也。须以参附汤大剂峻补其阳，继以六味地黄丸、十补丸之类填实真阴。又有心火暴甚，肾水虚衰，兼之五志过极，以至心神昏闷，卒倒无知，其手足牵掣，口眼㖞斜，乃水不能营筋急而纵也，俗云风者，乃风淫末疾之假象，风自火出也，须以河间地黄饮子峻补其阴，继以麦门冬、五味子之类滋其化源，此根阳根阴之至论也。若夫所谓痰者，凡人之将死，必有痰，何独中风为然。要知痰者水也，从何处来乎？其原盖出于肾。张仲景曰：气虚痰泛，以肾气丸补而逐之。观此，凡治中风者，即以前法治其根本，则痰不治而自去矣。若初时痰涎壅盛，汤药不入，少用稀涎散之类，使喉咽疏通，能进汤液即止。若必欲尽攻其痰，顷刻立毙。戒之哉！戒之哉！", "18360": "乾坤生气云：凡人有手足渐觉不遂，或臂膊，或髀股、指节麻木不仁，或口眼㖞斜，语言蹇涩，或胸膈迷闷，吐痰相续，或六脉弦，续而虚软无力，虽未至于倒仆，其中风晕厥之候可指日而决矣，须预防之。愚谓预防之理，当节饮食，戒七情，远房事，此至要也。如欲服饵，须察其脉证之虚实，如两尺虚衰者，以六味丸、八味丸切补肝肾；如寸关虚弱者，以六君子汤、十全大补汤之类急补脾肺才有补益。若以搜风顺气及清气化痰等药，适足以招风取中也，不可不知。", "18361": "曾治凌秀才之母，年五十，已生九男二女，气血衰惫，一日外出，饮食过伤，途遇风雨，食填太阴，倒晕床褥，水浆不入已四日矣。举家议以必无生理，三子促骑而请，予因家有要事，辞以不果。其七子廪生弼祖，在馆攻书，闻之来寓，长跪而请，予念救母心诚，扶起允之登舆，顷刻而至。视之衣棺俱备，静候死耳。其夫亦府庠，引予入室。见其手撒口开，诊之寸关如丝，两尺全无。乃谓其夫曰：经云上部有脉，下部无脉，其人当吐，不吐者死。令其子烧淡盐汤三品碗，入童便一碗搅匀，扶起病人，三饮而三吐之，果吐出宿食痰涎碗许而人事稍苏。乃与六君子汤加耆、术、白蔻一剂，是夜即服稀粥一碗，明早乃起床矣。又用归脾汤数十剂，兼服六味地黄丸而安。", "18362": "又治傅福兴，年三十，形体魁梧，因酒色过度，忽一日至街仆地，口眼㖞斜，语言蹇涩，不省人事，痰涎上涌，右手足不活，腰俯不伸，四肢不动，乃弟迎诊。按之六脉沉伏，惟肝脉洪数，面色青而兼黑。予曰：此肾水枯竭也。乃与大剂补中益气汤，加酒炒黄柏三分，以滋化源，泻阴中之伏火；酒炒红花三分，以入血分而养心血。连进二剂，人事稍苏，痰涎渐少，语言颇觉爽利，行动亦觉自如。仍用前汤，去黄柏、红花，合六味地黄汤，大剂煎饮，十剂而诸证悉退。单服补中益气汤，又兼服龟鹿地黄丸，而元气大复。", "18363": "曾治元配周氏，年四十，勤俭过甚，气血久枯，忽一日早，头晕仆地，人事不省，痰涎满口，手撒鼾睡，气息如丝。按之六脉浮迟，乍有乍无。吾料其不可为也，勉强与三生饮，浓煎灌之；外以神应散吹鼻，得嚏而苏。乃以六君子汤，兼六味地黄丸服之，一载无功，交春而殁。可见气血虚甚者，即治之得法，亦竟不能保其长年。", "18364": "今人患暑证卒殁，而手足指甲及肢体青黯者，此皆不究其因，不温其内，而泛用香薷饮之所误也。夫香薷饮乃散阳气、导真阴之药也，须审果有是证而服之，斯为对证，今世人于平时恐患此病，而先服之以预防，适足以招暑取病也，若其人元气素虚，或房劳过度而服之者，为祸尤深。必欲预防，惟孙真人生脉散为夏月最宜。", "18365": "暑证与热证相似，但热病脉盛，暑病脉虚，斯为辨耳，临证慎之。", "18366": "曾治一富翁张某，感冒盛暑，壮热大汗，烦渴恶热，晕眩倒仆，昏睡懒言，其子来寓求诊。按其六脉，微细而缓，惟右关弦紧而芤。余曰：此暑邪侵入阳明之里，故壮热大汗；烦渴饮冷，乃为热越；晕眩不言，热盛而神昏也。乃与白虎汤以撤其热，更加人参二钱、黄耆五钱、桑叶十三片，以大补其气而收其汗。果服一剂而热退汗止，再服生脉散二剂而痊愈夫。", "18367": "又治乡中一人，暑月忽吐利，发热，以手触之则痛甚，其父求诊。按之六脉弦细而芤。余曰：此溽暑也。乃与益元散合四苓散，煎服一剂，而吐、利、痛、热退去大半。因其人气弱，更用补中益气汤，倍参、耆，加麦、味，二剂而安。", "18368": "有在天之湿，雨、雾、露是也。在天者，本乎气，故先中表之营卫。有在地之湿，泥、水是也。在地者，本乎形，故先伤肌肉、筋骨、血脉。有饮食之湿，酒、水、乳酪是也。胃为水谷之海，故伤于脾胃。有汗湿之湿，谓汗液出而沾衣湿透，未经解换者是也。有足太阴脾土所化之湿，不从外入者也。阳盛则火胜，化为湿热；阴盛则水胜，化为寒湿。其证发热恶寒，身重自汗，筋骨疼痛，小便秘涩，大便溏泄，腰痛而不能转侧，跗肿，肉如泥，按之不起。", "18369": "喘与胀，二证相因，必皆小便不利。喘则必生胀，胀则必生喘。但要识得标本先后，先喘而后胀者主于肺，先胀而后喘者主于脾。何则？肺经司降，外主皮毛，肺朝百脉，通调水道，下输膀胱。又曰：膀胱为州都之官，津液藏焉，气化则能出矣。小便之行，由于肺气之下降而输化也。若肺气受邪而上喘，则失下行之令，故小便渐短，以致皮肤必生胀满之疾。此则喘为本，而胀为标，治当清金降火为主，而行水次之。脾土恶湿，外主肌肉，土能克水，若脾土受伤，不能制水，则水湿妄行，浸渍肌肉，水邪上溢，则邪反侵肺，气不得降而生喘矣。此则胀为本，而喘为标，治当实脾行水为主，而清金次之。苟肺证而用燥脾之药，则金得燥而喘愈加；脾病而用清金之剂，则脾得寒而胀愈甚矣。举世治二证，但知实脾行水，而不分别脾、肺二经，愚故为发明其说。", "18370": "曾治一儒学，失于调养，饮食难化，胸膈不利，医家用行气消导，咳嗽喘促。又用化痰行气，肚腹渐胀。又用行气分利，睡卧不安，两足浮肿，小便不利，大便不实。肺、肾两部脉浮大，按之微细，两寸皆短。朝与补中益气汤加姜、附，夕与金匮肾气丸加故纸、肉果，各服数剂，诸证渐退。再与八味地黄丸，两月乃能步履。又用六味丸，兼服补中益气汤而康。", "18371": "曾治一人，时五月病热，医用平调血气兼清热和解之剂，服之不应，其热愈甚，舌上焦黑，膈间有火，漱水不咽。诊其脉，两手皆虚微，而右手微甚。六七日内谵语撮空，循衣扪床，恶证俱见。予用四物汤加陈皮、耆、术、参、麦、知母、熟附子，服之良久，汗出而热退。次日复热，再服前药而退。又次日又热，予知其虚极也，遂连进十服，皆加附子而安。", "18372": "又治一人，亦夏月病热，口渴唇干，谵语。诊其脉细而迟。予与之四君子汤加归、芍、黄耆、附子，令进一服，其热愈甚，狂言乱走。旁观者曰：附子之误也。复诊其脉如旧，仍增附子，进一大剂，服之汗出而热退，其脉如常。", "18373": "按：前证治法，真所谓舍时从证，舍证从脉，卓有定见者也。", "18374": "又治黄武进士，饮食劳倦，发热恶寒，误用发表，神思昏愦，胸发赤斑，脉洪数而无力。余曰：此内伤元气，非外邪也，宜急用温补之剂，或可得生。其兄曰：明明斑见，敢用温补为耶？不听余言，重投消斑化斑而殁矣。冤哉！", "18375": "《总录》谓不能食而渴者，未传中满；能食而渴者，必发背痈、脑疽。设不知分辨能食、不能食，概以寒凉泻火之药而施治之，则内热未除，中寒复生，能不末传鼓胀耶？惟七味白术散、人参生脉散之类，恣意多饮，复以八味地黄丸滋其化源。如发痈疽而渴者，或黑或紫，火极似水之象，乃肾水已竭，不治，惟峻补其阴，亦或可救也。", "18376": "按：前证若体倦少食，视物昏花，或劳役益甚，脾胃虚弱者，用补中益气汤；若眵多紧涩，赤脉贯珠，或脏腑秘结者，用芍药清肝丸；若赤翳布白，畏热羞明，或痛如针刺者，上焦风热也，用黄连饮子；若久坐生花畏日，远视如雾者，神气伤也，用神效黄耆汤。凡午前甚而作痛者，东垣助阳活血汤；凡午后甚而作痛者，黄连天花粉丸；午后甚而不痛者，益阴地黄丸。能近视而不能远视者，八味地黄丸；能远视而不能近视者，定志丸、六味地黄丸。", "18377": "东垣曰：五脏六腑之精气皆禀受于脾土，上贯于目。脾者，诸阴之首也。目者，血脉之宗也。故脾虚则五脏之精气难周运乎目，故多不明。心者，君火也，主人之神，宜静而安，相火代行其令。相火，包络也，主百脉皆荣于目，既劳役运动，势乃妄行。又曰：形气所并，而损血脉，故目中诸病生焉。世医治目，不知理脾健胃及养血安神，治标不治本，是不明正理，乃庸工也。若概用辛凉苦寒之剂，损伤真气，促成内障之证矣。", "18378": "曾医张给事，患目赤不明。医用祛风散热药，反畏明重听，脉大而虚，此因劳心过度，饮食失节。余以补中益气汤加茯神、枣仁、远志、山萸、山药、五味顿愈。又因劳役复甚，与十全大补汤渐愈。仍用补中益气汤，兼服六味丸料，加四制枸杞、菊花为丸，服之目明如旧。余读岐伯曰：目赤而痛，肿如含桃，泪出不止，酸痛多眵，火眼是也。其眵多、泪多、红肿而痛，如针刺不可忍，方用柴胡、栀子、白蒺藜各三钱，半夏、甘草各一钱，水煎服。此方神妙不测，全在直散肝胆之郁火，火散而热自退，不攻之胜于攻，不下之胜于下也。轻者一剂获效，重者四剂立愈。余得此方数十年，用之如桴鼓相应，愿同志宝之以广其传，德莫大焉。", "18379": "曾治方人贤，其家巨富，为人孝友，已单传三代矣。惜幼斲丧，本实先拨，艰于子嗣，已成虚劳，屡医不效。形体尪羸，双目昏暗，羞光怕日，阳事不举，来寓求治。诊毕谓曰：经曰：男子寸强而尺弱，女子寸弱而尺强。今贵脉尺强寸弱，阴阳相反矣，宜补中益气汤加白菊、茯苓以滋化源，继服四神丸加鹿茸壮水明目、填补精血，多服自效。观子行止端方，语言温柔，且肯方便广施，自必螽斯衍庆。彼曰：先生妙论，弟幸重闻，敢不惟命是听？贱躯如愈，奕祀感德矣。", "18380": "脉两寸浮洪而溢者，喉痹也。脉微而伏者，死证也。经曰：一二经中，惟足太阳经下项，余经皆凑于喉咙，盖君相二火独盛，则热正络，故痛者数也。余谓一言可了者，火也。嗌干、嗌痛、喉肿、舌本强，皆君火也。咽痛急速，是相火所为肿也。夫君火者人火也，相火者龙火也，人火焚木其势缓，龙火焚木其势速。后世名详其状，名曰单乳蛾、双乳蛾、子舌胀、木舌胀、缠喉痹、走马喉痹，皆因热气结于外，其形似乳蛾，一为单，二为双。比乳蛾差小者名曰喉痹。热于舌下，复生以小舌子，名曰子舌胀。热结于舌，舌肿名曰木舌胀，强而不柔和也。热结于咽喉，肿绕于外，且麻且痒，且肿大者，名曰下喉风。暴发暴死，名曰走马喉风。故喉痹之证，死生反掌。其不误人者，无如砭针出血，血出，即磨紫金锭服之，立已。《易》曰：血去惕出，此之谓也。此慧屡试而屡验，同志慎宜留意焉。", "18381": "世医多知咽痛是火，少知咽痛是寒。经曰：太阳在泉，寒淫所胜，民病咽痛项肿。陈藏先生用附子，去皮脐，炮裂切片，以白蜜涂炙，令蜜入内，噙咽其津，俟甘味尽去之，换一片再噙。又有下利清谷，里寒外热，脉微欲绝，面赤咽痛，宜通脉汤。盖因冬月伏寒在肾经，发则咽痛下利，宜用附子汤温经则愈。", "18382": "赵氏引薛案云：一人年五十，患咽喉肿痛，用针去血，神思虽清，其尺脉洪数无伦，次按之微细若无。余曰：有形而若无，戴阳证也。先宜峻补其阴，今反伤阴血，必死，是夜果殁。举此一案以为粗工轻用刀针之戒。", "18383": "曾治春桥魏表弟，素禀阳虚，牙龈不时肿痛，针出脓血即已。诊其脉浮大而空。余曰：此太阴脾肺二经气虚，兼足太阳膀胱经虚热所致。遂与人参理中汤加山萸、山药，煎服而瘥。", "18384": "曾治县令曹秉让，因本实先拨，忽患咽痛喉痹，求余诊之。其脉浮大，重取细涩。余曰：此先天之真阴虚极，真阳飞越，故痰结于喉间，去生已远。速煎独参汤，细细呷之，三日乃平。继以六味丸加麦、味，不两旬而安。", "18385": "曾治汤时顺，患咽喉肿痛，内热口干，痰涎上涌。按之尺脉数而无力。余曰：此肾水亏损，相火无制而然。乃与六味丸料加麦冬一两、北味三钱，尽一日饮之而肿痛消，痰涎少。再以前汤为丸，调理三月而安。", "18386": "曾治宋飞鸣，患咽喉肿闭，不省人事，痰涎上涌，喘促汗出，肢体痿软。诊之其脉浮大而数。余曰：此饮食劳伤，是无根虚火上促也。乃与补中益气汤，磨油桂心三钱，冲服而安。", "18387": "又治萧大明，患咽喉肿痛，作渴饮冷，大便秘结。按之六脉俱实。乃与防风通圣散，因自汗，去麻黄，加桂枝；因涎嗽，加姜制半夏，重用硝、黄下之而愈。但余历验五十年来，虚热者多，实热者少，此方不可轻用。", "18388": "余考诸失血之证，必察五脏之脉为据，心脉沉，主咯血、尿血；肝脉浮，主肠风下血；脾脉数，主呕吐鲜血；肺脉浮，主吐、衄；肾脉沉，主小便淋沥有血。诊其脉沉小者生，身凉者生；脉大、身热者死。吐后脉微者可治；吐、衄后，脉复大，热躁急者。又主死也。", "18389": "六淫中虽俱能病血，其中独寒气致病者居多。何也？盖寒伤营，风伤卫，自然之理。又太阳寒水，少阴肾水，俱易以感寒。一有所感，皮毛先入，肺主皮毛，水冷金寒，肺金先受，血亦水也，故经中之水与血，一得寒气，皆凝滞而不行，咳嗽带痰而出，问其人必恶寒，切其脉必紧，视其血，中间必有或紫或黑数点者，此皆寒淫之验也。医者不察审其证，便以阴虚火动，而概用滋阴降火之剂，病日深而死日迫矣。余尝用麻黄桂枝汤而愈者数人，皆一服得微汗而愈。盖汗与血一物也，夺血者无汗，夺汗者无血。余读《兰室秘藏》而得此意，因备记以广其传。", "18390": "独有伤暑吐衄者，可用河间法，必审其证，面垢，口渴喜饮，干呕，腹痛或不痛，发热或不发热，其脉必虚，大汗出者，黄连解毒汤主之，甚者白虎汤。", "18391": "愚按：暑伤心，心气既虚，暑气故承而入之，心主血，故吐衄。心既虚而不能生血，恐不宜过用寒凉以泻心，须清暑益气汤中加生地、丹皮，兼犀角地黄治之。盖暑伤心亦伤气，其人必无气以动，脉必虚，宜以参、耆助气，使气能摄血，斯无弊也。", "18392": "凡失血之后大发热者，名曰血虚发热。古方立当归补血汤，用黄耆一两、当归六钱。名曰补血汤，而以黄耆为主，阳旺能生阴血也。丹溪于产后发热，用参、耆、归、芎、黑姜以佐之。或问曰：干姜辛热，何以用之？余曰：姜味辛，能引血药入气分而生新血，神而明之。不明此理，见其大热，六脉洪大，而误用发散之剂，或以其象白虎汤证而误用白虎汤，立见危殆，不可救矣，慎之哉！", "18393": "《三因方》云：理中汤能止伤胃吐血，以其方最理中脘，分别阴阳，安定气血。按：患者果身受寒气，口受冷物，邪入血分，血得冷而凝，不归经络而血妄行者，其血必黑黯，其色必白而夭，其脉必微迟，其身必清凉，斯时不急用姜、桂，而用凉血之剂殆矣。临证之工，宜详审焉。", "18394": "王海藏云：胸中积聚之残火，腹里积久之太阴，上下隔绝，脉络部分阴阳不通，用苦热以定若中，使辛热以行于外，升以甘温，降以辛润，化严肃为春温，变凛冽为和气，汗而愈也。然余毒土苴，犹有存者，周身阳和，尚未泰然，心中微燥而思凉饮，因食冷物、服凉剂，阳气复消，余阴再作，脉退而小，弦细而迟，激而为吐、衄者有之，心肺受邪也；下而为便血、尿血者有之，肾肝受邪也；三焦出血，色紫不鲜，此重沓寒湿化毒，凝泣水谷道路，浸溃而成。若见血证，不详本末，便用凉折，变乃生矣。", "18395": "一男子咳嗽吐血，热渴痰盛，盗汗遗精，用六味地黄丸料，加麦冬、五味治之而愈。后因劳怒，忽吐紫血块，先用花蕊石散化其紫血，又用独参汤渐愈。后每劳则吐血一二口，脾脉与肺肾脉皆洪数，用归脾汤、六味地黄丸而愈。", "18396": "客又问曰：吐血、衄血，同是上炎之火，一出于鼻，一出于口，何也？答曰：东垣云：衄血出于肺，从鼻中出也；呕血出于胃，吐出成碗成盆也；咯血、唾血出于肾，血如红缕在痰中、唾中，咳咯而出也；痰涎血者出于脾，涎唾中有少血散浸而出也。东垣论虽如此，然肺不特衄血，亦能咳血、唾血；胃不特呕血，肝亦呕血。盖肺主气，肝藏血，肝血不藏，乱气自两胁中逆而出之。然总之是肾水随相火炎上之血也，肾主水，水化液为痰、为唾、为血，肾脉上入肺，循喉咙，挟舌本，其支者从肺出，络心注胸中，故病则俱病也。但衄血出于经，衄行清道；吐血出于胃，吐行浊道。喉与咽，二管不同也。盖经者走而不守，走经之血随气而行，火气急，故随经直犯清道而出于鼻，其不出于鼻者，则为咳咯，从肺窍而出于咽也。胃者守营之血，守而不走，存于胃中，胃气虚不能摄血，故令人呕吐，从喉而出于口也。今人一见吐衄，便以犀角地黄汤为必用之药，然耶？否耶？曰：犀角地黄汤乃是衄血之的方，若阴虚火动吐血与咳咯者，可以借用成功，若阳虚劳力及脾胃虚者，俱不宜用。盖犀，水兽也，焚犀可分水，亦可通天。鼻衄之血，从任督而至巅顶，入鼻中，惟犀角能下入肾水，水由肾脉而上引，地黄滋阴之品，故为对证。今方书所载，如无犀角以升麻代之，犀角、升麻气味形性迥不相同，何以代之？答曰：此又有说焉，盖缘任冲二脉附足阳明胃经之脉亦入鼻中，火郁于阳明而不得泄，因成衄者，故升麻可代。升麻阳明药也，非阳明经衄者不可代。衄亦有阴虚火衰者，其血必点滴不成流，须用壮火之剂，不可概用犀角。有伤寒病五六日，但头汗出，身无汗，际颈而还，小便自利，渴饮水浆，此瘀血证也，宜犀角地黄汤、桃仁承气汤，看上下虚实，用犀角地黄汤治上，桃仁承气汤治中，代抵当汤治下，斟酌用之可也。", "18397": "有怒气伤肝而成吐衄者，其人必唇青、面青、脉弦，须用柴胡栀子清肝散。又有郁气伤脾者，须用归脾汤加丹皮、山栀。推而广之，世人因郁而致血病者多。凡郁皆肝病也，木中有火，郁甚则火不得舒，血不得藏而妄行。但郁之一字，不但怒为郁，忧为郁，怒与忧固其一也。若其人素有阴虚火证，外为风寒暑湿所感，皮毛闭塞即为郁，郁则火不得泄，血随火而妄行，郁于经络则从鼻而出，郁于胃脘则从吐而出。凡系郁者，其脉必涩，其人必恶风、恶寒，不知者便以为虚而温补之，误矣，须视其面色必滞，必喜呕，或口苦，或口酸。审果有如是证，必当舒散其郁为主，木郁则达之，火郁则发之是也。其方惟逍遥散为的药，外加丹皮、吴萸、水炒黄连，随手而应。止血后，若不用六味地黄丸多服以滋其阴，翌日必发。吾于五郁论中详言之矣。", "18398": "向日在泸城，曾治曾荣庆，患虚劳咳嗽，予已治愈三载矣，并嘱禁服凉药，后因纳宠，酒色沉迷，忽吐血不止，医用泻火之剂而血愈吐，又用止血之剂，闷乱不安，饮食不进，昏晕欲死，病者医家相依为苦，闻予在江邑署中，买舟告急。按其脉小细，数而微，其势将脱，刻不容缓。予曰：此血不归经，俗医误认为火，肆用寒凉，真阳受困，恐无及也。荣庆曰：悔不听先生之言，至有今日之苦。书曰：自作孽，不可活，宜也。痛念老母年逾八旬，膝下幼子无养，望先生垂怜，自当结草。予曰：仆不居功，亦不认过也，但视有缘否耳。乃与天师引血汤，用黄耆一两六钱，当归七钱，黑荆芥穗五钱，粉丹皮、黑侧柏叶、黑姜灰各三钱，炙草二钱，官拣参一钱（另熬，冲药水），服之一剂而血顿止，略进稀粥。此方之妙，不专补血，妙在补气，尤妙在不单去止血，反去行血以止血，血得寒而凝滞不行，逢散则归经而不逆，救危亡于呼吸之间，实有神功也。再进一剂而起床，继用补中益气汤合六味地黄汤十剂，滋化源以补肾水，而行动如常。后服人参鹿茸丸一料，而元气大复也。", "18399": "向游永宁，曾治陈秀才，因父互讼被辱，怒气吐血，倾囊而出，昏晕于地，知予在孙公署内，急延予诊。按之六脉沉小，惟左关弦细而数。其兄知医，乃谓予曰：用止血药可乎？曰：不可，若强止之则气闷而不安。又问：用补血药可乎？曰：不可，若骤补之则胸痛而不受。曰：先生高论，补、止皆不可，已闻命矣，敢问治之将何法？曰：乃弟因怒气伤肝，一团郁气结在胸中，以致冲激而吐，宜逍遥散吞左金丸二剂，而舒散其肝木之郁。继服散血平气汤：白芍二两，当归一两，黑荆芥穗、软柴胡、鲜红花、黑姜灰、黑栀子各三钱，甘草一钱，水煎服。夫怒气伤肝，不能平其气，故至大吐，不先舒肝而遽止血，愈激动肝木之气，气愈旺而血愈吐矣。方中白芍多用，妙竟平肝，又能舒气，荆芥穗炒黑，皆能引血归经；柴胡舒肝神品，适是开郁之剂，所以奏功甚速，而摄血归经甚神也；至于当归，非用补血，不过佐白芍以成功耳。果服一剂而气舒，连服二剂而血无矣。再服归脾汤解郁结、生脾血，兼服八仙长寿丸加牛膝、鹿茸，以滋补肾肝而愈。", "18400": "曾治友人周大有之妾，性多欲、忽暴崩不止，昏晕床褥，适余在渝回，彼知请诊。按其脉小无力，乍有乍无，乃血脱之象。大有曰：敝妾还可治否？余曰：幸脉小身凉，可有救。危乃与安崩汤，用黄耆、白术各一两，另用人参二钱，煎汤调三七末三钱冲服，可反危为安也。夫血崩之后，惟气独存，不补气而单补血，缓不济事，今亟固其欲脱之气，佐之三七末三钱以涩其血，真气固而血自不脱也。果服一剂而崩止。吾意男女好色，均皆所同，遂与补中益气汤合六味地黄汤，大剂煎饮十余剂，顿愈。又与六味地黄丸加龟胶、鹿茸、鹿鞭三味，配服一料而元气大复。", "18401": "曾治李符山之妻，午膳后闻夫舟覆，怒气填胸，忽患血崩，四肢作逆，痰涎上涌，促骑求诊。按之六脉沉小，惟左关尺细数无伦。乃与逍遥散加黑山栀、黑侧柏、黑姜灰各三钱，炒黑马通（即干马粪，收贮经年者佳）五钱，桔梗、枳壳、半夏各二钱，白蔻一钱，为细末，调药水服一剂，吐出痰涎碗许，神思稍清，明晨进稀粥一碗。惟左乳胁胀痛，寒热往来，欲呕不呕，四肢困倦。予曰：此肝火炽盛，中州不运。遂与六君子汤加柴胡、栀仁、芥穗，而诸证顿退，惟血崩时下。其吉归家谢曰：拙荆恐肝火未息，先生用凉血之药可乎？予曰：不可，此乃心、肝、脾三经血弱气虚，宜服补中益气汤补脾土，脾统血也。连服四剂而崩止。乃与鹿茸、鹿鞭加于六味地黄丸内，兼服前汤而元气复，明年四十八双生。", "18402": "曾医廪贡王美秀，患吐血发热，其病已久，精神倦怠，肌肉瘦削，向治无效，渐见沉重，乃一日暴吐，昏晕床褥，其气将绝，周身俱冷，独心中微温，乃兄料不能起，将衣冠尽附其身，时夜将半忽苏，云到城皇祠中，父命速回，又昏昏睡去，次早促骑求治。余诊其六脉沉小而微，手足厥逆。余即用加味补中益气汤：黄耆、白术、当归、沙参各五钱，升麻一钱，柴首三钱，怀山、茯苓、麦冬各三钱，远志二钱，五味子六分，红枣六枚，干熟地八钱。煎服一剂而苏，连进二剂而饮食渐进，精神亦长。再用补中益气汤兼服龟鹿地黄丸而痊。赠我诗曰：", "18403": "曾治曾其恒乃弟，冬月患吐血，老医与以犀角、芩、连、知、柏数剂，叫楚烦乱，不能起床，其吐加剧，乃兄皇皇求治。按其六脉沉小而微，势在将脱，刻不容缓。余曰：此太少二阴中寒之证，前医不明六经，不知分经辨证、温中散邪，肆用寒凉克伐脾阴，真阳受困，故其血冲激而出，孤阳将绝，危候也，犹幸脉微身凉，谅或可救。乃与黄耆、白术各用八钱，半夏、干姜各二钱，砂仁、白蔻各一钱，碾细末，冲药水服。一剂而苏，连进四剂而血顿止，饮食渐进。因卧室当风，夜即壮热无汗，腹痛作泄，人事恹恹，又似不救之象。余细审之壮热无汗者，寒伤营也，腹痛作泄属少阴，急于前方中加肉桂、故纸大剂温里，少加麻黄、桂枝各三钱兼散太阳表邪，服一剂而热退身安，腹痛作泄俱已。改服补中益气兼服龟鹿地黄丸一料而愈，明年康壮生子。", "18404": "曾治国学阳厚重，冬月患吐血，其人本实先拨，因构讼失算，忿激暴吐，是夜呕鲜血盈盆，昏晕于地，不能床褥，举室仓皇莫措，伊戚其恒，代为请诊。按之六脉沉微。余曰：尔勿忧，是病虽险，犹幸身温脉微。经脉篇云：凡失血证，脉微身凉者生，吐衄后，其脉洪数、身热者死。足下是劳伤肺肾，又兼肝木仲郁，故其血冲激而吐，但非我不能及。乃与补中益气汤加麦冬、五味、茯神、远志、怀山、熟地，大剂煎服而安。多服补中益气兼地黄丸而愈。", "18405": "曾治门人王臣杰，受业未几，患白浊，伊岳知医，与之调理一载无效，转加吐血，饮食俱困，胀闷不安，伊师代为请治。余细察之，病在太少二阴。斯时不为之扶脾固肾，一味克削，致犯肾肝。余述丹溪云：肾主闭藏，肝主疏泄，脾主化导。今脾、肾、肝三经失职，而误用茯苓、去白陈皮泄其精气，开其孔道，以致玉关不禁，精无统摄。又妄谓为火，肆用寒凉，孤阳将绝之候，何可及也？其父变色曰：如先生之言，此子微矣。余曰：以脉决之。按之沉小而微。乃曰：王氏有福，乃郎之证虽险，幸脉微小，天犹或永其寿，尔勿忧，吾与治之。遂与黄耆、白术各五钱，砂仁八分，炒黑姜二钱，炙草、白蔻各一钱。煎服一剂而人事稍定，连服数剂而血顿止，饮食渐进，精神益增。又与补中益气汤、归脾汤生脾血，滋化源，兼服六味地黄丸壮水之主，逾月脾胃顿强，精神倍长。乃父喜形于色，其后每见，敬恭有加焉。", "18406": "曾治四弟秉珍，暴患吐血盈盆，每吐则面青，形神俱倦，不思饮食，坐卧不宁。按之六脉沉小，自胸前背心微热，心中甚紧。余曰：此少阴、厥阴二脏受伤，惟肝尤甚，因怒气所致。乃与逍遥散煎服，吞左金丸三十粒，以疏肝气，兼和脾气，二剂而血渐微。继与补中益气汤加麦冬、五味、茯神、远志、怀山、熟地、生姜、枣子，连进数剂，以摄血归经而愈。自谓强壮，即不服药，已三年矣。去冬复吐，时因贸易匆匆，不以为事，今春加剧，方来求药，仍与前逍遥散方加左金丸二剂，加味补中益气汤连进数十剂，神气清爽，饮食渐旺，身渐强壮。吾弟颜曰：今而后我再不敢不信药矣。又问：归脾汤可服乎？曰：可，但其方中去木香、甘草，加五味子、肉桂脾肾两补，兼服龟鹿地黄丸壮水之主、补血生精而愈。", "18407": "曾治徐桂之女李徐氏，年三十，患大便久下鲜血，医治三载无功，起坐不宁，昏晕床褥，饮食不进，肌肉瘦体，白若枯骨，内兄为之请诊。按之六脉沉微，势在将脱，不可救也。乃勉强作剂，用干熟地一两，当归七钱，酒芍五钱，川芎三钱，黑姜灰、黑侧柏叶、黑马通各五钱，炙草一钱，令进六剂。旬日外不见信息，余意其病必死矣。否知两旬，其兄来寓曰：余妹因近日移居，诸事匆匆，是以覊绊，今特请愚来致谢先生，并求补剂。余闻摇首曰：嘻！令妹之寿长也，李氏之福也，我之药力幸遇也，余焉得居功哉？又与补中益气汤，兼服龟鹿地黄丸，而元气大复，明年生子。", "18408": "曾治南邑张配先，其家殷实，年三十患痨瘵，前士乃用全真滋膏治之，一载无功，病在垂危，伊舅宋肇堂代为请视。诊之两寸浮大而空，余脉沉微，面部黑黯，毛发干燥，肤无润泽，形神俱疲，声哑无音，欲咳气紧，步履维艰。余曰：足下初患三阴虚寒之证，法当驱阴回阳，医者不知分经辨证，一味滋阴，以致阴愈长而阳愈亏，种种难明之疾具矣，然欲治之，非数百剂之汤药、数十斤之丸饵不可问，愈期以年计，不可以月计，仆方认劳也。彼曰：贱躯十死，只冀一生耳，先生怜而救之，敢不惟命是听。爰与补中益气汤加麦冬、五味、茯苓、半夏、诃子、银杏，三十余剂，病未增减。又与前药三十剂，兼服八味丸加鹿茸、去附子十二斤，咳声虽小，其音清亮。又三十剂，其气渐平。又服十全大补四十剂，前丸十二斤，是时冬至，明年仲春，汤丸服毕，皮肤光泽，声音谐和，欢笑如旧矣。又与人参养营汤六十剂，前丸十二斤，又明年春，病已痊愈。彼曰：再服一年，庶免后患。余曰：善。又与补中益气汤四十剂以滋化原，龟鹿地黄丸十六斤滋补肾肝，至今十五载而无恙。计服汤药二百三十剂，丸饵五十二斤，此服药之最有恒者，予亦遇之罕矣，可为较量锱铢，不知爱身惜命者示。", "18409": "向日在渝，曾治张洪泰，年五十，形体魁梧，酒色过度，本实先拨，忽吐衄盈盆，昏晕床褥，不省人事，知余在英公署中，告急请治。按其脉，右寸浮大而空，左关弦细而数，余俱沉小，皮肤微温。余曰：血势奔腾，脱证已俱，刻不容缓。乃用人参五钱，黄耆一两，当归七钱，熟枣仁三钱，浓煎二次，布漉去渣，调真三七末三钱。行内有知医者，进而问曰：血乃有形之物，今忽暴吐，则一身之中，如大兵之后，仓廪空虚，田野萧然，何况倾囊，其无血以养可知，斯时不急生血补血，先生方中一味补气，得无迂而寡效乎？余哂曰：治吐血不得喻嘉言之传，不读赵养葵《绛雪丹书》，虽皓首穷经，终归无用。经云：有形之血，不能速生，而无形之气，所当急固。当奉为吐衄之妙诀！盖血乃有形之物，气乃无形之化，有形不能速生，而无形实能先得，况有形之物必从无形中生来，阳生则阴长之义，不知补气正所以补血，生气正所以生血也。今既大吐，只存几希一线之气，若不急补其气，一旦气绝，在何地补血而生血哉？问者大悦，唯唯而退。煎服一剂而苏，血亦顿止。又与归脾汤去木香、甘草，加五味、肉桂煎汤，调鹿茸末数十剂，兼配六味地黄丸一料服之而愈，元气大复。", "18410": "曾治庠生聂子闻，年十八，患吐血，屡治不效，乃堂伯灼三公，为人孝友，视侄如子，来寓求诊。按之右关微涩而芤，余脉如常。余曰：饮食所伤，而致吐血。乃与理脾涤饮四剂，饮食有味，精神渐爽。忽又吐血甚多，其伯曰：恐干姜燥动其血。余曰：非也，今多吐者，早有停蓄，乃为积满之故也，皆由脾胃气虚，致不能传布，法当理脾健胃，大补中气，宣畅胸膈。又服数剂，而血渐止。乃与补中汤加麦、味、茯神、远志、怀山、熟地，兼服六味地黄丸加五味子、鹿茸而愈。", "18411": "赵氏曰：治以肾肝为主。经曰：阴阳之要，阳密乃固。苟阳强不密，阴气乃绝。阴平阳密，精神乃治。阴阳离决，精气乃绝。夫所谓阳强者，乃肾肝所寄之相火强也。所谓阴绝者，乃肾中所藏之真阴绝也。肾为阴，主藏精；肝为阳，主疏泄。是故肾之阴虚则精不藏，肝之阳强则火不秘，以不秘之火，加临不藏之精，除不梦，梦即泄矣。或问曰，何故不为他梦，而偏多淫梦耶？答曰：《灵枢经》淫邪发梦篇云：厥气客于阴器则梦接内。盖阴器者，泄精之窍，主宗筋，足太阴、足阳明、足少阴、足厥阴之筋，与夫冲、任、督三脉之所会，诸筋皆结聚于阴器，而其中有相火寄焉。凡平人入房，而强于作用者，皆此相火充其力也。若不接内，不与阴气合，则精不泄。一接内，与阴相合，则三焦上下内外之火，翕然而下从，百体玄府悉开，其滋生之精尽趋阴器以泄，而肾不藏矣。若其人元精坚固者，淫气不能摇，久战而尚不泄，况于梦乎？纵相火动而成宵梦，梦亦不遗，此谓阴平阳秘，无病人也。今人先天禀赋原虚，兼之色欲过度，以致肾阴衰惫，阴虚则火动，相火之系，上系于心为君火，感物而动，动则相火翕然而随，虽不交会，而精已离其位，即客于阴器间矣，夜卧时，当所寄之相火一遇与接内时，与阴气相合同，故卧而即梦，梦而即遗矣。若肾不虚，则无复是梦，梦亦不遗也。故治是证者，先以肾、肝为主。或又问曰：阴虚火动而梦遗，服丹溪补阴丸以滋阴降火，则证与药相对，每依法服之，而不效何也？答曰：此未得丹溪之本义也。盖丹溪心法第一方，原以肾气丸为滋阴之要药也，今人不会其意，以黄柏、知母为君，概用坎离丸、固本丸之类，凡此皆沉寒泻火之剂，苦寒极能泻水，肾有补而无泻，焉能有裨于阴哉？独薛立斋发明丹溪之所未发，专用六味地黄丸以补肾，而治梦遗屡效，纵有相火，水能滋木，水升而木火自息矣。倘有脾胃不足，湿热下流者，以前丸为主，煎服补中益气汤以升提之。有用心过度，心不能主令，而相火代事者，亦以前丸为主，而兼用归脾汤。有命门火衰，元精脱陷，玉关不闭者，急用八味、锁正丹以壮真阳，使之涵乎阴精而不泄，此其大略也。", "18412": "吴茭山有治遗精得法论云：一男子用心过度，遂梦觉而遗，多痰瘦削，诸医以清心莲子饮，久服无效。吴先生诊其脉紧涩，知冷药利水之剂太过，致使阴气独降，服此愈加剧矣。余以升提之法，升坎水而济离火，降阳气而滋阴血。次用鹿茸、人乳填补精血，不愈月而痊愈。", "18413": "曾治魏孝廉，发热遗精，或小便不禁。诊其脉，右寸浮大，右关微弦，左寸关俱沉微，两尺俱迟而芤。余曰：此劳伤脾肾，俱属亏损。遂与补中益气汤合六味地黄丸料，煎服十剂顿愈。劝令多服补中益气汤以滋化原，兼服六味地黄丸壮水之主，至今不发。", "18414": "曾治春桥茂才魏表弟，禀性刚直，为人厚道，素患中气不足，遗精唾血。愚于庚午春诊之，右寸脉大于五部，惟左尺沉迟而芤。余曰：足下之恙，乃浊气下降，清阳不升，中州郁滞，脾失健运，黄庭衰败，不能摄血，兼以肾气涣散，或观书久坐，或作文用心，每劳必遗精，缘因茯苓、陈皮疏泄太过，一味滋阴，以至阴愈长而阳愈亏矣。春桥曰：分经用药，阳生阴长，既闻命矣，敢问治之当何法？答曰：明乎哉问也。乃用黄耆、白术大补中气，益智、故纸收司肾气，砂仁、半夏醒脾开胃，干姜、白蔻宣畅胸膈，使中州气壮，转运有权，肾气收藏，胸中之气肃然下行，再加煎当归、茯神、远志、枣仁安神益智，麦冬甘寒润燥金而清水源，五味子酸温泻丙丁而补庚金，更以鹿鞭大补肾阳，耆、术、参、茸温补黄庭，益其气而举其陷，则肾自固而精自守。再服龟鹿地黄丸，壮水之主，大补精血，可保长年矣。彼见余议病精确，依法调理而安。明年冬，以书谢我曰：三折妙手，俾得远近回春；万应仙方，普动亲疏诵德。弟不知何修而得遇此矣。沐恩愚表弟奇逢顿首。", "18415": "甲戌冬，又因惊闻戚友家难，不忍坐视，代为忧郁，前证复作，偶因外寒，邪中章门，痛如刀插，人即昏晕，倒卧床褥，乃兄仓惶，急延予诊。按之六脉已伏，惟右寸浮大，乍有乍无。细察其候，脱证已具八九，刻不容缓，乃与逍遥散舒肝气，归脾汤解郁结，合煎一剂而苏。明早复诊，脉出如常矣。以理脾涤饮加草蔻一钱，煎服二剂而安。春桥复问余曰：章门结块，痛似刀插，又兼麻木，人即昏晕而脉即伏，果为何证？余曰：窘乎哉问也，其理莫措，静而筹之，明日方得其解。麻乃血虚，木乃湿痰，皆脾肾经寒所致。缘君平日憨直善怒，怒则未有不伤心、肝、脾三经者也。理脾涤饮乃对证之方，兼服归脾汤解郁结，生脾血；补中益气汤壮脾胃，生发诸经；龟鹿地黄丸以滋补肾肝。汤丸并进，自必永寿。丙子秋，又书曰：弟自幼至壮，多病床褥，父母常忧不寿。庚午春，天以兄台赐弟一饮，妙剂回生，不独弟蒙深恩，即堂上白发亦暗自怡颜，以为弟身强壮，可以读书，稍慰于万一耳。沐恩愚表弟顿首禀谢。", "18416": "曾医优生雷大壮，赋性端方，为人诚厚，素患遗精，缘因先天不足，中气大虚，虽自调养，究之治未得法。丙戌之秋，病卧床褥，脱证已具，举室仓惶，乃弟求诊。按之六脉沉微，右寸脉大而空，左尺迟细而芤。察其色，询其状，肾气涣散，屁无休息，尤兼下利，不能收固，心慌之极，自知其不可为矣。余哂曰：不妨，观子面白唇红，声音清亮，目精尚慧，生气勃勃，雷氏尚有福庇也，纵病虽重，吾药可解，子何忧哉？乃与黄耆、白术大补中气，砂仁、半夏醒脾崇土，胡巴、故纸收固肾气，怀山、芡实、莲子兜塞大肠涩以固脱。大剂多服，使精生神足，肾气收藏，元气自复。兼服龟鹿地黄丸加牛膝、虎胶壮水生津，强筋壮骨。如法调理，果逾月而安。", "18417": "脉大而虚浮而濡者汗，在寸为自汗，在尺为盗汗。", "18418": "自汗属阳虚，盗汗属阴虚。伤寒之脉，阴阳俱紧，法当无汗，若自汗不止，名曰亡阳，不治。", "18419": "若内伤自汗，属阳虚也。法宜补中益气汤加熟附子、蜜炙麻黄根、浮小麦、老桑叶、姜、枣煎，黎明服之，其神效捷于影响。但升麻、柴胡必要蜜水炙过，制其勇悍升腾之性，又欲引参、耆入肌表，不可缺也。浮麦收汗，桑叶止汗，更不可少也。如左寸脉浮洪而自汗者，心火炎也，前方倍参、耆，加麦冬、五味、川连；左关脉浮弦而自汗者，挟风邪也，本方加桂枝、白芍，阴不虚者，白芍不用；左尺脉浮洪无力而自汗者，水亏火旺也，前方重加生地，或重加熟地，尤须斟酌；右寸脉浮大而无力者，自汗不止，前方加五味、枣仁；右关脉浮洪无力而自汗者，前方倍参、耆；右尺脉洪大无力而自汗者，或兼盗汗，乃相火挟心火之势而上伐肺金也，又宜当归六黄汤。", "18420": "曾治黄孝廉，素勤学，因冠早，患梦遗滑精，发热盗汗，医以清离滋坎汤，唾痰见血，足热痿软。又与四物汤加知、柏，其汗更甚，促骑求治。六脉皆浮，余察其色，闻其声，问其因，知其病，即与补中汤加麦、味、茯神、远志、怀山、干熟地数十剂，兼服八仙长寿丸而愈。", "18421": "门人向于夫子曰：吾师医太平乡之证，人皆称奇，弟子愿闻其详。答曰：晰理精深，难为不知者言也，今为子言之。其人因家难不决，数月一闷，忿怒不已，岁底归家，抱病不堪，神识不清，不知昼夜，欲寐不寐，惺惺达旦，医家为之安神开郁，病转加剧，求予诊视。脉微如丝，按之即绝。人事不知，饮食不下，翕翕微热，濈濈微汗，昏眩少气，欲言不出，且又兴阳强良不已，每夜将半，胸中攘扰，而气欲脱，五更方安，日中亦然。客问曰：此病阳虚之极，何得肾阳复强？予曰：明乎哉问也。此乃孤阳下陷，为阴所逼，阳从下竭之证也。客又问曰：胸中扰攘，痰乎？气乎？予曰：窘乎哉问也，并无形迹，其理莫措，静而筹之，明日方得其解。其人抱闷终日，默默不欲人言，静而生阴也，浊阴壅遏胸中，冒蔽清阳，所以神识不清，且饮食不下，子午二时阴阳代谢，因其阴过盛，不容阳进，代谢之顷，故有此脱离之象。其所以不得寐者，亦为孤阳不得与强阴交也。然此证非外邪直中之阴，不可以附、桂等药驱而逐之，法当大补其阳，阳旺则阴消，阴消阳不陷，且肾火必自安，而阳亦自不兴矣。方用耆、术、参、姜、远志、白蔻，一剂而效，十余剂而安。", "18422": "百病之客乎人身也，必有因以客之。经曰：邪之所凑，其气必虚。不治其虚，安问其余？又曰：治病必求其本。诚万世之医旨也。假如发热脸红，烦躁，似有余也，然究其本，乃脾胃气虚不能传运，则虚乃其本也，理宜推扬谷气，助脾消化，方称医手，若徒从标攻伐，则内伤之患接踵而至。更如伤风感冒，头痛壮热，虽似有余，所谓邪气盛则实，实因卫气不固所招也，若纯用猛剂发散，则表气愈虚，外邪之乘虚而入，何时而已耶？更加咳嗽喘促，烦躁不安，肺气热盛，似有余也，细究其源，非水不能制火，即虚阳上浮，设从标理肺为事，治虽暂愈，而发愈甚。故凡外凑有余之证，即本经正气不足之时也，若不从源调治，正当不足而更不足之，虚者愈虚而危亡继其后矣。明通之士，贵乎顾本求源，杜危防险，则病根永绝，正气发生，其病全去，长年可保。慧自入杏林，迄今五十年矣，凡治伤寒外感一切虚实之证，均遵长沙公之法，分经治病；其余春夏秋三时之杂病，察其证见何经，即用何经之药以治之，百发百中。至于内伤诸证，其所用者，多以补中益气汤、理脾涤饮二方出入加减，以理脾胃。至于阴虚、阳虚，即以六味、八味壮水之主，益火之源。其余六君、四物、八珍、四君、十全、养营、归脾、独参、生脉、理中，对证用药，效如桴鼓。不敢私秘，敢以尽告同仁。", "18423": "夫虚者宜补，然有不受补者，非不受补，乃补之不得其法也，必须凭脉用药，不可问病执方。", "18424": "六脉一部或大或小之间，便有生克胜负之别；一方分两或加或减之中，便存轻此重彼之殊。脉有真假，病有逆从。假如六脉洪大有力，此真阴不足也，宜六味地黄汤。右寸更洪更大者，八仙长寿汤。如脉洪大而数者，人谓阴虚阳盛者，用知柏地黄汤则误矣。如果真阳盛实，则当济其光明之用，资始资生，而致脉息有神，急徐得次，以循其常经矣。惟其真阳不足，假阳乘之，乃龙雷之火妄作，疾乱变常也，宜八味地黄汤加五味子、肉桂，助天日之阳光，以逐龙雷之假火，方内去附子。至若弦数、细数，则更系真阴、真阳亏损，宜当大剂八味地黄汤服之，以火济火，类既可从，承乃可治，火既制而阴易长也，况脉之微缓，中和胃之气也，不微而洪大，不缓而弦数，近乎无胃气之象，用此既补真阳以息假阳，复藉真火以保脾土，此补肾中真阴、真阳之至论也。更有劳心运用太过，饥饱劳役失调，以致后天心脾亏损者，设以根本为论，徒事补肾则元气反随而陷，化源既绝于上，肾气何由独足于下，纵下实而上更虚也。", "18425": "又若六脉浮大无力者，此乃中气不足，营阴有亏，而失收摄元气之用，宜于温补气血之中加以敛纳之味，如养营汤用五味子，更宜减去陈皮是也。", "18426": "六脉沉细无力者，此元阳中气大虚，大宜培补中州，温补气血。盖脾胃既为气血之化源，而万物之滋补，亦必仗脾胃运行而始得，故古诸方药中必用姜、枣，即此意也。况中气既虚，运行不健，故用辛温于中鼓舞，使药力自行，药力不劳脾胃之转输，如归脾汤之用木香、十全汤之用肉桂是也。", "18427": "如六脉迟缓甚微者，则元阳大虚，纯以挽救阳气为主，轻则人参理中汤，重则附子理中汤，不得杂一阴分之药。盖阳可生阴，阴可化阳耳。", "18428": "如六脉细数，久按元神者，此先天、后天之阴阳并亏也，早服八味地黄丸，晚服人参养营汤去陈皮，或十全大补汤去川芎，生地换熟地可也。", "18429": "先天之阳虚补命门，后天之阳虚温胃气；先天之阴虚补肾水，后天之阴虚补心肝。盖心为血之主，肝为血之脏，然更重乎足太阴脾也。夫脾者，营之本，化源之基，血之统也。且一方之中，与脉有宜有禁，宜者加之，禁者去之。如应用十全大补汤，而肺脉洪大者，则芎、耆应去，而麦、味应加者也。盖川芎味辛而升，黄耆味甘气厚于味，故功专肺脾而固表也。", "18430": "六脉无力，十全最宜，倘无力服参者，以耆、术倍用，只用当归，勿用地、芍、盖重在补气则当归为阴中之阳，地黄、白芍为阴中之阴耳。", "18431": "至于地黄一汤，依脉轻重变化，万病俱见神功。若六脉沉微，亡阳之证，暂所忌之。盖虽有桂、附之热，终属佐使，而熟地黄、山萸肉一队阴药，乃系君臣，故能消阴翳之火也。其熟地黄重可加至二三两，山萸只可用三四钱，盖酸味独厚，能掩诸药之长，况过酸强于吞服，便伤胃气矣。", "18432": "以上治有余之法。至于不足之证，乃虚劳汗多，五内枯燥，脂腴既去，不能生津，膀胱中原无水积而欲通之，如向乞人而求食，穷而益穷矣。故东垣分在气分、在血分而治之，以渴与不渴辨之。如渴而小便不利，此属上焦气分，水生于金，肺热则清化之源绝矣，常于肺之分助其秋令，水自生焉。如天令至秋白露降，须用清金之药，如生脉散之类为当。又有肺虚者，盖因饮食失节，伤其胃气，陷于下焦。经云：脾胃一虚，令人九窍不通。用补中益气汤，以参、耆甘温之品先调其胃气，以升、柴从九原之下而提之，则清升而浊自降矣。清肺者，隔二之治也。补脾者，隔三之治也。东垣虚则补母之妙用，类如此。此皆滋夫后天之化原者。如不渴而小便不利，此属下焦血分。下焦者，肾与膀胱也，乃阴中之阴。阴受热，闭塞其下流。经曰：无阳则阴无以生，无阴则阳无以化。若淡渗之药，乃阳中之阴，非纯阴之剂，阳何以化？须用滋肾丸，此气味俱阴，乃阴中之阴也。", "18433": "语云：能治十男子，莫医一妇人。盖言审病认证之难也。何则？凡治病不外望、闻、问、切四法，然妇女见人，颜色每多娇羞，声音每逾卑小，则声不得其正，色不得其平，而脂粉丛中，又不得任我之回详审视，则望、闻之法废矣。且病多不便之端，难为告语，欲诘其所以，询其所由，莫得一二，诊其脉气无定，纺缉织纴之余，脉因而动，目瞑嗜卧之际，脉因而静，而问、切之法又废矣。自非悉心观变，阐明至理，乌能临证别有一种元机，遍见五内而方药得当哉？然男妇之病，不外性情之邪正，由正而致病者，其病虽险而奏效亦速；由邪而致病者，其病虽浅而见功尤难。慧入杏林，阅历有年，常见德性温良、举止端庄之妇，孝敬公姑，相夫教子，勤务女工，厨灶井臼，鸡犬桑麻之事，俱皆一一尽善，此女中君子也，必无灾病，偶或起居失节，饮食失宜，感冒风寒，亦易为治。若逆妒险恶，失敬失养，夺夫之权，罔尊凌卑，醉饱自耽，全无妇德，又见一等自不生育，不容纳妾，致夫绝嗣，此罪重恶极，天教病入膏肓，即有卢扁再生，亦难治疗。余痛识此弊已久，今于妇科篇首，因立医方，借作劝戒。至于分经辨证，按法治病，惟驰远之书，于妇科门中独步千古，余不揣谫陋，略为增补，附录之，以为后学广一津梁云尔。", "18434": "又见怀孕七月者，漏下清水，时值秋分之际，燥令大行，乃为肺经受燥。医者不识，谬执成法，以为脾虚，而用耆、术、砂、半之药不效。又谓药不胜病，再加大剂十余服，水更加甚，而胎落矣。其后仍复下水，医谓小产后元气暴虚，更重用大补数剂，而证变喘促直视，口不能言。延予诊之，右寸洪劲无伦，面色焦槁，肌肤熯燥，鼻靥煽动，吾知其不可为矣。乃斥医者曰：子谓脾虚，何所征验？盖脾虚者，当必自利不渴，今大便结硬，口干心烦，乃为秋燥伤肺，其气下迫胃中，津水长驱而下，而反用耆、术、砂、半健脾，愈助其燥而肺愈伤，今见脉动无伦，鼻靥煽动，乃肺气立绝之候，尚何可为哉？医者不能置喙，少顷气涌而死矣。冤哉！惜予遇之不早也。", "18435": "明年九月，又有怀孕七月受秋燥而漏下清水者，其证与前死者无异，其家惧而求吾药。诊视之，依然右寸脉洪劲，皮色干枯，心烦不眠。吾用天冬、麦冬、玉竹、蒌仁、阿胶、鸡子白以清肺燥，桔梗开提，甘草和中。一剂而效，五剂痊愈。可见安胎必当治病，病不能除，命且去矣，可不慎欤！", "18436": "又医产后一证，身重恶寒，饮食不下，大便泄，小便不利，腹中痞块作痛，庸工谬谓血气，用元胡四物汤加蒲黄服之无效，转加膨胀矣。于是再加厚朴、木香，则胀满加剧，凑上胸膈，喘促不能卧。予曰：其身重恶寒者，少阴证也；腹中痞块作痛，阴寒凝结也；食不下者，阴邪逼塞胃口也，且阴邪下奔而作泄；膀胱无阳，其气不化而小便不利。凡此皆为病在气分，彼妄投血药，阴愈长而阳愈消。又误破其气，则气亏而邪愈凑，其证危矣。吾用砂、蔻、姜、半宣畅胸膈，温醒脾胃，附子御阴，肉桂化气，使上焦得通，中枢得运，而后气化行；桔梗开提，生姜升散，俾转运之机乃得先升而后降。一剂而小便通，胸膈略宽。再加耆、术，三剂而腹痛止，胀渐消，饮食加健，身复发热。其家曰：表见发热，何故也？予曰：真阳来复，休征也。经曰：伤寒先厥后发热，下利必自止。再重加黄耆、白术而泄止，其胀更消。忽加口渴，腹中作饿，食未久又索食，其家恐服附、桂助起胃火，故能消食，商议改用清凉。余曰：不可也。经曰：脉滑而数，手足自温，渴欲饮水，饥欲得食，此阳进欲愈之证也。再加益智、故纸收固肾气，又二剂而身轻，腹胀俱消。再加覆盆、菟丝、鹿鞭兼补肾阳，数剂而痊愈矣，痞块消弭。终无血行下者，调理两月，经信行通如故。", "18437": "其证卒然昏迷，颠仆身痛，有青筋，以乱发搓痛处，是则发卷成团而硬，即用两宝浓煎服。不愈，加甘草。发不卷硬者非，另察其脉证在何经，即以何经之药施治之。", "18438": "舒驰远曰：余按：疫有九传者，病人皆得其一，非一病而有此九也。证有表里轻重，而法之宜先宜后即出其间。其先表而后里者，此非表邪入里，乃膜原伏邪溃有先后也。先溃者先传，后溃者后传。若先传表者，则表证先见，宜先传表。表解已，而里证后见者，乃后溃之伏邪至，是方传里也。其先里而后表者，亦非里邪外出，仍是后溃之伏邪至，是方传表也。至于表里分传，亦是伏邪分溃也。其初用表药之时，亦不可不先看其本气。虚寒者宜加附子，火旺者宜加芩、地、石膏等药。用下亦然，元气虚者，承气汤中宜加人参、黄耆；阳虚者，宜加附子；阴虚者，倍用生地熬膏煎药。凡此皆法中之法也。其表而再表者，是方解其表，而表证复见，此亦伏邪以次第而溃也，故不妨再表之。其里而再里者，是下去其结，而腑邪复结，亦伏邪以次第而聚胃也，再一下之则愈。至于下后诸证，总在相其津液。其溃邪传表，身发热而脉续浮者，法宜分经解表。假若舌上依然干燥，气喷如火，则表药不可用，又宜白虎汤重用石膏、知母、甘草、粳米，倍生地以救津液，乃得自汗而解。其津干饮结者，栝贝养营汤：栝蒌实、知母、贝母、花粉、苏子、当归、白芍、橘红。阴枯血燥者，清燥养营汤：重用生地一两，花粉、归身、白芍、陈皮、甘草、知母，灯心酌加。里邪未尽者，承气养营汤：归身、知母、厚朴、生姜、枳实，大黄生熟并用，生地倍加。本气虚寒，下后微恶寒者，又宜参、附以温补之，养营又所当禁，立法诚大备矣。而醒医六书，医家又不可不留心考究焉。", "18439": "吴又可曰：应下之证，下后当脉静身凉。今反发热者，此内结开，正气通，郁阳暴伸，此不久自愈。仍有余邪未尽，当明辨表里，用法以消悉之。", "18440": "及至己丑、庚寅年间，痧证复作，乡村城市皆有，或为暗痧、闷痧、痛痧、落弓痧、噤口痧、扑鹅痧、角弓痧、盘肠痧，或又有因伤寒疫痢暨夫胎前产后诸证而兼发痧，甚有阖门被祸，邻里相传染者不可屈指。余尝临证救急有三法焉，如痧在肌肤，刮之而愈；痧在血肉，放之而愈。斯二者其痧尚浅，虽重亦轻。痧之深而重者，胀塞肠胃，壅阻经络，直犯心君，命悬旦夕，扶之不起，呼之不应，而痧胀已极难于刮放矣。呜乎！病邻于死，谁不伤心，非药救醒，乌能回生？则刮、放之外，又必以药济之。惟智者三法兼备，救生而生全其如。世人只知刮、放，少知用药，因而枉死者多。或有云诸书不载，非药可疗。不知载籍之内原有绞肠痧，有云青筋，有云中恶，此皆痧之散见诸书，但略而不详，且历代未有专家耳。夫痧有真头痛，朝发夕死，夕发旦死，记载头痛之条。痧有真心痛，亦夕发旦死，早发暮死，载在心痛之例。此二证者，虽属不治，若能见机于早，或从痧胀门中揣摹治之，或可挽回于无何有之乡。况痧有为头痛而肿胀，一似大头瘟；痧有为咽喉锁闷，一似急喉风；有为眩晕昏闷，倏焉云亡，一似中风中暑；有为喑痖沉迷，身体重痛，一似惊魂落魄。此皆势在危急，刮放不及者，非药将何以救之乎？且痧有头痛、寒热，类于伤寒；咳嗽、烦闷，类于伤风；与夫疟而兼痧，因痧而化疟；又有痢以痧发，痧缘痢生。而痧证百出，传变多端，更有吐衄、泻血便血，因痧而得者有之；更有大肿大毒，流火流痰，由痧而生者有之；或又有胎前产后，气郁、火郁、食郁、血郁，而痧之兼发者有之；或又有痧而手肿足肿，手痛足痛，连及遍身不能转侧者；或又有痧而胸胁肚腹结成一块，一似痞懑，一似结胸者有之；或又有痧而吐蛔、泻蛔、食结、气结、血结者有之；或又有痧而心痛、胁痛、腹痛、腰痛、盘肠吊痛、遍身疼痛，几不能生者有之。况痧又有内证所伤，将邻于死者，男方犯此，一似蓄血而血分之治法不同；女子犯此，一似倒经而气分之治法亦异。痧之为病，种种害人，全在医家望色、闻声、问因、切脉，真假认证的确，投药乃应。痧在肌肤，当刮即刮；痧在血肉，当放即放；痧在肠胃、经络与肝、脾、肾三经，当药即药。若痧气肆行，不拘表里，传变皆同，务宜三法兼用，其效捷于桴鼓。语云：救人一命，胜造七级浮屠。此慧屡经试验，敢为先生畅发其义焉。", "18441": "治病必须凭脉，若犯痧胀，则脉不对证，证不合脉，或云痧筋为据，亦惟现外焉。夫痧胀有为食积、血痰阻滞者，或阻于上，或阻于下，或阻于左，或阻于右，或阻于两胁，苟非认证的确，求其中病也，难矣。治痧一见脉有不合，先看痧筋，次审气色，三听声音，四问犯病之由。其间或有食积、血痰阻于上、中、下、左、右各处之分，须细辨其病原，庶乎用药不误。凡痧脉有一部独异，有六脉俱异，而异之中，亦有阴阳、寒热、表里、虚实、脉息之神气可辨，并非一端可执，惟善医者审之。", "18442": "痧脉十二经辨", "18443": "脉芤而浮者，手太阴肺痧也；脉芤而数者，手少阴心痧也；脉弦长而动者，足厥阴肝痧也；脉芤大而滑实者，足太阴脾痧也；脉沉细而动止不匀者，足少阴肾痧也；手阳明大肠之痧，类于肺而长；手太阳小肠之痧，类于心而细；足少阳胆之痧，类于肝而数；足阳明胃之痧，类于脾而紧；足太阳膀胱之痧，类于肾而浮虚；手少阳三焦之痧，脉必怪异。", "18444": "伤食之痧，脉多战动；伤血之痧，脉多芤滑；伤暑之痧，脉多洪滑而疾数；伤风之痧，脉多沉微；秽浊之痧，脉多变异不常；伤气之痧，脉多沉伏或形如雀啄；伤湿之痧，脉多沉细。痧证之脉，与诸证之脉不同。如伤寒、伤风之脉，一兼痧证，其脉必变，病必凶暴是也。凡遇杂证兼痧皆然。", "18445": "痧中于里，则痧气壅阻，毒攻心膂，立时发晕，放痧、刮痧皆不中用，强于发晕时放之，气血不流，即有些虚，不过紫黑血点而已，此痧毒深而凶危立见。惟智者能审脉辨证，果系风、寒、暑、湿、燥、火、气血、食积、痰饮，审在何因而施治，候其苏醒，气血活动，然后扶起放痧，细心调治。倘或不醒，再用牛黄丸、三香丸、救苦丸，亦庶乎可以挽回此等危候，曲全其生，德莫大焉。", "18446": "痧证轻者，脉固如常，重者脉必变异。若但据夫脉，不识痧筋，势必据脉用药，而脉已多变，则实病变虚，虚病变实，诚不可恃。倘脉证不合，认痧筋有无，有则据痧用药，无则据脉用药，尤须兼望、闻、问三法行之，方无差误。", "18447": "曾治长邑县令曹秉让来郡，患遍身肿胀，势在危急，吴友迫视。见其手足俱肿，将逮胸腹，诊之脉微如丝，视腿湾十指，青筋交现。命刺之出紫黑毒血，乃命冷服宝花散及桃仁红花汤，肿痛消而回县。", "18448": "曾治长邑明经邓庚兄来寓谒见，发晕昏迷。余即诊之，两寸芤而散，余脉如常，重按歇指。此暑热秽气触犯心君。先与宝花散、薄荷汤，继与藿香汤冷服，觉醒扶起，速刺腿湾三针，用沉香阿魏丸、薄荷汤微冷饮之。稍愈，用四物汤调理而痊。", "18449": "此证倏忽昏迷不醒，或痰喘不已，眼目上吊，形如小儿落弓证。此暗痧难识，必须审脉辨证，果是痧毒，摹身上凉热，唇上燥润，细心治之。", "18450": "曾治泸阳汤时顺，首夏忽发热口渴，昏迷不醒，两目上翻。延余诊之，六脉微细而伏。先与宝花散调砂仁汤冷服而苏，扶起放痧，出紫黑毒血。继与救苦丹及大黄细辛丸调砂仁汤，稍冷服。又与防风散痧汤加金银花、丹参、山楂、莱菔子而安。", "18451": "默默不语，语亦无声，形如哑子，此乃痧气壅盛，热痰上升，阻逆气管，故咽喉闭塞。治宜先放其痧，审肺、肾、脾三经之脉，而后推详余经，则问起于何时，得于何因，则病源自知矣。", "18452": "曾治泸阳周长庚，忽患痧胀，心中烦闷，昏昏不言。延予诊之，左脉有力，右脉沉微。余曰：怒气伤肝，痧气阻塞肝经。刺腿湾紫筋三针，血流如注。又刺顶心、臂、指二十余针，乃与三香散、陈皮厚朴汤加元胡、香附，微温饮之而愈。", "18453": "右陶治贾公清，腹痛如绳绞。诊其脉，大而数实。放痧不应，乃与乌药顺气汤加大黄下积而愈。", "18454": "又治何君雅子，暮春患盘肠绞痛。诊之脉伏。令刮、放痧，乃与沉香郁金散、棱术汤冷饮之稍愈。将晚，复绞痛异常，喊叫不已，又与细辛大黄丸，清茶微冷饮之，继用紫朴汤而痊。", "18455": "右陶治张显如，患头痛发晕沉重，六脉俱伏。刺颠顶百会穴一针，余痧筋俱刺，少苏。复诊其脉，沉实而上鱼际，用清气化痰饮，冷服而安。", "18456": "右陶治黄敬宇内室，腰中大痛，强硬如板，误饮热酒，发热烦躁，昏沉痰壅。左尺虚微，右尺洪实，脉且歇指。此痧中于肾也。刺腿湾痧筋，仅有紫黑血点不流，用降香桃花散，微冷服，腿湾痧筋复现，刺二针，血流如注，痧退痛减，调理而痊。", "18457": "右陶治朱子佩内室，患身热、吐痰、胁痛，饮汤喘呕不已。左脉洪数，右脉似伏。余曰：痧也。刺腿湾痧筋二针，不应，令服童便，喘、呕稍减。乃与阿魏丸、大黄丸，白汤微冷下，三剂而瘳。", "18458": "曾治王子男，痰气壅盛，凶暴痛极。延予诊视，脉多怪异。余曰：此三焦命门痧也。阅臂湾手指筋刺十二针，腿湾二针，出紫黑毒血。乃用救苦丹、沉香郁金散，清茶冷饮之；外吹冰硼散。继与荆芥金银花汤，微冷饮之，二剂而愈。", "18459": "曾治汪名扬，心中烦热，头眩，两目红肿如桃，其痛不可忍，因饮热酒，眼珠突出，左目尤甚，是晚昏沉发晕。延余诊之，左脉微细无根，乃痧毒为害。放痧不应，乃用两宝、茜草、连翘、黑栀、枳壳、丹皮、赤芍、牛膝、石斛、草决明煎，和入童便，微冷饮之，眼珠方收，调理而安。", "18460": "曾治杨和明，重九登高，忽寒热如疟，心腹绞痛，吐泻不已，六脉沉紧，是瘟痧为害也。用沉香阿魏丸，清茶微冷下。继与和脾宣化饮，入大黄二三钱合煎，微冷饮之。次日再服而愈。", "18461": "曾治张天元室人，患胸腹中气不舒畅，惟盘旋绞绞于胸腹肠胃中，喊叫几死，将近一日，时晚延治。余诊其脉，洪大无伦。余放指头痧二十余针，乃与救苦丹、沉香丸，清茶稍冷饮之。继与防风胜金汤加桃仁、红花，服之而安。", "18462": "又治牛四美，患胸腹迷闷，作苦之极，自谓死无所逃，举室惶惶，迫予诊治。按之右脉俱伏，左脉洪大无伦。即放指头痧二十余针，遂与白矾汤冷饮二碗，吐去新食。继与蒲黄饮去姜黄，加莱菔子，微冷饮之而愈。", "18463": "曾治从元孙仲子，犯喉疳证，脉细而数。视腿湾痧筋放五针，出紫黑毒血，外吹冰硼散，服清凉至宝饮减细辛，加射干、连翘、枳壳、牛膝、贝母，微温饮之而安。", "18464": "曾治徐四可，患重舌，苦不可言，连更数医不应，促骑求救。按之左寸沉细，右关无力。据证宜补，据脉宜凉，余知其有痧，令放腿湾痧筋十三针，出紫黑毒血。乃与清凉之味加川连，吹用引涎之药多加冰片，药以温凉服之，调理五日而痊。", "18465": "曾治万鹤鸣，右耳肿痛，日夜不安。诊之脉微而紧。放腿湾痧十三针，出紫黑血甚多。乃服清凉至宝饮减细辛，加射干、连翘、枳壳、牛膝、贝母，微温饮之而安。", "18466": "曾治庄以恭次子，发热面赤，痰涎如锯，两目上视，昏迷之极，诸医不应。余在兴邑，回寓诊之，脉数急甚。乃与圆红散稍冷饮之，然后刮痧。痧起，用和脾宣化饮研细辛大黄丸，微冷饮之而愈。", "18467": "曾治梁尔章，筋骨疼痛，卧床一载，诸医不应。延予诊之，右脉微弦，左脉沉细。视腿湾痧筋放之，俟紫黑毒血流尽。乃与圆红散，微温饮之。继与蒲黄饮加五灵脂、天丁，温服四剂而愈。", "18468": "右陶治盛昭元次子，患猪痫风六载，其脉浮紧而数，阅痧筋放之，脉乃平。即以沉香滚痰丸，微温汤饮之，遂果不发。", "18469": "曾治徐知州妾，犯羊痫风七载矣，已生二子，诸医不应。延余诊之，六脉紧伏不匀。视其手臂、两侧少阳穴有痧筋，现放之。乃与沉香滚痰丸，微温汤饮之，遂不再发。", "18470": "右陶治胡丹子，七岁出痘，脱痂光洁，饮食如常，行动如故已二十五日，忽然喊叫不已，发晕欲死，人皆以为痘后余毒。诊之六脉俱微细而伏。乃曰：痘后余毒，脉当沉紧有力，今微细而伏，若此脉证不合。视其痧筋，历历可指，刺出紫黑毒血，不应。乃与荆芥金银花汤合和脾宣化饮，稍冷饮之而苏。后小腹痛，变为痢疾，用当归五钱、楂肉二钱、酒军二钱，入童便，微温饮之。稍安，仍用前药去酒军，四剂而愈。", "18471": "曾治俞光斗之妻，孕娠七月，闷乱不安，寒热交作。延余至时兼痧已发，脉尚未现，用药不应，更渐昏沉，如痴如醉。明早复脉，左脉俱伏，面色微黑，方知其有痧也。令视其腿湾果有青筋，刺六针，出紫黑毒血，稍安。乃与真桑寄生、红花、益母草、荆、防、吴曲、莱菔子煎汤，冲砂仁末调冷服之。继与小柴胡汤，用黄芩退少阳之腑热，加茯苓、归、地以健脾养血而安。", "18472": "曾治贡生梁尔常之侧室，产后七日，周身疼痛，寒热往来，昏沉之极。诊其六脉，乍隐乍现。视其中指、无名指稍黑，方知兼痧也。刺二指各三针，出紫黑毒血，臂湾一针，舌底一针，痧退。用归、术、地、芍，加桃仁、山楂、益母草四剂，寒热乃退，调补月余而元气康复。", "18473": "妇人隐疾，多有兼痧，最难认识，惟在审脉。倘脉不合，更当秘问其夫，方知病情，庶不致误耳。", "18474": "曾治俞清庭室人，血淋半载矣，头面手足俱肿。诊之六脉洪大紧盛，热已极矣。因何头面手足俱肿，殆非痧乎？令其家老成人放痧筋二十余针。乃用解毒之剂，而肿痛俱消。继用补中益气汤、六味地黄丸调理而愈。", "18475": "曾治雷洪兴，痢血，日数十次，腹中绞痛，呕哕不食。诊之六脉，或迟或数，或时歇指。余曰：此秋痢兼痧也，恐防危殆。乃放痧时许，其痛略松。煎砂仁汤送阿魏丸，稍冷饮之。继与当归、楂肉、红花、枳实、赤芍、泽兰、青皮、槟榔、莱菔子，加酒军二钱，冲童便一钟，稍冷饮。二剂，痢转鹜溏而无红，诸证悉退。重用参、耆、苓、术、芡实、苡米、炮姜、建莲米、怀山药以兜涩大肠而愈。", "18476": "曾治张天全室人，季秋患疟，发热痰嗽，烦闷口渴。诊之左三部微涩数甚。余曰：此疟兼痧之证。即放痧十二针，服散痧顺气、活血解毒不应。明日又复放痧，脉始弦紧。仍与前药，诸证顿退。继服柴胡双解散四剂，疟愈止。用消痰顺气药冲童便，服四剂而痰嗽如失。", "18477": "曾治蒋东升次子，心疼发热，口吐涎沫，吐蛔数条。诊之右关沉细而紧，余脉洪数。刺腿痧筋二针，微有紫黑血出。乃与连翘薄荷饮四剂，痧退而仍寒热往来，乃与小柴胡汤三剂而热退身安。", "18478": "曾治汪多士长子，七岁，痧发痛极，头汗如雨。诊之脉芤洪数。放痧不出，刮亦不起。乃与细辛大黄丸微冷服。又用荆芥防风汤，稍冷饮之。明日痧筋自现，放之血流如注。仍服前药加大黄，下死蛔数条，结粪随下。其痛不止，痧筋复现，又复放之，仍服前药二剂而愈。", "18479": "右陶治姜云衢，遍身疼痛，背发一毒，黑烂痛苦。诊之脉沉微，指头黑色而恶热饮，此痧变恶毒，用冷围药而成背疽也。令去其围药，放痧讫。俟痧气已绝根，用参、耆、姜、桂、熟附子温托之。外敷以代刀散，黑变红色，贴太乙膏而痊。", "18480": "丁巳初夏，武昌游仙馆得谒黄超凡先生，见其言论丰采，迥迈时流，知为夙学。其临证也，则曰病在何经主用何药，有一定不移之见：其论古也，则曰孰当于理，孰悖于道，有卓然至正之规。予心焉折之，操贽就业。先生出驰远《集注》以示，予阅至少阳头痛在两侧之语，遂掩卷曰：世书咸绘少阳穴为太阳矣，先生今辨讹虽确，而指示则尚未明也，予阅至此而生疑，得毋有阅至此而亦如我之生疑者乎？何如分经绘图，注明脉穴，使人一见而了然乎？师曰：驰远先生非见不及此，特著书难于周详，留待亲传口授耳。子既有见地，留心精习，他日可作补遗。遂于馆中步月楼独居二载，课读录写者数十余部，绘图摘要者满案盈箱。师见而讶曰：子诚非无恒人，医道洵可作也，吾弗逮子也远矣。", "18481": "久咳失血，寒热似疟，脉弦细，自汗过多。系营卫两虚，心肺不足之候。", "18482": "诊脉虚滑，右大于左，两尺空豁，少年阳道不举，溺浊遗精，寐多汗泄。属真阴内亏，肾虚不固，未可徒作相火治也。", "18483": "脉虚数，两关坚锐，阴虚复多火郁，治法心肾宜补，肝脏宜疏。", "18484": "诊脉左弦涩右弱，肺主出气，肾主纳气，咳嗽气虚，阳不下达，金不制木，木反乘金，致身半以上，先病浮肿，继以失血。治宜滋肝益肾，纳气归元，未可徒作相火治也。", "18485": "风温初起，即发谵妄，自汗多卧，不发热，而大便结。据述脉沉细数促，已经半月，犹以汗下劫夺，焉望向安。今诊左脉细乱，右脉断续，口开目闭，唇板舌焦，不语失溲，头顶强直，手足拘挛。种种恶象，皆成坏症，立法制方，殊为棘手。至细按胸胁脐下少腹宗筋上，凝滞不和，时复冲逆，此非动气，亦非燥结。因思六旬高年，津液已枯，素多操持怫郁，夏秋省墓，强涉高巅，触山岚时气，越数十日而病发，乃阴气不荣，阳邪郁伏，少阴少阳，开合不司，枢转不利，而清浊升降失度，经络机窍不灵，即《内经》所谓精不能养神，柔不能养筋也。考古法中阳陷入阴，气血顽钝，每取味中之气，浊药轻投，从阴引阳，开之通之，清之泄之，补以运之，都以督之。冀其流利转运，关钥渐通，度可斡旋于万一。", "18486": "时感湿温之气，阳明蓄热发黄，非疸症可比也。今脉数无神，便闭已及二旬，肠胃枯燥，府气不通，心荣肺卫，悉被阳邪劫伤，内不守，外不固，神昏头汗有之。但延久正气日溃，邪火固踞，有正邪交脱之虞。", "18487": "风温风证，脉躁神狂，胸腹胀闷，身半以下，痛难转侧。此邪风被火，搏击营分，致血气流行失度，妊娠五月，际此危险，难免胎堕之虞。", "18488": "脉左关弦结搏指，两尺微细欲绝，齿舌喉闭，腹痛吐蛔，皆少阴厥阴见症，其脉俱循喉咙，而气至则为齿舌。夫肾藏虚，水无坐镇之权，斯肉𥆧而筋惕矣。此时不以回阳为治，虚虚之祸，将何所底止。", "18489": "脉数口甜，善食易饥，渴饮便数，多因过啖肥甘，积久酿热致病，发为脾瘅。子和云：消烁万物，莫甚于火，脾阴亏，邪火亢，肾元五液少司，而背为之痛，脾土主诸阳之本，而肢节为之酸也。议玉女煎合经义辛香荡涤陈气立法，玉女煎加人参三钱，省头草八钱，煎汤代水。", "18490": "心脉涩，胃脉滑，两尺微，胸胁烦闷，气升兀兀，鼓动咽喉，窒塞多痰，嘈杂吞酸，汗多面赤，心阳虚，火上浮，肺燥令其𪱥郁，清肃不得下行。子和云：气火炎烁而道路不利，津液日消。拟嘉言清燥汤法。", "18491": "左脉细弦，右寸关短滑，睪丸漏卮有年，腰脊牵引酸痛，肾精肝血，已自内损。今食减咳逆多痰，脾肺之阳亦亏，先崇土固金，后用补益下焦之法。", "18492": "酒湿酿热，多饮则肝浮胃胀，咳血半月，脉已弦细。皆酒客伤中，阳络损伤，致血逆不归经络，病在肝胃二脏。", "18493": "血症脉弦大空豁，少年阳亢阴亏，血随气火升动，急宜凉肝滋肾之品，以引血归经络，再商进退治法。", "18494": "头目眩运空痛，脉虚弦无力，两尺微涩，此皆木郁生火，风自火出，虚风郁火，上乘高巅。经云：脑为髓海。而肝胆之络，又皆络于脑。因平昔精髓内枯，肝郁血燥所致，非外感温散可解，法宜滋肝养阴，息风降火，尤当情怀开畅，善自调摄。", "18495": "脉左细涩，右虚滑，肢节酸疼，腿足麻木不仁，患偏于右。凡男子中年后，精血易枯，肝风鼓动，脾失健运之机，浊痰凝聚清阳，而胸脘噎塞，此偏风血槁之渐也。", "18496": "诊脉弦滑，右关独大，头目眩冒，腿股酸痛。此风痰郁滞，经络郁久生火，火与风合，上凌空窍，蒙蔽清阳，致神不健爽，急者先治，降火豁痰，而风自愈。", "18497": "脉数弦滑，痰火内滞，风邪外触。", "18498": "又劫夺强汗，木燥火炎，营血耗，君相动，则精泄不固矣。今交长夏，火土司升而烦躁，面庞精采外越，须预防狂乱变幻。不然，曷不观乎仲景太阳条中，火迫劫汗亡阳之惊狂起卧不安者乎。仿复脉汤意。", "18499": "脉左弦数，右关滑大，善饥肉脱，诸药不应。因思风横脾胃，煽灼中土，致谷食不能荣长肌肉，精力日衰。经云：二阳之病发心脾，其传为风消。可知子病必累其母，藏病必连及府也。仿河间法。", "18500": "右脉微弱，左弦细，木燥血枯，肾阴虚损，肝风内动，火灼津液，气壅生痰，阻塞隧道，机关不利，项强肢挛，筋脉不营，神倦流涎，语言艰涩。《内经》诸风掉眩，皆属肝木。木失水滋，母病而累及乎子也。顾质弱病延，大伤神气。治本则痰水未清，治表则本元耗散，风浮所胜，治以甘寒，中土不伤，标本兼施矣。", "18501": "又神脉稍清，语言略爽，痰涎挛痛，仍复如前。经云：肝痹善痛，大筋软短，小筋弛张。肾痹善胀，尻以代踵，脊以代头。肝肾血痹，筋骨焉能流利。仍从前法加减，缓调多服为宜。", "18502": "制首乌柏子仁地榆乌梅木瓜白蒺藜生白芍茯神枣仁又左脉短数，较甚于右，肢体虚浮，倦卧痿弱，因去血过多，气亦无附。交夏至节前后，阴阳升降之大关，吉凶由此而系，宜加意慎之。", "18503": "诊脉沉而有力，舌焦身汗，神昏壮热发斑，晦滞坚满，二便闭结，适合伤寒下格，邪气内盛，脉反郁伏之说。羌防辛散，徒耗其阴，于里症无与也。急当治苦以泄之。", "18504": "左脉细弱，右寸滑大，向患腰痛，近因风热客邪，袭伤肺络，先议清凉清上。", "18505": "寒热胁痛，脉弦细数，系邪郁少阳不清。", "18506": "病过两候，脉不缓和，舌干鼻鼾，上哕下泄，非退象也。", "18507": "脉弦浮，寒热头痛，经脉不舒。此风热外客两阳之象。", "18508": "脉弦滑，右关独大，寒热似疟，肢体麻木不舒，虽外感风热，然中虚向有积痰，尤宜兼顾其里。", "18509": "脉数浮弦，风伤肺胃之络。", "18510": "复脉汤加天冬、茯神、玉竹、鲜生地，去麻仁、大枣。", "18511": "脉细涩，少腹胀如复杯，舌燥渴饮，躁狂便闭，乃心阳火炽，藏病连府，气不宣化，致手足太阳之府，俱热结也。议桃核承气汤。", "18512": "脉虚滑数，两尺细微，久病羸弱，肝肾式微，阴不交阳，心神不聚，胞络空虚，痰火内迷，乘虚厥动，精识蔽蒙，虚中夹实，语言失绪，早安神志心肾为宜，晚涤痰火不失病机。方阙。", "18513": "病后虚风柔痉，精气内灼，漐漐汗泄，乃卫阳失护，气易外浮，筋脉不得滋荣，而手足振掉，神志失其内守，而口噤不语。所谓精不能养神，柔不能养筋也。但脉涣无神，直视失溲，脉症俱系散脱，势已难挽，再请高明裁酌。", "18514": "生脉散频灌。", "18515": "脉涩细数，两尺无神，初起咽喉肿痛，阴气下虚，阳浮上结。近因五火挟痛亢胃，乘虚暴中跌仆，口噤呕吐黑血，气机不宣，唇燥舌干。古称肺为水之上源，主司五声，肾为关钥闭藏，主司五液。水源不清，则关门不禁，遗溺便泄，有由来矣。今则痰火秘结于止，本气衰脱于下，际此险途，难保其无变端也。", "18516": "努力负重伤中，气结不舒，脘痛按之有声，脉左细右弦，两尺空豁。因痛久肝脾两伤，气血痹阻其经，遂致水饮溢膜外而为病也。且调气和络，冀病缓再商。", "18517": "关脉弦，尺脉弱，腰脊痛，少腹胀，气从左胁下绕脐攻逆，浊阴凝聚，下焦见症，皆属肝肾，议温柔通剂。", "18518": "又胁痛脘闷，气塞不通，日晡烦热，小便赤色而脉弦数，都因水亏木张，肝火上乘，脾土交春夏，木火升腾，前病复来矣，暂拟疏泄。", "18519": "病起左胁，上及中脘，下趋少腹，脉弦结歇止，此胆阳不舒，肝邪用事，则气血痹阻冲突乎其间也，宗通则不痛之意。", "18520": "脉数弦芤，肝肾真阴内损，阴虚阳搏，血动下溢淋漓，固当滋益肾阴，引血归肝。但肝病必然乘脾，又当佐以植土。又脉缓弱，火渐降，血自得引归经。但汗多食减色夺，此阴虚阳无所附也，急宜补气以通血，勿徒见血投凉。", "18521": "经云：血脱补气。以有形之血，不能速生，无形之气，所当急固。即太仆所谓无阳则阴无以生，无阴则阳无以化也。今年高体弱，阳络伤而血外溢。治病之初，但以滋阴降火为事。不知周身之血，悉统摄于脾，脾恶湿而喜燥，过服归、地、芩、连，壅于脾胃，则中州窒塞，升降无由，遂成胀满之候也。况元气素虚，平昔思虑多郁，肝胆之阳，久已不和。去冬先患肿毒，后即继以血症，血去则脾损而气愈弱矣。今诊脉虚弦不和，两关尤大而涩，可知起恙因由，皆关肝脾两藏。是时急于寒凉止血，遂致屈曲之木，愈陷于壅塞之土。时当春令不复，焉有畅茂条达之机。急者先治，莫过调脾和胃一法，则州都运化，决渎宣通，而胃气自能下行，脾气游溢，上可散精于肺，以通调水道，斯清浊自分，上下无不条达。中土既和，精悍得以四布，又何必拘拘于开鬼门，洁净府，逐水消肿之验剂，而胀始释者哉。", "18522": "咳逆浮肿，脉得弦数。宗仲景汗出恶风，用越婢汤法。", "18523": "又脉缓嗽减，风水已退，从脾肺两经调养。", "18524": "脾病则九窍不利，以至阴之藏，不得阳和舒布，斯水谷入胃，传送不行，清浊混乱，遂成腹满。肿胀之病，此经旨所谓藏寒生满病。三阴结，谓之水也。病者胎前即患喘咳，产后继以肿胀，经今百日有余，脉来微弱无神，在右尤甚。可知气血式微，中焦窒塞，升降无由，州都失职，决渎不宣，日居月诸，灌入隧道，津液脂血，浸淫洋溢，悉化为水。总由中央孤藏无气，不能灌溉四旁，以镇流行，则水湿泛滥而难支矣。读《病机一十九条》，所以胀病独归脾土，盖脾损不能散精于肺，则病于上，胃损不能司肾之关钥，则病于上，三焦俱病，以肾纯阴之剂投之，求其向愈，岂可得乎。勉拟东垣脾宜升胃宜降，合以回阳，不失乎人事之当尽也可。", "18525": "脉弦细，左胁亦坚大如盘，痰裹气凝血结，此五积症中之肥气也。", "18526": "神色痿弱，上下睛明穴黑滞，脉浮弦，腹痛喜食香味，寐则肠鸣，此虫积为患也。", "18527": "脉沉细，肾肝交损，阴中之阳内离，健运不司，食减腹胀，乃藏之寒生满之渐也。宜用温通宣补。", "18528": "胃痛气逆，上引胸胁，纳食则胀痛猛甚，脉迟弦滑。此多思郁结，气陷于土，脾不升，胃不降，致水谷之海壅闭，所谓不通则痛耳。宜疏木以达之。取乎《内经》胜克治病之旨。", "18529": "人身气血，流布经俞脉络，全赖中州施化，得以纳谷生津，考之《内外伤辨》，所以独取脾胃立论也。今诊脉弦细而迟，胁痛嗽血，得自力伤，不独金水交亏，缘土衰少生化之权，致吞酸脘痛，妨于饮食。此即东垣所谓戊无火不运，而痛斯作。宜温中辛散，佐苦甘淡以泄之。若徒补下元，则太阴之脾藏愈窒矣。", "18530": "肾为藏精之府，木为相火之官，真阴亏，相火动，而梦泄不固，所谓精不能养神，阳虚阴必走也。夫耳者少阴少阳寄窍，脉络所主之地，精不守则龙雷不宁，上扰乎清空，以致耳鸣震动，上实下虚。法当厚味填阴，介类潜阳，取经义下病治下之旨。", "18531": "心脉细数劲，两尺微弱，乃阴不交阳，心君妄动，耳鸣失聪，梦多遗泄。盖肝阳左升太过，由肾母收摄少权耳。以填补不元，导引静镇为主。", "18532": "久泄必伤肝肾之阳，腰痛脉数，皆水亏不能制火。", "18533": "脉细弱，气衰力倦，淋浊便溺作痛，得之劳倦伤中，所谓中气不足，溲为之白也。", "18534": "脉数大，按之微弦，湿热交蒸，脾阳不舒，浊阴下陷膀胱，致便浊精遗，溺痛。淡以渗之，苦以泄之。", "18535": "小便淋沥，精随溺泄，脉至弦数，两尺细涩，乃少阴肾藏有亏，致太阳府气不化，用滋肾丸方法。", "18536": "脉症气结在上，中脘阻塞吐涎，男子中年后，阴气先亏，津不运行，聚液成痰，闭遏胃阳，稍食阻痛欲呕，漉漉有声，老年噎膈之渐。", "18537": "脉左涩右滑，酒客伤中，胃阳痹阻，营血内枯，燥火易动，气逆胸痞吐痰，食入噎塞，大便燥结。所谓上焦不通，则上下脘不行。老年阴液已亏，怕延关格。", "18538": "丸方金匮肾气丸，用生脉散加白蜜汤送下。", "18539": "食下噎塞，痛连胸腹，脉左搏右平，由恚怒伤肝，肝厥必乘胃府，血不藏聚，致呕吐见血，而阳明之大络亦损，所谓阳络伤则血外溢也。用柔剂缓调。", "18540": "积怒动肝损营，亢乃燥气乘复，上噫气，下泄气，由血少藏聚，流而不行，痹阻厥阴，循经之所致，喉不利，胁痞痛也。况脉至右滑左涩，涩为肺象，滑为阳盛，金刑木位，胆阳不舒，脘中迷痛，食减液消，有自来矣。但今值疟后，余邪未尽，先宜清暑和标，再商治本之法。", "18541": "四君子汤合生脉散", "18542": "咽喉肿胀，气塞眩冒，心烦汗泄，食减便溏，脉至细小涩数。此心脾之亏，由肝肾内损，致阴心亢逆，上凌少阴循经之地。归脾虽当，泥于心脾，于少阴肾藏有间矣。", "18543": "久淋久带，必伤肝肾之阴，致奇脉交损，腰脊垂痛，维纲不振，寒热交作，女科以肝为先天，宜柔剂缓调，以和八脉。", "18544": "咳血脉弦，此肝血失藏，肺气不降，从清阳治法。", "18545": "又血脱日久，阴气难以骤复，过劳脊膂微痛。此因营虚失守，致督脉亦伤。平旦口苦舌干，脉反见数，可知阴液内损，则君相之火，易以升动也。", "18546": "左脉小弱，右寸滑大，髫年喘症，数载不痊，遇劳感寒即发，即风痰结于肺底，积久竟成窠囊，阻塞空窍，清肃不令下行矣。且肺病善咳，咳久未有不传至三焦者。故每交少阳气分用事，喘促更无止息也。早用化痰定喘，晚用复脉和阴。", "18547": "海浮石马兜铃杏仁桑皮橘红川贝紫菀苏子北沙参枇杷叶晚服复脉汤。", "18548": "久嗽脉数，食减骨蒸，得自产后，阴亏蓐劳之渐也。", "18549": "大风胀满，脉多沉迟，然按之有神，方为有胃气也。今诊得沉细如丝，寸关歇止，知谋虑伤肝，积久延及心脾。心病血不流，脾病食不化，胶滞凝结中脘，先成痞块，从微至著，暴腹胀大如蛊。医家不明肝喜疏达，脾升胃降，治法非苦降即温补，致藏府气血日钝，胃阳困厄，无怪乎愈治愈剧也。但经百日以来，精神日以告匮，即进药饵，亦如杯水沃燎原矣。姑进参附理中，冀谷食渐进，再商。", "18550": "诊脉左弦劲而右细涩，气逆从左上升，引胸脘而闷痛，食下噎塞，高年精血内枯，恼怒动肝，横逆中土，上凌肺，下侵肾，致咳呕便闭，清阳不升，浊阴不降，关格之渐。拟缓肝润燥双开，通其经隧。", "18551": "经云：怒则气高。阳气薄厥于上，必致神蒙窍蔽。且向有厥症，包络之痰，易随气火上胃，胸闷口噤，耳聋神愦。今发五六日，心下痞满不舒，脉微色脱，两颧时显红赤，乃气未平而神已耗。下虚本实先拨，从少阴厥阴两治。", "18552": "痢久不止，脉见细数，少阴肾虚，亡血失精之象也。又不能食，脾火不化，相火侵凌，上炎下夺，津液告竭，故又作渴。惟专救欲脱之真阳，兼能复返其阴，俟一阳来复之期，冀转回生发之气，则治矣。为拟三阴煎及三物桃花汤，间服之。", "18553": "少年火盛，心肾不交，梦多走泄，或无梦自遗，颧赤脉数，全属阴虚，精气不固，玉关不闭，相火妄动之故也。则宜壮水制之，不再动其火，自然痊安矣。", "18554": "太阴厥阴之络，寒气引痛，致项强舌卷，语言似乎蹇涩，其邪由府及藏，气不外卫，血不内营，致风之所袭，并入于心者。沉著于络，无阳以煦之，故不条达也。当治八脉为病。", "18555": "六脉弦大搏指，足征平素火必有余。肝强胃盛，以内伏之火，挟外来之风，致口眼㖞斜，头目不明，清阳之分，经络为之所中也。然在上之风，乃实邪，缓散自出。", "18556": "腹胀甚于少腹，按之坚急，大便泄，小便少，脉虚细，皆阴寒凝结，厥气在下而单腹膨满，当用温通之法。", "18557": "肝脾素郁，气血素亏，致清浊之混乱，窒塞中焦及小腹，足膝脉络不仁，食减吞酸，乃木来侮土之象，寡于畏耳。按脉皆微，真阳不运，阴凝阻遏，致𪱥郁不宣。当辛通达下之法，复以苦泄，胀可减矣。", "18558": "又大凡脉微腹胀，小腹上逆者，即经云：厥气在下，营卫留上，真气逆上，正邪相攻而为胀也。况乎产后下焦空乏，寒从此入，致不行也。拟方宣通之法，兼温下元，自能释然。徐之才云：宣可去壅，通可去滞，温可去湿，因仿而用之。", "18559": "三疟之后，中脘痞结，气郁生痰，痛呕少食，兼之经水愆期，来时作痛且呕，甚至经逆不调，而脉细并涩，视其形气未弱，血则有余，而气太郁，色虽紫而有寒。乃因血积胞门，或凝子宫，致冲任不荣，经年不孕。今取义于震阳也，一索而得长男。更欲求其虚灵不昧之性，使三气混合，自然一举而得子矣。", "18560": "又脉象略和，少腹痛处高突亦平，但交阴气冲，乃浊阴之邪，上干犯胃，尚宜渗利，以清肃上焦。", "18561": "身热十余日，头有汗而热不解，口苦耳聋，自利不止，即此已为上厥下夺之症，前医所用辛凉达表不应。今细按脉皆浮弦，舌苔白滑，气弱神倦，治法宜从一表一里和之。用柴苓法，俾两阳之邪，自然解散矣。", "18562": "（初六）脉浮弦略减，自利稀少，里邪欲和，反恶寒者，表邪亦欲和也。身热，漐漐汗出，口渴，有转退少阳之象，用温胆法以清余热。", "18563": "脉数细少神，瘟毒之邪，郁而未散，一身斑疹隐然，症非轻候。", "18564": "第五日方左脉微而无神，甚属可虑，右脉数实，十余日不大解，颇有下证。但烦躁不宁，未敢轻下。且以竹叶门冬饮，止其烦乱为第一。", "18565": "第七日方少阴之为病，但欲寐，躁不得卧者，不治。舌卷或唇焦，不大便，脉微欲绝，用苦辛入肾救逆。", "18566": "冬温邪伏，起于吐泻之后，致中气不和，热不减，神昏谵语，口渴恶心，苔白厚，左胁呼吸不利，肺气不清，时咳，总之热邪为害。按脉浮大，且无汗，邪尚在经，未入乎府。宜先理阳明，邪散乃愈。", "18567": "二诊脉浮大而数，因得微汗，势已略减，外热稍清，舌苔黄黑干燥，大便有转矢气，结燥未下，胃不和。前方再为加减，此时里热重于表矣。", "18568": "三诊脉症俱减，里热未尽，胃不和，大便未通，小便赤色。再用通利下焦，以生津液。", "18569": "四诊脉象略减，热亦稍清。此系余邪不足虑，憔左胁痛处，大如手掌部位，乃肺之经络，痛且拒按，系积伤气血，非细故也。用和伤之法。", "18570": "遇兄之症，至今念载。据述发时必先不寐，而后头痛发热。诊得脉左细弱，右弦大，乃阴虚阳盛，卫气不得下行之故。从阴引阳治法。", "18571": "丁亥正月二日，夏万隆子傅生，年七岁，卧床月余，身如燔炭，无汗干咳不食，儿科屡治，病益增，因请予视之。病热日久无汗，肌肉瘦削，扪之热愈炽。近复增干咳不食，纳谷无味，腹痛，按之虚软，诊脉左小右大而皆数。此肝胃之热己深，昼静夜剧，渐积为虫，有自来矣。再以去冬亢旱风燥之邪，乘虚上受于肺，咳频而愈增其因耳。用内外兼治法。", "18572": "瘕聚少腹，偏左有形，发亦从左，升至胃脘，累累然满腹，便溺为之阻塞，顷之腹中气喧胀消，仍归少腹。医有平肝若左金之属，温补者肾气之属，论奇脉辛香苦温之属，寒热杂投，历治三载，日夜发作愈剧。今交春分节后，寒热大作，望之面如渥丹，而仍洒浙恶寒，骨似蒸苏，究则上热下冷，况兼头汗淋漓，气怯神倦，种种虚候，所共睹矣。从前脉象，据云细弱，今左弦而右大，中虚无神，阴阳有离脱之兆，可惧之甚。所幸经水届期不爽，生生未绝。大凡此症虽由肝郁起见，目今病久体虚，下焦脉海乏气，络虚气阻，易于聚结耳。今以峻补之剂，培其阴阳根本，敛其阳光下潜，仍不离通络之结也。", "18573": "丁亥六月，侄患痢极重，治疗月余已愈，然不能戒口戒气，复发。延至闰七月二十日外日没时，人事昏沉，更定后方苏。余诊脉细弱无神，右关为最，腹如仰瓦，脐右动气大如鸡卵，震跃不息，中虚已极，生气索然。投以建中法，次日病势不减。延姜体干诊之，案云：", "18574": "痢下肠垢，五十余日，犹腹痛抽掣，惟悴尪羸殆甚，几几欲脱矣。虽胃口有滞，势难消导，急救其阴，以恋其阳，仿佛复脉汤之意。", "18575": "诊左脉弱，右较有神，连进复脉汤，中宫柔和，而神乱烦躁俱止，有津回液转之机。此时不问其虚，安问其余。", "18576": "自此之后，又服消积去滞丸药缓攻一法，余症俱减，而痢终不止。家贫不能服参，胃中邪火燔灼，日啖羊肉厚味斤许方快。凡除中能食，大约不过数日。此竟有月余不辍，但利不上，身亦不能转侧，面浮足肿，脉息俱绝，又延二三日方死，亦事之罕见者。是役也，虽未收功，医法另出一种，亦堪传也。", "18577": "丁亥七月，浦景文患暑症，愈而复发，壮热不退。医者先发散，继则重用犀羚连石等药，连服数剂，身热渐退，舌苔反煤黑，两脉沉而数细，手指牵掣不停，眼目定，人事一毫不省，以手拍额上，微有醒意。予曰：此虚邪未清，寒药遏之太过，邪已舍于神明之室，顷刻难支。正治方法，已不能施，速以奇法治之，为订一方。", "18578": "丁亥五月，长泾镇毛禹谟患时症，本镇医家，以三阳经药发表，苦寒药清火杂治，自余汗后，热不衰，神昏默沉，遍身似斑非斑。时复躁扰狂越，谵语片晌方定，胸腹按之痞满，咽噎多痰，舌苔色白中央黄，诊脉皆数大。此时行疫邪，横连募原，不易解散。遵吴又可法，用达原饮疏利之。", "18579": "丁亥冬至前，王仲良患伤寒，宋朝宗用羌活冲和汤二剂不效。戚向书诊之，身热脉沉而头不痛，曰此少阴症，须服麻黄附子细辛汤，发表温经。连进三服，亦无效。盖因其人生意操劳过甚，又多外宠，胃中有寒湿宿病蛰藏，与干健之阳，素已衰微不振，直宜少阴附子汤法，细辛麻黄，过于外散，尚非法也。次日再诊，其父缵臣初不为意，向书曰：脉中神情来往不续，病难收功。举家惊惶无措。请体干曰：事虽急，速进大剂参附，犹可挽回。用附子五钱，人参二钱，日夜各一服不效，且神思散漫，口中白沫，勃勃上泛，进吴茱萸汤又不效，再拟方。", "18580": "连进二剂，脉象或断或续，竟无寸功，招予同王履安、姜体干戚向书四人共商，议用黑锡丹碾化，参汤调服。白沫始下，少顷复上，再服又止矣。煎剂仍以前方频服，无可更改，日夜服参三四钱，两日后脉象来复，有向安之兆。伊新亲唐叔文，竟邀陈杏三来看，用六君子汤加减一剂，次日脉右尺又断续，左关微弱如丝，涎沫又上，危症复见。仍守前法二日，脉续涎沫可咽，而疲倦不堪，反甚于病重时矣。此后症屡增屡退，计服黑锡丹九钱，人参三两余，后改用八味，从阴恋阳，膏子以平调上下，立春前始能起身，犹腹痛胀闷，进真武汤而泄泻胀宽，再以参剂调补平安。是症也，赖有向书之先识，体干之主持，二人之功居多，而予与履安，商酌赞襄，他人不能生别议，方克起一生于九死，为无功之功也。", "18581": "初二日早诊，痢已减半，谷食渐增而安寝，脉皆和缓，右尺独劲大不平，浊邪陷于大肠之分未清。拟将欲降之，必先升之之法。", "18582": "初三日痢止便溏，肌润泽有汗，神思清爽，谷食顿加，脉细弱而数，痢后阴亏宜和。", "18583": "戊子六月，赵羹和令堂，因两孙布痘而夭其一，劳碌悲伤之后，骤发寒热，呕吐头痛，汗多腹中胀闷，二便不快。城中医者，先用小柴胡汤，后因其胸闷恶心，加入草豆蔻之辛温，遂困苦不堪，乃招予治。诊左脉不弦而小弱，右洪大，头偏右痛，抽掣入巅，目白赤，时泛恶心，交申酉时，则寒微热甚，口虽渴，脘痞不能饮汤，苔白，汗出淋漓，似有昏厥之象。余曰：此非少阳疟症，乃暑邪由肺入胃，暑必兼湿，而作壅阻，弥浸三焦气分，若延入营中。须防变幻，遵河间法，用宣明甘露饮，一剂症减半，二剂寒热止，改用人参、麦冬、甘草、竹叶、半夏、茯苓、五味、粳米，霍然。", "18584": "祝肇文之妻，王巷徐东旭孙女也，四月归家，患时症发斑。太叔岳宗圣，知医调治，先用荆防风栀豉，继进犀羚膏连生地诸凉剂，二候不退。肇文作札致施兄登士，请予往视，至巳二鼓矣。进诊面光亮，目赤神思瞆瞆，手频欲缩去，舌赤齿燥，问之微微有声。余知其痉厥将至，曰今已更深，且不服药，明早进视，已口噤目定𬹼齿，两手牵搐不定，身僵无汗，面赤如妆，脉弦大搏如指数，右洪大，刚痉之症悉具。此邪未发泄，凉剂遏之太多耳。为用葛根、花粉、白芷、防风、僵蚕、犀角、羚羊角、牛黄、蚌水、钩钩、竹沥宣达阳明经分之邪，祛痰开窍，以息内风相火。服一剂，至夜半得汗遂苏。天明予欲归，时复又微厥，肇文甚恐。予曰：无妨，再服一剂，自然减可。至第二日到彼，诊脉数小而不能鼓指，虚汗津液，已现虚象。即用生地、麦冬、阿胶、白芍、炙草、玉竹、牡蛎、茯神，令服三剂。登士见方，疑补太骤，予以病久体虚液亏为虑，决不复痉，竟加枣仁、当归，补其营阴而安。", "18585": "己丑八月中，先寒战一日，大汗热退，左半身痛，腰胯更甚，足不能伸，口渴面赤，溺混浊短涩，平昔脉象六阴，今觉数大。予思本年春夏，雨霪过多，酒客素多内湿，为订一方，五苓散加滑石、桃仁，通阳利湿，以疏下部血中之滞。服二剂，左半上下之痛俱减，稍能起坐，但腰痛连胯，膝屈不伸，行走伛偻苦楚。思嘉言先生治腰偻废，瘀血内痹者，用桃仁承气加肉桂。此邪尚在经络，宗其意立方。", "18586": "戊子七月十六日，季七翁乃室，患痢极重，招予与姜体干诊视，予约体干同去。是日予先至，痢已半月，五色相杂。始事者令君族侄祝冀堂，为梁溪著名士，因症由脾泻转痢，为脾传肾之藏病，药用干姜、白术、赤石脂、龙骨、蕲艾、人参等，一派辛温燥涩之药，但反佐川连、乌梅，病热日重，饮食已减，面色晦滞，精神困顿已极，诊脉细涩不和，右尺激之，时又鼓指，手温足冷，又时微热，舌苔白，心中烦，腹痛后重如初。予意此非藏病下利，究为暑湿内郁肠胃，初未外达，又未内消，邪未去而阴已耗，液已亏矣。拟和阴润燥之剂。", "18587": "是夜只痢三次，烦痛亦减，但神倦似睡，汗微欲出，举家咸喜病减，又疑欲脱。十七日早，体干至，同进诊。脉象虚涩，未刻交白露节，正气当倍。", "18588": "甲辰十一月，章南山次子兴官，忽患头痛，面色青黑晦滞，畏寒神倦，兼有痰嗽，曾服息风和阳疏解之药数剂，身发微疹，头痛旋止，神识日呆，耳聋无汗，溺少大便不解。越三日，适交冬至节候，暮夜昏谵而遗溲。伊兄洪远，邀予诊视。其脉浮而带弦，重按空虚，验其舌上无苔，不饥不渴，但有疼痛声而不知其处，询其病之所苦，而又不能鸣其状，目视瞑而神呆。予骇曰：此症渐入厥象也。变幻最多，此时尚在游移未定之际，极难图治，必须邀同姜干干酌议，方可主持。奈又往锡未归，不获已。勉拟降厥豁痰开窍育阴息风方法挽之。服后至夜颇安，并且得汗身凉。清晨复诊，按其脉虚象忽退，予令彼将此药再服一剂。是日体翁适归，又邀为之诊视。就予方略为加减，更进一剂，耳聋忽闻，症反变出，多言无绪，似昏非昏，似清非清，脉变不调之象，舌色忽紫，中见微黑碎裂之纹，如蚕豆瓣大，大便久闭，小便一昼夜不解。体翁悉审视良久曰：此症因肾虚邪凑，致在下之风火，上干而脱其志，心虚邪混，致在上之痰厥，气不降而失其神。况头疼起见，显系木失水涵，肝风挟温邪而上冒，风火煽烁不已，肝肾失疏泄闭藏之权，而魂志日离，邪阳挟相火冲突，使津液成痰，而乱其神明之主，则神不守舍矣。虽然，温症变厥，治亦何难，独不若此症之不归经络，不归肠胃，而窃踞于神志之间，如油入面，打成一局，安居于难分难解之地，冥顽不灵，所以现出狂言失志之状。经云：狂言者是失志，失志者死。遍考方书，前而仲景之伤寒，后而河间之温热，从无成法可求，应归不治之例。但念与病者嫡表弟兄，虽死亦须图治，莫若以灵治灵之法，望其或成为尸厥，或变为发狂，其阴其阳，归正其候，乃可斡旋于万一，亦未可知。生死关头，惟此一举而已。因与予同拟一方。", "18589": "服此药后，至夜忽作痉状，口噤多汗，手足强，痰涎满口，不能言语，至上午时候，同体翁诊视，其脉弦急，舌苔转为白色，汤水与之能咽，不兴则不知。体翁曰：此正尸厥之象也。乃照前方去犀角、川贝，加入", "18590": "服此药后，至夜半忽发狂，天明复诊，其脉弦大而数，谵语狂妄。体翁曰：症转阳分，已见发狂，可无虑也。", "18591": "弱脉神虚，肢振鼓栗，暑风内郁，药以寒凉杂进，病日益甚，体日益虚，以致神识渐有昏沉之累瘁，姑以枇杷叶散挽之。", "18592": "十九日再诊脉颇有神，鼓栗已减七八，舌苔尚白，胃阳为寒苦大伤，畏风多汗，以建中先立中宫之墓。十余日不大便，此胃气不下行，必得健阳中运，化物自通，无庸攻伐。", "18593": "二十七日三诊左寸关脉，浮弦而虚，右浮大，按之无神，舌苔白滑，鼻与环口，气色青黑，面微浮，身仍发热，鼻多汗，头痛烦闷不止，心加饥，食下则眠睡，中土阳和之气不运，风木厥动，水谷与风暑，郁而变幻不一，病根实深，未可轻视。仍从初诊静顺汤法，冀其中旺木和。", "18594": "发汗后肿势大减，喘息渐平，但脉微神倦，恍惚惊惕。此水去而封蛰不固也，以真武镇之。方用真武汤，服数剂后，即以此作丸料。", "18595": "脉左涩结，关芤，右亦涩弱，失血十几年矣。今怒动肝伤，气逆上溢，精遗龙雷不宁，甚至无梦自泄，此阳虚阴必走也。当处𭶟阳发泄之候，尤贵调平气分，恰与仲淳三要，宜降气不宜降火符合。", "18596": "又初一日，大暑之第七日也。连进济生八味丸两服，而血色遂稀，精不复遗，五内之病情，亦可略见矣。切其脉，亦似前日较胜，少涩结之形，有鼓荡之致。若云不能敛气凝神，毕竟氤氲之气，与干健之阳，总未必反失冲和也。尝考阳虚之治有二，一理中，脾宜升也；一摄下，肾主纳也。今是龙雷不肯潜伏于收藏之地，反升清阳之所，故必引之导之。咸以润之，介以潜之。在此调摄勿懈，庶几病魔可却。", "18597": "壬辰秋分夜半起，今已四月，发热左胸胁痛，难以转侧，咳吐自汗，无头痛身痛恶寒等症，舌无苔，大小便自可，腹中和，口渴不欲饮，先悲泣而后能嗽咳，出痰有秽气，毛际胀痛不可近，脉弦大而数，目微赤，面色滞，多叫呼，与《内经》悲哀动中则伤魂正合。今正值四气风木湿土令退，五气君火燥金加临，遇悲哀抑郁之境，用甘麦大枣，清燥救肺，枇杷叶散，静顺四汤意。", "18598": "一人年将五十，身体肥健，素患肠风下血，已十余载矣。去冬因思虑忧郁，忽然下血数斗，后又下如尘水，或如猪脂状，延至今春，所纳之食，汨汨下行，不得停留变化，甚至直出如箭，以致肛门脱出数寸，每以热汤浴之，睁叫托入，顷之去后，其肛复脱，一昼夜下痢二十余行，苦不可言，面色浮肿，夭然不泽，唇焦口干，鼻孔煤黑，右寸浮大，重按无力，脾脉软弱。（痢）", "18599": "昨服一剂，药后内邪消去，但手太阳之脉洪数，此胃气未服也。今宜扶胃养脾为主，勿亟亟于治痢，痢亦自止。", "18600": "脉渐缓弱，嗽减痛止，胸脘亦宽，平昔木旺土衰，久患脾泄，中气大亏。若饮食杂投，诸症复增，愈难调摄，须慎之。（嗽）", "18601": "肝脉渐平，胃脉反见滑大，此皆饮食不调之故。", "18602": "六脉迟弱，两尺尤甚，左腰膝足肿，关节间疼痛麻木，遇温暖即稍止。此系三阴经之恙，治宜温肾养肝活络为治。", "18603": "六脉弦数，外见寒热往来，间日而作，两额巅顶微痛，舌现黄苔，饮食不贪，小便通调，大便艰涩。此统属少阳阳明两经疟症之象。今治宜用小柴胡汤主之，加入阳明之药一二味。服之两剂，再议损益可也。（疟）", "18604": "尊翁六脉弦数，身热如烙，舌起黑苔，中脘按之而痛，大便自利，小便赤色，邪热郁伏，值此高年，属在大险。拟方服之一剂，若能稍减，即是生机。（时感）", "18605": "又六脉洪滑有力，舌燥唇焦，胸满胀痛，手不可按，口渴无汗。此阳明夹食之候，法宜先用解肌，后议清里可也。", "18606": "业侯令政，素多郁怒，因产后嗽咳未除，口干喜饮，至春夏之交，忽恶寒壮热，身重头疼，其上则时欲饮水，水入即吐，下则气痛泄泻，小水全无。所服皆柴胡、黄芩、桔梗、竹茹、泽泻、猪苓等药，外热似减，诸症转甚。予忝在相知，为越俎而代庖焉。诊脉两寸浮大，关尺弦数，且闻嗳气频加，并见上气难忍，不得不略陈一二。以辨症定治，大凡伤寒之来，始太阳而络厥阴，在一经则有一经之症，有一经之症，必有一经之脉，以符合之。虽其错综变化，自不可执，要不外乎同中察异，所谓有者求之，无者求之是也。故有时上病不必治上，下病不必治下，从乎中治；有时上病而反治下，下病而反治上，运用存乎一心。夫当头痛治头，脚痛医脚，遂以毕神奇之用，而称大方家哉。即今外显恶寒发热，头疼吐逆，是太阳表症未解也。喜饮汤水，仍不能饮，非热邪之入里，乃津液结聚于胸中也。肺主气，水出高源。故经曰：膀胱者，州都之官，津液藏焉，气化则能出矣。胸中为津液结聚，兼以素多郁怒，遂使肺失其职，不能通调水道，下输膀胱，须开其水饮，达阳和，则上之口干，不治自愈，而下之小便，不利亦多矣。因请立方，遂以小青龙减麻黄、细辛、五味，加茯苓、前胡、紫朴、苏梗、广皮，一剂立效。嗳气未除，两寸尚浮，此气逆上也，再加益智、香附，服后向安。但下午微寒，寒过又热，至天明始退，如是者二日，此客病已去，本病犹存。因用调理脾胃，兼养血分之品，投之乃愈。（壬寅初夏）", "18607": "产后之症，以补养气血为先，虽有他患，以末治之。所以内热口干者，不得任用寒凉，用寒凉则新血不生。而胃阳受困，头疼恶寒者，不可专行发散，行发散则气随汗出。而精神告匮，前六七日时见脉势涩弱，饮食不入，乳汁全无，频频自汗，以为平素体虚，而产后过伤气血，用阳阴平调之剂，从缓治也。目今寒热时发，神气不清，脉来涩数而弱，左关略旺。大抵皆阳阴二气，自力乘侮，非干外邪所致。其神气不清者，一由于血室空虚，留瘀得以随热势而入，一由于胃阳不固，心神因以随自汗而伤。法宜生血以退热，养气以安神，开胃以加食，乃能全愈也。", "18608": "今春三月中旬，周庄俞君爱次子来，述其兄病症危笃，坚请一诊。至则见其面黧神瘁，口噤自合，脉来软弱，沉思半晌，因诘之曰：是病外无六经之邪，内无五藏之患，莫非负重远行，枵腹任劳乎？何厥状之困顿，至于此极也。其家人曰：兴工筑岸，半月来勿得休息，继又到贵镇探视，食生冷难化之物，归至中途，呕吐频作，胃中由是胀痛？三月前服导滞丸，大便行过数次，然终饮食不思，胀痛自若，转觉神气愤乱，今病危矣。原先生有以救之，乃恍然曰：劳苦旬余，过伤脾胃，复食以难化之物，其不能容而吐出也宜矣。一吐则脾胃愈伤，从前困倦之态，始显呈于外。药贵半养神而半和胃，乃能奏效收功，服下二剂，果不爽言。", "18609": "泗港陆九文昆仲，夙年相知也。仲秋之月，久凝三公郎，忽寒热头疼，从胸至腹，胀闷不堪，久文知医，先服解肌消导之剂，不效。来镇相邀，值予在云亭曹氏，乃请承调元往诊。用小柴胡加石羔，头疼虽止，诸症转甚，加以恶心。使者相望于道，适又他出，不得已延余弟宇瞻诊视。云是结胸，主以瓜蒌、山栀、枳实、竹茹、黄芩等药，服后胸腹愈痛。伊兄允升，躬叩予门。同仲儿寻至慕义庄，飞掉归家，薄暮始得抵彼，病者闻声欣然曰：先生其救我乎。盖望之久矣，予因思结胸成于下早，否则日久邪陷亦成。今疾作而痛随起，定非结胸，细按右脉弦中带紧，其间必有寒物阻住升降，以寒凉治之，所以胀痛日甚。况是日阴雨两旬，天时之湿，感召极速，必平胃散加藿香、腹皮、苏梗、半夏、柴胡、乌药，始得破其壅塞。忙服一剂，下咽后恶心顿止，觉腹有声如雷，顷刻胀痛若失，遂能安卧无虞。丙申仲秋存案", "18610": "蒋天祥令郎，年十三，今秋患伤寒，更数医调治，有用麻黄发汗者，有用石羔泻火者，更有用牛黄大黄清心行滞者，鲜获一效。后市医以启脾为主，自谓妥当得法矣，亦卒无成功。比及四旬，势病转剧，将治后事。乃延余诊，涕泣哀告，请决行期之早晚，非以望愈也。余观大肉已脱，面赤唇红，时时干咳，午后发热尤甚，六脉浮数，两寸兼大，知其精液被药久伤，肺金为火所烁，是为阴虚阳盛之极，不速治之，必变成痨瘵，虽勿即毙，亦难望愈。所喜者，三部中无弦急不和之状，犹有生机。遂慰其父曰：是病虽重，可以不死。予且勿优，从前之药，悉属误治，倘能坚信予言，数剂必获全效。方用门冬、青葱、沙参、秦艽、白芍、丹皮、甘草、薄荷、桔梗、桑皮、橘红，一剂热退，再剂身凉，咳犹未除。去薄荷、秦艽，加五味九粒，石斛一钱，连进四服，气平咳止，即思饮食。是余独有确见，所以立方用药，得心应手，因笔之以志一时之见云。", "18611": "方裕远政，寒热如疟，柳仁和以解肌清热之法治之。数剂后神昏口噤，手足拘挛。有蔡松涛者，江宁人也，近居吾乡，新与方结为秦晋，迎归调治，见势危急，束手无策，遂辞去。于是遣使相招。进诊时，力持其手，乃可切脉，观松涛所定药案，议论似是，用药实非，犹以一杯水救一车薪之火也，安能起一生于九死哉。即索笔纸，立书数行，大约谓风寒湿三气，杂合难解，正虚邪盛，以至此极。当遵太阳刚痉法，用桂枝、天麻、钩钩、秦艽、木瓜，通其经络，茯神、菖蒲、半夏、甘草、丹皮，开其心神，频频灌下。半日人事稍清，三宿手足亦舒。见胃虚神困，加人参、归身，平调四剂。裕远以为无事，不复医治。半月后神呆气滞，语言恍惚，就商于予，为用清心消痰之药，遂获愈。", "18612": "瓯瞻次媳，缪氏女也。缪无子，止生此女，性多躁，久患三疟，春初归探母病，维持而调护之，寒热交作。有程姓蒙师，属在比邻，亦稍知医，道服发散药，热已渐退，连食腐浆大枣等药，胸前遂觉胀闷，热又复作。乃延余诊，因用和解清导一帖，已自减可。程不思彼体虚，加入三棱、蓬术，嗳气转加，吐痰不已，酌方主和营卫，兼清气化痰，寒热乃止。但汗出过多，反觉恶寒脉细。且所吐者皆清水，而小便全无，少腹肿满，余思脾气又虚之人，土不制水，水泛为痰，土不生金，金难化气，惟纳其气以归肾，燥其脾以培元，则水不患其无制，金不患其失司。遂以五苓散加益智、半夏、广皮、车前，外用杉木皮煎汤薰洗，病即全愈。", "18613": "得病六七日，转觉头疼壮热，咳逆烦渴，诊脉右滑大，左弦急。此系风热郁遏三阳，当凉解为法。（风热咳）", "18614": "吐泻六脉微弱，面青肢冷，气脱神疲，中气衰而脾阳欲脱，已成慢脾风候，拟参附理中一法。", "18615": "产后脉涩而数，形羸气怯，腹痛腰疼，潮热心悸，将成蓐劳，症非轻可，宜建中汤。", "18616": "上则喉口糜烂，下则腹痛便溏，病由去秋延及今夏，时作寒热如疟，缘劳心体质，夏气失长，秋冬收藏，今至暑气，为之内伏。今诊脉左尺寸俱紧，右关重按见涩，面色赤黑晦滞，舌苔腻厚黄白。睹色切脉，见症情形，明明肾水郁及丙火，三焦失司宣化耳。河间云：膀胱移热于小肠，膈肠不便，心胃壅热，上为口糜，主以柴胡地骨散。奈病久食减亏虚，虚火易以升动，用药以此为棘手，不获已。小其剂，缓其制以进之。", "18617": "医之先，谓出于神农、黄帝。儒者多不以为然。予尝考医之与卜，并见于《周礼》，曰医师隶冢宰，筮人隶宗伯，并称于孔子，曰人而无恒，不可以作巫医。巫、筮字，盖古通也。然卜之先，实出于羲、文、周、孔，则医之先谓出于神农、黄帝，亦必有所从来。大约羲、文、周、孔之书存，故卜之道尊；神农、黄帝之书亡，故医之道卑。然其书虽亡，而绪余之出于先秦者，殆亦有之。若今《本草》、《素问》、《难经》、《脉经》，此四书者，其察草木鸟兽金石之性，论阴阳风寒暑湿之宜，标其穴以施针𤋲，诊其脉以究表里，测诸秋毫之末，而活之危亡之余，类非神人异士，不足以启其机缄，而发其肯綮。则此四书者，诚有至理，不可谓非出于圣笔而遂少之也。然则医之与卜，皆圣人之一事，必儒者乃能知之，其不以为然者，不能通其说者也。医之方书，皆祖汉张仲景之言，实与前四书相出入，亦百世不能易者。自汉而后，代不乏贤。中古以来，予所取五人，曰孙思邈氏，其言尝见录于程子；曰张元素氏，曰刘守真氏，曰李杲氏，皆见称于鲁斋许文正公；曰朱震亨氏，实白云许文懿公高第弟子。斯五人者，皆儒者也。而朱氏实渊源于张、刘、李三君子，尤号集其大成。朱氏每病世之医者，专读宋之《局方》，执一定之法，以应无穷之疾，譬之儒者，专诵时文，以幸一第，而于圣经贤传，反不究心。乃作《局方发挥》、《格致余论》等书，深有补于医道。而方书所传，则有《丹溪心法》若干卷。推脉以求病，因病而治药，皆已设之方也。朱氏没而其传泯焉。近世儒者始知好之，稍稍行世。然业医者乐检方之易，而惮读书之难，于《素》、《难》诸书，盖皆不能以句，而于五人者之著述，则亦视为迂阔之论。其茫然不知所用力无足怪者，其以药试人之疾，间一获效，则亦如村甿牧竖，望正鹄而射之，偶尔中焉。或从其旁问之射法，瞠目相视，不知所对。彼老成者，日从事乎内志外体之间，虽或小有所失，而矢之所向，终无大远，此观射之法也。审医之能，何以异此！予宗人用光，世业儒而好医，其读《素》、《难》之书甚稔，最喜朱氏之说。尝以《丹溪心法》有川、陕二本，妄为世医所增附，深惧上有累于朱氏，乃为之彪分胪列，厘其误而去其复，以还其旧。凡朱氏之方有别见者，则以类入之。书成，将刻梓以传，请予序。予故以多病好医而未能也。辄以医卜并言于编首，使业医者知其道本出于圣人，其书本足以比易，而非可以自卑，则日勉焉以致力乎《本草》、《素》、《难》、《脉经》之书，以及五君子之说，而尤以朱氏为入道之门，则庶几乎上可以辅圣主拯世之心，下可以见儒者仁民之效，而医不失职矣。用光名充，休宁汉口人，与予同出梁将军忠壮公后。", "18618": "夫驱邪扶正，保命全真，拯夭阏于长年，济疲癃于仁寿者，非资于医则不能致之矣。医之道肇自轩、岐，论《难》、《灵》、《素》出焉；降而和、缓、扁、仓，咸神其术；至汉张仲景作《伤寒卒病论》，始制方剂，大济丞民；晋王叔和撰次其书，复集《脉经》，全生之术，于斯备矣。他如华氏剖腹，王氏针妖，与夫奇才异士，间有一节一法取衒于时者亦多，非百代可行之活法也。嗟夫！去古愈远，正道湮微，寥寥千载之下，孰能继往开来而垂法于无穷者？宋金间，上谷张元素、河间刘守真，俱以颖特之资，深达阃奥，高出前古。元素之学，东垣李杲深得之，明内伤之旨，大鸣于时。王海藏、罗谦甫又受业于东垣，罗太无、亦私淑诸贤者也。明哲迭兴，肩摩踵接，著为方论，究极精微，犹水火谷粟之在天下，不可一日无。遵而用之，困苏废起，斯民何其幸欤！泰定中，丹溪朱先生起江东，先生，许文懿公高第，讳震亨，字彦修，婺之乌伤人，为元巨儒。因母病脾，刻志于医曰：医者，儒家格物致知一事，养亲不可缺，遂遍游江湖，寻师无所遇，还杭，拜罗太无，乃得刘、张、李之学以归，穷研《素问》之旨，洞参运气之机，辟《局方》之非宜，悟戴人之攻击，别阴阳于疑似，辨标本于隐微，审察血气实虚，探究真邪强弱，一循活法，无泥专方。诚医道之宗工，性命之主宰，而集先贤之大成者也。其徒赵以德、刘叔渊、戴元礼氏，咸能翼其道，遗书传播有年。景泰中，杨楚玉集其心法，刊于陕右。成化初，王季𤩽附方重梓于西蜀，志欲广布海内，使家传人诵，不罹夭枉。其用心仁矣！而杨之集，篇目或有重出，而亦有遗，附以他论，使玉石不分。王因之附添诸方，多失本旨。充，江左一愚，夙志于此，每阅是书，实切病焉，辄不自揆妄意，窃取平治会萃经验等方。及《玉机微义》、《卫生宝鉴》、《济生拔萃》、东垣、河间诸书校之，究尾会首，因证求方，积日既久，复得今中书乌伤王允达先生以丹溪曾孙朱贤家藏的本寄示，合而参考，其或文理乖讹，意不相贯者，详求原论以正其误；篇目错综，前后重叠者，芟去繁冗以存其要；此有遗而彼有载者，采之以广其法；论既详而方未备者，增之以便检阅。一言去取，无敢妄有损益，庶几丹溪之书，犹泾渭合流，清浊自别；乌鹭同栖，皂白攸分，学者免惑于他岐，疾疢得归于正治，未知其然否乎？极知僭逾，无所逃罪，同志之士，倘矜其愚，正其讹舛而赐教之，则充之至愿也。于是乎书。", "18619": "手厥阴别脉经见证（心主）", "18620": "能合色脉可以万全", "18621": "欲知其内者，当以观乎外；诊于外者，斯以知其内。盖有诸内者形诸外。苟不以相参而断其病邪之逆顺，不可得也。为工者深烛厥理，故望其五色，以青黄赤白黑，以合于五脏之脉，穷其应与不应；切其五脉，急大缓涩沉，以合其五脏之色，顺与不顺。诚能察其精微之色，诊其微妙之脉，内外相参而治之，则万举万全之功，可坐而致矣；《素问》曰：能合色脉，可以万全。其意如此。原夫道之一气，判而为阴阳，散而为五行，而人之所禀皆备焉。夫五脉者，天之真，行血气，通阴阳，以荣于身；五色者，气之华，应五行，合四时，以彰于面。惟其察色按脉而不偏废，然后察病之机，断之以寒热，归之以脏腑，随证而疗之，而获全济之效者，本于能合色脉而已。假令肝色如翠羽之青，其脉微弦而急，所以为生；若浮涩而短，色见如草滋者，岂能生乎？心色如鸡冠之赤，其脉当浮大而散，所以为顺；若沉濡而滑，色见如衃血者，岂能顺乎？脾色如蟹腹之黄，其脉当中缓而大，所以为从；若微弦而急，色见如枳实者，岂能从乎？肺色如豕膏之白，其脉当浮涩而短，所以为吉；若浮大而散，色见如枯骨者，岂能吉乎？以至肾色见如乌羽之黑，其脉沉濡而滑，所以为生；或脉来缓而大，色见如炲者死。死生之理，夫惟诊视相参。既以如此，则药证相对，厥疾弗瘳者，未之有也。抑尝论之，容色所见，左右上下，各有其部；脉息所动，寸关尺中，皆有其位。左颊者肝之部，以合左手关位，肝胆之分，应于风木为初之气；颜为心之部，以合于左手寸口，心与小肠之分，应于君火为二之气；鼻为脾之部，合于右手关脉，脾胃之分，应于湿土为四之气；右颊肺之部，合于右手寸口，肺与大肠之分，应于燥金为五之气；颐为肾之部，以合于左手尺中，肾与膀胱之分，应于寒水为终之气。至于相火为三之气，应于右手，命门三焦之分也。若夫阴阳五行，相生相胜之理，当以合之于色脉而推之也。是故《脉要精微论》曰：色合五行，脉合阴阳。《十三难》曰：色之与脉，当参相应。然而治病万全之功，苟非合于色脉者，莫之能也。《五脏生成篇》云：心之合脉也，其荣色也。夫脉之大小滑涩沉浮，可以指别，五色微诊，可以目察，继之以能合色脉，可以万全。谓夫赤脉之至也喘而坚，白脉之至也喘而浮，青脉之至也长而左右弹，黄脉之至也大而虚，黑脉之至也上坚而大。此先言五色，次言五脉，欲后之学者望而切之以相合也。厥后扁鹊明乎此，述之曰：望而知之谓之神，切脉而知之谓之巧，深得《内经》之理也。下迨后世，有立方者，目之曰神巧万全，厥有旨哉。", "18622": "将以施其疗疾之法，当以穷其受病之源。盖疾疢之原，不离于阴阳之二邪也，穷此而疗之，厥疾弗瘳者鲜矣。良工知其然，谓夫风热火之病，所以属乎阳邪之所客。病既本于阳，苟不求其本而治之，则阳邪滋蔓而难制。湿燥寒之病，所以属乎阴邪之所客。病既本于阴，苟不求其本而治之，则阴邪滋蔓而难图。诚能穷原疗疾，各得其法，万举万全之功，可坐而致也。治病必求于本，见于《素问·阴阳应象大论》者如此。夫邪气之基，久而传化，其变证不胜其众也。譬如水之有本，故能游至汪洋浩瀚，泒而趋下以渐大，草之有本，故能荐生茎叶实秀，而在上以渐蕃。若病之有本，变化无穷。苟非必求其本而治之，欲去深感之患，不可得也。今夫厥阴为标，风木为本，其风邪伤于人也，掉摇而眩转，𥆧动而瘛疭，卒暴强直之病生矣；少阴为标，君火为本，其热邪伤于人也，疮疡而痛痒，暴注而下迫，水液浑混之病生矣；少阳为标，相火为本，其热邪伤于人也，为热而瞀瘈，躁扰而狂越，如丧神守之病生矣。善为治者，风淫所胜，平以辛凉；热淫所胜，平以咸寒；火淫所胜，平以咸冷。以其病本于阳，必求于阳而疗之。病之不愈者，未之有也。太阴为标，湿土为本，其湿邪伤于人也，腹满而身肿，按之而没指，诸痉强直之病生矣；阳明为标，燥金为本，其燥邪伤于人也，气滞而𪱥郁，皮肤以皴揭，诸涩枯涸之病生矣；太阳为标，寒水为本，其寒邪伤于人也，吐利而腥秽，水液以清冷，诸寒收引之病生矣。善为治者，湿淫所胜，平以辛热；以其病本于阴，必求其阴而治之。病之不愈者，未之有也。岂非将以疗疾之法，当以穷其受病之源者哉？抑尝论之，邪气为病，各有其候；治之之法，各有其要。亦岂止于一端而已。其在皮者，汗而发之；其入里者，下而夺之；其在高者，因而越之，谓可吐也；剽悍者，按而收之，谓按摩也；藏寒虚夺者，治以灸𤋲；脉病挛痹者，治以针刺；血实蓄结肿热者，治以砭石；气滞痿厥寒热者，治以导引；经络不通，病生于不仁者，治以醪醴；血气凝泣，病生于筋脉者，治以熨药。始焉求其受病之本，终焉蠲其为病之邪者，无出于此也。噫！昔黄帝处于法宫之中，坐于明堂之上，受业于岐伯，传道于雷公，曰：阴阳者，天地之道也，纲纪万物，变化生杀之妙。盖有不测之神，斡旋宰制于其间也。人或受邪生病，不离于阴阳也。病既本于此，为工者岂可他求哉！必求于阴阳可也。《至真要大论》曰：有者求之，无者求之。此求其病机之说，与夫求于本，其理一也。", "18623": "中风大率主血虚有痰，治痰为先，次养血行血。或属虚，挟火（一作痰）与温，又须分气虚血虚。半身不遂，大率多痰，在左属死血瘀（一作少）血，在右属痰有热，并气虚。左以四物汤加桃仁、红花、竹沥、姜汁，上以二陈汤四君子等汤加竹沥、姜汁。痰壅盛者、口眼㖞斜者、不能言者，皆当用吐法，一吐不已，再吐。轻者用瓜蒂一钱，或稀涎散，或虾汁，以虾半斤，入酱、葱、姜等料物，水煮。先吃虾，次饮汁，后以鹅翎探引。吐痰用虾者，盖引其风出耳，重者用藜芦半钱，或三分，加麝香少许，齑汁调，吐。若口噤昏迷者，灌入鼻内吐之。虚者不可吐。气虚卒倒者，用参耆补之，有痰，浓煎参汤加竹沥、姜汁；血虚用四物汤，俱用姜汁炒，恐泥痰故也，有痰再加竹沥、姜汁入内服，能食者，去竹沥加荆沥。肥白人多温，少用乌头、附子行经，凡用乌、附，必用童便煮过，以杀其毒。初昏倒，急掐人中，至醒，然后用痰药，以二陈汤、四君子汤、四物汤加减用之；瘦人阴虚火热，用四物汤加牛膝、竹沥、黄芩、黄柏，有痰者加痰药，治痰气实而能食，用荆沥，气虚少食，用竹沥。此二味开经络行血气故也。入四物汤，必用姜汁助之。遗尿属气，以参耆补之。筋枯者，举动则痛，是无血不能滋养其筋，不治也。《脉诀》内言诸不治证：口开手撒，眼合遗尿，吐沫直视，喉如鼾睡，肉脱筋痛，发直摇头上窜，面赤如妆，或头面青黑，汗缀如珠，皆不可治。", "18624": "案《内经》以下，皆谓外中风邪。然地有南北之殊，不可一途而论。惟刘守真作将息失宜，水不能制火，极是。由今言之，西北二方，亦有真为风所中者，但极少尔。东南之人，多是湿土生痰，痰生热，热生风也。邪之所凑，其气必虚。风之伤人，在肺脏为多。许学士谓气中者亦有，此七情所伤。脉微而数，或浮而紧，缓而迟。必也脉迟浮可治，大数而极者死。若果外中者，则东垣所谓中血脉、中府、中脏之理，其于四肢不举，亦有与痿相类者，当细分之。《局方》风痿同治，大谬。发挥甚详。子和用三法，如的系邪气卒中，痰盛实热者可用，否则不可。", "18625": "上为末。汤酒调下。不效，时春脉伏，渐以淡盐汤齑汁每早一碗，吐五日。仍以白术、陈皮、茯苓、甘草、厚朴、菖蒲，日二帖。后以川芎、山栀、豆豉、瓜蒂、绿豆粉、齑汁、盐汤吐之，吐甚快。不食，后以四君子汤服之，以当归、酒芩、红花、木通、黏子、苍术、姜南星、牛膝、茯苓为末，酒糊丸。服十日后，夜间微汗，手足动而能言。", "18626": "〔附录〕风者，百病之始，善行而数变。行者动也，风本为热，热胜则风动。宜以静胜其燥，养血是也。治须少汗，亦宜少下，多汗则虚其卫，多下则损其荣。治其在经，虽有汗下之戒，而有中脏、中府之分，中府者宜汗之，中脏者宜下之。此虽合汗下，亦不可太过，汗多则亡阳，下多则亡阴，亡阳则损其气，亡阴则损其形。初谓表里不和，须汗下之，表里已和，是宜治之在经。其中府者，面显五色，有表证而脉浮，恶风恶寒，拘急不仁，或中身之后，身之前，身之侧，皆曰中府也。其治多易。中脏者，唇吻不收，舌不转而失音，鼻不闻香臭，耳聋而眼瞀，大小便秘结，或眼合直视，摇头，口开，手撒，遗溺，痰如拽锯，鼻鼾，皆曰中脏也。中脏者多不治也。六腑不和，留结为痈；五脏不和，九窍不通。无此乃在经也，初证既定，宜以大药养之，当顺时令而调阴阳，安脏腑而和营卫，少有不愈者也。风中府者，先以加减续命汤，随证发其表。如兼中脏，则大便多秘涩，宜以三化汤通其滞。初证已定，别无他变，以大药和治之。大抵中府者多著四肢，中脏者多滞九窍。中府者多兼中脏之证，至于舌强失音，久服大药，能自愈也。又因气中，其证与中风相似，但风中多痰涎，气中口中无涎，治之之法，调气为先，经言治风者以理气，气顺则痰消，徐理其风，庶可收效。又有中已，言不变，志不乱，病在分腠之间者，只宜温肝取解汗，为可复也。凡中风，脉多沉伏，大法浮迟者吉，沉实者凶。先用麻油调苏合香丸，或用姜汁，或用白汤调，如口噤，抉开灌之，稍醒则服八味顺气散。若痰盛者，只以省风导痰汤服之。若中则昏沉不省人事，口噤，急以生半夏末吹入鼻中，或用细辛、皂角为末吹之，喷嚏则苏，无嚏者不治。肥人中者，以其气盛于外而歉于内也，肺为气出入之道，肥者气必急，气急必肺邪盛，肺金克木，胆为肝之府，故痰涎壅盛。所以治之必先理气为急，中后气未顺，痰未除，调理之剂，惟当以藿香正气散和星香散煎服。此药非特可治中风之证，治中气中恶，尤宜，寻常止呕多痰者，亦可用之。若前证多怒，宜小续命汤加羚羊角；热而渴者，汤中去附子，加秦艽半钱；恍惚错语，加茯神、远志各半钱；不得睡，加酸枣仁半钱；不能言，加竹沥一蚬壳许；人虚无力者，去麻黄，加人参如其数。若人自苏，能言能食，惟身体不遂，急则挛蜷，缓则亸曳，经年不愈，以加减地仙丹常服。若饮食坐卧如常，但失音不语，只以小续命去附子，加菖蒲一钱。治风之法，初得之，即当顺气，及日久，即当活血，此万古不易之至理，惟可以四物汤吞活络丹愈者，正是此义。若先不顺气化痰，遽用乌、附，又不活血，徒用防风、天麻、羌活辈，吾未见能治也。又见风中于肤腠，辄用脑麝治之者，是引风入骨髓也，尤为难治，深可戒哉！如口㖞斜未正者，以蓖麻去壳烂捣，右㖞涂左，左㖞涂右，或鲜鱼血入麝香少许，涂之即正。嚏嚏，初卒倒，僵仆不知人事，急以皂角末，或不卧散于鼻内吹之，就提头顶发，立苏。若有嚏者可治，无嚏者不治。经曰：风从汗泄，似可微汗。正如解表，表实无汗者，散之劫之。表虚自汗者，温之解之。若气滞者难治，宜吐之（余症见前）。可下者，此因内有便溺之阻隔，故里实。若三五日不大便者，可与《机要》三化汤，或子和搜风丸，老人只以润肠丸。理气者，气滞气郁，肩膊麻痛之类，此七情也，宜乌药顺气、八味顺气之类；理血者，无表里之急，血弱举发不时者，用大秦艽汤，或羌活愈风汤，兼用化痰丸子。灸，可灸风池、百会、曲池、合谷、风市、绝骨、环跳、肩髃、三里等穴。皆灸之以凿窍疏风。", "18627": "每服五钱，水一盏半，姜五片，枣一枚，煎。温服，取微汗。随人虚实与所中轻重，加减于后：若热者，去附子，入白附子亦可；筋急拘挛，语迟，脉弦，加苡薏仁；若筋急，加人参，去黄芩、芍药，以避中寒，服后稍轻，再加当归；烦燥不大便，去附、桂，倍加芍药、竹沥；如大便三五日不去，胸中不快，加枳壳、大黄；如言语謇涩，手足颤掉，加菖蒲、竹沥；若发渴，加麦冬、葛根、栝蒌根；身体痛，加羌活；搐者亦加之；烦燥多惊者，加犀角、羚羊角；汗多者，去麻黄。", "18628": "〔附录〕法曰：四肢不收举，俗曰瘫痪，故经所谓太过则令人四肢不举。又曰：上太过则敦阜。阜，高也；敦，厚也。既厚而又高，则令除去，此真所谓膏粱之疾，非肾肝经虚。何以明之？经所谓三阳三阴发病，偏枯痿易，四肢不举。三阴不足，则发偏枯；三阳有余，则为痿易，易为变易，常用而痿弱无力也。其治则泻令气弱，阳衰土平而愈，故以三化汤下之。若脾虚则不用也，经所谓土不及则卑陷。卑，下也；陷，坑也。故脾病四肢不用，四肢皆禀气于胃，而不能至经，必因脾方可得禀受也。令脾不能与胃行其津液，四肢不得禀水谷，气日以衰，脉道不利，筋骨肌肉皆无气以生，故不用焉。其治可大补十全散、加减四物汤，去邪留正。", "18629": "戴云：此伤寒，谓身受肃杀之气，口伤生冷物之类。因胃气大虚，肤腠疏豁，病者脉必沉细，手足厥冷，息微身倦，虽身热亦不渴，倦言动者是也，宜急温之，迟则不救矣。与热症若相似而实不同，凡脉数者，或饮水者，烦燥动摇者，皆热病。寒热二证，若水火然，不可得而同治，误即杀人。", "18630": "上锉。每服三钱，水煎服。挟气攻刺，加木香半钱；挟气不仁，加防风一钱；挟湿者，加白术；筋脉牵急，加木瓜；肢节痛，加桂二钱。", "18631": "暑证，用黄连香薷饮。挟痰，加半夏、南星；虚，加人参、黄耆。暑病内伤者，用清暑益气汤，著暑气是痰，用吐。注夏属阴虚，元气不足，夏初春末，头疼脚软，食少体热者是，宜补中益气汤，去柴胡、升麻，加炒柏、白芍药。挟痰者，加南星、半夏、陈皮，煎服，又或用生脉汤。暑风挟痰挟火，实者可用吐法。", "18632": "暑乃夏月炎暑也，盛热之气者火也，有冒、有伤、有中，三者有轻重之分，虚实之辨。或腹痛水泻者，胃与大肠受之，恶心者，胃口有痰饮也。此二者冒暑也，可用黄连香薷饮、清暑益气汤，盖黄连退暑热，香薷消蓄水。或身热头疼，燥乱不宁者，或身如针刺者，此为热伤在分内也，当以解毒汤、白虎汤，加柴胡，气如虚者，加人参。或咳嗽发寒热，盗汗出不止，脉数者，热在肺经，用清肺汤、柴胡天水散之类急治则可，迟则不救，成火乘金也，此为中暑。凡治病，须要明白辨别，慎勿混同施治。春秋间亦或有之，切莫执一，随病处方为妙。戴云：暑风者，夏月卒倒，不省人事者是也。有因火者，有因痰者。火，君相二火也；暑，天地二火也。内外合而炎烁，所以卒倒也。痰者，人身之痰饮也，因暑气入而鼓激痰饮，塞碍心之窍道，则手足不知动蹑而卒倒也。此二者皆可吐。《内经》曰：火郁则发之。吐即发散也。量其虚实而吐之，吐醒后，可用清剂调治之。", "18633": "〔附录〕中暍是阳证，中暑是阴证。脉沉弱者，切不可用寒凉药。清热宜天水散、五苓、白虎汤皆可。热闷恍惚，辰砂五苓散。脉弦实，黄连香薷汤。热甚，自汗而渴，便涩者，五苓分利之，或桂苓甘露饮。吐泻，脉沉微甚者，可用附子大顺散。伏热伤冷，缩脾饮、冷香饮子皆可浸冷服之。或剥蒜肉入鼻中，或研蒜水解灌之，盖蒜气臭烈，能通诸窍故也。", "18634": "生脉汤", "18635": "人参白虎汤治暑热，发渴，脉虚。", "18636": "冷香饮子治伤暑渴，霍乱腹痛烦躁，脉沉微，或伏。", "18637": "防己黄耆汤治风温脉浮，身重汗出恶风或痛。", "18638": "左手脉大于右手，浮缓而盛，按之无力。", "18639": "地骨皮散治浑身壮热，脉长而滑，阳毒火炽发渴。", "18640": "化斑汤治伤寒汗吐下后，斑发脉虚。", "18641": "疟脉多弦，但热则弦而带数，寒则弦而带迟，亦有病久而脉极虚微而无力，似乎不弦，然而必于虚微之中见弦，但不搏手耳。细察可见也。", "18642": "有汗要无汗，正气为主。小柴胡加桂，或白虎加桂。无汗要有汗，散邪为主，带补。桂枝加黄耆、知母、石膏汤，或人参柴胡饮子。热多寒少、目痛多汗、脉大，以大柴胡汤，微利为度。余邪未尽，以白芷石膏三物汤，以尽其邪。", "18643": "人参二分，姜炒黄连一分，为末浓煎，终日细细呷之，如吐则再服，但一呷下咽便开。人不知此，多用温热药甘味，此以火济火，以滞益滞，封脐引热下行，用田螺肉捣碎，入麝香少许。盦脐内。下痢不治之症，下如鱼脑者，半死半生；下如尘腐色者，死；下纯血者，死；下如屋漏水者，死；下如竹筒注者，不治。赤痢乃自小肠来，白痢乃自大肠来，皆湿热为本，赤白带浊同法。下痢有风邪下陷，宜升提之，盖风伤肝，肝主木故也；有湿伤血，宜行湿清热。《内经》所谓身热则死，寒则生，此是大概言，必兼证详之方可。今岂无身热而生，寒而死者？脉沉小留连或微者易治，洪大数者难治也。脉宜滑大，不宜弦急。仲景治痢可温者五法，可下者十治，或解表，或利小便，或待其自已，还分易治难治不治之证，至为详密。但与泻同，立论不分，学者当辨之。大抵痛，一曰温之，一曰清之。按久病身冷，脉沉小者，宜温；暴病身服，脉浮洪者，宜清、宜补。有可吐者，亦有可汗可下者。初得之时，元气未虚，必推荡之，此通因通用之法。稍久气虚，则不可下。壮实初病宜下，虚弱衰老久病宜升之。先水泻，后脓血，此脾传肾，贼邪难愈；先脓血，胜水泻，此肾传脾，微邪易愈。下痢如豆汁者湿也，盖脾肾为水谷之海，无物不受，常兼四脏，故五色之相杂。当先通利，此迎而夺之之义。如虚者，亦宜审之。因热而作，不可用巴豆。如伤冷物者，或可用，宜谨。又有时疫作痢，一方一家之内，上下传染相似，却宜明逆气之胜复以治之。", "18644": "〔附录〕痢有气虚兼寒热，有食积，有风邪，有热有湿，有阳气下陷，而感受不一，当分治。泻轻痢重，诸有积以肚热缠痛推之，诸有气以肚如蟹渤验之，究其受病之源，决之对病之剂。大要以散风邪，行滞气，开胃脘为先，不可遽用肉豆蔻、诃子、白术辈以补住寒邪，不可投米壳、龙骨辈以闭涩肠胃。邪得补而愈盛，故证变作，所以日夕淹延而未已也。若升散者，以胃风汤、防风芍药汤、神术散、苍术防风汤、败毒散，皆可汗之。攻里若有湿者，用导水丸、兼郁承气汤、和中丸；若积滞用圣饼子、脾积丸；冷积用《局方》苏感丸；若湿热甚者，宜《宣明》玄青膏；若后重窘迫，用木香槟榔丸。色白者，属气；赤白者，属气血受病；赤黑相兼，属湿热；青绿杂色，是风与火湿。下血者，当凉血，当归、生地黄。赤者属血，《保命集》四物汤，和槐花、黄连、米壳醋炒。下利，脉沉弱而腹痛，用姜附汤，加对五苓理中。又机要浆水散若青色者，寒兼风，若阳气下陷者，以升阳益胃汤加桔梗、醋沃南星，用梅叶外贴眉攒极效，起泡便止。下痢若湿盛胜湿者，以平胃散对五苓散最可，或曲芎丸。老人奉养大过，饮食伤脾，为脾泄，《机要》白术芍药汤。湿胜，仙术炒用。若阴阳不分，当渗泄以五苓之类，或单用苤苡实炒为末，米饮调二钱。若气血俱虚，神弱者，以人参、白术、当归、芍药、炒茯苓，少加黄连服之，或钱氏白术散，又或十补汤佳。若暑痢而脉虚者，香薷饮，或清暑益气，又或六和汤、藿香正气各加木香半钱，名木香交加散。若白痢下如冻胶，或鼻涕，此属冷痢，宜除湿汤加木香一钱。虚弱者，亦与十补汤。赤痢发热者，以败毒散加陈仓米一撮煎。下痢小便不通者，黄连阿胶丸为最。", "18645": "一老人年七十，面白，脉弦数，独胃脉沉滑，因饮白酒作痢，下血淡脓水，腹痛，小便不利，里急后重。参、术为君，甘草、滑石、槟榔、木香、苍术为佐，下保和丸二十五丸，第二日前证俱减，独小便不利。以益元散与之，安。", "18646": "〔附录〕凡人五味之秀者养脏腑，诸阳之浊者归大肠，大肠所以司出而不纳也。今停蓄蕴结，独不得疏导何哉？抑有由矣！邪入里，则胃有燥粪，三焦伏热，则津液中干，此大肠挟热然也。虚入脏冷而血脉枯，老人脏寒而气道涩，此大肠之挟冷然也。亦有肠胃受风，涸燥秘涩，此证以风气蓄而得之。若夫气不下降而谷道难，噫逆泛满，必有其证矣。", "18647": "内有所积，外有所感，致成吐泻，仍用二陈汤加减作吐以提其气。此非鬼神，皆属饮食，前人确论，乃阳不升，阴不降，垂隔而成。切莫与谷食，虽米饮一呷，入口即死。必待吐泻过二三时，直至饥甚，方可与稀粥食之，脉多伏欲绝。见成吐泻不彻，还用吐提其气起不透，或用樟木煎汤，吐之亦可。大法：生姜理中汤最好，不渴者可用。如渴者用五花散，有吐者以二陈汤探吐，亦有可下者。转筋不住，男子以手挽其阴，女子以手牵乳，近两边，此千金妙法也。转筋皆属乎血热，四物汤加酒、芩、红花、苍术、南星煎服。干霍乱者，最难治，死在须臾。升降不通，当以吐提其气，极是良法，世多用盐汤。此系内有物所伤，外有邪气所遏。有用吐者，则兼发散之义；有用温药解散者。不可用凉药，宜二陈汤加解散药。", "18648": "通脉四逆汤治霍乱多寒，身冷，脉绝。", "18649": "脉浮当吐。久得脉涩，卒难开也，必费调理。大凡治痰用利药过多。致脾气虚，则痰易生而多。湿痰，用苍术、白术；热痰，用青黛、黄连、芩；食积痰，用神曲、麦芽、山楂；风痰，用南星；老痰，用海石、半夏、栝蒌、香附、五倍子，作丸服。痰在膈上，必用吐法，泻亦不能去。风痰多见奇证，湿痰多见倦怠软弱。气实痰热结在上者，吐难得出。痰清者属寒，二陈汤之类。胶固稠浊者，必用吐。热痰挟风，外证为多。热者清之；食积者，必用攻之；兼气虚者，用补气药送；痰因火盛逆上者，以致火为先，白术、黄芩、软石膏之类；内伤挟痰，必用参、耆、白术之属，多用姜汁传送，或加半夏；虚甚，加竹沥；中气不足，加参、术。痰之为物，随气升降，无处不到。脾虚者，宜清中气以运痰降下，二陈汤加白术之类，兼用升麻提起。中焦有痰则食积，胃气亦赖所养，卒不便虚，若攻之尽，则虚矣。痰成块，或吐咯不出，兼气郁者，难治。气湿痰热者，难治。痰在肠胃间者，可下而愈；在经络中，非吐不可。吐法中就有发散之义焉。假如痫病，因惊而得，惊则神出舍，舍空则痰生也。血气入在舍，而拒其神，不能归焉。血伤必用姜汁传送。黄芩治热痰，假其下火也。竹沥滑痰。非姜汁不能行经络。五倍子能治老痰，佐他药，大治顽痰。二陈汤，一身之痰都治管，如要下行，加引下药；在上，加引上药。凡用吐药，宜升提其气，便吐也，如防风、山栀、川芎、桔梗、芽茶、生姜、齑汁之类，或用瓜蒂散。凡风痰病，必用风痰药，如白附子、天麻、雄黄、牛黄、片芩、僵蚕，猪牙、皂角之类（诸吐法另具于后）。", "18650": "〔附录〕肺以清阳上升之气，居五脏之上，通荣卫，合阴阳，升降往来，无过不及。六淫七情之所感伤，饱食动作，脏气不和，呼吸之息，不得宣畅而为喘急。亦有脾肾俱虚，体弱之人，皆能发喘。又或调摄失宜，为风寒暑湿邪气相干，则肺气胀满，发而为喘。又因痰气皆能令人发喘，治疗之法当究其源。如感邪气，则驱散之；气郁，即调顺之；脾肾虚者，温理之。又当于各类而求。凡此证，脉滑而手足温者生，脉涩而四肢寒者死。风伤寒者，必上气急，不得卧，喉中有声，或声不出，以三拗汤、华盖散、九宝汤、神秘汤皆可选用；若痰喘，以四磨汤或苏子降气汤；若虚喘，脉微，色青黑，四肢厥，小便多，以《活人书》五味子汤或四磨汤。治嗽与喘，用五味子为多，但五味有南北。若生津止渴，润肺益肾，治劳嗽，宜用北五味；若风邪在肺，宜用南五味。", "18651": "〔附录〕《金匮方论》曰：热在上焦者，因咳为肺痿，得之或从汗出，或从呕吐，或消渴小便利数，或从便难，又被快药下利，重亡津液，故寸口脉数，其人咳，口中有浊唾涎沫者，为肺痿之病，其人脉数虚者是。", "18652": "〔附录〕肺痈为何？口中辟辟燥，咳即胸中隐隐痛，脉反滑数或数实者，此为肺痈也。", "18653": "吐血，阳盛阴虚，故血不得下行。因火炎上之势而上出，脉必大而芤，大者发热，芤者血滞与失血也。大法：补阴抑火，使复其位，用交趾桂五钱为末，冷水调服。山栀子最清胃脘之血。吐血，觉胸中气塞，上吐紫血者，桃仁承气汤下之。先吐绝，后见痰嗽，多是阴虚火动，痰不下降，四物汤为主，加痰药、火药；先痰嗽后见红，多是痰积热，降痰火为急；痰嗽涎带血出，此是胃口清血热蒸而出，重者栀子，轻者蓝实；或暴吐紫血一碗者无事，吐出为好。此热伤血死于中，用四物汤、解毒汤之类。吐血挟痰，积吐一二碗者，亦只补阴降火，四物加火剂之类。挟痰若用血药，则泥而不行，只治火则止。吐血，火病也。大吐红不止，以干姜炮末，童便调从治。喉腕痰血，用荆芥散。舌上无故出血，如线不止，以槐花炒末干掺之。若吐血，一方：童便一分，酒半分，擂柏叶温饮，非酒不行。呕吐，血出于胃也。实者，犀角地黄汤主之；虚者，小建中汤加黄连主之。", "18654": "〔附录〕凡血证上行，或唾或呕或吐，皆逆也；若变而下行为恶痢者，顺也。上行为逆，其治难；下行为顺，其治易。故仲景云：蓄血证，下血者，当自愈也。与此意同。若无病人忽然下痢，其病进也。今病血证上行，而复下行恶痢者，其邪欲去，是知吉也。诸见血，身热脉大者难治，是火邪胜也；身凉脉静者易治，是正气复也。故《脉诀》云：鼻衄吐血沉细宜，忽然浮大即倾危。", "18655": "呕血，火载血上，错经妄行。脉大发热，喉中痛者，是气虚，用参、耆、蜜炙黄柏、荆芥、当归、生地黄服之；呕血，用韭汁、童便、姜汁磨郁金，同饮之，其血自清；火载血上，错经妄行，用四物汤加炒山栀、童便、姜汁服。", "18656": "〔附录〕下血当别其色，色鲜红为热，以连蒲散。又若内蕴热毒，毒气入肠胃，或因饮酒过多，及淡糟藏炙爆引血入大肠，故下血鲜红，宜黄连丸，或一味黄连煎。余若大下不至者，宜四物汤加黄连、槐花，仍取血见愁少许，生姜捣取汁，和米大服。于血见愁草中，加入侧柏叶，与生姜同捣汁，尤好。毒暑入肠胃下血者，亦宜加味黄连、槐花入煎服。血色瘀者为寒，血逐气走，冷寒入客肠胃，故上瘀血，宜理中汤温散。若风入肠胃，纯下清血，或湿毒，并宜胃风散加枳壳、荆芥、槐花。攧扑损恶，血入肠胃，下血浊如瘀血者，宜黑神散加老黄茄为末，酒调下。《内经》云：「下血为内伤络脉所致」，用枳壳一味服；又方：用黄连二两，枳壳二两，槐花八两炒上一味，去槐花不用，止以二味煎服，立效，以解络脉之结也。", "18657": "又方脉缓大，口渴，月经紫色，劳伤挟湿。", "18658": "〔附录〕痔者，皆因脏腑本虚，外伤风湿，内蕴热毒，醉饱交接，多欲自戕，以故气血下坠，结聚肛门，宿滞不散，而冲突为痔也。其肛边发露肉珠，状如鼠乳，时时滴渍脓血，曰牡痔；肛边生疮肿痛，突出一枚，数日脓溃即散，曰牝痔；肠口大颗发㿔，且痛且痒，出血淋沥，曰脉痔；肠内结核有血，寒热往来，登溷脱肛，曰肠痔。若血痔则每遇大便，清血随而不止；若酒痔则每遇饮酒，发动疮肿，痛而流血；若气痔则忧恐郁怒，适临乎前，立见肿痛，大便艰难，强力则肛出而不收矣。此诸痔之外证也。治法总要，大抵以解热调血顺气先之。盖热则血伤，血伤则经滞，经滞则气不运行，气与血俱滞，乘虚而坠入大肠，此其所以为痔也。诸痔久不愈，必至穿穴为漏矣。", "18659": "翻胃大约有四，血虚、气虚、有热、有痰兼病。必用童便、韭汁、竹沥、牛羊乳、生姜汁。气虚，入四君子汤，右手脉无力；血虚，入四物汤加童便，左手脉无力。切不可用香燥之药，若服之必死，宜薄滋味。治反胃，用黄连三钱，生姜汁浸，炒山楂肉二钱，保和丸二钱，同为末，糊丸如麻子大，胭脂为衣，人参汤入竹沥再煎一沸，下六十丸。有痰，二陈汤为主，寸关脉沉或伏而大；有气结，宜开滞导气之药，寸关脉沉而涩；有内虚阴火上炎而反胃者，作阴火治之。年少者，四物汤清胃脘，血燥不润便故涩，《格致余论》甚详；年老，虽不治，亦用参术，关防气虚胃虚。气虚者，四君子汤加芦根、童便，或参苓白术散，或韭汁、牛羊乳，或入駮驴尿。又有积血停于内而致，当消息逐之，大便涩者难治，常令食兔肉，则便利。翻胃即膈噎，膈噎乃翻胃之渐。《发挥》备言年高者不治。粪如羊屎者，断不可治，大肠无血故也。", "18660": "戴云：翻胃，血虚者，脉必数而无力；气虚者，脉必缓而无力；气血俱虚者，则口中多出沫，但见沫大出者必死。有热者，脉数而有力；有痰者，脉滑数，二者可治。血虚者，四物为主；气虚者，四君子为主；热以解毒为主；痰以二陈为主。", "18661": "脉缓有痰而痞，加半夏、黄连；脉弦，四肢满闷，便难，而心下痞，加柴胡、黄连、甘草；大便秘燥，加黄连、桃仁，少加大黄、归身；心下痞，瞀闷者，加白芍药、黄连；心下痞，中寒者，加附子、黄连；心下痞，腹胀，加五味子、白芍、砂仁；天寒，少加干姜，或中桂；心下痞，呕逆者，加黄连、生姜、陈皮如冬月，加黄连，少入丁香、藿香；心下痞，如腹中气上逆者，是冲脉逆也，加黄柏三分，黄连一分半以泄之；如食已，心下痞，别服橘皮枳术丸。", "18662": "枳实消痞丸治右关脉浮弦，心下虚痞，恶食，懒倦。开胃进食。", "18663": "〔附录〕黄疸乃脾胃经有热所致，当究其所因，分利为先，解毒次之。诸疸口淡，怔忡耳鸣，脚软，微寒发热，小便白浊，此为虚证。治宜四君子汤，吞八味丸，不可过用凉剂强通小便，恐肾水枯竭。久而面黑黄色，及有渴者不治；不渴者可治。黄疸，通身面目悉黄，宜生料五苓散加茵陈；又宜小柴胡加茵陈、茯苓、枳实，少加朴硝；《济生》茵陈汤；《千金方》：东引桃根细者煎，空心服。谷疸，食已头眩，心中怫郁不安，饥饱所致，胃气蒸冲而黄，宜小柴胡加谷芽、枳实、厚朴、山栀、大黄，《济生》谷疸丸。酒疸，身目黄，心中懊𢙐，足胫满，尿黄面黄而赤斑，酒过胃热，醉卧当风，水湿得之，小柴胡加茵陈、豆豉、大黄、黄连、葛粉。脉微数，面目青黑，或大便黑，《三因方》白术散；脉弦涩，《三因》当归白术散，《济生方》五苓加葛根汤。女劳疸，因房事后为水湿所搏，故额黑身黄，小腹满急，小便不利，以大麦一撮，同滑石、石膏末各一钱煎服。黄汗者，因脾胃有热，汗出入水澡浴所致，故汗出黄染衣而不渴，《济生方》黄耆散、茵陈汤。又以苦丁香如豆大，深吸鼻中，出黄水瘥。发黄，脉沉细迟，四肢逆冷，身冷，自汗不止，宜茵陈四逆汤。", "18664": "〔附录〕腰以下肿，宜利小便；腰以上肿，宜发汗。此仲景之要法也。诸家只知治湿当利小便之说，执此一途，用诸去水之药，往往多死。又用导水丸、舟车丸、神佑丸之类大下之，此速死之兆。盖脾极虚而败，愈下愈虚，虽劫效目前，而阴损正气，然病亦不旋踵而至。大法，宜大补中宫为主，看所挟加减，不尔则死。当以严氏实脾散加减用。阳病水兼阳证者，脉必沉数；阴病水兼阴证者，脉必沉迟，水之为病不一。贾洛阳以病肿不治，必为锢疾，虽有扁鹊，亦莫能为，则知肿之危恶，非他病比也。夫人之所以得全其性命者，水与谷而已。水则肾主之，土谷则脾主之，惟肾虚不能行水，惟脾虚不能制水，胃与脾合气，胃为水谷之海，又因虚而不能传化焉。故肾水泛溢，反得以浸渍脾土，于是三焦停滞，经络壅塞，水渗于皮肤，注于肌肉而发肿矣。其状：目胞上下微起，肢体重著咳喘，怔忡，股间清冷，小便涩黄，皮薄而光，手按成窟，举手即满是也。治法：身有热者，水气在表，可汗；身无热，水气在里，可下。其间通利小便，顺气和脾，俱不可缓耳。证虽可下，又当权其重轻，不可过用芫花、大戟、甘遂猛烈之剂，一发不收，吾恐峻决者易，固闭者难，水气复来而无以治之也。风肿者，皮粗，麻木不仁，走注疼痛；气肿者，皮厚，四肢瘦削，腹胁胀膨。其皮间有红缕赤痕者，此血肿也。妇人怀胎，亦有气遏水道而虚肿者，此但顺气安脾，饮食无阻，既产而肿自消。大凡水肿，先起于腹，而后散四肢者，可治；先起于四肢，而后归于腹者，不治。大便滑泄，与夫唇黑、缺盆平、脐突、足平、背平，或肉硬，或手掌平，又或男从脚下肿而上，女从身上肿而下，并皆不治。若遍身肿，烦渴，小便赤涩，大便闭，此属阳水，先以五皮散，或四磨饮，添磨生枳壳，重则疏凿饮；若遍身肿，不烦渴，大便溏，小便少，不涩赤，此属阴水，宜实脾饮，或木香流气饮。", "18665": "鼓胀又名单鼓，宜大补中气行湿，此乃脾虚之甚，必须远音乐，断厚味，大剂人参、白术，佐以陈皮、茯苓、苍术之类。有血虚者，用四物汤行血药。有脉实坚人壮盛者，或可攻之，便可收拾，用参、术为主。凡补气，必带厚朴宽满，厚朴治腹胀，因味辛以气聚于下焦故也，须用姜汁制之。如肥胖之人腹胀者，宜平胃、五苓共服之；如白人腹胀者，是气虚，宜参、术、厚朴、陈皮；如瘦人腹胀者，是热，宜黄连、厚朴、香附、白芍；如因有故蓄血而腹胀者，宜抵当丸下死血；如因有食积而腹胀者，有热，用木香槟榔丸，有寒，用木香、厚朴、丁香，砂仁、神曲、香附；如因外寒郁内热而腹胀者，用藿香、麻黄、升麻、干葛、桂枝；因大怒而腹胀者，宜青皮、陈皮、香附、木香、栀子仁、芦荟。实者，按之不坚不痛。治须实者下之、消之，次补之；虚者温之、升之，补为要。朝宽暮急，血虚；暮宽朝急，气虚；终日急，气血皆虚。腹胀不觉满者，食肉多，以黄连一两，阿魏半两，醋浸蒸饼为丸，同温中丸、白术汤下。食肉多腹胀，三补丸料内加香附、半夏曲，蒸饼丸服。", "18666": "紫苏子汤治忧思过度，致伤脾胃，心腹胀满，喘促烦闷，肠鸣气走，漉漉有声，大小便不利，脉虚紧而涩。", "18667": "关格，必用吐，提其气之横格，不必在出痰也。有痰宜吐者，二陈汤吐之，吐中便有降。有中气虚不运者，补气药中升降。寒在上，热在下，脉两手寸俱盛四倍以上。", "18668": "浊主湿热，有痰、有虚。赤属血，白属气。痢带同治，寒则坚凝，热则流通。大率皆是湿痰流注，宜燥中宫之湿，用二陈加苍术、白术燥去其湿。赤者，乃是湿伤血也，加白芍药，仍用珍珠粉丸加臭椿根白皮、滑石、青黛，作丸药。虚劳用补阴药，大概不宜热（一作凉）药；肥白人必多痰，以二陈汤去其湿热。胃弱者，兼用人参，以柴胡、升麻升其胃中之气；丸药，用黄柏炒褐色，干姜炒微黑，滑石、蛤粉、青黛，糊丸服。胃中浊气下流，为赤白浊，用二陈加柴胡、升麻、苍术、白术；丸药用樗皮末、蛤粉、炒干姜、炒黄柏。胃中浊气下流，渗入膀胱，青黛、蛤粉。肝脉弦者，用青黛以泻肝。又方：炒黄柏一两，生柏一两，滑石三两，神曲半两，为末，滴水丸。燥湿痰，南星、半夏、蛤粉、青黛，为末，神曲糊丸，青黛为衣。有热者，青黛、滑石、黄柏之类，水丸。张子元气血两虚有痰，痛风时作，阴火间起，小便白浊，方在痛风类。一人便浊经年，或时梦遗，形瘦，作心虚主治，用珍珠粉丸，和定志丸服。一妇人年近六十，形肥奉养膏粱，饮食肥美，中焦不清，浊气流入膀胱，下注白浊，白浊即湿痰也，用二陈去痰，加升麻、柴胡升胃中清气，加苍术去湿，白术补胃，全在活法。服四帖后，浊减大半，却觉胸满。因柴胡、升麻升动胃气，痰阻满闷。又用本汤加炒曲、白术、香附。素无痰者，虽升动不满也。", "18669": "半夏（燥湿）猪苓（分水）肝脉弦，加青黛。", "18670": "阴虚发热症难治。戴云：凡脉数而无力者，便是阴虚也，四物汤加炒黄柏、黄芩、龟板。兼气虚，加人参、黄耆、黄芩、白术。四物汤加炒柏，是降火补阴之妙剂，甚者必加龟板。吃酒人发热，难治；不饮酒人因酒发热者，亦难治。一男子年二十三岁，因酒发热，用青黛、栝蒌仁，入姜汁，每日数匙入口中，三日而愈。阳虚发热，补中益气汤。手足心热，属热郁，用火郁汤。伤寒寒热，当用表散。发热，柴胡；恶寒，苍术；虚人，用苍术，恐燥。发热恶风，人壮气实者，宜先解表。发热恶寒，亦宜解表。", "18671": "胸中烦热，须用栀子仁。有实热而烦躁者，亦用栀子仁；有虚热而烦躁者，宜参、耆、麦门冬、白茯苓、竹茹、白芍药。若脉实数有实热者，神芎丸。", "18672": "戴云：凡背恶寒甚者，脉浮大而无力者，是阳虚也。", "18673": "〔附录〕或问湿之与汗，为阴乎，为阳乎？曰：西南，坤土也，在人则为脾胃也。人之犹天地之雨也，阴滋其湿则为露，露为雨也。阴湿下行，地之气也。汗多则亡阳，阳去则阴胜也。甚则寒中。湿胜则音声如从瓮中出，言其壅也，不出也，以明其湿审矣。《内经》曰：「气虚则外寒」，虽见热中，蒸蒸为汗，终传大寒，知始为热中。表虚亡阳，不任外寒，终传寒中，多成痹寒矣。色以候天，脉以候地。形者，乃候地之阴阳也，故以脉气候之，皆有形无形之可见者也。又云：「心之所藏，在内者为血，发外者为汗」。盖汗乃心之液，而自汗之证，未有不由心肾俱虚而得之者。故阴虚阳必凑，发热而自汗；阳虚阴必乘，发厥而自汗。故阴阳偏胜所致也。", "18674": "又方治体弱，肌肥壮，血虚脉大。", "18675": "茯神汤治脉虚极，或咳则心痛，喉中介介或肿。", "18676": "八物汤治心肺俱损，皮聚毛落，血脉虚损，妇人月水愆期，宜益气和血。四君子合四物汤", "18677": "无比山药丸治诸虚百损，五劳七伤，肌体消瘦，肤燥脉弱。", "18678": "戴云：郁者，结聚而不得发越也。当升者不得升，当降者不得降，当变化者不得变化也，此为传化失常。六郁之病见矣。气郁者，胸胁痛，脉沉涩；湿郁者，周身走痛，或关节痛，遇阴寒则发，脉沉细；痰郁者，动则喘，寸口脉沉滑；热郁者，瞀闷，小便赤，脉沉数；血郁者，四肢无力，能食便红，脉沉；食郁者，嗳酸，腹饱不能食，人迎脉平和，气口脉繁盛者是也。", "18679": "黄耆（劳役病甚可用一钱半，嗽者减去一钱）人参（一钱，有嗽去之）甘草（炙，一钱）以上三味除燥热肌热之圣药）当归身（酒洗，焙干，半钱，以和血脉）柴胡（半钱引清气行少阳之气上升）陈皮（半钱，以导滞气，又能同诸甘药益元气，独用泻脾）白术（半钱）升麻（三分，引胃气上腾而复其本位）葛根（半钱，如渴用之，不渴不用，一方有白芍半钱，秋冬不用红花三分少加黄柏三分，以救肾水，泻伏火", "18680": "上作一服，水煎，午前稍热服。若病日久者，以权立加减法。若头痛，加蔓荆子三分；痛甚，加川芎五分；顶疼脑痛者，加藁本五分，细辛三分；诸头痛并用此药四味；头痛有痰，沉重懒倦者，乃太阴厥阴头疼，加半夏半钱或一钱，生姜三片；若耳鸣、目黄、颊颔肿，颈肩臑肘臂外后廉痛、面赤、脉洪大者，加羌活一钱，防风七分，甘草三分，藁本五分，通其经血，加黄芩、黄连各三分消其肿；嗌痛颔肿，脉洪大，面赤，加黄芩三分，桔梗七分，甘草三分；口干嗌干或渴者，加葛根五分，升胃气上行以润之；心下痞，瞀闷者，加芍药、黄连各一钱；如痞腹胀，加枳实三分，厚朴七分，木香、砂仁各三分；如天寒，加干姜；腹中痛，加白芍药炒半钱，炙甘草三分；如恶寒觉冷痛，加中桂（即桂心）半钱；夏月腹中痛，不恶寒不恶热者，加黄芩五分，芍药一钱，甘草五分，以治时热；脐下痛者，加真熟地黄半钱；如胸中滞气，加莲花青皮一分或二分，壅滞可用，气促少气者去之；如身体重疼，乃风湿相搏，加羌活半钱，防风半钱，升麻一钱，柴胡半钱，藁本根半钱，苍术一钱。如病去，勿再服。若大便秘涩，加当归梢一钱；若久病痰嗽者，去人参，冬月加不去节麻黄，秋凉亦加不去根节麻黄，春月天温，只加佛耳草三分，款花一分，勿加麻黄。若初病之人，虽痰嗽不去人参，必不增添。若久病肺中伏火者，去人参，以防痰嗽增益耳。长夏湿土，客邪大旺，加苍术、白术、泽泻，上下分消其湿热之气。湿热大胜，主食不消，故食减不知谷味，则加曲以消之，加五味子、麦门冬，助人参泻火，益肺气，助秋损也，在三伏中为圣药。胁下急或痛，俱加柴胡、甘草、人参；多唾，或唾白沫，胃口上停寒也，加益智仁；若胃脘当心痛，加草豆仁三分。疲甚之人，参、耆、术有用至一两二两者。", "18681": "〔附录〕五脏之积曰五积，六腑之积曰六聚。积有定形，聚无定处。不问何经，并宜服十味大七气汤，吞下尊贵红丸子。凡木香、槟榔，去气积；神曲、麦芽，去酒积；虻虫、水蛭，去血积；礞石、巴豆，去食积；牵牛、甘遂，去水积；雄黄、腻粉，去涎积；硇砂、水银，去肉积。各从其类也。肝积曰肥气，肺积曰息贲，心积曰伏梁，脾积曰痞气，肾积曰奔豚。其如积聚之脉，实强者生，沉小者死。", "18682": "厥，逆也，手足因气血逆而冷也。因气虚为主，有因血虚。气虚脉细，血虚脉大，热厥脉数，外感脉沉实，有痰脉弦。因痰者，用白术、竹沥；气虚，四君子；血虚，四物；热厥，用承气；外感，用双解散加姜汁、酒。有阴厥阳厥，阴衰于下则热，阳衰于下则寒。", "18683": "〔附录〕厥者，甚也，短也，逆也，手足逆冷也，其证不一，散之方书者甚多。今姑撮大概，且如寒热厥逆者，则为阴阳二厥也。阳厥者，是热深则厥，盖阳极则发厥也，不可作阴证，而用热药治之，精魂绝而死矣。急宜大小承气汤，随其轻重治之。所谓阴厥者，始得之，身冷脉沉，四肢逆，足蜷卧，唇口青，或自利不渴，小便色白，此其候也。治之以四逆、理中之辈，仍速灸关元百壮。又尸厥、飞尸、卒厥，此即中恶之候，因冒犯不正之气，忽然手足逆冷、肌肤粟起、头面青黑、精神不守，或错言妄语、牙紧口噤，或昏不知人，头旋晕倒，此是卒厥客忤，飞尸鬼击、吊死问丧、入庙登冢，多有此病。以苏合丸灌之。候稍苏，以调气散和平胃散服，名「调气平胃散」。痰厥者，乃寒痰迷闷，四肢逆冷，宜姜附汤，以生附汤，以生附代熟附。蛔厥者，乃胃寒所生，经曰：「蛔者，长虫也」。胃中冷即吐蛔虫。宜理中汤加炒川椒五粒、槟榔半钱吞。乌梅丸效。蛔见椒则头伏故也。气厥者，与中风相似，何以别之？风中身温，气中身冷，以八味顺气散或调气散。如有痰，以四七汤、导痰汤服之。", "18684": "癫属阴，狂属阳，癫多喜而狂多怒，脉虚者可治，实则死。大率多因痰结于心胸间，治当镇心神、开痰结。亦有中邪而成此疾者，则以治邪法治之，《原病式》所论尤精。盖为世所谓重阴者癫，重阳者狂是也，大概是热。癫者，神不守舍，狂言如有所见，经年不愈，心经有损，是为真病。如心经蓄热，当清心除热；如痰迷心窍，当下痰宁志。若癫哭呻吟，为邪所凭，非狂也，烧蚕纸，酒水下方寸匕。卒狂言鬼语，针大拇指甲下，即止。风癫引胁痛，发则耳鸣，用天门冬去心，日干作末，酒服方寸匕。癫证，春治之，入夏自安，宜助心气之药。阳虚阴实则癫，阴虚阳实则狂。狂病宜大吐下则除之。", "18685": "如肢节痛，须用羌活，去风湿亦宜用之。如肥人肢节痛，多是风湿与痰饮，流注经络而痛，宜南星、半夏；如瘦人肢节痛，是血虚，宜四物加防风、羌活；如瘦人性急燥而肢节痛发热，是血热，宜四物汤加黄芩、酒炒黄柏；如肢节肿痛脉滑者，当用燥湿，宜苍术、南星，兼行气药木香、枳壳、槟榔，在下者加汉防己；若肢节肿痛脉涩数者，此是瘀血，宜桃仁、红花、当归、川芎及大黄微利之；如倦怠无力而肢节痛，此是气虚，兼有痰饮流注，宜参、术、星、半。丹溪无肢节痛条，此文又纯似丹溪语，姑书以俟知者。", "18686": "治麻风脉大而虚者。", "18687": "上为末。用乌蛇肉酒煮，如无蛇，以乌鲤鱼亦可，糊丸服之。候脉实，再用通天再造散取虫。", "18688": "头眩，痰，挟气虚并火。治痰为主，挟补气药及降火药。无痰则不作眩，痰因火动。又有湿痰者，有火痰者。湿痰者，多宜二陈汤。火者，加酒芩。挟气虚者，相火也，治痰为先，挟气药降火，如东垣半夏白术天麻汤之类。眩晕不可当者，以大黄酒炒为末，茶汤调下，火动其痰，用二陈加黄芩、苍术、羌活，散风行湿。左手脉数热多，脉涩有死血；右手脉实有痰积，脉大是久病（久一作虚）。久病之人，气血俱虚而脉大，痰浊不降也。昔有一老妇，患赤白带一年半，头眩，坐立不得，睡之则安。专治赤白带，带愈，其眩亦安。", "18689": "如肥人头痛，是湿痰，宜半夏、苍术；如瘦人，是热，宜酒制黄芩、防风。如感冒头痛，宜防风、羌活、藁本、白芷；如气虚头痛，宜黄耆酒洗、生地黄、南星、秘藏安神汤；如风热在上头痛，宜天麻、蔓荆子、台芎、酒制黄芩；如苦头痛，用细辛；如形瘦苍黑之人头痛，乃是血虚，宜当归、用芎、酒黄芩；如顶颠痛，宜藁本、防风、柴胡。东垣云：顶颠痛须用藁本，去川芎。且如太阳头痛，恶风，脉浮紧，川芎、羌活、独活、麻黄之类为主；少阳头痛，脉弦细，往来寒热，柴胡为主；阳明头痛，自汗，发热恶寒，脉浮缓长实，升麻、葛根、石膏、白芷为主；太阴头痛，必有痰，体重或腹痛，脉沉缓，以苍术、半夏、南星为主；少阴头痛，足寒气逆，为寒厥，其脉沉细，麻黄、附子、细辛为主；厥阴头痛，或吐痰沫，厥冷，其脉浮缓，以吴茱萸汤主之，血虚头痛，当归、川芎为主；气虚头痛，人参、黄耆为主；气血俱虚头痛，调中益气汤内加川芎三分，蔓荆子三分，细辛二分，其效如神。又有痰厥头痛，所感不一。是知方者验也，法者用也，徒知体而不知用者弊，体用不失，可谓上工矣。", "18690": "上为末，每服二钱，热盏内入茶少许，汤调如膏。抹在口内，临卧少用白汤送下。如苦头痛，每服加细辛二分；痰厥头痛，脉缓，减羌活、防风、川芎、甘草，加半夏一两五钱；如偏正头痛，服之不愈，减羌活、防风、川芎一半，加柴胡一倍；如发热、恶热而渴，此阳明头痛，只与白虎汤，加好吴白芷，", "18691": "心痛，即胃脘痛，虽日数多，不吃食，不死。若痛方止便吃物，还痛。必须三五服药后，方吃物。痛甚者，脉必伏，用温药附子之类，不可用参术。诸痛不可补气。大凡心膈之痛，须分新久。若明知身受寒气，口吃寒物而得病者，于初得之时，当与温散或温利之药。若曰病得之稍久则成郁，久郁则蒸热，热久必生火，《原病式》中备言之矣。若欲行温散温利，宁无助火添病耶？古方中多以山栀子为热药之向导，则邪易伏，病易退，正易复而病安。然病安之后，若纵恣口味，不改前非，病复作时，反咎医之失，良可叹哉！一方用山栀子炒去皮，每服十五枚，浓煎汤一呷，入生姜汁令辣，再煎小沸，又入川芎一钱，尤妙。山栀子大者，或七枚，或九枚，须炒黑。大概胃口有热而作痛者，非山栀子不可，须佐以姜汁，多用台芎开之。病发者，或用二陈汤加川芎、苍术，倍加炒栀子。痛甚者，加炒干姜从之，反治之法也。轻者，川芎一两，苍术一两，山栀子炒去皮二两，姜汁蒸饼糊丸梧桐子大，服七八十丸，热辣姜汤下。重者，桂枝、麻黄、石碱各等分，姜汁和蒸饼丸桐子大，服五十丸，热辣姜汤下。一本：轻者散之，麻黄、桂枝之类。重者加石碱、川芎、苍术、炒山栀子去皮，作丸服。凡治此证，必要先问平日起居何如。假如心痛，有因平日喜食热物，以致死血留于胃口作痛，用桃仁承气汤下之，切记。轻者用韭汁、桔梗，能开提其气，血药中兼用之。以物柱按痛处则止者挟虚，以二陈汤加炒干姜和之。有虫痛者，面上白斑，唇红能食属虫，治以苦楝根、锡灰之类，痛定便能食。时作时止者，是虫。上半月虫头向上，易治；下半月虫头向下，难治。先以肉汁及糖蜜食下，则引虫头向上，然后用药打出。楝树根皮、槟榔、鹤虱，夏取汁饮，冬浓煎汤，下万应丸，最好。脉坚实不大便者，下之。心痛，用山栀并劫药止之。若又复发，前药必不效，可用玄明粉一服，立止。左手脉数热多，脉涩有死血；右手脉紧实痰积，弦大必是久病。胃脘有湿而痛者，宜小胃丹下之。", "18692": "一人脉涩，心脾常痛。", "18693": "胁痛，肝火盛，木气实，有死血，有痰流注，肝急。木气实，用苍术、川芎、青皮、当归之类；痛甚者，肝火盛，以当归龙荟丸，姜汁下，是泻火之要药；死血，用桃仁、红花、川芎；痰流注，以二陈汤加南星、苍术、川芎；肝苦急，急食辛以散之，用抚芎、川芎、苍术。血病，入血药中行血。治咳嗽胁痛，以二陈汤加南星、香附、青皮、青黛，入姜汁。胁痛有瘀血，行气药中加桃仁不去尖，并香附之类。有火盛者，当伐肝木。左金丸治肝火，有气郁而胸胁痛者，看其脉沉涩，当作郁治。痛而不得伸舒者蜜丸，龙荟丸最快。胁下有食积一条扛起，用吴茱萸、炒黄连。控涎丹，一身气痛，及胁痛，痰挟死血，加桃仁泥，丸服。右胁痛，用推气散，出严氏方；左胁痛，用前药为君加柴胡或小柴胡，亦可治。", "18694": "腹痛有寒、积热、死血、食积、湿痰。脉弦，食；脉滑，痰（一作涩）。清痰多作腹痛，台芎、苍术、香附、白芷为末，以姜汁入汤调服，大法之方若此。腹痛者，气用气药，如木香、槟榔、香附、枳壳之类；血用血药，如当归、川芎、桃仁、红花之类。初得时，元气未虚，必推荡之，此通因通用之法。久必难。壮实与初病，宜下；虚弱衰与久病，宜升之消之。腹中水鸣，乃火击动其水也，用二陈汤加黄芩、黄连、栀子。亦有脏寒而鸣者。凡心腹痛者，必用温散，此是郁结不行，阻气不运，故痛。在上者多属食，食能作痛，宜温散之，如干姜、炒苍术、川芎、白芷、香附、姜汁之类，不可用峻利药攻下之。盖食得寒则凝，热则化，更兼行气快气药助之，无不可者。一老人腹痛，年高不禁下者，用川芎、苍术、香附、白芷、干姜、茯苓、滑石之类。", "18695": "腰痛主湿热、肾虚、瘀血、挫闪、有痰积。脉大者肾虚，杜仲、龟板、黄柏、知母、枸杞、五味之类为末，猪脊髓丸服；脉涩者瘀血，用补阴丸加桃仁、红花；脉缓者湿热，苍术、杜仲、黄柏、川芎之类；痰积作痛者，二陈加南星、半夏。腰曲不能伸者，针人中。凡诸痛皆属火，寒凉药不可峻用，必用温散之药。诸痛不可用参，补气则疼愈甚。人有痛，面上忽见红点者，多死。", "18696": "〔附录〕腰者，肾之外候，一身所恃以转移阖辟者也。盖诸经皆贯于肾而络于腰脊，肾气一虚，凡冲寒、受湿、伤冷、蓄热、血涩气滞、水积堕伤，与失志、作劳，种种腰疼，叠见而层出矣。脉若弦而沉者为虚，沉者为滞，涩者瘀血，缓者为湿，滑与伏者是痰。", "18697": "疝痛，湿热痰积流下作病，大概因寒郁而作，即是痰饮食积并死血。专主肝经，与肾经绝无相干，大不宜下。痛甚者不宜参、术。𤻊湿多。疝气宜灸大敦穴，在足大指爪甲后一韭叶聚毛间，是穴。食积与死血成痛者，栀子、桃仁、山楂、枳子（一作枳实）、吴茱萸，并炒，以生姜汁顺流水煎汤调服。一方加茴香、附子。却有水气而肿痛者，又有挟虚者，当用参、术为君，佐以疏导之药，其脉沉紧豁大者是。按之不定者属虚，必用桂枝、山栀炒、乌头细切炒，上为末，姜汁糊丸，每服三四十丸，姜汤下，大能劫痛。", "18698": "〔附录〕耳，属足少阴之经，肾家之寄窍于耳也。肾通乎耳，所主者，精。精气调和，肾气充足，则耳闻而聪。若劳伤气血，风邪袭虚，使精脱肾惫，则耳转而聋。又有气厥而聋者，有挟风而聋者，有劳损而聋者。盖十二经脉上络于耳，其阴阳诸经适有交并，则脏气逆而为厥，厥气搏入于耳，是谓厥聋，必有眩晕之证。", "18699": "耳者，宗脉之所附。脉虚而风邪乘之，风入于耳之脉，使经气痞而不宣，是谓风聋。必有头痛之证。劳役伤于血气，淫欲耗其精元，瘦悴力疲，昏昏瞆瞆，是为劳聋。有能将息得所，血气和平，则其聋暂轻。又有耳触风邪，与气相搏，其声嘈嘈，眼见光，为之虚聋。热气乘虚随脉入耳，聚热不散，浓汁出，为之脓耳。人耳间有津液，轻则不能为害，若风热搏之，津液结𩊅成核塞耳，亦令暴聋，为之耵耳。前是数者，肾脉可推。风则浮而盛，热则洪而实，虚则涩而濡。风为之疏散，热为之清利，虚为之调养，邪气屏退，然后以通耳调气安肾之剂主之。于此得耳中三昧。", "18700": "人以气为主，一息不运则机缄穷，一毫不续则穹壤判。阴阳之所以升降者，气也。血脉之所以流行者，亦气也。荣卫之所以运转者，此气也。五脏六腑之所以相养相生者，亦此气也。盛则盈，衰则虚，顺则平，逆则病。气也者，独非人身之根本乎？人有七情，病生七气，七气者，寒、热、怒、恚、喜、忧、愁，或以为喜、怒、忧、思、悲、惊、恐，皆通也。然则均调是气，将何先焉？曰：气结则生痰，痰盛则气愈结，故调气必先豁痰，如七气汤。以半夏为主而官桂佐之，盖良法也。况夫冷则生气。调气须用豁痰，亦不可无温中之剂，其间用桂，又所以温其中也。不然，七情相干，痰涎凝结，如絮如膜，甚如梅核，窒碍于咽喉之间，咯不去，咽不下，或中艰食，或上气喘急，曰气隔，曰气滞，曰气秘，曰气中，以至五积六聚，疝癖症瘕，心腹块痛，发则欲绝，殆无往而不至矣。怒则气上，喜则气缓，惊则气乱，恐则气下，劳则气耗，悲则气消，思则气结，此七者皆能致疾，寒气郁于中作痛者，以七气汤、盐煎散、东垣升阳顺气汤。逆者抑之，以木香流气饮、降气汤。有热者须加凉剂抑之，所谓从阴引阳也。", "18701": "胃风此因初饮食讫乘风凉而致。其证胀满，食饮不下，形瘦腹大，恶风，头多汗，膈寒不通，胃风汤正治。然此亦看挟证加减，脉右关弦而缓带浮。", "18702": "郭氏升麻牛蒡子散治时毒疮疹，脉浮，红在表者，疮发于头面胸膈之际。", "18703": "痈疽只是热胜血。六阳经，六阴经，有多气少血者，有少气多血者，有多气多血者，不可一概论也。若夫要害处近虚怯薄处，前哲已曾论及。惟分经之言未闻，诸经惟少阳厥阴经生痈疽，理宜预防，以其多气少血，肌肉难长，疮久未合，必成死症。遽用驱毒利药，以伐其阴分之血，祸不旋踵。阳滞于阴，脉浮洪弦数；阴滞于阳，脉沉细弱涩。阳滞以寒治之，阴滞以热治之。人中年以后，不可生痈，才有痛肿，参之脉证，但见虚弱，便与滋补气血，可保终吉。若用寻常驱热拔毒纾气之药，虚虚之祸，如指诸掌。内托之法，河间治肿焮于外，根盘不深，形证在表，其脉多浮，病在皮肉，非气盛则必侵于内，急须内托以救其里，宜复煎散，除温散郁，使胃气和平。如或未已，再煎半料饮之。如大便秘及烦热，少服黄连汤。如微利及烦热已退却，与复煎散半两。如此，使荣卫俱行，邪气不能内伤也。然世俗多用排脓内补十宣散，若用之于此小疮与冬月时令即可。若溃疡于夏月用之，其桂朴之温散，佐以防风、白芷，吾恐虽有参、耆，难为倚仗。一妇年七十，形实性急而好酒，脑生疽，才五日，脉紧急且涩，急用大黄酒煨细切，酒拌炒为末。又洒拌人参炒，入姜煎，调一钱重。又两时再与。得睡而上半身汗，睡觉病已失。此内托之意。又一男子，年五十，形实色黑，背生红肿，及胛骨下痛，其脉浮数而洪紧，食亦呕。正冬月，与麻黄桂枝汤加酒黄柏、生附、栝蒌子、甘草节、羌活、青皮、人参、黄芩、半夏、生姜，六帖而消。此正内托之法，非《精要》内托散、乳香、绿豆等药。想此方专为服丹石而发疽者设，不因丹石而发，恐非必用之剂。疮先发为肿，气血郁积，蒸肉为脓，故其痛多少疮之始作时也。脓溃之后，肿退肌宽，痛必渐减。而反痛者，此为虚，宜补。亦有秽气所触，宜和解；风寒逼者，宜温散。", "18704": "内疏黄连汤治疮皮色肿硬，发热而呕，大便闭，脉洪实者。", "18705": "治一切疔疮，用紫梗菊花根茎叶皆可，研碎取汁，滴口中饮之。瘰疬，血气痰热，以牡蛎煅过为末，玄参捣膏为丸，桑椹黑熟者捣汁熬膏，汤调服。红者晒干为末，汤调服。师云：大田螺连肉烧灰存性为末，入麝香少许，湿则干敷，干则油调敷。夏枯草，大能散结气，而有补养血脉之功，能退寒热，虚者尽可倚仗。若实者，以行散之药佐之，外施艾灸，亦渐取效。", "18706": "妇人经水过期，血少也，四物加参、术；带痰，加南星、半夏、陈皮之类。经水不及期而来者，血热也，四物加黄连。过期，紫黑有块，亦血热也，必作痛，四物加香附、黄连；过期，淡色来者，痰多也，二陈加川芎、当归。过期而来，乃是血虚，宜补血，用四物加黄耆、陈皮、升麻；未及期先来，乃是气血俱热，宜凉气血，柴胡、黄芩、当归、白芍、生地黄、香附之属。经不调而血水淡血，宜补气血，参、耆、芎、归、香附、白芍。腹痛，加胶珠、艾叶、玄胡索。经候过而作痛者，乃虚中有热，所以作痛；经水将来作痛者，血实也（一云气滞），四物加桃仁、黄连、香附；临行时腰疼腹痛，乃是郁滞，有瘀血，宜四物加红花、桃仁、莪术、玄胡索、香附、木香。发热，加黄芩、柴胡。紫色成块者，热也，四物加黄连、柴胡之类。痰多占住血海地位，因而下多者，目必渐昏。肥人如此，用南星、苍术、川芎、香附，作丸子服之，肥人不及日数而多者，痰多血虚有热，亦用前丸，药中更加黄连、白术丸服。血枯经闭者，四物加桃仁、红花。躯脂满经闭者，以导痰汤加黄连、川芎，不可服地黄，泥膈故也，如用，以姜汁炒。肥胖饮食过度之人，而经水不调者，乃是湿痰，宜苍术、半夏、滑石、茯苓、白术、香附、川芎、当归。临经来时肚痛者，四物汤加陈皮、玄胡索、牡丹、甘草。痛甚者，豆淋酒；痛缓者，童便煮莎，入炒条芩末为丸。经水去多不能住者，以三补丸加莎根、龟板、金毛狗脊。阴虚，经脉久不通，小便涩，身体疼痛，以四物加苍术、牛膝、陈皮、生甘草。又用苍莎丸加苍耳、酒芍药为丸，就煎前药吞下。", "18707": "若经候微少，渐渐不通，手足烦疼，渐瘦，生潮热，脉微数，本方去地黄、芎，加泽兰叶三倍，甘草半分；经候过多，本方去熟地黄，加生地黄，或只加黄芩、白术；经行身热，脉数，头昏，本方加柴胡、芩；经行微少，或胀或疼，四肢疼痛，加延胡、没药、白芷与本方等，淡醋汤调下末子。经候不调，心腹㽲痛，只用芎、归二味，名君臣散。气冲经脉，故月事频并，脐下多痛，加芍药；经欲行，脐腹绞痛，加玄胡、槟榔、苦楝，炒木香减半；经水涩少，加葵花、红花；经水适来适断，或有往来寒热，先宜服小柴胡汤，后以四物和之；经候过而作痛，血气俱虚也，宜本方对四君子汤服之。", "18708": "当归散治经脉不通。", "18709": "血崩，东垣有治法，但不言热，其主在寒。学者宜寻思之。急则治其标，用白芷汤调百草霜末，甚者用棕榈灰。后用四物汤加炒干姜调理。因劳者，用参耆带升补药；因寒者，用干姜；因热者，黄芩；崩过多者，先用五灵脂末一服，当分寒热。盖五灵脂能行能止，紫色成块者热，以四物汤加黄连之类。妇人血崩，用香附白芷丸服。气虚血虚者，皆以四物汤加参、耆。漏下乃热而虚，四物加黄连。崩中白带，用椒目末，又用白芷、石灰炒去灰为末，茜草少许，粥丸服。一方，用生狗头骨烧灰存性，或酒调服，或入药服。一方，五灵脂半生半炒为末酒调服。经血逆行，或血腥，或吐血，或唾血，用韭菜汁服效。夫妇人崩中者，由脏腑伤损，冲任二脉，血气俱虚故也。二脉为经脉之海，血气之行，外循经络，内荣脏腑。若气血调适，经下依时。若劳动过极，脏腑俱伤，冲任之气虚，不能约制其经血，故忽然而下，谓之崩中暴下。治宜当大补气血之药，举养脾胃，微加镇坠心火之药，治其心，补阴泻阳，经自止矣。", "18710": "又方治白带，因七情所伤而脉数者。", "18711": "〔附录〕赤白带者，皆因七情内伤，或下元虚惫，感非一端。叔和云：「崩中日久为白带，漏下多时骨本枯」。崩中者，始病血崩，久则血少亡其阳，故白滑之物，下流不止，是本经血海将枯，津液复亡，枯干不能滋养筋骨。执剂之法，须以本部行经药为引用，为使。大辛甘油腻之药，润其枯燥，而滋益津液，以大卒热之气味药，补其阳道，生其血脉。以寒苦之药，泄其肺而救上热伤气。以人参补之。以微苦温之药为佐，而益元气。此治之大法也。", "18712": "产前当清热产血。产妇因火动胎，逆上作喘急者，急用条芩、香附之类为末调下。条芩，水中取沉者为佳。堕胎，乃气虚、血虚、血热。黄芩，安胎，乃上中二焦药，能降火下行。益母草，即茺蔚子，治产前产后诸病，能行血养血。难产可煎作膏，地黄膏、牛膝膏，皆可用。怀妊爱物，乃一脏之虚。假如肝脏之虚，肝气止能生胎，无余用也。又云：不能荣其肝，肝虚故爱酸物。产前安胎，白术、黄芩为妙药也。条芩，安胎圣药也。俗人不知，以为害而不敢用，反谓温热之药可养胎。殊不知产前宜清热，令血循经而不妄行，故能养胎。胎热将临月，以三补丸加炒香附、炒白芍，蒸饼丸服。抑热，以三补丸，用地黄膏丸。有孕八九个月，必顺气，须用枳壳、紫苏梗。凡妊妇脉细匀，易产；大浮缓，火气散，难产。生产如抱舡过坝一般。", "18713": "产后无得令虚，当大补气血为先。虽有杂证，以末治之。一切病多是血虚，皆不可发表。产后不可用芍药，以其酸寒伐生发之气故也。产后血晕，因虚火载血上行，渐渐晕来，方用鹿角烧灰，出火毒，研极细末，好酒同童便灌下，一呷即醒，行血极快。又方，以韭叶细切，盛于有觜瓶中，以热醋沃之，急封其口，以觜塞产妇鼻中，可愈眩冒。产后中风，切不可作风治，必大补气血为主，然后治痰，当以左右手之脉，分其气血多少而治。产后中风，口眼㖞斜，切不可服小续命汤。产后水肿，必用大补气血为主，小佐苍术、茯苓，使水自利。产后大发热，必用干姜，轻者用茯苓，淡渗其热，一应寒苦并发表之药，皆不可用，产后发热恶寒，皆属血虚。左手脉不足，补血药多于补气药。恶寒发热腹痛者，当去恶血，腹满者不是。产后发热，乳汁不通及膨者，无子当消，用麦蘖二两炒，研细末，清汤调下，作四服。有子者，用木通、通草、猪蹄煎服。凡产后有病，先固正气。前条云：产后大热，必用干姜。或曰：用姜者何也？曰：此热非有余之热，乃阴虚生内热耳。故以补阴药大剂服之。且干姜能入肺和肺气，入肝分引血药生血，然不可独用，必与补阴药同用。此造化自然之妙，非天下之至神，孰能与于此乎？产后脉洪数，产前脉细小涩弱，多死。怀孕者脉主洪数，已产而洪数不改者，多主死。", "18714": "痘疮，分气虚、血虚，用补。气虚者，人参、白术加解毒药；血虚者，四物汤中加解毒药。凡痘疮初出之时，色白者，便用大补气血，参、术、耆、芎、升麻、干葛、草、木香、丁香、酒洗当归、白芍。若大便泻，加诃子、肉豆蔻、酒炒芩连，名解毒药。但见红点，便忌葛根汤，恐发得表虚也。吐泻食少，为里虚；不吐泻，能食，为里实；里实而补，则结痈毒。陷伏倒靥为表虚，灰白者亦表虚，或用烧人屎。红活绽凸为表实，表实而更复用表药，则反溃烂不结痂。吐泻陷伏，二者俱见，为表里俱虚。黑陷甚者，亦用烧人屎，蜜水调服，出子和方。痘疮初出时，或未见时，人有患者，宜预服此药，多者令少，重者令轻。方以丝瓜近蒂三寸，连皮子烧灰存性为末，砂糖拌，干吃。入朱砂末，尤妙。痘疮分人清浊，就形气上取勇怯。黑陷二种，因气虚而毒气不能尽出者，酒炒黄耆、酒紫草、人参。颜色正者如上治。将欲成就，却色淡者，宜助血药，用当归、川芎、酒洗芍药之类，或加红花。将成就之际，却紫色者，属热，用凉药解其毒，升麻、葛根、黄连、黄芩、桂枝、连翘之类，甚者犀角，大解痘毒，炉灰白色、静者、怯者，作寒看。勇者、燥者、焮发者，作热看。痘疮，鼠黏子、连翘、山楂、甘草，此四味，始终必用之药。全白色，将靥时如豆壳者，盖因初起时饮水多，其靥不齐，俗呼倒靥，不好。但服实表之剂，消息以大小便，如大便秘，通大便；小便秘，通小便。有初起烦躁谵语，狂渴引饮，若饮水则后来靥不齐，急以凉药解其标，如益元散之类亦可服。痒塌者，于形色脉上分虚实，实则脉有力气壮，虚则脉无力气怯。轻者用淡蜜水调滑石末，以羽润疮上。虚痒者，以实表之剂加凉血药。实痒如大便不通者，以大黄寒凉之药少许与之，下其结粪。疏则无毒，蜜则有毒，宜凉药解之，虽数十帖亦不妨。无害眼之患。疮干者宜退火，湿者用泻湿。退火止用轻剂，荆芥、升麻、葛根之类；泻湿乃肌表间湿，宜用风药白芷、防风之类。如痘疮伤眼，必用山栀、决明、赤芍、归尾、芩连、防风、连翘、升麻、桔梗，作小剂，末调服。如眼无光，过百日后，血气复自明。痘痈多是实毒，血热成痈，分上下用药，一日不可缓。已成脓，必用凉药为主，赤芍、甘草节、连翘、桔梗，上引用升麻、葛根，下引用槟榔、牛膝，助以贝母、忍冬草、白芷、栝蒌之类。大便燥，用大黄。发寒热，用黄芩、黄柏。痘疮，黑属血热，凉血为主；白属虚，补气为主。中黑陷而外白起得迟者，则相兼而治。初起时自汗不妨，盖湿热熏蒸而然故也。痘风分气血虚实，以日子守之，多带气血不足，虚则黄耆，生血活血之剂助之，略佐以风药；实则白芍为君，黄芩亦为君，佐以白芷、连翘、续断之类。若属寒，陈氏方可用。", "18715": "〔附录〕小儿疮疹，大抵与伤寒相似，发热烦躁，脸赤唇红，身痛头疼，乍寒乍热，喷嚏呵欠，嗽喘痰涎，伤寒证候类有之。始发之时，有因伤风寒而得者，有时气传染而得者，有因伤食呕吐而得者，有因跌扑惊恐蓄血而得者，或为窜眼禁牙惊搐如风之证，或口舌咽喉肚腹疼痛，或烦躁狂闷昏睡，或自汗，或下痢，或发热，或不发热，证候多端。卒未易辨，亦须以耳冷骫冷足冷验之。盖谓疮疹属阳，肾脏无证，耳与骫足，俱属于肾，故肾之所部独冷。疑似之间，或中或否，不若视其耳后有红脉赤缕为真，于此可以稽验矣。调护之法，首尾俱不可汗下，但温凉之剂，兼而济之，解毒和中安表而已。如欲解肌，干葛、紫苏可也。其或小儿气实，烦躁热炽，大便秘结，则与犀角地黄汤，或人参败毒散辈。又或紫草饮，多服亦能利之。故前说大便不通者，少与大黄，尤宜仔细斟酌之，慎之可也。若小便赤少者，分利小便，则热气有所渗而出。凡热不可骤遏，但轻解之。若无热，则疮又不能发也。凡已发未发，并与紫苏饮为当，虚者益之，实者损之，冷者温之，热者平之，是为权度。借喻而言，亦如庖人笼蒸之法，但欲其松耳。如苟妄汗，则荣卫既开，转增疮烂；妄下则正气内脱，变而归肾。身体振寒，耳骫反热，眼合肚胀，其疮黑坏，十无一生。钱氏云：黑陷青紫者，百祥丸下之，不黑者谨勿下。余知其所下者，泻膀胱之邪也。又云：下后身热气温欲饮水者，可治，水谷不消，或寒战者为逆。余知其脾强者，土可以治水也。百祥丸太峻，当以宣风散代之。泻后温脾，则用人参、茯苓、白术等分，厚朴、木香、甘草各半为妙。盖疮发肌肉，阳明主之，脾土一温，胃气随畅，独不可消弭已泄之肾水乎。此钱氏不刊之秘旨也。朱氏曰：疮疹已发未发，但不可疏转，此为大戒。又曰：疮疹首尾，皆不可下，辄用利药，则毒气入里杀人。以此观之，疮疹证状，虽与伤寒相似，而疮疹治法，实与伤寒不同。伤寒所传从表入里，疮疹所发从里出表。盖毒根于里，若下之，则内气一虚，毒不能出而返入焉。由是土不胜水，黑陷者有之。毒发于表，若汗之，则荣卫一虚，重令开泄，转增疮烂，由是风邪乘间变证者有之。汗下二说，古人所深戒也。调解之法，活血调气，安表和中，轻清消毒，温凉之剂，二者得兼而已。温如当归、黄耆、木香辈，凉如前胡、干葛、升麻辈，佐之以川芎、芍药、枳壳、桔梗、羌活、木通、紫草、甘草之属，则可以调适矣。但小儿凡觉身热，证似伤寒，未经疮痘，疑似未明，且先与惺惺散、参苏饮，或人参羌活散辈，热甚则与升麻葛根汤、人参败毒散。疮痘已出，则少与化毒汤。出不快者，加味四圣散、紫草饮子、紫草木香汤、紫草木通汤，或快斑散、丝瓜汤；出太甚者，人参败毒散、犀角地黄汤。小便赤涩者，大连翘汤、甘露饮、麦门冬五苓散；大便秘结，内烦外热者，小柴胡汤加枳壳最当，或少少四顺清凉饮；若咽喉痛者，大如圣汤、鼠黏子汤；喘满气壅者，麻黄黄芩汤；胸腹胀满者，枳壳桔梗汤、二陈加枳壳汤；烦渴者，甘草散、乌梅汤；下利呕逆者，木香理中汤、甘草干姜汤。陷入者，加味四圣散，更以胡荽酒薄敷其身，厚敷其足，喷其衣服，并以厚绵盖之。若犹未也，独圣散入麝香老酒调剂。或不用酒，则木香煎汤。若其疮已黑，乃可用钱氏宣风散加青皮主之。然而疮疹用药，固有权度，大小二便不可不通。其有大便自利，所下黄黑，则毒气已减，不必多与汤剂，但少用化毒汤可也，或不用亦可。若大小二便一或闭焉，则肠胃壅塞，脉络凝滞，毒气无从而发泄，眼闭声哑，肌肉黧黑，不旋踵而告变矣。其坏疮者，一曰内虚泄泻，一曰外伤风冷，三曰变黑归肾。春夏为顺，秋冬为逆。凡痘疮初出之时，须看胸前，若稠密急宜消毒饮加山楂、黄芩酒洗、紫草，减食加人参。凡痘疮初欲出时，发热鼻尖冷，呵欠，咳嗽面赤，方是痘出之候，便宜服升麻葛根汤加山楂、大力子，其疮稀疏而易愈。凡痘疮发热之时，便宜恶实子为末，蜜调，贴囟门上，免有患眼之疾。近世小儿痘疮，上党陈文中木香散、异攻散。殊不知彼时立方之时，为运气在寒司天，时令又值严冬大寒，为因寒气郁遏，痘疮不红绽，故用辛热之剂发之。今人不分时令寒热，一概施治，误人多矣。时值温热，山野农家贫贱之人，其或偶中也。", "18716": "凡看脉，如得恶脉，当覆手取。如与正取同，乃元气绝，必难治矣；如与正取不同者，乃阴阳错综，未必死。弦坚之脉，虽是有积，亦带阴虚，脉无水不软之意。脉紧指者，其气大虚，多死，峻补气，无水，参、术、归之类；形脱者，必补气，参、术；面白补气；肥人补气。", "18717": "点三里穴，随意依古法点，但趺阳脉不应即是穴，盖三里属阳明经也。", "18718": "丹溪先生既卒，宗属失其所倚藉，井邑失其所依凭，嗜学之士失其所承事，莫不彷徨遥慕，至于洒涕！濂闻之，中心尤摧咽不自胜。盖自加布于首，辄相亲于几杖间，订义质疑，而求古人精神心术之所寓。先生不以濂为不肖，以忘年交遇之，必极言而无所隐，故知先生之深者，无逾于濂也。方欲聚厥事行，为书以传来世，而先生之子玉汝、从子嗣泛、忽蹐濂门，以先生从弟无忌所为状，请为表以勒诸墓上。濂何敢辞！先生讳震亨，字彦修，姓朱氏，其先出于汉槐里令云之后。居平陵，至晋永兴中，临海太守泛，始迁今婺之义乌。子孙蝉联，多发闻于世，郡志家乘载之为详。当宋之季，有东堂府君者，讳良祐，懿然君子人也，盖以六经为教，以弘其宗。府君生某，某生迪功郎桂，迪功生乡贡进士环，先生之大父也。父讳元，母某氏。先生受资爽朗，读书即了大义，为声律之赋，刻烛而成，长老咸器之，已而弃去。尚侠气，不肯出人下，乡之右族咸陵之，必风怒电激求直于有司，上下摇手相戒，莫或轻犯。时乡先生文懿许公，讲道东阳八华山中，公上承考亭朱子四传之学，授受分明，契证真切，担簦而从之者亡虑数百人。先生叹曰：「丈夫所学，不务闻道，而唯侠是尚，不亦惑乎？」乃抠衣往事焉。先生之年，盖已三十六矣。公为开明天命人心之秘，内圣外王之微，先生闻之，自悔昔之沉冥颠济，汗下如雨。由是日有所悟，心扃融廓，体肤如觉增长，每宵挟朋坐至四鼓，潜验默察，必欲见诸实践，抑其疏豪，归于粹夷。理欲之关，诚伪之限，严辨确守，不以一毫苟且自恕。如是者数年，而其学坚定矣。岁当宾兴，先生应书秋闱，幸沾一命，以验其所施。再往，再不利，复叹曰：「不仕固无义，然得失则有命焉。苟推一家之政，以达于乡党州闾，宁非仕乎？」先是府君置祭田三十余亩，合为一区，嗣人递司穑事，以陈时荐，然有恒祭而无恒所。先生乃即适意亭遗址，建祠堂若干楹，以奉先世神主，岁时行事。复考朱子家礼而损益其仪文，少长咸在，执事有恪，深衣大带，以序就列，宴私洽比，不愆于礼。适意亭者，府君所造，以延徐文清公之地。先生弗忍其废，改创祠堂之南，俾诸子姓肄习其中。包银之不下，州县承之，急如星火，一里之间，不下数十姓，民莫敢与辨。先生所居里，仅上富氓二人。郡守召先生，自临之曰：「此非常法，君不爱头乎？」先生笑曰：「守为官，头固当惜，民不爱也。此害将毒子孙，必欲多及，民愿倍输吾产当之。」守虽怒，竟不能屈。县有暴丞，好谄渎鬼神，欲修岱宗祠以徼福，惧先生莫己与，以言尝之曰：「人之生死，岳神实司之，欲治其宫，孰敢干令？」先生曰：「吾受命于天，何庸媚土偶为生死计耶？且岳神无知则已，使其有知，当此俭岁，民食糠核不饱，能振吾民者，然后降之福耳。」卒罢其事，赋役无艺。胥史高下其手，以为民奸。先生集同里之人谓曰：「有田则科徭随之，君等人胥史饵而护相倾，非策之上也，宜相率以义，契其力之朒，嬴而敷之。」众翕然从，每官书下，相依如父子，议事必先集。若苛敛之至，先生即以身前，辞气恳款，上官多听，为之损裁。县大夫劝耕于乡，将有要于民。先生愳其临境，邪幅扉屦，往迎于道左。大夫惊曰：「先生何事乃尔耶？」先生曰：「民有役于官，礼固应尔。」大夫曰：「劝耕善乎？」先生曰：「私田不烦官劝，第公田生青刍耳。」是时圭田赋重，种户多逃亡，故先生以此为风。大夫一笑而去。乡有蜀墅塘，周围凡三千六百步，溉田至六千亩而嬴；堤坏而水竭，数以旱告。先生倡民兴筑，置坊庸，凿为三窦，时其深浅而舒泄之。民食其利。后十年，山水暴至，堤又坏，先生命再从子漳力任其事，以嗣其成。县令长或问决狱得失，先生必尽心为之开导。东阳郭氏父子三人，虐殴小民几毙，又贯针䲡腹，逼使吞之。事移义乌鞠问，当其子父皆死。先生曰：「原其故杀之情，亦一人可偿尔。一子从父之令，宜从未减，若皆杀之，无乃已重乎？」事上从先生议。张甲行小径中，适李乙荷任器来，几中甲目，甲怒拳其耳而死。甲乙皆贫人，甲又有九十之亲。先生曰：「贳甲罪则废法，徇法甲必瘦死，亲无以养亦死。乙尸暴于道，孰为藏之？不若使竟其葬薶，且慰其亲，徐来归狱，服中刑耳。」或曰：「甲或逃奈何？」先生曰：「若以诚待之，必不尔也。」县如先生言。后会赦免。细民有斩先生丘木者，先生讯之，民弗服。先生闻于县，将逮之。人交让民曰：「汝奈何犯仁人耶？」民曰：「计将安出？」人曰：「先生，长者也。急舁木还之，当尔贷。」民从之，先生果真而不问。先生客吴妙湛院，尼刻木作人形，以为厌蛊。馆客陈庚得之，欲发其事，尼惧甚。先生知之，以计绐陈出，碎其木刻。陈归怒且詈。先生徐曰：「君乃士人，获此声于吴楚间，甚非君利。倘乏金，吾财可通用，勿忧也。」尼后辇金帛为谢，先生叱而去。方岳重臣及廉访使者，闻先生名，无不愿见；既见，无不欲交章荐之。先生皆力辞。唯民瘼吏弊，必再三蹙额告之，不啻亲受其病者。覃怀郑公持节浙东，尤敬先生，以尊客礼礼之。众或不乐，竞短其行于公。公笑曰：「朱聘君盛举诸公之长，而诸公顾反短之，何其量之悬隔耶？」皆惭不能退。初，先生壮龄时，以母夫人病脾，颇习医。后益研矿之，且曰：「吾既穷而在下，泽不能致远，其可远者，非医将安务乎？」时方盛行陈师文、裴宗元所定大观一百九十七方，先生独疑之，曰：「用药如持衡，随物重轻而为前却，古方新证，安能相值乎？」于是寻师而订其说，渡涛江走吴，又走宛陵，走建业，皆不能得。复回武林，有以罗司徒知悌为言者。知悌，字子敬，宋宝祐中寺人，精于医，得金士刘元素之学，而旁参于李杲、张从正二家，然性倨甚。先生谒焉，十往返不能通。先生志益坚，日拱立于其门，大风雨不易。或告罗曰：「此朱彦修也，君居江南而失此士，人将议君后矣。」罗遽修容见之，一见如故交。为言学医之要，必本于《素问》《难经》，而湿热相火，为病最多，人罕有知其秘者。兼之长沙之书详于外感，东垣之书详于内伤，必两尽之，治疾方无所憾。区区陈裴之学，泥之且杀人。先生闻之，夙疑为之释然，学成而归。乡之诸医始皆大惊，中而笑且排，卒乃大服相推尊，愿为弟子。四方以疾迎候者无虚日，先生无不即往，虽雨雪载途，亦不为止。仆伕告痛，先生谕之曰：「疾者度刻如岁，而欲自逸耶。」窭人求药，无不与，不求其偿，其困厄无告者，不待其招，注药往起之，虽百里之远弗惮也。江浙省臣往讨闽寇，深入瘴地，遂以病还钱塘，将北归。先生脉之曰：「二十日死。使道经三衢时召吾，可使还燕，然亦不能生之也。」如期卒于姑苏驿。权贵人以微疾来召，危坐中庭，列三品仪卫于左右。先生脉已，不言而出。或追问之，先生曰：「三月后当为鬼」，犹有骄气耶。及死，其家神先生之医，载粟为寿，先生辞之。一少年病热，两颧火赤，不能自禁，躁走于庭，将蹈河。先生曰：「此阴证也，制附子汤饮之」，众为之吐舌。饮已，其疾如失。先生治疗，其神中若此甚多，门人类证有书，兹不详载。先生孤高如鹤，挺然不群，双目有小大轮，日出明，虽毅然之色不可凌犯。而清明坦夷，不事表儤，精神充满，接物和粹，人皆乐亲炙之。语言有精魄，金锵铁铿，使人侧耳耸听，有蹶然兴起之意。而于天人感应殃庆类至之说，尤竭力戒厉，反复不厌，故其教人也。人既易知昏明强弱，皆获其心。老者则爱慈祥，幼者则乐恭顺，莫不皆知忠信之为美。固未能一变至道，去泰去甚，有足观者。或有小过，深掩密覆，唯恐先生之知。凡先生杖屦所临，人随而化。浦阳郑太和，十世同居，先生为之喜动颜面，其家所讲冠婚丧祭之礼，每咨于先生而后定。盖先生之学，稽诸载籍，一以躬行为本，以一心同天地之大，以耳目为礼乐之原，积养之久，内外一致。夜寐即平昼之为，暗室即康衢之见，汲汲孜孜，耄而弥笃。每见夸多斗靡之士，辄语之曰：「圣贤一言，终身行之弗尽矣。」以为多。至于拈英摘艳之辞，尤不乐顾，且以吾道蟊贼目之。及自为文，率以理为宗，非有关于纲常治化，不轻论也。居室垣墉，敦尚俭朴，服御唯大布宽衣，仅取蔽体；藜羹糗饭，安之如八珍。或在豪大姓家，当以肆筵设席，水陆之羞，交错于前。先生正襟默坐，未尝下箸。其清修苦节，能为人之所不能为，而于世上所悦者；澹然无所嗜，惟欲闻人之善，如恐失之，随闻随录，用为世劝。遇有不顺轨则者，必诲其改，事有难处者，又导之以其方。晚年识见尤卓，尝自括苍还，道过永康，谓人曰：「青田之民嚣悍，值此法弛令乖之时，必依险阻啸聚为乱。」已而果然。又尝告亲友曰：「吾足迹所及广矣，风俗浇漓甚，垂髫之童，亦能操狡谋罔上，天怒已极，必假手歼之，盍力善以延其胤乎。」时方承平，闻者咸笑先生之迂。言未几，天下大乱，空村无烟火动百余里。先生所著书，有《宋论》一卷、《格致余论》若干卷、《局方发挥》若干卷、《伤寒论辨》若干卷、《外科精要发挥》若干卷、《本草衍义补遗》若干卷、《风水问答》若干卷，凡七种，微文奥义，多发前人之所未明。先生尝曰：「义理精微，礼乐制度，吾门师友论著已悉，吾可以无言矣。」故其所述，独志于医为多。先生生于至元辛巳十一月二十八日，卒于至正戊戌六月二十四日，濒卒无他言，独呼嗣泛谓曰：「医学亦难矣，汝谨识之。」言讫，端坐而逝，享年七十有八。娶戚氏，道一书院山长象祖之女，先三十五年卒。子男二，嗣衍、玉汝，嗣衍亦先三年卒。女四，适傅似翁、蒋长源、吕文忠、张思忠。孙男一，文椐；女二，一适丁榆，一尚幼。其年十一月日，始葬先生于某山之原。卒后之五月也，先生所居曰丹溪，学者尊之而不敢字，故因其地称之曰丹溪先生云。夫自学术不明于天下，凡圣贤防范人心维持世道之书，往往割裂摭拾，组织成章，流为哗世取宠之具。间有注意遗经，似若可尚，又胶于训诂之间，异同纷拿，有如聚讼。其视身心，皆藐然若不相关，此其知识反出于不学庸人之下。於戏，秦汉以来，则或然矣。然而灵豸不鸣，孽狐之妖弗息；黄钟不奏，瓦缶之音日甚。天开文运，濂洛奋兴，远明凡圣之绪，流者遏而止之，胶者释而通之，一期闿廓其昏翳、挽回其精明而后已。至其相传，唯考亭集厥大成；而考亭之传，又唯金华之四贤，续其世胤之正，如印印泥，不差毫末。此所以辉连景接而芳猷允著也。先生少负任侠之气，不少屈挠，及闻道德性命之说，遽变之而为刚毅，所以局量弘而载任重，寤寐先哲，唯日不足，民吾同胞之念，须臾莫忘。虽其力或弗支，苟遇惠利少足以濡物，必委蛇周旋，求尽其心。应接之际，又因人心感发之机，而施仁义之训，触类而长，开物成化。所谓风雨霜露无非君子之教者，要亦不可诬也。致思于医，亦能搜隐抉秘，倡期南方之绝学。婴疢之家，倚以为命。先生一布衣耳，其泽物有如此者，使其得位于朝以行其道，则夫明效大验又将何如哉！呜呼！先生已矣！其山峙渊澄之色，井洁石贞之操，与其不可传者，弗能即矣。徒因其遗行而诵言之，见闻不博，恶能得十一于千百之间哉。虽然，舍是又无足以求先生者，敢摭状之概叙而为之铭曰。", "18719": "丹溪翁者，婺之义乌人也，姓朱氏，讳震亨，字彦修，学者尊之曰丹溪翁。翁自幼好学，日记千言。稍长，从乡先生治经，为举子业。后闻许文懿公得朱子四传之学，讲道八华山，复往拜焉。益闻道德性命之说，宏深粹密，遂为专门。一日，文懿谓曰：「吾卧病久，非精于医者不能以起之。子聪明异常人，其肯游艺于医乎？」翁以母病脾，于医亦粗习，及闻文懿之言，即慨然曰：「士苟精一艺，以推及物之仁，虽不仕于时，犹仕也。」乃悉焚弃向所习举子业，一于医致力焉。时方盛行陈师文、裴宗元所定大观二百九十七方。翁穷昼夜是习，既而悟曰：「掺古方以治今病，其势不能以尽合。苟将起度量，立规矩，称权衡，必也《素》《难》诸经乎。然吾乡诸医鲜克知之者。」遂治装出游，求他师而叩之。乃渡浙河，走吴中，出宛陵，抵南徐，达建业，皆无所遇。及还武林，忽有以其群罗氏告者。罗名知悌，字子敬，世称太无先生，宋理宗朝寺人，学精于医，得金刘完素之再传，而旁通张从正、李杲二家之说。然性褊甚，恃能厌事，难得意。翁往谒焉，凡数往返，不与接。已而求见愈笃，罗乃进之曰：「子非朱彦修乎？」时翁已有医名，罗故知之。翁既得见，遂北面再拜以谒，受其所教。罗遇翁亦甚欢，即授以刘、张、李诸书，为之敷扬三家之旨，而一断于经，且曰：「尽去而旧学，非是也。」翁闻其言，涣焉无少疑滞于胸臆。居无何，尽得其学以归。乡之诸医，泥陈裴之学者，闻翁言，即大惊而笑且排。独文懿喜曰：「吾疾其遂瘳矣乎！」文懿得末疾，医不能疗者余十年。翁以其法治之，良验。于是诸医之笑且排者，始皆心服口誉，数年之间，声闻顿著。翁不自满足，益以三家之说推广之，谓刘、张之学，其论脏腑气化有六，而于湿热相火三气致病为最多。遂以推陈致新，泻火之法疗之，此固高出前代矣。然有阴虚火动，或阴阳两虚，湿热自盛者，又当消息而用之。谓李之论饮食劳倦，内伤脾胃，则胃脘之阳不能以升举，并及心肺之气，陷入中焦，而用补中益气之剂治之，此亦前人之所无也。然天不足于西北，地不满于东南。天，阳也；地，阴也。西北之人，阳气易于降；东南之人，阴火易于升。苟不知此，而徒守其法，则气之降者固可愈，而于其升者亦从而用之，吾恐反增其病矣。乃以三家之论，去其短而用其长，又复参之以太极之理，《易》《礼记》《通书》《正蒙》诸书之义，贯穿《内经》之言，以寻其指归。而谓《内经》之言火，盖与太极动而生阳，五性感动之说有合；其言阴道虚，则又与《礼记》之养阴意同。因作相火及阳有余阴不足二论以发挥之。其论相火有曰：阳动而变，阴静而合，而生水火木金土。然火有二焉，曰君火，曰相火。君火者，人火也；相火者，天火也。火内阴而外阳，主乎动者也。故凡动皆属火。以名而言，形质相生，配于五行，故谓之君；以位而言，生于虚无，守位禀命，故谓之相。天生物，恒于动；人有此生，亦恒于动。然其所以恒于动者，皆相火助之也。见于天者，出于龙雷则木之气，出于海则水之气也；具于人者，寄于肝肾二部，肝属木而肾属水也。胆者肝之府，膀胱者肾之府，心胞络者肾之配，三焦以焦言，而下焦司肝肾之分，皆阴而下也。天非此火不能生，人非此火不能以有生。天之火虽出于木，而皆本乎地，故雷非伏，龙非蛰，海非附于地，则不能鸣，不能飞，不能波也。鸣也，飞也，波也，动而为相火者也，肝肾之阴，悉具相火，人而同乎天也。或曰：相火天人所同，东垣何以指为元气之贼？又谓火与元气不两立，一胜则一负，然则如之何而可使之无胜负乎？曰：周子曰：神发知矣。五性感动而万事出，五者之性，为物所感，不能不动。谓之动者，即《内经》五火也。相火易动，五性厥阳之火，又从而扇之，则妄动矣。火既妄动，则煎熬真阴，阴虚则病，阴绝则死。君火之气，经以暑与热言之，而相火之气，则以火言，盖表其暴悍酷烈有甚于君火也。故曰：「相火元气之贼。」周子曰：圣人定之以中正仁义而主静。朱子亦曰：必使道心常为之主，而人心每听命焉，此善处乎火者也。人心听命于道心，而又能主之以静，彼五火将寂然不动。而相火者，惟有扶助造化，而为生生不息之运用尔，夫何元气之贼哉！或曰：《内经》相火注，言少阴少阳矣，未尝言及厥阴太阳，而吾子言之，何也？曰：足太阳少阴，东垣尝言之，治以炒柏，取其味辛，能泻水中之火。戴人亦言胆与三焦，肝与胞络，皆从火治，此历指龙雷之火也。余以天人之火，皆生于地，如上文所云者，实广二公之意耳。或曰：《内经》言火者非一，往往于六气中见之，而言脏腑者未之有也，二公岂他有所据耶？曰：经以百病皆生于风寒暑湿燥火之动而为变者，岐伯历指病机一十九条，而属火者五，此非相火为病之出于脏腑者乎？考之《内经》，诸热瞀瘛，则属之火；诸狂燥越，则属之火；诸病附肿，痛酸惊骇，则属之火。又《原病式》曰：诸风掉眩，属于肝火之动也；诸风𪱥郁病痿，属于肺火之升也；诸湿肿满，属于脾火之胜也；诸痛痒疮疡，属于心火之用也。是皆火之为病出于脏腑者然也。噫！以陈无择之通达，犹以暖识论君火，日用之火论相火，是宜后人之聋瞽哉！其论阳有余阴不足，有曰：「人受天地之气以生，天之阳气为气，地之阴气为血」，然气常有余而血常不足，何为其然也？天，大也，为阳而运于地之外。地居天之中，为阴，而天之大气举之。日，实也，属阳而运于月之外；月，缺也，属阴而禀日之光以为明者也。则是地之阴已不胜夫天之阳，月之阴亦不敌于日之阳。天地日月尚然，而况于人乎！故人之生，男子十六岁而精通，女子十四岁而经行，是有形之后，犹有待于乳哺水谷之养，而后阴可与阳配成乎人，而为人之父母。古人必近三十二十而后嫁娶者，可见阴气之难于成，而古人之善于保养也。钱仲阳于肾有补而无泻，其知此意者乎。又按《礼记》注曰：「人惟五十，然后养阴者有以加」，《内经》「年至四十，阴气自半而起居衰矣」，男子六十四岁而精绝，女子四十九岁而经断。夫以阴气之成，止为三十年之运用，而竟已先亏，可不知所保养也。经曰：「阳者天也，主外；阴者地也，主内。故阳道实，阴道虚。」斯言岂欺我哉？或曰：远取诸天地日月，近取诸男子之身，曰有余，曰不足，吾已知之矣。人在气交之中，今欲顺阴阳之理而为摄养之法，如之何则可？曰：主闭藏者，肾也；司疏泄者，肝也。二脏皆有相火，而其系上属于心，心君火也。为物所感则易于动，心动则相火翕然而随。圣贤教人收心养心，其旨深矣。天地以五行更迭衰旺而成四时，人之五脏六腑，亦应之而衰旺，四月属巳，五月属午，为火不旺。火为肺金之夫，火旺则金衰。六月属未，为土大旺，土为水之夫，土旺则水衰，况肾水尝藉肺金为母，以补助其不足。古人于夏月必独宿而淡味，兢兢业业，保养金水二脏，正嫌火土之旺尔。《内经》又曰：「冬藏精者，春不病湿」，十月属亥，十一月属子，正元气潜伏闭藏，以养其本然之真，而为来春升动发生之本。若于此时不恣欲以自戕，至春升之际，根本壮实，气不轻浮，尚何病之可言哉？于是翁之医益闻，四方以病来迎者，遂辐辏于道，翁咸往赴之。其所治病凡几，病之状何如，施何良方，饮何药而愈，自前至今验者何人何县里主名，得诸见闻，班班可纪。浦江郑义士，病滞下，一夕，忽昏仆，目上视，溲注而汗泻。翁诊之，脉大无伦，即告曰：「此阴虚阳暴绝也，盖得之病后酒且内，然吾能愈之。」急命治人参膏，而且促灸其气海。顷之，手动，又顷而唇动。及参膏成，三饮之，苏矣。其后服参膏尽数斤，病已。天台周进士，病恶寒，虽暑亦必以绵蒙其首，服附子数百，增剧。翁诊之，脉滑而数，即告曰：「此热甚而反寒也」，乃以辛凉之剂，吐痰一升许，而蒙首之绵减半。仍用防风通圣饮之，愈。周固喜甚，翁曰：「病愈后，须淡食以养胃，内观以养神，则水可生，火可降，否则附毒必发，殆不可救。彼不能然，后告疽发背死。浙省平章，南征闽粤还，病反胃，医以为可治。翁诊其脉，告曰：「公之病不可言也」，即出，独告其左右曰：「此病得之惊后而使内，火木之邪相挟，气伤液亡，肠胃枯损，食虽入而不化，食既不化，五脏皆无所禀。去此十日，死。」果如言。郑义士家一少年，秋初病热，口渴而妄语，两颧火赤，医作大热治。翁诊之，脉弱而迟，告曰：「此作劳后病温，惟当服补剂自已，今六脉皆搏手，必凉药所致。」竟以附子汤啜之，应手而瘥。浙东宪幕傅氏子，病妄语，时若有所见，其家妖之。翁切其脉，告曰：「此病痰也，然脉虚弦而沉数，盖得之当暑饮酸又大惊。」傅曰：「然！尝夏因劳而甚渴，恣饮梅水一二升，又连得惊数次，遂病。」翁以治痰补虚之剂处之，旬浃愈。里人陈时叔病胀，腹如斗，医用利药转加。翁诊之，脉数而涩，告曰：「此得之嗜酒，嗜酒则血伤。血伤则脾土之阴亦伤，胃虽受谷，不能以转输，故阳升阴降而否矣。」陈曰：「某以嗜酒，前后溲见血者有年。」翁用补血之剂投之，验。权贵人以微疾来召，见翁至，坐中堂自如。翁诊其脉，不与言而出。使诘之，则曰：「公病在死法中，不出三月，且入鬼录。」顾犹有骄气耶，后果如期死。一老人病目无见，使来求治。翁诊其脉，微甚，为制人参膏饮之，目明如常时。后数日，翁复至，忽见一医在庭炼礞石，问之，则已服之矣。翁愕然曰：「此病得之气大虚，今不救其虚，而反用礞石，不出此夜必死。」至夜参半，气奄奄不相属而死。一男子病小便不通，医治以利药，益甚。翁诊之，右寸颇弦滑，曰：「此积痰病也，积痰在肺。肺为上焦，而膀胱为下焦，上焦闭则下焦塞，譬如滴水之器，必上窍通，而后下窍之水出焉。」乃以法大吐之，吐已，病如失。一妇人病不知，稍苏，即号叫数四而复昏。翁诊之，肝脉弦数而且滑，曰：「此怒心所为，盖得之怒而强酒也。」诘之，则不得于夫，每遇夜，引满自酌解其怀。翁治以流痰降火之剂，而加香附以散肝分之郁，立愈。一女子病不食，面北卧者且半载，医告术穷。翁诊之，肝脉弦出左口，曰：「此思男子不得，气结于脾故耳。」叩之，则许嫁夫入广且五年。翁谓其父曰：「是病惟怒可解，盖怒之气击而属木，故能冲其土之结。今茅触之使怒耳。」父以为不然。翁入而掌其面者三，责以不当有外思，女子号泣大怒，怒已，进食。翁复潜谓其父曰：「思气虽解，然必得喜，则庶不再结。」乃诈以夫有书，旦夕且归。后三月，夫果归而病不作。一妇人产后，有物不上如衣裾，医不能喻。翁曰：「此子宫也，气血虚，故随子而下。」即与黄耆当归之剂，而加升麻举之，仍用皮工之法，以五倍子作汤洗濯，皴其皮。少选，子宫上。翁慰之曰：「三年后可再生儿，无忧也。」如之。一贫妇寡居病癞，翁见之恻然，乃曰：「是疾世号难治者，不守禁忌耳。是妇贫而无厚味，寡而无欲，庶几可疗也。」即自具药疗之，病愈后复投四物汤数百，遂不发动。翁之为医，皆此类也。盖其遇病施治，不胶于古方，而所疗皆中。然于诸家方论，则靡所不通。他人靳靳守古，翁则操纵取舍而卒与古合。一时学者咸声随影附，翁教之亹亹忘疲。一日，门人赵良仁问大极之旨。翁以阴阳造化之精微与医道相出入者论之，且曰：「吾于诸生中，未尝论至于此。今以吾子所问，故偶及之，是盖以道相告，非徒以医言也。赵出语人曰：「翁之医其始橐籥于此乎！罗成之自金陵来见，自以为精仲景学，翁曰：「仲景之书，收拾于残篇断简之余，然其间或文有不备，或意有未尽，或编次之脱落，或义例之乖舛，吾每观之，不能以无疑。」因略摘疑义数条以示，罗尚未悟。及遇治一疾，翁以阴虚发热而用益阴补血之剂疗之，不三日而愈。罗乃叹曰：「以某之所见，未免作伤寒治。今翁治此，犹以芎归之性辛温，而非阴虚者所宜服，又况汗下之误乎！」翁春秋既高，乃徇张翼等所请，而著《格致余论》《局方发挥》《伤寒辨疑》《本草衍义补遗》《外科精要新论》诸书，学者多诵习而取则焉。翁简悫贞良，刚严介特，执心以正，立身以诚，而孝友之行，实本乎天质。奉时祀也，订其礼文而敬泣之；事母夫人也，时其节宣以忠养之。宁歉于己而必致丰于兄弟；宁薄于己子而必施厚于兄弟之子。非其友不友，非其道不道。好论古今得失，慨然有天下之忧。世之名公卿，多折节下之，翁谓直陈治道，无所顾忌。然但语及荣利事，则拂衣而起。与人交，一以三纲五纪为去就。尝曰：「天下有道，则行有枝叶；天下无道，则辞有枝叶。」夫行，本也；辞，从而生者也。苟见枝叶之辞，去本而末是务，辄怒溢颜面，若将浼焉。翁之卓卓如是，则医又特一事而已。然翁讲学行事之大方，已具吾友宋太史濂所为翁墓志，兹故不录。而窃录其医之可传者为翁传，庶使后之君子得以互考焉。", "18720": "余宗族素多，向余二百。建安纪年以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救，乃勤求古训，博采众方，撰用《素问》、《九卷》、《八十一难》、《阴阳大论》、《胎胪药录》，并平脉辨证，为《伤寒杂病论》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。", "18721": "辨脉法第一", "18722": "问曰：脉有阴阳者，何谓也？答曰：凡脉大、浮、数、动、滑，此名阳也；脉沈、濇、弱、弦、微，此名阴也，凡阴病见阳脉者生，阳病见阴脉者死。", "18723": "问曰：脉有阳结阴结者，何以别之？答曰：其脉浮而数，能食，不大便者，此为实，名曰阳结也，期十七日当剧。其脉沈而迟，不能食，身体重，大便反鞕，名曰阴结也，期十四日当剧。", "18724": "问曰：病有洒淅恶寒而复发热者何？答曰：阴脉不足，阳往从之；阳脉不足，阴往乘之。曰：何谓阳不足？答曰：假令寸口脉微，名曰阳不足，阴气上入阳中，则洒淅恶寒也。曰：何谓阴不足？答曰：假令尺脉弱，名曰阴不足，阳气下陷入阴中，则发热也。阳脉浮（一作微）阴脉弱者，则血虚。血虚则筋急也。其脉沈者，荣气微也。其脉浮，而汗出如流珠者，卫气衰也。荣气微者，加烧针，则血流不行，更发热而躁烦也。", "18725": "脉蔼蔼，如车盖者，名曰阳结也。（一云秋脉）", "18726": "脉累累，如循长竿者，名曰阴结也。（一云夏脉）", "18727": "脉瞥瞥，如羹上肥者，阳气微也。", "18728": "脉萦萦，如蜘蛛丝者，阳气衰也。（一云阴气）", "18729": "脉绵绵，如泻漆之绝者，亡其血也。", "18730": "脉来缓，时一止复来者，名曰结。脉来数，时一止复来者，名曰促（一作纵）。脉阳盛则促，阴盛则结，此皆病脉。", "18731": "若数脉见于关上，上下无头尾，如豆大，厥厥动摇者，名曰动也。", "18732": "阳脉浮大而濡，阴脉浮大而濡，阴脉与阳脉同等者，名曰缓也。", "18733": "脉浮而紧者，名曰弦也。弦者状如弓弦，按之不移也。脉紧者，如转索无常也。", "18734": "脉弦而大，弦则为减，大则为芤。减则为寒，芤则为虚。寒虚相抟，此名为革。妇人则半产、漏下，男子则亡血、失精。", "18735": "问曰：病有战而汗出，因得解者，何也？答曰：脉浮而紧，按之反芤，此为本虚，故当战而汗出也。其人本虚，是以发战。以脉浮，故当汗出而解也。", "18736": "若脉浮而数，按之不芤，此人本不虚；若欲自解，但汗出耳。不发战也。", "18737": "问曰：病有不战而汗出解者，何也？答曰：脉大而浮数，故知不战，汗出而解也。", "18738": "问曰：病有不战不汗出而解者，何也？答曰：其脉自微，此以曾经发汗、若吐、若下、若亡血，以内无津液，此阴阳自和，必自愈，故不战不汗出而解也。", "18739": "问曰：伤寒三日，脉浮数而微，病人身凉和者，何也？答曰：此为欲解也，解以夜半。脉浮而解者，濈然汗出也；脉数而解者，必能食也；脉微而解者，必大汗出也。", "18740": "问曰：脉病，欲知愈未愈者，何以别之？答曰：寸口、关上、尺中三处，大小、浮沈、迟数同等，虽有寒热不解者，此脉阴阳为和平，虽剧当愈。", "18741": "立夏得洪（一作浮）大脉，是其本位。其人病身体苦疼重者，须发其汗。若明日身不疼不重者，不须发汗。若汗濈濈自出者，明日便解矣。何以言之？立夏得洪大脉，是其时脉，故使然也。四时倣此。", "18742": "寸口脉浮为在表，沈为在里，数为在府，迟为在藏。假令脉迟，此为在藏也。", "18743": "趺阳脉浮而濇，少阴脉如经也，其病在脾，法当下利。何以知之？若脉浮大者，气实血虚也。今趺阳脉浮而濇，故知脾气不足，胃气虚也。以少阴脉弦而浮（一作沈），才见此为调脉，故称如经也。若反滑而数者，故知当屎脓也（玉函作溺）。", "18744": "寸口脉浮而紧，浮则为风，紧则为寒；风则伤卫，寒则伤荣。荣卫俱病，骨节烦疼，当发其汗也。", "18745": "趺阳脉迟而缓，胃气如经也。趺阳脉浮而数，浮则伤胃，数则动脾，此非本病，医特下之所为也。荣卫内陷，其数先微，脉反但浮，其人必大便鞕，气噫而除。何以言之？本以数脉动脾，其数先微，故知脾气不治，大便鞕，气噫而除。今脉反浮，其数改微，邪气独留，心中则饥，邪热不杀谷，潮热发渴，数脉当迟缓，脉因前后度数如法，病者则饥。数脉不时，则生恶疮也。", "18746": "师曰：病人脉微而濇者，此为医所病也。大发其汗，又数大下之，其人亡血，病当恶寒，后乃发热，无休止时，夏月盛热，欲著复衣，冬月盛寒，欲裸其身。所以然者，阳微则恶寒，阴弱则发热，此医发其汗，令阳气微，又大下之，令阴气弱。五月之时，阳气在表，胃中虚冷，以阳气内微，不能胜冷，故欲著复衣；十一月之时，阳气在里，胃中烦热，以阴气内弱，不能胜热，故欲裸其身。又阴脉迟濇，故知血亡也。", "18747": "脉浮而大，心下反鞕，有热属藏者，攻之，不令发汗。属府者，不令溲数。溲数则大便鞕，汗多则热愈，汗少则便难，脉迟，尚未可攻。", "18748": "脉浮而洪，身汗如油，喘而不休，水浆不下，体形不仁，乍静乍乱，此为命绝也。又未知何藏先受其灾，若汗出、发润、喘不休者，此为肺先绝也。阳反独留，形体如烟熏，直视摇头，此心绝也。唇吻反青，四肢漐习者，此为肝绝也。环口黧黑，柔汗发黄者，此为脾绝也。溲便遗失，狂言，目反直视者，此为肾绝也。", "18749": "寸口脉浮大，而医反下之，此为大逆。浮则无血，大则为寒，寒气相抟，则为肠鸣，医乃不知，而反饮冷水，令汗大出，水得寒气，冷必相抟，其人即䭇。趺阳脉浮，浮则为虚，浮虚相抟，故令气䭇，言胃气虚竭也，脉滑则为哕。此为医咎，责虚取实，守空迫血。脉浮、鼻中燥者，必衄也。", "18750": "诸脉浮数，当发热，而洒淅恶寒，若有痛处，饮食如常者，畜积有脓也。脉浮而迟，面热赤而战惕者，六七日当汗出而解。反发热者，差迟。迟为无阳，不能作汗，其身必痒也。", "18751": "寸口脉阴阳俱紧者，法当清邪中于上焦，浊邪中于下焦。清邪中上，名曰洁也；浊邪中下，名曰浑也。阴中于邪，必内栗也，表气微虚，里气不守，故使邪中于阴也。阳中于邪，必发热、头痛、项强、颈挛、腰痛、胫酸。所为阳中雾露之气，故曰清邪中上，浊邪中下。阴气为栗，足膝逆冷，便溺妄出，表气微虚，里气微急，三焦相溷，内外不通。上焦怫郁，藏气相熏，口烂食断也。中焦不治，胃气上冲，脾气不转，胃中为浊，荣卫不通，血凝不流。若卫气前通者，小便赤黄，与热相抟，因热作使，游于经络，出入藏府，热气所过，则为痈脓。若阴气前通者，阳气厥微，阴无所使，客气内入，嚏而出之，声嗢（乙骨切）咽塞，寒厥相逐，为热所拥，血凝自下，状如豚肝。阴阳俱厥，脾气孤弱，五液注下，下焦不阖，清便下重，令便数难，脐筑湫痛，命将难全。", "18752": "脉阴阳俱紧者，口中气出，唇口干燥，踡卧足冷，鼻中涕出，舌上胎滑，勿妄治也。到七日已来，其人微发热，手足温者，此为欲解；或到八日以上，反大发热者，此为难治。设使恶寒者，必欲呕也；腹内痛者，必欲利也。", "18753": "脉阴阳俱紧，至于吐利，其脉独不解，紧去人安，此为欲解。若脉迟至六七日，不欲食，此为晚发，水停故也，为未解；食自可者，为欲解。", "18754": "病六七日，手足三部脉皆至，大烦而口噤不能言，其人躁扰者，必欲解也。若脉和，其人大烦，目重，睑内际黄者，此为欲解也。", "18755": "脉浮而数，浮为风，数为虚，风为热，虚为寒，风虚相抟，则洒淅恶寒也。", "18756": "脉浮而滑，浮为阳，滑为实，阳实相抟，其脉数疾，卫气失度，浮滑之脉数疾，发热汗出者，此为不治。", "18757": "伤寒欬逆上气，其脉散者死，谓其形损故也。", "18758": "平脉法第二", "18759": "问曰：脉有三部，阴阳相乘；荣卫血气，在人体躬；呼吸出入，上下于中；因息游布，津液流通；随时动作，效象形容，春弦秋浮，冬沈夏洪；察色观脉，大小不同；一时之间，变无经常；尺寸参差，或短或长；上下乖错，或存或亡；病辄改易，进退低昂；心迷意惑，动失纪纲；愿为具陈，令得分明。师曰：子之所问，道之根源。脉有三部，尺寸及关；荣卫流行，不失衡铨；肾沈心洪，肺浮肝弦；此自经常，不失铢分；出入升降，漏刻周旋；水下二刻，一周循环；当复寸口，虚实见焉；变化相乘，阴阳相干；风则浮虚，寒则牢坚；沈潜水畜，支饮急弦；动则为痛，数则热烦；设有不应，知变所缘；三部不同，病各异端；太过可怪，不及亦然；邪不空见，中必有奸；审察表里，三焦别焉；知其所舍，消息诊看；料度府藏，独见若神。为子条记，传与贤人。", "18760": "师曰：呼吸者，脉之头也。初持脉，来疾去迟，此出疾入迟，名曰内虚外实也。初持脉，来迟去疾，此出迟入疾，名曰内实外虚也。", "18761": "问曰：上工望而知之，中工问而知之，下工脉而知之，愿闻其说。师曰：病家人请云，病人若发热，身体疼，病人自卧。师到，诊其脉，沈而迟者，知其差也。何以知之？表有病者，脉当浮大，今脉反沈迟，故知愈也。", "18762": "假令病人云，腹内卒痛，病人自坐。师到，脉之，浮而大者，知其差也。何以知之？若里有病者，脉当沈而细，今脉浮大，故知愈也。", "18763": "师曰：病家人来请云，病人发热烦极。明日师到，病人向壁卧，此热已去也。设令脉不和，处言已愈。设令向壁卧，闻师到，不惊起而盼视，若三言三止，脉之咽唾者，此诈病也。设令脉自和，处言汝病大重，当须服吐下药，针灸数十百处乃愈。", "18764": "师持脉，病人欠者，无病也；脉之呻者，病也；言迟者，风也；摇头言者，里痛也；行迟者，表强也；坐而伏者，短气也；坐而下一脚者，腰痛也；里实护腹，如怀卵物者，心痛也。", "18765": "师曰：伏气之病，以意候之。今月之内，欲有伏气，假令旧有伏气，当须脉之。若脉微弱者，当喉中痛似伤，非喉痹也。病人云：实咽中痛。虽尔，今复欲下利。", "18766": "问曰：人病恐怖者，其脉何状？师曰：脉形如循丝，累累然，其面白脱色也。", "18767": "问曰：人不饮，其脉何类？师曰：其脉自濇，唇口干燥也。", "18768": "问曰：人愧者，其脉何类？师曰：脉浮，而面色乍白乍赤。", "18769": "问曰：经说脉有三菽、六菽重者，何谓也？师曰：脉者，人以指按之，如三菽之重者，肺气也；如六菽之重者，心气也；如九菽之重者，脾气也；如十二菽之重者，肝气也；按之至骨者，肾气也。", "18770": "假令下利，寸口、关上、尺中悉不见脉，然尺中时一小见，脉再举头者，肾气也。若见损脉来至，为难治。", "18771": "问曰：脉有相乘，有纵有横，有逆有顺，何也？师曰：水行乘火，金行乘木，名曰纵；火行乘水，木行乘金，名曰横；水行乘金，火行乘木，名曰逆；金行乘水，木行乘火，名曰顺也。", "18772": "问曰：脉有残贼，何谓也？师曰：脉有弦、紧、浮、滑、沈、濇，此六者名曰残贼，能为诸脉作病也。", "18773": "问曰：脉有灾怪，何谓也？师曰：假令人病，脉得太阳，与形证相应，因为作汤。比还送汤如食顷，病人乃大吐，若下利，腹中痛。师曰：我前来不见此证，今乃变异，是名灾怪。又问曰：何缘作此吐利？答曰：或有旧时服药，今乃发作，故名灾怪耳。", "18774": "问曰：东方肝脉，其形何似？师曰：肝者木也，名厥阴，其脉微弦，濡弱而长，是肝脉也。肝病自得濡弱者，愈也。假令得纯弦脉者，死。何以知之？以其脉如弦直，是肝藏伤，故知死也。", "18775": "南方心脉，其形何似？师曰：心者火也，名少阴，其脉洪大而长，是心脉也。心病自得洪大者，愈也。假令脉来微去大，故名反，病在里也；脉来头小本大者，故名覆，病在表也。上微头小者，则汗出；下微本大者，则为关格不通，不得尿，头无汗者可治，有汗者死。", "18776": "西方肺脉，其形何似？师曰：肺者金也，名大阴，其脉毛浮也，肺病自得此脉。若得缓迟者，皆愈；若得数者，则剧。何以知之？数者南方火，火克西方金，法当痈肿，为难治也。", "18777": "问曰：二月得毛浮脉，何以处言至秋当死？师曰：二月之时，脉当濡弱，反得毛浮者，故知至秋死。二月肝用事，肝脉属木，应濡弱，反得毛浮者，是肺脉也。肺属金，金来克木，故知至秋死。他皆倣此。", "18778": "师曰：脉肥人责浮，瘦人责沈。肥人当沈，今反浮；瘦人当浮，今反沈，故责之。", "18779": "师曰：寸脉下不至关，为阳绝；尺脉上不至关，为阴绝。此皆不治，决死也。若计其余命死生之期，期以月节克之也。", "18780": "师曰：脉病人不病，名曰行尸，以无王气，卒眩仆不识人者，短命则死。人病脉不病，名曰内虚，以无谷神，虽困无苦。", "18781": "问曰：翕奄沈，名曰滑，何谓也？沈为纯阴，翕为正阳，阴阳和合，故令脉滑。关尺自平，阳明脉微沈，食饮自可。少阴脉微滑，滑者紧之浮名也，此为阴实，其人必股内汗出，阴下湿也。", "18782": "问曰：曾为人所难，紧脉从何而来？师曰：假令亡汗、若吐，以肺里寒，故令脉紧也。假令欬者，坐饮冷水，故令脉紧也。假令下利，以胃中虚冷，故令脉紧也。", "18783": "寸口脉缓而迟，缓则阳气长，其色鲜，其颜光，其声商，毛发长；迟则阴气盛，骨髓生，血满，肌肉紧薄鲜鞕。阴阳相抱，荣卫俱行，刚柔相抟，名曰强也。", "18784": "趺阳脉滑而紧，滑者胃气实，紧者脾气强。持实击强，痛还自伤，以手把刃，坐作疮也。", "18785": "寸口脉浮而大，浮为虚，大为实。在尺为关，在寸为格。关则不得小便，格则吐逆。", "18786": "趺阳脉伏而濇，伏则吐逆，水谷不化，濇则食不得入，名曰关格。", "18787": "脉浮而大，浮为风虚，大为气强；风气相抟，必成瘾疹，身体为痒，痒者名泄风，久久为痂癞。", "18788": "寸口脉弱而迟，弱者卫气微，迟者荣中寒。荣为血，血寒则发热；卫为气，气微者心内饥，饥而虚满不能食也。", "18789": "趺阳脉大而紧者，当即下利，为难治。", "18790": "寸口脉弱而缓，弱者阳气不足，缓者胃气有余，噫而吞酸，食卒不下，气填于膈上也（一作下）。", "18791": "趺阳脉紧而浮，浮为气，紧为寒；浮为腹满，紧为绞痛。浮紧相抟，肠鸣而转，转即气动，隔气乃下，少阴脉不出，其阴肿大而虚也。", "18792": "寸口脉微而濇，微者卫气不行，濇者荣气不足。荣卫不能相将，三焦无所仰，身体痹不仁。荣气不足，则烦疼，口难言；卫气虚，则恶寒数欠。三焦不归其部，上焦不归者，噫而酢吞；中焦不归者，不能消谷引食；下焦不归者，则遗溲。", "18793": "趺阳脉沈而数，沈为实，数消谷。紧者，病难治。", "18794": "寸口脉微而濇，微者卫气衰，濇者荣气不足。卫气衰，面色黄；荣气不足，面色青。荣为根，卫为叶，荣卫俱微，则根叶枯槁，而寒栗、欬逆唾腥、吐涎沫也。", "18795": "趺阳脉浮而芤，浮者卫气衰，芤者荣气伤。其身体瘦，肌肉甲错，浮芤相抟，宗气衰微，四属断绝。", "18796": "寸口脉微而缓，微者卫气疏，疏则其肤空；缓者胃气实，实则谷消而水化也。谷入于胃，脉道乃行，而入于经，其血乃成。荣盛则其肤必疏，三焦绝经，名曰血崩。", "18797": "趺阳脉微而紧，紧则为寒，微则为虚，微紧相抟，则为短气。", "18798": "少阴脉弱而濇，弱者微烦，濇者厥逆。", "18799": "趺阳脉不出，脾不上下，身冷肤鞕。", "18800": "少阴脉不至，肾气微，少精血，奔气促迫，上入胸隔，宗气反聚，血结心下，阳气退下，热归阴股，与阴相动，令身不仁，此为尸厥，当刺期门、巨阙。", "18801": "寸口脉微，尺脉紧，其人虚损多汗，知阴常在，绝不见阳也。", "18802": "伤寒之病，逐日浅深，以施方治。今世人伤寒，或始不早治，或治不对病，或日数久淹，困乃告医。医人又不依次第而治之，则不中病。皆宜临时消息制方，无不效也。今搜采仲景旧论，录其证候、诊脉、声色，对病真方，有神验者，拟防世急也。", "18803": "尺寸俱浮者，太阳受病也，当一二日发。以其脉上连风府，故头项痛，腰脊强。尺寸俱长者，阳明受病也，当二三日发。以其脉侠鼻，络于目，故身热、目疼、鼻干、不得卧。尺寸俱弦者，少阳受病也，当三四日发。以其脉循胁，络于耳，故胸胁痛而耳聋。此三经皆受病，未入于府者，可汗而已。", "18804": "尺寸俱沈细者，太阴受病也，当四五日发。以其脉布胃中，络于嗌，故腹满而嗌干。尺寸俱沈者，少阴受病也，当五六日发。以其脉贯肾、络于肺、系舌本，故口燥舌干而渴。尺寸俱微缓者，厥阴受病也，当六七日发。以其脉循阴器、络于肝，故烦满而囊缩。此三经皆受病，已入于府，可下而已。", "18805": "若两感于寒者，一日太阳受之，即与少阴俱病，则头痛口干、烦满而渴；二日阳明受之，即与太阴俱病，则腹满身热、不欲食、谵（之廉切，又女监切，下同。）语；三日少阳受之，即与厥阴俱病，则耳聋，囊缩而厥，水浆不入，不知人者，六日死。若三阴三阳、五藏六府皆受病，则荣卫不行，府藏不通，则死矣。其不两感于寒，更不传经，不加异气者，至七日太阳病衰，头痛少愈也；八日阳明病衰，身热少歇也；九日少阳病衰，耳聋微闻也；十日太阴病衰，腹减如故，则思饮食；十一日少阴病衰，渴止舌干，已而嚏也；十二日厥阴病衰，囊纵，少腹微下，大气皆去，病人精神爽慧也。若过十三日以上不间，尺寸陷者，大危。若更感异气，变为他病者，当依旧坏证病而治之。若脉阴阳俱盛，重感于寒者，变成温疟。阳脉浮滑，阴脉濡弱者，更遇于风，变为风温。阳脉洪数，阴脉实大者，遇温热，变为温毒，温毒为病最重也。阳脉濡弱，阴脉弦紧者，更遇温气，变为温疫（一本作疟）。以此冬伤于寒，发为温病，脉之变证，方治如说。", "18806": "凡得病厥，脉动数，服汤药更迟；脉浮大减小；初躁后静，此皆愈证也。", "18807": "凡脉四损，三日死；平人四息，病人脉一至，名曰四损。脉五损，一日死；平人五息，病人脉一至，名曰五损。脉六损，一时死；平人六息，病人脉一至，名曰六损。", "18808": "脉盛身寒，得之伤寒；脉虚身热，得之伤暑。", "18809": "脉阴阳俱盛，大汗出，不解者，死。", "18810": "脉阴阳俱虚，热不止者，死。", "18811": "脉至乍疏乍数者，死。", "18812": "脉至如转索者，其日死。", "18813": "谵言妄语，身微热，脉浮大，手足温者，生。逆冷，脉沈细者，不过一日，死矣。", "18814": "辨痓湿暍脉证第四（痓，音炽，又作痓，巨郢切，下同。）", "18815": "太阳病，发热，脉沈而细者，名曰痓。", "18816": "病身热足寒，颈项强急，恶寒，时头热面赤，目脉赤，独头面摇，卒口噤，背反张者，痓病也。", "18817": "太阳病，关节疼痛而烦，脉沈而细（一作缓）者，此名湿痹（一云中湿）。湿痹之候，其人小便不利，大便反快，但当利其小便。", "18818": "湿家病身上疼痛，发热面黄而喘，头痛鼻塞而烦，其脉大，自能饮食，腹中和无病，病在头中寒湿，故鼻塞，内药鼻中则愈。", "18819": "太阳中暍者，身热疼重，而脉微弱，此亦夏月伤冷水，水行皮中所致也。", "18820": "太阳中暍者，发热恶寒，身重而疼痛，其脉弦细芤迟，小便已，洒洒然毛耸，手足逆冷，小有劳，身即热，口开，前板齿燥。若发汗，则恶寒甚；加温针，则发热甚；数下之，则淋甚。", "18821": "辨太阳病脉证并治上第五", "18822": "太阳之为病，脉浮，头项强痛而恶寒。", "18823": "太阳病，发热，汗出，恶风，脉缓者，名为中风。", "18824": "太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名为伤寒。", "18825": "伤寒一日，太阳受之，脉若静者，为不传。颇欲吐，若躁烦，脉数急者，为传也。", "18826": "太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，鼻息必鼾，语言难出。若被下者，小便不利，直视失溲，若被火者，微发黄色，剧则如惊痫，时瘈疭，若火熏之，一逆尚引日，再逆促命期。", "18827": "太阳病三日，已发汗，若吐、若下、若温针，仍不解者，此为坏病，桂枝不中与之也。观其脉证，知犯何逆，随证治之。桂枝本为解肌，若其人脉浮紧，发热汗不出者，不可与之也。常须识此，勿令误也。", "18828": "太阳病，下之后，脉促胸满者，桂枝去芍药汤主之。桂枝去芍药汤方桂枝（三两，去皮）甘草（二两，炙）生姜（三两，切）大枣（十二枚，擘）右四味，以水七升，煮取三升，去滓，温服一升。本云：桂枝汤，今去芍药。将息如前法。", "18829": "太阳病，下之后，脉促胸满者，桂枝去芍药汤主之。", "18830": "太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可更发汗、更下、更吐也；面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜桂枝麻黄各半汤。桂枝麻黄各半汤方桂枝（一两十六铢，去皮）芍药生姜（切）甘草（炙）麻黄（去节，各一两）大枣（四枚，擘）杏仁（二十四枚，汤浸，去皮尖及两仁者）右七味，以水五升，先煮麻黄一二沸，去上沫，内诸药，煮取一升八合，去滓，温服六合。本云：桂枝汤三合，麻黄汤三合，并为六合，顿服。将息如上法。", "18831": "太阳病，得之八九日，如疟状，发热恶寒，热多寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可更发汗、更下、更吐也；面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜桂枝麻黄各半汤。", "18832": "服桂枝汤，大汗出，脉洪大者，与桂枝汤，如前法。若形似疟，一日再发者，汗出必解，宜桂枝二麻黄一汤。桂枝二麻黄一汤方桂枝（一两十七铢，去皮）芍药（一两六铢）麻黄（十六铢，去节）生姜（一两六铢，切）杏仁（十六个，去皮尖）甘草（一两二铢，炙）大枣（五枚，擘）右七味，以水五升，先煮麻黄一二沸，去上沫，内诸药，煮取二升，去滓，温服一升，日再服。本云：桂枝汤二分，麻黄汤一分，合为二升，分再服。今后合为一方。将息如前法。", "18833": "服桂枝汤，大汗出，脉洪大者，与桂枝汤，如前法。若形似疟，一日再发者，汗出必解，宜桂枝二麻黄一汤。", "18834": "服桂枝汤，大汗出后，大烦渴不解，脉洪大者，白虎加人参汤主之。白虎加人参汤方知母（六两）石膏（一斤，碎，绵裹）甘草（二两，炙）粳米（六合）人参（三两）右五味，以水一斗，煮米熟，汤成，去滓，温服一升，日三服。", "18835": "服桂枝汤，大汗出后，大烦渴不解，脉洪大者，白虎加人参汤主之。", "18836": "太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，宜桂枝二越婢一汤。桂枝二越婢一汤方桂枝（去皮）芍药麻黄甘草（炙，各十八铢）大枣（四枚，擘）生姜（一两二铢，切）石膏（二十四铢，碎，绵裹）右七味，以水五升，煮麻黄一二沸，去上沫，内诸药，煮取二升，去滓，温服一升。本云：当裁为越婢汤、桂枝汤，合之饮一升，今合为一方，桂枝二分，越婢汤一分。", "18837": "太阳病，发热恶寒，热多寒少，脉微弱者，此无阳也，不可发汗，宜桂枝二越婢一汤。", "18838": "伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与桂枝欲攻其表，此误也。得之便厥，咽中干，烦躁吐逆者，作甘草干姜汤与之，以复其阳。若厥愈足温者，更作芍药甘草汤与之，其脚即伸。若胃气不和，谵语者，少与调胃承气汤。若重发汗，复加烧针者，四逆汤主之。甘草干姜汤方甘草（四两，炙）干姜（二两）右二味，以水三升，煮取一升五合，去滓，分温再服。芍药甘草汤方芍药甘草（炙，各四两）右二味，以水三升，煮取一升五合，去滓，分温再服。调胃承气汤方甘草（二两，炙）芒硝（半升）大黄（四两，清酒洗）右三味，以水三升，煮取一升，去滓，内芒硝，更上火微煮令沸，少少温服之。四逆汤方甘草（二两，炙）干姜（一两半）附子（一枚，生用，去皮，破八片）右三味，以水三升，煮取一升二合，去滓，分温再服。强人可大附子一枚、干姜三两。", "18839": "伤寒，脉浮，自汗出，小便数，心烦，微恶寒，脚挛急，反与桂枝欲攻其表，此误也。得之便厥，咽中干，烦躁吐逆者，作甘草干姜汤与之，以复其阳。若厥愈足温者，更作芍药甘草汤与之，其脚即伸。若胃气不和，谵语者，少与调胃承气汤。若重发汗，复加烧针者，四逆汤主之。", "18840": "问曰：证象阳旦，按法治之而增剧，厥逆，咽中干，两胫拘急而谵语。师曰：言夜半手足当温，两脚当伸。后如师言。何以知此？答曰：寸口脉浮而大，浮为风，大为虚，风则生微热，虚则两胫挛，病形象桂枝，因加附子参其间，增桂令汗出，附子温经，亡阳故也。厥逆，咽中干，烦躁，阳明内结，谵语烦乱，更饮甘草干姜汤，夜半阳气还，两足当热，胫尚微拘急，重与芍药甘草汤，尔乃胫伸。以承气汤微溏，则止其谵语，故知病可愈。", "18841": "辨太阳病脉证并治中第六", "18842": "太阳病，桂枝证，医反下之，利遂不止。脉促者，表未解也。喘而汗出者，葛根黄芩黄连汤主之。葛根黄芩黄连汤方葛根（半斤）甘草（二两，炙）黄芩（三两）黄连（三两）右四味，以水八升，先煮葛根，减二升，内诸药，煮取二升，去滓，分温再服。", "18843": "太阳病，桂枝证，医反下之，利遂不止。脉促者，表未解也。喘而汗出者，葛根黄芩黄连汤主之。", "18844": "太阳病，十日已去，脉浮细而嗜卧者，外已解也。设胸满脇痛者，与小柴胡汤；脉但浮者，与麻黄汤。", "18845": "太阳中风，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，大青龙汤主之。若脉微弱，汗出恶风者，不可服之，服之则厥逆，筋惕肉𥆧，此为逆也。大青龙汤方麻黄（六两，去节）桂枝（二两，去皮）甘草（二两，炙）杏仁（四十枚，去皮尖）生姜（三两，切）大枣（十枚，擘）石膏（如鸡子大，碎）右七味，以水九升，先煮麻黄，减二升，去上沫，内诸药，煮取三升，去滓，温服一升，取微似汗。汗出多者，温粉扑之。一服汗者，停后服。若复服，汗多亡阳，遂虚，恶风、烦躁、不得眠也。", "18846": "太阳中风，脉浮紧，发热恶寒，身疼痛，不汗出而烦躁者，大青龙汤主之。若脉微弱，汗出恶风者，不可服之，服之则厥逆，筋惕肉𥆧，此为逆也。", "18847": "伤寒脉浮缓，身不疼，但重，乍有轻时，无少阴证者，大青龙汤发之。", "18848": "太阳病，外证未解，脉浮弱者，当以汗解，宜桂枝汤。", "18849": "太阳病，先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故在外，当须解外则愈，宜桂枝汤。", "18850": "太阳病，脉浮紧，无汗，发热，身疼痛，八九日不解，表证仍在，此当发其汗。服药已微除，其人发烦目瞑，剧者必衄，衄乃解。所以然者，阳气重故也，麻黄汤主之。", "18851": "太阳病，脉浮紧，发热，身无汗，自衄者愈。", "18852": "二阳并病，太阳初得病时，发其汗，汗先出不彻，因转属阳明，续自微汗出，不恶寒。若太阳病证不罢者，不可下，下之为逆，如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之，熏之。若发汗不彻，不足言，阳气怫郁不得越，当汗不汗，其人躁烦，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气但坐，以汗出不彻故也。更发汗则愈，何以知汗出不彻？以脉濇故知也。", "18853": "脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚。须表里实，津液自和，便自汗出愈。", "18854": "脉浮紧者，法当身疼痛，宜以汗解之，假令尺中迟者，不可发汗，何以知然？以荣气不足，血少故也。", "18855": "脉浮者，病在表，可发汗，宜麻黄汤。", "18856": "脉浮而数者，可发汗，宜麻黄汤。", "18857": "病常自汗出者，此为荣气和，荣气和者，外不谐，以卫气不共荣气谐和故尔。以荣行脉中，卫行脉外，复发其汗，荣卫和则愈，宜桂枝汤。", "18858": "伤寒脉浮紧，不发汗，因致衄者，麻黄汤主之。", "18859": "伤寒发汗已解，半日许复烦，脉浮数者，可更发汗，宜桂枝汤。", "18860": "下之后，复发汗，必振寒，脉微细。所以然者，以内外俱虚故也。", "18861": "下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕不渴，无表证，脉沈微，身无大热者，干姜附子汤主之。干姜附子汤方干姜（一两）附子（一枚，生用，去皮，切八片）右二味，以水三升，煮取一升，去滓，顿服。", "18862": "下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕不渴，无表证，脉沈微，身无大热者，干姜附子汤主之。", "18863": "发汗后，身疼痛，脉沈迟者，桂枝加芍药生姜各一两，人参三两新加汤主之。桂枝加芍药生姜各一两人参三两新加汤方桂枝（三两，去皮）芍药（四两）甘草（二两，炙）人参（三两）大枣（十二枚，擘）生姜（四两）右六味，以水一斗二升，煮取三升，去滓，温服一升。本云：桂枝汤，今加芍药、生姜、人参。", "18864": "发汗后，身疼痛，脉沈迟者，桂枝加芍药生姜各一两，人参三两新加汤主之。", "18865": "伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沈紧，发汗则动经，身为振振摇者，茯苓桂枝白术甘草汤主之。茯苓桂枝白术甘草汤方茯苓（四两）桂枝（三两，去皮）白术甘草（炙，各二两）右四味，以水六升，煮取三升，去滓，分温三服。", "18866": "伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沈紧，发汗则动经，身为振振摇者，茯苓桂枝白术甘草汤主之。", "18867": "太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。若脉浮，小便不利，微热消渴者，五苓散主之。五苓散方猪苓（十八铢，去皮）泽泻（一两六铢）白术（十八铢）茯苓（十八铢）桂枝（半两，去皮）右五味，捣为散，以白饮和服方寸匕，日三服。多饮暖水，汗出愈。如法将息。", "18868": "太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。若脉浮，小便不利，微热消渴者，五苓散主之。", "18869": "发汗已，脉浮数，烦渴者，五苓散主之。", "18870": "未持脉时，病人手叉自冒心，师因教试令欬，而不欬者，此必两耳聋无闻也。所以然者，以重发汗，虚，故如此。发汗后，饮水多，必喘；以水灌之，亦喘。", "18871": "衄家，不可发汗，汗出必额上陷，脉急紧，直视不能眴，不得眠。", "18872": "病发热，头痛，脉反沈，若不差，身体疼痛，当救其里，宜四逆汤。", "18873": "太阳病未解，脉阴阳俱停，必先振栗汗出而解。但阳脉微者，先汗出而解；但阴脉微者，下之而解。若欲下之，宜调胃承气汤。", "18874": "得病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食而脇下满痛，面目及身黄，颈项强，小便难者，与柴胡汤，后必下重。本渴饮水而呕者，柴胡不中与也，食谷者哕。", "18875": "伤寒，阳脉濇，阴脉弦，法当腹中急痛，先与小建中汤，不差者，与小柴胡汤主之。小建中汤方桂枝（三两，去皮）甘草（二两，炙）大枣（二十枚，擘）芍药（六两）生姜（三两，切）胶饴（一升）右六味，以水七升，煮取三升，去滓，内饴，更上微火消解，温服一升，日三服。呕家不可用建中汤，以甜故也。", "18876": "伤寒，阳脉濇，阴脉弦，法当腹中急痛，先与小建中汤，不差者，与小柴胡汤主之。", "18877": "伤寒十三日，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，脉调和者，知医以丸药下之，非其治也。若自下利者，脉当微厥，今反和者，此为内实也，调胃承气汤主之。", "18878": "伤寒，腹满，谵语，寸口脉浮而紧，此肝乘脾也，名曰纵。刺期门。", "18879": "伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，卧起不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。桂枝去芍药加蜀漆牡蛎龙骨救逆汤方桂枝（三两，去皮）甘草（二两，炙）生姜（三两，切）大枣（十二枚，擘）牡蛎（五两，熬）蜀漆（三两，洗去腥）龙骨（四两）右七味，以水一斗二升，先煮蜀漆减二升，内诸药，煮取三升，去滓，温服一升。本云：桂枝汤，今去芍药，加蜀漆、牡蛎、龙骨。", "18880": "伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，卧起不安者，桂枝去芍药加蜀漆牡蛎龙骨救逆汤主之。", "18881": "形作伤寒，其脉不弦紧而弱，弱者必渴，被火必谵语，弱者发热脉浮，解之当汗出愈。", "18882": "脉浮，热甚，而反灸之，此为实，实以虚治，因火而动，必咽燥，吐血。", "18883": "微数之脉，慎不可灸。因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。脉浮，宜以汗解。用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也。欲自解者，必当先烦，烦乃有汗而解。何以知之？脉浮，故知汗出解。", "18884": "太阳病，当恶寒发热，今自汗出，反不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，以医吐之所致也，此为小逆。", "18885": "病人脉数，数为热，当消谷引食，而反吐者，此以发汗，令阳气微，膈气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。", "18886": "太阳病，六七日表证仍在，脉微而沈，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也。抵当汤主之。抵当汤方水蛭（熬）虻虫（各三十个，去翅足，熬）桃仁（二十个，去皮尖）大黄（三两，酒洗）右四味，以水五升，煮取三升，去滓，温服一升。不下，更服。", "18887": "太阳病，六七日表证仍在，脉微而沈，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也。抵当汤主之。", "18888": "太阳病，身黄，脉沈结，少腹鞕，小便不利者，为无血也。小便自利，其人如狂者，血证谛也，抵当汤主之。", "18889": "辨太阳病脉证并治下第七", "18890": "问曰：病有结胸，有藏结，其状如何？按之痛，寸脉浮，关脉沈，名曰结胸也。", "18891": "何谓藏结？答曰：如结胸状，饮食如故，时时下利，寸脉浮，关脉小细沈紧，名曰藏结。舌上白胎滑者，难治。", "18892": "结胸证，其脉浮大者，不可下，下之则死。", "18893": "太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，数则为虚。头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气躁烦，心中懊𢙐，阳气内陷，心下因鞕，则为结胸，大陷胸汤主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。大陷胸汤方大黄（六两，去皮）芒硝（一升）甘遂（一钱匕）右三味，以水六升，先煮大黄，取二升，去滓，内芒硝，煮一两沸，内甘遂末，温服一升。得快利，止后服。", "18894": "太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，数则为虚。头痛发热，微盗汗出，而反恶寒者，表未解也，医反下之，动数变迟，膈内拒痛，胃中空虚，客气动膈，短气躁烦，心中懊𢙐，阳气内陷，心下因鞕，则为结胸，大陷胸汤主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄。", "18895": "伤寒六七日，结胸热实，脉沈而紧，心下痛，按之石鞕者，大陷胸汤主之。", "18896": "小结胸病，正在心下，按之则痛，脉浮滑者，小陷胸汤主之。小陷胸汤方黄连（一两）半夏（半升，洗）栝蒌实（大者一枚）右三味，以水六升，先煮栝蒌，取三升，去滓，内诸药，煮取二升，去滓，分温三服。", "18897": "小结胸病，正在心下，按之则痛，脉浮滑者，小陷胸汤主之。", "18898": "太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，此本有寒分也。反下之，若利止，必作结胸；未止者，四日复下之，此作协热利也。", "18899": "太阳病，下之，其脉促，不结胸者，此为欲解也；脉浮者，必结胸；脉紧者，必咽痛；脉弦者，必两脇拘急；脉细数者，头痛未止；脉沈紧者，必欲呕；脉沈滑者，协热利；脉浮滑者，必下血。", "18900": "太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗，发汗则谵语、脉弦，五日谵语不止，当刺期门。", "18901": "妇人中风，发热恶寒，经水适来，得之七八日，热除而脉迟身凉，胸脇下满，如结胸状，谵语者，此为热入血室也。当刺期门，随其实而取之。", "18902": "伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉细者，此为阳微结，必有表，复有里也。脉沈，亦在里也。汗出，为阳微。假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也。脉虽沈紧，不得为少阴病。所以然者，阴不得有汗，今头汗出，故知非少阴也。可与小柴胡汤，设不了了者，得屎而解。", "18903": "脉浮而紧，而复下之，紧反入里，则作痞，按之自濡，但气痞耳。", "18904": "心下痞，按之濡，其脉关上浮者，大黄黄连泻心汤主之。大黄黄连泻心汤方大黄（二两）黄连（一两）右二味，以麻沸汤二升渍之，须臾，绞去滓，分温再服。", "18905": "心下痞，按之濡，其脉关上浮者，大黄黄连泻心汤主之。", "18906": "伤寒吐下后，发汗，虚烦，脉甚微，八九日心下痞鞕，脇下痛，气上冲咽喉，眩冒，经脉动惕者，久而成痿。", "18907": "病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上冲喉咽不得息者，此为胸有寒也，当吐之，宜瓜蒂散。瓜蒂散方瓜蒂（一分，熬黄）赤小豆（一分）右二味，各别捣筛，为散已，合治之，取一钱匕。以香豉一合，用热汤七合，煮作稀糜，去滓。取汁合散，温，顿服之。不吐者，少少加；得快吐，乃止。诸亡血、虚家，不可与瓜蒂散。", "18908": "病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上冲喉咽不得息者，此为胸有寒也，当吐之，宜瓜蒂散。", "18909": "伤寒，脉浮，发热无汗，其表不解，不可与白虎汤；渴欲饮水，无表证者，白虎加人参汤主之。", "18910": "伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而濇者，桂枝附子汤主之。若其人大便鞕，小便自利者，去桂加白术汤主之。桂枝附子汤方桂枝（四两，去皮）附子（三枚，炮，去皮，破）生姜（三两，切）甘草（二两，炙）大枣（十二枚，擘）右五味，以水六升，煮取二升，去滓，分温三服。去桂加白术汤方附子（三枚，炮，去皮，破）白术（四两）生姜（三两，切）甘草（二两，炙）大枣（十二枚，擘）右五味，以水六升，煮取两升，去滓，分温三服。初一服，其人身如痹，半日许复服之，三服都尽，其人如冒状，勿怪。此以附子、术并走皮内，逐水气未得除，故使之耳，法当加桂四两。此本一方二法：以大便鞕、小便自利，去桂也；以大便不鞕、小便不利，当加桂。附子三枚，恐多也。虚弱家及产妇，宜减服之。", "18911": "伤寒八九日，风湿相抟，身体疼烦，不能自转侧，不呕不渴，脉浮虚而濇者，桂枝附子汤主之。若其人大便鞕，小便自利者，去桂加白术汤主之。", "18912": "伤寒，脉浮滑，此以表有热，里有寒，白虎汤主之。白虎汤方知母（六两）石膏（一斤，碎）甘草（二两，炙）粳米（六合）右四味，以水一斗，煮米熟，汤成，去滓，温服一升，日三服。", "18913": "伤寒，脉浮滑，此以表有热，里有寒，白虎汤主之。", "18914": "伤寒，脉结代，心动悸，炙甘草汤主之。炙甘草汤方甘草（四两，炙）生姜（三两，切）人参（二两）生地黄（一斤）桂枝（三两，去皮）阿胶（二两）麦门冬（半斤，去心）麻仁（半升）大枣（三十枚，擘）右九味，以清酒七升，水八升，先煮八味，取三升，去滓，内胶烊消尽，温服一升，日三服。一名复脉汤。", "18915": "伤寒，脉结代，心动悸，炙甘草汤主之。", "18916": "右九味，以清酒七升，水八升，先煮八味，取三升，去滓，内胶烊消尽，温服一升，日三服。一名复脉汤。", "18917": "脉按之来缓，时一止复来者，名曰结。又脉来动而中止，更来小数，中有还者反动，名曰结，阴也。脉来动而中止，不能自还，因而复动者，名曰代，阴也。得此脉者，必难治。", "18918": "辨阳明病脉证并治第八", "18919": "伤寒三日，阳明脉大。", "18920": "伤寒脉浮而缓，手足自温者，是为系在太阴。太阴者，身当发黄，若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。", "18921": "阳明中风，口苦咽干，腹满微喘，发热恶寒，脉浮而紧。若下之，则腹满，小便难也。", "18922": "阳明病，初欲食，小便反不利，大便自调，其人骨节疼，翕翕如有热状，奄然发狂，濈然汗出而解者，此水不胜谷气，与汗共并，脉紧则愈。", "18923": "阳明病，脉迟，食难用饱，饱则微烦头眩，必小便难，此欲作谷瘅，虽下之，腹满如故，所以然者，脉迟故也。", "18924": "阳明病，脉浮而紧者，必潮热，发作有时，但浮者，必盗汗出。", "18925": "阳明病，脉迟，虽汗出不恶寒者，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然汗出者，此大便已鞕也，大承气汤主之；若汗多，微发热恶寒者，外未解也，其热不潮，未可与承气汤；若腹大满不通者，可与小承气汤，微和胃气，勿令致大泄下。大承气汤方大黄（四两，酒洗）厚朴（半斤，炙，去皮）枳实（五枚，炙）芒硝（三合）右四味，以水一斗，先煮二物，取五升，去滓，内大黄，更煮取二升，去滓，内芒硝，更上微火一两沸，分温再服。得下，余勿服。小承气汤方大黄（四两，酒洗）厚朴（二两，炙，去皮）枳实（三枚，大者，炙）右三味，以水四升，煮取一升二合，去滓，分温二服。初服当更衣，不尔者尽饮之，若更衣者，勿服之。", "18926": "阳明病，脉迟，虽汗出不恶寒者，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然汗出者，此大便已鞕也，大承气汤主之；若汗多，微发热恶寒者，外未解也，其热不潮，未可与承气汤；若腹大满不通者，可与小承气汤，微和胃气，勿令致大泄下。", "18927": "发汗多，若重发汗者，亡其阳，谵语，脉短者死，脉自和者不死。", "18928": "伤寒若吐若下后，不解，不大便五六日，上至十余日。日晡所发潮热，不恶寒，独语如见鬼状。若剧者，发则不识人，循衣摸床，惕而不安，微喘直视。脉弦者生，濇者死。微者，但发热谵语者，大承气汤主之。若一服利，则止后服。", "18929": "阳明病，谵语，发潮热，脉滑而疾者，小承气汤主之。因与承气汤一升，腹中转气者，更服一升；若不转气者，勿更与之。明日又不大便，脉反微濇者，里虚也，为难治，不可更与承气汤也。", "18930": "伤寒四五日，脉沈而喘满，沈为在里，而反发其汗，津液越出，大便为难，表虚里实，久则谵语。", "18931": "阳明病，脉浮而紧，咽燥，口苦，腹满而喘，发热汗出，不恶寒，反恶热，身重。若发汗则躁，心愦愦，反谵语，若加温针，必怵惕，烦躁不得眠。若下之，则胃中空虚，客气动膈，心中懊𢙐，舌上胎者，栀子豉汤主之。", "18932": "若脉浮，发热，渴欲饮水，小便不利者，猪苓汤主之。猪苓汤方猪苓（去皮）茯苓泽泻阿胶滑石（碎，各一两）右五味，以水四升，先煮四味，取二升，去滓，内阿胶烊消，温服七合，日三服。", "18933": "若脉浮，发热，渴欲饮水，小便不利者，猪苓汤主之。", "18934": "脉浮而迟，表热里寒，下利清谷者，四逆汤主之。", "18935": "脉浮，发热，口干，鼻燥，能食者则衄。", "18936": "阳明中风，脉弦浮大而短气，腹都满，脇下及心痛，久按之气不通，鼻干，不得汗，嗜卧，一身及目悉黄，小便难，有潮热，时时哕，耳前后肿。刺之小差，外不解，病过十日，脉续浮者，与小柴胡汤。", "18937": "脉但浮，无余证者，与麻黄汤。若不尿，腹满加哕者，不治。", "18938": "阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜桂枝汤。", "18939": "阳明病，脉浮，无汗而喘者，发汗则愈，宜麻黄汤。", "18940": "病人烦热，汗出则解，又如疟状，日晡所发热者，属阳明也。脉实者，宜下之；脉浮虚者，宜发汗。下之，与大承气汤；发汗，宜桂枝汤。", "18941": "阳脉微而汗出少者，为自和也；汗出多者为太过，阳脉实。因发其汗，出多者，亦为太过，太过者，为阳绝于里，亡津液，大便因鞕也。", "18942": "脉浮而芤，浮为阳，芤为阴，浮芤相抟，胃气生热，其阳则绝。", "18943": "趺阳脉浮而濇，浮则胃气强，濇则小便数，浮濇相抟，大便则鞕，其脾为约，麻子仁丸主之。麻子仁丸方麻子仁（二升）芍药（半斤）枳实（半斤，炙）大黄（一斤，去皮）厚朴（一尺，炙，去皮）杏仁（一升，去皮尖，熬，别作脂）右六味，蜜和丸，如梧桐子大，饮服十丸，日三服，渐加，以知为度。", "18944": "趺阳脉浮而濇，浮则胃气强，濇则小便数，浮濇相抟，大便则鞕，其脾为约，麻子仁丸主之。", "18945": "得病二三日，脉弱，无太阳柴胡证，烦躁，心下鞕，至四五日，虽能食，以小承气汤少少与，微和之，令小安。至六日，与承气汤一升。若不大便六七日，小便少者，虽不受食，但初头鞕，后必溏，未定成鞕，攻之必溏，须小便利，屎定鞕，乃可攻之，宜大承气汤。", "18946": "阳明少阳合病，必下利，其脉不负者，为顺也。负者，失也。互相克贼，名为负也。脉滑而数者，有宿食也。当下之，宜大承气汤。", "18947": "病人无表里证，发热七八日，虽脉浮数者，可下之。假令已下，脉数不解，合热则消谷善饥，至六七日，不大便者，有瘀血，宜抵当汤。", "18948": "若脉数不解，而下不止，必协热便脓血也。", "18949": "辨少阳病脉证并治第九", "18950": "伤寒，脉弦细，头痛发热者，属少阳。少阳不可发汗，发汗则谵语，此属胃，胃和则愈；胃不和，烦而悸。", "18951": "本太阳病不解，转入少阳者，脇下鞕满，干呕不能食，往来寒热，尚未吐下，脉沈紧者，与小柴胡汤。", "18952": "三阳合病，脉浮大，上关上，但欲眠睡，目合则汗。", "18953": "伤寒三日，少阳脉小者，欲已也。", "18954": "辨太阴病脉证并治第十", "18955": "太阴中风，四肢烦疼，脉阳微阴濇而长者，为欲愈。", "18956": "太阴病，脉浮者，可发汗，宜桂枝汤。", "18957": "伤寒脉浮而缓，手足自温者，系在太阴。太阴当发身黄，若小便自利者，不能发黄；至七八日，虽暴烦下利，日十余行，必自止，以脾家实，腐秽当去故也。", "18958": "太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。", "18959": "辨少阴病脉证并治第十一", "18960": "少阴之为病，脉微细，但欲寐也。", "18961": "病人脉阴阳俱紧，反汗出者，亡阳也，此属少阴，法当咽痛而复吐利。", "18962": "少阴病，脉细沈数，病为在里，不可发汗。", "18963": "少阴病，脉微，不可发汗，亡阳故也。阳已虚，尺脉弱濇者，复不可下之。", "18964": "少阴病，脉紧，至七八日，自下利，脉暴微，手足反温，脉紧反去者，为欲解也，虽烦下利，必自愈。", "18965": "少阴中风，脉阳微阴浮者，为欲愈。", "18966": "少阴病，吐、利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。", "18967": "少阴病，四逆，恶寒而身踡，脉不至，不烦而躁者，死。", "18968": "少阴病，脉微细沈，但欲卧，汗出不烦，自欲吐。至五六日，自利，复烦躁不得卧寐者，死。", "18969": "少阴病，始得之，反发热，脉沈者，麻黄细辛附子汤主之。麻黄细辛附子汤方麻黄（二两，去节）细辛（二两）附子（一枚，炮，去皮，破八片）右三味，以水一斗，先煮麻黄，减二升，去上沫，内诸药，煮取三升，去滓，温服一升，日三服。", "18970": "少阴病，始得之，反发热，脉沈者，麻黄细辛附子汤主之。", "18971": "少阴病，身体痛，手足寒，骨节痛，脉沈者，附子汤主之。", "18972": "少阴病，下利，脉微者，与白通汤。利不止，厥逆无脉，干呕烦者，白通加猪胆汁汤主之。服汤，脉暴出者死，微续者生。白通加猪胆汁汤方葱白（四茎）干姜（一两）附子（一枚，生，去皮，破八片）人尿（五合）猪胆汁（一合）右五味，以水三升，煮取一升，去滓，内胆汁、人尿，和令相得，分温再服。若无胆，亦可用。", "18973": "少阴病，下利，脉微者，与白通汤。利不止，厥逆无脉，干呕烦者，白通加猪胆汁汤主之。服汤，脉暴出者死，微续者生。", "18974": "少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒。其人面色赤，或腹痛，或干呕，或咽痛，或利止脉不出者，通脉四逆汤主之。通脉四逆汤方甘草（二两，炙）附子（大者一枚，生用，去皮，破八片）干姜（三两，强人可四两）右三味，以水三升，煮取一升二合，去滓，分温再服。其脉即出者愈。面色赤者，加葱九茎；腹中痛者，去葱，加芍药二两；呕者，加生姜二两；咽痛者，去芍药，加桔梗一两；利止、脉不出者，去桔梗，加人参二两。病皆与方相应者，乃服之。", "18975": "少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒。其人面色赤，或腹痛，或干呕，或咽痛，或利止脉不出者，通脉四逆汤主之。", "18976": "通脉四逆汤方", "18977": "右三味，以水三升，煮取一升二合，去滓，分温再服。其脉即出者愈。面色赤者，加葱九茎；腹中痛者，去葱，加芍药二两；呕者，加生姜二两；咽痛者，去芍药，加桔梗一两；利止、脉不出者，去桔梗，加人参二两。病皆与方相应者，乃服之。", "18978": "少阴病，脉沈者，急温之，宜四逆汤。", "18979": "少阴病，饮食入口则吐，心中温温欲吐，复不能吐，始得之，手足寒，脉弦迟者，此胸中实，不可下也，当吐之。若膈上有寒饮，干呕者，不可吐也，当温之，宜四逆汤。", "18980": "少阴病，下利，脉微濇，呕而汗出，必数更衣，反少者，当温其上，灸之。", "18981": "辨厥阴病脉证并治第十二", "18982": "厥阴中风，脉微浮为欲愈，不浮为未愈。", "18983": "伤寒，始发热六日，厥反九日而利。凡厥利者，当不能食；今反能食者，恐为除中。食以索饼，不发热者，知胃气尚在，必愈。恐暴热来出而复去也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，与厥相应，故期之旦日夜半愈。后三日脉之而脉数，其热不罢者，此为热气有余，必发痈脓也。", "18984": "伤寒脉迟，六七日，而反与黄芩汤彻其热，脉迟为寒，今与黄芩汤复除其热，腹中应冷，当不能食，今反能食，此名除中，必死。", "18985": "伤寒，脉微而厥，至七八日，肤冷，其人躁无暂安时者，此为藏厥，非蚘厥也。蚘厥者，其人当吐蚘，令病者静而复时烦者，此为藏寒。蚘上入其膈故烦，须臾复止，得食而呕，又烦者，蚘闻食臭出，其人常自吐蚘。蚘厥者，乌梅丸主之。又主久利。乌梅丸方乌梅（三百枚）细辛（六两）干姜（十两）黄连（十六两）附子（六两，炮，去皮）当归（四两）黄檗（六两）桂枝（六两，去皮）人参（六两）蜀椒（四两，出汗）右十味，异捣筛，合治之，以苦酒渍乌梅一宿，去核，蒸之五斗米下，饭熟捣成泥，和药令相得，内臼中，与蜜，杵二千下，丸如梧桐子大。先食饮服十丸，日三服，稍加至二十九。禁生冷、滑物、臭食等。", "18986": "伤寒，脉微而厥，至七八日，肤冷，其人躁无暂安时者，此为藏厥，非蚘厥也。蚘厥者，其人当吐蚘，令病者静而复时烦者，此为藏寒。蚘上入其膈故烦，须臾复止，得食而呕，又烦者，蚘闻食臭出，其人常自吐蚘。蚘厥者，乌梅丸主之。又主久利。", "18987": "伤寒六七日，脉微，手足厥冷，烦躁，灸厥阴，厥不还者，死。", "18988": "伤寒五六日，不结胸，腹濡，脉虚复厥者，不可下，此亡血，下之死。", "18989": "伤寒脉促，手足厥逆，可灸之。", "18990": "伤寒，脉滑而厥者，里有热，白虎汤主之。", "18991": "手足厥寒，脉细欲绝者，当归四逆汤主之。当归四逆汤方当归（三两）桂枝（三两，去皮）芍药（三两）细辛（三两）甘草（二两，炙）通草（二两）大枣（二十五枚，擘，一法十二枚）右七味，以水八升。煮取三升，去滓，温服一升，日三服。", "18992": "手足厥寒，脉细欲绝者，当归四逆汤主之。", "18993": "病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜瓜蒂散。", "18994": "伤寒六七日，大下后，寸脉沈而迟，手足厥逆，下部脉不至，喉咽不利，唾脓血，泄利不止者，为难治，麻黄升麻汤主之。麻黄升麻汤方麻黄（二两半，去节）升麻（一两一分）当归（一两一分）知母（十八株）黄芩（十八株）萎蕤（十八铢，一作菖蒲）芍药（六铢）天门冬（六铢，去心）桂枝（六铢，去皮）茯苓（六铢）甘草（六铢，炙）石膏（六铢，碎，绵裹）白术（六铢）干姜（六铢）右十四味，以水一斗，先煮麻黄一两沸，去上沫，内诸药，煮取三升，去滓，分温三服。相去如炊三斗米顷，令尽，汗出愈。", "18995": "伤寒六七日，大下后，寸脉沈而迟，手足厥逆，下部脉不至，喉咽不利，唾脓血，泄利不止者，为难治，麻黄升麻汤主之。", "18996": "下利，有微热而渴，脉弱者，今自愈。", "18997": "下利脉数，有微热汗出，今自愈。设复紧，为未解。", "18998": "下利，手足厥冷，无脉者，灸之。不温。若脉不还，反微喘者，死。少阴负趺阳者，为顺也。", "18999": "下利，寸脉反浮数，尺中自濇者，必清脓血。", "19000": "下利，脉沈弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。", "19001": "下利，脉沈而迟，其人面少赤，身有微热，下利清谷者，必郁冒汗出而解。病人必微厥。所以然者，其面戴阳，下虚故也。", "19002": "下利，脉数而渴者，今自愈。设不差，必清脓血，以有热故也。", "19003": "下利后脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。", "19004": "伤寒下利，日十余行，脉反实者，死。", "19005": "下利清谷，里寒外热，汗出而厥者，通脉四逆汤主之。", "19006": "呕而脉弱，小便复利，身有微热，见厥者难治，四逆汤主之。", "19007": "辨霍乱病脉证并治第十三", "19008": "伤寒，其脉微濇者，本是霍乱，今是伤寒，却四五日，至阴经上，转入阴必利；本呕，下利者，不可治也。欲似大便，而反失气，仍不利者，此属阳明也，便必鞕，十三日愈。所以然者，经尽故也。下利后，当便鞕，鞕则能食者愈。今反不能食，到后经中，颇能食，复过一经能食，过之一日当愈；不愈者，不属阳明也。", "19009": "恶寒脉微而复利，利止，亡血也，四逆加人参汤主之。四逆加人参汤方甘草（二两，炙）附子（一枚，生，去皮，破八片）干姜（一两半）人参（一两）右四味，以水三升，煮取一升二合，去滓，分温再服。", "19010": "恶寒脉微而复利，利止，亡血也，四逆加人参汤主之。", "19011": "既吐且利，小便复利而大汗出，下利清谷，内寒外热，脉微欲绝者，四逆汤主之。", "19012": "吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，通脉四逆加猪胆汁汤主之。通脉四逆加猪胆汁汤方甘草（二两，炙）干姜（三两，强人可四两）附子（大者一枚，生，去皮，破八片）猪胆汁（半合）右四味，用水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来。无猪胆，以羊胆代之。", "19013": "吐已下断，汗出而厥，四肢拘急不解，脉微欲绝者，通脉四逆加猪胆汁汤主之。", "19014": "通脉四逆加猪胆汁汤方", "19015": "右四味，用水三升，煮取一升二合，去滓，内猪胆汁，分温再服，其脉即来。无猪胆，以羊胆代之。", "19016": "吐利，发汗，脉平，小烦者，以新虚不胜谷气故也。", "19017": "辨阴阳易差后劳复病脉证并治第十四", "19018": "伤寒差以后，更发热，小柴胡汤主之。脉浮者，以汗解之；脉沈实者，以下解之。", "19019": "病人脉已解，而日暮微烦，以病新差，人强与谷，脾胃气尚弱，不能消谷，故令微烦，损谷则愈。", "19020": "辨不可发汗病脉证并治第十五", "19021": "脉濡而弱，弱反在关，濡反在巅，微反在上，濇反在下。微则阳气不足，濇则无血。阳气反微，中风汗出而反躁烦。濇则无血，厥而且寒。阳微发汗，躁不得眠。", "19022": "诸脉得数动微弱者，不可发汗，发汗则大便难，腹中干，胃燥而烦，其形相象，根本异源。", "19023": "脉微而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，不可发汗，发汗则寒栗，不能自还。", "19024": "厥，脉紧，不可发汗，发汗则声乱，咽嘶舌萎，声不得前。", "19025": "辨可发汗脉证并治第十六", "19026": "夫病脉浮大，问病者，言但便鞕尔，设利者，为大逆。鞕为实，汗出而解。何以故？脉浮，当以汗解。", "19027": "辨发汗后病脉证并治第十七", "19028": "病胸上诸实，胸中郁郁而痛，不能食，欲使人按之，而反有涎唾，下利日十余行，其脉反迟，寸口脉微滑，此可吐之，吐之利则止。", "19029": "病人手足厥冷，脉乍结，以客气在胸中。心下满而烦，欲食不能食者，病在胸中，当吐之。", "19030": "辨不可下病脉证并治第二十", "19031": "脉濡而弱，弱反在关，濡反在巅，微反在上，濇反在下。微则阳气不足，濇则无血。阳气反微，中风、汗出而反躁烦；濇则无血，厥而且寒。阳微不可下，下之则心下痞鞕。", "19032": "诸外实者，不可下。下之则发微热，亡脉厥者，当脐握热。", "19033": "脉濡而弱，弱反在关，濡反在巅，弦反在上，微反在下。弦为阳运，微为阴寒。上实下虚，意欲得温。微弦为虚，虚者不可下也。", "19034": "脉濡而弱，弱反在关，濡反在巅，浮反在上，数反在下。浮为阳虚，数为无血，浮为虚，数为热。浮为虚，自汗出而恶寒；数为痛，振寒而栗。微弱在关，胸下为急，喘汗而不得呼吸，呼吸之中，痛在于胁，振寒相抟，形如疟状，医反下之，故令脉数、发热，狂走见鬼，心下为痞，小便淋沥，小腹甚鞕，小便则尿血也。", "19035": "脉濡而紧，濡则卫气微，紧则荣中寒。阳微卫中风，发热而恶寒；荣紧胃气冷，微呕心内烦。医为有大热，解肌而发汗，亡阳虚烦躁，心下苦痞坚。表里俱虚竭，卒起而头眩。客热在皮肤，怅怏不得眠。不知胃气冷，紧寒在关元。技巧无所施，汲水灌其身。客热应时罢，栗栗而振寒。重被而覆之，汗出而冒巅。体惕而又振，小便为微难。寒气因水发，清谷不容间。呕变反肠出，颠倒不得安。手足为微逆，身冷而内烦。迟欲从后救，安可复追还。", "19036": "脉浮而大，浮为气实，大为血虚。血虚为无阴，孤阳独下阴部者，小便当赤而难，胞中当虚，今反小便利而大汗出，法应卫家当微，今反更实，津液四射，荣竭血尽，干烦而不得眠，血薄肉消，而成暴液。医复以毒药攻其胃，此为重虚，客阳去有期，必下如污埿而死。", "19037": "脉数者，久数不止，止则邪结正气不能复，正气却结于藏，故邪气浮之，与皮毛相得。脉数者，不可下，下之则必烦，利不止。", "19038": "脉浮大，应发汗，医反下之，此为大逆。", "19039": "伤寒，脉阴阳俱紧，恶寒发热，则脉欲厥。厥者，脉初来大，渐渐小，更来渐渐大，是其候也。如此者恶寒，甚者翕翕汗出，喉中痛；热多者，目赤脉多，睛不慧，医复发之，咽中则伤；若复下之，则两目闭，寒多者便清谷，热多者便脓血；若熏之，则身发黄；若熨之，则咽燥。若小便利者，可救之；小便难者，为危殆。", "19040": "伤寒发热，口中勃勃气出，头痛目黄，衄不可制，贪水者必呕，恶水者厥。若下之，咽中生疮，假令手足温者，必下重便脓血。头痛目黄者，若下之，则两目闭。贪水者，脉必厥，其声嘤，咽喉塞；若发汗，则战栗，阴阳俱虚。恶水者，若下之，则里冷不嗜食，大便完谷出；若发汗，则口中伤，舌上白胎，烦躁，脉数实，不大便，六七日后必便血；若发汗，则小便自利也。", "19041": "下利脉大者，虚也，以其强下之故也。设脉浮革，因尔肠鸣者，属当归四逆汤主之。", "19042": "辨可下病脉证并治第二十一", "19043": "下利，三部脉皆平，按之心下鞕者，急下之，宜大承气汤。", "19044": "下利，脉迟而滑者，内实也。利未欲止，当下之，宜大承气汤。", "19045": "问曰：人病有宿食，何以别之？师曰：寸口脉浮而大，按之反濇，尺中亦微而濇，故知有宿食，当下之，宜大承气汤。", "19046": "下利，脉反滑，当有所去，下之乃愈，宜大承气汤。", "19047": "伤寒后脉沈，沈者，内实也，下解之，宜大柴胡汤。", "19048": "脉双弦而迟者，必心下鞕。脉大而紧者，阳中有阴也，可以下之，宜大承气汤。", "19049": "辨发汗吐下后脉证并治第二十二", "19050": "一气之块然乎太虚之间也。氤氲摩荡，以生生万物。而其禀之驳者，为禽兽，为草木；粹者为人。而其粹者，亦有厚薄强弱之不同，加之六气沴乎外，七情侵乎内，而诸疾生焉。有寒有热，有表有里，千状万证，不可俱述。而要之不过虚实两者之间焉。故经曰：虚则补，实则泻。呜呼！虚实者，诊病之标的，而补泻者，施治之大要也哉！长沙以还，明哲辈出，家擅专门，人立异见。诸说旁舞，多歧亡羊。至若张戴人、薛立斋之学之术，可谓百世之宗师矣。而究其设施之方，则戴人偏于泻，而立斋偏于补。既有所偏，则不能无弊。苟不能无弊，则又不可无辨焉！予窃为二君之术，一补一泻，虽有不同，而各极其至，庶乎圣之功，亦莫以加焉。然天下之病，未必尽实，则其偏于泻也，吾恐虚者之反受其害也；未必尽虚，则其偏于补也，吾恐实者之亦反受其害也。一得一失，明于此而暗于彼，此岂斯道之大成哉！若长沙则不然，可以补则补，而不偏于补；可以泻则泻，而不偏于泻。虚实随证，补泻应机，呜呼！亦可谓大成矣。拟诸古之圣贤，二君之于长沙，犹夷惠之于孔子也。盖补泻之不可偏废，犹裘葛之不可一施也。而今不核虚与实，而致补泻之各偏，犹不审冬夏之异候，而欲偏裘葛之御也，岂其理也哉。故曰：少阴病下利清谷，里寒外热者，通脉四逆汤主之。又曰：少阴病，自利清水，色纯青者，宜大承气汤。补泻不可偏废也，可见矣。方今之世，好补而恶泻，喜温而畏寒，大黄芒硝，视如蛇蝎；干姜附子，甘如饴蜜。遇硝黄奏效，则曰：此惟取一时之快，后必致寒中之患。姜附错投，则曰：姜附犹不验，归之于命。盖亦不思之甚也。故凡治疗之书，偏于补者，盛行于世，而梨枣日广，至于戴人此书，传诵甚罕，予窃童蒙学医者，呫哗偏补之书，而不讲泻实之方，则虚虚实实，其弊将有不可胜言者。乃鸠工寿梓，以广其传。惟冀此书，与立斋之书，并行于世，可以泻则师戴人，可以补则师立斋，无致补泻之偏胜，使斯民同跻于仁寿之域矣！", "19051": "夫风之为状，善行而数变。《内经》曰：诸风掉眩，皆属肝木。掉摇眩运，非风木之象乎？纡曲劲直，非风木之象乎？手足掣颤，斜目㖞口，筋急挛搐，瘛疭惊痫，发作无时，角弓反张，甚则吐沫，或泣或歌，喜怒失常，顿僵暴仆，昏不知人，兹又非风木之象乎？故善行而数变者，皆是厥阴肝之用也。夫肝木所以自甚而至此者，非独风为然。盖肺金为心火所制，不能胜木故也。此病之作，多发于每年十二月，大寒中气之后，及三月四月之交，九月十月之交。何以言之？大寒中气之后，厥阴为主气，巳亥之月，亦属厥阴用事之月，皆风主之时也。故三月四月之交，多疾风暴雨。振拉摧拔，其化为冰雹。九月十月之交，多落木发屋之变。故风木郁极甚者，必待此三时而作。凡风病之人，其脉状如弓弦而有力，岂敢以热药投之，更增其势哉！", "19052": "夫痹之为状，麻木不仁，以风湿寒三气合而成之。故《内经》曰：风气胜者为行痹。风则阳受之，故其痹行，旦剧而夜静。世俗莫知，反呼为走注疼痛虎咬之疾。寒气胜者为痛痹。寒则阴受之，故其痹痛，旦静而夜剧。世俗不知，反呼为鬼忤。湿气胜者为著痹。湿胜则筋脉皮肉受之，故其痹著而不去，肌肉削而著骨。世俗不知，反呼为偏枯。此疾之作，多在四时阴雨之时，及三月九月，太阳寒水用事之月。故草枯水寒为甚，或濒水之地，劳力之人，辛苦失度，触冒风雨，寝处津湿，痹从外入。况五方七地，寒暑殊气，刚柔异禀，饮食起居，莫不相戾。故所受之邪，各有浅深。或痛或不痛，或仁或不仁，或筋屈而不能伸，或引而不缩。寒则虫行，热则纵缓，不相乱也。皮痹不已，而成肉痹。肉痹不已，而成脉痹；脉痹不已，而成筋痹；筋痹不已，而成骨痹；久而不已，内舍其合。若脏腑俱病，虽有智者，不能善图也。凡病痹之人，其脉沉涩。", "19053": "今人论方者，见诸痹证，遽作脚气治之，岂知《内经》中本无脚气之说。或曰：诸方亦有脚气统论，又有脚气方药，若止取《素问》，则诸方皆非耶！曰：痹病以湿热为源，风寒为兼，三气合而为痹。奈何治此者，不问经络，不分脏腑，不辨表里，便作寒湿脚气，乌之附之，乳之没之，种种燥热攻之；中脘灸之，脐下烧之，三里火之，蒸之熨之，汤之炕之。以至便旋涩滞，前后俱闭，虚燥转甚，肌肤日削，食饮不入，邪气外侵，虽遇扁、华，亦难措手。若此者何哉？胸膈间有寒痰之故也。痹病本不死，死者医之误也。虽亦用蒸之法，必先涌去其寒痰，然后诸法皆效。《内经》曰：五脏有俞穴，六腑有合穴。循脉之本分，各有所发之源，以砭石补之，则痹病瘳。此其《内经》中明白具载，如之何不读也？陈下酒监魏德新，因赴冬选，犯寒而行。真气元衰，加之坐卧冷湿，食饮失节，以冬遇此，遂作骨痹。骨属肾也。腰之高骨坏而不用，两胯似折，面黑如炭，前后廉痛，痿厥嗜卧。遍问诸医，皆作肾虚治之。余先以玲珑灶熨蒸数日，次以苦剂，上涌讫，寒痰三、二升。下虚上实，明可见矣。次以淡剂，使白术除脾湿，令茯苓养肾水，责官桂伐风木。寒气偏胜，则加姜、附，否则不加。又刺肾俞、太谿二穴，二日一刺。前后一月，平复如故。仆尝用治伤寒汗、下、吐三法，移为治风痹痿厥之法，愈者多矣。", "19054": "痿之为状，两足痿弱，不能行用。由肾水不能胜心火，心火上烁肺金。肺金受火制，六叶皆焦，皮毛虚弱，急而薄著，则生痿躄。躄者，足不能伸而行也。肾水者，乃肺金之子也。令肾水衰少，随火上炎。肾主两足，故骨髓衰竭，由使内太过而致。然《至真要大论》云诸痿喘呕皆属于上者，上焦也。三焦者，手少阳相火也。痿、喘、呕三病，皆在膈上，属肺金之部分也。故肌痹传为脉痿；湿痹不仁，传为肉痿；髓竭足躄，传为骨痿；房室太过为筋痿，传为白淫。大抵痿之为病，皆因客热而成，好以贪色，强力过极，渐成痿疾。故痿躄属肺，脉痿属心，筋痿属肝，肉痿属脾，骨痿属肾。总因肺受火热，叶焦之故，相传于四脏，痿病成矣。直断曰痿病无寒。故痿之作也，五月、六月、七月，皆其时也。午者，少阴君火之位；未者，湿土庚金伏火之地；申者，少阳相火之分。故痿发此三月之内，以为热也。故病痿之人，其脉浮而大。", "19055": "今之行药者，凡见脚膝痿弱，难于行步，或一足不伸，便作寒湿脚气治之，骤用乌、附、乳、没、自然铜、威灵仙之类，燔针、艾火，汤煮、袋蒸，痿弱转加，如此而死，岂亦天乎！夫治痿与治痹，其治颇异。风寒湿痹，犹可蒸汤灸燔，时或一效。惟痿用之转甚者，何也？盖以痿，肺热为本，叶焦而成痿，以此传于五脏，岂有寒者欤？若痿作寒治，是不刃而杀之也。夫痿病不死，死者用药之误也。陈下一武弁宋子玉，因驻军息城，五、六月间，暴得痿病，腰胯两足，皆不任用，躄而不行，求治于予。察其两手，脉俱滑之而有力。予凭《内经》火淫于内，治以咸寒，以盐水越其膈间寒热宿痰。新者为热，旧者为寒。或宿食宿饮在上脘者，皆可涌之。宿痰既尽，因而下之。节次数十行，觉神志日清，饮食日美，两足渐举，脚膝渐伸。心降肾升，便继以黄连解毒汤，加当归等药，及泻心汤、凉膈散、柴胡饮子，大作剂煎，时时呷之。《经》曰：治心肺之病最近，用药剂不厌频而少；治肾肝之病最远，用药剂不厌顿而多。此法人皆怪之。", "19056": "然余治痿，寻常用之，如拾遗物。予若以此诳人，其如获罪于天何？此宋子玉之证，所以不得不书也，且示信于来世。故《内经》谓治痿之法，独取阳明经。阳明经者，胃脉也，五脏六腑之海也，主润养宗筋。宗筋主束骨。束骨在脐下阴毛际上是也。又主大利机关。机关者，身中大关节也，以司曲伸。是以阳明虚则宗脉纵，宗脉纵则大脉不伸，两足痿弱。然取阳明者，胃脉也。胃为水谷之海，人之四季，以胃气为本。本固则精化，精化则髓充，髓充则足能履也。《阴阳应象论》曰：形不足者，温之以气；精不足者，补之以味。味者，五味也。五味调和，则可补精益气也。五味、五谷、五菜、五果、五肉，五味贵和，不可偏胜。又曰：恬憺虚无，真气从之，精神内守，病安从来？若用金石草木补之者，必久而增气，物化之常，气增而久，夭之由也。所以久服黄连、苦参者，而反化为热，久服热药之人，可不为寒心哉？余尝用汗、下、吐三法，治风痹痿厥，以其得效者众，其敢诬于后人乎！", "19057": "厥亦有令人腹暴满不知人者，或一、二日稍知人者，或卒然闷乱无觉知者。皆因邪气乱，阳气逆，是少阴肾脉不至也。肾气微少，精血奔逸，使气促迫，上入胸膈，宗气反结心下，阳气退下，热归阴股，与阴相助，令身不仁，又五络皆会于耳中，五络俱绝，则令人身脉皆动，而形体皆无所知，其状如尸，故曰尸厥。有涎如拽锯声在喉咽中为痰厥；手足搐搦者为风厥；因醉而得之为酒厥；暴怒而得之为气厥；骨痛爪枯为骨厥；两足指挛急，屈伸不得，爪甲枯结为臂厥；身强直如椽者为肝厥；喘而啘者，狂走攀登为阳明厥，皆气逆之所为也。", "19058": "今人见兹厥者，皆谓之⿰豆及著掠著，此是何等语也？非徒其名之谬，因其名之谬，而乖其实也。既言⿰豆及著、中著、掠著，必归之风，此清心、灵宝、至宝，又为先驱矣！鼻中嗅药，身上焫火。岂知厥之为病，如前所说者耶？顷西华季政之病寒厥，其妻病热厥，前后十余年。其妻服逍遥十余剂，终无寸效。一日，命余诊之，二人脉皆浮大而无力。政之曰：「吾手足之寒，时时渍以热汤，渍而不能止。吾妇手足之热，终日以冷水沃而不能已者，何也？」余曰：「寒热之厥也，此皆得之贪饮食，纵嗜欲。遂出《内经·厥论》证之。」政之喜曰：「《内经》真圣书也！十余年之疑，今而释然，纵不服药，逾过半矣。」仆曰：热厥者，寒在上也。寒厥者，热在上也。寒在上者，以温剂补肺金；热在上者，以凉剂清心火。分处二药，令服之不辍。不旬日，政之诣门谢曰：寒热之厥皆愈矣。其妻当不过数月而有娠，何哉？阴阳皆和故也。凡尸厥、痿厥、风厥、气厥、酒厥，可一涌而醒，次服降心火，益肾水，通血和气之药，使粥食调养，无不瘥者。若其余诸厥，仿此行之，慎勿当疑似之间，便作风气，相去邈矣。", "19059": "予尝见世医，用升麻、五积解利、伤寒、温疫等病，往往发狂谵语，衄血泄血，喘满昏瞀，懊𢙐闷乱，劳复。此数证，非伤寒便有此状，皆由辛温之剂，解之不愈，而热增剧，以致然也。凡解利、伤寒、时气疫疾，当先推天地寒暑之理，以人参之。南陲之地多热，宜辛凉之剂解之；朔方之地多寒，宜辛温之剂解之；午未之月多暑，宜辛凉解之；子丑之月多冻，宜辛温解之；少壮气实之人，宜辛凉解之；老耆气衰之人，宜辛温解之；病人因冒寒、食冷而得者，宜辛温解之；因役劳、冒暑而得者，宜辛凉解之；病人禀性怒急者，可辛凉解之；病人禀性和缓者，可辛温解之；病人两手脉浮大者，可辛凉解之；两手脉迟缓者，可辛温解之。如是之病，不可一概而用。偏热寒凉及与辛温，皆不知变通者。夫地有南北，时有寒暑，人有衰旺，脉有浮沉，剂有温凉，服有多少，不可差玄。病人禁忌，不可不知。", "19060": "以予论之，凡伤寒之气有六禁。初病之时，甚似中酒伤食者，禁大下之，一禁也；当汗之时，宜详时之寒暑，用衾衣之厚薄，禁沐浴之火炕重被、热粥燔针，二禁也；当汗之时，宜详解脉之迟数，用辛凉之剂，禁妄用热药，三禁也；当下之时，宜审详证下之药，禁巴豆、银粉丸方，四禁也；远来之病人，禁车载马驮，五禁也；大汗之后，禁杂食嗜欲，忧思作劳，六禁也。故凡有此者，宜清房凉榻，使不受客热之邪；明窗皓室，使易见斑出黄生之变。病者喜食凉，则从其凉；喜食温，则从其温。清之而勿扰，休之而勿劳。可辛温则辛温解之，可辛凉则辛凉解之。所察甚微，无拘彼此。欲水之人，慎勿禁水。但饮之后，频与按摩其腹，则心下自动。若按摩其中脘，久则必痛。病人获痛，复若有水结，则不敢按矣。止当禁而不禁者，轻者危，重则死；不当禁而禁者，亦然。今之士大夫，多为俗论。先锢其心，虽有正论，不得而入矣。昔陆象先尝云：天下本无事，庸人扰之为烦耳！余亦曰：正气本不乱，庸医扰之为剧耳！", "19061": "凡治者，轻者，因而扬之，重者，因而减之。《内经》曰：少阳客胜则丹疹外发，及为丹熛。手少阳者，三焦少阳相火也。启玄子云：是五寅五申之岁，即少阳相火司天故也，他岁亦有之。但《内经》独明疮疹者，少阳相火之所为也。俗呼曰斑疹伤寒，此言却有理。为此证时，与伤寒相兼而行，必先发热恶寒，头项痛，腰脊强，从太阳传至四、五日，熛疹始发，先从两胁下有之，出于胁肋，次及身表，渐及四肢，故凡小儿疮疱、丹熛、瘾疹，皆少阳相火客气胜也。《内经》曰：诸痛痒疮疡，皆属心火。岂有寒乎？故治疮疱，与治伤寒时气同法。初觉头痛，身热恶寒，此小儿初发疮疱之候也。其脉息皆浮大而有力，亦与伤寒、时气、冒风、惊风、宿乳，一概难辨。", "19062": "君子非好与昔人辨以要誉也。盖昔人有一误，流为千百世之祸者，苟不证其非，虽曰谦让，其如人命何？如精选《圣惠方》二十三卷，论妇人赤白带下云：妇人带下者，由劳神过度，损动经血，致令身虚，受于风冷，风冷入于脬络，传其血之所成也。又有巢氏内篇四十四卷，论任脉为经之海。其任之为病，女子则为带下。手太阳为小肠之经也，手少阴为心之经也。心为藏，主于里；小肠为腑，主于表。二经之血，在于妇人，上为乳汁，下为月水，冲任之所统也。冲任之脉，既起于脬内，阴阳过度，则伤脬络。故风邪乘虚而入于脬中，损冲任之经，伤太阳少阳之血，致令脬络之间，秽与血相兼带而下，冷则多白，热则多赤，二家之说皆非也。", "19063": "夫治病当先识经络。《灵枢》十二经中，有「是动之病」，有「所生之病」。大经有十二，奇经有八脉。言十二经之外，复有此八道经脉也。十二经与八道经脉，通身往来。经络共二十道，上下流走，相贯周环，昼夜不息，与天同度。自手太阴肺经起，行阳二十五度，行阴亦二十五度，复会于手太阴肺经也。然此二十道经络，上下周流者，止一十九道耳。惟带脉起少腹侧季胁之端，乃章门穴是也，环身一周，无上下之源，络脬而过，如束带之于身。《难经》曰：带之为病，溶溶如坐水中。冲任者，是经脉之海也，循腹胁，夹脐傍，传流于气冲，属于带脉，络于督脉。督脉者，起于关元穴；任脉者，女子在养胎孕之所。督脉乃是督领妇人经脉之海也。冲、任、督三脉，同起而异行，一源而三歧，皆络带脉。冲、任、督三脉，皆统于篡户，巡阴器，行廷孔、溺孔上端。冲、任、督三脉，以带脉束之。", "19064": "因余经上下往来，遗热于带脉之间。热者，血也。血积多日不流，火则从金之化，金曰从革而为白，乘少腹间冤热，白物滑溢，随溲而下，绵绵不绝，多不痛也。或有痛者则壅碍，因壅而成痛也。《内经》曰：少腹冤热，溲出白液。冤者，屈滞也，病非本经，为他经冤抑而成此疾也。冤，一作客。客，犹寄也。遗客热于少腹，久不去，从金化而为白。设若赤白痢，赤者，新积也，从心火；白者，旧积也，从肺金。故赤白痢，不可曲分寒热，止可分新旧而治之。假如痈疖，始赤血，次溃白脓，又岂为寒者哉？而病者未信也，此今之刘河间常言之矣！皆云寒多则白，以干姜、赤石脂、桃花丸治痢，虽愈，后必生血疾。如白带下病，径以白芍药、干姜，白带虽愈，则小溲必不利。治泻痢与治带下，皆不可骤用峻热之药燥之。燥之则内水涸，内水涸则必烦渴，烦渴则小溲不利，小溲不利则足肿面浮，渐至不治。", "19065": "《内经》曰：思想无穷，所愿不得，意淫于外，入房太甚，发为筋痿。淫衍白物，如精之状，男子因溲而下，女子绵绵而下。《左传》曰：少男惑长女，风落山之象，是为惑蛊之疾。其文三虫同皿曰蛊。乃是思慕色欲，内生后蚀，甚不可便用燥热之药攻之。渐至形削羸瘦脉大者，必死而不救。且赤白痢者，是邪热传于大肠，下广肠出赤白也。带下者，传于小肠，入脬经下赤白也。据此二证，皆可同治湿法治之。先以导水、禹功泻讫，次以淡剂降心火，益肾水，下小溲，分水道，则自愈矣。", "19066": "顷顿丘一妇人，病带下连绵不绝，白物或来，已三载矣，命予脉之。诊其两手脉，俱滑大而有力，得六、七至，常上热口干眩运，时呕醋水。余知其实有寒痰在胸中，以瓜蒂散吐讫冷痰三、二升，皆醋水也，间如黄涎，状如烂胶；次以浆粥养其胃气；又次用导水、禹功，以泻其下；然后以淡剂渗泄之药，利其水道，不数日而愈。", "19067": "余实悟《内经》中所云：上有病，下取之；下有病，上取之。又：上者下之，下者上之。然有此法，亦不可偏执，更宜详其虚实而用之。故知精选《圣惠方》带下风寒之言，与巢氏论中赤热白寒之说，正与《难》、《素》相违。予非敢妄论先贤，恐后学混而不明，未免从之而行也。如其寡学之人，不察病人脉息，不究病人经脉，妄断寒热，信用群方暴热之药，一旦有失，虽悔何追？呜呼！人命一失，其复能生乎？赤白痢与赤白带下，皆不死人。《内经》惟肠澼便血，血温身热者，死。赤白带下，白液白物，蛊病肾消，皆不能死人。有死者，药之误也。", "19068": "巢氏，先贤也，固不当非。然其说有误者，人命所系，不可不辨也。今之医者，家置本以为绳墨。呜呼！何今之人信巢氏，而不信《素问》也？此，予不得不为之说。且巢氏论霍乱、吐泻，皆由温凉不调，阴阳清浊，二气相干，致肠胃之间，变而为霍乱。寒气客于脾则泻，寒气客于胃则吐。亦由饮酒食肉，腥脍生冷过度；或因居处坐卧湿地，当风取凉，风之气归于三焦，传于脾胃，脾胃得冷，水谷不消，皆成霍乱。其名有三：一曰胃反，胃气虚逆，反吐饮食；二曰霍乱，言其病挥霍之间，便致撩乱也；三曰晡食变逆者也。霍乱者，脉必代。又云：七月间食蜜，令人暴下霍乱。此皆巢氏霍乱之论也。", "19069": "故目暴赤肿起，羞明隐涩，泪出不止，暴寒目瞒，皆工艺之所为也。夫目之五轮，乃五脏六腑之精华，宗脉之所聚。其气轮属肺金，肉轮属脾土，赤脉属心火，黑水、神光属肾水，兼属肝木，此世俗皆知之矣。及有目疾，则又不知病之理，岂知目不因火则不病。何以言之？气轮变赤，火乘肺也；肉轮赤肿，火乘脾也；黑水神光被翳，火乘肝与肾也；赤脉贯目，火自甚也。能治火者，一句可了。故《内经》曰：热胜则肿。", "19070": "世俗云：「热汤沃眼十日明。」此言谬之久矣！火方乘目，更以热汤沃之，两热相搏，是犹投贼以刃也。岂知凉水沃之，暂涩而久滑；热水沃之，暂滑而久涩。不然，曷以病目者忌沐浴？或曰：世俗皆言凉水沃眼，血脉不行。余闻大笑之。眼药中用黄连、硼砂、朴硝、龙脑、熊胆之属，皆使人血脉不行耶？何谬之甚也。又若头风之甚者，久则目昏，偏头风者，少阳相火也，久则目束小。大肠闭涩者，目必昏，何也？久病滑泄者，目皆明，惟小儿利久，反疳眼昏。盖极则反，与此稍异，其余皆宜出血而大下之。余尝病目赤，或肿或翳，作止无时，偶至亲息帅府间，病目百余日，羞明隐涩，肿痛不已。忽眼科姜仲安云：宜上星至百会，速以䤵针刺四、五十刺，攒竹穴、丝竹穴上兼眉际一十刺，反鼻两孔内，以草茎弹之出血。三处出血如泉，约二升许，来日愈大半，三日平复如故。余自叹曰：百日之苦，一朝而解，学医半世，尚缺此法，不学可乎？惟小儿疮疱入眼者，乃余热不散耳。止宜降心火，泻肝风，益肾水，则愈矣。若大人目暴病者，宜汗、下、吐。以其血在表，故宜汗；以其火在上，故宜吐；以其热在中，故宜下。出血之与发汗，名虽异而实同，故录《铜人》中五穴照用。", "19071": "《语》云：子之所慎，齐、战、疾。又曰：丘未达，不敢尝。此言服药不可不畏慎也。然世有百十年相袭之弊，至今不除者，敢略数一、二，使后车改辙，不蹈前覆。夫伤寒、温疫、时气、中暑、风温、风疟，与中酒伤食者，其初相类，此最误人。或先一日头痛，曾伤酒便归过于洒，曾伤食便归过于食。初觉满闷，医者不察其脉，不言其始，径用备急丹、缠积丹、软金丸、酒症丸。此药犯巴豆，或出油不尽，大热大毒，走泄五、七行，或十余行。其人必津液枯涸，肠胃转燥，发黄瘀热，目赤口干，恍惚潮热，昏愦惑狂，诸热交作。如此误死者，不可胜举。若其人或本因酒食致过，亦能头痛身热，战栗恶寒。医者不察其脉，不究其原，反作伤寒发之，桂枝、麻黄、升麻之属，以汗解之。汗而不解，辗转疑惑，反生他证。如此误死者，可胜计哉？", "19072": "又如妇人产余之疾，皆是败血恶物，发作寒热，脐腹撮痛，乳潼枯涸，食饮稍减。医者不察，便谓产后血出数斗，气血俱虚，便用温热之剂，养血补虚，止作寒治，举世皆然。岂知妇人之孕，如天地之孕物也。物以阴阳和合而后生，人亦以阴阳和合而后孕。偏阴偏阳，岂有孕乎？此与禾黍、瓜果之属何异哉？若水旱不时，则华之与实，俱痿落矣。此又与孕而不育者，复何异哉？七月立秋后十八日，寸草不结者，犹天寒故也。今妇人妊娠，终十月无难而生，反谓之寒，何不察其理之甚也？窃譬之冶砖者，炎火在下，以水沃其窑之巅，遂成砖矣。砖既出窑，窑顿寒邪！世俗竟传黑神散之属，治产后一十八证，非徒其不愈，则经脉涸闭，前后淋闭，呕吐嗽痰，凡百热证生矣。若此误死者，不可计之。曷若四物汤与凉膈散停对，大作汤剂而下之，利以数行，恶物俱尽，后服淡甘之剂自愈矣。", "19073": "又有一妇，病风痫，从六、七岁因惊风得之。自后三、二年，间一、二作，至五、七年，五、七作，逮三十余岁至四十岁，日作或一日十余作，以至昏痴健忘，求死而已。会兴定岁大饥，遂采百草而食，于水濒采一种草，状若葱属，泡蒸而食之。食讫，向五更觉心中不安，吐涎如胶，连日不止，约一、二斗，汗出如洗，初昏困，后三日，轻健非曩之比，病去食进，百脉皆和。省其所食，不知何物。访问诸人，乃憨葱苗也。憨葱苗者，《本草》所谓藜芦苗是也。《图经》云：藜芦苗吐风病。此亦偶得吐法耳！又有一妇，年三十余，病滑泄经年。皆云虚中有积，以无忧散，五、七日一服，至二十服不效。又服缠积丹、软金丸诸药，皆不效。其人服药愈速，病势愈甚，食饮日减。人或谓曰：「此休息痢也。」宜灸中脘及左右穴，脐下气海及膀胱穴，以三里引之，每年当冬至日夏至日灸之。前后仅万余壮。忽门外或者曰：「此病我屡谙，盖大伤饮之故。即目桃花正开，俟其落时，以长棘针刺之，得数十萼，勿犯人手，以白面和作饼子，文武火烧令熟，嚼烂，以米饮汤下之。」病人如其言服之。不一、二时，泻如倾，前后泻六、七日，仅数百行，昏困无所知觉，惟索冷水，徐徐而饮。至六、七日，少省。尔后食日进，神日昌，气血日和。不数年，生二子。此人本不知桃花萼有取积之神效，亦偶得泻法耳！", "19074": "余之所以屡书此者，叹知音之难遇也。近者，余之故人某官，不欲斥言其名，因病头项强，状类伤寒，服通圣散，虽不得其法，犹无害也，医者见其因通圣散也，立毁其非仲景之药也。渠不察其热已甚矣，复以辛热发之。汗出不解，发黄血泄，竟如前所言。后虽以承气下之，不能已。又复下之，至绝汗出，其脉犹搏击。然余亲见其子，言之甚详。至今士大夫，皆不知辛热一发之过也，独归罪于通圣散。呜呼！甚矣，道之难明也！", "19075": "夫病之一物，非人身素有之也。或自外而入，或由内而生，皆邪气也。邪气加诸身，速攻之可也，速去之可也，揽而留之，何也？虽愚夫愚妇，皆知其不可也。及其闻攻则不悦，闻补则乐之。今之医者曰：「当先固其元气，元气实，邪自去。」世间如此妄人，何其多也！夫邪之中人，轻则传久而自尽，颇甚则传久而难已，更甚则暴死。若先论固其元气，以补剂补之，真气未胜，而邪已交驰横骛而不可制矣。惟脉脱、下虚、无邪、无积之人，始可议补；其余有邪积之人而议补者，皆鲧湮洪水之徒也。今予论吐、汗、下三法，先论攻其邪，邪去而元气自复也。况予所论之法，谙练日久，至精至熟，有得无失，所以敢为来者言也。", "19076": "故凡可吐，令条达者，非徒木郁然。凡在上者，皆宜吐之。且仲景之论，胸上诸实郁，而痛不能愈，使人按之，及有涎唾，下痢十余行，其脉沉迟，寸口脉微滑者，此可吐之，吐之则止。仲景所谓胸上诸实，按之及有涎唾者，皆邪气在上也。《内经》曰：下痢，脉迟而滑者，内实也；寸口脉微滑者，上实也。皆可吐之。王冰曰：上盛不已，吐而夺之。仲景曰：宿食在上脘，当吐之。又如宿饮酒积在上脘者，亦当吐之。在中脘者，当下而去之。仲景曰：病人手足厥冷，两手脉乍结，以客气在胸中，心下满而烦，欲食不能食者，知病在胸中，当吐之。余尝用吐方，皆是仲景方，用瓜蒂散，吐伤寒头痛；用葱根白豆豉汤，以吐杂病头痛；或单瓜蒂名独圣，加茶末少许，以吐痰饮食；加全蝎梢，以吐两胁肋刺痛、濯濯水声者。《内经》所谓「湿在上，以苦吐之」者，其是谓欤！", "19077": "设若飧泄不止，日夜无度，完谷下出，发汗可也。《内经》曰：春伤于风，夏生飧泄。此以风为根，风非汗不出。昔有人病此者，腹中雷鸣泄注，水谷不分，小便涩滞，皆曰脾胃虚寒故耳。豆蔻、乌梅、罂粟壳、干姜、附子，曾无一效；中脘脐下，灸已数十，燥热转甚，小溲涸竭，瘦削无力，饮食减少。命予视之，余以谓《应象论》曰：热气在下，水谷不分，化生飧泄；寒气在上，则生䐜胀。而气不散，何也；阴静而阳动故也。诊其两手脉息，俱浮大而长，身表微热。用桂枝麻黄汤，以姜枣煎，大剂，连进三服，汗出终日，至旦而愈。次以胃风汤，和平脏腑，调养阴阳，食进病愈。", "19078": "顷又治一狂人，阴不胜其阳，则脉流薄疾，阳并乃狂。《难经》曰：重阳者狂，重阴者癫。阳为腑，阴为脏，非阳热而阴寒也。热并于阳则狂，狂则生寒；并于阴则癫，癫则死。《内经》曰：足阳明胃实则狂。故登高而歌，弃衣而走，无所不为，是热之极也。以调胃承气，大作汤下数十行，三、五日，复上涌一、二升，三、五日又复下之，凡五、六十日，下百余行，吐亦七、八度，如吐时，暖室置火，以助其热而汗少解，数汗方平。", "19079": "又治一酒病人，头痛、身热、恶寒，状类伤寒，诊其脉，两手俱洪大，三两日不圊。余以防风通圣散约一两，用水一中碗，生姜二十余片，葱须根二十茎，豆豉一大撮，同煎三、五沸，去滓，稍热，分作二服，先服一服多半，须臾以钗股探引咽中，吐出宿酒，酒之香味尚然，约一两掬，头上汗出如洗，次服少半立愈。《内经》曰：火郁发之。发为汗之，令其疏散也。", "19080": "又尝治一税官，病风寒湿痹，腰脚沉重，浮肿，夜则痛甚，两足恶寒，经五、六月间，犹绵胫靴足。腰膝皮肤，少有跣露，则冷风袭之，流入经络，其痛转剧。走注上下，往来无定。其痛极处，便挛急而肿起，肉色不变，腠理间如虫行。每遇风冷，病必转增。饮食转减，肢体瘦乏，须人扶掖，犹能行立。所服者，乌、附、姜、桂，种种燥热；燔针著灸，莫知其数，前后三年，不获一愈。一日，命予脉之，其两手皆沉滑有力。先以导水丸、通经散各一服，是夜泻三十余行，痛减半。遂渐服赤茯苓汤、川芎汤、防风汤。此三方在《宣明论》中，治痹方是也。日三服，煎七、八钱，漐漐然汗出。余又作玲珑灶法熏蒸，血热病必增剧。诸汗法古方亦多有之，惟以吐发汗者，世罕知之。故余尝曰：吐法兼汗，良以此夫！", "19081": "或言：男子不可久泄，妇人不可久吐。何妄论之甚也？可吐则吐，可下则下，岂问男女乎？大人小儿，一切所伤之物在胃脘，如两手脉迟而滑者，内实也，宜下之。何以别乎？盖伤宿食者恶食，伤风者恶风，伤寒者恶寒，伤酒者恶酒，至易辨也。故凡宿食在胃脘，皆可下之，则三部脉平，若心下按之而硬满者，犹宜再下之。如伤寒大汗之后，重复劳发而为病者，盖下之后热气不尽故也，当再下之。若杂病腹中满痛不止者，此为内实也。《金匮要略》曰：痛而腹满，按之不痛为虚，痛者为实。《难经》曰：痛者为实，腹中满痛，里壅为实，故可下之。不计杂病、伤寒，皆宜急下之。宜大承气汤，或导水丸，或泄水丸等药，过十余行。如痛不已，亦可再服，痛已则止。至如伤寒大汗之后，发热，脉沉实，及寒热往来，时时有涎嗽者，宜大柴胡汤加当归煎服之，下三、五行，立愈。产后慎不可作诸虚不足治之，必变作骨蒸寒热，饮食不入，肌肤瘦削，经水不行。《经》曰：寒则衰饮食，热则消肌肉。人病瘦削，皆粗工以药消烁之故也。呜呼！人之死者，岂为命乎？《难经》曰：实实虚虚。损不足而益有余，如此死者，医杀之耳！", "19082": "余尝用前十余药，如身之使臂，臂之使手。然诸洞泄寒中者，不可下，俗谓休息痢也。伤寒脉浮者，不可下。表里俱虚者，不宜下。《内经》中五痞心证，不宜下。厥而唇青，手足冷，内热深者，宜下。寒者，不宜下，以脉别之。小儿内泻，转生慢惊，及两目直视，鱼口出气者，亦不宜下。若十二经败甚，亦不宜下，止宜调养，温以和之，如下则必误人病耳！若其余大积大聚，大病大秘，大涸大坚，下药乃补药也。余尝曰：泻法兼补法，良以此夫。", "19083": "余用补法则不然。取其气之偏胜者，其不胜者自平矣。医之道，损有余，乃所以补其不足也。余尝曰：吐中自有汗，下中自有补，岂不信然！余尝用补法，必观病人之可补者，然后补之。昔维阳府判赵显之，病虚羸，泄泻褐色，乃洞泄寒中证也。每闻大黄气味即注泄。余诊之，两手脉沉而软，令灸水分穴一百余壮，次服桂苓甘露散、胃风汤、白术丸等药，不数月而愈。又息城酒监赵进道，病腰痛，岁余不愈。诊其两手脉，沉实有力，以通经散下五、七行；次以杜仲去粗皮细切，炒断丝为细末，每服三钱；猪腰子一枚，薄批五、七片，先以椒盐淹去腥水，掺药在内，裹以荷叶，外以湿纸数重封，以文武火烧熟，临卧细嚼，以温酒送下；每旦以无比山药丸一服，数日而愈。又相台监酒岳成之，病虚滑泄，日夜不止，肠鸣而口疮，俗呼为心劳口疮，三年不愈。予以长流水，同姜枣煎五苓散五、七钱，空心使服之，以治其下；以宣黄连与白茯苓去皮，二味各等分为末，以白面糊为丸，食后温水下三、五十丸，以治其上，百日而愈。又汝南节度副使完颜君宝，病脏毒，下衃血发渴，寒热往来，延及六载，日渐瘦弱无力，面黄如染。余诊其两手脉沉，而身凉。《内经》寒以为荣气在，故生，可治。先以七宣丸下五、七行；次以黄连解毒汤加当归赤芍药，与地榆散同煎服之，一月而愈。", "19084": "余尝治此证，未尝用世俗之药。非故与世参商，方凿圆枘，自然龃龉者。过颖，一长吏病此，命予疗之。目之斜，灸以承泣；口之㖞，灸以地仓，俱效。苟不效者，当灸人迎。夫气虚风入而为偏，上不得出，下不得泄，真气为风邪所陷，故宜灸。《内经》曰：陷下则灸之。正谓此也，所以立愈。又尝过东杞，一夫亦患此，予脉其两手，急数如弦之张，甚力而实。其人齿壮气充，与长吏不同，盖风火交胜。予调承气汤六两，以水四升，煎作三升，分四服，令稍热啜之，前后约泻四、五十行，去一、两盆，次以苦剂投之，解毒数服，以升降水火，不旬日而愈。《脉诀》云：热则生风。若此者，不可纯归其病于窗隙之间而得，亦风火素感而然也。盖火胜则制金，金衰则木茂，木茂则风生。若东杞之人，止可流湿润燥，大下之后，使加餐通郁为大。《灵枢》虽有马膏桂酒双涂之法，此但治其外耳，非治其内也。今人不知其本，欲以单服热水，强引而行之，未见其愈者也。向之用姜附、乌、桂、起石、硫黄之剂者，是耶？非耶？", "19085": "岂知诸疝，皆归肝经。其奈通流，归之小肠脬囊。夫膀胱水府，专司渗泄；小肠水道，专主通流。肾为少阴，总统二水，人之小溲，自胃入小肠，渗入膀胱。膀胱者，脬囊也，气化则水出茎端，此常道也，及其为疝，乃属足厥阴肝经。盖环阴器而上入小腹者，足厥阴肝经也。夫肝肾皆属于下，与冲、任、督相附，然《灵枢经》言：足厥阴肝经病，则有遗溺、癃闭、狐疝，主肾与膀胱、小肠三经，则不言疝，是受疝之处，乃肝之部分也。且《内经》男子宗筋，为束骨之会也。而肝主筋，睪者囊中之丸，虽主外肾，非厥阴环而引之，与玉茎无由伸缩。在女子则为篡户。其内外为二：其一曰廷孔，其二曰窈漏，此足厥阴与冲任督之所会也。《灵枢》言：足厥阴之经筋聚于阴器，其病伤于寒则阴缩入，伤于热则纵挺不收。治在行水清阴气。故阳明与太阴厥阴之筋，皆会于阴器，惟厥阴主筋，故为疝者，必本之厥阴。《灵枢》又言：足厥阴之别，名曰「蠡沟」，去内踝五寸，别走少阳，循胫上睪，结于茎。其病气逆、睪肿、卒疝，实则挺长，虚则暴痒，取之所别矣。岂非厥阴为受病之处耶？《灵枢》又言：邪在小肠，连睪系，属于肾，贯肝络肺，结心系。气盛厥逆，上冲肠胃，熏肝散于肓，结于脐。故取之肓原以散之，刺太阴以平之，取厥阴以下之，取巨虚下臁以去之，按其所过之经以调之。此其初，虽言邪在小肠，至其治法，必曰取厥阴以下之，乃知诸疝关于厥阴，可以无疑。以脉考之，《素问》云：厥阴滑，为狐疝；少阳滑，为肺风疝；太阴滑，为脾风疝；阳明滑，为心风疝；太阳滑，为肾风疝；少阴滑，为肝风疝。凡此六疝，虽见于他脉中，皆言风疝者，足厥阴肝经之气也。《灵枢》亦曰：心脉微滑，为心疝；肝脉滑甚，为溃癃；肾脉滑甚，为癃㿉。凡此三脏脉之疝，亦以滑为疝也。《素问》又云：脉大急，皆为疝。心脉滑，传为心疝；肺脉沉，传为肺疝。三阴急为疝，三阳急为瘕。王太仆云：太阳受寒，血凝为瘕；太阴受寒，气聚为疝。此言太阴受寒，传之肝经也。可以温药逐之，不可以温药补之。若补之者，是欲病去而强挽留之也。历考《素问》：三阳为病，发寒热，其传为𤻊疝。此亦言膀胱非受病之处，必传于厥阴部分，然后为疝也。又言病在少腹，腹痛，不得大小便，病名曰疝。得之寒，言脉急者曰疝瘕。少腹痛，凡言少腹者，岂非厥阴之部分耶？又言脾风传胃，名曰疝瘕。此谓非肝木不能为风气，名曰厥疝。盖脾土虚而不能制水，又为肝木所凌也。又言督脉为冲疝。盖厥阴与冲、任、督，俱会于前阴也。岂不明哉？至如运气中，又言岁太阳在泉，寒淫所胜，民病少腹控睪。盖寒客于小肠、膀胱，则肝木缩而不得伸行，母传之子也。阳明司天，燥淫所胜，丈夫𤻊疝，妇人少腹痛，此言肝气不得上行，为金所抑，鬼贼故也。又言太阴在泉，土胜则寒气逆满，食饮不下，甚则为疝。此亦言寒客太阴湿土，土不胜水，水传之肝经也。又尝遍阅《铜人》俞穴，亦相表里。如背上十三椎俞，肝经，言寒疝，腹部中行。惟阴交一穴，言寒疝，任脉之所发也；关元一穴，言暴疝，小肠之募，足三阴任脉之会也；中极一穴，言疝瘕，膀胱之募，亦足三阴任脉之会也；曲骨一穴，言㿉疝，任脉足厥阴之会也；其腹部第二行肓腧二穴，言寒疝，冲脉足少阴之会也；四病上穴，言疝瘕，冲任脉足少阴肾之会也；其腹部第三行大巨二穴，言㿉疝，足阳明脉气之所发也；气冲二穴，言𤻊疝，茎中痛，两丸寒痛，亦足阳明脉气之所发也；其腹部第四行府合二穴，言疝痛，足太阴厥阴阴维之交会也，亦太阴部三阴阳明之别也；冲门二穴，言阴疝，足太阴厥阴之会也；其在侧胁者，五枢二穴，言寒疝，阴邪上入少腹，带脉下三寸也。其在足六经者，足厥阴穴十名，言疝者七，谓大敦、行间、太冲、中封、蠡沟、中都、曲泉。足少阳穴十四名，言疝者一，谓丘墟穴也。足太阴穴十一名，言疝者一，谓阴陵泉也。足阳明穴十五名，言疝者一，谓阴市穴也。足少阴穴十名，言疝者五，谓然谷、大溪、照海、交信、筑宾也。足太阳穴十八名，言疝者二，谓金门、合阳也。由是言之，惟厥阴言疝独多，为疝之主也。其余经穴，虽亦治疝，终非受疝之地，但与足厥阴相连耳。或在泉寒胜，木气挛缩禁于此经；或司天燥胜，木气抑郁于此经；或忿怒悲哀，忧抑顿挫，结于此经；或药淋外固闭，尾缩精壅于此经。其病差别如此。", "19086": "《内经》曰：五实者死，五虚者亦死。夫五实者，谓五脏皆实也；五虚者，谓五脏皆虚也。腑病为阳，易治而鲜死；脏病为阴，难治而多死。《经》明言：脉盛，皮热，腹胀，前后不通，闷瞀者，五实也。脉盛为心，皮热为肺，腹胀为脾，前后不通为肾，闷瞀为肝，五脏皆实之证也。五虚者反是：脉细，皮寒，气少，泻利前后，饮食不入者，五虚也。脉细为心，皮寒为肺，气少为肝，泄利前后为肾，饮食不入为脾，此五脏皆虚之证也。夫五实为五脏俱太过，五虚为五脏俱不及。《内经》言此二证皆死，非谓必死也，谓不救则死，救之不得其道，亦死也。其下复言：将粥入胃则虚者活，身汗后利则实者活，此两证自是前二证之治法也。后人不知是治法，只作辨验生死之断句，直谓病人有此则生，无此则死。虚者听其浆粥自入胃，实者听其自汗自利，便委之死地，岂不谬哉？夫浆粥入胃而不注泄，则胃气和，胃气和则五虚皆实也，是以生也；汗以泄其表，利以泄其里，并泄则上下通，上下通则五实皆启矣，是以生也。此二证异常，却不宜用。班氏所谓有病不服药之言，盖其病大且笃故也。", "19087": "咽与喉，会厌与舌，此四者，同在一门，而其用各异。喉以候气，故喉气通于天；咽以咽物，故咽气通于地；会厌与喉，上下以司开合，食下则吸而掩，气上则呼而出，是以舌抵上腭，则会厌能闭其咽矣。四者相交为用，阙一则饮食废而死矣！此四者，乃气与食出入之门户最急之处。故《难经》言「七冲门」。而会厌之下为吸门，及其为病也，一言可了。一言者何？曰火。《内经》曰：一阴一阳结，谓之喉痹。王太仆注云：一阴者，手少阴君火，心主之脉气也；手少阳相火，三焦之脉气也。二火皆主脉，并络于喉。气热则内结，结甚则肿胀，肿胀甚则痹，痹甚而不通则死矣！", "19088": "病派之分，自巢氏始也。病失其本，亦自巢氏始也。何者？老子曰：少则得，多则惑。且俗谓噎食一证，在《内经》苦无多语，惟曰：三阳结，谓之膈。三阳者，谓大肠、小肠、膀胱也。结，谓结热也。小肠热结则血脉燥；大肠热结则后不圊；膀胱热结则津液涸。三阳既结则前后闭塞。下既不通，必反上行，此所以噎食不下，纵下而复出也。", "19089": "留饮，止证也，不过蓄水而已。王氏脉经中，派之为四：痰饮、悬饮、支饮、溢饮。《千金方》又派之为五饮，皆观病之形状而定名也。今予皆不论，此论饮之所得。其来有五：有愤郁而得之者，有困乏而得之者，有思虑而得之者，有痛饮而得之者，有热时伤冷而得之者。饮证虽多，无出于此。", "19090": "夫愤郁而不得伸，则肝气乘脾，脾气不化，故为留饮。肝主虑，久虑而不决，则饮气不行。脾主思，久思而不已，则脾结，故亦为留饮。人因劳役远来，乘困饮水，脾胃力衰，因而嗜卧，不能布散于脉，亦为留饮。人饮酒过多，肠胃已满，又复增之，脬经不及渗泄，久久如斯，亦为留饮。因隆暑津液焦涸，喜饮寒水，本欲止渴，乘快过多，逸而不动，亦为留饮。人若病饮者，岂能出此五者之外乎？", "19091": "故今代刘河间依仲景十枣汤，制三花神佑丸，而加大黄、牵牛。新得之疾，下三、五十丸，气流饮去。昔有病此者，数十年不愈。予诊之，左手脉三部，皆微而小，右手脉三部，皆滑而大。微小为寒，滑大为燥。余以瓜蒂散，涌其寒痰数升，汗出如沃；次以导水、禹功，去肠胃中燥垢亦数升，其人半愈；然后以淡剂流其余蕴，以降火之剂开其胃口，不逾月而痊。夫黄连、黄柏，可以清上燥湿；黄耆、茯苓，可以补下渗湿。二者可以收后，不可以先驱。复未尽者，可以苦葶苈、杏仁、桑白皮、椒目逐水之药，伏水皆去矣。", "19092": "嗽之为病，自古归之肺，此言固不易也。《素问》言：肺病，喘咳逆。又曰：咳嗽上气，厥在胸中，过在手太阴阳明。《灵枢》十二经，惟太阴肺经云：肺胀满，膨膨而喘咳，他经则不言。《素问·咳论》，虽言五脏六腑皆有咳，要之止以肺为主。《素问》言：皮毛者，肺之合也。皮毛先受邪气。注云：邪为寒气。《经》又曰：邪气以从其合也。其寒饮食入胃，从脾脉上至于肺则肺寒，肺寒则内外合邪，因而客之，则为肺咳。", "19093": "《灵枢》论神、意、魂、魄、志、精所主之病，然无寒暑惊劳四证。余以是推而广之。怒气所至，为呕血，为飧泄，为煎厥，为薄厥，为阳厥，为胸满胁痛；食则气逆而不下，为喘渴烦心，为消瘅，为肥气，为目暴盲，耳暴闭，筋解，发于外为疽痈；喜气所至，为笑不休，为毛发焦，为内病，为阳气不收，甚则为狂；悲气所至，为阴缩，为筋挛，为肌痹，为脉痿，男为数溲血，女为血崩，为酸鼻辛頞，为目昏，为少气不足以息，为泣则臂麻；恐气所至，为破䐃脱肉，为骨酸痿厥，为暴下绿水，为面热肤急，为阴痿，为惧而脱颐；惊气所至，为潮涎，为目睘，为口呿，为痴痫，为不省人，为僵仆，久则为痛痹；劳气所至，为咽噎病，为喘促，为嗽血，为腰痛、骨痿，为肺鸣，为高骨坏，为阴痿，为唾血，为瞑视，为耳闭，男为少精，女为不月，衰甚则溃溃乎若环都，汩汩乎不可止；思气所至，为不眠，为嗜卧，为昏瞀，为中痞三焦闭塞，为咽嗌不利，为胆瘅呕苦，为筋痿，为白淫，为得后与气快然如衰，为不嗜食；寒气所至，为上下所出水液澄沏清冷，下痢清白，吐痢腥秽，食已不饥，坚痞腹满急痛，症瘕颓疝，屈伸不便，厥逆禁固，热气所至，为喘呕吐酸，暴注下迫，转筋，小便混浊，腹胀大而鼓之有声如鼓，疮疽疡疹，瘤气结核，吐下霍乱，瞀郁肿胀，鼻窒鼽衄，血溢血泄淋闭，身热恶寒，甚则瞀瘈，目昧不明，耳鸣或聋，躁扰狂越，骂詈惊骇，禁栗，如丧神守，气逆冲上，嚏腥涌溢，食不下，跗肿疼酸，暴喑暴注，暴病暴死。", "19094": "余又尝以巫跃妓抵，以治人之悲结者。余又尝以针下之时便杂舞，忽笛鼓应之，以治人之忧而心痛者。余尝击拍门窗，使其声不绝，以治因惊而畏响，魂气飞扬者。余又尝治一妇人，久思而不眠，余假醉而不问，妇果呵怒，是夜困睡。又尝以酸枣仁丸，治人多忧。以白虎汤，不计四时，调理人之暑。余又以无忧散，泻人冬月得水中之寒痹，次以麻黄汤，数两作一剂，煎之枣姜，热服汗出而愈。如未愈者，以瓜蒂散涌之，以火助其汗，治寒厥亦然。余尝治大暑之病，诸药无效，余从其头，数刺其痏，出血立愈。余治此数者，如探囊。然惟劳而气耗，恐而气夺者，为难治。喜者少病，百脉舒和故也。昔闻山东杨先生，治府主洞泄不已。杨初未对病人，与众人谈日月星辰缠度，及风云雷雨之变，自辰至未，而病者听之，而忘其圊。杨尝曰：治洞泄不已之人，先问其所好之事。好棋者，与之棋；好乐者，与之笙笛，勿辍。又闻庄先生者，治以喜乐之极而病者。庄切其脉，为之失声，佯曰：吾取药去。数日更不来，病者悲泣，辞其亲友曰：吾不久矣。庄知其将愈，慰之。诘其故，庄引《素问》曰：惧胜喜。此二人可谓得玄关者也。然华元化以怒郡守而几见杀；文挚以怒齐王而竟杀之。千万人中，仅得一两人，而反招暴祸。若乃医，本至精至微之术，不能自保，果贱技也哉？悲夫！", "19095": "夫消者必渴。渴亦有三：有甘之渴，有石之渴，有火燥之渴。肥者令人内热，甘者令人中满，其气上溢，转为消渴。《经》又曰：味厚者发热。《灵枢》亦曰：咸走血，多食之人渴。咸入于胃中，其气上走中焦，注于肺，则血气走之，血与咸相得，则凝干而善渴。血脉者，中焦之道也。此皆肥甘之渴。夫石药之气悍，适足滋热，与热气相遇，必内伤脾，此药石之渴也。阳明司天，四之气，嗌干引饮，此心火为寒水所郁故然；少阳司天，三之气，炎暑至，民病渴；太阳司天，甚则渴而欲饮，水行凌火，火气郁故然。少阴之复，渴而欲饮；少阳之复，嗌络焦槁，渴饮水浆，色变黄赤。又伤寒五日，少阴受之，故口燥舌干而渴。肾热病者，苦渴数饮，此皆燥热之渴也。故膏粱之人，多肥甘之渴、石药之渴；藜藿奔走之人，多燥热之渴。二者虽殊，其实一也。故火在上者，善渴；火在中者，消谷善饥；火在上中者，善渴多饮而数溲；火在中下者，不渴而溲白液；火偏上中下者，饮多而数溲，此其别也。后人断消渴为肾虚，水不胜火则是也。", "19096": "况《灵枢》又说：心脉滑为善渴。《经》又曰：滑者阳气胜。又言：五脏脉，心脉微小为消瘅。又言：五脏脆，为消瘅。又言：消瘅之人，薄皮肤而目坚固以深，长冲直扬，其心刚。刚者多怒，怒则气逆上，胸中蓄积，血气逆留，𣎑皮充肌，血脉不行，转而为热，热则消肌肤，故为消瘅。又言：五脏皆柔弱者，善病消瘅。夫柔弱者，必有刚强，刚强者多怒，柔弱者易伤也。余以是遂悟气逆之人，非徒病消渴。若寒薄其外，亦为痈肿、少气、狂、膈中、肺消。涌水者，热客其脏，则亦为惊衄、膈消、柔痓，虚肠澼死；客其腑，则为癃溺血、口麋、伏瘕、为沉、食㑊、辛頞鼻渊、衄蔑瞑目。盖此二十一证，皆在气厥论中。《经》曰：诸逆冲上，皆属于火。一言可了，善读书者，以是求之。", "19097": "巢氏之衍九虫三𧏾详矣。然虫之变，不可胜穷，要之皆以湿热为主，不可纯归三气虚与食生具。巢氏之衍九虫也，曰伏、蛔、白、肉、肺、胃、弱、赤、蛲。伏虫，长四分，群虫之主也。蛔虫，长一尺，亦有长五、六寸，其发动则腹中痛，发作肿聚，往来上下，痛有休息，亦攻心痛，口喜吐涎，及吐清水，贯伤心则死。诊其脉，腹中痛，其脉法当沉弱，今脉反洪大，是蛔虫也。白虫，长一寸，相生子孙转大，长四、五尺，亦能杀人。寸白虫色白形扁小，因饮白酒，以桑枝贯牛肉炙食之，并生粟所成。又云：食生鱼后，即饮乳酪亦生。其发动则损人精气，腰脚疼。此虫长一尺，则令人死。肉虫，状如烂杏，令人烦满。肺虫，状如蚕，令人咳嗽。胃虫，状如虾蟆，令人呕逆吐喜哕。弱虫，状如瓜瓣，又名鬲虫，令人多唾。赤虫，状如生肉，动则腹鸣。蛲虫，至微，形如菜虫，居肚肠中，多则为痔，极则为癞，因人疮处，以生痈、疽、癣、瘘、疠瘑疥。龋虫，无故不为，人患亦不尽有，有亦不必尽多，或偏无者。此诸虫依肠胃之间，若人脏腑气实，则不为害，虚则侵蚀，随其虫之动，能变成诸疾也。", "19098": "予请为言补之法。大抵有余者损之，不足者补之，是则补之义也。阳有余而阴不足，则当损阳而补阴；阴有余而阳不足，则当损阴而补阳。热则芒硝、大黄，损阳而补阴也；寒则干姜、附子，损阴而补阳也。岂可以热药而云补乎哉？而寒药亦有补之义也。《经》曰：「因其盛而减之，因其衰而彰之。」此之谓也。或曰：形不足者，温之以气；精不足者，补之以味。执此温补二字，便为温补之法，惟用温补之药。且温补二字，特为形精不足而设，岂为病不病而设哉？虽曰温之，止言其气；虽曰补之，止言其味。曷尝言热药哉？至于天之邪气，感则害人，五脏实而不满，可下而已；水谷之寒热，感则害人，六腑满而不实，可吐而已；地之湿气，感则害人，皮肉筋脉，邪从外入，可汗而已。然发表不远热，而无补之意。", "19099": "夫暑者，为少阴君火之主也。诸痛痒疮疡，痈疽肿毒，及胃烦热，嗌干咳喘，唾血泄血，胕肿，肩胛皆内痛，心痛，肺胀，腹胀，郁闷。风温病多发，风伤于荣，温伤于卫。血为荣，气为卫。其脉两手多沉，自汗出，身重，多睡必鼾。三日以里，且宜辛凉解之，或辛温解之。如不已，表证未罢，大不可下。如下则胃中虚空。四日之外，表热入里，则谵语口干，发疹潮热，直视失溲者，十死八、九。肺金为病，人气在胸。及小儿疮疹丹熛，但发人气在腹。", "19100": "伤寒、温疫、时气、冒风、中暑，俱四时不正之气也。人若初感之，皆头痛、恶寒、身热，及寒热往来，腰脊强，是太阳经受之也。《内经》曰：可先治外而后治内。先用生姜、葱白、豆豉煎双解散，上涌及汗出则解。如不解者，至五、六日，或不大便，喘满𧮪语实热，两手脉沉，可用调胃、大、小承气汤下之，慎不可用银粉、巴豆霜、杏仁、芫花热药，下之则必死。此先治外，而后治内也。如大汗之后，慎不可食葵羹、藿菜及羊、猪、鸡、犬、鱼、兔等肉。惟不先明，必致重困，后必难治也。伤寒七、八日，发黄有斑，潮热腹满者，或痰实作止，虽诸承气汤下过者，仲景曰：寸口脉浮滑者，可用瓜蒂散吐之。然伤寒寸口脉浮滑者可用，杂病寸口脉沉者可吐。叔和云：寸脉沉兮胸有痰。启玄子曰：上盛不已，吐而夺之是也。", "19101": "夫痔漏肿痛，《内经》曰：因而大饱，筋脉横解，肠澼为痔。痔而不愈，变而为漏，同治湿法而治之。可先用导水丸、禹功散；泻讫，次服枳壳丸、木香槟榔丸；更加以葵羹、菠菜、猪羊血等，通利肠胃。大忌房室，鸡、鱼、酒、醋等物勿食之。", "19102": "夫一切冷食不消，宿酒不散，亦同伤寒，身热恶寒，战栗，头项痛，腰脊强，及两手脉沉，不可用双解，止可用导饮丸五、六十丸，量虚实加减，利五、七行。所伤冷食宿酒，若推尽则头痛等病自愈也。次以五苓散、生姜、枣，长流水煎服，五、六服。不可服酒症进食丸，此药皆犯巴豆，有热毒之故也。", "19103": "夫男子妇人，骨蒸热劳，皮肤枯干，痰唾稠黏，四肢疼痛，面赤唇干烦躁，睡卧不宁，或时喘嗽，饮食少味，困弱无力，虚汗黄瘦等疾，《内经》曰：男子因精不足而成；女子因血不流而得也。可先以茶调散轻涌讫；次以导水禹功散，轻泻三、两行；后服柴胡饮子、桂苓甘露散、搜风丸、白术调中汤、木香槟榔丸、人参犀角散之类，量虚实选而用之。如咯血、吐血、便血，此乃亡血也，并不宜吐，吐之则神昏。《内经》曰：血者，人之神也。故亡血则不宜吐。慎不可服峻热姜附之药。若服之则饮食难进，肌肉消削，转成危笃也。五劳之病，乃今人不明发表攻里之过也。大忌暑月于手腕、足外踝上著灸。手腕者，阳池穴也，此穴皆肌肉浅薄之处，灸疮最难痊。可及胸，次中脘、脐下、背俞、三里等穴，或有灸数十者，及以燔针，终无一效，病人反受苦，可不思之？劳疾多馋，所思之物，但可食者，宜《食疗本草》而与之。菠菜、葵羹，冰水、凉物，慎不可禁，以图水谷入胃，脉道乃行也。若过忌慎，则胃口闭，胃口闭，则形必瘦，形瘦脉空，乃死之候也。诸劳皆可仿此。", "19104": "夫头痛不止，乃三阳之受病也。三阳者，各分部分：头与项痛者，是足太阳膀胱之经也；攒竹痛，俗呼为眉楞痛者是也；额角上痛，俗呼为偏头痛者，是少阳经也；如痛久不已，则令人丧目。以三阳受病，皆胸膈有宿痰之致然也。先以茶调散吐之；后以香薷饮、白虎汤投之则愈。然头痛不止，可将葱白须、豆豉汤吐之；吐讫，可服川芎、薄荷，辛凉清上，搜风丸、香芎散之类。仲景曰：葱根、豆豉，亦吐伤寒头痛。叔和云：寸脉急而头痛是也。", "19105": "夫便痈者，乃男子之疝也，俗呼为便痈。言于大便处害一痈，故名便痈也。便痈者，谬名也，《难》《素》所不载也。然足厥阴肝之经络，是气血行流之道路也。冲、任、督脉，亦属肝经之旁络也。《难经》曰：男子有七疝是也。便痈者，血疝也。治之以导水丸、桃仁承气汤，或抵当汤投之，同瘀血不散而治，大作剂料，峻泻一、二十行；次以玉烛散，和气血，通经络之类则是也。世之多用大黄、牡蛎而已。间有不愈者，是不知和血通经之道也。", "19106": "夫妇人月事不来，室女亦同。《内经》曰：月事不来者，是胞脉闭也。胞脉者，属火而络于脬中。令气上迫肺，心气不得下通，故月事不来也。可用茶调散吐之；吐讫，可用玉烛散、当归散，或三和汤、桂苓白术散、柴胡饮子，量虚实选而用之。降心火，益肾水，开胃进食，分阴阳，利水道之药是也。慎勿服峻热之药。若服之，则变成肺痿，骨蒸潮热，咳嗽咯脓，呕血而喘，小便涩滞，寝汗不已，渐至形瘦脉大，虽遇良医，亦成不救。呜呼！人之死者，岂为命耶？", "19107": "若妇人有癃闭、遗溺、嗌干之诸证，虽服药、针灸，亦不能孕也。盖冲、任、督三脉之病，故不治也。表证见内证及热论中。", "19108": "夫妇人有天生无乳者，不治。或因啼哭悲怒郁结，气溢闭塞，以致乳脉不行，用精猪肉清汤，调和美食，于食后调益元散五、七钱，连服三、五服，更用木梳梳乳，周回百余遍，则乳汁自下也。", "19109": "夫乳痈发痛者，亦生于心也，俗呼曰吹乳是也。吹者，风也。风热结薄于乳房之间，血脉凝注，久而不散，溃腐为脓也。可用一法禁之。", "19110": "夫妇人身重，九月而喑哑不言者，是脬之络脉不相接也，则不能言。《经》曰：无治也。虽有此论，可煎玉烛散二两，水一碗，同煎至七分，去滓，放冷，入蜜少许，时时呷之，则心火下降，而肺金自清，故能作声也。", "19111": "夫小儿身瘦肌热，面黄腹大，或吐泻，腹有青筋，两胁结硬如碗之状，名乳痈癖，俗呼曰奶脾是也。乳痈得之绵帛太厚，乳食伤多。大热则病生肌，大饱则必伤于肠胃。生于肌表者，赤眼、丹瘤、疥癣、痈疖、眉炼、赤白口疮、牙疳宣烂及寒热往来。此乳母抱不下怀，积热熏蒸之故，两手脉浮而数也。伤于肠胃者，吐泻惊疳，哽气腹胀，肌瘦面黄，肚大筋青，喜食泥土，揉鼻窍，头发作穗，乳瓣不化，此皆大饱之致然也，久而不愈，则成乳痈，两手脉沉而紧也，此其辨也。以上诸症，皆乳母怀抱，奉养过度之罪。癖之疾，可以丁香化痹散，取过数服，牛黄通膈丸、甘露散、益黄散等药磨之。如不愈者，有揉脾一法。", "19112": "赵明之，米谷不消，腹作雷鸣，自五月至六月不愈。诸医以为脾受大寒，故并与圣散子、豆蔻丸，虽止一、二日，药力尽而复作。诸医不知药之非，反责明之不忌口。戴人至而笑曰：春伤于风，夏必飧泄。飧泄者，米谷不化，而直过下出也。又曰：米谷不化，热气在下，久风入中。中者，脾胃也。风属甲乙，脾胃属戊己，甲乙能克戊己，肠中有风故鸣。《经》曰：岁木太过，风气流行，脾土受邪，民病飧泄。诊其两手脉，皆浮数，为风在表也，可汗之。直断曰：风随汗出。以火二盆，暗置床之下，不令病人见火，恐增其热。绐之入室，使服涌剂，以麻黄投之，乃闭其户，从外锁之，汗出如洗。待一时许开户，减火一半，须臾汗止，泄亦止。", "19113": "南乡陈君俞，将赴秋试，头项遍肿连一目，状若半壶，其脉洪大。戴人出视。《内经》：面肿者，风，此风乘阳明经也。阳明气血俱多。风肿宜汗。乃与通圣散，入生姜、葱根、豆豉，同煎一大盏，服之，微汗；次日以草茎鼻中，大出血，立消。", "19114": "曹典吏妻，产后忧恚抱气，浑身肿绕，阴器皆肿，大小便如常，其脉浮而大，此风水肿也。先以齑水撩其痰，以火助之发汗；次以舟车丸、浚川散，泻数行；后四、五日，方用苦剂；涌讫，用舟车丸、通经散，过十余行；又六日，舟车、浚川复下之；末后用水煮桃红丸。四十余丸。不一月如故，前后涌者二，泻凡四，通约百余行。当时议者，以为倒布袋法耳，病再来，则必死。世俗只见尘市货药者，用银粉、巴豆，虽肿者暂去，复来必死，以为惊俗。岂知此法，乃《内经》治郁之玄缺。", "19115": "故息城一男子病疟，求治于戴人。诊两手脉，皆沉伏而有力，内有积也，此是肥气。病者曰：左胁下有肥气，肠中作痛，积亦痛，形如复杯，间发止，今已三年，祈禳避匿，无所不至，终不能疗。戴人曰：此㾬疟也。以三花神祐丸五、七十丸，以冷水送过五、六行。次以冷水止之，冷主收敛故也。湿水既尽一、二日，煎白虎汤，作顿啜之，疟犹不愈，候五、六日，吐之以常山散，去冷痰涎水六、七次，若翻浆。次以柴胡汤和之，间用妙功丸磨之，疟悉除。", "19116": "一叟，年六十，值徭役烦扰，而暴发狂，口鼻觉如虫行，两手爬搔，数年不已。戴人诊其两手脉，皆洪大如𫄠绳。断之曰：口为飞门，胃为贲门。曰：口者，胃之上源也，鼻者，足阳明经起于鼻交頞之中，旁纳太阳，下循鼻柱，交人中，环唇下，交承浆，故其病如是。夫徭役烦扰，便属火化。火乘阳明经，故发狂。故《经》言：阳明之病，登高而歌，弃衣而走，骂詈不避亲疏。又况肝主谋，胆主决。徭役迫遽，则财不能支，则肝屡谋而胆屡不能决。屈无所伸，怒无所泄，心火磅礴，遂乘阳明经。然胃本属土，而肝属木，胆属相火，火随木气而入胃，故暴发狂。乃命置燠室中，涌而汗出，如此三次，《内经》曰：木郁则达之，火郁则发之。良谓此也。又以调胃承气汤半斤，用水五升，煎半沸，分作三服，大下二十行，血水与瘀血相杂而下数升，取之乃康。以通圣散调其后矣。", "19117": "麻先生妻，当七月间，病脏腑滑泄。以祛湿降火之药治之，少愈。后腹胀及乳痛，状如吹乳，痛重壮热，面如渥丹，寒热往来，嗌干呕逆，胸胁痛不能转侧，耳鸣，食不可下，又复泻。余欲泻其火，脏腑已滑数日矣；欲以温剂止痢，又禁上焦已热。实不得其法。使人就诸葛寺，礼请戴人。比及戴人至，因检刘河间方，惟益元散正对此证，能降火解表，止渴利小便，定利安神。以青黛、薄荷末，调二升，置之枕右，使作数次服之。夜半遍身冷汗如洗。元觉足冷如冰，至此足大暖，头顿轻，肌凉痛减，呕定痢止。及戴人至，余告之已解。戴人曰：益元固宜。此是少阳证也，能使人寒热遍剧，他经纵有寒热，亦不至甚，既热而有痢，不欲再下，何不以黄连解毒汤服之？乃令诊脉。戴人曰：娘子病来，心常欲痛哭为快否？妇曰：欲如此，余亦不知所谓。戴人曰：少阳相火，凌烁肺金，金受屈制，无所投告。肺主悲，但欲痛哭而为快也。麻先生曰：余家诸亲，无不敬服。脉初洪数有力，自服益元散后已半，又闻戴人之言，使以当归、芍药，以解毒汤中数味服之，大瘥矣。", "19118": "遂平李官人妻，病咽中如物塞，食不下，中满，他医治之不效。戴人诊其脉曰：此痰隔也。《内经》曰：三阳结为隔。王启玄又曰：格阳云阳盛之极，故食格拒而不入。先以通经散，越其一半；后以舟车丸下之，凡三次，食已下；又以瓜蒂散再越之，健啖如昔日矣。", "19119": "夫小儿悲哭，弥日不休，两手脉弦而紧。戴人曰：心火甚而乘肺，肺不受其屈，故哭。肺主悲。王太仆云：心烁则痛甚。故烁甚悲亦甚。今浴以温汤，渍形以为汗也。肺主皮毛，汗出则肺热散矣。浴止而啼亦止。乃命服凉膈散加当归、桔梗，以竹叶、生姜、朴硝同煎服，泻膈中之邪热。", "19120": "岳八郎，常日嗜酒，偶大饮醉，吐血近一年，身黄如橘，昏愦发作，数日不省，浆粥不下，强直如厥，两手脉皆沉细。戴人视之曰：脉沉细者，病在里也，中有积聚。用舟车丸百余粒，浚川散五、六钱，大下十余行，状若葵菜汁，中燥粪，气秽异常。忽开两目，伸挽问左右曰：我缘何至此？左右曰：你吐血后数日不省，得戴人治之乃醒。自是五、六日必以泻，凡四、五次，其血方止，但时咳一、二声，潮热未退。以凉膈散加桔梗、当归，各秤二两，水一大盂，加老竹叶，入蜜少许，同煎去滓，时时呷之，间与人参白虎汤，不一月复故。", "19121": "武阳仇天祥之子，病发寒热。诸医作骨蒸劳治之，半年病愈甚。以礼来聘戴人。戴人往视之。诊其两手脉，尺寸皆潮于关，关脉独大。戴人曰：痈象也。问其乳媪：曾有痛处否？乳媪曰：无。戴人令儿去衣，举其两手，观其两胁下，右胁稍高。戴人以手侧按之，儿移身乃避之，按其左胁则不避。戴人曰：此肺部有痈也，非肺痈也。若肺痈已吐脓矣。此不可动，止可以药托其里，以待自破。家人皆疑之，不以为然。服药三日，右胁有三点赤色。戴人连辞云：此儿之病，若早治者，谈笑可已，今已失之迟。然破之后，方验其生死矣。若脓破黄赤白者生也，脓青黑者死也。遂辞而去，私告天祥之友李简之曰：数月之后，即此儿必有一证也。其证乃死矣，肺死于巳。至期而头眩不举，不数日而死也。其父曰：群医治之，断为骨蒸证。戴人独言其肺有痈也。心终疑之。及其死，家人辈以火焚其棺。既燃，天祥以杖破其胁下，果出青黑脓一碗。天祥仰天哭曰：诸医误杀吾儿矣！", "19122": "彭吴张叟，年六十余岁，病热厥头痛，以其用涌药，时已一月间矣。加之以火，其人先利脏腑，年高身困，出门见日而仆，不知人。家人惊惶，欲揉扑之。戴人曰：大不可扰。续与西瓜、凉水、蜜雪，少顷而苏。盖病人年老涌泄，目脉易乱，身体内有炎火，外有太阳，是以自跌。若是扰之，便不救矣。惟安定神思，以凉水投之，待之以静。静便属水，自然无事。若他医必惑，足以知戴人之谙练。", "19123": "孟官人母，年五十余岁，血崩一载，佥用泽兰丸、黑神散、保安丸、白薇散，补之不效。戴人见之曰：天癸已尽，本不当下血。盖血得热而流散，非寒也。夫女子血崩，多因大悲哭。悲甚则肺叶布，心系为之恐，血不禁而下崩。《内经》曰：阴虚阳搏为之崩。阴脉不足，阳脉有余，数则内崩，血乃下流。举世以虚损治之，莫有知其非者。可服大剂。大剂者，黄连解毒汤是也。次以拣香附子二两（炒），白芍二两焙，当归一两（焙），三味同为细末，水调下；又服槟榔丸，不拘日而安。", "19124": "一妇身冷脉微，食沸热粥饭，六月重衣，以狐帽蒙其首犹觉寒，泄注不止。常服姜、附、硫黄燥热之剂，仅得平和，稍用寒凉，其病转增，三年不愈。戴人诊其两手脉，皆如𫄠绳有力，一息六、七至。《脉诀》曰：六数七极热生多。以凉布搭心，次以新汲水淋其病处，妇乃叫杀人。不由病者，令人持之，复以冷水淋其三、四十桶，大战汗出，昏困一、二日，而向之所恶皆除。此法华元化已曾用，世无知者。", "19125": "又息帅，病腰股沉痛，行步坐马皆不便。或作脚气寒湿治之，或作虚损治之，乌、附、乳、没，活血壮筋骨之药，无不用之。至六十余日，目赤上热，大小便涩，腰股之病如故。戴人诊其两手脉，皆沉迟。沉者为在里也。在里者泄之。以舟车丸、浚川散，各一服，去积水二十余行。至早晨，服齑白粥一二顿，与之马，已能矍铄矣。", "19126": "一妇年三十四岁，夜梦与鬼神交，惊怕异常，及见神堂阴府，舟楫桥梁，如此一十五年，竟无娠孕。巫祈觋祷，无所不至，钻肌灸肉，孔穴万千。黄瘦发热引饮，中满足肿，委命于天。一日，苦请戴人。戴人曰：阳火盛于上，阴火盛于下。鬼神者，阴之灵；神堂者，阴之所；舟楫桥梁，水之用。两手寸脉皆沉而伏，知胸中有痰实也。凡三涌三泄三汗，不旬日而无梦，一月而有孕。戴人曰：余治妇人使有娠，此法不诬。", "19127": "古郾一讲僧，病泄泻数年，丁香、豆蔻、干姜、附子、官桂、乌梅等燥药，燔针、烧脐、焫腕，无有阙者。一日，发昏不省，檀那赠纸者盈门。戴人诊其两手脉，沉而有力。《脉诀》云：下利，脉微小者生，洪浮大者无瘥。以瓜蒂散涌之，出寒痰数升；又以无忧散，泄其虚中之积及燥粪，仅盈斗；次以白术、调中汤、五苓散、益元散，调理数日，僧已起矣。非术精识明，谁敢负荷如此？", "19128": "又李德卿妻，因产后病泄一年余，四肢瘦乏，诸医皆断为死证。当时戴人在朱葛寺，以舟载而乞治焉。戴人曰：两手脉皆微小，乃痢病之生脉。况洞泄属肝经，肝木克上而成。此疾亦是肠澼。澼者，肠中有积水也。先以舟车丸四、五十粒，又以无忧散三、四钱，下四、五行。寺中人皆骇之：病羸如此，尚可过耶？众人虽疑，然亦未敢诮，且更看之。复导饮丸，又过之，渴则调以五苓散。向晚使人伺之，已起而缉床，前后约三、四十年。以胃风汤调之，半月而能行，一月而安健。由此阖寺服，德卿之昆仲咸大异之。", "19129": "郾城梁贾人，年六十余，忽晓起梳发，觉左手指麻，斯须半臂麻，又一臂麻，斯须头一半麻；比及梳毕，从胁至足皆麻，大便二、三日不通。往问他医，皆云风也。或药或针，皆不解。求治于戴人。戴人曰：左手三部脉皆伏，比右手小三倍，此枯涩痹也。不可纯归之风，亦有火燥相兼。乃命一涌一泄一汗，其麻立已。后以辛凉之剂调之，润燥之剂濡之，惟小指次指尚麻。戴人曰：病根已去，此余烈也。方可针溪谷。溪谷者，骨空也，一日晴和，往针之，用《灵枢》中鸡足法，向上卧针，三进三引讫，复卓针起，向下卧针送入指间皆然，手热如火，其麻全去。昔刘河间作《原病式》，常以麻与涩，同归燥门中，真知病机者也。", "19130": "戴人过曹南省亲，有姨表兄，病大便燥涩，无他证。常不敢饱食，饱则大便极难，结实如针石，或三、五日一如圊，目前星飞，鼻中血出，肛门连广肠痛，痛极则发昏，服药则病转剧烈。巴豆、芫花、甘遂之类皆用之，过多则困，泻止则复燥，如此数年，遂畏药性暴急不服，但卧病待尽。戴人过诊其两手脉息，俱滑实有力。以大承气汤下之，继服神功丸、麻仁丸等药，使食菠菱、葵菜及猪羊血作羹，百余日充肥。亲知见骇之。呜呼！粗工不知燥分四种：燥于外则皮肤皱揭；燥于中则精血枯涸；燥于上则咽鼻焦干；燥于下则便溺结闭。夫燥之为病，是阳明化也。水寒液少，故如此。然可下之，当择之药之。巴豆可以下寒；甘遂芫花可下湿；大黄朴硝可以下燥。《内经》曰：辛以润之，咸以软之。《周礼》曰：以滑养窍。", "19131": "戴人过东杞，一妇人病大便燥结，小便淋涩，半生不娠，惟常服疏导之药，则大便通利，暂废药则结滞。忽得孕，至四、五月间，医者禁疏导之药，大便依常为难，临圊则力努，为之胎坠。凡如此胎坠者三。又孕，已经三、四月，弦望前后，溲溺结涩，甘分胎陨，乃访戴人。戴人诊其两手脉，俱滑大。脉虽滑大，以其且妊，不敢陡攻。遂以食疗之，用花碱煮菠菱葵菜，以车前子苗作茹，杂猪羊血作羹，食之半载，居然生子，其妇燥病方愈。戴人曰：余屡见孕妇利脓血下迫，极努损胎，但同前法治之愈者，莫知其数也。为医拘常禁，不能变通，非医也，非学也。识医者鲜，是难说也。", "19132": "一妇人年四十余，病额角上耳上痛，俗呼为偏头痛。如此五、七年，每痛大便燥结如弹丸，两目赤色，眩运昏涩，不能远视。世之所谓头风药、饼子风药、白龙丸、芎犀丸之类，连进数服。其痛虽稍愈，则大便稍秘，两目转昏涩。其头上针灸数千百矣。连年著灸，其两目且将失明，由病而无子。一日问戴人。戴人诊其两手脉，急数而有力，风热之甚也。余识此四、五十年矣，遍察病目者，不问男子妇人，患偏正头痛，必大便涩滞结硬，此无他。头痛或额角，是三焦相火之经及阳明燥金胜也。燥金胜，乘肝则肝气郁，肝气郁则气血壅，气血壅则上下不通，故燥结于里，寻至失明。治以大承气汤，令河水煎三两，加芒硝一两，煎残顿令温，合作三、五服，连服尽。荡涤肠中垢滞结燥，积热下泄如汤，二十余行。次服七宣丸、神功丸以润之，菠菱葵菜，猪羊血为羹以滑之。后五、七日、十日，但遇天道晴明，用大承气汤，夜尽一剂，是痛随利减也，三剂之外，目豁首轻，燥泽结释，得三子而终。", "19133": "一男子六十余，病腰尻脊胯皆痛，数载不愈，昼静夜躁，大痛往来，屡求自尽天年。旦夕则痛作，必令人以手捶击，至五更鸡鸣则渐减，向曙则痛止。左右及病者，皆作神鬼阴谴，白虎啮。朝祷暮祝，觋巫僧道禁师至，则其痛以减。又梦鬼神，战斗相击。山川神庙，无不祭者。淹延岁月，肉瘦皮枯，饮食减少，暴怒日增，惟候一死。有书生曰：既云鬼神虎啮，阴谴之祸，如此祷祈，何无一应？闻陈郡有张戴人，精于医，可以问其鬼神白虎与病乎？彼若术穷，可以委命。其家人从之。戴人诊其两手脉，皆沉滞坚劲，力如张𫄠。谓之曰：病虽瘦，难于食，然腰尻脊胯皆痛者，必大便坚燥。其左右曰：有五、六日，或八、九日，见燥粪一、两块，如弹丸结硬不可言，曾令人剜取之，僵下一、两块，浑身燥痒，皮肤皱揭枯涩如麸片。戴人既得病之虚实，随用大承气汤，以姜枣煎之，加牵牛头末二钱，不敢言是泻剂。盖病者闻暖则悦，闻寒则惧，说补则从，说泻则逆。此弊非一日也。而况一齐人而敷之，众楚人咻之乎！及煎成，使稍热咽之，从少至多，累至三日。天且晚，脏腑下泄四、五行，约半盆。以灯视之，皆燥粪燥痹块及瘀血杂脏，秽不可近。须臾痛减九分，昏睡，鼻息调如常人。睡至明日将夕，始觉，饥而索粥，温凉与之。又困睡一、二日，其痛尽去。次令饮食调养，日服导饮丸、甘露散，滑利便溺之药，四十余日乃复。呜呼！再传三十六虎书，三十六黄经，及小儿三十六吊，谁为之耶？始作俑者，其无后乎？古人以医为师，故医之道行；今之人以医辟奴，故医之道废。有志之士，耻而不学，病者亦不择精粗，一概待之。常见官医迎送长吏，马前唱诺，真可羞也。由是通今博古者少，而师传遂绝。《灵枢经》谓：刺与汗虽久，犹可拔而雪；结与闭虽久，犹可解而决。去腰脊胯痛者，足太阳膀胱经也。胯痛，足少阳胆经之所过也。《难经》曰：诸痛为实。《内经》曰：诸痛痒疮疡，皆属心火。注曰：心寂则痛微，心躁则痛甚。人见巫觋僧道禁师至，则病稍去者，心寂也。然去其后来者，终不去其本也。古之称痛随利减，不利则痛何由去？病者既痊，乃寿八十岁。故凡燥证，皆三阳病也。", "19134": "一僧病疝，发作冷气上贯齿，下贯肾，紧若绳挽两睪，时肿而冷。戴人诊两手，脉细而弱。断之曰：秋脉也。此因金气在上，下伐肝木，木畏金抑而不伸，故病如是。肝气磅礴，不能下荣于睪丸，故其寒，实非寒也。木受金制，传之胃土，胃为阳明，故上贯齿，病非齿之病。肝木者，心火之母也，母既不伸，子亦屈伏，故下冷而水化乘之。经曰：木郁则达之，土郁则泄之。令涌泄四次，果觉气和，睪丸痒而暖。戴人曰：气已入睪中矣。以茴香、木茂之药，使常服之，首尾一月而愈。", "19135": "一妇人，心下脐上结硬如斗，按之如石。人皆作病胎，针灸毒药，祷祈无数，如捕风然。一日，戴人见之曰：此寒痰。诊其两手，寸脉皆沉，非寒痰而何？以瓜蒂散吐之，连吐六、七升，其块立消过半。俟数日后再吐之，其涎沫类鸡黄，腥臭特殊，约二、三升。凡如此者三。后以人参调中汤、五苓散调之，腹已平矣。", "19136": "东门一男子，病泻利不止，腹鸣如雷，不敢冷坐，坐则下注如倾。诸医例断为寒证。干姜、官桂、丁香、豆蔻之属；枯矾、龙骨，皆服之矣。何针不燔！何艾不炷！迁延将二十载矣。一日，问于戴人。戴人曰：两手寸脉皆滑，余不以为寒。然其所以寒者，水也。以茶调散，涌寒水五、七升；无忧散，泻积水数十行。乃通因通用之法也。次以五苓散淡剂，渗泻利之道；又以甘露散止渴。不数日而冷食寒饮皆如故。此法王启玄稔言之矣，奈何无人用之哉？", "19137": "息城司侯，闻父死于贼，乃大悲哭之，罢，便觉心痛，日增不已，月余成块，状若复杯，大痛不住，药皆无功。议用燔针炷艾，病人恶之，乃求于戴人。戴人至，适巫者在其旁，乃学巫者，杂以狂言以谑病者，至是大笑，不忍回。面向壁，一、二日，心下结块皆散。戴人曰：《内经》言：忧则气结，喜则百脉舒和。又云：喜胜悲。《内经》自有此法治之，不知何用针灸哉？适足增其痛耳！", "19138": "一富家妇人，伤思虑过甚，二年不寐，无药可疗。其夫求戴人治之。戴人曰：两手脉俱缓，此脾受之也。脾主思故也。乃与其夫，以怒而激之。多取其财，饮酒数日，不处一法而去。其人大怒汗出，是夜困眠，如此者，八、九日不寤，自是而食进，脉得其平。", "19139": "陈州长吏一小儿，病寐而不寤。一日，诸医作睡惊治之，或欲以艾火灸之，或以大惊丸，及水银饼子治之。其父曰：此子平日无疾，何骤有惊乎？以子之病，乃问于戴人。戴人诊其两手，脉皆平和。戴人曰：若惊风之脉，当洪大而强，今则平和，非惊风也。戴人窃问其乳母：尔三日前曾饮醉酒否？遽然笑曰：夫人以煮酒见饷，酒味甚美，饮一罂而睡。陈酒味甘而恋膈，酒气满，乳儿亦醉也。乃锉甘草、干葛花、缩砂仁、贯众煎汁使饮之，立醒。", "19140": "一孕妇，年二十余，临产召稳媪三人，其二媪极拽妇之臂，其一媪头抵妇之腹，更以两手扳其腰，极力为之。胎死于腹，良久乃下，儿亦如血，乃稳媪杀之也。岂知瓜熟自落，何必如此乎？其妇因兹经脉断闭，腹如刀剜，大渴不止，小溲闭绝。主病者禁水不与饮，口舌枯燥，牙齿黧黑，臭不可闻，食饮不下，昏愦欲死。戴人先以冰雪水恣意饮之，约二升许，痛缓渴止；次以舟车丸、通经散，前后五、六服，下数十行，食大进；仍以桂苓甘露散、六一散、柴胡饮子等调之，半月获安。", "19141": "一富家女子，十余岁，好食紫樱，每食即二、三斤，岁岁如此，至十余年。一日潮热如劳。戴人诊其两手脉，皆洪大而有力。谓之曰：他日必作恶疮肿毒，热上攻目，阳盛阴脱之证。其家大怒，不肯服解毒之药。不一、二年，患一背疽如盘，痛不可忍。其女忽思戴人曾有是言，再三悔过，请戴人。戴人以䤵针绕疽晕，刺数百针，去血一斗。如此三次，渐渐痛减肿消，微出脓而敛。将作痂时，使服十补内托散，乃痊。终身忌口。然目亦昏，终身无子。", "19142": "上渠卜家一男子，年二十八岁，病身弱，四肢无力，面色苍黄，左胁下身侧，上下如臂状，每发则痛无时，食不减，大便如常，小便微黄，已二、三载矣。诸医计穷，求戴人治之。视其部分，乃足厥阴肝经，兼足少阳胆经也。张曰：甲胆乙肝故青。其黄者，脾也。诊胆脉小，此因惊也。惊则胆受邪，腹中当有惊涎绿水。病人曰：昔曾屯军被火，自是而疾。戴人夜以舟车百五十丸，浚川散四、五钱，加生姜自然汁，平旦果下绿水四、五行。或问大加生姜何也？答曰：辛能伐木也。下后觉微痛，令再下之，比前药减三之一，又下绿水三、四行。痛止思食，反有力。戴人谓卜曰：汝妻亦当病。卜曰：太医未见吾妻，何以知之？曰：尔感此惊几年矣？卜省曰：当被火时，我正在草堂中熟寐，人惊唤，我睡中惊不能言，火已塞门，我父拽出我火中，今五年矣。张曰：汝胆伏火惊，甲乙乘脾土，是少阳相火乘脾，脾中有热，故能食而杀谷。热虽能化谷，其精气不完，汝必无子。盖败经反损妇人，汝妻必手足热，四肢无力，经血不时。卜曰：吾妻实如此，亦已五年矣。他日，门人因观《内经》，言先泻所不胜，次泻所胜之论，其法何如，以问张。张曰：且如胆木乘胃土，此土不胜木也。不胜之气，寻救于子，己土能生庚金。庚为大肠，味辛者为金，故大加生姜使伐木。然先不开脾，土无由行也。遂用舟车丸，先通其闭塞之路，是先泻其所不胜；后用姜汁调浚川散大下之，次泻其所胜也。大抵阳干克阳干，腑克腑，脏克脏。", "19143": "一妇人，年四十余得孕。自以为年衰多病，故疾复作，以告医氏。医者不察，加燔针于脐两旁，又以毒药攻磨。转转腹痛，食减形羸，已在床枕。来问戴人。戴人诊其脉曰：六脉皆平，惟右尺脉洪大有力，此孕脉也，兼择食，为孕无疑。左右皆笑之。不数月，生一女子，两目下各有燔针痕，几丧其明。凡治病妇，当先问娠，不可仓卒矣。", "19144": "戴人出游，道经阳夏，问一旧友，其人病已危矣。戴人往视之。其人曰：我别无病。三年前，当隆暑时出村野，有以煮酒馈予者，适村落无汤器，冷饮数升，便觉左胁下闷，渐痛结硬，至今不散。针灸磨药，殊不得效。戴人诊其两手，脉俱沉实而有力。先以独圣散吐之，一涌二、三升，色如煮酒，香气不变；后服和脾散、去湿药。五、七日，百脉冲和，始知针灸无功，增苦楚矣。", "19145": "一缁侣，好茶成癖，积在左胁。戴人曰：此与肥气颇同。然㾬疟不作，便非肥气。虽病十年，不劳一日。况两手脉沉细，有积故然。吾治无针灸之苦，但小恼一饷，可享寿尽期。先以茶调散，吐出宿茶水数升；再以木如意揃之，又涌数升，皆作茶色；次以三花神祐丸九十余粒，是夜泻二十余行，脓水相兼，燥粪瘀血，杂然而下；明日以除湿之剂，服十余日，诸苦悉蠲，神清色莹。", "19146": "戴人过醮都营中饮会，邻席有一卒，说出妻事。戴人问其故。答曰：吾妇为室女，心下有冷积如复杯，按之如水声，以热手熨之如火聚，来已十五年矣。恐断我嗣，是故弃之。戴人曰：公勿黜也。如用吾药，病可除，孕可得。卒从之。戴人诊其脉沉而迟，尺脉洪大而有力，非无子之候也，可不逾年而孕。其良人笑曰：试之。先以三圣散吐涎一斗，心下平软；次服白术调中汤、五苓散；后以四物汤和之。不再月，气血合度，数月而娠二子。戴人常曰：用吾此法，无不子之妇，此言不诬矣。", "19147": "一妇从年少时，因大哭罢，痛饮冰水困卧，水停心下，渐发痛闷。医氏咸以为冷积，治之以温热剂，及禁食冷物。一闻茶气，病辄内作，如此数年。燎针烧艾，疮孔数千。十余年后，小便赤黄，大便秘闷，两目加昏，积水转甚，流于两胁。世谓水癖，或谓支饮，硇、漆、棱、术，攻磨之药，竟施之矣。食日衰，积日茂，上至鸠尾，旁至两胁及脐下，但发之时，按之如水声，心腹结硬，手不可近者。月发五、七次，甚则欲死，诸药皆厌，二十余年。求戴人发药。诊其脉，寸口独沉而迟，此胸中有痰。先以瓜蒂散涌痰五、七升；不数日，再越痰水及斗；又数日，上涌数升。凡三涌三下，汗如水者亦三，其积皆去。以流湿饮之药调之，月余大瘥。", "19148": "修弓杜匠，其子妇年三十，有孕已岁半矣。每发痛则召侍媪待之，以为将产也。一、二日复故，凡数次。乃问戴人。戴人诊其脉涩而小，断之曰：块病也，非孕也。《脉诀》所谓涩脉如刀刮竹形，主丈夫伤精，女人败血。治之之法，有病当泻之。先以舟车丸百余粒；后以调胃承气汤加当归、桃仁，用河水煎，乘热投之；三、两日，又以舟车丸、桃仁承气汤泻，青黄脓血，杂然而下，每更衣，以手向下推之揉之则出；后三、二日，又用舟车丸，以猪肾散佐之；一、二日，又以舟车丸，通经如前，数服，病十去九；俟晴明，当未食时，以针泻三阴交穴。不再旬，块已没矣。此与隔腹视五脏者，复何异哉？", "19149": "胡王之妻，病脐下积块，呕食面黄，肌瘦而不月。或谓之干血气，治之无效。戴人见之曰：孕也。其人不信，再三求治于戴人。与之平药以应其意，终不肯下毒药。后月到，果胎也。人问何以别之？戴人曰：尺脉洪大也。《素问·阴阳别论》所谓阴搏阳别之脉。", "19150": "一男子，病泄十余年。豆蔻、阿胶、诃子、龙骨、枯矾，皆用之矣。中脘、脐下、三里，岁岁灸之。皮肉皴槁，神昏足肿，泄如泔水，日夜无度。戴人诊其两手脉，沉且微，曰：生也。病人忽曰：羊肝生可食乎？戴人应声曰：羊肝止泄，尤宜服。病人悦而食一小盏许，可以浆粥送之。病人饮粥数口，几半升，续又食羊肝（生）一盏许，次日泄几七分。如此月余而安。此皆忌口太过之罪也。", "19151": "小满至大暑，少阳相火之位。阳气发，万物俱成，故亦云太阳旺。其脉洪大而长，天气并万物，人脉盛衰。造物造化亦同。", "19152": "大暑至秋分，太阴湿土之位。天气吉感，夏后阴已用事，故曰：太阴旺。此三阴三阳，与天气标本阴阳异矣。脉缓大而长。燥金旺，紧细短涩。以万物干燥，明可见矣。", "19153": "秋分至小雪，阳明燥金之位。气衰阴盛，故云金气旺，其脉细而微。", "19154": "是动则病手心热、臂肘挛急、腋肿，甚则胸胁支满、心中憺憺大动、面赤目黄、喜笑不休。是主脉所生病者，烦心、心痛、掌中热。为此诸病。", "19155": "是动则病齿痛、颈肿。是主津液所生病者，目黄、口干、鼽衄、喉痹、肩前臑痛、大指次指痛不用。气有余，则当脉所过者热肿；虚则寒栗不复。为此诸病。", "19156": "乳痔肠风：必肛门左右有核。《内经》曰：因而饱食，筋脉横解，肠澼为痔。属大肠经，可服枳壳之属。大癖生肠风，乳痔相连。", "19157": "凡下痢之脉，微且小者生，浮大者死。水肿则反是，浮大者生，沉细者死。夫病在里脉沉，在表脉浮。里当下之，表当汗之。下痢而脉浮滑，水肿者脉沉细，表里俱受病，故不治也。凡脏血便血，两手脉俱弦者死绝，俱滑大者生，血温身热者死。王太仆则曰：若下血而身热血温，是血去而外逸也，血属火故也。七日而死者，火之成数也。", "19158": "彼豆蔻、乌梅、罂粟壳勿骤用也。设病形一变，必致大误。或通而塞，或塞而通，塞塞通通，岂限一法？世俗止知塞剂之能塞，而不知通剂之能塞者，拘于方也！凡治湿，皆以利小溲为主。诸泄不已，宜灸水分穴，谓水谷之所别也。脐之上一寸半，灸五、七壮。腹鸣如雷，水道行之候也。凡湿勿针。《内经》虽云缪刺其处，莫若以张长沙治伤寒法治之。盖泄者，亦四时伤寒之一也。仲景曰：上涌而下泄，表汗而里攻，半在表，半在里，则宜和解之，表里俱见，随证渗泄。此虽以治伤寒，其于治湿也同。仍察脉以视深浅，问年壮以视虚实，所投必如其意矣。", "19159": "凡伤寒、中风、温疫、时气、冒暑，感四时不正之气。若邪毒之气，人或感之，始于巨阳受之，二日阳明受之。三日少阳受之，前三日在于表阳也，后三日在于里阴也。《内经·热论》，通谓之伤寒。热病者，言一身之热气也；伤寒者，外感于寒邪也。夫伤寒之寒热者，恶寒为表热里和，故恶寒脉浮大也；发热为里热表和，故发热脉滑实也。可以吐法而解之，用拔雪汤主之。生姜、葱白、豆豉同煎葶苈苦酒汤，上而越之。若病人脉沉实者，或不大便，喘满𧮪语，不必拘日数，急攻于里，可用通解丸；胃中渴燥者，大承气汤下之。慎不可用银粉、巴豆粉霜、杏仁、芫花热性之药，用之必致危殆。仲景云：调理伤寒者，皆在汗、下之理。当明表里，无不愈矣！差之毫厘，失之千里，深可慎之。汗、下之后，切宜慎口，可服淡粥而养之，不然，其病复作。", "19160": "又论伤寒七八日，潮热腹满，发黄有斑者，何脏使然？《内经》云：手太阴肺经，足太阴脾经，足阳明胃经，手少阴心经，此四经受病也，仲景云，两寸口脉俱浮滑，胸中有痰攻上者，可用瓜蒂散吐之；吐后，随证调治处药。发黄之证，皆因阳明中风，太阳中湿，瘀血与宿谷相抟，令人发黄。煎栀子茵陈蒿汤，调加减五苓散服之后，利小便快者，如皂角色汁，此为效矣。发斑者，心经受热，故有此证。详斑轻重用药之理：轻者斑红，可用越桃饮子；重者斑紫，毒气胃中盛也，大青四物汤、元参升麻汤主之。潮热腹满者，谓邪热在胃中也，可以荡涤邪热，流湿润燥，宜急治之。杂病寸口脉沉实者，亦在胸中。有启玄子注云：上盈不愈者，吐而夺之，此病乃瘳矣。斑黑者，危而难治也。黄病血病，问其小便利与不利也，验又有头痛数日不止者，此乃六阳受病也。手之三阳，从手走至于头；足之三阳，从上走至于下。盖六阳之聚会也。久痛不愈者，令人丧目，以胸膈亦有宿痰故也。先以羌活散涌之，以川芎石膏散、白虎汤，选而服之则愈矣。", "19161": "又一法：治头痛不愈者，可煎连须葱白豆豉汤，多服之，后吐为效；吐后，可服川芎薄荷汤，辛凉之剂，清上之药，疏风丸散之类。仲景云：伤寒头痛，脉寸口急而头痛是也。", "19162": "凡人病心胸痞闷，不欲饮食，身体壮热，口燥舌干，大小便不利。有一工治之，说下元虚冷，便投暖药十数服，其病不愈。又一医所论与前亦同，又投暖药五、七日，其证转加困弱。请余治之。诊脉而说曰：审问日数、饮食、大小便何似？小便赤色，大便黑色。便言伤寒瘀血之证，初用大黄芍药汤二剂，次服犀角地黄汤二服，后用通经丸一服，换过大便黄色，以为效验。此药服十余服，方可病瘥矣。", "19163": "凡男子妇人，所显证候，皮肤发热，肌肉消瘦，四肢倦怠，兼有头痛颊赤，心忪，唇干舌燥，日晡潮热，夜有盗汗，涕唾稠黏，胸膈不利，或时喘嗽，五心烦热，睡卧不安，饮食减少，多思水浆，经脉不通，病名曰何病？《奇病论》曰：女子不月，血滞之病也；男子肾虚，精不足也。凡治此证，降心火、益肾水，此之谓也。可先用通解丸，泻三、二行，次服当归饮子，又用加减五苓散、木香三棱丸、人参黄耆散、犀角散之类，详其虚实，选而用之。若咯脓咯血，大小便血，但亡血者，不可宣吐，勿服酸辛热物姜附之类药，不可不戒慎也。若犯诸亡血之证者，不可发汗，不可温补。脾胃之药若服之，虽进饮食，不生肌肉，此病转加危笃，乃成虚劳之病也。", "19164": "凡医人不明发表攻里，乱投汤剂，有误性命。更大忌夏月燔灸中脘、脐下、关元、气海背俞、三里等。燔灸千百壮者，全无一效，使病者反受其殃，岂不痛哉？虚劳之疾，私嗜肉、食、面、辛酸之物，不可食之。但可食者，谨按神农食疗而与之。菠棱葵菜、冰水清凉之物，不可禁也。且图寒凉滑利肠胃，使气血并无壅碍燥涩。《经》曰：谷入于胃，脉道乃行；水入于经，其血乃成。若不忌慎，致令病人胃口闭涩，则形体渐瘦，此乃死之由也。诸劳皆仿此。但诸人咯脓血、衄血、大小便血者，可服三黄丸、黄连解毒丸、凉膈散加桔梗、当归、大黄、芍药、犀角地黄汤，大作剂料，时时呷之。《内经》曰：所谓邪热伤于肝心之病，依此调治，万举万全矣。", "19165": "凡人有脏毒下血，何谓也？《生气通天论》曰：邪热伤肝，因而大饱，筋脉横解，肠澼为痔。故脓血者，血随热行，参差入于肠胃之间，乃成泻血也。若身体壮热，则为难治；身凉者，可治也。可先调中消血，荡除积血，泻之三、二行；泻后，服芍药柏皮丸、黄连解毒汤、五苓散、益元散各停，新汲水调下五、七钱。甚者取地黄汁半盏，服之则愈矣。", "19166": "凡男子妇人，骨蒸热发，皮肤枯干，痰唾稠黏，四肢疼痛，面赤唇焦，盗汗烦躁，睡卧不安，或时喘嗽，饮食无味，困弱无力，虚汗黄瘦等证，《内经》曰：男子因精不足，女子因血不流，而得此证。可以茶调散，轻涌讫；次以导水丸、禹功散，轻泻三、五行；后服柴胡饮子、桂苓甘露散、犀角散之类。大搜风丸、白术丸、调中汤、木香槟榔丸、人参散，量虚实选而用之。或咯血、便血，诸亡血者，并不宜吐，不可不知。慎勿服峻热姜、附之药。若服之，饮食难进，肌肉消减，转加危笃。五劳之病，今人不明发表攻里，遂误至此。大忌暑月于手腕、足踝上著灸。以其手足者，诸阳之表，起于五指之外。《内经》曰：诸阳发四肢。此穴皆是浅薄之处，灸疮最难痊也。及胸穴、中脘、脐下、背俞、三里等穴，或有灸数百壮者，加以燔针，略无寸效，病人反受苦楚，可不思之？劳疾多馋，所思之物，但可食者，宜照食疗本草而与。菠菜、葵羹、冰水凉物，慎不可禁。且因水谷入胃，脉道乃行也。若遇禁则胃口闭而形体渐瘦而脉大，乃死之候也。诸劳皆仿此。", "19167": "凡痔瘘肿痛，《内经》曰：因而大饱，筋脉横解，肠澼为痔而不愈，变为瘘。痔与瘘，其治同法。《至真要大论》云：太阳之胜，凝凓且至，非时水冰，痔疟乃发。注云：水气太胜，阳火不行，此言阳火畏水郁而为痔。又少阴之复，痱疹疮疡，痈疽痤痔。注云：火气内蒸，金气外拒，阳热内郁，故为痱疹疮疡。疹甚亦为疮也。热少则外生痱疹，热多则内结痈痤。小肠有热，则中外为痔。其复热之变，皆病于身后及外侧也。又《灵枢》云：太阳经虚则为痔疟癫疾。盖水虚则火所乘故也。可先用导水丸、禹功散；泻讫，次服枳壳丸、木香槟榔丸；更以葵羹、菠菜，通利肠胃。大忌房室及鸡、鱼、酒、醋辛热之物。", "19168": "凡便痈者，谬名也，乃男子血疝也，《难》《素》所不载。然而是厥阴肝之经络，乃血流行之道路也。冲脉、任脉、督脉，亦属肝经之旁络也。《难经》曰：男子七疝。血疝者，乃七疝之一也。治以导水丸、桃仁承气汤，或抵当汤，投之同瘀血法。聚而不散，可以大作剂料，大泻一、二十行；次以玉烛散，和血通经之类是也。世人多用大黄、牡蛎，间有不愈者，是不知和血通经之道也。", "19169": "凡妇人乳痈发痛者，亦生于心也，俗呼吹奶是也。吹者，风也。风热结于乳房之间，血脉凝注，久而不散，溃腐为脓。宜用益元散，生姜汤调下，冷服；或新汲水，时时呷之勿辍，昼夜可三、五十次，自解矣；或煎解毒汤，顿服之。", "19170": "凡妇人年五十以上，经脉暴下。妇人经血，终于七七之数。数外暴下者，此乃《内经》所谓火主暴速，亦因暴喜暴怒，忧愁惊恐致然。慎勿作冷病治之。如下峻热药治之必死。止宜黄连解毒汤以清上，更用莲壳、棕毛灰以渗其下，然后用四物汤、玄胡索散，凉血和经之药也。", "19171": "凡妇人月事不来，室女亦同，《内经》曰：谓月事不来，皆是胞脉闭也。胞脉者，属心而络于胞中。令气上通于肺，心下不通，故月事不来也。可用茶调散吐之；次用玉烛散、芎䓖汤、三和汤、桂苓白术散之类，降心火，益肾水，开胃进食，分阴阳，利水道之药皆是也。慎勿服峻热有毒之药。若服之，变成肺痿，骨蒸潮热，咳嗽咯脓，呕血喘满，小便不利，寝汗不止，渐至形瘦脉大，虽遇良医，亦成不救。呜呼！人之死者，岂命使之然也。", "19172": "凡妇人身重，九月而喑哑不言者，是胞之络脉不相续也，故不能言。《经》曰：无治也。然有是言，不若煎玉烛散二两，水半碗，同煎至七分，去滓，入蜜，放温，时时呷之，令火下降，肺金自清，故声复出也。肺主声音也。", "19173": "凡妇人年二、三十，无病而无子，经血如常，或经血不调者，乃阴不升而阳不降，此上下不得交通，有所滞碍，不能为用故也。可用独圣散，涌讫寒痰二、三升；后用导水丸、禹功散，泄三、五行或十余行；单用无忧散，泄十余行，见寒热虚实用之；次服葱白粥三、五日。胃气宣通，肠中得实，可服玉烛散，更助白术散、茯苓之类。降火益水，既济之道，当不数月而有孕。《内经》曰：妇人有癃、痔、遗溺、嗌干诸症，虽服妙药针灸，亦不能孕。盖冲脉、督脉、任脉有此病不能孕故也。", "19174": "凡妇人半产，俗呼曰「小产」。或三、四月，或五、六个月，皆为半产，以男女成形故也。或因忧恐暴怒、悲哀太甚，或因劳力扑打损伤，及触冒暑热。慎勿用黑神散，以其犯热药，恐转生他疾。止宜用玉烛散、和经汤之类。凡妇人天生无乳者，不治。或因啼泣、暴怒、郁结，气血闭塞，以致乳脉不通，用精猪肉清汤，调和美味，于食后调益元散五七钱，连服三、五服；更用木梳梳乳房周回，则乳汁自下也。", "19175": "加甘遂一两，去湿热腰痛，泄水湿肿满；久病，则加。白芥子一两，去遍身走注疼痛；或加朴硝一两，退热，散肿毒，止痛；久毒，宜加。郁李仁一两，散结滞，通关节，润肠胃，行滞气，通血脉；或加樟柳根一两，去腰腿沉重。", "19176": "《五常政大论》曰：根于中者，命曰神机。是为动物，根本在于中也。根本者，脾、胃、肾也。食入胃，则脾为布化气味，荣养五脏百骸。故酸入肝而养筋膜；苦入心而养血脉；甘入脾而养肌肉；辛入肺而养皮毛；咸入肾而养骨髓。五气亦然。故清养肺，热养心，温养肝，湿养脾，寒养肾也。凡此五味五气，太过则病，不及亦病，惟平则常安矣。故《六节藏象论》曰：五味入口，藏于肠胃，味有所藏，以养五气，气和而生，津液相成，神乃自生。是其理也。又《太阴阳明论》云：脾病而四肢不用者，何也？岐伯曰：四肢皆禀气于胃，而不得至经，必因于脾乃得禀也。今脾病不能为胃行其津液，不得禀水谷气，气日以衰，脉道不利，筋骨肌肉，皆无气以生，故不用焉。帝曰：脾不主时，何也？岐伯曰：脾者，土也，治中央，常以四时长四脏，各十八日寄治，不得独主于时也。脏藏者，常著胃土之精也。土者生万物，而法天地。故上下至头足，不得独主于时也。", "19177": "帝曰：脾与胃，以膜相连尔，而能行其津液，何也？岐伯曰：足太阴者，三阴也，其脉贯胃，属脾络嗌。故太阴为之行气于三阴。足阳明者，表也，五脏六腑之海也，亦为之行气于三阳。脏腑各因其经而受气，以益阳明，故为胃行其津液。四肢不得禀水谷，气日以衰，阴道不利，筋骨肌肉，皆无气以生，故不用焉。不用者，谓不能为之运用也。由是观之，则五脏六腑，四肢百骸，皆禀受于脾胃，行其津液，相与濡润滋养矣。后之医者，欲以燥热之剂，以养脾胃，滋土之气，不亦外乎？况消渴之病者，本湿寒之阴气极衰，燥热之阳气太甚，更服燥热之药，则脾胃之气竭矣。叔世不分五运六气之虚实，而一概言热为实，而虚为寒，彼但知心火阳热一气之虚实，而非脏腑六气之虚实也。盖肺本清，虚则温；心本热，虚则寒；肝本温，虚则清；脾本湿，虚则燥；肾本寒，虚则热。假若胃冷为虚者，乃胃中阴水寒气实甚，而阳火热气衰虚也，非胃土湿气之本衰，故当温补胃中阳火之衰，退其阴水寒气之甚。又如胃热为实者，乃胃中阳火实而阴水虚也，故当以寒药，泻胃中之实火，而养其虚水。然此皆补泻胃中虚热，水火所乘之邪，非胃为湿者之本。其余例同法。夫补泻脾胃湿土之水气者，润其湿者是补湿，燥其湿者是泻湿，土本湿故也。", "19178": "余闻世之方，多一方而通治三消渴者，以其善消水谷而喜渴也。然叔世论消渴者，多不知本。其言消渴者，上实热而下虚冷。上热故烦渴多饮，下寒故小便多出。本因下部肾水虚，而不能制其上焦心火，故上实热而下虚冷。又曰：水数一，为物之本，五行之先。故肾水者，人之本，命之元，不可使之衰弱。根本不坚，则枝叶不茂；元气不固，则形体不荣。消渴病者，下部肾水极冷，若更服寒药，则元气转虚，而下部肾水转衰，则上焦心火亢甚而难治也。但以暖药补养元气，若下部肾水得实而胜退上焦火，则自然渴止，小便如常而病愈也。若此之言，正与仲景相反。所以巧言似是，于理实违者也。非徒今日之误，误已久哉！又如蒋氏《药证病原》中，论消渴、消中、消肾病曰：三焦五脏俱虚热，惟有膀胱冷似冰。又曰：腰肾虚冷日增重。又曰：膀胱肾脏冷如泉。始言三焦五脏俱虚热，惟有膀胱冷似冰，复言五脏亦冷，且肾脏水冷言为虚，其余热者，又皆言其虚。夫阴阳兴衰，安有此理？且其言自不相副，其失犹小，至于寒热差殊，用药相反，过莫大焉！或又谓：肾与膀胱属水，虚则不能制火。虚既不能制火，故小便多者，愈失之远矣。彼谓水气实者，必能制火，虚者不能制火。故阳实阴虚，而热燥其液，小便淋而常少；阴实阳虚，不能制水，小便利而常多。岂知消渴小便多者，非谓此也。何哉？盖燥热太甚，而三焦肠胃之腠理，怫郁结滞，致密壅塞，而水液不能渗泄浸润于外，荣养百骸。故肠胃之外燥热太甚，虽复多饮于中，终不能浸润于外，故渴不止。小便多出者，如其多饮，不能渗泄于肠胃之外，故数溲也。故余尽言《原病式》曰：皮肤之汗孔者，谓泄汗之孔窍也。一名气门者，谓泄气之门户也。一名腠理者，谓气液之隧道纹理也。一名鬼门者，谓幽冥之门也。一名玄府者，谓玄微之府也。然玄府者，无物不有。人之脏腑皮毛，肌肉筋膜，骨髓爪牙，至于万物，悉皆有之，乃出入升降，道路门户也。故《经》曰：出入废则神机化灭，升降息则气立孤危。故非出入，则无以生长壮老已；非升降，则无以生长化收藏。是知出入升降，无器不有。故知人之眼、耳、鼻、舌、身、意、神、识，能为用者，皆有升降出入之通利也。有所闭塞，则不能用也。若目无所见，耳无所闻，鼻不闻香，舌不知味，筋痿骨痹，爪退齿腐，毛发堕落，皮肤不仁，肠胃不能渗泄者，悉有热气怫郁，玄府闭塞，而致津液血脉，荣卫清气，不能升降出入故也。各随郁结微甚，而有病之大小焉。病在表则怫郁，腠理闭密，阳气不能散越，故燥而无汗，而气液不能出矣。叔世不知其然，故见消渴数溲，妄言为下部寒尔。岂知肠胃燥热怫郁使之然也？予之所以举此，世为消渴之证，乃肠胃之外燥热，痞闭其渗泄之道路，水虽入肠胃之内，不能渗泄于外，故小便数出而复渴。此数句，足以尽其理也。", "19179": "所谓肾热而渴者，《刺热论》曰：肾热病者，先腰痛胻酸，苦渴数饮，身热。《热论》曰：少阴脉贯肾，络于肺，系舌本，故口燥舌干而渴。叔世惟言肾虚不能制心火，为上实热而下虚冷，以热药温补肾水，欲令胜退心火者，未明阴阳虚实之道也。夫肾水属阴而本寒，虚则为热；心火属阳而本热，虚则为寒。若肾水阴虚，则心火阳实，是谓阳实阴虚，而上下俱热明矣。故《气厥论》曰：肾气衰，阳气独胜。《宣明五气论》曰：肾恶燥，由燥肾枯水涸。《藏气法时论》曰：肾苦燥，急食辛以润之。夫寒物属阴，能养水而泻心；热物属阳，能养火而耗水。今肾水既不胜心火，则上下俱热，奈何以热药养肾水？欲令胜心火，岂不谬哉？", "19180": "又如胃与大肠热结而渴者，《阴阳别论》：二阳结为之消。注曰：阳结，胃及大肠俱热结也。肠胃藏热，善消水谷。又《气厥论》曰：大肠移热于胃，善食而瘦。《脉要精微论》曰：瘅成为消中，善食而瘦。", "19181": "夫标本之道，要而博，小而大，可以言一而知百。言标与本，易而弗损。察本与标，气可令调。明知胜复，为万民式，天之道毕矣。《天元纪大论》曰：至数极而道不惑。可谓明矣。所谓药之巧能者，温凉不同，寒热相反，燥湿本异云云，前已言之矣。斯言气也，至于味之巧能，如酸能收，甘能缓，辛能散，苦能坚，咸能软，酸属木也。燥金主于散落而木反之，土湿主于缓而水胜之，故能然也。若能燥湿而坚火者，苦也。《易》曰：燥万物者，莫燥乎火。凡物燥则坚也。甘能缓苦急而散结。甘者，土也。燥能急结，故缓则急散也。辛能散抑、散结、润燥。辛者，金也。金主散落，金生水故也。况抑结散，则气液宣行而津液生也。《藏气法时论》曰：肾苦燥，急食辛以润之。开腠理，致津液，通气也。咸能软坚。咸者，水也。水润而柔，故胜火之坚矣。此五脏之味也。其为五味之本也淡也。淡，胃土之味也。胃土者，地也。地为万物之本，胃为一身之本。《天元纪大论》曰：在地为化，化生五味。故五味之本淡也。以配胃土，淡能渗泄利窍。夫燥能急结，而甘能缓之；淡为刚土，极能润燥，缓其急结，令气通行，而致津液渗泄也。故消渴之人，其药与食，皆宜淡剂。《至真要大论》曰：辛甘发散为阳，酸苦涌泄为阴；咸味涌泄为阴，淡味渗泄为阳。六者，或散，或收，或缓，或急，或燥，或润，或坚，或软，所以利而行之，调其气也。《本草》云：药有三品：上品为君，主养命，小毒，以应天；中品为臣，主养性，常毒，以应人；下品为佐使，主治病，大毒，以应地。不在三品者，气毒之物也。凡此君臣佐使者，所以明药之善恶也。处方之道，主治病者为君，佐君者为臣，应臣之用者为佐使。适其病之所根，有君、臣、佐、使、奇、偶、小、大之制；明其岁政君臣脉位，而有逆、顺、反、正、主疗之方，随病所宜以施用。", "19182": "病人面白目黑者，死。此谓荣华已去，血脉空索。", "19183": "诊目病，赤脉从上下者，太阳病也；从下上者，阳明病也；从外入内者，少阳病也。", "19184": "诊寒热瘰疬，目中有赤脉，从上下至瞳子，见一脉，一岁死；见一脉半，一岁半死；见二脉，二岁死；见二脉半，二岁半死；见三脉，三岁死。", "19185": "诊牙齿痛，按其阳明之脉来太过者，独热在右，右热；热在左，左热；热在上，上热；热在下，下热。", "19186": "诊血者，脉多赤多热，多青多痛，多黑多黄，多痹多赤，多黑多青，皆见者，寒热身痛，面色微，齿垢，黄爪甲上，黄疸也。安卧少黄赤，脉小而涩者，不嗜食。", "19187": "诊伤寒热盛，脉浮大者，生；沉小者，死。", "19188": "伤寒已得汗，脉沉小者，生；浮大者，死。", "19189": "温病三、四日以下，不得汗，脉大疾者，生；脉细小难得者，死不治。", "19190": "温病穰穰大热，其脉细小者，死。（《千金》「穰穰」「作时行」）", "19191": "厥逆汗出，脉坚强急者，生；虚缓者，死。", "19192": "温病二、三日，身体热，腹满，头痛，食如故，脉直而疾者，八日死；四、五日，头痛，腹痛而吐，脉来细强，十二日死；八、九日，头不痛，身不痛，目不变，色不变而反利，脉来喋喋，按之不弹手，时时，心下坚，十七日死。", "19193": "热病七、八日，脉不软（一作喘）、不散（一作数）者，当有喑，喑后三日，温汗不出者，死。", "19194": "热病七、八日，其脉微细，小便不利，加暴口燥，脉代，舌焦干黑者，死。", "19195": "热病未得汗，脉盛躁疾，得汗者，生；不得汗者，难瘥。", "19196": "热病已得汗，脉静安者，生；脉躁者，难治。", "19197": "热病已得汗，热未去，脉微躁者，慎不得刺治。", "19198": "热病发热，热甚者，其脉阴阳皆竭，慎勿刺，不汗出，必下利。", "19199": "诊人被风，不仁，痿蹶，其脉虚者，生；坚急疾者，死。", "19200": "诊癫病，脉实坚者，生；脉沉细者，死。", "19201": "又癫疾，脉得大滑者，久而自已，其脉沉小急实，不可疗；小坚急者，亦不可疗也。", "19202": "诊人心腹积聚，其脉坚强急者，生；虚弱者，死。又实强者，生；沉者，死。其脉大，腹大胀，四肢逆冷，其人脉形长者，死；腹胀满，便血，脉大时绝，极下血，小疾者，死。", "19203": "肠澼下白沫，脉沉则生，浮则死。", "19204": "肠澼下脓血，脉悬绝则死，滑大则生。", "19205": "肠澼之属，身热，脉不悬绝，滑大者，生；悬涩者，死。以脏期之。", "19206": "肠澼下脓血，脉沉小留连者，生；数疾且大，有热者死。", "19207": "肠澼筋挛，其脉小细安静者，生；浮大紧者，死。", "19208": "洞泄食不化，不得留，下脓血，脉微小者，生；紧急者，死。", "19209": "泄注，脉缓时小结者，生；浮大数者，死。", "19210": "蚕蚀阴注，其脉虚小者，生；紧急者，死。", "19211": "咳嗽，脉沉紧者，死，浮直者，浮软者，生，小沉伏匿者，死。", "19212": "咳嗽羸瘦，脉形坚大者，死。", "19213": "咳，脱形发热，脉小坚急者，死；", "19214": "咳而呕，腹胀且泄，其脉弦急欲绝者，死。", "19215": "吐血、衄血，脉滑小弱者，生；实大者，死。", "19216": "汗若衄，其脉小滑者，生；大躁者，死。", "19217": "吐血脉紧强者，死；滑者，生。", "19218": "吐血而咳上气，其脉数有热，不得卧者，死。", "19219": "上气脉数者，死，谓损形故也。", "19220": "上气喘息低昂，其脉滑，手足温者，生；脉涩，四肢寒者，必死。", "19221": "上气面浮肿，肩息，其脉大，不可治，加利必死。", "19222": "上气注液，其脉虚宁伏匿者，生；坚强者，死。", "19223": "寒气上攻，脉实而顺滑者，生；实而逆涩死。（《太素》云：寒气在上，脉满实何如？曰：实而滑则生，实而逆则死矣。其形尽满何如？曰：举形尽满者，脉急大坚，尺满而不应。如是者，顺则生，逆则死。何谓顺则生，逆则死？所谓顺者，手足温也；逆者，手足寒也）", "19224": "病瘅，脉实大，病久可治；脉弦小坚急，病久不可治。", "19225": "消渴，脉数大者，生；细小浮短者，死。", "19226": "消渴，脉沉小者，生；实坚大者，死。", "19227": "水病，脉洪大者，可治；微细，不可治。", "19228": "水病胀闭，其脉浮大软者，生；沉细虚小者，死。", "19229": "水病腹大如鼓，脉实者，生；虚则死。", "19230": "卒中恶咯血数升，脉沉数细者，死；浮大疾快者，生。", "19231": "卒中恶腹大，四肢满，脉大而缓者，生；紧大而浮者，死；紧细而微，亦生。", "19232": "寒热瘛疭，其脉代绝者，死。", "19233": "金疮血出太多，其脉虚细者，生；数实大者，死。", "19234": "金疮出血，脉沉小者，生；浮大者，死。", "19235": "斫疮出血一、二升，脉来大，二十日死。", "19236": "斫刺俱有病，多少血出不自止者，其脉来大者，七日死，滑细者生。", "19237": "从高顿仆，内有血，腹胀满，其脉坚强者，生；小弱者，死。", "19238": "人为百药所中伤，脉涩而疾者，生；微细者，死；洪大而迟者，生（《千金》「迟」作「速」）。", "19239": "人病甚而脉不调者，难治；脉洪大者，易瘥。", "19240": "脉实满，手足寒，头热，春秋生，冬夏必死矣。", "19241": "老人脉微，阳羸阴强者，生；脉大加息者，死；阴弱阳强，脉至而代，期月而死。", "19242": "尺脉涩而坚，为血实气虚也。其发病，腹痛逆满，气上行。此为妇人胞中绝伤，有恶血，久成结瘕，得病以冬时，黍穄赤而死。", "19243": "尺脉细而微者，血气俱不足；细而来有力者，是谷气不充；病得节辄动，枣叶生而死。此病秋时得之。", "19244": "左手寸口脉偏动，乍大乍小不齐，从寸至关，关至尺，三部之位，其脉动，各异不同，其人病仲夏得之，此脉桃花落而死。", "19245": "右手寸口，脉偏沉伏，乍小乍大，朝浮大，而暮沉伏。浮大即太过，上出鱼际；沉伏即下，不至关中。往来无常，时复来者，榆叶枯落而死。", "19246": "右手尺部脉，三十动一止，有顷更还，二十动一止，乍动乍疏，连连相因，因不与息数相应，其人虽食谷，犹不愈，蘩草生而死。", "19247": "右手尺部脉，四十动而一止，止而复来，来逆如循张弓弦，𫄠𫄠然，如两人共引一索，至立冬死。", "19248": "阴阳应象论云水谷之寒热感则害人六腑痹论云阴气者静则神藏躁则消亡饮食自倍肠胃乃伤此乃混言之也分之为二饮也食也饮者水也无形之气也因而大饮则气逆形寒饮冷则伤肺病则为喘咳为肿满为水泻轻则当发汗利小便使上下分消其湿解酲汤五苓散生姜半夏枳实白术之类是也如重而蓄积为满者芫花大戟甘遂牵牛之属利下之此其治也食者物也有形之血也如生气通天论云因而饱食筋脉横解肠澼为痔又云食伤太阴厥阴寸口大于人迎两倍三倍者或呕吐或痞满或下痢肠澼当分寒热轻重而治之轻则内消重则除下如伤寒物者半夏神曲干姜三棱广术巴豆之类主之如伤热物者枳实白术青皮陈皮麦蘖黄连大黄之类主之亦有宜吐者阴阳应象论云在上者因而越之瓜蒂散之属主之然而不可过剂过剂则反伤肠胃盖先因饮食自伤又加之以药过故肠胃复伤而气不能化食愈难消矣渐至羸困故五常政大论云大毒治病十去其六小毒治病十去其七凡毒治病不可过之此圣人之深戒也", "19249": "调经篇云阴虚生内热岐伯曰有所劳倦形气衰少谷气不盛上焦不行下脘不通而胃气热热气熏胸中故内热举痛论云劳则气耗劳则喘且汗出内外皆越故气耗矣夫喜怒不节起居不时有所劳伤皆损其气气衰则火旺火旺则乘其脾土脾主四肢故困热无气以动懒于语言动作喘乏表热自汗心烦不安当病之时宜安心静坐以养其气以甘寒泻其热火以酸味收其散气以甘温补其中气经言劳者温之损者温之者是也金匮要略云平人脉大为劳脉极虚亦为劳矣夫劳之为病其脉浮大手足烦热春夏剧秋冬瘥脉大者热邪也极热者气损也春夏剧者时助邪也秋冬瘥者时胜邪也以黄耆建中汤治之此亦温之之意也夫上古圣人饮食有节起居有常不妄作劳形与神俱百岁乃去此谓治未病也今时之人去圣人久远则不然饮食失节起居失宜妄作劳役形气俱伤故病而后药之是治其已病也推其百病之源皆因饮食劳倦而胃气元气散解不能滋荣百脉灌溉脏腑卫护周身之所致也故苍天之气贵清静阳气恶烦劳噫饮食喜怒之间寒暑起居之际可不慎欤", "19250": "治因饥饱劳役损伤脾胃元气不足其脉弦洪缓而沉按之中之下得时一涩其证四肢满闷肢节疼痛难以屈伸身体沉重烦心不安忽肥忽瘦四肢懒倦口失滋味腹难舒伸大小便清利而数或上饮下便或大便涩滞或夏月餐泄米谷不化或便后见血或便见白脓胸满短气咽膈不通痰唾稠黏口中沃沫食入反出耳鸣耳聋目中流火视物昏花胬肉红丝热壅头目不得安卧不思饮食并皆治之", "19251": "如大便虚坐不得或大便了而不了腹中常常逼迫皆是血虚血涩加当归身（三分）无此证则去之如身体沉重虽小便数多亦加茯苓（二分）黄柏（三分）泽泻（五分）苍术（一钱）时暂从权而去湿也不可常用兼足太阴已病其脉亦络于心中故显湿热相合而生烦乱", "19252": "如秋冬之月胃脉四道为冲脉所逆胁下少阳脉二道而反上行名曰厥逆其证气上冲咽不得息而喘息有音不得卧加吴茱萸（五分至一钱汤洗去苦）观厥气多少而用之亦于前药中作一服服之", "19253": "上为细末熟汤为丸如梧桐子大每服一百丸或二百丸白汤送下空心服仍多饮热汤服毕少时便以美食压之使不令胃中停留直至下元以泻冲脉之邪也大抵治饮食劳倦所得之病乃虚劳七损证也常宜以甘温平之甘多辛少是其治也", "19254": "易水张先生常戒不可峻利食药下咽未至药丸施化其标皮之力始开便言快也所伤之物已去若更待一两时辰许药尽化开其药峻利必有情性病去之后脾胃既损是真气元气败坏促人之寿当时设下一药枳实一两麸炒黄色为度白术二两只此二味荷叶裹烧饭为丸以白术甘温甘温补脾胃之元气其苦味除胃中之湿热利腰脐间血故先补脾胃之弱过于枳实克化之药一倍枳实味苦寒泄心下之痞闷消化胃中所伤此一药下胃其所伤不能即去须侍一两时辰许食则消化是先补其虚而后化其所伤则不峻利矣当是之时未悟用荷叶烧饭为丸之理老年味之始得可谓奇矣荷叶之物中央空象震卦之体震者动也人感之生足少阳甲胆者风也生化万物之根蒂也内经云履端于始序则不愆人之饮食入胃营气上行即少阳甲胆之气也其手少阳三焦经人之元气也手足经同法便是少阳元气生发也胃气谷气元气甲胆上升之气一也异名虽多止是胃气上升者也荷叶之体生于水土之下出于污秽之中不为所染挺然独立其色青形乃空青而象风木者也食药感此气之化胃气何由不上升乎其主意用此一味为引用可谓远识深虑合于道者也更以烧饭和药与白术协力滋养谷气而补令胃厚再不至内伤其利广矣大矣若内伤脾胃辛热之物酒肉之类自觉不快觅药于医医者亦不问所伤敷之集香丸小丁香丸巴豆大热药之类下之大便下则物去遗留食之热性药之热性重伤元气则七神不炽经云热伤气正谓此也其人必无气以动而热困四肢不举传变诸疾不可胜数使人真气自此衰矣若伤生冷硬物世医或用大黄牵牛二味大寒药投之随药下所伤去矣遗留食之寒性药之寒性重泻其阳阳去则皮肤筋肉血脉无所依倚便为虚损之证论言及此令人寒心夫辛辣薄味之药无故不可乱服非止牵牛而已至真要大论云五味入口各先逐其所喜攻攻者克伐泻也辛味下咽先攻泻肺之五气气者真气元气也其牵牛之辛辣猛烈伤人尤甚饮食所伤肠胃邪当以苦泄其肠胃可也肺与元气何罪之有用牵牛大罪有五此其一也况胃主血所生病为物所伤物者有形之物也皆是血病泻其气其罪二也且饮食伤之于中焦止合克化消导其食重泻上焦肺中已虚之气其罪三也食伤肠胃当塞因塞用又曰塞因塞用枳实大黄苦寒之物以泄有形是也反以辛辣牵牛散泻真气大禁四也殊不知针经有云外来客邪风寒伤人五脏若误泻胃气必死误补亦死其死也无气以动故静若内伤肠胃而反泻五脏必死误补亦死其死也阴气有余故躁今内伤肠胃是谓六腑不足之病反泻上焦虚无肺气肺者五脏之一数也虽不即死若更旬日之间必暗损人寿数谓如人寿应百岁为牵牛之类朝损暮损其元气消耗不得终其天年但人不觉耳将为天年已尽此乃暗里折人寿数大禁五也故特著此论并方庶令四海闻而行之不至夭横耳此老夫之用心也胃气不可不养复明养胃之理内经云安谷者昌绝谷者亡水去则荣散谷消则卫亡荣散卫亡神无所依仲景云水入于经其血乃成谷入于胃脉道乃行故血不可不养胃不可不温血养胃温荣卫将行常有天命谷者身之大柄也书与周礼皆云金木水火土谷惟修以奉养五脏者也内伤饮食固非细事苟妄服食药而轻生殒命其可乎哉黄帝针经有说胃恶热而喜清冷大肠恶清冷而喜热两者不和何以调之岐伯曰调此者食饮衣服亦欲适寒温寒无凄怆暑无出汗饮食热无灼灼寒无凄凄寒温中适故气将持乃不致邪僻也是必有因用岂可用俱寒俱热之药仓卒致损与以刃杀人者何异内经说内伤者其气口脉反大于人迎一倍二倍三倍分经用药又曰上部有脉下部无脉其人当吐不吐者死如但食不纳恶心欲吐者不问一倍二倍不当正与瓜蒂散吐之但以指或以物探去之若所伤之物去不尽者更诊其脉问其所伤以食药去之以应塞因塞用又谓又寒因寒用泄而下降乃应太阴之用其中更加升发之药令其元气上升塞因通用因曲而为直何为曲内伤胃气是也何为直因而升发胃气是也因其饮食之内伤而使生气增益胃气完复此乃因曲而为之直也若分经用药其所伤之物寒热温凉生硬柔软所伤不一难立定一法只随所伤之物不同各立治法临时加减用之其用药又当问病人从来禀气盛衰所伤寒物热物是喜食而食之耶不可服破气药若乘饥因而伤之耶当益胃气或为人所勉劝强食之宜损血而益气也诊其脉候伤在何脏可与对病之药岂可妄泻天真元气以轻丧身宝乎且如先食热物而不伤继之以寒物因后食致前食亦不消化而伤者当问热食寒食孰多孰少斟酌与药无不当矣喻如伤热物二分寒物一分则当用寒药二分热药一分相合而与之则荣卫之气必得周流更有或先饮酒而后伤寒冷之食及伤热食冷水与冰如此不等皆当验其节次所伤之物酌量寒热之剂分数各各对证与之无不取效自忖所定药方未敢便谓能尽药性之理姑用指迷辩惑", "19255": "六元政纪论云太阴所至为中满太阴所至为蓄满诸湿肿满皆属脾土论云脾乃阴中之太阴同湿土之化脾湿有余腹满食不化天为阳为热主运化也地为阴为湿主长养也无阳则阴不能生化故云脏寒生满病调经篇云因饮食劳倦损伤脾胃始受热中未传寒中皆由脾胃之气虚弱不能运化精微而制水谷聚而不散而成胀满经云腹满肿胀支膈胠胁下厥上冒过在太阴阳明乃寒湿郁过也脉经所谓胃中寒则胀满者是也（针经三卷杂病第八）腹满大便不利上走胸溢喘息喝喝然取足少阴又云胀取三阳三阳者足太阳寒水为胀与通评虚实论说腹暴满按之不下取太阳经络胃之募也正同取者泻也经云中满者泻之于内者是也宜以辛热散之以苦泻之淡渗利之使上下分消其湿正如开鬼门洁净府温衣缪刺其处是先泻其血络后调其真经气血平阳布神清此治之正也或曰诸胀腹大皆属于热者何也此乃病机总辞假令外伤风寒有余之邪自表传里寒变为热而作胃实腹满仲景以大承气汤治之亦有膏粱之人湿热郁于内而成胀满者此热胀之谓也大抵寒胀多而热胀少治之者宜详辨之", "19256": "诸腹胀大皆属于热此乃八益之邪有余之证自天外而入是感风寒之邪传里寒变为热作胃实曰晡潮热大渴引饮谵语是太阳阳明并大实大满者大承气下之少阳阳明微满实者小承气下之泄之则胀已此之谓也假令痎疟为胀满亦有寒胀热胀是天之邪气伤暑而得之不即时发至秋暑气衰绝而疟病作矣知其寒也局方用交解饮子者是也内虚不足寒湿令人中满及五脏六腑俱有胀满更以脉家寒热多少较之胃中寒则胀满浊气在上则生䐜胀胀取三阳三阳者足太阳膀胱寒水为胀腹暴满按之不下取太阳经络者胃之募也正同腹满䐜胀肢膈胠胁下厥上冒过在太阴阳明胃中寒湿郁遏也太阴䐜胀复不利不欲食食则呕不得卧按所说寒胀之多如此中满治法当开鬼门洁净府开鬼门者谓发汗也洁净府者利小便也中满者泻之于内谓脾胃有病当令上下分消其温下焦如渎气血自然分化不待泄滓秽如或大实大满大小便不利从权以寒热药下之或伤酒湿面及味厚之物膏粱之人或食已便卧使湿热之气不得施化致令腹胀满此胀亦是热胀治热胀分消丸主之", "19257": "治右关脉弦心下虚痞恶食懒倦开胃进饮食", "19258": "治脾胃虚弱而心火乘之不能滋荣上焦元气遇冬肾与膀胱寒水旺时子能令母实以致肺金大肠相辅而来克心乘脾胃此大复仇也经云大胜必大复理之常也故皮毛血脉分肉之间元气已绝于外又大寒大燥二气并乘之则苦恶风寒耳鸣及腰背相引而痛鼻息不通不闻香臭额寒脑痛大恶风寒目时眩不欲开腹中为寒水反乘痰唾沃沫食则反出腹中常痛心胃作痛胁下缩急有时而痛腹不能努大便多泻而少秘下气不绝或腹中鸣此脾胃虚之至极也胸中气乱心烦不安而为霍乱之渐咽膈不通极则噎塞有声喘喝闭塞或于日阳处或于暖室中少缓口吸风寒之气则复作四肢厥逆身体沉重不能转侧头不可以回顾小便溲而时躁此药主之秋冬寒凉大复气之药也", "19259": "上部有脉下部无脉其人当吐不吐者死何谓下部无脉此谓木郁也饮食过饱填塞胸中胸中者太阴之分野经曰气口反大于人迎三倍食伤太阴故曰木郁则达之吐者是也", "19260": "上二味为极细末每服二钱匕温浆水调下取吐为度若不至两手尺脉绝无不宜便用此药恐损元气令人胃气不复若止是胸中窒塞闷乱不通以指探去之如不得吐者以物探去之得吐则已如食不去用此药吐之解云盛食填塞于胸中为之窒塞两寸脉当主事两尺脉不见其理安在胸中有食故以吐出之食者物也物者坤土也是足太阴之号也胸中者肺也为物所填肺者手太阴金也金主杀伐也与坤土俱在于上而旺于天金能克木故肝木生发之气伏于地下非木郁而何吐去上焦阴土之物木得舒畅则郁结去矣食塞于上脉绝于下若不明天地之道无由达此至理水火者阴阳之征兆天地之别名也故曰独阳不生独阴不长天之用在于地下则万物生长矣地之用在于天上则万物收藏矣此乃天地交而万物通也此天地相根之道也故阳火之根本于地下阴水之源本于天上故曰水出高源故人五脏主有形之物物者阴也阴者水也右三部脉主之偏见于寸口食塞其二是绝五脏之源源绝则水不下流两尺竭绝此其理也何疑之有假令所伤前后不同以分为率伤热物二分伤生冷硬物一分用寒药三黄丸二停热药巴豆三棱丸一停合而服之如热物伤少而寒物伤多则寒药少而热药多也假令夏月大热之时伤生冷硬物当用热药巴豆三棱丸治之须加三黄丸谓天时不可伐故加寒药以顺时令若热物只用三黄丸何谓此三黄丸时药也假令冬天大寒之时伤羊肉湿面等热物当用三黄丸治之须加热药少许草豆蔻丸之类是也为引用又为时药经云必先岁气无伐天和此之谓也余皆仿此", "19261": "阴阳别论云二阳结谓之消脉要精微论云瘅成为消中夫二阳者阳明也手阳明大肠主津病消则目黄口干是津不足也足阳明胃主血热则消谷善饥血中伏火乃血不足也结者津液不足结而不润皆燥热为病也此因数食甘美而多肥故其气上溢转为消渴治之以兰除陈气也不可服膏粱芳草石药其气剽悍能助燥热也越人云邪在六腑则阳脉不和阳脉不和则气留之气留之则阳脉盛矣阳脉大盛则阴气不得荣也故皮肤肌肉消削是也经云凡治消瘅仆系偏枯痿厥气满发逆肥贵人则膏粱之疾也岐伯曰脉实病久可治脉弦小病久不可治后分为三消高消者舌上赤裂大渴引饮逆调论云心移热于肺传于膈消者是也以白虎加人参汤治之中消者善食而瘦自汗大便硬小便数叔和云口干饮水多食亦肌虚瘅成消中者是也以调胃承气三黄丸治之下消者烦躁引饮耳轮焦干小便如膏叔和云焦烦水易亏此肾消也以六味地黄丸治之总录所谓末传能食者必发脑疽背疮不能食者必传中满鼓胀皆谓不治之证洁古老人分而治之能食而渴者白虎加人参汤不能食而渴者钱氏方白术散倍加葛根治之上中既平不复传下消矣前人用药厥有旨哉或曰未传疮疽者何也此火邪胜也其疮痛甚而不溃或赤水者是也经云有形而不痛阳之类也急攻其阳无攻其阴治在下焦元气得强者生失强者死未传中满者何也以寒治热虽方士不能废其绳墨而更其道也然脏腑有远近心肺位近宜制小其服肾肝位远宜制大其服皆适其至所为故知过与不及皆诛罚无过之地也如高消中消制之太急速过病所久而成中满之病正谓上热未除中寒复生者也非药之罪失其缓急之制也处方之制宜加意焉。", "19262": "治口干舌干小便数舌上赤脉此药生津液除干燥生肌肉", "19263": "柴胡炙甘草生甘草（此味治口干舌干也）麻黄根（各三分）酒当归梢（四分）酒知母酒汉防己羌活（各五分）酒生地黄（七分）升麻（一钱）杏仁桃仁（各六个）红花（少许）酒黄连（八分治舌上赤脉也）石膏（六分治小便赤色）酒黄柏（一钱）", "19264": "诸脉者皆属于目论", "19265": "阴阳应象论云诸脉者皆属于目目得血而能视五脏六腑精气皆上注于目而为之精精之窠为眼骨之精为瞳子筋之精为黑眼血之精为络其窠气之精为白眼肌肉之精则为约束里撷筋骨血气之精而与脉并为系上属于脑后出于项中故邪中于项因逢其身之虚其入深则即随眼系入于脑则脑转脑转则引目系急目系急则目眩以转矣邪中其精其精所中不相比也则精散精散则视岐故见两物目者五脏六腑之精荣卫魂魄之所常营也神气之所主也故神劳则魂魄散志意乱是故瞳子黑眼发于阴白眼赤脉发于阳故阴阳合传而为精明也目者心之使也心者神之舍也故神精乱而不转卒然见非常之处精神魂魄散不相得故曰惑也夫十二经脉三百六十五络其血气皆上走于面而走空窍其清阳气上散于目而为精其气走于耳而为听因心事烦冗饮食失节劳役过度致脾胃虚弱心火大盛则百脉沸腾血脉逆行邪害空窍天明则日月不明矣夫五脏六腑之精气皆禀受于脾上贯于目脾者诸阴之首也目者血脉之宗也故脾虚则五脏之精气皆失所司不能归明于目矣心者君火也主人之神宜静而安相火化行其令相火者包络也主百脉皆荣于目既劳役运动势乃妄行又因邪气所并而损血脉故诸病生焉凡医者不理脾胃及养血安神治标不治本是不明正理也", "19266": "凡心包络之脉出于心中以代心君之行事也与少阳为表里瞳子散大者少阴心之脉挟目系厥阴肝之脉连目系心主火肝主木此木火之势盛也其味则宜苦宜酸宜凉大忌辛辣热物以助木火之邪也饮食中常知此理可也夫辛主散热则助火故不可食诸酸主收心气泻木火也诸苦泻火热则益水也尤忌食冷水大寒之物此则能损胃气不行则元气不生元气不生胃气下流胸中三焦之火及心火乘于肺上入脑灼髓火主散溢瞳子开大大热之物又助火邪此盖不可食验也药中云茺蔚子一味辛及主益睛辛者是助火也故去之乃加黄芩黄连泻中焦之火芩能泻上焦肺中之火以酒洗之乃寒因热用也又去青葙子为助阳火也加五味子以收瞳人间大且火之与气势不两立故内经曰壮火食气气食少火少火生气壮火散气诸酸之物能助元气孙真人云五月常服五味助五脏气以补西方肺金法云以酸补之以辛泻之辛泻气则明矣或曰药中有当归其味亦辛而甘其不去者何此辛甘一味以其和血之圣药况有甘味又欲以为向导为诸药之使耳", "19267": "治目疾累服寒凉药不愈两眼蒸热如火之熏赤而不痛满目红丝血脉贯睛瞀闷昏暗羞明畏日或上下睑赤烂或冒风沙而内外眦皆破洗之神效", "19268": "戊申六月徐总管患眼疾于上眼皮下出黑白翳两个隐涩难开两目紧缩而无疼痛两手寸脉细紧按之洪大无力知足太阳膀胱为命门相火煎熬逆行作寒水翳及寒膜遮晴证呵欠善悲健忘嚏喷眵泪时自泪下面赤而白能食不大便小便数而欠气上而喘", "19269": "治血弱阴虚不能养心致心火旺阳火甚瞳子散大少阴为火君主无为不行其令相火代之兼心包络之脉出心系分为三道少阳相火之体无形其用在其中矣火盛则令母实乙木肝旺是也心之脉挟于目系肝连目系况手足少阳之脉同出耳中至耳上角斜起于目外眦风热之盛亦从此道而来上攻头目致偏头肿闷瞳子散大视物则花此由血虚阴弱故也法当养血凉血益血收火之散大除风之热则愈矣", "19270": "金匮真言论云东风生于春病在肝俞在颈项故春气者病在头又诸阳会于头面如足太阳膀胱之脉起于目内眦上额交颠上入络脑还出别下项病冲头痛又足少阳胆之脉起于目锐眦上抵头角病则头角额痛夫风从上受之风寒伤上邪从外入客于经络令人振寒头痛身重恶寒治在风池风府调其阴阳不足则补有余则泻汗之则愈此伤寒头痛也头痛耳鸣九窍不利者肠胃之所生乃气虚头痛也心烦头痛者病在膈中过在手巨阳少阴乃湿热头痛也如气上不下头痛癫疾者下虚上实也过在足少阴巨阳甚则入肾寒湿头痛也如头半边痛者先取手少阳阳明后取足少阳阳明此偏头痛也有真头痛者甚则脑尽痛手足寒至节死不治有厥逆头痛者所犯大寒内至骨髓髓者以脑为主脑逆故令头痛齿亦痛凡头痛皆以风药治之者总其大体而言之也高巅之上惟风可到故味之薄者阴中之阳乃自地升天者也然亦有三阴三阳之异故太阳头痛恶风脉浮紧川芎羌活独活麻黄之类为主少阳经头痛脉弦细往来寒热柴胡为主阳明头痛自汗发热恶寒脉浮缓长实者升麻葛根石膏白芷为主太阴头痛必有痰体重或腹痛为痰癖其脉沉缓苍术半夏南星为主少阴经头痛三阴三阳经不流行而足寒气逆为寒厥其脉沉细麻黄附子细辛为主厥阴头项痛或吐痰沫厥冷其脉浮缓吴茱萸汤主之血虚头痛当归川芎为主气虚头痛人参黄耆为主气血俱虚头痛调中益气汤少加川芎蔓荆子细辛其效如神白术半夏天麻汤治痰厥头痛药也青空膏乃风湿热头痛药也羌活附子汤治厥阴头痛药也如湿气在头者以若吐之不可执方而治先师尝病头痛发时两颊青黄晕眩目不欲开懒言身体沉重兀兀欲吐洁古曰此厥阴太阴合病名曰风痰以局方玉壶丸治之更灸侠谿穴即愈是知方者体也法者用也徒执体而不知用者弊体用不失可谓上工矣", "19271": "如太阴脉缓有痰名曰痰厥头痛减羌活防风川芎甘草加半夏（一两五钱）", "19272": "论曰夫齿者肾之标口者脾之窍诸经多有会于口者其牙齿是手足阳明之所过上龈隶于坤土乃足阳明胃之脉贯络也止而不动下龈嚼物动而不休手阳明大肠之脉所贯络也手阳明恶寒饮而喜热足阳明喜寒饮而恶热其病不一牙者肾之标亦喜寒寒者坚牢为病不同热甚则齿动龈龈袒脱作痛不已故所治疗不同也有恶热而作痛者有恶寒而作痛者有恶寒恶热而作痛者有恶寒饮少热饮多而作痛者有恶热饮少寒饮多而作痛者有牙齿动摇而作痛者有齿龈肿起为痛者有脾胃中有风邪但觉风而作痛者又有牙上多为虫所蚀其齿缺少而色变为虫牙痛者有胃中气少不能于寒袒露其齿作痛者有牙齿疼痛而秽臭之气不可近者痛既不一岂可一药而尽之哉", "19273": "治牙齿痛不可忍及头脑项背痛微恶寒饮大恶热饮其脉上中下三部阳虚阴盛是五脏内盛六腑阳道微脉微小小便滑数", "19274": "上同为细末汤浸𩚫饼为丸如绿豆大每服一百丸或加至二百丸止白汤下食远服兼治血痢及血崩及血下不止血下褐色或紫色黑色及肠澼下血空心服米汤下其脉洪大而缓者及治麻木厥气上冲逆气上行妄闻妄见者", "19275": "治六脉俱大按之空虚心动面赤善惊上热乃手少阴心脉也此气盛多而亡血以甘寒镇坠之剂大泻其气以坠气浮以甘辛温微苦峻补其血", "19276": "如两寸脉芤血在上焦或衄血或呕血与犀角地黄汤则愈", "19277": "救脉汤（一名人参救肺散）", "19278": "人参（益上焦元气不足而实其表也）麦冬（保肺气各三分）桂枝（以补表虚）当归身（和血养血各五分）甘草（补其脾胃之虚）麻黄（去根节）黄耆（实表益卫）白芍药（各一钱）五味子（五个安其脉气）", "19279": "六脉弦细而涩按之空虚其色必白而天不泽者脱血也此大寒证以辛温补血益血以甘温甘热滑润之剂以佐之则愈此亡血亦伤精气", "19280": "丁未冬曹通甫自河南来有役人小翟露宿寒湿之地腰痛不能转侧两胁搐急作痛已经月余不愈矣腰痛论中说皆为足太阳足少阴血络中有凝血作痛间有一二证属少阳胆经外络脉病皆去血络之凝乃愈其内经有云冬三月禁不得用针只宜服药通其经络破其血络中败血以此药主之", "19281": "治阴室中汗出懒语四肢困倦无力走注疼痛乃下焦伏火而不得伸浮而躁热汗出一身尽痛盖风湿相搏也以升阳发汗渐渐发之火郁及湿在经者亦宜发汗况正值季春之月脉缓而迟尤宜发汗令风湿去而阳升以此困倦乃退气血俱得生旺也", "19282": "阴阳别论云二阳之病发心脾有不得隐曲女子不月其传为风消为息贲者死不治妇人脾胃久虚或形嬴气血俱衰而致经水断绝不行或病中消胃热善食渐瘦津液不生夫经者血脉津液所化津液既绝为热所烁肌肉消瘦时见渴躁血海枯竭病名曰血枯经绝宜泻胃之燥热补益气血经自行矣此证或经适行而有子子不安为胎病者有矣或心包脉洪数躁作时见大便秘涩小便虽清不利而经水闭绝不行此乃血海干枯宜调血脉除包络中火邪而经自行矣内经所谓小肠移热于大肠为症瘕为沉脉涩不利则月事沉滞而不利故云为症瘕为沉也或因劳心心火上行月事不来安心和血泻火经自行矣故内经云月事不来者胞脉闭也胞脉者属心而络于胞中令气上迫肺心气不得下故月事不来也", "19283": "阴阳别论云阴虚阳搏谓之崩妇人脾胃虚损致命门脉沉细而数疾或沉弦而洪大有力寸关脉亦然皆由脾胃有亏下陷于肾与相火相合湿热下迫经漏不止其色紫黑如夏月腐肉之臭中有白带者脉必弦细寒作于中中有赤带者其脉洪数疾热明矣必腰痛或脐下痛临经欲行先见寒热往来两胁急缩兼脾胃证出见或四肢困热心烦不得眠卧心下急宜大补脾胃而升举血气可一服而愈或人故贵脱势人事疏少或先富后贫心气不足其火大炽旺于血脉之中又致脾胃饮食失节火乘其中形质肌肉容颜似不病者此心病也不形于诊故脾胃饮食不调其证显矣而经水不时而下或适来适断暴下不止治当先说恶死之言劝谕令欢死而心不动以大补气血之药养脾胃微加镇坠心火之药治其心补阴泻阳经自止矣痿论云悲哀太甚则胞络绝也阳气内动发则心下崩数溲血也故本病曰大经空虚发则肌痹传为脉痿此之谓也", "19284": "治女子漏下恶血月事不调或暴崩不止多下水浆之物皆由饮食不节或劳伤形体或素有心气不足因饮食劳倦致令心火乘脾其人必怠惰嗜卧四肢不收困倦乏力无气以动气短上气逆急上冲其脉缓而弦急按之洪大皆中指下得之脾土受邪也脾主滋荣周身者也心主血血主脉二者受邪病皆在脉脉者血之府也脉者人之神也心不主令包络代之故曰心之脉主属心系心系者包络命门之脉也主月事因脾胃虚而心包乘之故漏下月事不调也况脾胃为血气阴阳之根蒂也当除湿去热益风气土伸以胜其湿又云火郁则发之", "19285": "足太阴脾之经中血海二穴在膝膑上内臁白肉际二寸中治女子漏下恶血月事不调逆气腹胀其脉缓者是也灸三壮", "19286": "治癫疝白带下疰脚气腰以下如在冰雪中以火焙炕重重厚绵衣盖其上犹寒冷不任寒之极也面白如枯鱼之象肌肉如刀割削瘦峻之速也小便不止与白带长流而不禁固自不知觉面白目青蓝如菜色目䀮䀮无所见身重如山行步欹侧不能安地腿膝枯细大便难秘口不能言无力之极食不下心下痞烦心懊𢙐不任其苦面停垢背恶寒小便遗而不知此上中下三阳真气俱虚欲竭哕呕不止胃虚之极也脉沉厥紧而涩按之空虚若脉洪大而涩按之无力犹为中寒之证况按之空虚者乎按之不鼓是为阴寒乃气血俱虚之极也", "19287": "治白带久下不止脐腹冷痛阴中亦然目中溜火视物䀮䀮然无所见齿皆恶热饮痛须得黄连细末擦之乃止惟喜干食大恶汤饮此病皆寒湿乘其胞内故喜干而恶湿肝经阴火上溢走于标故上壅而目中溜火肾水侵肝而上溢致目䀮䀮而无所见齿恶热饮者是阳明经中伏火也治法当大泻寒湿以丸药治之故曰寒在下焦治宜缓大忌汤散以酒制白石脂白龙骨以枯其湿炮干姜大热辛泻寒水以黄柏之大寒为因用又为乡导故云古者虽有重罪不绝人之后又为之伏其所主先其所因之意又泻齿中恶热饮也以柴胡为本经之使以芍药五分导之恐辛热之药大甚损其肝经故微泻之以当归身之辛温大和其血脉此用药之法备矣", "19288": "治崩漏不止盖心气不足劳役及饮食不节所得经隔少时其脉二尺俱弦紧洪按之无力其证自觉脐下如冰求厚衣被以御其寒白带白滑之物多间有如屋漏水下时有鲜血石尺脉时微洪也", "19289": "丁未仲冬郭大方来说其妻经水暴崩不止先曾损身失血自后一次缩一十日而来今次不止其人心窄性急多惊以予料之必因心气不足饮食不节得之大方曰无到彼诊得掌中寒脉沉细而缓间而沉数九窍微有不利四肢无力上喘气短促口鼻气皆不调果有心气不足脾胃虚弱之证胃脘当心而痛左胁下缩急有积当脐有动气腹中鸣下气大便难虚证极多不能尽录拟先治其本余证可以皆去安心定志镇坠其经调和脾胃大益元气补其血脉令养其神以大热之剂去其冬寒凝在皮肤内少加生地黄去命门相火不令四肢痿弱", "19290": "治妇人经脉漏下不止其色鲜红时值七月处暑之间先因劳役脾胃虚弱气短气逆自汗不止身热闷乱恶见饮食非惟不入亦不思食沉懒困倦四肢无力大便时泻后再因心气不足经脉再下不止惟觉气下脱其元气逆上全无惟觉心腹中气下行气短少不能言是无力以言非懒语也此药主之", "19291": "治经水不止如右尺脉控之空虚是气血俱脱大寒之证轻手其脉数疾举指弦紧或涩皆阳脱之证阴火亦亡见热证于口鼻眼或渴此皆阴躁阳欲先去也当温之举之升之浮之燥之此法当大升浮血气切补命门之下脱也", "19292": "白文举正室白带常漏久矣诸药不效诊得心包尺脉微其白带下流不止叔和云崩中日久为白带漏下多时血水枯言崩中者始病血崩久则血少复亡其阳故白滑之物下流不止是本经血海将枯津液复亡枯干不能滋养筋骨以本经行经药为引用为使以大辛甘油腻之药润其枯燥而滋益津液以大辛热之气味药补其阳道生其血脉以苦寒之药泄其肺而救上热伤气以人参补之以微苦温之药为佐而益元气", "19293": "李正臣夫人病诊得六脉中俱得弦洪缓相合按之无力弦在上是风热下陷入阴中阳道不行其证闭目则浑身麻木昼减而夜甚觉而开目则麻木渐退久则绝止常开其目此证不作惧其麻木不敢合眼致不得眠身体皆重时有痰嗽觉胸中常似有痰而不利时烦躁气短促而喘肌肤充盛饮食不减大小便如常惟畏其麻木不敢合眼为最苦观其色脉形病相应而不逆内经曰阳盛瞑目而动轻阴病闭目而静重又云诸脉皆属于目灵枢经云闭目则阳道行阳气遍布周身闭目则阳道闭而不行如昼夜之分知其阳衰而阴旺也且麻木为风三尺之童皆以为然细校之则有区别耳久坐而起亦有麻木为如绳缚之久释之觉麻作而不敢动良久则自已以此验之非有风邪乃气不行主治之当补其肺中之气则麻木自去矣如经脉中阴火乘其阳分火动于中为麻木也当兼去其阴火则愈矣时痰嗽者秋凉在外在上而作也当以温剂实其皮毛身重脉缓者湿气伏匿而作也时见躁作当升阳助气益血微泻阴火与湿通行经脉调其阴阳则已矣非五脏六腑之本有邪也此药主之", "19294": "如脉涩觉身痒气涩而大便不通者加郁李仁大黄以除气燥", "19295": "若病人虽是阴证或是阴寒之证其病显躁脉实坚亦宜于阳药中少加苦寒之药以去热躁躁止勿加", "19296": "如阴躁欲坐井中者其二肾脉按之必虚或沉细而迟此易为辨耳知有客邪之病亦当从权加药以去之", "19297": "内经曰因而饱食筋脉横解肠澼为痔夫大肠庚也主津本性燥清肃杀之气本位主收其所司行津以从足阳明旺则生化万物者也足阳明为中州之土若阳衰亦殒杀万物故曰万物生于土而归于土者是也以手阳明大肠司其化焉既在西方本位为之害蜚司杀之府因饱食行房忍泄前阴之气归于大肠木乘火势而侮燥金故火就燥也大便必闭其疾甚者当以苦寒泻火以辛温和血润燥疏风止痛是其治也以秦艽当归梢和血润燥以桃仁润血以皂角仁除风燥以地榆破血以枳实之苦寒补肾以下泄胃实以泽泻之淡渗使气归于前阴以补清燥受胃之湿邪也白术之苦甘以苦补燥气之不足其甘味以泻火而益元气也故曰甘寒泄火乃假枳实之寒也古人用药为下焦如渎又曰在下者引而竭之多为大便秘涩以大黄推去之其津血益不足以当归和血及油润之剂大便自然软利矣宜作锉汤以与之是下焦有热以急治之之法也以地榆酸苦而坏胃故宿食消尽空心作丸服之", "19298": "治痔漏经年因而饱食筋脉横解肠澼为痔治法当补北方泻中央", "19299": "一富者前阴臊臭又因连日饮酒腹中不和求先师治之日夫前阴者足厥阴肝之脉络循阴器出其挺末凡臭者心之所主散入五方为五臭如肝为臊此共一也当于肝经中泻行间是治其本后于心经中泻少冲乃治其标如恶针当用药除之酒者气味俱阳能生里之湿热是风湿热合于下焦为邪故经云下焦如渎又云在下者引而竭之酒是湿热之水亦宜决前阴以去之", "19300": "治脐下撮急疼痛并周身皆急痛小便频数及五脉急独肾脉按之不急皆虚无力名曰肾疝", "19301": "治肠澼下血另作一派其血唧出有力而远射四散如筛肠中血下行腹中大作痛乃阳明气冲热毒所作也当升阳去湿热和血脉是其治也", "19302": "治肠澼下血或血色紫黑腹中痛腹皮恶寒右手关脉弦按之无力而喜热物熨之内寒明矣", "19303": "治太阴阳明腹痛大便常泄若不泄即秘而难见在后传作湿热毒下鲜红血腹中微痛胁下急缩脉缓而洪弦中下得之按之空虚", "19304": "护皮毛实腠理虚及活血脉生血亦疮家圣药也又能补表实元气之弱也", "19305": "如脉涩觉身痒气涩而大便不通者加郁李仁大黄以除气燥也", "19306": "治足太阳经中左右尺脉俱紧按之无力尻臀生痈坚硬肿痛大作", "19307": "治妇人两乳间出黑头疮疮顶陷下作黑眼子其脉弦洪按之细小", "19308": "贾德茂小男于左大腿近膝股内出附骨痈不辩肉色漫肿皮泽木硬疮势甚大其左脚乃肝之脾土也更在足厥阴肝经之分少侵足太阴脾经之分其脉左三部细而弦按之洪缓微有力此药主之", "19309": "尹老家素贫寒形志皆苦于手阳明大肠经分出痈幼小有𤻊疝其臂外皆肿痛在阳明左右寸脉皆短中得之俱弦按之洪缓有力此痈得自八风之变以脉断之邪气在表其证大小便如故饮食如常腹中和口知味知不在里也不恶风寒止热躁脉不浮知不在表也表里既和邪气在经脉之中内经云凝于经络为疮痈其痈出身半以上故风从上受之故知是八风之变为疮者也故治其寒邪调其经脉中血气使无凝滞而已", "19310": "治妇人肌热躁热目赤面红烦渴引饮昼夜不息其脉洪大而虚重按全无内经曰脉虚血虚脉实血实又云血虚发热证象白虎惟脉不长实为辨也若误服白虎汤必死此病得之于饥困劳役", "19311": "治胸中痛头痛食减少咽嗌不利右寸脉弦急", "19312": "治两腿麻木沉重无力多汗喜笑口中涎下身重如山语声不出右寸脉洪大", "19313": "或问湿之与汗为阴乎为阳乎曰西南坤土也在人则为脾胃也人之汗犹天地之雨也阴滋其湿则为雾露为雨也阴湿下行地之气也汗多则亡阳阳去则阴胜也甚为寒中混胜则音声如从瓮中出湿若中水也相法家有说土音如居深瓮里言其壅也远也不出也以明其湿审矣又知此二者亦为阴寒也内经云气虚则外寒虽见热中蒸蒸为汗终传大寒知始为热中表虚亡阳不任外寒终传寒中多成痹寒矣色以候天脉以候地形者乃候地之阴阳也故以脉气候之皆有形无形之可见者也", "19314": "灵寿县董监军癸卯冬大雪时因事到真定忽觉有风气暴至诊候得六脉俱弦甚按之洪实有力其证手挛急大便秘涩面赤热此风寒始至加于身也四肢者脾也以风寒之邪伤之则搐急而挛痹乃风淫未疾而寒在外也内经曰寒则筋挛正谓此也本人素饮酒内有实热乘于肠胃之间故大便秘涩而面赤热内则手足阳明受邪外则足太阴脾经受风寒之邪用桂枝甘草以却其寒邪而缓其急搐又以黄柏之苦寒滑以泻实而润燥急救肾水用升麻葛根以升阳气行手足阳明之经不令遏绝更以桂枝辛热入手阳明之经为引用润燥复以芍药甘草专补脾气使不受风寒之邪而退木邪专益肺金也加人参以补元气为之辅佐加当归身去里急而和血润燥此药主之", "19315": "治面黄汗多目赤四肢沉重减食腹中时时痛咳嗽两手寸脉短右手脉弦细兼涩关脉虚", "19316": "时初冬一小儿二岁大寒证明堂青脉额上青黑脑后青络高起舌上白滑喉鸣而喘大便微青耳尖冷目中常常泪下仍多眵胸中不利卧而多惊无搐则寒", "19317": "夫癍疹始出之证必先见面烧腮赤目胞亦赤呵欠烦闷乍凉乍热咳嗽嚏喷足稍冷多睡惊并疮疹之证或生脓胞或生小红癍或生瘾疹此三等不同何故俱显上证而后乃出盖以上诸证皆太阳寒水起于右肾之下煎熬左肾足太阳膀胱寒水夹脊逆流上头下额逆手太阳丙火不得传导逆于面上故显是证盖旺癸寒水克丙丁热火故也诸癍证皆从寒水逆流而作也医者当知此理乃敢用药夫胞者一名赤宫一名丹田一名命门主男子藏精施化妇人系胞有孕俱为生化之源非五行也非水亦非火此天地之异名也象坤土之生万物也夫人之始生也血海始净一日二日精胜其血则为男子三日四日五日血脉已旺精不胜血则为女子二物相搏长生先身谓之神又谓之精道释二门言之本来面目是也其子在腹中十月之间随母呼吸者阳气也而生动作滋益精气神饥则食母血渴则饮母血儿随日长皮肉筋骨血脉形气俱足十月降生口中尚有恶血啼声一发随吸而下此恶血复归命门胞中僻于一隅伏而不发直至因内伤乳食湿热之气下流合于肾中二火交攻致荣气不从逆于肉理恶血乃发诸癍疹皆出于膀胱旺水其疡后聚肉理归于阳明故三番癍始显之证皆足太阳旺膀胱克丙小肠其始出皆见于面终归于阳明肉理热化为脓者也二火炽甚反胜寒水遍身俱出此皆出从足太阳传变中来也当外发寒邪使令消散内泻二火不令交攻其中令湿气上归复其本位可一二服立已仍令小儿以后再无二番癍出之患此内经之法览者详之", "19318": "如心出小红癍必先见嗌干惊悸身热肌肉肿脉弦洪少加黄连", "19319": "治小儿寒郁而喘喉鸣腹满鼻流清涕脉沉急而数", "19320": "按〈阴阳应象大论〉云「天之邪气，感则害人五脏」，是八益之邪，乃风邪伤人筋骨。风从上受之，风伤筋，寒伤骨，盖有形质之物受病也，系在下焦，肝肾是也。肝肾者，地之气，《难经》解云肝肾之气，已绝于内，以其肝主筋，肾主骨，故风邪感人，则筋骨疼痛，筋骨之绝，则肾肝之本亦绝矣，乃有余之证也。又云「水谷之寒热，感则害人六腑」，是七损之病，乃内伤饮食也。《黄帝针经》解云：适饮食不节，劳役所伤，湿从下受之。谓脾胃之气不足，而反下行，极则冲脉之火逆而上，是无形质之元气受病也，系在上焦，心肺是也。心肺者，天之气。故《难经》解云心肺之气已绝于外，以其心主荣，肺主卫。荣者，血也。脉者，血之府，神之所居也。「卫」者，元气七神之别名，卫护周身，在于皮毛之间也。肺绝则皮毛先绝，神无所依，故内伤饮食，则亦恶风寒，是荣卫失守，皮肤间无阳以滋养，不能任风寒也。皮毛之绝，则心肺之本亦绝矣。盖胃气不升，元气不生，无滋养心肺，乃不足之证也。", "19321": "辨脉", "19322": "古人以脉上辨内外伤于人迎、气口。人迎脉大于气口为外伤，气口脉大于人迎为内伤。此辨固是，但其说有所未尽耳。外感风寒，皆有余之证，是从前客邪来也，其病必见于左手，左手主表，乃行阳二十五度。内伤饮食及饮食不节，劳役不节，皆不足之病也，必见于右手，右手主里，乃行阴二十五度。故外感寒邪，则独左寸人迎脉浮紧，按之洪大，紧者急甚于弦，是足太阳寒水之脉；按之洪大而有力，中见手少阴心火之脉，丁与壬合，内显洪大，乃伤寒脉也。若外感风邪，则人迎脉缓而大于气口一倍，或两倍、三倍。内伤饮食，则右寸气口脉大于人迎一倍；伤之重者，过在少阴，则两倍，太阴则三倍，此内伤饮食之脉。若饮食不节，劳役过甚，则心脉变见于气口，是心火刑肺，其肝木挟心火之势亦来薄肺，《经》云「侮所不胜，寡于畏」者是也。故气口脉急大而涩数，时一代而涩也。涩者，肺之本脉；代者，元气不相接，脾胃不及之脉。洪大而数者，心脉刑肺也；急者，肝木挟心火而反克肺金也。若不甚劳役，惟右关脾脉大而数，谓独大于五脉，数中显缓，时一代也。如饮食不节，寒温失所，则先右关胃脉损弱，甚则隐而不见，惟内显脾脉之大数微缓，时一代也。宿食不消，则独右关脉沉而滑。《经》云：「脉滑者，有宿食也。」以此辨之，岂不明白易见乎！但恐山野间卒无医者，何以诊候？故复说病证以辨之。", "19323": "当内虚而伤之者躁热也，或因口吸风寒之气，郁其阴火，使咽膈不通，其吸入之气欲入，为膈上冲脉之火所拒，使阴气不得入，其胸中之气为外风寒所遏而不得伸，令人口开目瞪，极则声发于外，气不能上下，塞于咽中而气欲绝。又或因哕因呕因吐，而躁热发必有所因，方有此证，其表虚恶风寒之证复见矣。表虚之弱，为阴火所乘，躁发须臾而过，其表虚无阳，不任风寒复见矣。是表虚无阳，常常有之，其躁热则间而有之，此二者不齐，躁作寒已，寒作躁已，非如外伤之寒热齐作，无有间断也。", "19324": "外感风寒之邪，三日已外，谷消水去，邪气传里，始有渴也。内伤饮食失节，劳役久病者，必不渴，是邪气在血脉中有余故也。初劳役形质，饮食失节，伤之重者，必有渴，以其心火炽，上克于肺金，故渴也。又当以此辨之。虽渴欲饮冷水者，当徐徐少与之，不可纵意而饮，恐水多峻下，则胃气愈弱，轻则为胀，重则传变诸疾，必反复闷乱，百脉不安，夜加增剧，不得安卧，不可不预度也。", "19325": "苟饮食失节，寒温不适，则脾胃乃伤；喜怒忧恐，劳役过度，而损耗元气。既脾胃虚衰，元气不足，而心火独盛。心火者，阴火也，起于下焦，其系系于心，心不主令，相火代之；相火，下焦胞络之火，元气之贼也。火与元气不能两立，一胜则一负。脾胃气虚，则下流于肾，阴火得以乘其土位。故脾胃之证，始得之则气高而喘，身热而烦，其脉洪大而头痛，或渴不止，皮肤不任风寒而生寒热。盖阴火上冲，则气高而喘，身烦热，为头痛，为渴，而脉洪大；脾胃之气下流，使谷气不得升浮，是生长之令不行，则无阳以护其荣卫，不任风寒，乃生寒热，皆脾胃之气不足所致也。", "19326": "夫脾胃虚者，因饮食劳倦，心火亢甚，而乘其土位，其次肺气受邪，须用黄耆最多，人参、甘草次之。脾胃一虚，肺气先绝，故用黄耆以益皮毛而闭腠理，不令自汗，损其元气。上喘气短，人参以补之。心火乘脾，须炙甘草之甘以泻火热，而补脾胃中元气，若脾胃急痛并大虚，腹中急缩者，宜多用之，经云：「急者缓之。」白术苦甘温，除胃中热，利腰脐间血。胃中清气在下，必加升麻、柴胡以引之，引黄耆、人参、甘草甘温之气味上升，能补卫气之散解，而实其表也；又缓带脉之缩急。二味苦平，味之薄者，阴中之阳，引清气上升也。气乱于胸中，为清浊相干，用去白陈皮以理之，又能助阳气上升，以散滞气，助诸甘辛为用，口干咽干加干葛。脾胃气虚，不能升浮，为阴火伤其生发之气，荣血大亏，荣气不营，阴火炽盛，是血中伏火日渐煎熬，血气日减，心包与心主血，血减则心无所养，致使心乱而烦，病名曰悗。悗者，心惑而烦闷不安也，故加辛甘微温之剂生阳气，阳生则阴长。或曰：甘温何能生血？曰：仲景之法，血虚以人参补之，阳旺则能生阴血，更以当归和之。少加黄柏以救肾水，能泻阴中之伏火。如烦犹不止，少加生地黄补肾水，水旺而心火自降。如气浮心乱，以朱砂安神丸镇固之则愈。", "19327": "耳鸣，目黄，颊颔肿，颈肩臑肘臂外后廉痛，面赤，脉洪大者，以羌活（一钱），防风、藁本（以上各七分），甘草（五分），通其经血；加黄芩、黄连（以上各三分）消其肿；人参（五分），黄耆（七分），益元气而泻火邪。另作一服与之。", "19328": "嗌痛颔肿，脉洪大，面赤者，加黄芩、甘草（以上各三分），桔梗（七分）。", "19329": "心下痞，觉中寒，加附子、黄连（以上各一钱）。不能食而心下痞，加生姜、陈皮（以上各一钱）。能食而心下痞，加黄连（五分），枳实（三分）。脉缓有痰而痞，加半夏、黄连（以上各一钱）。脉弦，四肢满，便难而心下痞，加黄连（五分），柴胡（七分），甘草（三分）。", "19330": "如腹中痛，恶寒而脉弦者，是木来克土也，小建中汤主之；盖芍药味酸，于土中泻木为君。如脉沉细，腹中痛，是水来侮土，以理中汤主之；干姜辛热，于土中泻水，以为主也。如脉缓，体重节痛，腹胀自利，米谷不化，是湿胜，以平胃散主之，苍术苦辛温，泻湿为主也。", "19331": "脚膝痿软，行步乏力，或痛，乃肾肝伏热，少加黄柏（五分），空心服；不已，更加汉防己（五分）。脉缓，显沉困怠惰无力者，加苍术、人参、泽泻、白术、茯苓、五味子（以上各五分）。", "19332": "时当长夏，湿热大胜，蒸蒸而炽。人感之多四肢困倦，精神短少，懒于动作，胸满气促，肢节沉痛；或气高而喘，身热而烦，心下膨痞，小便黄而少，大便溏而频，或痢出黄糜，或如泔色；或渴或不渴，不思饮食，自汗体重；或汗少者，血先病而气不病也。其脉中得洪缓，若湿气相搏，必加之以迟，迟病虽互换少差，其天暑湿令则一也。宜以清燥之剂治之，名之曰清暑益气汤主之。", "19333": "《内经》云：「阳气者，卫外而为固也」，「炅则气泄。」今暑邪干卫，故身热自汗。以黄耆、人参、甘草补中益气为君；甘草、橘皮、当归身甘辛微温养胃气，和血脉为臣。苍术、白术、泽泻渗利除湿。升麻、葛根苦甘平，善解肌热，又以风胜湿也。湿胜则食不消而作痞满，故炒曲甘辛，青皮辛温，消食快气。肾恶燥，急食辛以润之，故以黄柏苦辛寒，借甘味泻热补水虚者，滋其化源。以五味子、麦门冬酸甘微寒，救天暑之伤庚金为佐也。", "19334": "夫脾胃虚弱之人，遇六七月霖雨，诸物皆润，人汗沾衣，身重短气，更逢湿旺，助热为邪，西北二方寒清绝矣，人重感之，则骨乏无力，其形如梦寐间，朦朦如烟雾中，不知身所有也。圣人立法，夏月宜补者，补天真元气，非补热火也，夏食寒者是也。故以人参之甘补气，麦门冬苦寒，泻热补水之源，五味子之酸，清肃燥金，名曰生脉散。孙真人云：五月常服五味子以补五脏之气，亦此意也。", "19335": "治肌热，燥热，困渴引饮，目赤面红，昼夜不息。其脉洪大而虚，重按全无。《内经》曰：「脉虚血虚。」又云，血虚发热，证象白虎，惟脉不长实有辨耳，误服白虎汤必死。此病得之于饥困劳役。", "19336": "黄耆（二两）半夏（洗，此一味脉涩者用）人芦（去芦）甘草（炙，以上各一两）独活防风（以秋旺，故以辛温泻之）白芍药（何故秋旺用人参白术芍药之类反补肺，为脾胃虚则肺最受邪，故因时而补，易为力也。）羌活（以上各五钱）橘皮（四钱）茯苓（小便利不渴者勿用）柴胡泽泻（不淋勿用）白术（以上各三钱）黄连（一钱）", "19337": "治法已试验者，学者当以意求其的，触类而长之，则不可胜用矣。予病脾胃久衰，视听半失，此阴盛乘阳，而上气短，精神不足，且脉弦，皆阳气衰弱，伏匿于阴中故耳。癸卯岁六七月间，霖雨阴寒，逾月不止，时人多病泻痢，乃湿多成五泄故也。一日，体重肢节疼痛，大便泄并下者三，而小便闭塞，默思《内经》有云：「在下者，引而竭之，」是先利小便也。又治诸泻而小便不利者，先分利之。又云：治湿不利小便，非其治也。法当利其小便，必用淡渗之剂以利之，是其法也。噫！圣人之法，虽布在方策，其不尽者，可以意求。今客邪寒湿之胜，自外入里而甚暴，若以淡渗之剂利之，病虽即已，是降之又降，复益其阴而重竭其阳也，则阳气愈削，而精神愈短矣，阴重强而阳重衰也。兹以升阳之药，是为宜耳。羌活、独活、柴胡、升麻各二钱，防风半钱，炙甘草半钱。同㕮咀，水四盏，煎至一盏，去渣，热服，一服乃愈。大法云：寒湿之胜，助风以平之。又曰：下者举之。此得阳气升腾故愈，是因曲而为之直也。夫圣人之法，可以类推，举一则可以知百矣。", "19338": "若内伤脾胃，以辛热之物，酒肉之类，自觉不快，觅药于医者，此风习以为常，医者亦不问所伤，即付之以集香丸、巴豆大热药之类下之，大便下则物去，遗留食之热性、药之热性，重伤元气，七神不炽，经云：「热伤气，」正谓此也。其人必无气以动而热困，四肢不举，传变诸疾，不可胜数，使人真气自此衰矣。若伤生冷硬物，世医或用大黄、牵牛二味大寒药投之，物随药下，所伤去矣。遗留食之寒性、药之寒性，重泻其阳，阳去则皮肤筋骨肉血脉无所依倚，便为虚损之证。论言及此，令人寒心。", "19339": "胃气岂可不养，复明养胃之理，故经曰，安谷则昌，绝谷则亡。水去则荣散，谷消则卫亡，荣散卫亡，神无所依。仲景云：水入于经，其血乃成；谷入于胃，脉道乃行。故血不可不养，胃不可不温，血温胃和，荣卫将行，常有天命。谷者，身之大柄也，《书》与《周礼》皆云：金木水火土谷，惟修以奉养五脏者也。内伤饮食，固非细事，苟妄服食药而轻生损命，其可乎哉！《黄帝针经》有说：胃恶热而喜清冷，大肠恶清冷而喜热，两者不和，何以调之？伯歧曰：调此者，饮食衣服，亦欲适寒温，寒无凄怆，暑无出汗；饮食者，热无灼灼，寒无凔凔，寒温中适，故气将持，乃不致邪僻也（详说见于本经条下）。是必有因用，岂可用俱寒俱热之食药，致损者与？！", "19340": "《内经》云：内伤者，其气口脉反大于人迎，一倍二倍三倍，分经用药。又曰：上部有脉，下部无脉，其人当吐，不吐者死。如但食不纳，恶心欲吐者，不问一倍二倍，不当正与瓜蒂散吐之，但以指或以物探去之。若所伤之物去不尽者，更诊其脉，问其所伤，以食药去之，以应塞因塞用，又谓之寒因寒用，泄而下降，乃应太阴之用，其中更加升发之药，令其元气上升，塞因塞用，因曲而为之直。何为曲？乃伤胃气是也。何为直？因而升发胃气是也。因治其饮食之内伤，而使生气增益，胃气完复，此乃因曲而为之直也。", "19341": "若依分经用药，其所伤之物，寒热温凉，生硬柔软，所伤不一，难立定一法，只随所伤之物不同，各立法治，临时加减用之。其用药又当问病人从来禀气盛衰，所伤寒物热物，是喜食而食之耶，不可服破气药；若乘饥困而食之耶，当益胃气；或为人所勉劝强食之，宜损血而益气也。诊其脉候，伤在何脏，方可与对病之药，岂可妄泄天真生气，以轻丧身宝乎？且如先食热物而不伤，继之以寒物，因后食致前食亦不消化而伤者，当问热食寒食孰多孰少，斟酌与药，无不当矣。喻如伤热物二分，寒物一分，则当用寒药二分，热药一分，相合而与之，则荣卫之气必得周流。更有或先饮酒，而后伤寒冷之食，及伤热食，冷水与冰，如此不等，皆当验其节次所伤之物，约量寒热之剂分数，各各对证而与之，无不取验。自忖所定方药，未敢便为能尽药性之理，姑用指迷辨惑耳，随证立方，备陈于后。", "19342": "如脉缓体重自利，乃湿气胜也，以五苓散平胃散加炒曲相合而服之，名之曰对金饮子。", "19343": "如脉弦，恶寒腹痛，乃中气弱也。以仲景小建中汤加黄耆，钱氏异功散加芍药，选而用之。", "19344": "《痹论》云：「阴气者，静则神藏，躁则消亡。饮食自倍，肠胃乃伤」。此混言之也。分之为二：饮也，食也。又经云：「因而大饮则气逆。因而饱食，筋脉横解，则肠澼为痔」。饮者，无形之气，伤之则宜发汗利小便，使上下分消其湿，解酲汤、五苓散之类主之。食者，有形之物，伤之则宜损其谷；其次莫若消导，丁香烂饭丸、枳术丸之类主之；稍重则攻化，三棱消积丸、木香见𪾢丸之类主之；尤重者，则或吐或下，瓜蒂散、备急丸之类主之。以平为期。盖脾已伤，又以药伤，使营运之气减削，食愈难消。故《五常政大论》云，「大毒治病，十去其六；常毒治病，十去其七；小毒治病，十去其八；无毒治病，十去其九；谷肉果菜，食养尽之。无使过之，伤其正也。不尽，行复如法。」圣人垂，此严戒，是为万世福也。如能慎言语、节饮食，所谓治未病也。", "19345": "吐法宜用辨上部有脉下部无脉", "19346": "上部有脉，下部无脉，其人当吐，不吐者死，何谓也？下部无脉，此所谓木郁也。饮食过饱，填塞胸中，胸中者，太阴之分野。经云：气口反大于人迎三倍，食伤太阴，故曰木郁则达之，吐者是也。", "19347": "上二味，为极细末，每服一钱匕，温浆水调下，取吐为度。苦不至两手尺脉绝无，不宜便用此药，恐损元气，令人胃气不复。若止是胸中窒塞，闷乱不通，以指探去之；如不得吐者，以物探去之，得吐则已。如食不去，用此药去之。", "19348": "解云：盛食填塞于胸中，胸中为之窒塞，两手寸脉当主事，两尺脉不见，其理安在？胸中有食，故以吐出之。食者，物也。物者，坤土也，是足太阴之号也。胸中者，肺也，为物所填。肺者，手太阴金也，金主杀伐也；与坤土俱在于上，而旺于天。金能克木，故肝木生发之气伏于地下，非木郁而何？吐去上焦阴土之物，木得舒畅，则郁结去矣。", "19349": "食塞于上，脉绝于下，若不明天地之道，无由达此至理。水火者，阴阳之征兆，天地之别名也，故曰独阳不生，独阴不长。天之用在于地下，则万物生长矣；地之用在于天上，则万物收藏矣。此乃天地交而万物通也，此天地相根之道也。故阳火之根本于地下，阴水之源本于天上，故曰水出高源。故人五脏主有形之物，物者阴也，阴者水也，右三部脉主之，偏见于寸口，食塞其上，是绝五脏之源，源绝则水不下流，两尺竭绝，此其理也，何疑之有？", "19350": "「故曰：刺不知逆顺，真邪相搏，满者补之，则阴阳四溢，肠胃充廓，肝肺内䐜，阴阳相错；虚而泻之，则经脉空虚，血气枯竭，肠胃㒤辟，皮肤薄著，毛腠夭焦，予之死期。故曰：用针之要，在于知调阴与阳；调阴与阳，精气乃光，合形与气，使神内藏。", "19351": "故曰：上工平气，中工乱脉，下工绝气危生。故曰：下工不可不慎也，必审五脏变化之病，五脉之应，经络之实虚，皮肤之柔粗，而后取之也。」", "19352": "夫形气者，气，谓口鼻中气息也；形，谓皮肤筋骨血脉也。形胜者为有余，消瘦者为不足。其气者，审口鼻中气，劳役如故，为气有余也；若喘息气促气短，或不足以息者，为不足也。故曰形气也，乃人之身形中气血也，当补当泻，全不在于此，只在病势潮作之时，病气增加者，是邪气胜也，急当泻之；如潮作之时，精神困弱，语言无力，及懒语者，是真气不足也，急当补之。若病人形气不足，病来潮作之时，病气亦不足，此乃阴阳俱不足也。禁用针；宜补之以甘药，不可以尽剂；不灸弗已，脐下一寸五分气海穴是也。", "19353": "先生张元素，〔字〕洁古，易水人也。八岁试童经，二十七经义登科，犯章庙讳出落，于是怠仕进，遂潜心于医学，二十余年虽记诵广博书，（然）治人之术，不出人右。其夜梦人柯斧长凿，〔凿心〕开窍，纳书数卷于其中，见其题曰《内经主治备要》，骇然惊悟，觉心痛，只为凶事也，不敢语人。自是心目洞彻，便为传道轩岐，指挥秦越也。河间刘守真医名贯世，视之蔑如也。异日守真病伤寒八日误下证，头疼脉紧，呕恶不食，门人侍病，未知所为，请洁古诊之，至则守真面壁不顾也。洁古曰：〔何〕视我直如此卑也？诊其脉，（谓）之曰：脉病乃尔，初〔服〕某药犯某味药乎？曰：然。洁古曰：差之甚也。守真遽然起曰：何谓也？曰：某药味寒，下降，走太阴，阳亡，汗不彻故也。今脉〔如此〕，当以某药〔服〕之。守真首〔恳〕大服其能，一服而愈，自是名满天下。洁古治病，不用古方，但云：古方新病，〔甚〕不相宜，反以害人。每自从病处方，刻期见效，药〔下〕如攫，当时目之曰神医。暇日辑（集）《素问》五运六气，《内经》治要，《本草》药性，名曰《医学启源》，以教门生，及有《医方》三十卷传于世。〔壬辰遗失，□□□存者惟《医学启源》〕。真定李明之，门下高弟也，请余为序，故书之。兰泉老人张吉甫〔序〕。", "19354": "三、五脏六腑，除心包络十一经脉证法", "19355": "夫人有五脏六腑，虚实寒热，生死逆顺，皆见形证脉气，若非诊（切），无由识也。虚则补之，实则泻之，寒则温之，热则凉之，不虚不实，以经调之，此乃良医之大法也。", "19356": "（一）肝之经，肝脉本部在于筋，足厥阴，风，乙木也。", "19357": "经曰：肝与胆为表里，足厥阴（少〔阳〕）也。其经旺于春，乃万物之始生也。其气软而弱，软则不可汗，弱则不可下。其脉弦长曰平，反此曰病。脉实而弦，此为太过，病在外，令人忘忽眩运；虚而微，则为不及，病在内，令人胸胁胀满。凡肝〔实〕则两胁下引痛，喜怒，虚〔则〕如人将捕之。其气逆则头痛、耳聋、颊赤，其脉沉而急，浮之亦然，主胁〔支〕满，小便难，头痛眼眩。脉急〔甚〕主恶言，微急气在〔胸胁下〕。缓甚则呕逆，微缓水痹。大甚内痈吐血，微大筋痹。〔小甚多饮〕，微小痹。滑甚𤻊疝，微滑遗尿。涩甚流饮，微涩疭挛。肝之积气在左胁下，久而不去，发为咳逆，或为〔痎〕疟也。虚梦花草茸茸，实梦山林茂盛。肝病旦〔慧、晚〕甚、夜静。肝病头痛目眩，胁满囊缩，小便不通，十日死。又身〔热〕恶寒，四肢不举，其脉当弦而急；反短涩者，乃金克木也，死不治。又肝中寒，则两臂不举，舌燥，多太息，胸中痛，不能转侧，其脉左关上迟而涩者是也。肝中热，则喘满多嗔，目痛，腹胀不嗜食，所作不定，梦中惊悸，眼赤，视物不明，〔其〕脉左关阳实者是也。肝虚冷，则胁下坚痛，目〔盲〕臂痛，发寒〔热〕如疟状，不欲食，妇人则月水不来，气急，其脉左关上沉而弱者是也。此寒热虚实，生死逆顺之法也。", "19358": "经曰：胆者，中清之腑也，号曰将军，决断出焉。能喜怒刚柔，与肝为表里也，足少阳是其经也。虚则伤寒，恐畏头眩，不能〔独〕卧；实则伤热，惊悸，精神不守，卧起不定，玄水发，其根在胆。又肝咳不已，则传邪入胆，呕青汁也。又胆有水，则从头肿至足也。胆病则善太息，口苦，吐宿汁，心中戚戚恐，如人将捕之，咽中介介然数〔唾〕。又睡卧则胁下痛，〔口〕苦，多太息。邪气客于胆，则梦斗讼，脉在左关上浮而得之者，是〔其〕部也。胆实热，则精神不守。胆热则多肿，胆冷则多眠。又左关上脉阳微者，胆虚；阳数者，胆实；阳虚者胆绝也。以上皆虚实寒热，生死脉证之法也。", "19359": "《主治备要》云：是动则病口苦，善太息，胸胁痛，不能转侧，甚则面微有尘，体无膏泽，足外反热，是为阳厥。是主胆所生病者，头痛颔肿，目锐眦痛，缺盆中肿痛，腋下肿，马刀挟瘿，汗出振寒，疟，胸、肋、胁、髀、膝，外至胫、绝骨、外踝前及诸节皆痛。《脉诀》云：左关，肝与胆脉之所生也。先以轻手得之，是胆，属表；后以重手取之，是肝，属里也。肝合筋，肝脉循经而行。持脉指法，如十二菽之重，按至筋平，脉道如筝弦者，为弦；脉道迢迢者，为长。此弦长，乃肝家不病之状也。肝脉本部在筋，若出筋上，见于皮肤血脉之间者，是其浮也；入于筋下，见于骨上，是其沉也。临病细推之，举一知十之道也。", "19360": "（三）心之经，心脉本部在于血，手少阴君，丁火也。", "19361": "经曰：心者，五脏之尊也，号帝王之称也。与小肠通为表里，神之所〔舍〕，又〔主〕于血，属火，旺于夏，手〔少〕阴（太阳）是其经也。凡夏脉钩，来盛去衰，故曰钩，反此者病。来盛去亦盛，为太过，病在外；来衰去亦衰，为不足，病在内。太过，令人〔身〕热而骨痛，口疮而舌焦引水；不及，令人〔躁〕烦，上为咳唾，下为气泄。其脉如循琅〔玕〕，如连珠，曰平；来而啄啄连属，其中微曲，曰病；脉来前曲后〔倨〕，如〔操〕带钩，曰死。思虑过多〔则怵惕〕，怵惕则伤心，心伤则神失，神失则恐惧。又真心痛，手足寒而过〔节〕，则旦占夕死。又心有水气，身肿不〔得〕卧，烦躁。心中风，则吸吸发热，不能行立，饥而不〔能〕食，食则呕吐。夏心脉〔旺〕，左手〔寸口〕浮大而散，曰平；反此则病。若沉而滑者，水〔来〕克火，十死不治。长而弦者，木来归子，不治自愈。缓而大者，土来入火，〔为〕微邪相干，无所害。心病则胸中痛，〔胁〕满〔胀〕，肩背臂膊皆〔痛〕；虚则多惊悸〔惕惕然〕无眠，胸〔腹及〕腰背引痛，喜悲。心积气久不去，则苦烦，心中痛。实则笑不休，梦火发；心气盛则梦喜笑〔及〕恐畏。邪气客于心，则梦烟火，心〔胀〕气短，夜卧不宁，懊𢙐，气〔逆〕往来，腹中热，喜水涎出。心病，日中慧，夜半甚，平旦静。又左手脉大，手热腋肿；大甚，胸中满而烦，澹澹大动，面赤目黄也。心病，先心痛，时刻不止，关〔格〕不通，身重不已，三日死。心虚甚，则畏〔人〕，〔瞑〕目欲眠，精神不守，魂魄妄行。心脉沉之小而紧，浮之〔不〕喘，苦心下气坚，食不下，喜咽唾，手热烦满，多忘，太息，此得之思虑太过也。其脉急甚，瘛疭；微急则心中痛，引前后胸背，不下食。缓甚则痛引背，善泪。小甚则哕，微小则消〔瘅〕。滑甚则为〔渴〕，微滑则心〔疝〕，引脐腹鸣。涩甚谙不语。又心脉坚搏而长，主舌强不能言；软而散，当慑怯不食也。又急甚〔则〕心疝，脐下有病形，烦闷少气，大热上煎。又心病狂言，汗出如珠，身厥冷，其脉当浮而〔大〕，反沉濡而滑，其色当赤，而反黑者，水克火，不治，十死。又心积，沉之空空，上下往来无常处，病胸满悸，腹中热，面颊赤，咽干，躁烦掌热，甚则吐血，夏瘥冬甚，宜急疗之，止于旬日也。又赤黑色入口必死也。面目赤色亦死，赤如〔衃〕血亦死。又忧〔恚〕思虑太过，心气内去，其色反和而盛者，不出十日死。扁鹊云：心绝一日死，色见凶多，人虽健〔敏〕，号曰行尸，一年之中，祸必至矣。又其人语声前宽后急，后声不接前声，其声浊恶，其口不正，冒昧善笑，此风入心也。又心伤则心损，手足不遂，骨节离解，舒缓不自由，利下无休，此病急宜治之，不过十日而〔亡〕矣。又笑不休，呻而复忧，此水乘火也，阴〔击〕于阳，阴起阳伏，伏则热，热生狂冒，谵〔乱〕妄言，不可采〔问〕，心已损矣。扁鹊云：其人唇口赤色可治，青黑色即死。又心〔疟〕则先烦而后渴，翕翕发热也，其脉浮紧而大是也。心气实而（大）便不利，腹满身热而重，温温欲吐，吐而不出，喘息急，不安卧，其脉左寸口与人迎皆实大者是也。心虚则恐悸多惊，忧思不乐，胸腹中苦痛，言语战栗，恶寒恍惚，面赤目黄，〔喜〕血衄，其脉左寸口虚而微者是也。此心脏寒热虚实，生死逆顺脉证也。", "19362": "小肠者，受盛之腑也，与心为表里，手太阳是其经也。小肠绝者，六日死，绝则发直如麻，汗出不已，不能屈伸。又心病传小肠，小肠咳则气咳，（气咳）一齐出也。小肠实则伤热，（伤）热则口疮生；虚则伤寒，伤寒则泄脓血，或〔泄黑〕水，〔其〕根在小肠也。小肠寒则下，〔肿〕重〔有〕热久不出，则渐生痔；有积则夕发热而旦止；病气发则使人腰下重，食则窘迫而便难，是其候也。小肠胀则小〔腹䐜〕胀，引〔腰而〕痛厥；邪入小肠，则梦聚井邑中，或咽痛颔肿，不可回首，肩似拔，臑似折〔也〕。又曰：心者，主也，神之舍也，其脏（固）密，而不易伤，伤则神去，神去则（心死）矣。故人〔心〕多不病，病即死不可治也，〔惟〕小肠受病〔多〕也。又左寸口阳绝〔者〕，（则）无小肠脉也，六日死。有热邪则小便赤涩，实则口〔生〕疮，身热往来，心中烦闷，身重。小肠主于舌之官也，和则能言，而机关利健，善别其味也。虚则〔左〕寸〔口〕脉浮而微，软弱不禁按，病惊惧狂无所守，心下空空然不能言语者。此小肠虚实寒热，生死逆顺脉证之法也。", "19363": "《主治备要》云：是动〔气也〕则病嗌痛颔肿，不可以顾，肩似拔，臑似折，〔是〕主液（血）所生病者，耳聋，目黄，颊肿，颈、颔、肩、臑、肘、臂外后廉痛。《脉诀》云：左寸，小肠心脉之所出也，先以轻手得之，是〔小肠〕属表；后以重手得之，是〔心〕属里。心合血脉，心脉循血脉而行，持脉指法，如六菽之重，按至血脉而得者为浮；稍稍加力，脉道粗大〔者〕为大；又稍稍加力，脉道润软者为散。此乃浮大而散，心家不病脉之状也。心脉本部，在于血脉，若出于血脉之上，见于皮肤之间，是其浮也；入于血脉之下，见于筋骨之分，是其沉也。", "19364": "（五）脾之经，脾脉本在肌肉，足太阴，湿，己土。", "19365": "经曰：脾者，土也，谏议之官，主意与智，消磨五谷，寄在（胸）中，养于四旁，旺〔于〕四季，正主长夏，与胃为表里，足太阴（阳明），是其经也。扁鹊云：脾病则面黄色痿，实则舌强直，不嗜食，呕逆，四肢缓；虚则多澼喜吞，注痢不已。又脾虚，则精不胜，元气乏力，手足缓弱，不能自持。其脉来似流水，曰太过，病在外（也）；如鸟距，曰不及，病在内。太过令人四肢沉重，言语謇涩；不及令人中满，不食乏力，手足缓弱不遂，涎引口中，四肢肿胀，溏泄不时，梦中饮食。脾脉来而和柔者，如鸡践地，曰平；来实而满，〔稍〕数，如鸡举足，曰病；又如鸟之啄，如鸟之距，如〔屋〕之漏，曰死。中风则翕翕发热，状如醉人，腹中〔烦〕满，皮肉〔𥆧𥆧〕（而起），〔其脉〕阿阿然〔缓〕，曰平；〔反〕弦急者，肝〔来〕克脾也，真鬼相遇，大凶之兆也。又微涩〔而〕短者，肺乘于脾，不治自愈；又沉而滑者，肾来乘脾，亦〔为不〕妨。又浮而洪，心来生脾，不为疾耳。脾病色黄体重，失便，目直视，唇反张，爪甲青，四肢沉，吐食，百节疼痛不能举，其脉〔当〕浮大而缓，〔今〕反〔弦〕急，其色青，死不治。又脾病，其色黄，饮食不消，〔心〕腹胀满，体重节痛，大便〔硬〕，（小便）不利，其脉微缓而长者，可治。脾气虚，则大〔便滑〕，小便〔利〕，汗出不止，五液注下，为五色注痢下也。又积在其中，久不愈，四肢不收，黄疸，食不为「肌肤」，气〔满〕胀喘喘而不〔定〕也。脾实则时梦筑墙垣盖屋，盛则梦歌乐，虚则梦饮食不足。厥邪客于脾，则梦大泽丘陵，风雨〔坏屋〕。脾胀则善哕，四肢急，体〔重〕，不食善〔噫〕。脾病〔日昳慧〕，平旦甚，日中持，下晡静。脉急甚，则瘛疭；微急，则膈中不利，食不下而还出。缓甚，则痿厥；微缓，则风痿，四肢不〔收〕。大甚，〔则〕暴仆；微大，〔则痹疝〕，气〔裹大脓血〕在肠胃之〔外〕。小甚，则寒热作；微小，则消〔瘅〕。滑甚，则颓疝；微滑，则虫毒，肠鸣中热。涩甚，则肠𤻊；微涩，则〔内〕溃下脓血。脾脉至，大而虚，则有积。脾（气）绝，则十日死。唇焦枯无〔纹理〕，（面）青黑者，脾先（死）。脾病，面黄目赤〔者〕，〔可治〕；青黑色入口，半年死；色如枳实〔者〕，一（日）死，吉凶休咎，皆〔见〕其色出〔于〕部〔分〕也。又口噤唇青，四肢重如山，不能自持，大小便利无休歇，饮食不入，七日死。又唇虽痿黄，语声〔啭啭〕者，尚可治。脾病，（水）气久不去，腹中痛鸣，徐徐热汗出，其人〔本意宽〕缓，（今反急，怒语而鼻笑），不能答人，此不过一（日），祸必至矣。又脾中寒热，则使人腹中痛，不下食，病甚〔舌〕强语涩，转〔筋〕卵〔缩〕，〔阴股〕腹中引痛，身重，不思食，膨胀，变则水泄不能卧者，十死不治。脾〔土〕热，则面黄目赤，〔季〕胁痛满；寒则吐涎沫而不食，四肢痛，滑泄不已，手足厥，甚则战栗如疟也。临病之时，切要〔明〕察脉证，然后投药，此脾脏虚实寒热，生死逆顺脉证之法也。", "19366": "胃者，脾之腑也，又名〔水〕谷之海，与脾为表里。胃者，人之根本，胃气壮，则五脏六腑皆壮（也），足阳明是其经也。胃气绝，五日死。实则中胀便难，肢节痛，不下食，呕逆不已。虚则肠鸣胀满，滑泄。寒则腹中痛，不能食〔冷〕物。热则面赤如醉人，四肢不〔收〕持，不〔得〕安眠，语狂㲋乱，便硬者是也。病甚则腹胁胀满，呕逆不食，当心痛，（下上）不〔通〕，恶闻香臭，嫌人语，振寒，善欠伸。胃中热，〔则〕唇黑；热甚，则登高而歌，弃衣而走，颠狂不定，汗出额上，鼽〔衄〕不止。虚极则四肢肿满，胸中短气，谷不化，中满也。胃中风，则溏泄不已；胃不足，则多饥，不消食。病人鼻下平，则胃中病，渴者可治。胃脉搏坚而长，其色〔黄赤者，当病折髀〕。其脉弱而散者，病食〔痹〕。右关上浮而大者，虚也；浮而短涩者，实也；浮而微滑者，亦〔实〕也；浮而迟者，寒也；浮而数者，热也。此胃〔腑〕虚实寒热，生死逆顺脉证之法也。", "19367": "《主治备要》云：是动则病〔凄沧〕振寒，善〔呻〕数欠，颜黑，病至则恶人与火，闻木声则惕然而惊，心欲动，〔独〕闭户〔塞牖而〕处，甚则登高而歌，弃衣而走，贲响腹胀，是为骭厥。《脉诀》云：右关上，脾胃脉之所出也，先以轻手得之，是胃，属表；后以重手得之，是脾，属里。脾合肌肉，脾脉循肌肉而行，持脉指法，如九菽之重，按至肌肉，脉道如微风轻扬柳梢者为缓；又稍稍加力，脉道敦实者为大，此为缓大，脾家不病〔脉〕之状也。脾脉本部在肌肉，若出于肌肉之上，见于皮毛之间者，是其浮也；入于肌肉之下，见于筋骨之分者，是其沉也。", "19368": "是动则病手心热，肘臂挛急，腋肿，甚则胸胁〔支〕满，心中〔憺憺〕大动，〔面〕赤㲋黄，喜笑不休，〔是〕主脉所生病者，烦心，心痛，掌中热，治法与小肠同。", "19369": "三焦者，人之三元〔之〕气也，号曰中清之腑，总领五脏六腑，荣卫经络，内外左右上下之气也。三焦通，则上下内外左右皆通也。其于灌体周身，和内调外，荣养左右，宣通上下，莫大于此也。又名玉海水道。上则曰三管，中则曰霍乱，下则曰走泄，名虽三而归（其），有其名而〔无〕其形，亦号孤独之府。而卫〔出〕于上，荣出于中，上者络脉之系也，中者经〔脉〕之系也，下者水道之系也，〔亦又〕属膀胱之宗始，主通阴阳，〔调虚实〕，呼吸，有病则（善）腹胀气满，小〔腹〕坚，〔溺〕而不得，（大便）窘迫也。溢则作水，留则作胀，手少阳是其经也。又上焦实热，则额汗〔出〕而身无汗，能食而气不利，舌干、口焦、咽闭之类，腹胀肋胁痛。寒则不入食，吐酸水，胸背引痛，嗌干，津不纳也。实则食已而还出，〔膨膨〕然不乐。虚则不能〔制〕下，遗溺，头面肿也。中焦实热，则下上不通，腹胀而喘，下气不上，上气不下，关〔格〕不利也。寒则下利不止，饮食不消，中满。虚则肠鸣（膨膨）也。下焦实热，则小便不通，大便亦难，苦〔重〕痛也。虚寒则〔大〕小便〔泄〕下不止也。三焦〔之气〕和则内外和，〔逆〕则内外逆也。故云三焦者，人之三元〔之〕气也。此三焦虚〔实〕寒热，生死逆顺之法也。", "19370": "《主治备要》云：是动则病耳聋，浑浑焞焞，嗌肿喉〔痹〕。〔是〕主气所生病者，汗出，目〔锐〕眦〔痛〕，颊〔痛〕，耳后肩臑肘臂外〔皆〕痛，小指次指不用。《脉诀》云：右尺三焦、命门脉之所出，先以轻手得之，是三焦，属表；后以重手得之，是命门，属里也。上焦〔热〕，凉膈散、〔泻〕心汤；中焦热，〔调〕胃承气汤、〔泻〕脾散；下焦热，大承气〔汤〕、三才封髓丹。气分热，柴胡饮子、白虎汤；血分热，桃仁承气汤、清凉饮子；通治其热之气，三黄丸、黄连解毒汤是也。", "19371": "（九）肺之经，肺（之）脉本部在于皮毛，手太阴，燥，辛金。", "19372": "〔经曰〕：肺者，魄之舍也，生气之源，号为相傅，乃五脏之华盖也。外养皮毛，内荣肠胃，与大肠为表里，手太阴（阳明）是其经也。〔肺〕气通〔于鼻〕，〔和〕则知其香臭，有病则善咳，鼻流清涕。〔凡〕虚实寒热，则皆使人喘嗽，实则梦刀兵恐惧，肩息，〔胸中满〕；〔虚则寒热喘息〕，利下，少气力，多悲感，旺于秋。其脉浮而毛，曰平；又浮而短涩者，肺脉也；其脉来毛而中央坚，两（头）虚，曰太过，则令人气逆，胸满背痛；不及，令人喘呼而咳，上气见血。又肺脉来厌厌聂聂，如（循）榆荚，曰平；来如循鸡羽，曰病；来如物之浮，如风吹鸟背上毛者，死。（真）肺脉至，大而虚，如〔以〕毛羽中人（皮）肤，其色白赤不泽，其毛折者死。微毛曰平，毛多曰病，毛而弦者春病，弦甚者即病。又肺病，吐衄血，皮热脉数，颊赤者死。又久咳而见血身热，而短气，脉〔当〕涩，而今反浮大，色〔当〕白，而今反赤者，火克金，十死不治。肺病喘咳身寒，脉迟微者，可治。秋旺于肺，其脉多浮涩而短，曰平；反此为病。又反洪大〔而〕长，是火刑金，亦不可治；反得沉而软滑者，肾乘于肺，不治自愈；反浮大而缓者，是脾来〔生〕肺，不治自瘥；反弦而长者，〔是〕肺被肝〔横〕，为微邪，虽病不妨。虚则不能息，〔身〕重；实则咽嗌干，喘嗽上气，肩背痛。有积，〔则〕胁下胀满痛。中风则口燥而喘，身运而重，形似冒而肿，其脉按之虚弱如葱叶，下无根者死。中热则唾血，其脉细紧浮数芤者，皆主失血，此由躁扰嗔怒劳伤得之，气壅结所为也。〔肺胀则其人喘咳〕而目〔如〕脱，其脉浮大〔者〕是也。又肺痿则〔吐〕涎沫，而咽干欲饮者，欲愈；不饮者，未瘥。又咳而遗小便者，上虚不能制其下故也。其脉〔沉〕涩者，病〔在〕内；浮滑者，病〔在〕外。肺死则鼻孔开而黑枯，喘而目直视〔也〕。肺绝则十二日死，其状腹满，泄利不觉出，面白目青，此为乱经，虽天命亦不可治。又饮酒当风，中于肺，咳嗽喘闷，见血者，不可治也；面黄目白，亦不可治也。肺病颊赤者死。又言〔谙〕，喘急短气，好唾，此为真鬼相害，十死十，百死百，大逆之兆也。又阳气上而不降，燔于肺，肺自结邪，〔胀〕满喘急，狂言瞑目，非〔当〕所说，而口鼻张，大小便俱〔胀〕，饮水无度，此因〔热伤于肺〕，肺化〔为〕血，半年死。又肺〔疟〕使〔人〕心寒，寒甚则发热，寒热往来，休作不定，多惊，咳〔喘〕如有所见者是也。其脉浮而紧，〔又〕滑而数，又迟而涩小，皆为肺〔疟之脉〕也。又其人素声清而雄〔者〕，暴不〔响〕亮，噎而气短，用力言语〔难〕出，视不转睛，虽未为病，其〔人〕不久。肺病实，则上气喘闷，咳嗽身热，脉大是也。虚则力乏喘促，右胁胀，言语气短者是也。乍寒乍热，鼻塞颐赤面白，皆肺〔病〕之象也。〔此〕肺脏虚实寒热，生死逆顺脉证法也。", "19373": "经曰：大肠者，肺之腑也，传道之司，号监仓之官。肺病久，则传入大肠，手阳明是其经也。寒则泄，热则结，绝则利下不止而死。热极则便血。又〔风中〕大肠则下血。又实热则〔胀〕满而大便不通；虚寒则滑泄不止。大肠〔者〕，乍虚乍实，乍来乍去，寒则溏泄，热则后重，有积物则发寒栗而战，热则发渴如疟状。积冷不去，则当脐痛，不能久立，痛已则泄白物是也。虚则喜满喘嗽，咽中如核妨矣。此乃大肠虚实寒热，生死〔逆顺〕脉证之法也。", "19374": "《主治备要》云：是动则病齿痛，颈肿。是主津液所生病者，目黄，口干，鼽衄，喉痹，肩前臑痛，大指次指〔痛〕不用。气有余，则当脉所过者热肿，虚则寒栗不复。《脉诀》云：右寸大肠肺脉之所出也，先以轻手得之，是大肠，属表；后以重手得之，是肺，属里。肺合皮毛，肺脉循皮毛而行，持脉指法，如三菽之重，按至皮毛而得之者，为浮；稍稍加力，脉道不利，为涩；又稍加力，脉道缩入关中，上半指不动，下半指微动者，为短。此乃浮涩而短，肺不病之状也。肺脉本部出于皮毛之上，见于皮肤之表，是其浮也；入于血脉肌肉之分，是其沉也。", "19375": "（十一）肾之经，命门，肾脉本部〔在〕足少阴，寒，癸水。", "19376": "经曰：〔肾者〕，精神之舍，性命之根，外通于耳，男子以〔藏〕精，女子以系胞，与膀胱为表里，足少阴（太阳）是其经也。肾气绝，则不尽天命而死也。旺于冬，其脉沉滑曰平，反此者病。其脉来如弹，〔石〕名曰太过，病在外；其去如解索，谓之不及，病在内。太过令人解㑊脊痛，而少气不欲言；不及则令人心悬，小腹满，小便滑，变黄色。又肾脉来喘喘累累如钩，按之紧曰平；又来如引葛，按〔之〕益坚曰病；来如转索，辟辟如弹石曰死。又肾脉但石无胃气亦死。肾有水，则腹胀脐肿，腰重痛，不得溺，阴下湿，如同牛鼻头汗出，〔足〕为逆寒，大便难。肾病，手足冷，面赤目黄，小便不禁，骨节烦疼，小〔腹〕结瘀热，气上冲心，脉〔当〕沉〔细〕而滑，今反浮大，其色当黑，〔今反黄〕，其人吸吸少气，两耳若聋，精自出，饮食少，便下清谷，脉迟可治。冬则脉沉而滑曰平，反浮大而缓，是土〔来〕克水，〔大逆，十死不治〕；反浮涩而短，是肺〔来〕乘肾，〔虽病〕，易治；反弦〔细而〕长〔者〕，肝〔来〕乘肾，不治自愈；反浮大而洪，心〔来〕乘肾，不妨，肾病腹〔大胫〕肿，〔喘咳身重〕，〔寝〕汗出，憎〔风〕。虚则胸中痛。阴邪入肾，则骨痿腰痛，上引背脊痛。过房，汗出当风，浴水久立，则肾损。其脉急甚，则病痿；微急则沉厥奔豚，足不收。缓甚则虚损；微缓则洞泄，食不下，入咽还出。大甚则阴〔痿〕；微大则水气〔起〕脐下，〔其肿埵埵然〕而上至胸者，死〔不治〕。小甚则（亦）洞泄；微小则消瘅。滑〔甚〕则癃〔𤻊〕；微滑则骨痿，坐不能起，目视〔见〕花。涩甚则寒壅塞;微涩则〔不月〕痔疾。其脉〔之〕至〔也〕，坚而大，有〔积〕气在阴中及腹内也，名〔曰〕肾〔痹〕，得之浴清水，卧湿地来。沉而大坚，浮之而紧，手足肿厥，阴痿不起，腰背痛，小腹〔肿〕，心下有水气，时胀满〔而〕洞泄，此因浴水未干，而房事得之也。虚则梦舟（舡）溺人，〔得其时，梦〕伏水中，〔若有所畏〕；实则梦临〔深〕投水中。肾胀则腹〔痛〕满，引脊腰痹痛。肾病夜半平，四季甚，下晡静。肾生病，口热舌干，咽肿，上气，嗌干及痛，烦心而痛，黄疸，肠癖，痿厥，腰脊背急痛，嗜卧，足心热而痛，胻酸。肾病久不愈，而膂筋疼，小便闭，而两胁胀满，目盲者死。肾〔之〕积，〔苦〕腰〔脊〕相引而痛，饥见饱减，〔此肾中〕寒结在脐下也。积脉来细而软，附于骨者是也，面白目黑，肾已内伤，八日死。又阴缩，小便不出，出而不止者，亦死。又〔其〕色青黄连耳，其人年三十许，百日死；若偏在一边，一（年）死。实则烦闷，脐下重；热则口舌焦而小便涩黄；寒则阴中与腰背俱肿疼，面黑耳聋，干呕而不食，或呕血者是也。又喉鸣，坐而喘咳，唾血出，亦为肾虚寒，〔气〕欲绝者。此肾脏虚实寒热，生死逆顺脉证之法也。", "19377": "经曰：膀胱者，津液之府也，与肾为表里，号为水曹〔掾〕，〔又〕名玉海，〔足〕太阳是其经也。总通〔于〕五腑，所以五腑有疾，则应膀胱；膀胱有疾，〔即应〕胞囊〔也〕。〔伤热则〕小便不利，热入膀胱，则其气急，而小便黄涩也；膀胱寒则小便数而清（白）也。又水发则〔其〕根在膀胱，〔四肢瘦小〕，而腹反大〔是〕也。又膀胱咳〔久〕不已，传之三焦，满而不欲饮食也。然〔上〕焦主心肺之病，人有热，则食不入；寒则神不守，泄下利不止，语声不出也。实则上绝于〔心〕气不行也，虚则引热气于肺。其三焦和，则五脏六腑之气和，逆则皆逆。膀胱经中有厥气，〔则〕梦行不快；满胀，则小便不下，脐下〔重〕闷，或〔肩痛也〕。绝〔则〕三日死，死在鸡鸣也。此膀胱虚实〔寒热〕生死逆顺脉证之法也。", "19378": "《主治备要》云：是动则病（气）冲头痛，目似脱，项似拔，脊痛，腰似折，髀不可以曲，腘〔如〕结，〔踹〕如裂，是为踝厥。〔是〕主筋所生病者，痔，疟，狂，癫疾，头囟项痛，目黄泪出，鼽衄，项、〔背〕、腰、尻、腘、〔踹〕，脚皆痛，足小指不用。《脉诀》云：左尺，膀胱肾脉之所出也，先以轻手得之，是膀胱，属表；后以重手得之，是肾，属里。命门与肾脉循骨而行，〔持〕脉指法，按至骨上得之为沉；又重手按之，脉道无力者，为濡；举手来疾流利者为滑。此乃沉濡而滑，命门与肾〔脉〕不病之状也。命门与肾部近骨，若出于骨上，见于皮肤血脉筋骨之间，是其浮也；入而至骨，是其沉也。", "19379": "注云：二之气为病，多发风湿风热。经曰：风伤于阳，湿伤于阴，微则头痛身热，发作风湿之候，风伤于血也，湿伤于胃气也。是以风湿为病，阴阳俱虚，而脉浮，汗出，身重，眠多鼻息，语言难出。以上二证，不宜热药，下之必死。二之气病，宜以桂枝麻黄汤发汗而已。", "19380": "小满以上，三之气，小满至大暑，少阳相火之位，阳〔气〕发万物俱盛，故云太阳旺。其脉洪大而长，天气并万物人脉盛。", "19381": "大暑未上，四之气，大暑至秋分，太阴湿土之位，阳气发散之后，阴已用事，故曰太阴旺，此三阴三阳，与天气标本阴阳异矣。脉缓大而长，燥金旺；紧细短涩，以万物干燥，明可见矣。", "19382": "秋分酉上，五之气，秋分至小雪，阳明燥金之位，阳衰阴盛，故曰金气旺，其脉细而微。", "19383": "小雪亥上，终之气，小雪至大寒，太阳寒水之位，阴极而尽，天气所收，故曰厥阴旺。厥者，极也，其脉沉短而〔微〕。万物收藏在内，寒气闭塞肤腠，气液不能越，故脉微也。", "19384": "凡痢疾腹痛，以白芍药、甘草为君，当归、白术为佐，见血先后，分三焦热〔论〕。凡泻痢小便白，不涩为寒，赤涩为热也。又法曰：完谷不化，而色不变，吐利腥秽，澄澈清冷，小便清白不涩，身凉不渴，脉细而微者，寒证也。谷虽不化，而色变非白，烦渴，小便赤黄而或涩者，热证也。凡谷消化，无问他证及色变，便为热也。寒泄而谷消化者，未之有也。泻痢，白术、甘草；水泻，米谷不化，防风；伤食微加大黄；腹胀，厚朴；渴者，白茯苓；腹痛，白芍药、甘草为主；冬月，白芍药一半，白术一半，夏月制黄芩。先见脓血，后见大便者，黄柏为君，地榆佐之；脓血相杂而下者，制大黄；先大便而后脓血者，黄芩二制，皆以当归根梢，详其上下而用之；腹不病，白芍药半之。身体困倦，目不欲开，口不欲言，黄耆、人参；沉重者，制苍术。不思饮食者，木香、藿香叶。里急，大黄、芒硝、甘草下之。后重者，木香、藿香、槟榔和之。", "19385": "脉浮在表，当汗之；脉沉在里，当下之。背后搐〔者〕，羌活、防风、独活、甘草。〔向〕前搐者，升麻、白芷、防风、独活、甘草。两傍搐者，柴胡、防风、甘草；右搐者，白芷加之。", "19386": "经曰：凡疮热甚郁结，而荣卫不得宣通，故多发白痂，是时疮口闭塞，气不通泄，热甚则生风也。《治法》曰：破〔伤〕中风，风热燥甚，怫郁在表，而里气尚平者，善伸数欠，筋脉拘急，或时恶寒而搐，脉浮数而弦者，以辛热治风之药，开冲结滞，荣卫宣通而愈也。凡用辛热之药，或以寒凉之药佐之尤妙，免致药不中病，而风转甚。若破〔伤〕中风，表不已，而渐入于里，则病势转甚；若里未太甚，而脉在肌肉者，宜以退风热、开结滞之寒药调之。或以微加治风辛热药，亦得以意消息，不可妄也。至宝丹亦凉药也。如〔热〕甚于里，以大承气汤下之。", "19387": "（苦寒为君：黄芩、黄柏、黄连、知母、生地黄酒洗。甘〔温〕为佐：黄耆、人参、甘草。大辛解结为臣：连翘、当归、藁本。辛温活血去〔瘀〕：当归梢、苏木、红花、牡丹皮。）脉浮者为在表，宜行经：黄连、黄芩、连翘、当归、人参、木香、槟榔、黄柏、泽泻。在腰以上至头者，枳壳仍作引药，引至疮所。（出毒消肿：鼠黏子。排〔脓〕：肉桂。入心引血化经汗而不溃，〔伤〕皮：王瓜根、三棱、莪术、黄药子。痛甚：芩、连、柏、知母。）脉沉者在里，当疏利脏腑，利后，用前药中加大黄，取利为度，随虚实定分两。痛者，止以当归、黄耆止之。", "19388": "妇人带下，举世皆曰寒，误之甚矣。所谓带下者，任脉之病也。经曰：任脉者，起于中极之下，以上毛际，循腹里，上关元，至于咽喉，上颐循面入目。注言：任脉自胞上，过带脉，贯络而上，然其病所发，正在带脉之分，而淋沥以下，故曰带下也。其赤白说者，〔与〕痢义同，而无〔独〕寒者。法曰：头目昏眩，口苦舌干，嗌咽不利，小便赤涩，大便涩滞，脉实而数者，皆热证也。", "19389": "注云：喘，热则息数气粗而为喘也，故热则脉实而甚数，喘之象也。", "19390": "注云：三焦为水谷传化之路，热气甚，则传化失常，而吐下霍乱，火性燥动故也。大法曰：吐利烦渴为热，不渴〔为〕寒。或〔热〕吐〔泻〕，始得之亦有不渴者，若不止，则亡液而后必渴也。或〔寒〕本不渴，若不止，〔亡〕津液过多，则亦燥而渴也。若寒者，脉当沉细而迟；热者，脉当实大〔而〕数。或损气亡液过极，则脉亦不能实数，而反缓弱也，虽尔，亦不为热矣。", "19391": "注云：湿为留饮，为痞隔，而传化失常，故甚则霍乱吐〔泻〕也。大法曰：若利色青者，肝木之色，由火甚制金，使金不能平木，则肝自甚，故色青也。或言利色青为寒〔者〕，误也。（则）如仲景曰：少阴病，下利清水，色纯青者，热在里也，大承气汤下之。及小儿热甚急惊，利色多青，为热明矣。利色黄〔者〕，由火甚则水必衰，而脾土自旺，故色黄也。利色红者为热，心火之色也；或赤者，热深也。利色黑而反为热者，由火盛过极，而反兼水化制之，故色黑也。（则）如伤寒阳明热病，则日晡潮热，甚则不识人，循衣摸床，如见鬼状，独语，法当大承〔气〕汤下之。大便不黑者易治，黑则难治也。诸痢同法。然辨痢色以明〔寒〕热者，更当审其〔饮食〕药物之色也。（则）〔如〕小儿病热，吐利霍乱，其乳未及消化，而痢尚白者，不可便言是寒，当以脉证别之。又法曰：凡泄利，小便清白，不涩为寒，赤涩者为热也。又法曰：完谷不化，而色不变，吐利腥秽，澄澈清冷，小便不涩，身凉不渴，脉迟细而微者，寒证也。谷虽不化，其色变〔非〕白，烦渴，小便赤黄而或涩者，热证也。凡谷消化者，无问他证，便为热也。", "19392": "注云：有声非妄闻也。耳为肾窍，交会〔手〕太阳、少阴、足厥阴、少阴、少阳之经，若水虚火实，而热气上甚，客其经络，冲于耳中，则鼓其听〔户〕，随其脉气微甚而作音声也。故经曰：阳气为物，上甚而跃，故耳鸣也。然音在耳中，故微亦闻之也。", "19393": "注云：惕跳动也，火主动，故夏热则脉洪大〔而〕长，𥆧瘈之象也。", "19394": "注云：凡物湿润则滑泽，干燥则涩滞，燥湿相反故也。〔如〕遍身中外涩滞，皆属燥金之化，故秋脉涩。涩，涩也。或麻者，亦由涩也。由水液衰少而燥涩，气行壅滞，而不〔得〕滑泽通利，气强攻冲，而为麻也。俗方〔多〕用乌附辈者，令气因之〔冲〕开道路，以得通利，气行，故麻愈也。无热证，即当此法，治之甚佳。或风热胜湿为燥，因而病麻，（则）〔宜以〕退风散热，活血养液，润燥通气之凉药调之，则麻自愈也。治〔诸〕燥涩，只如此〔法〕是也。", "19395": "注云：皮肤启裂也。干为天，为燥金；坤为地，为湿土。天地相反，燥湿异〔用〕，（故）燥金主于紧〔敛〕，故秋脉紧细而微；（而）湿土主于纵缓，故六月其脉缓大而长也。如地湿则纵缓滑泽，干则紧敛燥〔涩〕，皴揭之理明矣。俗言皴揭为风者，由风能胜湿，而为燥故也。经云：厥阴所至，为风府，为璺启，由风胜湿而为燥也。", "19396": "注云：腹中坚硬，按之应手，谓之症也。水体柔顺，而今反坚硬如地体者，亢则害，承乃制也。〔故病湿〕过极而为痓，反兼风化制之也。风病过极而反燥，筋脉劲急，反兼金化制之也。燥病过极而烦渴，反兼火化制之也。热病过极而反出五液，或为战栗恶寒，反兼水化制之也。其为治者，俾以〔泻〕其过极之气，以为病本，不可反误治其兼化也。夫五常之道，甚〔而〕无以制之，则造化息矣。如春木旺而多风，风大则反凉，是反兼金化制其木也。大凉之下，天气反温，乃火化承其金也。夏火热极，体反出液，是反兼水化制其火也。因而湿〔蒸〕云雨，乃土化承于水也。雨湿过极，而兼〔烈〕风，乃木化制其土也。飘〔骤〕之下，秋气反凉，乃金化承于木也。凉极而反燥，乃火化制其金也。因而〔以为冬寒〕，乃水化承于火也。寒极则水〔凝〕如地，乃土化制其水也。凝冻极而起东风，乃〔木〕化承土而成岁也。凡不明病之标本者，由未知（此变化之道）也。", "19397": "注云：腹中虽硬，而忽聚忽散，无有常准。经曰：血不流而寒薄，故血内凝（不流）而成瘕也。一云：腹内积病也。又曰：小肠移热于大肠，为伏瘕，为沉。〔注〕曰：小肠热以传入大肠，两热相搏，则血溢而为〔虙〕瘕也。血涩不利，则月事沉滞而不行，故云为〔虙假〕、为沉〔虙〕。乃或阳气郁结，〔怫热壅滞〕而坚硬不消者，非寒瘕也，宜以脉〔证〕别之。瘕〔一为〕疝，传写之误。", "19398": "注云：小腹连卵肿急绞痛也，寒主拘缩故也。寒极而土化制之，故肿满也。经云丈夫𤻊疝，谓阴器连小腹急痛也。经〔注〕曰：寒气聚而为疝也。脉急者，寒之象也。然，寒则脉当短小而迟，今言急者，非急数而洪也，由紧脉主痛，急为病甚也。病寒缩急，亦短小也。所以有痛而脉紧急者，脉为心所养也。凡气为痛，则心神不宁而紧急，不得舒缓，故脉亦（从）之而见也。欲知何气为其痛〔者〕，诊其紧急相兼之脉可知矣。如紧急洪数，则为热痛之类也。", "19399": "注云：寒主拘缩，故急痛也。寒极则血脉凝冱，而反兼土化制之，故坚痞而腹痛也。或热郁于内，而腹满坚结痛〔者〕，不可言为寒也，当以脉别之。", "19400": "注云：胃热则消谷善饥，故病寒〔则〕食虽已而不饥也。胃〔膈〕润泽，而无燥热故也。或邪热不杀谷，而腹热胀满，虽数日而不食，亦不饥者，不可言为寒也。由阳热太甚而郁结，传化失常，故虽不食。亦不饥也。二证以脉别之自见。", "19401": "注云：阴水〔主〕于清净，故病寒则四肢逆冷，而禁止坚固，舒卷不便〔利〕也。故冬脉沉（而）短以敦，病之象也，或病〔寒〕尚微，而未至于厥逆〔者〕，不可反以为热；或热〔甚〕而成阳厥者，不可反以为病寒也。然阴厥者〔之〕病脉候，皆为阴证，身凉不渴，脉迟细而微，未〔尝〕见于阳证也。其阳厥者〔之〕病脉证，皆为阳证，热极而反厥，〔时〕复反温，虽厥而烦渴谵妄，身热而脉数也。若阳厥〔极〕深，而至身冷，反见阴脉，而欲绝者，止为热极而欲死也。经曰：一阴一阳之谓道，偏阴偏阳之谓疾，阴阳以平为和，以偏为病，万物皆负阴抱阳而生，故孤阴不〔长〕，独阳不成；是以阳气极甚，而阴气极衰，则阳气怫郁，阴阳偏倾，而不能宣行，则阳气蓄聚于内，而不能营运于四肢，则手足厥冷为阳厥。仲景曰：热深则厥亦深，热微则厥亦微。又曰：厥当下之，下后厥愈。当以凉药养阴退阳，凉膈散、调胃承气汤下之是也。大凡治病者，必先明其标本，标者末，本者根源也。故经曰：先病为本，后病为标。又曰：标本相传，先以治其急者。〔又〕言：六气为本，三阴三阳为标，故病气为本，受病经络脏腑〔谓〕之标。夫标本微甚，治以逆从，不可不通〔也〕。故经曰：知逆与从，正行无问；明知标本，万举万当；不知标本，是〔谓〕妄行。正此谓也。", "19402": "治一切风热郁结，气血蕴滞，筋脉拘挛，手足麻痹，肢体焦痿，头痛昏眩，腰脊强痛，耳鸣鼻塞，口苦舌干，咽嗌不利，胸膈痞〔闷〕，〔咳呕〕喘满，涕唾稠黏，肠胃燥〔热结〕，便溺淋闭。或肠胃蕴热郁结，水液不能浸润于周身，而为小便多出者；或湿热内甚，而〔时〕有〔汗泄〕者；或表之正气与邪〔热〕并甚于里，阳极似阴，而寒战烦渴者；或热甚变为疟疾，久不已者；或风热走注，疼痛麻痹者；或肾水阴虚，心火阳热暴甚〔而〕中风；或暴喑不语，及暗风痫〔者〕；或破伤中风，时发潮热搐〔搦〕，并小儿热甚惊风，或〔斑〕疹〔反〕出不快者；或热极黑陷，将欲死者；或风热疮疥久不愈者；并〔解〕耽酒热〔毒〕，及调理伤寒，发汗不解，头项肢体疼痛，并宜服之。", "19403": "退风散热。治风有二法，〔行〕经和血及开〔发〕腠理。经脉凝滞，非行经则血不顺，是治于内也。皮肤郁结，非开发则荣卫不和，是调理于外也。此亦发散之药也。", "19404": "中府之药也。（大）治诸风，无问新久，手足軃曳，腰脚缓弱，行步不正，精神昏昧，口眼㖞斜，语言謇涩，痰涎壅盛，筋脉挛急，肌肉顽痹，皮肤燥痒，骨节疼，目眩，下注腰脚，疼痛腿重，肿疡生疮；或痛无常〔处〕，游〔走〕不定，及风气上攻，面浮〔肿〕耳鸣，并宜服之。", "19405": "治身热呕吐泄泻，肠癖下利赤白。治癃闭淋痛，利小便。偏荡胃中积聚寒热，〔宣积气〕，通九窍六腑，〔生〕津液，去留结，消蓄水，止渴，〔宽〕中，除烦热心躁。治腹胀痛，补益五脏，大养脾胃肾之气，理内伤阴痿，安魂定魄，补五劳七伤，一切虚损。主痫痓惊悸，健忘，心烦满短气，脏伤咳嗽，饮食不下，肌肉疼痛。治口疮，牙齿疳蚀，明耳目，壮筋骨，通〔经〕脉，和血气，消水谷，保真元，解百药酒食邪毒，〔耐〕劳〔役〕饥渴，〔宣〕热，〔辟〕中外诸邪所伤，久服强志轻身，驻颜延寿，及解〔中〕暑、伤寒、疫疠、饥饱、劳损、忧愁、思虑、〔恚〕怒、惊恐、传染。并汗〔后〕遗热，劳复诸病，并解两感伤寒，能令遍身结滞宣通，气〔和〕而愈。及妇人下乳催生，并产后损液血衰，阴虚热甚，一切热病，并宜服之。兼〔防〕发吹奶乳〔痈〕，或已觉吹乳乳结，顿服即愈，乃神验之仙药也，惟孕妇不可服。", "19406": "治伤寒杂证，内外所伤，日数远近，腹满咽干，烦渴谵妄，心下按之硬痛，小便赤涩，大便结滞，或湿热内〔甚而〕为滑泄，热甚喘咳闷乱，惊悸狂颠，目病口疮，舌肿喉痹痈疡，阳明胃热发〔斑〕，脉沉而可下者。小儿热极风惊，潮搐昏塞，并〔斑〕疹黑陷不〔起〕，小便不通，腹满欲死。或〔斑〕疹后，热不退，久不作痂，或作〔斑〕痈疮癣，久不已者，怫热内盛，痃癖坚积，黄瘦疟疾，久新暴卒心痛，风痰酒〔隔〕，肠垢积滞，久〔壅〕风热，暴伤酒食，烦心闷乱，脉数沉实。或肾水阴虚，阳热暴甚，而僵仆卒中，一切暴喑不语，蓄热内伤，阳厥极深，脉反沉细欲绝。或表〔之〕冲和正气，与邪气并〔之〕于里，则里热亢极〔似〕阴，反为寒战，脉微而绝。或风〔热〕燥甚，客于下焦，而大小便涩滞不通者。或产〔妇〕死胎不下，或两感表里热甚，须可下〔者〕。", "19407": "上除麻仁、桃仁别研如泥，余药细研，炼蜜丸梧子大，每服五十丸至百丸，空心白汤下。〔如血涩而大便燥者，加桃仁酒洗大黄〕。如大便不通而涩，滋其荣〔甚〕者，急加酒洗大黄；如风结燥，大便不行，加〔麻〕仁、大黄；如风湿大便不行者，加皂角仁、大黄、秦艽以利之；如脉涩，觉身有气〔涩〕而大便不通者，加郁李仁、大黄以除气涩。", "19408": "治大寒积冷，脏腑虚〔寒〕，心腹疼痛，胸胁胀满，泄泻肠鸣，下利自汗，米谷不化，阳气暴衰，阴气独盛，手足厥冷，伤寒阴胜，神昏脉短，四肢怠惰，并宜服之。", "19409": "治阴证伤寒，自利不渴，呕哕不止，〔或〕吐利俱作，小便涩；或利，脉微欲绝，腹痛胀满，手足厥冷；或〔病〕内寒外热，下利清谷，四肢沉重；或汗出不止，并宜服之。〔此药助阳救衰〕", "19410": "上㕮咀，每服四钱，水盏半，姜五片，煎至七分，去渣，食前服。挟风不仁，加防风半两；兼湿肿满，加白术半两；筋脉挛急，加木瓜半两；肢节疼，加桂心半两。", "19411": "〔注云〕：五脏更相平也，一脏不平，所胜平之，此之谓也。故云：安谷则昌，绝谷则亡，水去则荣散，谷消则卫亡，〔荣散卫亡〕，神无所居。又仲景云：水入于经，其血乃成；谷入于胃，脉道乃行。故血不可不养，卫不可不温，血温卫和，荣卫乃行，常有天命。", "19412": "大法曰：前人方法，即当时对证之药也。后人用之，当体指下脉气，从而加减，否则不效。余非鄙乎前人而自用也，盖五行相制相兼，生化制〔承〕之体，一时之间，变乱无常，验脉〔处〕方，亦前人之〔法〕也。厥后通乎理者，〔当〕以余言为〔然〕。", "19413": "如仲景治表虚，制桂枝汤方，桂枝味辛热，发散、助阳、体轻，本乎天者亲上，故桂枝为君，芍药、甘草佐之。〔如〕阳脉涩，阴脉弦，法当腹中急痛，制小建中〔汤〕方，芍药为君，桂枝、甘草佐之。一则治其表虚，一则治其里虚，是各言其主用也。后人之用古方者，触类而长之，则知其本，而不致差误矣。", "19414": "凡根〔之〕在上者，中半以上，气脉上行，以生苗者为根。中半以下，气脉下行，入土者为梢。当知病在中焦用身，上焦用根，下焦用梢。经曰：根升梢降。", "19415": "荆芥气温，味辛苦，辟邪毒，利血脉，宣通五脏不足〔气〕。《主治秘〔要〕》云：能发汗，通关节，除劳〔渴〕，冷捣和醋封毒肿，去枝茎以手搓碎用。", "19416": "干姜气热，味大辛，治沉寒痼冷，肾中无阳，脉气欲绝，黑附子为引，用水同煎二物，姜附汤是也。〔亦〕治中焦有寒。《主治秘要》云：性热味辛，气味俱厚，半沉半浮，可升可降，阳中阴也。其用有四：通心气助阳一也。去脏腑沉寒二也。发〔散〕诸经之寒气三也。〔治〕感寒腹疼四也。又云：辛温纯阳，《内经》云：寒淫所胜，以辛散之，此之谓也。水洗，慢火炙制，锉用。", "19417": "黄耆气温，味甘平，治虚劳自〔汗〕，补肺气，实皮毛，泻肺中火，脉弦、自汗。善治脾胃虚弱，疮疡血脉不行，内托阴证，疮疡必用之药也。《主治秘要》云：气温味甘，气薄味厚，可升可降，阴中阳也。其用有五：补诸虚不足一也。益元气二也。去肌热三也。疮疡排脓止痛四也。壮脾胃五也。又云：甘，纯阳，益胃气，去诸经之痛。去芦并皱，锉用。", "19418": "京三棱气平味苦，主心膈痛，饮食不消，破气，〔治〕老癖症瘕结块，妇人血脉不调，心腹刺痛。《主治秘〔要〕》云：〔味〕苦，阴中之阳，破〔积〕气，损真气，虚人不用。火炮制〔使〕。", "19419": "阿胶气微温，味甘平，主心腹疼痛，〔血〕崩，补虚安胎，坚筋骨，和血脉，益气止痢。《主治秘〔要〕》云：性平味淡，气味俱薄，浮而升，〔阳也〕，〔能〕补肺〔气〕不足。慢火炮〔脆〕搓细用。", "19420": "白芍药气微寒，味酸，补中焦之药，炙甘草为辅，治腹中痛；如夏月腹痛，少加黄芩；若恶寒腹痛，加肉桂一分，白芍药二分，炙甘草一分半，此仲景神品药也。如冬月大寒腹痛，加桂一〔钱〕半，水二盏，煎至一盏〔服〕。《主治秘〔要〕》云：性寒味酸，气厚味薄，升而微降，阳中阴也。其用有六：安脾经一也。治腹痛二也。收胃气三也。止泻利四也。和血〔脉〕五也。固腠理六也。又云：酸苦，阴中之阳，白补赤散，泻肝补脾胃，酒浸引经，止中部腹痛。去皮用。", "19421": "麦门冬气寒，味微苦甘，治肺中〔伏〕火，〔脉〕气欲绝。加五味子、人参〔二〕味，为生脉散，补肺中元气不足，须用之。《主治秘〔要〕》云：甘，阳中微阴，引经酒浸，治经枯、乳汁不下。汤洗，去心用。", "19422": "治劳瘵羸弱已甚，饮食减少，喘促咳嗽，身热脉虚数者。亦治女子血枯不月。", "19423": "或问曰：《内经》谓脾主思，西人又谓思想发于脑部，子则谓思发于心者何也？答曰：《内经》所谓脾主思者，非谓脾自能思也。盖脾属土，土主安静，人安静而后能深思，至西人谓思发于脑部，《内经》早寓其理。脉要精微论曰：「头者精明之府。」夫头之中心点在脑，头为精明之府，即脑为精明之府矣。既曰精明，岂有不能思之理，然亦非脑之自能思也。试观古文「思」字作「恖」，囟者脑也，心者心也，是知思也者，原心脑相辅而成，又须助以脾土镇静之力也。", "19424": "一九一三年，客居大名。治一室女，劳瘵年余，月信不见，羸弱不起。询方于愚，为拟此汤。连服数剂，饮食增多。身犹发热，加生地黄五钱，五六剂后热退，渐能起床，而腿疼不能行动。又加丹参、当归各三钱，服至十剂腿愈，月信亦见。又言有白带甚剧，向忘言及。遂去丹参加生牡蛎六钱，又将于术加倍，连服十剂带证亦愈。遂将此方邮寄家中，月余门人高××来函云：「赵××病劳瘵数年不愈，经医不知凡几，服药皆无效。今春骤然咳嗽，喘促异常，饮食减少，脉甚虚数，投以资生汤十剂全愈。」审斯则知此方治劳瘵，无论男女，服之皆有捷效也。", "19425": "津埠宋氏妇，年将四旬，身体羸弱，前二年即咳嗽吐痰，因不以为事未尝调治。今春证浸加剧，屡次服药无效。诊其脉，左部弦细，右部微弱，数近六至。咳嗽，吐痰白色，气腥臭，喘促自汗，午后发热，夜间尤甚，胸膈满闷，饮食减少，大便秘结，知其已成痨瘵而兼肺病也。从前所服药十余纸，但以止嗽药治其肺病，而不知子虚补母之义，所以无效。为疏方用资生汤加减，生山药八钱，玄参、大生地、净萸肉各六钱，生牡蛎、生杭芍、生赭石各四钱，于术、生鸡内金、甘草各二钱。煎服二剂，汗止喘轻，发热咳嗽稍愈。遂将前方去牡蛎，加蒌仁、地骨皮各三钱，山药改用一两，赭石改用六钱。连服十剂，诸病皆愈，为善后计，用生山药细末八钱煮粥，调白糖服之，早晚各一次。后月余。与介绍人晤面，言此时宋氏妇饮食甚多，身体较前健壮多矣。又：族嫂年三十五岁，初患风寒咳嗽，因懒于服药，不以为事。后渐至病重，始延医诊治。所服之药，皆温散燥烈之品，不知风寒久而化热，故越治越剧，几至不起。后生于腊底回里，族兄邀为诊视。脉象虚而无力，身瘦如柴，咳嗽微喘，饮食减少，大便泄泻，或兼白带，午后身热，颧红，确系痨瘵已成。授以资生汤，加炒薏仁、茯苓片、生龙骨、生牡蛎各三钱，茵陈、炙甘草各钱半。服二剂，身热、颧红皆退，咳嗽泄泻亦见愈。后仍按此方加减，又服六剂，诸病皆痊。嘱其每日用生怀山药细末煮粥，调以白糖服之，以善其后。四川泾南周××来函：杨姓女，年十九岁。出嫁二载，月事犹未见，身体羸瘦，饮食减少，干咳无痰，五心烦热，诊其脉细数有力。仿用资生汤方，用生山药一两，于术二钱，牛蒡子三钱，玄参五钱，生地黄四钱，生鸡内金一钱。连服五剂，热退咳减，食欲增加。遂于原方中去生地，倍于术。又服三剂，泛潮忽至。共服二十剂全愈。奉天法库县万××来函：族弟妇产后虚羸少食，迁延月余，渐至发灼、自汗、消瘦、乏气、干呕、头晕等证，此方书所谓蓐劳也。经医四人治不效，并添颧红作泻。适生自安东归，为之诊视，六脉虚数。检阅所服之方，有遵《医宗金鉴》三合饮者，有守用养荣汤者，要皆平淡无奇。然病势至此，诚难入手，幸脉虽虚数，未至无神，颧虽红，犹不抟聚（若抟聚则阴阳离矣，不抟聚是其阴阳犹未离），似尚可治。此盖素即阴虚，又经产后亡血，气亦随之，阴不中守，阳不外固，故汗出气乏；其阴阳不相维系，阴愈亏而阳愈浮，故发烧咳嗽头晕；其颧红者，因其部位应肾，肾中真阳上浮，故发现于此，而红且热也；其消瘦作泻者，以二阳不纳，无以充肌肉，更不特肾阴虚，而脾阴胃液均虚，中权失司，下陷不固，所必然者。此是病之原委欤？再四思维，遂处方，用生怀山药二两，于术三钱，玄参四钱，鸡内金、牛蒡子各二钱（此系资生汤原方稍加重），外加净萸肉、龙骨、牡蛎各五钱，止汗并以止泻。五剂后，汗与泻均止，饮食稍进，惟干咳与发热仅去十之二三。又照原方加粉甘草、天冬、生地等味，连服七剂。再照方减萸肉，加党参二钱，服四剂后，饮食大进，并能起坐矣，惟经尚未行。更按资生汤原方，加当归四钱。服数剂后，又复少有加减，一月经脉亦通。", "19426": "治虚劳，脉弦、数、细、微，肌肤甲错，形体羸瘦，饮食不壮筋力，或自汗，或咳逆，或喘促，或寒热不时，或多梦纷纭，精气不固。", "19427": "气分虚甚者，去三棱、莪术，加生鸡内金三钱；喘者，倍山药，加牛蒡子三钱；汗多者，以白术易黄耆，倍龙骨、牡蛎，加山萸肉、生白芍各六钱。若其汗过多，服药仍不止者，可但用龙骨、牡蛎、萸肉各一两煎服，不过两剂其汗即止。汗止后再服原方。若先冷后热而汗出者，其脉或更兼微弱不起，多系胸中大气下陷，细阅拙拟升陷汤后跋语，自知治法。仲景治劳瘵，有大黄䗪虫丸，有百劳丸，皆多用破血之药。诚以人身经络，皆有血融贯其间，内通脏腑，外溉周身，血一停滞，气化即不能健运，劳瘵恒因之而成。是故劳瘵者肌肤甲错，血不华色，即日食珍馐服参苓，而分毫不能长肌肉、壮筋力。或转消瘦支离，日甚一日，诚以血瘀经络阻塞其气化也。玉田王清任著《医林改错》一书，立活血逐瘀诸汤，按上中下部位，分消瘀血，统治百病，谓瘀血去而诸病自愈。其立言不无偏处，然其大旨则确有主见，是以用其方者，亦多效验。今愚因治劳瘵，故拟十全育真汤，于补药剂中，加三棱，莪术以通活气血，窃师仲景之大黄䗪虫丸、百劳丸之意也。且仲景于《金匮》列虚劳一门，特以血痹虚劳四字标为提纲。益知虚劳者必血痹，而血痹之甚，又未有不虚劳者。并知治虚劳必先治血痹，治血痹亦即所以治虚劳也。", "19428": "或问：劳瘵之证，阴虚发热者居其强半。故钱仲阳之减味地黄丸；张景岳之左归饮，皆为对证良方，以其皆以熟地黄为君，大能滋真阴退虚热也。子方中何以独不用也？答曰：若论用熟地，我固过来人也。忆初读方书时，曾阅赵氏《医贯》、《张氏八阵》、《冯氏锦囊》诸书，遂确信其说。临证最喜用熟地，曾以八味地黄丸作汤，加苏子、白芍，治吸不归根之喘逆；加陈皮、白芍，治下虚上盛之痰涎；加苏子、厚朴，治肾不摄气，以致冲气上逆之胀满（时病人服之觉有推荡之力，后制参赭镇气汤治此证更效，又尝减茯苓、泽泻三分之二，治女子消渴小便频数（《金匮》谓治男子消渴以治女子亦效，案详玉液汤下），又尝去附子，加知母、白芍，治阴虚不能化阳，致小便不利积成水肿；又尝用六味地黄丸作汤，加川芎、知母，以治如破之头疼；加胆草、青黛，以治非常之眩晕；加五味、枸杞、柏子仁，以敛散大之瞳子，且信其煎汁数碗，浩荡饮之之说；用熟地四两、茯苓一两，以止下焦不固之滑泻；用熟地四两、白芍一两，以通阴虚不利之小便；又尝于一日之中用熟地斤许，治外感大病之后，忽然喘逆，脉散乱欲脱之险证（此证当用后来复汤，彼时其方未拟出，惟知用熟地亦幸成功，是知冯楚瞻谓熟地能大补肾中元气诚有所试也），且不独治内伤也；又尝用熟地、阿胶大滋真阴之类，治温病脉阳浮而阴不应，不能作汗，一日连服二剂，济阴以应其阳，使之自汗（详案在寒解汤下）；并一切伤寒外感，因下元虚惫而邪深陷者，莫不重用熟地，补其下元，即以托邪外出。惟用以治阴虚劳热之证，轻者可效，若脉数至七八至鲜有效者。彼时犹不知改图，且以为地黄丸，即《金匮》之肾气丸，自古推为良方，此而不效，则他方更无论矣，不知肾气丸原用干地黄，即药坊间之生地也，其桂用桂枝，即《神农本草经》之牡桂也，与今之地黄丸迥不侔矣。其方《金匮》凡五见，一治「脚气上入少腹不仁」；一治「虚劳腰痛，少腹拘急，小便不利」；一治「短气有微饮，当从小便去之」；一治「男子消渴，小便反多，饮一斗，小便一斗」；一治「妇人转胞，胞系了戾，不得溺」。统观五条，原治少腹膀胱之疾居多，非正治劳瘵之药，况后世之修制，又失其本然乎。", "19429": "后治一妇人，年近五旬。身热劳嗽，脉数几至八至。先用六味地黄丸加减作汤服不效，继用左归饮加减亦不效。愚忽有会悟，改用生黄耆六钱、知母八钱为方，数剂见轻，又加丹参、当归各三钱，连服十剂全愈。以后凡遇阴虚有热之证，其稍有根柢可挽回者，于方中重用黄耆、知母，莫不随手奏效。始知叔和脉法谓数至七八至为不治之脉者，非确论也。盖人禀天地之气以生，人身之气化即天地之气化，天地将雨之时，必阳气温暖上升，而后阴云会合大雨随之。黄耆温升补气，乃将雨时上升之阳气也；知母寒润滋阴，乃将雨时四合之阴云也。二药并用，大具阳升阴应云行雨施之妙。膏泽优渥烦热自退，此不治之治也。况劳瘵者多损肾，黄耆能大补肺气，以益肾水之源，使气旺自能生水，而知母又大能滋肺中津液，俾阴阳不至偏胜，即肺脏调和，而生水之功益普也（黄耆、知母虽可并用以退虚热，然遇阴虚热甚者，又必须加生地黄八钱或至一两，方能服之有效）。", "19430": "或又问：肾气丸虽非专治虚劳之药，而《金匮》虚劳门，明载其治虚劳腰疼，似虚者皆可服之，子独谓无甚效验，岂古方不可遵欤？答曰：肾气丸若果按古方修制，地黄用干地黄，桂用桂枝，且止为丸剂，而不作汤剂，用之得当，诚有效验。盖生地能逐血痹（《神农本草经》），而熟地无斯效也。桂枝能调营卫，而肉桂无斯效也。血痹逐，则瘀血自消，营卫调，则气血自理。至于山萸肉之酸温，亦能逐痹（《神龙本草经》山茱萸逐寒湿痹）。牡丹皮之辛凉，亦能破血。附子之大辛大温，又能温通血脉，与地黄之寒凉相济，以共成逐血痹之功。是肾气丸为补肾之药，实兼为开瘀血之药，故列于《金匮》虚劳门，而为要方也。其止为丸剂，而不作汤剂者，诚以地黄经水火煎熬，则汁浆稠黏、性近熟地，其逐血痹之力必减，是以《神农本草经》，谓地黄生者尤良也。后贤徐灵胎曾治一人，上盛下虚，胸次痰火壅滞，喘不能卧，将人参切作小块，用清水理痰之药煎汤，送服而愈。后其病复发，病家自用原方，并人参亦煎服，病益甚，灵胎仍教以依从前服法，其病仍愈。夫同一人参也，生切块送服则效，煎汤则不惟不效，转至增剧，触类引伸，可以悟古人制肾气丸之精义矣。", "19431": "世俗医者，遇脉数之证，大抵责之阴虚血涸。不知元气虚极莫支者，其脉可至极数。设有人或力作，或奔驰，至气力不能支持之时，其脉必数。乃以力倦之不能支持，以仿气虚之不能支持，其事不同而其理同也。愚临证细心体验，凡治虚劳之证，固不敢纯用补药，然理气药多于补气药，则脉即加数，补气药多于理气药，则脉即渐缓。是知脉之数与不数，固视乎血分之盈亏，实尤兼视乎气分之强弱。故此十全育真汤中，台参、黄耆各四钱，而三棱、莪术各钱半，补气之药原数倍于理气之药。若遇气分虚甚者，犹必以鸡内金易三棱、莪术也。", "19432": "弟长男媳，年二十四岁，于本年（丙寅）正月间患寒热往来，自因素畏服药，故隐忍不肯言。至四月初，家人来迓弟，言儿媳病剧。回家视之，虽未卧床不起。而瘦弱实难堪矣。诊其脉，弦而浮数。细询病情，言每逢午后先寒后热，时而微咳无痰，日夜作泻十余次，黎明则头汗出，胸间绵绵作疼，食一下咽即胀满难堪，而诸虚百损之状，显然尽露。筹思良久，为立逍遥散方。服两剂无效。因复至沧取药，适逢张××自津来沧，遂将儿媳之病细述本末。张××曰：「以弟之意，将用何方以治之？」答曰：「余拟将资生汤、十全育真汤二方，汇通用之，可乎？」张××曰：「得之矣。此良方也，服之必效。」弟遂师二方之义，用生怀山药八钱，生白术、净萸肉、生鸡内金、生龙骨、生牡蛎、鲜石斛各三钱，丹参四钱。连服四剂，诸证皆大轻减。又于原方加三棱、莪术（十全育真汤中用此二药者，因虚劳之证多血痹也。）各一钱，粉丹皮、地骨皮各二钱。又连服八剂，诸病悉退，饮食增加，今已完全成功矣。", "19433": "治虚劳发热，或喘或嗽，脉数而弱。", "19434": "劳热之证，大抵责之阴虚。有肺阴虚者，其人因肺中虚热熏蒸，时时痒而作嗽，甚或肺中有所损伤，略一动作，辄发喘促，宜滋补肺阴，兼清火理痰之品，有肾阴虚者，其人因肾虚不能纳气，时时咳逆上气，甚或喘促，宜填补下焦真阴。兼用收降之品。若其脉甚数者，陈修园谓，宜滋养脾阴。盖以脾脉原主和缓，脉数者必是脾阴受伤，宜于滋阴药中，用甘草以引之归脾，更兼用味淡之药，如薏米、石斛之类。特是人身之阴，所盖甚广，凡周身之湿处皆是也。故阴虚之甚者，其周身血脉津液，皆就枯涸。必用汁浆最多之药，滋脏腑之阴，即以溉周身之液，若方中之山药、地黄是也。然脉之数者，固系阴虚，亦系气分虚弱，有不能支持之象，犹人之任重而体颤也。故用人参以补助气分，与玄参、天冬之凉润者并用，又能补助阴分。且虑其升补之性，与咳嗽上逆者不宜，故又佐以赭石之压力最胜者，可使人参补益之力下行直至涌泉，而上焦之逆气浮火，皆随之顺流而下；更可使下焦真元之气，得人参之峻补而顿旺，自能吸引上焦之逆气浮火下行也。至于牛蒡子与山药并用，最善止嗽，甘草与天冬并用，最善润肺，此又屡试屡效者也。", "19435": "初制此方时，原无赭石，有丹参三钱，以运化人参之补力。后治一年少妇人，信水数月不行，时作寒热，干嗽连连，且兼喘逆，胸隔满闷，不思饮食，脉数几至七至。治以有丹参原方不效，遂以赭石易丹参，一剂咳与喘皆愈强半，胸次开通，即能饮食，又服数剂脉亦和缓，共服二十剂，诸病皆愈。以后凡治妇女月闭血枯，浸至虚劳，或兼咳嗽满闷者，皆先投以此汤，俾其饮食加多，身体强壮，经水自通。间有瘀血暗阻经道，或显有症瘕可据者，继服拙拟理冲汤，或理冲丸以消融之，则妇女无难治之病矣。若其人胸中素觉短气，或大便易滑泻者，又当预防其大气下陷（大气下陷详升陷汤）。用醴泉饮时，宜减赭石、牛蒡子，并一切苏子、蒌仁、紫菀、杏仁，治咳喘套药皆不宜用。", "19436": "又按：方书名咳喘曰「咳逆」，喘曰「喘逆」，因二证多由逆气上干也。而愚临证实验以来，知因大气下陷而咳喘者，亦复不少。盖肺悬胸中，必赖大气以包举之，而后有所附丽；大气以鼓舞之，而后安然呼吸。大气一陷，则包举之力微，肺即无所附丽，而咳嗽易生。鼓舞之机滞，肺必努力呼吸，而喘促易作。曾治一少年，泄泻半载方愈。后因劳力过度，觉喉中之气不舒，五六呼吸之间，必咳嗽一两声，而其气始舒。且觉四肢无力，饮食懒进。诊其脉微弱异常，知其胸中大气下陷，投以拙拟升陷汤，数剂而愈。", "19437": "又：曾治一人，年近五旬，素有喘疾。因努力任重，旧证复发。延医服药罔效。后愚诊视其脉，数近六至，而兼有沉濡之象。愚疑其阴虚不能纳气，因其脉兼沉濡，不敢用降气之药。遂用熟地、生山药、枸杞、玄参大滋真阴之药，大剂煎汤，送下人参小块二钱，连服三剂脉即不数，仍然沉濡，喘虽见轻，仍不能愈。因思此证得之努力任重，胸中大气因努力而陷，所以脉现沉濡，且其背恶寒而兼发紧，此亦大气下陷之征也。亦治以升陷汤，方中升麻、柴胡、桔梗皆不敢用，以桂枝尖三钱代之。因其素有不纳气之证，桂枝能升大气，又能纳气归肾也（理详参赭镇气汤下）。又外加滋阴之药，数剂全愈（详案在升陷汤下）。按此二证之病因，与醴泉饮所主之病迥异，而其咳喘则同。必详观升陷汤后跋语，及所载诸案，始明治此二证之理。而附载于此者，恐临证者审证不确，误以醴泉饮治之也。", "19438": "沈阳娄××，年二十二，虚劳咳嗽，其形羸弱，脉数八至，按之即无。细询之，自言曾眠热炕之上，晨起觉心中发热，从此食后即吐出，夜间咳嗽甚剧，不能安寝。因二十余日寝食俱废，遂觉精神恍惚，不能支持。愚闻之，知脉象虽危，仍系新证，若久病至此，诚难挽回矣。遂投以醴泉饮，为其呕吐，将赭石改用一两（重用赭石之理详参赭镇气汤下），一剂吐即止，可以进食，嗽亦见愈。从前五六日未大便，至此大便亦通下。如此加减服之，三日后脉数亦见愈。然犹六至余，心中犹觉发热，遂将玄参、生地皆改用六钱，又每日于午时，用白蔗糖冲水，送服西药阿斯匹林（药性详参麦汤下）七厘许。数日诸病皆愈，脉亦复常。", "19439": "沈阳苏××，年三十许，劳嗽二年不愈，动则作喘，饮食减少。更医十余人，服药数百剂，分毫无效，羸弱转甚。来院诊治。其脉数六至，虽细弱仍有根柢，知其可治。自言上焦恒觉发热，大便三四日一行，时或干燥。遂投以醴泉饮，为其便迟而燥，赭石改用六钱，又加鸡内金二钱（捣细），恐其病久脏腑经络多瘀滞也。数剂后饭量加增，心中仍有热时，大便已不燥，间日一行。遂去赭石二钱，加知母二钱，俾于晚间服汤药后，用白蔗糖水，送服阿斯匹林四分之一瓦，得微汗。后令于日间服之，不使出汗，数日不觉发热，脉亦复常，惟咳嗽未能全愈。又用西药几阿苏六分，薄荷冰四分，和以绿豆粉为丸，梧桐子大，每服三丸，日两次，汤药仍照方服之，五六日后咳嗽亦愈，身体从此康健。", "19440": "陈修园谓：山药为寻常服食之物，不能治大病，非也。若果不治大病，何以《金匮》治劳瘵有薯蓣丸。尝治一室女，温病痰喘，投以小青龙加石膏汤，又遵《伤寒论》加减法，去麻黄加杏仁，喘遂定。时已近暮，一夜安稳。至黎明喘大作，脉散乱如水上浮麻，不分至数，此将脱之候也。取药不及，适有生山药两许，急煮汁饮之，喘稍定，脉稍敛，可容取药，方中仍重用山药而愈（详案在仙露汤下）。", "19441": "一妇人，产后十余日，大喘大汗，身热劳嗽。医者用黄耆、熟地、白芍等药，汗出愈多。后愚诊视，脉甚虚弱，数至七至，审证论脉，似在不治。俾其急用生山药六两，煮汁徐徐饮之，饮完添水重煮，一昼夜所饮之水，皆取于山药中。翌日又换山药六两，仍如此煮饮之。三日后诸病皆愈。", "19442": "一人，年四十余，得温病十余日，外感之火已消十之八九。大便忽然滑下，喘息迫促，且有烦渴之意。其脉甚虚，两尺微按即无。亦急用生山药六两，煎汁两大碗，徐徐温饮下，以之当茶，饮完煎渣再饮，两日共用山药十八两，喘与烦渴皆愈，大便亦不滑泻。", "19443": "愚对于此证，悉心研究，知其治法，当细分为数种。肾传肺者，以大滋真阴之药为主，以清肺理痰之药为佐，若拙拟之醴泉饮是也；肺传肾者，以清肺理痰之药为主，以滋补真阴之药为佐，若此参麦汤是也；其因肺肾俱病，而累及脾胃者，宜肺肾双补，而兼顾其脾胃，若拙拟之滋培汤、珠玉二宝粥是也。如此分途施治，斟酌咸宜，而又兼服阿斯匹林，凡其脉之稍有根柢可挽回者，需以时日皆愈也。至于但肺有结核，而未累及他脏者，可于斯编治肺病方中，酌其治法（论肺病治法，实合虚劳肺病详细论之也，凡治虚劳及肺病者皆宜参观）", "19444": "凡劳瘵阴虚之证，其脉之急数者，无论肺结核与不结核，于每服滋补剂外，皆宜服阿斯匹林，或半瓦，或至一瓦。恐其出汗多，分几次服下，其初日服之俾微见汗，后日日常服，以或出汗或不出汗为适宜。如此旬日之间，脉之数者可渐和缓。", "19445": "一少年，因感冒懒于饮食，犹勤稼穑，枵腹力作，遂成劳嗽。过午发热，彻夜咳吐痰涎。医者因其年少，多用滋阴补肾之药，间有少加参、耆者。调治两月不效，饮食减少，痰涎转增，渐至不起，脉虚数兼有弦象，知其肺脾皆有伤损也。授以此方，俾一日两次服之，半月全愈。", "19446": "或问：脉现弦象，何以即知其脾肺伤损？答曰：脉虽分部位，而其大致实不分部位，今此证左右之脉皆弦，夫弦为肝脉，肝盛必然侮脾，因肝属木脾属土也。且五行之中，惟土可以包括四行，即脾气可以包括四脏。故六部脉中，皆以和缓为贵，以其饶有脾土之气也。今其脉不和缓而弦硬，其脾气受伤，不能包括四脏可知。又肺属金，所以镇肝木者也，故肺金清肃之气下行，肝木必不至恣横，即脉象不至于弦。今其脉既现如此弦象，则肺金受伤，不能镇肝木更可知也。", "19447": "一人，年四十余，素有喘证，薄受外感即发。医者投以小青龙汤，一剂即愈，习以为常。一日喘证复发，连服小青龙汤三剂不愈。其脉五至余，右寸浮大，重按即无。知其从前服小青龙即愈者，因其证原受外感；今服之而不愈者，因此次发喘原无外感也，盖其薄受外感即喘；肺与肾原有伤损，但知治其病标，不知治其病本，则其伤损必益甚，是以此次不受外感亦发喘也。为拟此汤服两剂全愈，又服数剂以善其后。", "19448": "一人，年二十余，禀资素羸弱，又耽烟色，于秋初患疟，两旬始愈。一日大便滑泻数次，头面汗出如洗，精神颓愦，昏昏似睡。其脉上盛下虚，两寸摇摇，两尺欲无，数至七至。延医二人皆不疏方。愚后至为拟此汤，一剂而醒，又服两剂遂复初。", "19449": "一人，年二十余，于孟冬得伤寒证，调治十余日，表里皆解。忽遍身发热，顿饭顷，汗出淋漓，热顿解，须臾又热又汗。若是两昼夜，势近垂危，仓猝迎愚诊治。及至，见汗出浑身如洗，目上窜不露黑睛，左脉微细模糊，按之即无，此肝胆虚极，而元气欲脱也，盖肝胆虚者，其病象为寒热往来，此证之忽热忽汗，亦即寒热往来之意。急用净萸肉二两煎服，热与汗均愈其半，遂为拟此方，服两剂而病若失。", "19450": "赵叟，年六十三岁，于仲冬得伤寒证，痰喘甚剧。其脉浮而弱，不任循按，问其平素，言有劳病，冬日恒发喘嗽。再三筹思，强治以小青龙汤去麻黄，加杏仁、生石膏，为其脉弱，俾预购补药数种备用。服药后喘稍愈，再诊其脉微弱益甚，遂急用净萸肉一两，生龙骨、生牡蛎各六钱，野台参四钱，生杭芍三钱为方，皆所素购也。煎汤甫成，此时病人呼吸俱微，自觉气息不续，急将药饮下，气息遂能接续。", "19451": "李××，年五旬，偶相值，求为诊脉，言前月有病服药已愈，近觉身体清爽，未知脉象何如？诊之，其脉尺部无根，寸部摇摇有将脱之势，因其自谓病愈，若遽悚以危语，彼必不信，姑以脉象平和答之。遂秘谓其侄曰：「令叔之脉甚危险，当服补敛之药，以防元气之暴脱。」其侄向彼述之，果不相信后二日，忽遣人迎愚，言其骤然眩晕不起，求为诊治。既至，见其周身颤动，头上汗出，言语错乱，自言心怔忡不能支持，其脉上盛下虚之象较前益甚，急投以净萸肉两半，生龙骨、生牡蛎、野台参、生赭石各五钱，一剂即愈。继将萸肉改用一两，加生山药八钱，连服数剂，脉亦复常。按：此方赭石之分量，宜稍重于台参。", "19452": "张港朱××之儿媳，产后角弓反张，汗出如珠，六脉散乱无根，有将脱之象，迎为诊治。急用净萸肉二两，俾煎汤服之，一剂即愈。", "19453": "治胸膈满闷，其脉大而弦，按之似有力，非真有力，此脾胃真气外泄，冲脉逆气上干之证，慎勿作实证治之。若用开通之药，凶危立见。服此汤数剂后脉见柔和，即病有转机，多服自愈。", "19454": "脉之真有力者，皆有洪滑之象。洪者如波涛叠涌，势作起伏；滑者指下滑润，累累如贯珠。此脉象弦直，既无起伏之势，又无贯珠之形，虽大而有力，实非真有力之象。", "19455": "和缓者脾胃之正脉，弦长者肝胆之正脉。然脾胃属土，其脉象原宜包括金、木、水、火诸脏腑，故六部之脉皆有和缓，乃为正象。今其脉弦而有力，乃肝木横恣，侵侮脾土之象，故知其脾胃虚也。", "19456": "冲脉上隶阳明，故冲气与胃气原相贯通。今因胃气虚而不降，冲气即易于上干。此时脾胃气化不固，既有外越之势，冲气复上干而排挤之，而其势愈外越，故其脉又兼大也。", "19457": "一媪，年过六旬，胸腹满闷，时觉有气自下上冲，饮食不能下行。其子为书贾，且知医。曾因卖书至愚书校，述其母病证，且言脉象大而弦硬。为拟此汤，服一剂满闷即减，又服数剂全愈。", "19458": "一人，年近五旬，心中常常满闷，呕吐痰水。时觉有气起自下焦，上冲胃口。其脉弦硬而长，右部尤甚，此冲气上冲，并迫胃气上逆也。问其大便，言甚干燥。遂将方中赭石改作一两，又加知母、生牡蛎各五钱，厚朴、苏子各钱半，连服六剂全愈。", "19459": "天津王媪，得病月余，困顿已极，求治于弟。诊其脉，六部皆弦硬有力，更粗大异常，询其病，则胸膈满闷，食已即吐，月余以来，未得一饭不吐，且每日大便两三次，所便少许有如鸡矢，自云心中之难受，莫可言喻，不如即早与世长辞，脱此苦恼。细思胸膈满闷，颇似实证者；，然而脉象弦硬粗大，无一点柔和之象，遂忆镇摄汤下注云，治胸膈满闷，其脉大而弦，按之有力，此脾胃真气外泄，冲脉逆气上干之证，慎勿以实证治之云云。即抄镇摄汤原方予之。服一剂，吐即见减，大便次数亦见减，脉遂有柔和之象。四五剂，即诸病全愈。以后遇此等脉象，即按此汤加减治之，无不效如桴鼓。", "19460": "人身之热力，方书恒责重相火，而不知君火之热力，较相火尤胜。盖生育子女以相火为主，消化饮食以君火为主。君火发于心中，为阳中之火，其热下济，大能温暖脾胃，助其消化之力，此火一衰，脾胃消化之力顿减。若君火旺而相火衰者，其人仍能多饮多食可享大寿，是知君火之热力，关于人身者甚大也。愚自临证实验以来，遇君火虚者不胜计，其人多廉于饮食，寒饮留滞为恙，投以辛热升补之剂，即随手奏效（拙拟理饮汤为治是病的方）。彼谓心脏恶热，用药惟宜寒凉者，犹是一偏之论。曾治一人，年二十余，嗜睡无节，即动作饮食之时，亦忽然昏倒鼾睡。诊其脉两尺洪滑有力，知其肾经实而且热也。遂用黄柏、知母各八钱，茯苓、泽泻各四钱，数剂而愈。是知人之资禀不齐：心脏多恶热，而亦有宜温补者；肾脏多恶寒，而亦有宜凉泻者。是在临证时细心与之消息，不可拘于成见也。", "19461": "一叟年近六旬，得水肿证。小便不利，周身皆肿，其脉甚沉细，自言素有疝气，下焦常觉寒凉。愚曰：欲去下焦之寒，非服硫黄不可。且其性善利水，施之火不胜水而成水肿者尤为对证。为开苓桂术甘汤加野台参三钱、威灵仙一钱，一日煎渣再服，皆送服生硫黄末二分。十日后，小便大利，肿消三分之二。下焦仍觉寒凉，遂停汤药单服硫黄试验，渐渐加多，一月共服生硫黄四两，周身肿尽消，下焦亦觉温暖。", "19462": "一人年十八九，常常呕吐涎沫，甚则吐食。诊其脉象甚迟濡，投以大热之剂毫不觉热，久服亦无效验。俾嚼服生硫黄如黄豆粒大，徐徐加多，以服后移时觉微温为度。后一日两次服，每服至二钱，始觉温暖。共服生硫黄四斤，病始除根。", "19463": "一叟年六十有一，频频咳吐痰涎，兼发喘逆。人皆以为劳疾，未有治法。诊其脉甚迟，不足三至，知其寒饮为恙也。投以拙拟理饮汤加人参、附子各四钱，喘与咳皆见轻而脉之迟仍旧。因思脉象如此，非草木之品所能挽回。俾服生硫黄少许，不觉温暖，则徐徐加多，两月之间，服生硫黄斤余，喘与咳皆愈，脉亦复常。", "19464": "一妇人年五旬，上焦阳分虚损，寒饮留滞作嗽，心中怔忡，饮食减少，两腿畏寒，卧床不起者已二年矣。医者见其咳嗽怔忡，犹认为阴分虚损，复用熟地、阿胶诸滞泥之品，服之病益剧。后愚诊视，脉甚弦细，不足四至，投以拙拟理饮汤加附子三钱，服七八日咳嗽见轻，饮食稍多而仍不觉热，知其数载沉疴，非程功半载不能愈也。俾每日于两餐之前服生硫黄三分，体验加多，后服数月，其病果愈。", "19465": "治胸中大气下陷，气短不足以息。或努力呼吸，有似乎喘。或气息将停，危在顷刻。其兼证，或寒热往来，或咽干作渴，或满闷怔忡，或神昏健忘，种种病状，诚难悉数。其脉象沉迟微弱，关前尤甚。其剧者，或六脉不全，或参伍不调。", "19466": "大气者，充满胸中，以司肺呼吸之气也。人之一身，自飞门以至魄门，一气主之。然此气有发生之处，有培养之处，有积贮之处。天一生水，肾脏先成，而肾系命门之中（包肾之膜油连于脊椎自下上数七节处）有气息息萌动，此乃乾元资始之气，《内经》所谓「少火生气」也。此气既由少火发生，以徐徐上达。培养于后天水谷之气，而磅礴之势成。绩贮于膺胸空旷之府，而盘据之根固。是大气者，原以元气为根本，以水谷之气为养料，以胸中之地为宅窟者也。夫均是气也，至胸中之气，独名为大气者，诚以其能撑持全身，为诸气之纲领，包举肺外，司呼吸之枢机，故郑而重之曰大气。夫大气者，内气也。呼吸之气，外气也。人觉有呼吸之外气与内气不相接续者，即大气虚而欲陷，不能紧紧包举肺外也。医者不知病因，犹误认为气郁不舒，而开通之。其剧者，呼吸将停，努力始能呼吸，犹误认为气逆作喘，而降下之。则陷者益陷，凶危立见矣。其时作寒热者，盖胸中大气，即上焦阳气，其下陷之时，非尽下陷也，亦非一陷而不升也。当其初陷之时，阳气郁而不畅则作寒，既陷之后，阳气蓄而欲宣则作热。迨阳气蓄极而通，仍复些些上达，则又微汗而热解。其咽干者，津液不能随气上潮也。其满闷者，因呼吸不利而自觉满闷也。其怔忡者，因心在膈上，原悬于大气之中，大气既陷，而心无所附丽也。其神昏健忘者，大气因下陷，不能上达于脑，而脑髓神经无所凭借也。其证多得之力小任重或枵腹力作，或病后气力未复，勤于动作，或因泄泻日久，或服破气药太过，或气分虚极自下陷，种种病因不同。而其脉象之微细迟弱，与胸中之短气，实与寒饮结胸相似。然诊其脉似寒凉，而询之果畏寒凉，且觉短气者，寒饮结胸也；诊其脉似寒凉，而询之不畏寒凉，惟觉短气者，大气下陷也。且即以短气论，而大气下陷之短气，与寒饮结胸之短气，亦自有辨。寒饮结胸短气，似觉有物压之；大气下陷短气，常觉上气与下气不相接续。临证者当细审之（寒饮结胸详理饮汤下）。", "19467": "至大气即宗气者，亦尝深考《内经》而得之。《素问》平人气象论曰：「胃之大络名虚里，出于左乳下，其动应衣，脉宗气也。」", "19468": "按：虚里之络，即胃输水谷之气于胸中，以养大气之道路。而其贯膈络肺之余，又出于左乳下为动脉。是此动脉，当为大气之余波，而曰宗气者，是宗气即大气，为其为生命之宗主，故又尊之曰宗气。其络所以名虚里者，因其贯膈络肺游行于胸中空虚之处也。", "19469": "又：《灵枢》客邪篇曰：「五谷入于胃，其糟粕、津液、宗气，分为三隧。故宗气积于胸中，出于喉咙，以贯心脉，而行呼吸焉。」观此节经文，则宗气即为大气，不待诠解。且与五味篇同为伯高之言，非言出两人，而或有异同。且细审「以贯心脉，而行呼吸」之语，是大气不但为诸气之纲领，并可为周身血脉之纲领矣。至大气下陷之说，《内经》虽无明文，而其理实亦寓于《内经》中。《灵枢》五色篇雷公问曰：「人无病卒死，何以知之？」黄帝曰：「大气入于脏腑者，不病而卒死。」夫人之膈上，心肺皆脏，无所谓腑也。经既统言脏腑，指膈下脏腑可知。以膈上之大气，入于膈下之脏腑，非下陷乎？大气既陷，无气包举肺外以鼓动其闟辟之机，则呼吸顿停，所以不病而猝死也。观乎此，则大气之关于人身者，何其重哉！", "19470": "有兄弟二人，其兄年近六旬，弟五十余。冬日畏寒，共处一小室中，炽其煤火，复严其户牖。至春初，二人皆觉胸中满闷，呼吸短气。盖因户牖不通外气，屋中氧气全被煤火著尽，胸中大气既乏氧气之助，又兼受炭气之伤，日久必然虚陷，所以呼吸短气也。因自觉满闷，医者不知病因，竟投以开破之药。迨开破益觉满闷，转以为药力未到，而益开破之。数剂之后，其兄因误治，竟至不起。其弟服药亦增剧，而犹可支持，遂延愚诊视。其脉微弱而迟，右部尤甚，自言心中发凉，少腹下坠作疼，呼吸甚觉努力。知其胸中大气下陷已剧，遂投以升陷汤，升麻改用二钱，去知母，加干姜三钱。两剂，少腹即不下坠，呼吸亦顺。将方中升麻、柴胡、桔梗皆改用一钱，连服数剂而愈。", "19471": "一人，年四十八。素有喘病，薄受外感即发，每岁反复两三次，医者投以小青龙加石膏汤辄效。一日反复甚剧，大喘昼夜不止。医者投以从前方两剂，分毫无效。延愚诊视，其脉数至六至，兼有沉濡之象。疑其阴虚不能纳气，故气上逆而作喘也。因其脉兼沉濡，不敢用降气之品。遂用熟地黄、生山药、枸杞、玄参、大滋真阴之品，大剂煎汤，送服人参小块二钱。连服三剂，喘虽见轻，仍不能止。复诊视时，见令人为其椎背，言背常发紧，椎之则稍轻，呼吸亦稍舒畅。此时，其脉已不数，仍然沉濡。因细询，此次反复之由，言曾努力搬运重物，当时即觉气分不舒，迟两三日遂发喘。乃恍悟，此证因阴虚不能纳气，故难于吸。因用力太过，大气下陷，故难于呼。其呼吸皆须努力，故呼吸倍形迫促。但用纳气法治之，止治其病因之半，是以其喘亦止愈其半也。遂改用升陷汤，方中升麻、柴胡、桔梗，皆不敢用，以桂枝尖三钱代之。又将知母加倍，再加玄参四钱，连服数剂全愈。", "19472": "一人，年二十余。动则作喘，时或咳嗽。医治数年，病转增剧，皆以为劳疾不可治。其脉非微细，而指下若不觉其动。知其大气下陷，不能鼓脉外出，以成起伏之势也。投以升陷汤，加人参、天冬各三钱，连服数剂而愈。因其病久，俾于原方中减去升麻，为末炼蜜作丸药，徐服月余，以善其后。", "19473": "一人，年二十四。胸中满闷，昼夜咳嗽，其咳嗽时，胁下疼甚。诊其脉象和平，重按微弦无力。因其胁疼，又兼胸满，疑其气分不舒，少投以理气之药。为其脉稍弱，又以黄耆佐之，而咳嗽与满闷益甚，又兼言语声颤动。乃细问病因，知其素勤稼穑，因感冒懒食，犹枵腹力作，以致如此。据此病因，且又服理气之药不受，其为大气下陷无疑。遂投以升陷汤，四剂，其病脱然。", "19474": "一人，年四十许。失音半载，渐觉咽喉发紧，且常溃烂，畏风恶寒，冬日所著衣服，至孟夏犹未换。饮食减少，浸成虚劳，多方治疗，病转增剧。诊其脉，两寸微弱，毫无轩起之象，知其胸中大气下陷也。投以升陷汤，加玄参四钱，两剂，咽喉即不发紧。遂减去升麻，又连服十余剂，诸病皆愈。", "19475": "西丰县张××，年十八九，患病数年不愈，来院诊治。其证夜不能寐，饮食减少，四肢无力，常觉短气。其脉关前微弱不起。知系胸中大气下陷，故现种种诸证。投以升陷汤，为其不寐，加熟枣仁、龙眼肉各四钱，数剂全愈。", "19476": "奉天于氏女，出嫁而孀，依居娘门。因病还家中，夜忽不能言，并不能息。其同院住者王××，系愚门生，急来院扣门，求为援救。因素为诊脉调药，知其大气虚损，此次之证，确知其为大气下陷，遂为疏方，用生箭耆一两，当归四钱，升麻二钱，煎服，须臾即能言语。翌晨舁至院中，诊其脉沉迟微弱，其呼吸仍觉短气。遂将原方减升麻一钱，又加生山药、知母各三钱，柴胡、桔梗各一钱，连服数剂全愈。按此证，脉迟而仍用知母者，因大气下陷之脉大抵皆迟，非因寒凉而迟也，用知母以济黄耆之热，则药性和平，始能久服无弊。", "19477": "奉天袁姓少妇，小便处常若火炙，有时觉腹中之气下坠，则炙热益甚。诊其脉关前微弱，关后重按又似有力。其呼吸恒觉短气，心中时或发热。知其素有外感伏邪，久而化热，又因胸中大气下陷，伏邪亦随之下陷也。治以升陷汤加生石膏八钱，后渐加至二两，服药旬日全愈。", "19478": "答曰：此理不易骤解，仍宜以治愈之案证之。一人，年二十余。因力田劳苦过度，致胸中大气下陷，四肢懒动，饮食减少，自言胸中满闷，其实非满闷乃短气也，病人不善述病情，往往如此。医者不能自审病因，投以开胸理气之剂，服之增重。又改用半补半破之剂，服两剂后，病又增重。又延他医，投以桔梗、当归、木香各数钱，病大见愈，盖全赖桔梗升提气分之力也，医者不知病愈之由，再服时，竟将桔梗易为苏梗，升降易性，病骤反复。自此不敢服药。迟延二十余日，病势垂危，喘不能卧，昼夜倚壁而坐；假寐片时，气息即停，心下突然胀起，急呼醒之，连连喘息数口，气息始稍续；倦极偶卧片时，觉腹中重千斤，不能转侧，且不敢仰卧；其脉乍有乍无，寸关尺或一部独见，或两部同见，又皆一再动而止。此病之危，已至极点。因确知其为大气下陷，遂放胆投以生箭耆一两，柴胡、升麻、净萸肉各二钱。煎服片时，腹中大响一阵，有似昏愦，苏息片时，恍然醒悟。自此呼吸复常，可以安卧，转侧轻松。其六脉皆见，仍有雀啄之象。自言百病皆除，惟觉胸中烦热，遂将方中升麻、柴胡皆改用钱半，又加知母、玄参各六钱，服后脉遂复常。惟左关三五不调，知其气分之根柢犹未实也，遂用野台参一两，玄参、天冬、麦冬（带心）各三钱，两剂全愈。", "19479": "盖人之胸中大气，实司肺脏之呼吸。此证因大气下陷过甚，呼吸之机关将停，遂勉强鼓舞肺气，努力呼吸以自救，其迫促之形有似乎喘，而实与气逆之喘有天渊之分。观此证假寐片时，肺脏不能努力呼吸，气息即无，其病情可想也。设以治气逆作喘者治此证之喘，以治此证之喘者治气逆作喘，皆凶危立见。然欲辨此二证，原有确实征验：凡喘证，无论内伤外感，其剧者必然肩息（《内经》谓喘而肩上抬者为肩息）；大气下陷者，虽至呼吸有声，必不肩息。盖肩息者，因喘者之吸气难，不肩息者，因大气下陷者之呼气难也。欲辨此证，可作呼气难与吸气难之状，以默自体验，临证自无差谬。又喘者之脉多数，或有浮滑之象，或尺弱寸强，大气下陷之脉，皆与此成反比例，尤其明征。", "19480": "一人，年四十许。每岁吐血两三次，如此四年，似有一年甚于一年之势。其平素常常咳嗽，痰涎壅滞，动则作喘，且觉短气。其脉沉迟微弱，右部尤甚。知其病源系大气下陷，投以升陷汤，加龙骨、牡蛎（皆不用煅）、生地黄各六钱，又将方中知母改用五钱，连服三剂，诸病皆愈。遂减去升麻，又服数剂以善其后。", "19481": "一人，年四十余。小便不利，周身漫肿，自腰以下，其肿尤甚。上焦痰涎杜塞，剧时几不能息。咳嗽痰中带血，小便亦有血色。迁延半载，屡次延医服药，病转增剧。其脉滑而有力，疑是湿热壅滞，询之果心中发热。遂重用滑石、白芍以渗湿清热，佐以柴胡、乳香、没药以宣通气化。为其病久，不任疏通，每剂药加生山药两许，以固气滋阴。又用药汁，送服三七末二钱，以清其血分。数剂热退血减，痰涎亦少，而小便仍不利。偶于诊脉时，见其由卧起坐，因稍费力，连连喘息十余口，呼吸始顺。且其脉从前虽然滑实，究在沉分。此时因火退，滑实既减，且有濡象。恍悟此证确系大气下陷。遂投以升陷汤，知母改用六钱，又加玄参五钱，木通二钱，一剂小便即利。又服数剂，诸病全愈。", "19482": "一人，年四十七。咳嗽短气，大汗如洗，昼夜不止，心中怔忡，病势危急。遣人询方，俾先用山萸肉（去净核）二两煎服，以止其汗。翌日迎愚诊视，其脉微弱欲无，呼吸略似迫促。自言大汗虽止，而仍有出汗之时，怔忡见轻，仍觉短气。知其确系大气下陷，遂投以升陷汤，为其有汗，加龙骨、牡蛎（皆不用煅）各五钱，三剂而愈。", "19483": "一妇人，年二十余。资禀素羸弱，因院中失火，惊恐过甚，遂觉呼吸短气，心中怔忡，食后更觉气不上达，常作太息。其脉近和平，而右部较沉。知其胸中大气，因惊恐下陷，《内经》所谓恐则气陷也。遂投以升陷汤，为心中怔忡，加龙眼肉五钱，连服四剂而愈。", "19484": "一妇人，年二十余。因境多拂郁，常作恼怒，遂觉呼吸短气，咽干作渴，剧时，觉气息将停，努力始能呼吸。其脉左部如常，右部来缓去急，分毫不能鼓指。《内经》谓宗气贯心脉，宗气即大气也。此证盖因常常恼怒，致大气下陷，故不能鼓脉外出，以成波澜也。遂投以升陷汤，为其作渴，将方中知母改用六钱，连服三剂，病愈强半，右脉亦较前有力，遂去升麻，又服数剂全愈。", "19485": "一妇人，因临盆努力过甚，产后数日，胁下作疼，又十余日，更发寒热。其翁知医，投以生化汤两剂，病大见愈。迟数日，寒热又作。遂延他医调治，以为产后瘀血为恙，又兼受寒，于活血化瘀药中，重加干姜。数剂后，寒热益甚，连连饮水，不能解渴。时当仲夏，身热如炙，又复严裹厚被，略以展动，即觉冷气侵肤。后愚诊视，左脉沉细欲无，右脉沉紧，皆有数象。知其大气下陷，又为热药所伤也。其从前服生化汤觉轻者，全得芎䓖升提之力也。治以升陷汤，将方中知母改用八钱，又加玄参六钱，一剂而寒热已，亦不作渴。从前两日不食，至此遂能饮食。惟胁下微疼，继服拙拟理郁升陷汤，二剂全愈。", "19486": "或问：紧为受寒之脉，故伤寒麻黄汤证，其脉必紧。此证既为热药所伤，何以其右脉沉紧？答曰：脉沉紧者，其脉沉而有力也。夫有力当作洪象，此证因大气下陷，虽内有实热，不能鼓脉作起伏之势，故不为洪而为紧，且为沉紧也。其独见于右部者，以所服干姜之热，胃先受之也。", "19487": "按：脉无起伏为弦，弦而有力，即紧脉也。若但弦，则为寒矣。仲景平脉篇谓「双弦者寒，偏弦者饮。」究之饮为稀涎，亦多系因寒而成也。", "19488": "一妇人，年三十余。得下痿证，两腿痿废，不能屈伸，上半身常常自汗，胸中短气，少腹下坠，小便不利，寝不能寐。延医治疗数月，病势转增。诊其脉细如丝，右手尤甚。知其系胸中大气下陷，欲为疏方。病家疑而问曰：「大气下陷之说，从前医者，皆未言及。然病之本源，既为大气下陷，何以有种种诸证乎？」答曰：人之大气虽在胸中，实能统摄全身，今因大气下陷，全身无所统摄，肢体遂有废而不举之处，此两腿之所以痿废也。其自汗者，大气既陷，外卫之气亦虚也。其不寐者，大气既陷，神魂无所依附也。小便不利者，三焦之气化，不升则不降，上焦不能如雾，下焦即不能如渎也。至于胸中短气，少腹下坠，又为大气下陷之明征也。遂治以升陷汤，因其自汗，加龙骨、牡蛎（皆不用煅）各五钱，两剂汗止，腿稍能屈伸，诸病亦见愈。继服拙拟理郁升陷汤数剂，两腿渐能著力。然痿废既久，病在筋脉，非旦夕所能脱然。俾用舒筋通脉之品，制作丸药，久久服之，庶能全愈。", "19489": "一妇人，年三十许。胸中满闷，不能饮食。医者纯用开破之药数剂，忽然寒热，脉变为迟。医者见脉迟，又兼寒热，方中加黄耆、桂枝、干姜各数钱，而仍多用破气之药。购药未服，愚应其邻家延请，适至其村，病家求为诊视，其脉迟而且弱，问其呼吸觉短气乎？答曰：今于服药数剂后，新添此证。知其胸中大气因服破气之药下陷。时医者在座，不便另为疏方，遂谓医曰：子方中所加之药，极为对证，然此时其胸中大气下陷，破气药分毫不可再用。遂单将所加之黄耆、桂枝、干姜煎服。寒热顿已，呼吸亦觉畅舒。后医者即方略为加减，又服数剂全愈。", "19490": "门人高××曾治一人，年三十余。因枵腹劳力过度，致大气下陷。寒热往来，常常短气，大汗淋漓，头疼咽干，畏凉嗜睡，迁延日久，不能起床。医者误认为肝气郁结，投以鳖甲、枳实、麦芽诸药，病益剧。诊其脉，左寸关尺皆不见，右部脉虽见，而微弱欲无。知其为大气下陷，投以升陷汤，加人参三钱，一剂左脉即见，又将知母改用五钱，连服数剂全愈。", "19491": "高××又治一妇人，年三十许。胸中短气，常常出汗，剧时觉气不上达，即昏不知人，移时始苏，睡时恒自惊寤。诊其脉，微弱异常，知其胸中大气下陷甚剧。遂投以升陷汤，知母改用五钱，又加人参、萸肉（去净核）各三钱，连服数剂全愈。", "19492": "大气下陷之证，不必皆内伤也，外感证亦有之。一人年四十许，于季春得温证，延医调治不愈，留连两旬，病益沉重。后愚诊视，其两目清白无火，竟昏愦不省人事，舌干如磋，却无舌苔。问之亦不能言语，周身皆凉，其五六呼吸之顷，必长出气一口。其脉左右皆微弱，至数稍迟，此亦胸中大气下陷也。盖大气不达于脑中则神昏，大气不潮于舌本则舌干，神昏舌干，故问之不能言也。其周身皆凉者，大气陷后，不能宣布于营卫也。其五六呼吸之顷，必长出气者，大气陷后，胸中必觉短气，故太息以舒其气也。遂用野台参一两、柴胡二钱，煎汤灌之，一剂见轻，两剂全愈。", "19493": "一人，年三十余。于初夏得温病，医者用凉药清解之，兼用枳实、青皮破气诸品，连服七八剂，谵语不省人事，循衣摸床，周身颤动。再延他医，以为内风已动，辞不治。后愚诊视，其脉五至，浮分微弱，而重按似有力，舌苔微黄，周身肌肤不热，知其温热之邪，随破气之药下陷已深，不能外出也。遂用生石膏二两，知母、野台参各一两，煎汤两茶杯，分二次温服。自午至暮，连进二剂，共服药四次，翌日精神清爽，能进饮食，半日进食五次，犹饥而索食。看护者不敢复与，则周身颤动，复发谵语，疑其病又反复，求再诊视。其脉象大致和平，而浮分仍然微弱。恍悟其胸中大气，因服破气之药下陷，虽用参数次，至此犹未尽复，故亟亟求助于水谷之气，且胃中之气，因大气下陷无所统摄，或至速于下行，而饮食亦因之速下也。遂用野台参两许，佐以麦门冬（带心）三钱、柴胡二钱，煎汤饮下，自此遂愈。", "19494": "庚戍秋，在沧州治病，有赵姓，忽过访，言有疑事，欲质诸先生。问何疑？曰：予妹半月前来归宁，数日间，无病而亡，未知何故？愚曰：此必有病，子盖未知耳。×曰：其前一日，觉咽喉发闷，诊其脉沉细，疑其胸有郁气，俾用开气之药一剂，翌日不觉轻重，惟自言不再服药，斯夕即安坐床上而逝。其咽喉中发闷，并不甚剧，故曰无病也。愚曰：此胸中大气下陷耳。时行箧中有治大气下陷诸案，因出示之，且为剖析其理。×泫然流涕曰，斯诚为药误矣。", "19495": "一农家媪，年五十余。因麦秋农家忙甚，井臼之事皆自任之，渐觉呼吸不利，气息迫促。医者误认为气逆作喘，屡投以纳气降气之药，气息遂大形迫促，其努力呼吸之声，直闻户外。延愚诊视，及至，诊其脉左右皆无，勉为疏方，取药未至而亡，此亦大气下陷也。其气息之迫促，乃肺之呼吸将停，努力呼吸以自救也，医者又复用药，降下其气，何其谬哉！", "19496": "或问：案中所载大气下陷证，病因及其病状，皆了如指掌矣。然其脉之现象，或见于左部，或见于右部，或左右两部皆有现象可征，且其脉多迟，而又间有数者，同一大气之下陷也，何以其脉若是不同乎？答曰：胸中大气包举肺外，原与肺有密切之关系，肺之脉诊在右部，故大气下陷，右部之脉多微弱者其常也。然人之元气自肾达肝，自肝达于胸中，为大气之根本。其人或肝肾素虚，或服破肝气之药太过，其左脉或即更形微弱，若案中左部寸关尺皆不见，左脉沉细欲无，左关参伍不调者是也。至其脉多迟，而又间有数者，或因阴分虚损，或兼外感之热，或为热药所伤，乃兼证之现脉，非大气下陷之本脉也。", "19497": "湖北韩××妻，年六旬，素多肝郁，浸至胸中大气下陷。其气短不足以息，因而努力呼吸，有似乎喘；喉干作渴；心中满闷怔忡；其脉甚沉微。知其胸中大气下陷过甚，肺中呼吸几有将停之势，非投以升陷汤，以升补其大气不可。为录出原方，遵注大气；陷之甚者将升麻加倍服。一剂后，吐出黏涎数碗，胸中顿觉舒畅。又于方中加半夏、陈皮，连服三剂，病遂霍然。盖此证因大气下陷，其胸肺胃脘无大气以斡旋之，约皆积有痰涎，迨服药后，大气来复，故能运转痰涎外出，此《金匮》水气门所谓「大气一转，其气（水气即痰涎）乃散」也。后大气下陷证数见不鲜，莫不用升陷汤加减治愈。", "19498": "族婶母，年四十余岁，身体素弱。因境遇不顺，又多抑郁。癸亥十月下旬，忽患头疼甚剧，已三日矣，族叔来舍，俾生往诊。及至，闻呻吟不已，卧床不起，言已针过百会及太阳两处，均未见效。其左脉微细如丝，按之即无，右脉亦无力，自言气息不接，胸闷不畅，不思饮食，自觉精神恍惚，似难支持，知其胸中之大气下陷也。其头疼者，因大气陷后，有他经之逆气乘虚上干也。遵用升陷汤原方，升提其下陷之大气，连服数剂全愈。", "19499": "程姓男孩，年五岁，乳哺不足，脱肛近四载，医不能治。其面白神疲，身体孱弱；大肠坠出二寸许，用手塞入，旋又坠出；其脉濡弱无力；呼吸促短，状若不能接续。知其胸中大气下陷，下焦之气化因之不能固摄也。仿用升陷汤方，用生箭耆四钱，知母二钱，桔梗、柴胡、升麻各一钱，潞参、净萸肉各三钱煎汤一盅，分两次温饮下。连服二剂，肛即收缩。乃减去升麻，再服三剂，全愈。", "19500": "××之内，以其夫病势沉重，深恐难起，忧虑成疾。心内动悸，痞塞短气。医者以为痰郁，用二陈汤加减清之，病益加剧。因鉴其父为药所误（其父因下痢十余日，医用大黄四钱降之复杯而卒），遂停药不敢服。此际愚正在城中为其夫调治余病。俟愚来家求诊，见其满面油光，两手尺寸之脉皆极沉，惟关脉坚而有力。愚曰：「此乃胸中大气下陷，何医者不明如是，而用清痰之二陈也。今两关脉之坚弦，乃彼用药推荡之力。」诊际，大气一陷，遂全身一战，冷汗满额，心即连次跳动十余次。遂用升陷汤，再仿逍遥散、炙甘草汤之意，提其下陷之气，散其中宫之滞，并以交其心肾。一剂而三部平，大气固。嗣因尺中太微，而理气药及升柴等药皆不敢用，遂按治大气下陷方之意及治虚劳之法，精心消息，调治而愈。", "19501": "有冯××，务农而家小康。其母章氏，年正八秩，体丰善饭。一日忽觉左手麻痹，渐至不能持碗。越朝方食面饼，倏然僵厥，坐向下堕，肢冷额汗，气息仅属。人皆以为猝中也，聚商救治，自午至晡，逐见危殆，来请吾为筹挽救简方，以老人素不服药，且口噤鼻塞，恐药汁亦难下咽耳。吾意谓年老久厥，讵能回阳？姑嘱以红灵丹少许吹鼻中，倘嚏气能宣通，再议用药。乃药甫入而嚏作，似渐苏醒。然呼吸甚微，如一线游丝，恐风吹断。先按口鼻，温度甚低，音在喉中，犹言誓不服药。诊其脉，则沉微，察其瞳，亦涣散。遂确定为大气下陷。但值耄年，势难遽投重峻之剂，爰照升陷汤方而小其剂，用生箭耆一钱五分，知母八分，净萸肉一钱，柴胡四分，升麻三分。煎服须臾，即渐有转机。续进两剂，逐次平复。继俾服潞党参，每日二钱，加五味子五粒，广陈皮少许，频饮代茶。今春见之，较未病前更倍康强矣。", "19502": "一九二六年冬，河东友人翟××之母乳部生疮，疼痛难忍，同事王××约往诊视。翟××言，昨日请医诊治，服药一剂，亦不觉如何，惟言誓不再服彼医方药。生诊视时，其脉左关弦硬，右寸独微弱，口不能言，气息甚微，病势已危险万分。生断为年高因病疮大气下陷，为开升陷汤，以升举其气，又加连翘、丹参诸药，以理其疮。一剂能言，病人喜甚，非按原方再服一剂不可。后生又诊数次，即方略为加减，数服全愈。后遇此证数次，亦皆用升陷汤加减治愈。", "19503": "一妇人，产后乳上生痈，肿疼殊甚。延西医治不效，继延吾诊治。其脓已成，用针刺之，出脓甚多，第二日已眠食俱安矣。至第三日，忽神昏不食，并头疼。其母曰：「此昨日受风寒以致如此。」诊其脉，微细若无，身无寒热，心跳，少腹微疼，知非外感，当系胸中大气下陷。投以升陷汤，两剂全愈。", "19504": "或问：心脏属火，西人亦谓周身热力皆发于心，其能宣通周身之热宜矣。今论周身热力不足，何以谓心肺之阳皆虚？答曰：肺与心同居膈上，左心房之血脉管，右心房之回血管，皆与肺循环相通，二脏之宣通热力，原有相助为理之妙。然必有大气以斡旋之，其功用始彰耳。", "19505": "一童子，年十三四，心身俱觉寒凉，饮食不化，常常短气，无论服何热药，皆分毫不觉热。其脉微弱而迟，右部兼沉。知其心肺阳分虚损，大气又下陷也。为制此汤，服五剂，短气已愈，身心亦不若从前之寒凉。遂减桂枝之半，又服数剂全愈。俾停药，日服生硫黄分许，以善其后。", "19506": "一人，年五十余。大怒之后，下痢月余始愈。自此胸中常觉满闷，饮食不能消化。数次延医服药，不外通利气分之品，即间有温补脾胃者，亦必杂以破气之药，愈服病愈增重。后愚诊视，其脉沉细微弱，至数甚迟。询其心中，常有觉凉之时。知其胸中大气下陷，兼上焦阳分虚损也。遂投以此汤，十剂全愈。后因怒，病又反复，医者即愚方，加厚朴二钱，服后少腹下坠作疼，彻夜不能寐，复求为诊治，仍投以原方而愈。", "19507": "赵姓媪，年近五旬，忽然昏倒不语，呼吸之气大有滞碍，几不能息，其脉微弱而迟。询其生平，身体羸弱，甚畏寒凉，恒觉胸中满闷，且时常短气。即其素日资禀及现时病状以互戡病情，其为大气下陷兼寒饮结胸无疑。然此时形势将成痰厥，住在乡村取药无及，遂急用胡椒二钱捣碎煎两三沸，澄取清汤灌下。须臾胸中作响，呼吸顿形顺利。继用干姜八钱煎汤一盅，此时已自能饮下。须臾气息益顺，精神亦略清爽，而仍不能言，且时作呵欠，十余呼吸之顷必发太息，知其寒饮虽开，大气之陷者犹未复也。遂投以拙拟回阳升陷汤。服数剂，呵欠与太息皆愈，渐能言语。", "19508": "一妇人，年三十许。胸中满闷，时或作疼，鼻息发热，常常作渴。自言得之产后数日，劳力过度。其脉迟而无力，筹思再三，莫得病之端绪。姑以生山药一两，滋其津液，鸡内金二钱、陈皮一钱，理其疼闷，服后忽发寒热。再诊其脉，无力更甚，知其气分郁结，又下陷也。遂为制此汤，一剂诸病皆觉轻，又服四剂全愈。", "19509": "一少女，年十五。脐下左边起一症瘕，沉沉下坠作疼，上连腰际，亦下坠作疼楚，时发呻吟。剧时，常觉小便不通，而非不通也。诊其脉，细小而沉。询其得病之由，言因小便不利，便时努力过甚，其初腰际坠疼，后遂结此症瘕。其方结时，揉之犹软，今已五阅月，其患处愈坚结。每日晚四点钟，疼即增重，至早四点钟，又渐觉轻。愚闻此病因，再以脉象参之，知其小便时努力过甚。上焦之气，陷至下焦而郁结也。遂治以理郁升陷汤，方中乳香、没药皆改用四钱，又加丹参三钱、升麻钱半，二剂而坠与疼皆愈。遂去升麻，用药汁送服朱血竭末钱许，连服数剂，症瘕亦消。", "19510": "或问：龙骨、牡蛎为收涩之品，兼胁下胀疼者，何以加此二药？答曰：胁为肝之部位，胁下胀疼者，肝气之横恣也，原当用泻肝之药，又恐与大气下陷者不宜。用龙骨、牡蛎，以敛戢肝火，肝气自不至横恣，此敛之即以泻之，古人治肝之妙术也。且黄耆有膨胀之力，胀疼者原不宜用，有龙骨、牡蛎之收敛，以缩其膨胀之力，可放胆用之无碍，此又从体验而知道也。尝治一少妇，经水两月不见，寒热往来，胁下作疼，脉甚微弱而数至六至。询之常常短气，投以理郁升陷汤，加龙骨、牡蛎各五钱，为脉数，又加玄参、生地、白芍各数钱，连服四剂。觉胁下开通，瘀血下行，色紫黑，自此经水调顺，诸病皆愈。盖龙骨、牡蛎性虽收涩，而实有开通之力，《神农本草经》谓龙骨消症瘕，而又有牡蛎之咸能软坚者以辅之，所以有此捷效也。", "19511": "一妇人，年三十余，劳心之后兼以伤心，忽喘逆大作，迫促异常。其翁知医，以补敛元气之药治之，觉胸中窒碍不能容受。更他医以为外感，投以小剂青龙汤喘益甚。延愚诊视，其脉浮而微数，按之即无，知为阴阳两虚之证。盖阳虚则元气不能自摄，阴虚而肝肾又不能纳气，故作喘也。为制此汤，病人服药后，未及复杯曰：「吾有命矣。」询之曰：「从前呼吸惟在喉间，几欲脱去，今则转落丹田矣。」果一剂病愈强半，又服数剂全愈。", "19512": "一妇人，年二十余，因与其夫反目，怒吞鸦片。已经救愈，忽发喘逆，迫促异常。须臾又呼吸顿停，气息全无，约十余呼吸之顷，手足乱动，似有蓄极之势，而喘复如故。若是循环不已，势近垂危，延医数人，皆不知为何病。后愚诊视其脉，左关弦硬，右寸无力，精思良久，恍然悟曰：此必怒激肝胆之火，上冲胃气。夫胃气本下行者也，因肝胆之火冲之，转而上逆，并迫肺气亦上逆，此喘逆迫促所由来也。逆气上干，填塞胸膈，排挤胸中大气，使之下陷。夫肺悬胸中，须臾无大气包举之，即须臾不能呼吸，此呼吸顿停所由来也（此理参观升陷汤后跋语方明）。迨大气蓄极而通，仍上达胸膈，鼓动肺脏，使得呼吸、逆气遂仍得施其击撞，此又病势之所以循环也。《神农本草经》载，桂枝主上气咳逆、结气、喉痹、吐吸（吸不归根即吐出），其能降逆气可知。其性温而条达，能降逆气，又能升大气可知。遂单用桂枝尖三钱，煎汤饮下，须臾气息调和如常。夫以桂枝一物之微，而升陷降逆，两擅其功，以挽回人命于顷刻，诚天之生斯使独也。然非亲自经验者，又孰信其神妙如是哉！继用参赭镇气汤，去山药、苏子，加桂枝尖三钱、知母四钱，连服数剂，病不再发。此喘证之特异者，故附记于此。", "19513": "定县吴××妻病，服药罔效。弟诊其脉，浮而无力。胸次郁结，如有物杜塞，饮食至胃间，恒觉烧热不下。仿参赭镇气汤之义，用野台参六钱，赭石细末二两。将二药煎服，胸次即觉开通。服至二剂，饮食下行无碍。因其大便犹燥，再用当归、肉苁蓉各四钱，俾煎服。病若失。", "19514": "洪××，年五十余，家素贫苦，曾吸鸦片，戒未多年，由咳而成喘疾，勉强操劳，每届冬令则加剧，然病发时亦往往不服药而自愈。兹次发喘，初由外感，兼发热头痛。医者投以二活、防、葛，大剂表散，遂汗出二日不止，喘逆上冲，不能平卧，胸痞腹胀，大便旬余未行，语不接气，时或瘛疭，种种见证，已濒极险。诊其脉，微细不起。形状颓败殊甚。详细勘视，诚将有阴阳脱离之虞。适日前阅赭石解，记其主治，揣之颇合。但恐其性太重镇而正气将随以下陷也，再四踌躇，因配以真潞党参、生怀山药、野茯神、净萸肉、广桔红、京半夏、龙骨、牡蛎、苏子、蒡子等，皆属按证而拟，竟与参赭镇气汤大致相同。一剂病愈大半，两剂即扶杖起行，三剂则康复如恒矣。前月遇之，自言冬不知寒，至春亦未反复。", "19515": "或问：养气虽能隔肺胞透过，亦甚属些些无多，何以当吸气内入之时，全腹皆有膨胀之势？答曰：若明此理，益知所以致喘之由。人之脏腑皆赖气以撑悬，是以膈上有大气，司肺呼吸者也；膈下有中气，保合脾胃者也，脐下有元气，固性命之根蒂者也。当吸气入肺之时，肺胞膨胀之力，能鼓舞诸气，节节运动下移，而周身之气化遂因之而流通。且喉管之分支下连心肝，以通于奇经诸脉，当吸气内入之时，所吸之气原可由喉管之分支下达，以与肺中所吸之气，相助为理也。下焦肝肾（奇经与肾相维系）属阴，阴虚气化不摄则内气膨胀，遂致吸入之气不能容受而急于呼出，此阴虚者所以不纳气而作喘也。", "19516": "痰郁肺窍则作喘，肾虚不纳气亦作喘。是以论喘者恒责之肺、肾二脏，未有责之于脾、胃者。不知胃气宜息息下行，有时不下行而转上逆，并迫肺气亦上逆即可作喘。脾体中空，能容纳诸回血管之血，运化中焦之气，以为气血宽闲之地，有时失其中空之体，或变为紧缩，或变为胀大，以致壅激气血上逆迫肺，亦可作喘。且脾脉缓大，为太阴湿土之正象，虚劳喘嗽者，脉多弦数，与缓大之脉反对，乃脾土之病脉也。故重用山药以滋脾之阴，佐以于术以理脾之阳，脾脏之阴阳调和，自无或紧缩、或涨大之虞。特是，脾与胃脏腑相依，凡补脾之药皆能补胃。而究之脏腑异用，脾以健运磨积，宣通津液为主；胃以熟腐水谷、传送糟粕为主。若但服补药，壅滞其传送下行之机，胃气或易于上逆，故又宜以降胃之药佐之，方中之赭石、陈皮、牛蒡是也。且此数药之性，皆能清痰涎利肺气，与山药、玄参并用，又为养肺止嗽之要品也。用甘草、白芍者，取其甘苦化合，大有益于脾胃，兼能滋补阴分也。并治一切虚劳诸证者，诚以脾胃健壮，饮食增多，自能运化精微以培养气血也。", "19517": "一人，年二十二，喘逆甚剧，脉数至七至，用一切治喘药皆不效，为制此方。将药煎成，因喘剧不能服，温汤三次始服下，一剂见轻，又服数剂全愈。", "19518": "西人谓：心有病可以累肺作喘，此说诚信而有征。盖喘者之脉多数，夫脉之原动力发于心，脉动数则心动亦数可知。心左房之赤血与右房之紫血，皆与肺循环相通。若心动太急，逼血之力过于常度，则肺脏呼吸亦因之速过常度，此自然之理也。然心与肾为对待之体，心动若是之急数，肾之真阴不能上潮，以靖安心阳可知。由是言之，心累肺作喘之证，亦即肾虚不纳气之证也。", "19519": "治因心肺阳虚，致脾湿不升，胃郁不降，饮食不能运化精微，变为饮邪。停于胃口为满闷，溢于膈上为短气，渍满肺窍为喘促，滞腻咽喉为咳吐黏涎。甚或阴霾布满上焦，心肺之阳不能畅舒，转郁而作热。或阴气逼阳外出为身热，迫阳气上浮为耳聋。然必诊其脉，确乎弦迟细弱者，方能投以此汤。", "19520": "一妇人，年四十许。胸中常觉满闷发热，或旬日，或浃辰之间，必大喘一两日。医者用清火理气之药，初服稍效，久服转增剧。后愚诊视，脉沉细几不可见。病家问：系何病因？愚曰：此乃心肺阳虚，不能宣通脾胃，以致多生痰饮也。人之脾胃属土，若地舆然。心肺居临其上正当太阳部位（膈上属太阳，观《伤寒论》太阳篇自知），其阳气宣通，若日丽中天暖光下照。而胃中所纳水谷，实借其阳气宣通之力，以运化精微而生气血，传送渣滓而为二便。清升浊降，痰饮何由而生？惟心肺阳虚，不能如离照当空，脾胃即不能借其宣通之力，以运化传送，于是饮食停滞胃口，若大雨之后，阴雾连旬，遍地污淖，不能干渗，则痰饮生矣。痰饮既生，日积月累，郁满上焦则作闷，渍满肺窍则作喘，阻遏心肺阳气，不能四布则作热。医者不识病源，犹用凉药清之，勿怪其久而增剧也。遂为制此汤，服之一剂，心中热去，数剂后转觉凉甚。遂去白芍，连服二十余剂，胸次豁然，喘不再发。", "19521": "一妇人，年三十许。身形素丰。胸中痰涎郁结，若碍饮食，上焦时觉烦热。偶服礞石滚痰丸有效，遂日日服之。初则饮食加多，继则饮食渐减，后则一日不服，即不能进饮食。又久服之。竟分毫无效，日仅一餐，进食少许，犹不能消化。且时觉热气上腾，耳鸣欲聋，始疑药不对证。求愚诊治，其脉象浮大，按之甚软。愚曰：此证心肺阳虚，脾胃气弱，为服苦寒攻泻之药太过，故病证脉象如斯也。拟治以理饮汤。病家谓，从前医者，少用桂附，即不能容受，恐难再用热药。愚曰：桂附原非正治心肺脾胃之药，况又些些用之，病重药轻，宜其不受。若拙拟理饮汤，与此证针芥相投，服之必无他变。若畏此药，不敢轻服，单用干姜五钱，试服亦可。病家依愚言，煎服干姜后，耳鸣即止，须臾觉胸次开通。继投以理饮汤，服数剂，心中亦觉凉甚。将干姜改用一两，又服二十余剂，病遂除根。", "19522": "一妇人，年四十许。上焦满闷烦躁，思食凉物，而偶食之，则满闷益甚。且又黎明泄泻，日久不愈，满闷益甚，将成臌胀。屡次延医服药，多投以半补半破之剂，或佐以清凉，或佐以收涩，皆分毫无效。后愚诊视，脉象弦细而迟。知系寒饮结胸，阻塞气化。欲投以理饮汤，病家闻而迟疑，似不敢服。亦俾先煎干姜数钱服之，胸中烦躁顿除。为其黎明泄泻，遂将理饮汤去厚朴、白芍，加生鸡内金钱半，补骨脂三钱，连服十余剂，诸病皆愈。", "19523": "一妇人，年近五旬，常觉短气，饮食减少。屡次延医服药，或投以宣通，或投以升散，或投以健补脾胃，兼理气之品，皆分毫无效。浸至饮食日减，羸弱不起，奄奄一息，病家亦以为不治之证矣。后闻愚在其邻村，屡救危险之证，复延愚诊视。其脉弦细欲无，频吐稀涎。询其心中，言觉有物杜塞胃口，气不上达，知其为寒饮凝结也。遂投以理饮汤，方中干姜改用七钱，连服三剂，胃口开通。又觉呼吸无力，遂于方中加生黄耆三钱，连服十余剂，病全愈。方书谓，饮为水之所结，痰为火之所凝，是谓饮凉而痰热也。究之饮证亦自分凉热，其热者，多由于忧思过度，甚则或至癫狂，虽有饮而恒不外吐。其凉者，则由于心肺阳虚，如方名下所言种种诸情状。且其证，时吐稀涎，常觉短气，饮食廉少，是其明征也（后世谓痰之稀者为饮，稠者为痰，与《金匮》所载四饮名义不同）。", "19524": "邑，韩××医学传家，年四十有四，偶得奇疾。卧则常常发搐，旋发旋止，如发寒战之状，一呼吸之间即愈。即不发搐时，人偶以手抚之，又辄应手而发。自治不效，广求他医治疗皆不效。留连半载，病势浸增。后愚诊视，脉甚弦细。询其饮食甚少，知系心肺脾胃阳分虚惫，不能运化精微，以生气血。血虚不能荣筋，气虚不能充体，故发搐也。必发于卧时者，卧则气不顺也。人抚之而辄发者，气虚则畏人按也。授以理饮汤方，数剂，饮食加多，搐亦见愈。二十剂后，病不再发。", "19525": "世医治痰，习用宋《局方》二陈汤，谓为治痰之总剂。不知二陈汤能治痰之标，不能治痰之本。何者？痰之标在胃，痰之本原在于肾。肾主闭藏，以膀胱为腑者也。其闭藏之力，有时不固，必注其气于膀胱。膀胱膨胀，不能空虚若谷，即不能吸引胃中水饮，速于下行而为小便，此痰之所由来也。又肾之上为血海，奇经之冲脉也。其脉上隶阳明，下连少阴。为其下连少阴也，故肾中气化不摄，则冲气易于上干。为其上隶阳明也，冲气上干，胃气亦多上逆，不能息息下行以运化水饮，此又痰之所由来也。此方以半夏为君，以降冲胃之逆。即重用芡实，以收敛冲气，更以收敛肾气，而厚其闭藏之力。肾之气化治，膀胱与冲之气化，自无不治，痰之本原清矣。用芝麻、柏实者，润半夏之燥，兼能助芡实补肾也。用芍药、茯苓者，一滋阴以利小便，一淡渗以利小便也。用陈皮者，非借其化痰之力，实借其行气之力，佐半夏以降逆气，并以行芡实、芝麻、柏实之滞腻也。", "19526": "毛××又尝治一少妇，患痫风。初两三月一发，浸至两三日一发。脉滑、体丰，知系痰涎为恙。亦治以此汤，加赭石三钱，数剂竟能拔除病根。后与愚觌面述之。愚喜曰：向拟此汤时，原不知能治痫风，经兄加赭石一味，即建此奇功，大为此方生色矣。", "19527": "一人，年三十余。常觉胆怯，有时心口或少腹𥆧动后，须臾觉有气起自下焦，上冲胸臆，郁而不伸，连作呃逆，脖项发热，即癫狂唱呼。其夹咽两旁内，突起若瘰疬，而不若瘰疬之硬。且精气不固，不寐而遗，上焦觉热，下焦觉凉。其脉左部平和，微嫌无力，右部直上直下（李士材脉诀云直上直下冲脉昭昭），仿佛有力，而按之非真有力。从前屡次医治皆无效。此肾虚，致冲气挟痰上冲，乱其心之神明也。投以此汤，减厚朴之半，加山萸肉（去净核）五钱，数剂诸病皆愈，惟觉短气。知系胸中大气下陷（理详升陷汤下），投以拙拟升陷汤，去升麻、柴胡，加桂枝尖二钱，两剂而愈。盖此证，从前原有逆气上干，升麻、柴胡能升大气，恐兼升逆气。桂枝则升大气，兼降逆气，故以之代升、柴也。", "19528": "一媪，年六十二，资禀素羸弱。偶当外感之余，忽然妄言妄见，惊惧异常，手足扰动，饥渴不敢饮食，少腹塌陷，胸膈突起。脉大于平时一倍，重按无力。知系肝肾大虚，冲气上逆，痰火上并，心神扰乱也。投以此汤，去朴硝，倍赭石，加生山药、山萸肉（去净核）、生地黄各六钱。又磨取铁锈水煎药（理详一味铁养汤下），一剂即愈。又服一剂，以善其后。", "19529": "一妇人，年二十许。数日之前，觉胸中不舒，一日忽然昏昏似睡，半日不醒。适愚自他处归，过其村。病家见愚喜甚，急求诊治。其脉沉迟，兼有闭塞之象。唇𥆧动。凡唇动者，为有痰之征。脉象，当系寒痰壅滞上焦过甚。遂令人扶之坐，以大指点其天突穴，俾其喉痒作嗽。约点半点钟，咳嗽十余次，吐出凉痰一碗，始能言语。又用干姜六钱，煎汤饮下而愈。", "19530": "岁在甲寅，客居大名之金滩镇。时当孟春，天寒，雨且雪，一兵士衣装尽湿，因冻甚，不能行步，其伙舁之至镇，昏不知人。呼之不应，用火烘之，且置于温暖之处，经宿未醒。闻愚在镇，曾用点天突穴法，治愈一人，求为诊治。见其僵卧不动，呼吸全无。按其脉，仿佛若动。以手掩其口鼻，每至呼吸之顷，微觉有热，知犹可救。遂令人扶起俾坐，冶以点天突穴之法，兼捏其结喉。约两点钟，咳嗽二十余次，共吐凉痰碗半，始能呻吟。亦饮以干姜而愈。", "19531": "【明矾汤】生白矾，长于治顽痰热痰，急证用之，诚有捷效。惟凉痰凝滞者，断不可用。一妇人，年二十余。因悲泣过度，痰涎杜塞胃口，其胃气蓄极上逆，连连干呕。形状又似呃逆，气至咽喉不能上达。剧时，浑身抖战，自掇其发，有危在顷刻之状。医者，用生姜自然汁灌之，益似不能容受。愚诊视之，其脉左手沉濡，右三部皆无。然就其不受生姜观之，仍当是热痰杜塞，其脉象如此者，痰多能瘀脉也。且其面有红光，亦系热证。遂用生白矾二钱，化水俾饮之，即愈。此方愚用之屡次，审知其非寒痰杜塞，皆可随手奏效。即痰厥至垂危者，亦能救愈。", "19532": "【麝香香油灌法】严用和云：「中风不醒者，麝香清油灌之。」曾治一人，年二十余。因夫妻反目，身躯忽然后挺，牙关紧闭，口出涎沫。及愚诊视，已阅三点钟矣。其脉闭塞不全，先用痧药吹鼻，得嚏气通，忽言甚渴。及询之，仍昏昏如故，惟牙关微开，可以进药。因忆严用和麝香清油灌法，虽治中风不醒，若治痰厥不醒，亦当有效。况此证形状，未必非内风掀动。遂用香油二两炖热，调麝香一分，灌之即醒。", "19533": "朱姓妇，产后旬余，甚平顺。适伊弟来视，午后食煮包一大碗，伊弟去后，竟猝然昏倒，四肢抽搐，不省人事。延为诊视，六脉皆伏。当系产后五内空虚，骤而饱食填息，胸中大气不能宣通，诸气亦因之闭塞，故现此证。取药不及，急用点天突穴及捏结喉法，又用针刺十宣及少商穴，须臾咳吐稠痰若干，气顺腹响，微汗而愈。", "19534": "一妇人，年四十，上焦发热，咳吐失音，所吐之痰自觉腥臭，渐渐羸瘦，其脉弦而有力。投以清火润肺之药，数剂不效。为制此汤，于大队清火润肺药中，加生黄耆一味以助元气，数剂见轻，十余剂后，病遂全愈。", "19535": "或问：脉既有力矣，何以复用补气之药？答曰：脉之有力，有真有假。凡脉之真有力者，当于敦厚和缓中见之，此脾胃之气壮旺，能包括诸脏也（脾胃属土能包括金木水火诸脏腑）。其余若脉象洪而有力，多系外感之实热。若滑而有力，多系中焦之热痰。若弦而有力，多系肝经之偏盛，尤为有病之脉，此证之脉是也。盖肺属金、肝属木，金病不能镇木，故脉现弦而有力之象。此肝木横恣，转欲侮金之象也。凡肺痿、肺痈之病，多有胁下疼者，亦系肝木偏胜所致。", "19536": "一人，年三十余，肺中素郁痰火，又为外感拘束，频频咳嗽，吐痰腥臭。恐成肺痈，求为诊治。其脉浮而有力，关前兼滑。遂先用越婢汤，解其外感，咳嗽见轻，而吐痰腥臭如故。次用葶苈（生者三钱纱袋装之）大枣（七枚擘开）汤，泻其肺中壅滞之痰，间日一服。又用三七、川贝、粉甘草、金银花为散，鲜地骨皮煎汤，少少送服，日三次。即用葶苈大枣汤之日，亦服一次。如此调治数日，葶苈大枣汤用过三次，痰涎顿少，亦不腥臭。继用清金益气汤、贝母、牛蒡子各加一钱，连服十余剂，以善其后。", "19537": "一人，年四十八，咳吐痰涎甚腥臭，夜间出汗，日形羸弱。医者言不可治，求愚诊视。脉数至六至，按之无力，投以此汤，加生龙骨六钱，又将方中知母加倍，两剂汗止，又服十剂全愈。", "19538": "病剧者加三七二钱（捣细送服）。脉虚弱者，酌加人参、天冬各数钱。", "19539": "肺痈者，肺中生痈疮也。然此证肺中成疮者，十之一二，肺中腐烂者，十之八九。故治此等证，若葶苈、皂荚诸猛烈之药，古人虽各有专方，实不可造次轻用，而清火解毒化腐生肌之品，在所必需也。甘草为疮家解毒之主药，且其味至甘，得土气最厚，故能生金益肺，凡肺中虚损糜烂，皆能愈之。是以治肺痈便方，有单用生粉草四两煎汤，频频饮之者。而西人润肺药水，亦单有用甘草制成者。特其性微温，且有壅滞之意，而调以知母之寒滑，则甘草虽多用无碍，且可借甘草之甘温，以化知母之苦寒，使之滋阴退热，而不伤胃也。丹参性凉清热，色赤活血，其质轻松，其味微辛，故能上达于肺，以宣通脏腑之毒血郁热而消融之。乳香、没药同为疮家之要药，而消肿止疼之力，没药尤胜，故用之以参赞丹参，而痈疮可以内消。三七化瘀解毒之力最优，且化瘀血而不伤新血，其解毒之力，更能佐生肌药以速于生肌，故于病之剧者加之。至脉虚者，其气分不能运化药力，方虽对证无功，又宜助以人参。而犹恐有肺热还伤肺之虞，是以又用天冬，以解其热也。", "19540": "一人，年三十余，昼夜咳嗽，吐痰腥臭，胸中隐隐作疼，恐成肺痈，求为诊治。其脉浮而有力，右胜于左，而按之却非洪实。投以清金解毒汤，似有烦躁之意，大便又滑泻一次。自言从前服药，略补气分，即觉烦躁，若专清解，又易滑泻，故屡次延医无效也。遂改用粉甘草两半、金银花一两、知母、牛蒡子各四钱，煎汤一大碗，分十余次温饮下，俾其药力常在上焦，十剂而愈。后两月，因劳力过度旧证复发，胸中疼痛甚于从前，连连咳吐，痰中兼有脓血。再服前方不效，为制此汤，两剂疼止。为脉象虚弱，加野台参三钱，天冬四钱，连服十剂全愈。", "19541": "奉天赵××，年四十许。心中发热、懒食、咳嗽、吐痰腥臭，羸弱不能起床。询其得病之期，至今已迁延三月矣。其脉一分钟八十五至，左脉近平和，右脉滑而实，舌有黄苔满布，大便四五日一行且甚燥。知其外感，稽留于肺胃，久而不去，以致肺脏生炎，久而欲腐烂也。西人谓肺结核证至此，已不可治。而愚慨然许为治愈，投以清金解毒汤，去黄耆，加生山药六钱、生石膏一两，三剂后热大清减，食量加增，咳嗽吐痰皆见愈。遂去山药，仍加黄耆三钱，又去石膏，以花粉六钱代之，每日兼服阿斯匹林四分之一瓦，如此十余日后，病大见愈。身体康健，而间有咳嗽之时，因忙碌遂停药不服。二十日后，咳嗽又剧，仍吐痰有臭，再按原方加减治之，不甚效验。亦俾服犀黄丸病遂愈。", "19542": "治吐血、衄血，脉洪滑而长，或上入鱼际，此因热而胃气不降也，以寒凉重坠之药，降其胃气则血止矣。", "19543": "一童子，年十四，陡然吐血，一昼夜不止，势甚危急，求为诊视。其脉洪长，右部尤重按有力。知其胃气因热不降，血随逆气上升也。为拟此汤，一剂而愈，又服一剂，脉亦和平。", "19544": "一人，年十八，偶得吐血证，初不甚剧。因医者误治，遂大吐不止。诊其脉如水上浮麻，莫辨至数，此虚弱之极候也。若不用药立止其血，危可翘足而待。遂投以此汤，去竹茹，加生山药一两，赭石改用八钱，一剂血止。再诊其脉，左右皆无，重按亦不见。愚不禁骇然。询之心中亦颇安稳，惟觉酸懒无力。忽忆吕沧洲曾治一发斑证，亦六脉皆无，沧洲谓：脉者血之波澜，今因发斑伤血，血伤不能复作波澜，是以不见，斑消则脉出矣。遂用白虎加人参汤，化其斑毒，脉果出（详案在青盂汤下）。今此证大吐亡血，较之发斑伤血尤甚，脉之重按不见，或亦血分虚极，不能作波澜欤？其吐之时，脉如水上浮麻者，或因气逆火盛，强迫其脉外现欤？不然闻其诊毕还里（相距十里），途中复连连呕吐，岂因路间失血过多欤？踌躇久之，乃放胆投以大剂六味地黄汤，减茯苓、泽泻三分之二，又加人参、赭石各数钱，一剂脉出。又服平补之药二十余剂，始复初。", "19545": "按：因寒因热，皆可使胃气不降。然因热胃气不降者，人犹多知之，因寒胃气不降者，则知者甚鲜。黄氏论胃气不降，专主因寒一面，盖有所感触而言也。曾有一少妇，上焦烦热，不能饮食，频频咳吐，皆系稀涎，脉象弦细无力。知系脾胃湿寒，不能运化饮食下行，致成留饮为恙也。询其得病之初，言偶因咳嗽懒食，延本处名医投以栝蒌、贝母、麦冬之类，旋愈旋即反复，服药月余竟至如此。遂为开苓桂术甘汤，加干姜、半夏（细观理饮汤后跋语自知），且细为剖析用药之意。及愚旋里，其药竟不敢服，复请前医治之，月余而亡。夫世之所谓名医者，其用药大抵如此，何不读黄氏之论，而反躬自省也哉！", "19546": "门人高××实验一方：赭石、滑石等分研细，热时新汲井泉水送服，冷时开水送服，一两或至二两，治吐衄之因热者甚效。高××又在保阳，治一吐血证甚剧者，诸药皆不效，诊其脉浮而洪，至数微数，重按不实。初投以拙拟保元寒降汤，稍见效，旋又反复。高××遂放胆投以赭石二两、台参六钱、生杭芍一两，一剂而愈。", "19547": "天津曹××，年二十五岁，自春日患吐血证，时发时愈，不以介意。至仲冬，忽吐血较前剧，咳嗽音哑，面带贫血，胸中烦热，食少倦怠，屡治罔效，来寓求诊。左脉细弱，右脉则弦而有力，知其病久生热，其胃气因热上逆，血即随之上升也。为开寒降汤方，为其咳嗽音哑，加川贝三钱，连服二剂，病大轻减。又服二剂，不但吐血已止，而咳嗽音哑诸病皆愈。", "19548": "孟夏二十三日，赤日晴天，铄人脏腑。有陶××者，因业商，斯日出外买粮，午后忽于路中患吐血，迨抵家尚呕不止。凌晨来院求治。诊其脉象洪滑，重按甚实，知其为热所迫而胃气不降也。因夫子尝推《金匮》泻心汤为治吐衄良方，遂俾用其方煎汤，送服黑山栀细末二钱。服后病稍愈而血仍不止，诊其脉仍然有力，遂为开寒降汤，加广三七细末三钱，俾将寒降汤煎一大盅，分两次将三七细末送服。果一剂而愈。", "19549": "治吐衄脉虚濡而迟，饮食停滞胃口，不能消化，此因凉而胃气不降也，以温补开通之药，降其胃气，则血止矣。", "19550": "《内经》厥论篇谓阳明厥逆衄呕血，所谓阳明者，指胃腑而言也，所谓厥逆者，指胃腑之气上行而言也。盖胃以消化饮食，传送下行为职，是以胃气以息息下行为顺，设或上行则为厥逆；胃气厥逆，可至衄血、呕血，因血随胃气上行也。然胃气厥逆因热者固多，因寒者亦间有之。岁在壬寅，邑之北境，有学生刘××者，年十三岁，一日之间衄血四次。诊其脉甚和平，询其心中不觉凉热。因思吐衄之证热者居多，且以童子少阳之体，时又当夏令，遂略用清凉止血之品。衄益甚，脉象亦现微弱，知其胃气因寒不降，转迫血上逆而为衄也。投以拙拟温降汤，一剂即愈。隔数日又有他校学生，年十四岁，吐血数日不愈，其吐之时，多由于咳嗽。诊其脉，甚迟濡，右关尤甚。疑其脾胃虚寒，不能运化饮食，询之果然。盖吐血之证多由于胃气不降，饮食不能运化，胃气即不能下降。咳嗽之证，多由于痰饮入肺。饮食迟于运化，又必多生痰饮，因痰饮而生咳嗽，因咳嗽而气之不降者更转而上逆，此吐血之所由来也。亦投以温降汤，一剂血止，接服数剂，饮食运化，咳嗽亦愈。", "19551": "不惟吐衄之证有因寒者，即便血之证亦有因寒者，特其证皆不多见耳。邻村高某，年四十余，小便下血久不愈，其脉微细而迟，身体虚弱，恶寒，饮食减少。知其脾胃虚寒，中气下陷，黄坤载所谓「血之亡于便溺者，太阴不升也。」为疏方：干姜、于术各四钱，生山药、熟地黄各六钱，乌附子、炙甘草各三钱。煎服一剂，血即见少。连服十余剂，全愈。此方中不用肉桂者，恐其动血分也。", "19552": "治吐血过多，气分虚甚，喘促咳逆，血脱而气亦将脱。其脉上盛下虚，上焦兼烦热者。", "19553": "一叟，年六十四，素有劳疾，因劳嗽太甚，呕血数碗。其脉摇摇无根，或一动一止，或两三动一止。此气血虚极，将脱之候也。诊脉时见其所嗽吐者，痰血相杂。询其从前呕吐之时心中发热。为制此汤，一剂而血止，又服数剂脉亦调勺。", "19554": "河间裘××，年二十八岁。患咳嗽吐血，且咯吐甚多，气分太虚，喘息迫促，上焦烦热，其脉大而无力，右部尤甚，盖血脱而气亦将脱也。急用保元寒降汤，加青竹茹、麦门冬各三钱。一剂血止。至第二剂，将台参五钱易为西洋参一钱，服之而愈。方病相投，效如影响，洵不误也。", "19555": "治吐衄证，其人下元虚损，中气衰惫，冲气胃气因虚上逆，其脉弦而硬急，转似有力者。", "19556": "友人毛××曾治一少年吐血证。其人向经医者治愈，旋又反复。毛××诊其脉弦而有力，知其为冲胃之气上逆也。遂于治吐血方中，重用半夏、赭石以降逆，白芍、牡蛎（不煅）以敛冲泻热，又加人参以补其中气，使中气健旺以斡旋诸药成功。有从前为治愈之医者在座，颇疑半夏不可用，毛××力主服之。一剂血止，再剂脉亦和平，医者讶为异事。毛××晓知曰：「此证乃下元虚损，冲气因虚上逆，并迫胃气亦上逆，脉似有力而非真有力，李士材四字脉诀所谓：直上直下，冲脉昭昭者，即此谓也。若误认此脉为实热，而恣用苦寒之药凉其血分，血分因凉而凝，亦可止而不吐，而异日瘀血为恙，竟成劳瘵者多矣。今方中用赭石、半夏以镇冲气，使之安其故宅，而即用白芍、牡蛎以敛而固之，使之永不上逆。夫血为气之配，气为血之主，气安而血自安矣，此所以不治吐血，而吐血自止也。况又有人参之大力者，以参赞诸药，使诸药之降者、敛者，皆得有所凭借以成功乎。」", "19557": "一妇人，年近三旬，咳嗽痰中带血，剧时更大口吐血，常觉心中发热。其脉一分钟九十至，按之不实。投以滋阴宁嗽降火之药数剂无效。因思此证，若用药专止其嗽，嗽愈其吐血亦当愈。遂用川贝九钱，煎取清汤四茶盅，调入生山药细末一两，煮作稀粥。俾于一日连进二剂，其嗽顿止（此方可为治虚嗽良方），吐血证亦遂愈。数日后，觉血气上潮，肺复作痒而嗽，因此又复吐血。自言夜间睡时，常作生气恼怒之梦，怒极或梦中哭泣，醒后必然吐血。据所云云，其肝气必然郁遏，遂改用舒肝（连翘薄荷不可多用）泻肝（龙胆楝子）之品，而以养肝（柏子仁生阿胶）镇肝（生龙骨生牡蛎）之药辅之，数剂病稍轻减。而犹间作恼怒之梦，梦后仍复吐血。欲辞不治，病家又信服难却。再四踌躇，恍悟平肝之药，以桂为最要，肝属木，木得桂则枯也（以桂作钉钉树，其树立枯），而单用之则失于热。降胃止血之药，以大黄为最要（观《金匮》治吐衄有泻心汤重用大黄可知），胃气不上逆，血即不逆行也，而单用之又失于寒。若二药并用，则寒热相济，性归和平，降胃平肝，兼顾无遗。况俗传方，原有用此二药为散，治吐血者，用于此证当有捷效。而再以重坠之药辅之，则力专下行，其效当更捷也。遂用大黄、肉桂细末各一钱和匀，更用生赭石细末煎汤送下，吐血顿愈，恼怒之梦，亦从此不作。后又遇吐血者数人，投以此方，皆随手奏效。至其人身体壮实而暴得吐血者，又少变通其方：大黄、肉桂细末各用钱半，将生赭石细末六钱与之和匀，分三次服，白开水送下，约点半钟服一次。", "19558": "堂兄××，年五旬，得吐血证，延医治疗不效。脉象滑数，摇摇有动象，按之不实。时愚在少年，不敢轻于疏方，因拟此便方，煎汤两大碗，徐徐当茶温饮之，当日即见愈，五六日后病遂脱然。自言未饮此汤时，心若虚悬无著，既饮后，觉药力所至，若以手按心，使复其位，此其所以愈也。", "19559": "曾治一童子，年十五，大便下血，数月不愈，所下者若烂炙，杂以油膜，医者诿谓不治。后愚诊视其脉，弦数无力。俾用生山药轧细作粥，调血余炭六七分服之，日二次，旬日全愈。", "19560": "××又谓：「龙骨、牡蛎能收敛上溢之热，使之下行，而上溢之血，亦随之下行归经。至萸肉为补肝之妙药，凡因伤肝而吐血者，萸肉又在所必需也。且龙骨、牡蛎之功用神妙无穷。即脉之虚弱已甚，日服补药毫无起象，或病虚极不受补者，投以大剂龙骨、牡蛎，莫不立见功效，余亦不知其何以能然也。」愚曰：人身阳之精为魂，阴之精为魄。龙骨能安魂，牡蛎能强魄。魂魄安强，精神自足，虚弱自愈也。是龙骨、牡蛎，固为补魂魄精神之妙药也。", "19561": "又治本村表弟张×，年三十许，或旬日，或浃辰之间，必吐血数口，浸至每日必吐，亦屡治无效。其脉近和平，微有芤象，亦治以此方，三剂全愈。后又将此方加三七细末三钱，煎药汤送服，以治咳血吐血久不愈者，约皆随手奏效。若遇吐血之甚者，宜再加赭石五六钱，与此汤前三味同煎汤，送服三七细末更效。", "19562": "一人，年四十七，素患吐血。医者谓其虚弱，俾服补药，连服十余剂，觉胸中发紧，而血益不止。后有人语以治吐血便方，大黄、肉桂各五分轧细，开水送服，一剂血止。然因从前误服补药，胸中常觉不舒，饮食减少，四肢酸懒无力。愚诊之，脉似沉牢，知其膈上瘀血为患也。俾用鸭蛋子五十粒去皮，糖水送服，日两次，数日而愈。", "19563": "心因热怔忡者，酌加生地数钱，若脉沉迟无力者，其怔忡多因胸中大气下陷，详观拙拟升陷汤后跋语及诸案自明治法。", "19564": "西人曰：人身心肺关系尤重，与脑相等。凡关系重者、护持之尤谨，故脑则有头额等八骨以保护之，而心肺亦有胸胁诸骨以保护之。心肺体质相连，功用亦相倚赖，心之功用关系全体，心病则全体皆受害，心之重如此。然论其体质，不过赤肉所为，其能力专主舒缩，以行血脉。有左右上下四房；左上房主接肺经赤血；右上房主接周身回血；左下房主发赤血，运行周身；右下房主接上房回血过肺，更换赤血而回左上房；左上房赤血，落左下房入总脉管，以养全体；右上房回血，落右下房上注于肺，以出炭气而接养气。故人一身之血，皆经过于心肺。心能运血周流一身，无一息之停，即时接入，即时发出，其跳跃即其逼发也，以时辰表验试，一睯眤（即一分钟）跳七十五次，每半时跳四千五百次，一昼夜计跳十万八千次。然平人跳不自觉，若觉心跳即是心经改易常度。心房之内左厚于右，左下房厚于右下房几一倍，盖左房主接发赤血，功用尤劳，故亦加厚也。心位在胸中居左，当肋骨第四至第七节，尖当肋骨第五第六之间，下于乳头约一寸至半寸，横向胸骨。病则自觉周遭皆跳，凡心经本体之病，或因心房变薄变厚，或心房之门有病，或夹膜有病，或总管有病。亦如眼目之病，或在明角罩，或在瞳人，或在睛珠，非必处处皆病也。大概心病左多于右因左房功用尤劳故耳。心病约有数端：一者，心体变大，有时略大，或大过一半。因心房之户，有病拦阻，血出入不便，心舒缩之劳过常度。劳多则变大，亦与手足过劳则肿大之理相同。大甚，则逼血舒缩之用因之不灵矣。一者，心房门户变小、或变大、或变窄、或变阔，俱为非宜。盖心血自上房落下房之门，开张容纳血入后，门即翕闭，不令血得回旋上出。其自下房入总管处亦有门，血至则开张使之上出，血出后门即翕闭，不令血得下返。若此处太窄太小，则血不易出。太大太阔，则血逼发不尽，或已出复返，运行不如常度矣。再者心跳：凡无病之人心跳每不自觉。若因病而跳时时自觉，抚之或觉动。然此证有真有假：真者心自病而跳也，或心未必有病，但因身虚而致心跳，亦以真论；若偶然心跳，其人惊惧，防有心病，其实心本无病，即心跳亦暂时之事，是为假心跳证，医者均须细辨。凡心匀跳无止息，侧身而卧，可左可右，呼吸如常，大概心自不病。所虑跳跃不定，或三四次一停，停后复跳不能睡卧，左半身著床愈觉不安，当虑其门户有病，血不回运如常。有停滞妄流而为膨胀者，有累肺而咳嗽、难呼吸或喘者，有累脑而昏蒙头疼，中风慌怯者，有累肝而血聚积满溢者，有累胃不易消化，食后不安，心更跳者，皆心病之关系也。若胸胁骨之下有时动悸，人或疑为心跳，其实因胃不消化、内有风气，与心跳病无涉，虚弱人及妇女患者最多，略服补胃及微利药可也。", "19565": "按：西人论心跳证有真假，真者手扪之实觉其跳，假者手扪之不觉其跳。其真跳者又分两种：一为心体自病，若心房门户变大小窄阔之类，可用定心汤，将方中乳香、没药皆改用三钱，更加当归、丹参各三钱；一为心自不病，因身弱而累心致跳，当用治劳瘵诸方治之。至假心跳即怔忡证也，其收发血脉之动力，非大于常率，故以手扪之不觉其跳。特因气血虚而神明亦虚，即心之寻常舒缩，徐徐跳动，神明当之，亦若有冲激之势，多生惊恐，此等证治以定心汤时，磨取铁锈水煎药更佳。至于用铁锈之说，不但如西人之说，取其能补血分，实借其镇重之力以安心神也。载有一味铁养汤，细观方后治验诸案，自知铁锈之妙用。惟怔忡由于大气下陷者，断不宜用。", "19566": "一媪，年五十余，累月不能眠，屡次服药无效。诊其脉有滑象，且其身形甚丰腴。知其心下停痰也。为制此汤，服两剂而愈。", "19567": "一妇人，年三十许，一月之间未睡片时，自言倦极仿佛欲睡，即无端惊恐而醒。诊其脉左右皆有滑象，遂用苦瓜蒂十枚，焙焦轧细，空心时开水送服，吐出胶痰数碗，觉心中异常舒畅，于临眠之先又送服熟枣仁细末二钱，其夜遂能安睡。后又调以利痰养心安神之药，连服十余剂，其证永不反复矣。", "19568": "治癫狂失心，脉滑实者。", "19569": "痰脉多滑，然非顽痰也。愚治此证甚多。凡癫狂之剧者，脉多瘀塞，甚或六脉皆不见，用开痰药通之，其脉方出，以是知顽痰之能闭脉也。", "19570": "族家嫂，年六旬。夜间忽然呕吐头疼，心中怔忡甚剧，上半身自汗。其家人以为霍乱证。诊其脉，关前浮洪，摇摇而动。俾急磨浓铁锈水，煎汤服下即愈。", "19571": "友人韩××曾治一人，当恼怒之后，身躯忽然后挺，气息即断，一日数次。韩××诊其脉，左关虚浮。遂投以萸肉（去净核）、龙骨、牡蛎（皆不用煅）、白芍诸药，用三家磨刀水煎之，一日连服二剂，病若失。", "19572": "（原案一）己巳端阳前，友人黄××幼子，生六月，头身胎毒终未愈。禀质甚弱，忽肝风内动，抽掣绵绵不休。囟门微凸，按之甚软，微有赤色。指纹色紫为爪形。目睛昏而无神，或歪。脉浮小无根。此因虚气化不固，致肝阳上冲脑部扰及神经也。黄××云：此证西医已诿为不治，不知尚有救否？答曰：此证尚可为，听吾用药，当为竭力治愈。遂先用定风丹三分，水调灌下。继用生龙骨、生牡蛎、生石决明以潜其阳；钩藤钩、薄荷叶、羚羊角（锉细末三分）以熄其风；生箭耆、生山药、山萸肉、西洋参以补其虚；清半夏、胆南星、粉甘草以开痰降逆和中。共煎汤多半杯，调入定风丹三分，频频灌之。二剂肝风止，又增损其方，四剂全愈。", "19573": "（原案二）天津聂姓幼子，生七月，夜间忽患肝风，抽动喘息，不知啼。时当仲夏，天气亢旱燥热。察其风关、气关纹红有爪形，脉数身热，知系肝风内动。急嘱其乳母，将小儿置床上，不致怀抱两热相并。又嘱其开窗，以通空气。先用急救回生丹吹入鼻中，以镇凉其脑系。遂灌以定风丹三分。又用薄荷叶、黄菊花、钩藤钩、栀子、羚羊角以散风清热，生龙骨、生牡蛎、生石决明以潜阳镇逆，天竹黄、牛蒡子、川贝母以利痰定喘。将药煎好，仍调入定风丹三分，嘱其作数次灌下，勿扰其睡。嗣来信，一剂风熄而病愈矣。", "19574": "慢惊风，不但形状可辨，即其脉亦可辨。族侄××七八岁时，疟疾愈后，忽然吐泻交作。时霍乱盛行，其家人皆以为霍乱证。诊其脉弦细而迟，六脉皆不闭塞。愚曰：此非霍乱。吐泻带有黏涎否？其家人谓偶有带时。愚曰：此寒痰结胸，格拒饮食，乃慢惊风将成之兆也。投以逐寒荡惊汤、加味理中地黄汤各一剂而愈。", "19575": "又：有状类急惊，而病因实近于慢惊者。一童子，年十一二，咽喉溃烂。医者用吹喉药吹之，数日就愈。忽然身挺，四肢搐搦，不省人事，移时始醒，一日数次。诊其脉甚迟濡。询其心中，虽不觉凉，实畏食凉物。其呼吸，似觉短气。时当仲夏，以童子而畏食凉，且征以脉象病情，其为寒痰凝结，瘀塞经络无疑。投以《伤寒论》白通汤，一剂全愈。", "19576": "中风之证，有偏寒者，有偏热者，有不觉寒热者。拙拟此方治中风之无甚寒热者也。若偏热者，宜《金匮》风引汤加减（干姜、桂枝宜减半）。若偏寒者，愚别有经验治法。曾治一媪，年五十许，于仲冬忽然中风昏倒，呼之不应，其胸中似有痰涎壅滞，大碍呼吸。诊其脉，微细欲无，且迟缓，知其素有寒饮，陡然风寒袭入，与寒饮凝结为恙也。急用胡椒三钱捣碎，煎两三沸，取浓汁多半茶杯灌之，呼吸顿觉顺利。继用干姜六钱，桂枝尖、当归各三钱，连服三剂，可作呻吟，肢体渐能运动，而左手足仍不能动。又将干姜减半，加生黄耆五钱，乳香、没药各三钱，连服十余剂，言语行动遂复其常。", "19577": "若其人元气不虚，而偶为邪风所中，可去人参，加蜈蚣一条、全蝎一钱。若其证甚实，而闭塞太甚者，或二便不通，或脉象郁涩，可加生大黄数钱，内通外散，仿防风通圣散之意可也。", "19578": "徐灵胎曾治一人，平素多痰，手足麻木，忽昏厥遗尿、口噤手拳、痰声如锯。医者进参附、熟地等药，煎成末服。诊其脉，洪大有力，面赤气粗。此乃痰火充实，诸窍皆闭，服参附立危。遂以小续命汤去桂附，加生军一钱为末，假称他药纳之，恐旁人之疑骇也。三剂而有声，五剂而能言。然后以养血消痰之药调之，一月后，步履如初。此案与愚所治之案对观，则凉热之间昭然矣。又遗尿者多属虚，而此案中之遗尿则为实，是知审证者，不可拘于一端也。然真中风证极少，类中风者极多，中风证百人之中真中风不过一二人。审证不确即凶危立见，此又不可不慎也。", "19579": "热者加知母，凉者加附子，脉滑有痰者加半夏。", "19580": "湖北张某，患历节风证，西医名偻麻质斯，服其药年余无效。步履艰难，天未凉即著皮裤。诊其脉，浮数有力，知为经络虚而有热之象。遂用加味黄耆五物汤，遵注热者加知母，又加生薏米、鲜桑枝、牛膝、木通。服一剂觉轻减，三剂离杖，五剂痊愈。近年用此方治痛风、历节证，愈者甚多。若无热者，即用书中原方，亦甚效验。", "19581": "盖《神农本草经》原谓黄耆主大风，方中重用黄耆一两，又有他药以为之佐使，宜其风证皆可治也。若已中风抽掣者，宜加全蜈蚣两条。若更因房事不戒以致中风抽风者，宜再加真鹿角胶三钱（另煎兑服），独活一钱半。若脉象有热者，用此汤时，知母、天冬皆可酌加。", "19582": "治内中风证（亦名类中风，即西人所谓脑充血证），其脉弦长有力（即西医所谓血压过高），或上盛下虚，头目时常眩晕，或脑中时常作疼发热，或目胀耳鸣，或心中烦热，或时常噫气，或肢体渐觉不利，或口眼渐形歪斜，或面色如醉，甚或眩晕，至于颠仆，昏不知人，移时始醒，或醒后不能复原，精神短少，或肢体痿废，或成偏枯。", "19583": "心中热甚者，加生石膏一两。痰多者，加胆星二钱。尺脉重按虚者，加熟地黄八钱、净萸肉五钱。大便不实者，去龟板、赭石，加赤石脂（喻嘉言谓石脂可代赭石）一两。", "19584": "风名内中，言风自内生，非风自外来也。《内经》谓「诸风掉眩，皆属于肝」。盖肝为木脏，木火炽盛，亦自有风。此因肝木失和风自肝起。又加以肺气不降，肾气不摄，冲气胃气又复上逆，于斯，脏腑之气化皆上升太过，而血之上注于脑者，亦因之太过，致充塞其血管而累及神经。其甚者，致令神经失其所司，至昏厥不省人事。西医名为脑充血证，诚由剖解实验而得也。是以方中重用牛膝以引血下行，此为治标之主药。而复深究病之本源，用龙骨、牡蛎、龟板、芍药以镇熄肝风，赭石以降胃降冲，玄参、天冬以清肺气，肺中清肃之气下行，自能镇制肝木。至其脉之两尺虚者，当系肾脏真阴虚损，不能与真阳相维系。其真阳脱而上奔，并挟气血以上冲脑部，故又加熟地、萸肉以补肾敛肾。从前所拟之方，原止此数味。后因用此方效者固多，间有初次将药服下转觉气血上攻而病加剧者，于斯加生麦芽、茵陈、川楝子即无斯弊。盖肝为将军之官，其性刚果，若但用药强制，或转激发其反动之力。茵陈为青蒿之嫩者，得初春少阳生发之气，与肝木同气相求，泻肝热兼舒肝郁，实能将顺肝木之性。麦芽为谷之萌芽，生用之亦善将顺肝木之性使不抑郁。川楝子善引肝气下达，又能折其反动之力。方中加此三味，而后用此方者，自无他虞也。心中热甚者，当有外感，伏气化热，故加石膏。有痰者，恐痰阻气化之升降，故加胆星也。", "19585": "内中风之证，曾见于《内经》。而《内经》初不名为内中风，亦不名为脑充血，而实名之为煎厥、大厥、薄厥。今试译《内经》之文以明之。《内经》脉解篇曰：「肝气当治而未得，故善怒，善怒者名曰煎厥。」盖肝为将军之官，不治则易怒，因怒生热，煎耗肝血，遂致肝中所寄之相火，掀然暴发，挟气血而上冲脑部，以致昏厥。此非因肝风内动，而遂为内中风之由来乎？", "19586": "至清中叶王勋臣出，对于此证，专以气虚立论。谓人之元气，全体原十分，有时损去五分，所余五分，虽不能充体，犹可支持全身。而气虚者经络必虚，有时气从经络虚处透过，并于一边，彼无气之边，即成偏枯。爰立补阳还五汤，方中重用黄耆四两，以峻补气分，此即东垣主气之说也。然王氏书中，未言脉象何如。若遇脉之虚而无力者，用其方原可见效。若其脉象实而有力，其人脑中多患充血，而复用黄耆之温而升补者，以助其血愈上行，必至凶危立见，此固不可不慎也。前者邑中某人，右手废不能动，足仍能行。其孙出门，遇一在津业医者甫归，言此证甚属易治，遂延之诊视。所立病案言脉象洪实，已成痪证无疑。其方仿王氏补阳还五汤，有黄耆八钱。服药之后，须臾昏厥不醒矣。夫病本无性命之忧，而误服黄耆八钱，竟至如此，可不慎哉！", "19587": "刘××丁卯来津后，其脑中常觉发热，时或眩晕，心中烦躁不宁，脉象弦长有力，左右皆然，知系脑充血证。盖其愤激填胸，焦思积虑者已久，是以有斯证也。为其脑中觉热，俾用绿豆实于囊中作枕，为外治之法。又治以镇肝熄风汤，于方中加地黄一两，连服数剂，脑中已不觉热。遂去川楝子，又将生地黄改用六钱，服过旬日，脉象和平，心中亦不烦躁，遂将药停服。", "19588": "又：天津于氏所娶新妇，过门旬余，忽然头疼。医者疑其受风，投以发表之剂，其疼陡剧，号呼不止。延愚为之诊视。其脉弦硬而长，左部尤甚。知其肝胆之火上冲过甚也。遂投以镇肝熄风汤，加龙胆草三钱，以泻其肝胆之火。一剂病愈强半，又服两剂，头已不疼，而脉象仍然有力。遂去龙胆草，加生地黄六钱，又服数剂，脉象如常，遂将药停服。", "19589": "治身形软弱，肢体渐觉不遂，或头重目眩，或神昏健忘，或觉脑际紧缩作疼。甚或昏仆移时苏醒致成偏枯，或全身痿废，脉象迟弱，内中风证之偏虚寒者（肝过盛生风，肝虚极亦可生风），此即西人所谓脑贫血病也。久服此汤当愈。", "19590": "脑充血者，其脑中之血过多，固能伤其脑髓神经。脑贫血者其脑中之血过少，又无以养其脑髓神经。是以究其终极，皆可使神经失其所司也。古方有补血汤，其方黄耆、当归同用，而黄耆之分量，竟四倍于当归，诚以阴阳互为之根，人之气壮旺者，其血分自易充长。况人之脑髓神经，虽赖血以养之，尤赖胸中大气上升以斡旋之。是以《内经》谓「上气不足，脑为之不满，耳为之苦鸣，头为之倾，目为之眩。」所谓上气者，即胸中大气上升于脑中者也。因上气不足，血之随气而注于脑者必少，而脑为之不满，其脑中贫血可知。且因上气不足，不能斡旋其神经，血之注于脑者少，无以养其神经，于是而耳鸣、头倾、目眩，其人可忽至昏仆可知。由此知因脑部贫血以成内中风证者，原当峻补其胸中大气，俾大气充足，自能助血上升，且能斡旋其脑部，使不至耳鸣、头倾、目眩也。是以此方不以当归为主药，而以黄耆为主药也。用龙眼肉者，因其味甘色赤，多含津液，最能助当归以生血也。用鹿角胶者，因鹿之角原生于头顶督脉之上，督脉为脑髓之来源，故鹿角胶之性善补脑髓。凡脑中血虚者，其脑髓亦必虚，用之以补脑髓，实可与补血之药相助为理也。用丹参、乳香、没药者，因气血虚者，其经络多瘀滞，此于偏枯痿废亦颇有关系，加此通气活血之品，以化其经络之瘀滞，则偏枯痿废者自易愈也。用甘松者，为其能助心房运动有力，以多输血于脑，且又为调养神经之要品，能引诸药至脑以调养其神经也。用麝香、梅片者，取其香能通窍以开闭也。用制过马钱子者，取其能𥆧动脑髓神经使之灵活也。", "19591": "高姓臾，年过六旬，渐觉两腿乏力，浸至时欲眩仆，神昏健忘。恐成痿废，求为诊治。其脉微弱无力。为制此方服之，连进十剂，两腿较前有力，健忘亦见愈，而仍有眩晕之时。再诊其脉，虽有起色，而仍不任重按。遂于方中加野台参、天门冬各五钱，威灵仙一钱，连服二十余剂始愈。用威灵仙者，欲其运化参、耆之补力，使之灵活也。", "19592": "热者，加生石膏数钱，或至两许。寒者去知母，加乌附子数钱。筋骨受风者，加明天麻数钱。脉弦硬而大者，加龙骨、牡蛎各数钱，或更加山萸肉亦佳。骨痿废者，加鹿角胶、虎骨胶各二钱（另炖同服）。然二胶伪者甚多，若恐其伪，可用续断、菟丝子各三钱代之。手足皆痿者，加桂枝尖二钱。", "19593": "痿证之大旨，当分为三端：有肌肉痹木，抑搔不知疼痒者。其人或风寒袭入经络，或痰涎郁塞经络，或风寒痰涎，互相凝结经络之间，以致血脉闭塞，而其原因，实由于胸中大气虚损。盖大气旺，则全体充盛，气化流通，风寒痰涎，皆不能为恙。大气虚，则腠理不固，而风寒易受，脉管湮淤，而痰涎易郁矣；有周身之筋拘挛，而不能伸者。盖人身之筋，以宗筋为主，而能荣养宗筋者，阳明也。其人脾胃素弱，不能化谷生液，以荣养宗筋，更兼内有蕴热以铄耗之，或更为风寒所袭，致宗筋之伸缩自由者，竟有缩无伸，浸成拘挛矣；有筋非拘挛，肌肉非痹木，惟觉骨软不能履地者，乃骨髓枯涸，肾虚不能作强也。", "19594": "方中用黄耆以补大气，白术以健脾胃，当归、乳香、没药以流通血脉，灵仙以祛风消痰，恐其性偏走泄，而以人参之气血兼补者佐之，干姜以开气血之痹，知母以解干姜、人参之热，则药性和平，可久服而无弊。其阳明有实热者，加石膏以清阳明之热，仿《金匮》风引汤之义也。营卫经络有凝寒者，加附子以解营卫经络之寒，仿《金匮》近效术附汤之义也。至其脉弦硬而大，乃内风煽动，真气不固之象，故加龙骨、牡蛎以熄内风敛真气。骨痿者加鹿胶、虎胶取其以骨补骨也。筋骨受风者，加明天麻取其能搜筋骨之风，又能补益筋骨也。若其痿专在于腿，可但用牛膝以引之下行。若其人手足并痿者，又宜加桂枝兼引之上行。", "19595": "治肢体受凉疼痛，或有凝寒阻遏血脉，麻木不仁。", "19596": "一叟，年六十余得膈证，向愚求方。自言犹能细嚼焦脆之物，用汤水徐徐送下，然一口咽之不顺，即呕吐不能再食，且呕吐之时，带出痰涎若干。诊其脉关后微弱，关前又似滑实，知其上焦痰涎壅滞也。用此汤加邑武帝台所产旋覆花二钱，连服四剂而愈。", "19597": "一人，年四十六，素耽叶子戏，至废寝食。初觉有气上冲咽喉，浸至妨碍饮食，时或呕吐不能下行。其脉弦长而硬，左右皆然。知系冲气挟胃气上冲。治以此汤，加武帝台旋覆花二钱、生芡实四钱，降其冲逆之气而收敛之，连服十剂而愈。", "19598": "族家姑，年五旬有六，初觉饮食有碍，后浸增重，惟进薄粥，其脉弦细无力。盖生平勤俭持家，自奉甚薄，劳心劳力又甚过。其脉之细也，因饮食菲薄而气血衰，其脉之弦也，因劳心过度而痰饮盛也。姑上有两姊，皆以此疾逝世，气同者其病亦同，惴惴自恐不愈。愚毅然以为可治，投以此汤，加白术二钱、龙眼肉三钱，连服十余剂全愈。", "19599": "堂侄女，年四十八岁，素羸弱多病。因自理家务，劳心过度，恒彻夜不寐。于癸卯夏日得膈证。时愚远出，遂延他医调治，屡次无效。及愚旋里，病势已剧。其脉略似滑实，重按无力。治以此汤，加龙眼肉五钱，两剂见轻，又服十余剂全愈。", "19600": "奉天北镇县萧叟，年六十七岁，得膈证延医治不愈。迁延五六月，病浸加剧，饮水亦间有难下之时。来院求为诊治。其脉弦长有力，右部尤甚。知其冲气上冲过甚，迫其胃气不下降也。询其大便，干燥不易下，多日不行，又须以药通之。投以参赭培气汤，赭石改用一两。数剂后，饮食见顺，脉亦稍和，觉胃口仍有痰涎杜塞。为加清半夏三钱，连服十剂，饮食大顺，脉亦复常，大便亦较易。遂减赭石之半，又服数剂，大便一日两次。遂去赭石、柿霜饼、当归、知母，加于术三钱，数剂后自言，觉胃中消化力稍弱，此时痰涎已清，又觉胃口似有疙瘩，稍碍饮食之路。遂将于术改用六钱，又加生鸡内金（捣细）二钱，佐于术以健运脾胃，即借以消胃口之障碍，连服十余剂全愈。", "19601": "友人吴××治姜姓叟，年六十余，得膈食证。屡次延医调治，服药半载，病转增进。吴××投以参赭培气汤，为其脉甚弦硬，知其冲气上冲，又兼血液枯少也，遂加生芡实以收敛冲气，龙眼肉以滋润血液，一剂能进饮食，又连服七八剂，饮食遂能如常。", "19602": "邱××之女，年十五，天癸已至，因受惊而经闭。两阅月，发现心热、心跳、膨胀等证，经医治疗未效，更添翻胃吐食、便燥、自汗等证。又经两月，更医十数，病益剧。适友人介绍为之诊视，脉浮数而濡，尺弱于寸，面色枯槁，肢体消瘦，不能起床；盖两月间食入即吐，或俟半日许亦必吐出，不受水谷之养，并灼热耗阴，无怪其支离若是也。思之再四，此必因受惊气乱而血亦乱，遂至遏其生机，且又在童年，血分未充，即不能应月而潮，久之不下行，必上逆，气机亦即上逆，况冲为血海，隶属阳明，阳明有升无降，冲血即随之上逆，瘀而不行，以至作灼作胀。其心跳者，为上冲之气血所扰也。其出汗吐食者，为上冲之气血所迫也。其津液因汗吐过多而消耗，所以大便干燥也。势非降逆、滋阴，镇心、解瘀之药并用不可。查参赭镇气汤及参赭培气汤二方，实为治斯证之津梁，爰即二方加减，赭石两半，当归、净萸肉、龙骨、牡蛎各五钱，白芍、肉苁蓉、党参、天冬、生鸡内金各三钱，磨取铁锈之水煎服。一剂病似觉甚，病家哗然，以为药不对证，欲另延医。惟介绍人主持甚力，勉又邀生再诊，此中喧变生固未之知也。既诊脉如故，决无病进之象。后闻有如此情形，生亦莫解。因反复思之，恍悟：此必胃虚已极，兼胃气上逆过甚，遽投以如此重剂，其胃虚不能运化，气逆更多冲激，想有一番瞑眩，故病似加重也。于斯将原方减半，煎汤一盅，又分两次温服下，并送服柿霜三钱。其第一次服，仍吐药一半，二次即不吐，服完此剂后，略进薄粥，亦未吐，病家始欢然相信。又连服三剂，汗与吐均止，心跳膨胀亦大见轻。惟灼热犹不甚减，遂去净萸肉、龙骨、牡蛎，加生地、玄参各四钱，服五剂后，灼热亦愈强半。如此加减服之，一月后遂能起床矣。嘱其仍守服原方，至诸病全愈后可停药勿服，月事至期亦当自至也。", "19603": "吐后口舌干燥，思饮水者热也。吐后口舌湿润，不思饮水者凉也。若呕吐既久，伤其津液，虽有凉者亦可作渴，又当细审其脉，滑疾为热，弦迟为凉。滑而无力，为上盛下虚，上则热而下或凉。弦而有力，为冲胃气逆，脉似热却非真热。又当问其所饮食者，消化与否，所呕吐者，改味与否，细心询问体验，自能辨其凉热虚实不误也。", "19604": "朱砂能解心中窜入之毒，且又重坠，善止呕吐，俾服药后不致吐出。此方中冰片，宜用樟脑炼成者。因樟脑之性，原善振兴心脏，通活周身血脉，尤善消除毒菌。特其味稍劣，炼之为冰片，味较清馥，且经炼，而其力又易上升至脑，以清脑中之毒也。薄荷冰善解虎列拉之毒，西人屡发明之。且其味辛烈香窜，无窍不通，无微不至，周身之毒皆能扫除。矧与冰片，又同具发表之性，服之能作汗解，使内蕴之邪由汗透出。且与冰片皆性热用凉，无论症之因凉因热，投之咸宜也。粉甘草最善解毒，又能调和中宫，以止吐泻。且又能调和冰片、薄荷冰之气味，使人服之不致过于苛辣也。", "19605": "霍乱之证，西人所谓虎列拉也。因空气中有时含有此毒，而地面积秽之处，又酿有毒气与之混合（观此证起点多在大埠不洁之处可知），随呼吸之气入肺，由肺传心胞（即心肺相连之脂膜），由心胞传三焦（上焦心下膈膜，中焦包脾连胃脂膜，下焦络肠包肾脂膜），为手厥阴、少阳脏腑之相传。然其毒入三焦，其人中气充盛，无隙可乘，犹伏而不动。有时或饮食过量，或因寒凉伤其脾胃，将有吐泻之势，毒即乘虚内袭，盘据胃肠，上下不通，遂挥霍撩乱，而吐泻交作矣。吐泻不已，其毒可由肠胃而入心，更由心而上窜于脑，致脑髓神经与心俱病。左心房输血之力与右心房收血之力，为之顿减，是以周身血脉渐停，而通体皆凉也。其证多发于秋际者，因此毒气酿成多在夏令。人当暑热之时，周身时时有汗，此毒之伏于三焦者，犹得随汗些些外出。迨至秋凉汗闭，其毒不得外出，是以蓄极而动，乘脾胃之虚而内攻也。故治此症者，当以解毒之药为主，以助心活血之药为佐，以调阴阳奠中土之药为使。爰拟此方，名之曰急救回生丹。", "19606": "一九二四年六月，友人杜××之母得霍乱证，上吐下泻，转筋腹疼，六脉闭塞。生诊视后，为开卫生防疫宝丹方，共研作粉，每次服一钱。服第一次，吐泻稍止。服第二次，病即痊愈。", "19607": "斯年初冬，邓××之儿媳得霍乱证，时已夜半，请为诊视。吐泻转筋，六脉皆无，心中迷乱，时作谵语。治以卫生防疫宝丹，初服仍吐，服至二次，脉即徐出而愈。", "19608": "以上二方，皆为治霍乱之要药矣。然彼以祛邪为主，此以扶正为主。诚以得此证者，往往因治不如法，致日夜吐泻不已，虚极将脱，危在目前。病势至此，其从前之因凉因热皆不暇深究，惟急宜重用人参以回阳，山药、芍药以滋阴，山萸肉以敛肝气之脱（此证吐泻之始肝木助邪侮土，吐泻之极而肝气转先脱），炙甘草以和中气之漓，此急救回阳汤所以必需也。用赭石者，不但取其能止呕吐，俾所服之药不致吐出，诚以吐泻已久，阴阳将离，赭石色赤入心，能协同人参，助心气下降。而方中山药，又能温固下焦，滋补真阴，协同人参以回肾气之下趋，使之上行也。用朱砂且又送以童便者，又以此时百脉闭塞，系心脏为毒气所伤，将熄其鼓动之机，故用朱砂直入心以解毒，又引以童便使毒气从尿道泻出，而童便之性又能启发肾中之阳上达，以应心脏也。是此汤为回阳之剂，实则交心肾和阴阳之剂也。服此汤后，若身温脉出，觉心中发热有烦躁之意者，宜急滋其阴分，若玄参、生芍药之类，加甘草以和之，煎一大剂，分数次温饮下。此《伤寒论》太阳篇，先用甘草干姜汤继用甘草芍药汤之法也。", "19609": "霍乱之证，有实热者居多，其真寒凉者，不过百中之一二。即百脉闭塞，周身冰冷，但其不欲覆被，思饮凉水，即不可以凉断，当先少少与以凉水，若饮后病增重者，其人虽欲复饮，而不至急索者，凉水可勿与也。若饮后病不增重，须臾不与，有不能忍受之状，可尽量与之，任其随饮随吐，借凉水将内毒换出，亦佳方也。曾遇有恣饮凉水而愈者，问之，言当病重之时，若一时不饮凉水，即觉不能复活，则凉水之功用可知矣。然凉水须用新汲井泉水方效，无井泉水处，可以冰水代之，或吞服小冰块亦佳。", "19610": "王孟英曰：鸡矢白散，为《金匮》治霍乱转筋入腹之方。愚仿其意，拟得蚕矢汤，治霍乱转筋、腹疼、口渴、烦躁，危急之证甚效。方用晚蚕砂、木瓜各三钱，生薏仁、大豆芽（如无可代以生麦芽）各四钱，川黄连、炒山栀各二钱，醋炒半夏、酒炒黄芩、吴茱萸各一钱，以阴阳水煎，稍凉，徐徐服之。丁酉八九月间，吾杭盛行霍乱转筋之证。有沈氏妇者，夜深患此，继即音哑肢寒。比晓，其夫皇皇求为救治。诊其脉弦细以涩，两尺如无，口极渴而沾饮即吐不已，腓坚硬如石，其时疼楚异常。因拟此方治之，徐徐凉饮，药入口竟得不吐。外以好烧酒令人用力摩擦转筋坚硬之处，擦将一时许，其硬块始渐软散，而筋不转吐泻亦减。甫时复与前药半剂，夜间居然安寐矣。后治相类者多人，悉以是法获效。", "19611": "陆九芝曰：霍乱一证，有寒有热，热者居其九，寒者居其一。凡由高楼大厦，乘凉饮冷而得之者，仲景则有理中、四逆诸方，后世亦有浆水、大顺、复元、冷香饮子诸方，病多属寒，药则皆宜热。若夫春分以后，秋分以前，少阳相火，少阴君火，太阴湿土，三气合行其令。天之热气则下降，地之湿气则上腾，人在气交之中，清气在阴，浊气在阳，阴阳反戾，清浊相干，气乱于中，而上吐下泻。治此者，宜和阴阳，分清浊，以定其乱，乱定即无不愈。此则病非寒也，而亦非尽用寒药也。即如薷藿、平陈、胃苓等汤习用之剂，亦皆温通，特不用姜附丁萸之大辛大热者耳。又有不吐不泻而挥霍撩乱者，则多得之饱食之后。凡夏月猝然冒暑，惟食填太阴，亦曰饱食填息。此证为病最速，为祸最酷，而人多忽之。即有知者，亦仅以停食为言，绝不信其为闭证之急者。闭则手足肢冷，六脉俱伏，甚则喜近烈日。此乃邪闭而气道不宣，其畏寒也正其热之甚也。此等证，只欠一吐法耳。自吐法之不讲，本属一吐即愈之病，而竟不知用也。此外更有四肢厥逆，甚至周身如冰，而竟不恶寒，反有恶热者，此更是内真热，外假寒，即厥阴中热深厥深之象。岂独不可用四逆、理中，即姜汤、米饮及五苓散中之桂枝，亦不可用。而且宜苦寒之剂，佐以挑痧、刮痧等法，刺出其恶血以泄热毒者。同治壬戌，江苏沪渎，时疫盛行，绵延而至癸亥。余尝以石膏、芩、连，清而愈之者，则暑湿热之霍乱也。以凉水调胆矾吐而愈之者，则饱食填息之霍乱也。其肢皆冷，而其脉皆伏，维时大医，竞用丁萸桂附，日误数人，而竟不知改图，岂不深可惜哉。", "19612": "霍乱之证，宜兼用外治之法，以辅药饵所不逮。而外治之法，当以针灸为最要。至应针之处，若十宣、中脘、尺泽、足三里、阴陵、承山、太谿、太仓、太冲、公孙等穴（约略举之，未能悉数），习针灸者大抵皆知。惟督脉部分，有素髎穴，刺同身寸之三分出血，最为治霍乱之要著。凡吐泻交作，心中撩乱者，刺之皆效。诸针灸之书，皆未言其能治霍乱。世之能针灸者，间有知刺其处者，而或刺鼻准之尖，或刺鼻柱中间，又多不能刺其正穴。两鼻孔中间为鼻柱，《内经》王注，谓此穴在鼻柱之上端，则非鼻准之尖，及鼻柱中间可知。然刺未中其正穴者，犹恒有效验，况刺中其正穴乎。盖此穴通督脉，而鼻通任脉，刺此一处，则督、任二脉，可互相贯通，而周身之血脉，亦因之可贯通矣。", "19613": "又宜佐以刮痧之法。盖此证病剧之时，周身冰冷，回血管之血液凝滞不行。当用细口茶碗，将碗边一处少涂香油，两手执定其无油之处，先刮其贴脊两旁，脊椎上亦可轻刮，以刮处尽红为度。盖以脏腑之系皆连于脊，而诸脏腑腧穴，亦贴脊两旁，故以刮此处为最要。而刮时，又宜自上而下挨次刮之，可使毒气下行。次刮其胸与胁，次刮其四肢曲处（尺泽委中）及腿内外胻，至头额项肩，亦可用钱刮之。又当兼用放痧之法：将四肢回血管之血，用手赶至腿臂曲处，用带上下扎紧，于尺泽、委中两旁回血管，用扁针刺出其血，以助其血脉之流通，且又放出炭气，俾霍乱之毒菌，从此轻减也。", "19614": "一妇人，年三十许，泄泻数月。用一切治泻诸药皆不效。其脉不凉，亦非完谷不化。遂单用白术、枣肉，如法为饼，服之而愈。此证并不用鸡内金者，因鸡内金虽有助脾胃消食之力，而究与泻者不宜也。", "19615": "一妇人，年四十许。初因心中发热，气分不舒，医者投以清火理气之剂，遂泄泻不止。更延他医，投以温补之剂，初服稍轻，久服，则泻仍不止。一日夜四五次，迁延半载，以为无药可治。后愚为诊视，脉虽濡弱，而无弦数之象，知犹可治。但泻久身弱，虚汗淋漓，心中怔忡，饮食减少，踌躇久之，为拟此方，补脾兼补心肾。数剂泻止，而汗则加多。遂于方中加龙骨、牡蛎（皆不用煅）各六钱，两剂汗止，又变为漫肿。盖从前泻时，小便短少，泻止后，小便仍少，水气下无出路，故蒸为汗，汗止又为漫肿也。斯非分利小便，使水下有出路不可。特其平素常觉腰际凉甚，利小便之药，凉者断不可用。遂用此方，加椒目三钱，连服十剂全愈。", "19616": "门生吴××，年二十一。羸弱发热，脉象虚数，不能饮食。俾早晚服山药粥，加百布圣，晌午单服玄参三钱，煎汤服。如此数日，食量增加，发热亦愈，自此健壮。", "19617": "一娠妇，日发痫风。其脉无受娠滑象，微似弦而兼数。知阴分亏损，血液短少也。亦俾煮山药粥服之即愈。又服数次，永不再发。", "19618": "奉天郑××之女，年五岁。秋日为风寒所束，心中发热。医者不知用辛凉表散，而纯投以苦寒之药，连服十余剂，致脾胃受伤，大便滑泻，月余不止，而上焦之热益炽。医者皆辞不治，始求愚为诊视，其形状羸弱已甚，脉象细微浮数，表里俱热，时时恶心，不能饮食，昼夜犹泻十余次。治以此粥，俾随便饮之，日四五次，一次不过数羹匙，旬日全愈。", "19619": "河间刘××，年五十余岁。漏疮甚剧，屡治不痊，后兼泄泻不止，盖肠滑不固，故医药无灵。诊其脉甚小弱，渐已成痨。嘱其用薯蓣鸡子黄粥。一剂泻止。三服，精神焕发。十数日后，身体复原。此后凡遇虚泻久不愈者，用之屡收特效。", "19620": "一人，年五十余，素吸鸦片。当霍乱盛行之时，忽然心中觉疼、恶心呕吐、下痢脓血参半。病家惧甚，以为必是霍乱暴证。诊其脉毫无闭塞之象，惟弦数无力，左关稍实。愚曰：此非霍乱，乃下焦寒火交战，故腹中作疼，下痢脓血。上焦虚热壅迫，故恶心呕吐，实系痢证之剧者。遂投以白芍六钱，竹茹、清半夏各三钱，甘草、生姜各二钱，一剂呕吐即愈，腹疼亦轻，而痢独不愈，不思饮食。俾单用鸭蛋子五十粒，一日连服两次，病若失。审斯，鸭蛋子不但善理下焦，即上焦虚热，用之亦妙，此所以治噤口痢而有捷效也。", "19621": "一人，年四十八，资禀素弱，亦吸鸦片。于季秋溏泻不止。一日夜八九次，且带红色，心中怔忡，不能饮食。日服温补之药，分毫无效。延愚诊治，其脉左右皆微弱，而尺脉尤甚，知系下焦虚寒。为其便带红色，且从前服温补之药无效，俾先服鸭蛋子四十粒，泻愈其半，红色亦略减，思饮食。继用温补下焦之药煎汤，送服鸭蛋子三十粒，后渐减至十粒，十剂全愈。盖此证虽下焦虚寒，而便带红色，实兼有痢证也。故单服鸭蛋子，而溏泻已减半。然亦足征鸭蛋子虽善清热化瘀，而实无寒凉开破之弊，洵良药也。", "19622": "沧州友人滕××，壬寅之岁，于中秋下赤痢，且多鲜血。医治两旬不愈。适愚他出新归。过访之，求为诊治。其脉象洪实，知其纯系热痢。遂谓之曰：此易治。买苦参子百余粒，去皮，分两次服下即愈矣。翌日愚复他出，二十余日始归。又访之，言曾遍问近处药坊，皆无苦参子。后病益剧，遣人至敝州取来，如法服之，两次果愈。后滕××旋里，其族人有适自奉天病重归来者，大便下血年余，一身悉肿，百药不效。滕××授以此方，如法服之，三次全愈。", "19623": "一人，年五十二，因大怒之后，中有郁热，又寝于冷屋之中，内热为外寒所束，愈郁而不散，大便下血。延医调治，医者因其得于寒凉屋中，谓系脾寒下陷，投以参、耆温补之药，又加升麻提之。服药两剂，病益增重，腹中切疼，常常后重，所便之物，多如烂炙。更延他医，又以为下元虚寒，而投以八味地黄丸，作汤服之，病益加重。后愚诊视，其脉数而有力，两尺愈甚。确知其毒热郁于肠中，以致肠中腐烂也。为拟此方，两剂而愈。", "19624": "一妇人，年五十许，素吸鸦片。又当恼怒之余，初患赤痢，滞下无度。因治疗失宜，渐至血液腐败，间如烂炙，恶心懒食，少腹切疼。其脉洪数，纯是热象。亦治以此汤，加知母、白头翁各四钱，煎汤服。又另取鸭蛋子六十粒、三七二钱，送服。每日如此服药两次，三日全愈。", "19625": "一媪，年六十一岁，于中秋痢下赤白，服药旋愈，旋又反复。如此数次，迁延两月。因少腹切疼，自疑寒凉，烧砖熨之。初熨时稍觉轻，以为对证。遂日日熨之，而腹中之疼益甚。昼夜呻吟，噤口不食。所下者痢与血水相杂，且系腐败之色。其脉至数略数，虽非洪实有力，实无寒凉之象。舌上生苔，黄而且厚。病人自谓下焦凉甚，若用热药温之疼当愈。愚曰：前此少腹切疼者，肠中欲腐烂也，今为热砖所熨而腹疼益甚，败血淋漓，则肠中真腐烂矣。再投以热药，危可翘足而待。病人亦似会悟，为制此方。因河间天水散（即六一散），原为治热痢之妙药，此方中重用滑石、甘草，故名之天水涤肠汤。连服四剂，疼止，痢亦见愈。减去滑石四钱，加赤石脂四钱，再服数剂，病愈十之八九。因上焦气微不顺，俾用鲜藕四两，切细丝煎汤，频频饮之，数日而愈。", "19626": "奉天王××，年四十许。己未孟秋，自郑州病归，先泻后痢，腹疼重坠，赤白稠黏，一日夜十余次。先入奉天东人所设医院中，东人甚畏此证，处以隔离所，医治旬日无效。遂出院归寓，求为诊治。其脉弦而有力，知其下久阴虚，肝胆又蕴有实热也。投以此汤，一剂痢愈。仍变为泻，日四五次，自言腹中凉甚。愚因其疾原先泻，此时痢愈又泻，且恒以温水袋自熨其腹，疑其下焦或有伏寒，遂少投以温补之药。才服一剂，又变为痢，下坠腹疼如故，惟次数少减。知其病原无寒，不受温补。仍改用通变白头翁汤。一剂痢又愈，一日犹泻数次。继用生山药一两，龙眼、莲子各六钱，生杭芍三钱，甘草、茯苓各二钱，又少加酒曲、麦芽、白蔻消食之品，调补旬日全愈。", "19627": "奉天李××，年近四旬。因有事，连夜废寝。陡然腹疼，继而泄泻，兼下痢。其痢赤多于白，上焦有热，不能饮食。其脉弦而浮，按之不实。先投以三宝粥方，腹疼与泻痢皆见轻，仍不能饮食。继用通变白头翁汤方，连服两剂，痢愈可进饮食，腹疼泄泻犹未全愈。后仍用三宝粥方，去鸭蛋子，日服两次，数日病全愈。", "19628": "己巳之岁，愚客居德州，有卢姓妇，年五十六。于季夏下痢赤白，迁延至仲冬不愈。延医十余人，服药百剂，皆无效验，亦以为无药可医矣。后求愚诊治，脉象微弱，至数略数，饮食减少，头目时或眩晕，心中微觉烦热，便时下坠作疼，然不甚剧。询其平素，下焦畏凉。是以从前服药，略加温补，上即烦热，略为清理，下又腹疼泄泻也。为拟此方，一日连服两次，其病遂愈。后旬余，因登楼受凉，旧证陡然反复，日下十余次，腹疼觉剧。其脉象微弱如前，至数不数。俾仍用山药粥，送服生硫黄末三分，亦一日服两次，病愈强半。翌日又服一次，心微觉热。继又改用前方，两剂全愈。", "19629": "戊午秋日，愚初至奉天，有李××，年二十八。下痢四十余日，脓血杂以脂膜，屡次服药，病益增剧，羸弱已甚。诊其脉，数而细弱，两尺尤甚。亦治以此方。服后两点钟腹疼一阵，下脓血若干。病家言：从前腹疼不若是之剧，所下者亦不若是之多，似疑药不对证。愚曰：腹中瘀滞下尽即愈矣。伸再用白蔗糖化水，送服去皮鸭蛋子五十粒。此时已届晚九点钟，一夜安睡，至明晨，大便不见脓血矣。后间日大便，又少带紫血，俾仍用山药粥送服鸭蛋子二十粒，数次全愈。", "19630": "又：斯秋中元节后，有刘××者，下痢两月不愈，求为诊治。其脉近和平，按之无力，日便五六次，血液腐败，便时不甚觉疼，后重亦不剧。亦治以此方，一剂病愈强半。翌日将行，嘱以再接原方服两剂当愈。后至奉，接其来函言：服第二剂，效验不如从前；至三剂，病转似增重。因恍悟，此证下痢两月，其脉毫无数象，且按之无力，其下焦当系寒凉。俾仍用山药粥送服炒熟小茴香末一钱，连服数剂全愈。", "19631": "或问：西人谓痢为肠中生炎。所谓炎者，红热肿疼，甚则腐烂也。观此案与治卢姓之案，皆用热药成功，亦可谓之肠炎乎？既非肠炎，何以其肠亦欲腐烂乎？答曰：痢证，原有寒有热。热证不愈，其肠可至腐烂。寒证久不愈，其肠亦可腐烂。譬如疮疡，红肿者阳而热，白硬者阴而寒，其究竟皆可变为脓血。赏观《弢园随笔录》，言其曾患牙疳，医者治以三黄犀角纯寒之品，满口肉烂尽，而色白不知疼。后医者，改用肉桂、附子等品，一服知疼，连服十余剂而愈。夫人口中之肌肉，犹肠中之肌肉也。口中之肌肉，可因寒而腐烂，肠中之肌肉，独不可因寒而腐烂乎？曾治一人，因久居潮湿之地，致下痢，三月不愈。所下者紫血杂以脂膜，腹疼后重。或授以龙眼肉包鸭蛋子方，服之，下痢与腹疼益剧。后愚诊视，其脉微弱而沉，左部几不见。俾用生硫黄研细，掺熟面少许，作丸。又重用生山药、熟地、龙眼肉煎浓汤送服。连服十余剂，共计服生硫黄两许，其痢始愈。由是观之，即纯系赤痢，亦诚有寒者，然不过百中之二三耳。且尝实验痢证，若因寒者，虽经久不愈，犹可支持。且其后重、腹疼，较因热者亦轻也。且《伤寒论》有桃花汤，治少阴病下利、便脓血者，原赤石脂与干姜并用，此为以热药治寒痢之权舆。注家不知，谓少阴之火伤阴络所致，治以桃花汤，原系从治之法。又有矫诬药性，谓赤石脂性凉，重用至一斤，干姜虽热，止用一两，其方仍以凉论者。今试取其药十分之一，煎汤服之，果凉乎热乎？此皆不知《伤寒论》此节之义，而强为注解者也。", "19632": "治下痢，或赤、或白、或赤白参半，下重腹疼，周身发热，服凉药而热不休，脉象确有实热者。", "19633": "一叟，年六十七，于中秋得痢证，医治二十余日不效。后愚诊视，其痢赤白胶滞，下行时，觉肠中热而且干，小便亦觉发热，腹痛下坠并迫。其脊骨尽处，亦下坠作痛。且时作眩晕，其脉洪长有力，舌有白苔甚厚。愚曰：此外感之热挟痢毒之热下迫，故现种种病状，非治痢兼治外感不可。遂投以此汤，两剂，诸病皆愈。其脉犹有余热，拟再用石膏清之，病家疑年高，石膏不可屡服，愚亦应聘他往。后二十余日，痢复作。延他医治疗，于治痢药中，杂以甘寒濡润之品，致外感之余热，永留肠胃不去，其痢虽愈，而屡次反复。延至明年仲夏，反复甚剧。复延愚诊治，其脉象、病证皆如旧。因谓之曰，去岁若肯多服石膏数两，何至有以后屡次反复，今不可再留邪矣。仍投以此汤，连服三剂，病愈而脉亦安和。", "19634": "一人，年四十二，患白痢，常觉下坠，过午尤甚，心中发热，间作寒热。医者于治痢药中，重用黄连一两清之，热如故，而痢亦不愈。留连两月，浸至不起。诊其脉，洪长有力，亦投以此汤。为其间作寒热，加柴胡二钱，一剂热退痢止，犹间有寒热之时。再诊其脉，仍似有力，而无和缓之致。知其痢久，而津液有伤也，遂去白芍、柴胡，加玄参、知母各六钱，一剂寒热亦愈。", "19635": "一媪，年六旬，素多疾病。于夏季晨起，偶下白痢，至暮十余次。秉烛后，忽然浑身大热，不省人事，循衣摸床，呼之不应。其脉洪而无力，肌肤之热烙指。知系气分热痢，又兼受暑，多病之身，不能支持，故精神昏愦如是也。急用生石膏三两、野台参四钱，煎汤一大碗，徐徐温饮下，至夜半尽剂而醒，痢亦遂愈。诘朝煎渣再服，其病脱然。", "19636": "一人，年五十余，于暑日痢而且泻，其泻与痢俱带红色，下坠腹疼，噤口不食。医治两旬，病势浸增，精神昏愦，气息奄奄。诊其脉，细数无力，周身肌肤发热。询其心中亦觉热，舌有黄苔，知其证夹杂暑温。暑气温热，弥漫胃口，又兼痢而且泻，虚热上逆，是以不能食也。遂用生山药两半、滑石一两、生杭芍六钱、粉甘草三钱，一剂诸病皆见愈，可以进食。又服一剂全愈。此证用滑石不用石膏者，以其证兼泻也。为不用石膏，即不敢用人参，故倍用山药以增其补力。此就通变之方，而又为通变也。", "19637": "痢证，又有肝胆肠胃先有郁热，又当暑月劳苦于烈日之中，陡然下痢，多带鲜血，脉象洪数，此纯是一团火气。宜急用大苦大寒之剂，若芩、连、知、柏、胆草、苦参之类，皆可选用。亦可治以白虎汤，方中生石膏必用至二两，再加生白芍一两。若脉大而虚者，宜再加人参三钱。若其脉洪大甚实者，可用大承气汤下之，而佐以白芍、知母。", "19638": "有痢久而清阳下陷者，其人或间作寒热，或觉胸中短气。当于治痢药中，加生黄耆、柴胡以升清阳。脉虚甚者，亦可酌加人参。又当佐以生山药以固下焦，然用药不可失于热也。有痢初得，兼受外感者，宜于治痢药中，兼用解表之品。其外邪不随痢内陷，而痢自易治。不然，则成通变白虎加人参汤所主之证矣。", "19639": "痢证忌用滞泥之品，然亦不可概论。外祖母，年九旬。仲夏下痢赤白甚剧，脉象数而且弦。愚用大熟地、生杭芍各一两煎汤，服下即愈。又服一剂，脉亦和平。", "19640": "痢证间有凉者，然不过百中之一耳，且又多系纯白之痢。又必脉象沉迟，且食凉物，坐凉处则觉剧者。治以干姜、白芍、小茴香各三钱，山楂四钱，生山药六钱，一两剂即愈。用白芍者，诚以痢证必兼下坠腹疼。即系凉痢，其凉在肠胃，而其肝胆间必有伏热，亦防其服热药，而生热也。", "19641": "有奇恒痢者，张隐庵谓，其证三阳并至，三阴莫当，九窍皆塞，阳气旁溢，咽干喉塞痛，并于阴则上下无常，薄为肠澼。其脉缓小迟涩，血温身热者死，热见七日者死。盖因阳气偏盛，阴气受伤，是以脉小迟涩。此证急宜用大承气汤泻阳养阴，缓则不救。若不知奇恒之因，见脉气平缓，而用平易之剂，必至误事。", "19642": "将莱菔切片，同朴硝和水煮之。初次煮，用莱菔片一斤，水五斤，煮至莱菔烂熟捞出。就其余汤，再入莱菔一斤。如此煮五次，约得浓汁一大碗，顿服之。若不能顿服者，先饮一半，停一点钟，再温饮一半，大便即通。若脉虚甚，不任通下者，加人参数钱，另炖同服。", "19643": "软坚通结，朴硝之所长也。然其味咸性寒，若遇燥结甚实者，少用之则无效，多用之则咸寒太过，损肺伤肾。其人或素有劳疾或下元虚寒者，尤非所宜也。惟与莱菔同煎数次，则朴硝之咸味，尽被莱菔提出，莱菔之汁浆，尽与朴硝融化。夫莱菔味甘，性微温，煨熟食之，善治劳嗽短气（方附水晶桃下），其性能补益可知。取其汁与朴硝同用，其甘温也，可化朴硝之咸寒，其补益也，可缓朴硝之攻破。若或脉虚不任通下，又借人参之大力者，以为之扶持保护。然后师有节制，虽猛悍亦可用也。", "19644": "乙卯之岁，客居广平，忽有车载病人，造寓求诊者。其人年过五旬，呻吟不止，言自觉食物结于下脘，甚是痛楚，数次延医调治，一剂中大黄用至两半不下。且凡所服之药，觉行至所结之处，即上逆吐出，饮食亦然。此时上焦甚觉烦躁，大便不通者已旬日矣。诊其脉，虽微弱，至数不数，重按有根。知犹可任攻下，因谓之曰：此病易治，特所服药中，有猛悍之品，服药时，必吾亲自监视方妥。然亦无须久淹，能住此四点钟，结处即通下矣。遂用此汤去干姜，方中赭石改用三两，朴硝改用八钱。服后须臾，腹中作响，迟两点半钟，大便通下而愈。后月余，又患结证如前，仍用前方而愈。", "19645": "一童子，年十五六。因薄受外感，腹中胀满，大便数日不通，然非阳明之实热燥结也。医者投以承气汤，大便仍不通，而腹转增胀。自觉为腹胀所迫，几不能息，且时觉心中怔忡。诊其脉，甚微细，按之即无。脉虚证实，几为束手。亦用葱白熨法，腹胀顿减。又熨三点钟，觉结开，行至下焦。继用猪胆汁导法，大便得通而愈。", "19646": "一人，年四十许，素畏寒凉。愚俾日服生硫黄，如黑豆粒大两块，大见功效，已年余矣。偶因暑日劳碌，心中有火，恣食瓜果，又饱餐肉食，不能消化，肠中结而不行，且又疼痛，时作呕吐。医者用大黄附子细辛汤降之，不效。又用京都薛氏保赤万应散，三剂并作一剂服之，腹疼减去，而仍不通行。后愚诊视，其脉近和平，微弦无力。盖此时不食数日，不大便十日矣。遂治以葱白熨法，觉腹中松畅，且时作开通之声。而仍然恶心，欲作呕吐。继用赭石二两，干姜钱半，俾煎服以止其恶心。仍助以葱白熨法，通其大便。外熨内攻，药逾五点钟，大便得通而愈。", "19647": "一人，年四十三。房事后，恣食生冷，忽然少腹抽疼，肾囊紧缩。大便四日不通，上焦兼有烦躁之意。医者投以大黄附子细辛汤，两胁转觉疼胀。诊其脉，弦而沉，两尺之沉尤甚。先治以葱白熨法，腹中作响，大有开通之意。肾囊之紧缩见愈，而大便仍未通。又用赭石二两，附子五钱，当归、苏子各一两，煎汤，甫饮下，即觉药力下坠。俾复煎渣饮之，有顷，降下结粪若干，诸病皆愈。", "19648": "白虎加人参汤，乃《伤寒论》治外感之热，传入阳明胃腑，以致作渴之方。方书谓上消者宜用之，此借用也。愚曾试验多次，然必胃腑兼有实热者，用之方的。中消用调胃承气汤，此须细为斟酌，若其右部之脉滑而且实，用之犹可，若其人饮食甚勤，一时不食，即心中怔忡，且脉象微弱者，系胸中大气下陷，中气亦随之下陷，宜用升补气分之药，而佐以收涩之品与健补脾胃之品，拙拟升陷汤后有治验之案可参观。若误用承气下之，则危不旋踵。至下消用八味肾气丸，其方《金匮》治男子消渴，饮一斗溲亦一斗。而愚尝试验其方，不惟治男子甚效，即治女子亦甚效。曾治一室女得此证，用八味丸变作汤剂，按后世法，地黄用熟地、桂用肉桂，丸中用几两者改用几钱，惟茯苓、泽泻各用一钱，两剂而愈。后又治一少妇得此证，投以原方不效，改遵古法，地黄用干地黄（即今生地），桂用桂枝，分量一如前方，四剂而愈。此中有宜古宜今之不同者，因其证之凉热，与其资禀之虚实不同耳。", "19649": "消渴证，若其肺体有热，当治以清热润肺之品。若因心火热而铄肺者，更当用清心之药。若肺体非热，因腹中气化不升，轻气即不能上达于肺，与吸进之养气相合而生水者，当用升补之药，补其气化，而导之上升，此拙拟玉液汤之义也。然消渴之证，恒有因脾胃湿寒、真火衰微者，此肾气丸所以用桂、附。而后世治消渴，亦有用干姜、白术者。尝治一少年，咽喉常常发干，饮水连连，不能解渴。诊其脉微弱迟濡。投以四君子汤，加干姜、桂枝尖，一剂而渴止矣。又有湿热郁于中焦作渴者，苍柏二妙散、丹溪越鞠丸，皆可酌用。", "19650": "邑人某，年二十余，贸易津门，得消渴证。求津门医者，调治三阅月，更医十余人不效，归家就医于愚。诊其脉甚微细，旋饮水旋即小便，须臾数次。投以玉液汤，加野台参四钱，数剂渴见止，而小便仍数，又加萸肉五钱，连服十剂而愈。", "19651": "上五味，将前四味煎汤，送服猪胰子一半，至煎渣时，再送服余一半。若遇中、上二焦积有实热，脉象洪实者，可先服白虎加人参汤数剂，将实热消去强半，再服此汤，亦能奏效。", "19652": "消渴一证，古有上中下之分，谓其证皆起于中焦而极于上下。究之无论上消、中消、下消，约皆渴而多饮多尿，其尿有甜味。是以《圣济总录》论消渴谓：「渴而饮水多，小便中有脂，似麸而甘。」至谓其证起于中焦，是诚有理，因中焦膵病，而累及于脾也。盖膵为脾之副脏，在中医书中，名为散膏，即扁鹊《难经》所谓脾有散膏半斤也（膵尾衔接于脾门，其全体之动脉又自脾脉分支而来，故与脾有密切之关系）。有时膵脏发酵，多酿甜味，由水道下陷，其人小便遂含有糖质。迨至膵病累及于脾，致脾气不能散精达肺（《内经》谓脾气散精上达于肺）则津液少，不能通调水道（《内经》谓通调水道下归膀胱）则小便无节，是以渴而多饮多溲也。尝阅报，有患消渴，延中医治疗，服药竟愈者。所用方中，以黄耆为主药，为其能助脾气上升，还其散精达肺之旧也。《金匮》有肾气丸，善治消渴。其方以干地黄（即生地黄）为主，取其能助肾中之真阴，上潮以润肺，又能协同山萸肉以封固肾关也。又向因治消渴，曾拟有玉液汤，方中以生怀山药为主，屡试有效。近阅医报且有单服山药以治消渴而愈者。以其能补脾固肾，以止小便频数，而所含之蛋白质，又能滋补膵脏，使其散膏充足，且又色白入肺，能润肺生水，即以止渴也。又俗传治消渴方，单服生猪胰子可愈。盖猪胰子即猪之膵，是人之膵病，而可补以物之膵也。此亦犹鸡内金，诸家本草皆谓其能治消渴之理也。鸡内金与猪胰子，同为化食之物也。愚因集诸药，合为一方，以治消渴，屡次见效。", "19653": "一媪，年六十余，得水肿证，延医治不效。时有专以治水肿名者，其方秘而不传。服其药自大便泻水数桶，一身肿尽消，言忌咸百日，可保永愈。数日又见肿，旋覆如故。服其药三次皆然，而病人益衰惫矣。盖未服其药时，即艰于小便，既服药后，小便滴沥全无，所以旋消而旋肿也。再延他医，皆言服此药，愈后复发者，断乎不能调治。后愚诊视，其脉数而无力。愚曰：脉数者阴分虚也，无力者阳分虚也。膀胱之腑，有下口无上口，水饮必随气血流行，而后能达于膀胱，出为小便。《内经》所谓「州都之官，津液藏焉，气化则能出」者是也。此脉阴阳俱虚，致气化伤损，不能运化水饮以达膀胱，此小便所以滴沥全无也。一方，以人参为君，辅以麦冬以济参之热，灵仙以行参之滞，少加地肤子为向导药，名之曰宣阳汤。一方以熟地为君，辅以龟板以助熟地之润，芍药以行熟地之滞（芍药善利小便，故能行熟地之泥），亦少加地肤子为向导药，名之曰济阴汤。二方轮流服之，先服济阴汤，取其贞下起元也。服至三剂，小便稍利。再服宣阳汤，亦三剂小便大利。又再服济阴汤，小便直如泉涌，肿遂尽消。", "19654": "一妇人，年四十许，得水肿证。其脉象大致平和，而微有滑数之象。俾浓煎鲜茅根汤饮之，数日病愈强半。其子来送信，愚因嘱之曰：有要紧一言，前竟忘却。患此证者，终身须忌食牛肉。病愈数十年，食之可以复发。孰意其子未返，已食牛肉。且自觉病愈，出坐庭中，又兼受风。其证陡然反复，一身尽肿，两目因肿甚不能开视。愚用越婢汤发之，以滑石易石膏（用越婢汤原方，常有不汗者，若以滑石易石膏则易得汗），一剂汗出，小便顿利，肿亦见消。再饮白茅根汤，数日病遂全愈。", "19655": "治水肿小便不利，其脉沉迟无力，自觉寒凉者。", "19656": "服药数剂后，小便微利；其脉沉迟如故者，用此汤送服生硫黄末四五厘。若不觉温暖，体验渐渐加多，以服后移时觉微温为度。", "19657": "人之水饮，非阳气不能宣通。上焦阳虚者，水饮停于膈上。中焦阳虚者，水饮停于脾胃。下焦阳虚者，水饮停于膀胱。水饮停蓄既久，遂渐渍于周身，而头面肢体皆肿，甚或腹如抱瓮，而膨胀成矣。此方用苓桂术甘汤，以助上焦之阳。即用甘草协同人参、干姜，以助中焦之阳。又人参同附子，名参附汤（能固下焦元阳将脱）协同桂枝，更能助下焦之阳（桂枝上达胸膈，下通膀胱故肾气丸用桂枝不用肉桂）。三焦阳气宣通，水饮亦随之宣通，而不复停滞为患矣。至灵仙与人参并用，治气虚小便不利甚效（此由实验而知，故前所载宣阳汤并用之）。而其通利之性，又能运化术、草之补力，俾胀满者服之，毫无滞碍，故加之以为佐使也。若药服数剂后，脉仍如故，病虽见愈，实无大效，此真火衰微太甚，恐非草木之品所能成功。故又用生硫黄少许，以补助相火。诸家本草谓其能使大便润，小便长，补火之中大有行水之力，故用之因凉成水肿者尤良也。服生硫黄法，其中有治水肿之验案宜参观。", "19658": "脉沉水肿，与脉浮水肿迥异。脉浮者，多系风水，腠理闭塞，小便不利。当以《金匮》越婢汤发之，通身得汗，小便自利。若浮而兼数者，当是阴虚火动，宜兼用凉润滋阴之药。脉沉水肿，亦未可遽以凉断。若沉而按之有力者，系下焦蕴热未化，仍当用凉润之药，滋阴以化其阳，小便自利。惟其脉沉而且迟，微弱欲无，询之更自觉寒凉者，方可放胆用此汤无碍。或但服生硫黄，试验渐渐加多，亦可奏效。特是肿之剧者，脉之部位皆肿，似难辨其沉浮与有力无力，必重按移时，使按处成凹，始能细细辨认。", "19659": "用越婢汤治风水，愚曾经验，遇药病相投，功效甚捷。其方《金匮》以治风水恶风，一身悉肿，脉浮不渴，续自汗出，无大热者。而愚临证体验以来，即非续自汗出者，用之亦可，若一剂而汗不出者，可将石膏易作滑石（分量须加重）。", "19660": "一人，年六十余，溺血数日，小便忽然不通，两日之间滴沥全无。病人不能支持，自以手揉挤，流出血水少许，稍较轻松。揉挤数次，疼痛不堪揉挤。徬徨无措，求为诊治。其脉沉而有力，时当仲夏，身复厚被，犹觉寒凉。知其实热郁于下焦，溺管因热而肿胀不通也。为拟此汤，一剂稍通，又加木通、海金沙各二钱，服两剂全愈。", "19661": "或问：茅根能清热利小便，人所共知。至谓兼理气分之郁，诸家本草皆未言及，子亦曾单用之，而有确实之征验乎？答曰：此等实验，已不胜记。曾治一室女，心中常觉发热，屡次服药无效。后愚为诊视，六脉皆沉细，诊脉之际，闻其太息数次，知其气分不舒也。问其心中胁下，恒隐隐作疼。遂俾剖取鲜茅根，锉细半斤，煎数沸当茶饮之。两日后，复诊其脉，已还浮分，重诊有力，不复闻其太息。问其胁下，已不觉疼，惟心中仍觉发热耳。再饮数日，其心中发热亦愈。", "19662": "又尝治少年，得肺鼠疫病。其咽喉唇舌，异常干燥。精神昏昏似睡。周身肌肤不热。脉象沉微。问其心中，时常烦闷。此鼠疫之邪，闭塞其少阴，致肾气不能上达也。问其大便，四日未行。遂投以大剂白虎加人参汤，先用茅根数两煎汤，以之代水煎药，取汁三盅，分三次饮下。其脉顿起，变作洪滑之象。精神已复，周身皆热，诸病亦皆见愈。俾仍按原方将药煎出，每饮一次，调入生鸡子黄一枚，其病遂全愈。盖茅根生于水边，原兼禀寒水之气。且其出地之时，作尖锐之锥形，故能直入少阴，助肾气上达，与心相济，则心即跳动有力，是以其脉，遂洪滑外现也。再加生鸡子黄，以滋少阴之液，俾其随气上升，以解上焦之因燥生热，因热生烦，是以诸病皆愈也。此二案皆足征茅根理气之效也。", "19663": "一人，年三十许，患血淋。溲时血块杜塞，努力始能溲出，疼楚异常。且所溲者上多浮油，胶黏结于器底，是血淋而兼膏淋也。从前延医调治，经三十五人，服药年余，分毫无效，尪羸已甚。后愚诊视，其脉弦细，至数略数，周身肌肤甲错，足骨凸处，其肉皮皆成旋螺高寸余，触之甚疼。盖卧床不起者，已半载矣。细询病因，谓得之忿怒之余误坠水中，时当秋夜觉凉甚，遂成斯证。知其忿怒之火，为外寒所束，郁于下焦而不散，而从前居室之间，又有失保养处也。拟投以此汤，为脉弦，遂以柏子仁（炒捣）八钱，代方中山药，以其善于养肝也。疏方甫定，其父出所服之方数十纸，欲以质其同异。愚曰：无须细观，诸方与吾方同者，惟阿胶白芍耳，阅之果然。其父问何以知之？愚曰：吾所用之方，皆苦心自经营者，故与他方不同。服三剂血淋遂愈，而膏淋亦少减。改用拙拟膏淋汤，连服二十余剂，膏淋亦愈，而小便仍然频数作疼。细询其疼之实状，谓少腹常觉疼而且坠，时有欲便之意，故有尿即不能强忍，知其又兼气淋也。又投以拙拟气淋汤，十剂全愈。周身甲错，足上旋螺尽脱。", "19664": "溺血之证，热者居多，而间有因寒者，则此方不可用矣。曾治一人，年三十余，陡然溺血，其脉微弱而迟，自觉下焦凉甚。知其中气虚弱，不能摄血，又兼命门相火衰微，乏吸摄之力，以致肾脏不能封固，血随小便而脱出也。投以四君子汤，加熟地、乌附子，连服二十余剂始愈。又有非凉非热，但因脾虚不能统血而溺血者。方书所谓失于便溺者，太阴之不升也。仍宜用四君子汤，以龙骨、牡蛎佐之。", "19665": "大便下血者，大抵由于肠中回血管或血脉管破裂。方中龙骨、牡蛎之收涩，原可补其破裂之处。而又去阿胶者，防其滑大肠也。加龙眼肉者，因此证间有因脾虚不能统血而然者，故加龙眼肉以补脾。若虚甚者，又当重用白术，或更以参、耆佐之。若虚而且陷者，当兼佐以柴胡、升麻。若虚而且凉者，当兼佐以干姜、附子，减去芍药、白头翁。一少妇，大便下血月余，屡次服药不效。愚为诊视，用理血汤，去阿胶，加龙眼肉五钱治之。而僻处药坊无白头翁，权服一剂，病稍见愈。翌日至他处药坊，按方取药服之，病遂全愈。则白头翁之功效，何其伟哉！", "19666": "张××，年二十八岁，于冬月初，得膏淋，继之血淋。所便者，或血条，或血块，后则继以鲜血，溺频茎疼。屡经医者调治，病转加剧。其气色青黑，六脉坚数，肝脉尤甚。与以理血汤，俾连服三剂，血止，脉稍平，他证仍旧。继按治淋浊方诸方加减治之，十余剂全愈。", "19667": "治小便频数，遗精白浊，或兼疼涩，其脉弦数无力，或咳嗽、或自汗、或阴虚作热。", "19668": "治小便频数疼涩，遗精白浊，脉洪滑有力，确系实热者。", "19669": "一叟，年七十余，遗精白浊、小便频数，微觉疼涩。诊其六脉平和，两尺重按有力，知其年虽高，而肾经确有实热也。投以此汤，五剂全愈。", "19670": "一人，年三十许，遗精白浊，小便时疼如刀剺，又甚涩数。诊其脉滑而有力，知其系实热之证。为其年少，疑兼花柳毒淋，遂投以此汤，加没药（不去油）三钱、鸭蛋子（去皮）四十粒（药汁送服），数剂而愈。", "19671": "治小便遗精白浊，因受风寒者，其脉弦而长，左脉尤甚。", "19672": "东海渔者，年三十余，得骗白证甚剧。旬日之间，大见衰惫，惧甚，远来求方。其脉左右皆弦，而左部弦而兼长。夫弦长者，肝木之盛也。木与风为同类，人之脏腑，无论何处受风，其风皆与肝木相应。《内经》阴阳应象论所谓「风气通于肝」者是也。脉之现象如此，肝因风助，倍形其盛，而失其和也。况病人自言，因房事后小便当风，从此外肾微肿，遂有此证，尤为风之明征乎。盖房事后，肾脏经络虚而不闭，风气乘虚袭入，鼓动肾脏不能蛰藏（《内经》谓肾主蛰藏），而为肾行气之肝木，又与风相应，以助其鼓动，而大其疏泄（《内经》肝主疏泄），故其病若是之剧也。为拟此汤，使脉之弦长者，变为舒和。服之一剂见轻，数剂后遂全愈。以后凡遇此等症，其脉象与此同者，投以此汤无不辄效。", "19673": "伤寒之证，先自背受之，背者足太阳所辖之部位也。是以其证初得，周身虽皆恶寒，而背之恶寒尤甚，周身虽皆觉疼，而背下连腿之疼痛尤甚。其脉阴阳俱紧者，诚以太阳为周身外卫之阳，陡为风寒所袭，逼其阳气内陷，与脉相并，其脉当有力，而作起伏迭涌之势。而寒气之缩力（凡物之体热则涨，寒则缩），又将外卫之气缩紧，逼压脉道，使不得起伏成波澜，而惟现弦直有力之象。甚或因不能起伏，而至左右弹动。", "19674": "凡脉之紧者必有力。夫脉之跳动，心脏主之。而其跳动之有力，不但心主之也；诸脏腑有热皆可助脉之跳动有力，营卫中有热亦可助脉之跳动有力。特是脉之有力者，恒若水之有浪，大有起伏之势。而紧脉虽有力，转若无所起伏，诚以严寒束其外表，其收缩之力能逼营卫之热内陷与脉相并，以助其有力；而其收缩之力又能遏抑脉之跳动，使无起伏。是紧脉之真相，原于平行中见其有力也。至于紧脉或左右弹者，亦蓄极而旁溢之象也。仲师治以麻黄汤，所以解外表所束之寒也。", "19675": "或问：桂枝汤证，其原因既为大气虚损，宜其阳脉现微弱之象，何以其脉转阳浮而阴弱乎？答曰：人之一身，皆气之所撑悬也。此气在下焦为元气，在中焦为中气，在上焦为大气，区域虽分，而实一气贯注。故一身之中，无论何处气虚，脉之三部，皆现弱象。今其关前之脉，因风而浮，转若不见其弱，而其关后之脉，仍然微弱，故曰阳浮而阴弱也。如谓阴弱为下焦阴虚，则其脉宜兼数象。而愚生平所遇此等证，其脉多迟缓，不及四至，其为气分虚损，而非阴分虚损可知。即所谓啬啬恶寒、淅淅恶风，翕翕发热，亦皆气分怯弱之形状也。", "19676": "徐灵胎曰：龙骨最黏涩，能收敛正气，凡心神耗散，肠胃滑脱之疾，皆能已之。此药但敛正气，而不敛邪气。所以仲景于伤寒邪气未尽者，亦恒与牡蛎同用，若仲景之柴胡加龙骨牡蛎汤，桂枝、甘草、龙骨、牡蛎汤诸方是也。愚于伤寒、温病，热实脉虚，心中怔忡，精神骚扰者，恒龙骨与萸肉、生石膏并用，即可随手奏效。", "19677": "门人高××曾治一外感痰喘，其喘剧脉虚，医皆诿为不治。高××投以小青龙汤，去麻黄，加杏仁，又加生石膏一两、野台参五钱，一剂而喘定。恐其反复，又继投以从龙汤，亦加人参与生石膏，其病霍然顿愈。", "19678": "又：子××治曲姓叟，年六十余，外感痰喘，十余日不能卧。医者投以小清龙汤两剂，病益加剧（脉有热而不敢多加生石膏者其病必加剧）。××视之，其脉搏一息六至，上焦烦躁，舌上白苔满布，每日大便两三次，然非滑泻。审证论脉，似难挽回。而××仍投以小青龙汤，去麻黄，加杏仁，又加野台参三钱，生龙骨、生牡蛎各五钱，生石膏一两半。一剂病愈强半，又服一剂全愈。", "19679": "治胸中先有蕴热，又受外感，胸中烦闷异常，喘息迫促，其脉浮洪有力，按之未实，舌苔白而未黄者。", "19680": "奉天钱姓妇于仲冬得伤寒证，四五日间，喘不能卧，胸中烦闷异常，频频呼唤，欲自开其胸。诊其脉浮洪而长，重按未实，舌苔白厚。知其证虽入阳明，而太阳犹未罢也（胸中属太阳）。此时欲以小青龙汤治喘，则失于热。欲以白虎汤治其烦热，又遗却太阳之病，而喘不能愈。踌躇再三，为拟此方，取汽水轻浮之力，能引石膏上升，以解胸中之烦热。甘草甘缓之性，能逗留石膏不使下趋，以专其上行之力。又少佐以麻黄解散太阳之余邪，兼借以泻肺定喘，而胸中满闷可除也。汤成后，俾徐徐分六次服之。因病在上焦，若顿服，恐药力下趋，则药过病所，而病转不愈也。服至三次，胸间微汗，病顿见愈，服至尽剂，病愈十之八九。再诊其脉，关前犹似浮洪，喘息已平，而从前兼有咳嗽未愈，继用玄参一两，杏仁（去皮）二钱，蒌仁、牛蒡子各三钱，两剂全愈。", "19681": "一人，年二十余。伤寒六七日，头疼恶寒，心中发热，咳吐黏涎。至暮尤寒热交作，兼眩晕，心中之热亦甚。其脉浮弦，重按有力，大便五日未行。投以此汤，加生石膏六钱、芒硝四钱，下大便二次。上半身微见汗，诸病皆见轻。惟心中犹觉发热，脉象不若从前之浮弦，而重按仍有力。拟投以白虎加人参汤，恐当下后，易作滑泻，遂以生山药代粳米，连服两剂全愈。", "19682": "一叟，年近七旬。素有劳嗽，初冬宿病发动，又兼受外感，痰涎壅滞胸间，几不能息。剧时昏不知人，身躯后挺。诊其脉，浮数无力。为制此汤，一剂气息通顺，将麻黄、石膏减半，又服数剂而愈。", "19683": "治温病初得，头疼，周身骨节酸疼，肌肤壮热，背微恶寒无汗，脉浮滑者。", "19684": "《伤寒论》曰：「太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，息必鼾，言语难出。」此仲景论温病之提纲也。乃提纲详矣，而后未明言治温病之方。及反复详细观之，乃知《伤寒论》中，原有治温病方，且亦明言治温病方，特涉猎观之不知耳。六十一节云：「发汗后，不可更行桂枝汤。汗出而喘，无大热者，可与麻黄、杏仁、甘草、石膏汤主之。」夫此证既汗后不解，必是用辛热之药，发不恶寒证之汗，即温病提纲中，所谓若发汗已也（提纲中所谓若发汗，是用辛热之药强发温病之汗）。其汗出而喘，无大热者，即温病提纲中，所谓若发汗已，身灼热及后所谓自汗出、多眠睡、息必鼾也。睡而息鼾，醒则喘矣。此证既用辛热之药，误发于前，仲景恐医者见其自汗，再误认为桂枝汤证，故特戒之曰：不可更行桂枝汤，而宜治以麻杏甘石汤。此节与温病提纲遥遥相应，合读之则了如指掌。然麻杏甘石汤，诚为治温病初得之的方矣。而愚于发表药中不用麻黄，而用薄荷、蝉蜕者，曾于葛根黄芩黄连汤解后详论之，兹不再赘。", "19685": "一为春温。其证因冬月薄受外感，不至即病。所受之邪，伏于膜原之间，阻塞脉络，不能宣通，暗生内热。迨至春日阳生，内蕴之热，原有萌动之机，而复薄受外感，与之相触，则陡然而发，表里俱热，《内经》所谓「冬伤于寒，春必病温」者是也，宜治以拙拟凉解汤。热甚者，治以拙拟寒解汤。有汗者，宜仲景葛根黄连黄芩汤，或拙拟和解汤，加生石膏。若至发于暑月，又名为暑温，其热尤甚。初得即有脉洪长，渴嗜凉水者，宜投以大剂白虎汤，或拙拟仙露汤。", "19686": "一为风温。犹是外感之风寒也，其时令已温，外感之气已转而为温，故不名曰伤寒、伤风，而名风温，即《伤寒论》中所谓风温之为病者是也。然其证有得之春初者，有得之春暮者，有得之夏秋者，当随时序之寒热，参以脉象，而分别治之。若当春初秋末，时令在寒温之间，初得时虽不恶寒，脉但浮而无热象者，宜用拙拟清解汤，加麻黄一二钱，或用仲景大青龙汤。若当暑热之日，其脉象浮而且洪者，用拙拟凉解汤，或寒解汤。若有汗者，用拙拟和解汤，或酌加生石膏。", "19687": "曾治一人，年二十余。当仲夏夜寝，因夜凉，盖单衾冻醒，发懒，仍如此睡去。须臾又冻醒，晨起微觉恶寒。至巳时已觉表里大热，兼喘促，脉洪长而浮。投以清解汤，方中生石膏，改用两半，又加牛蒡子（炒捣）三钱，服后得汗而愈。由斯观之，其初非中于太阳乎，然不专在太阳也。人之所以觉凉者，由于衣衾之薄。其气候究非寒凉，故其中于人不专在太阳，而兼在阳明。且当其时，人多蕴内热，是以转阳明甚速也，然此所论者风温耳。若至冬受春发，或夏发之温，恒有与太阳无涉者。故《伤寒论》温病提纲中，特别之曰：风温之为病，明其异于「冬伤于寒，春必病温」之温病也。又杏仁与牛蒡子，皆能降肺定喘，而杏仁性温、牛蒡子性凉，伤寒喘证，皆用杏仁，而温病不宜用温药，故以牛蒡子代之。", "19688": "一九二五年春，一人来津学木工。因身体单薄，又兼天热，得温病，请为诊视。脉浮数而滑，舌苔白厚，时时昏睡。为开清解汤，生石膏用一两，为其脉数，又加玄参五钱，一剂病愈。", "19689": "治温病，表里俱觉发热，脉洪而兼浮者。", "19690": "春温之证，多有一发而表里俱热者，至暑温尤甚，已详论之于前矣。而风温证，两三日间，亦多见有此脉、证者。此汤皆能治之，得汗即愈。", "19691": "治周身壮热，心中热而且渴，舌上苔白欲黄，其脉洪滑。或头犹觉疼，周身犹有拘束之意者。", "19692": "或问：此汤为发表之剂，而重用石膏、知母，微用连翘、蝉蜕，何以能得汗？答曰，用此方者，特恐其诊脉不真，审证不确耳。果如方下所注脉证，服之复杯可汗，勿庸虑此方之不效也。盖脉洪滑而渴，阳明府热已实，原是白虎汤证。特因头或微疼，外表犹似拘束，是犹有一分太阳流连未去。故方中重用石膏、知母以清胃府之热；而复少用连翘、蝉蜕之善达表者，引胃中化而欲散之热，仍还太阳作汗而解。斯乃调剂阴阳，听其自汗，非强发其汗也。况石膏性凉（《神农本草经》谓其微寒即凉也）味微辛，有实热者，单服之即能汗乎？", "19693": "曾治一少年，孟夏长途劳役，得温病，医治半月不效。后愚诊视，其两目清白，竟无所见，两手循衣摸床，乱动不休，讝语不省人事。其大便从前滑泻，此时虽不滑泻，每日仍溏便一两次。脉浮数，右寸之浮尤甚，两尺按之即无。因此证目清白无见者，肾阴将竭也。手循衣摸床者，肝风已动也。病势之危，已至极点。幸喜脉浮，为病还太阳。右寸浮尤甚，为将汗之势。其所以将汗而不汗者，人身之有汗，如天地之有雨。天地阴阳和而后雨，人身亦阴阳和而后汗。此证尺脉甚弱，阳升而阴不能应，汗何由作？当用大润之剂，峻补真阴，济阴以应其阳，必能自汗。遂用熟地、玄参、阿胶、枸杞之类，约重六七两，煎汤一大碗，徐徐温饮下，一日连进二剂，即日大汗而愈。审是，则发汗原无定法。当视其阴阳所虚之处，而调补之，或因其病机而利导之，皆能出汗，非必发汗之药始能汗也。按：寒温之证，原忌用黏腻滋阴、甘寒清火，以其能留邪也。而用以为发汗之助，则转能逐邪外出，是药在人用耳。", "19694": "一人，年四十余。为风寒所束不得汗，胸中烦热，又兼喘促。医者治以苏子降气汤，兼散风清火之品，数剂病益进。诊其脉，洪滑而浮，投以寒解汤，须臾上半身即出汗。又须臾，觉药力下行，至下焦及腿亦皆出汗，病若失。", "19695": "一人，年三十许。得温证，延医治不效，迁延十余日。愚诊视之，脉虽洪而有力，仍兼浮象。问其头疼乎？曰：然！渴欲饮凉水乎？曰：有时亦饮凉水，然不至燥渴耳。知其为日虽多，而阳明之热，犹未甚实，太阳之表，犹未尽罢也。投以寒解汤，须臾汗出而愈。", "19696": "一人，年三十余。于冬令感冒风寒，周身恶寒无汗，胸间烦躁。原是大青龙汤证，医者投以麻黄汤。服后汗无分毫，而烦躁益甚，几至疯狂。诊其脉，洪滑异常，两寸皆浮，而右寸尤甚。投以寒解汤，复杯之顷，汗出如洗而愈。审是则寒解汤不但宜于温病，伤寒现此脉者，投之亦必效也。", "19697": "一叟，年七旬。素有劳疾，薄受外感，即发喘逆，投以小青龙汤，去麻黄，加杏仁、生石膏辄愈。上元节后，因外感甚重，旧病复发，五六日间，热入阳明之府。脉象弦长浮数，按之有力，而无洪滑之象（此外感兼内伤之脉）。投以寒解汤，加潞参三钱，一剂汗出而喘愈。再诊其脉，余热犹炽，继投以白虎加人参以山药代粳米汤一大剂，分三次温饮下，尽剂而愈。", "19698": "一妊妇，伤寒两、三日。脉洪滑异常，精神昏愦，间作讝语，舌苔白而甚厚。为开寒解汤方，有一医者在座，问方中之意何居？愚曰：欲汗解耳。曰：此方能汗解乎？愚曰：此方遇此证，服之自能出汗，若泛作汗解之药服之，不能汗也。饮下须臾，汗出而愈。", "19699": "一妇人，年二十余，得温病。咽喉作疼，舌强直，几不能言，心中热而且渴，频频饮水，脉竟沉细异常，肌肤亦不发热。遂舍脉从证，投以寒解汤，得微汗，病稍见愈。明晨又复如故，舌之强直更甚。知药原对证，而力微不能胜病也。遂仍投以寒解汤，将石膏加倍，煎汤两盅，分二次温饮下，又得微汗，病遂愈。", "19700": "按：伤寒脉若沉细，多系阴证。温病脉若沉细，则多系阳证。盖温病多受于冬，至春而发，其病机自内向外。有时病机郁而不能外达，其脉或即现沉细之象，误认为凉，必至误事。又此证，寒解汤既对证见愈矣，而明晨，舌之强直更甚，乃将方中生石膏倍作二两，分两次前后服下，其病即愈。由是观之，凡治寒温之热者，皆宜煎一大剂，分数次服下，效古人一剂三服之法也。", "19701": "门人高××曾治一媪，年近七旬。于春初得伤寒证，三四日间，烦热异常。又兼白痢，昼夜滞下无度，其脉洪滑兼浮。高××投以寒解汤，加生杭芍三钱，一剂微汗而热解，痢亦遂愈。", "19702": "又：吴又可曰：「里证下后，脉浮而微数，身微热，神思或不爽。此邪热浮于肌表，里无壅滞也。虽无汗，宜白虎汤，邪可从汗而解。若下后，脉空虚而数，按之豁然如无者，宜白虎加人参汤，复杯则汗解。」按：白虎汤与白虎加人参汤，皆非解表之药，而用之得当，虽在下后，犹可须臾得汗，况在未下之前乎。不但此也，即承气汤，亦可为汗解之药，亦视乎用之何如耳。又洪吉人曰：「余尝治热病八、九日，用柴葛解之、芩连清之、硝黄下之，俱不得汗。昏愦扰乱，撮空摸床，危在顷刻。以大剂地黄汤（必系减去桂附者），重加人参、麦冬进之。不一时，通身大汗淋漓，恶证悉退，神思顿清。」", "19703": "天津××，得温病，先服他医清解之药数剂无效。弟诊其脉象，沉浮皆有力，表里壮热无汗。投以寒解汤原方，遍身得汗而愈。山斯知方中重用生石膏、知母以清热，少加连翘、蝉蜕以引热透表外出，制方之妙远胜于银翘散、桑菊饮诸方矣。且由此知石膏生用诚为妙药。从治愈此证之后，凡遇寒温实热诸证，莫不遵书中方论，重用生石膏治之。其热实脉虚者，亦莫不遵书中方论，用白虎加人参汤，或用白虎加人参以生山药代粳米汤，皆能随手奏效。", "19704": "斯年初冬，适郭姓之女得伤寒证，三四日间阳明热势甚剧，面赤气粗，六脉洪数，时作谵语。为开寒解汤，因胸中觉闷，加栝蒌仁一两，一剂病愈。", "19705": "治温病表里俱热，时有汗出，舌苔白，脉浮滑者。", "19706": "若脉浮滑，而兼有洪象者，生石膏当用一两。", "19707": "一叟，年六十五，得风温证。六七日间，周身悉肿，肾囊肿大似西瓜，屡次服药无效。旬日之外，求为诊视。脉洪滑微浮，心中热渴，小便涩热，痰涎上泛，微兼喘息，舌苔白厚。投以此汤，加生石膏一两，周身微汗，小便通利，肿消其半，犹觉热渴。遂将方中生石膏加倍，服后又得微汗，肿遂尽消，诸病皆愈。按：此乃风温之热，由太阳经入于膀胱之府，阻塞水道，而阳明胃府亦将实也。由是观之，彼谓温病入手经、不入足经者，何其谬哉！", "19708": "一媪，年近七旬，素患漫肿。为调治月余，肿虽就愈，而身体未复。忽于季春得温病，上焦烦热，病家自剖鲜地骨皮，煮汁饮之稍愈，又饮数次，遂滑泻不止，而烦热益甚。其脉浮滑而数，重诊无力。病家因病者年高，又素有疾病，加以上焦烦热，下焦滑泻，惴惴惟恐不愈，而愚毅然以为可治。投以滋阴宣解汤，一剂泻止，烦热亦觉轻。继用拙拟白虎加人参以山药代粳米汤，煎汁一大碗，一次只温饮一大口，防其再滑泻也。尽剂而愈。", "19709": "一室女，感冒风热，遍身瘾疹，烦渴滑泻，又兼喘促。其脉浮数无力。愚踌躇再四，亦投以滋阴宣解汤，两剂诸病皆愈。", "19710": "治同前证。外表已解，其人或不滑泻，或兼喘息，或兼咳嗽，频吐痰涎，确有外感实热，而脉象甚虚数者。若前证，服滋阴宣解汤后，犹有余热者，亦可继服此汤。", "19711": "一妇人，受妊五月，偶得伤寒。三四日间，胎忽滑下。上焦燥渴，喘而且呻，痰涎壅盛，频频咳吐。延医服药，病未去，而转添滑泻，昼夜十余次。医者辞不治，且谓危在旦夕。其家人惶恐，迎愚诊视。其脉似洪滑，重诊指下豁然，两尺尤甚。本拟治以滋阴清燥汤，为小产才四五日，不敢遽用寒凉。遂先用生山药二两、酸石榴一个，连皮捣烂，同煎汁一大碗，分三次温饮下。滑泻见愈，他病如故。再诊其脉，洪滑之力较实，因思此证虽虚，确有外感实热，若不先解其实热，他病何以得愈？时届晚三点钟，病人自言，每日此时潮热，又言精神困倦已极，昼夜苦不得睡。遂于斯日，复投以滋阴清燥汤。方中生山药重用两半，煎汁一大碗，徐徐温饮下，一次只饮药一口，诚以产后，脉象又虚，不欲寒凉侵下焦也。斯夜遂得安睡，渴与滑泻皆愈，喘与咳亦愈其半。又将山药、滑石各减五钱，加龙骨、牡蛎各八钱，一剂而愈。", "19712": "一室女，伤寒过两旬矣，而瘦弱支离，精神昏愦，过午发热，咳而且喘，医者辞不治。诊其脉，数至七至，微弱欲无。因思此证，若系久病至此，不可为矣。然究系暴虚之证，生机之根柢当无损。勉强投以滋阴清燥汤，将滑石减半，又加玄参、熟地黄各一两，野台参五钱，煎汤一大碗，徐徐温饮下。饮完煎滓重饮，俾药力昼夜相继。两日之间，连服三剂，滑石渐减至二钱，其病竟愈。", "19713": "汲××之母，年近七旬。身体羸弱，谷食不能消化，惟饮牛乳，或间饮米汤少许，已二年卧床，不能起坐矣。于戊午季秋，受温病。时愚初至奉天，自锦州邀愚诊视。脉甚细数，按之微觉有力。发热咳嗽，吐痰稠黏，精神昏愦，气息奄奄。投以滋阴清燥汤，减滑石之半，加玄参五钱，一剂病愈强半。又煎渣取清汤一茶盅，调入生鸡子黄一枚，服之全愈。", "19714": "奉天一孺子年四岁，得温病，邪犹在表，医者不知为之清解，遽投以苦寒之剂，服后滑泻，四五日不止。上焦燥热，闭目而喘，精神昏愦。延为诊治，病虽危险，其脉尚有根柢，知可挽回。俾用滋阴清燥汤原方，煎汁一大茶杯，为其幼小，俾徐徐温饮下，尽剂而愈。然下久亡阴，余有虚热，继用生山药、玄参各一两以清之，两剂热尽除。大抵医者遇此等证，清其燥热，则滑泻愈甚，补其滑泻，其燥热亦必愈甚。惟此方，用山药以止滑泻，而山药实能滋阴退热，滑石以清燥热，而滑石实能利水止泻，二药之功用，相得益彰。又佐以芍药之滋阴血、利小便，甘草之燮阴阳、和中宫，亦为清热止泻之要品。汇集成方，所以效验异常。愚用此方，救人多矣，即势至垂危，投之亦能奏效。", "19715": "奉天刘××，年二十五六，于季冬得伤寒，经医者误治，大便滑泻无度，而上焦烦热，精神昏愦，时作谵语，脉象洪数，重按无力。遂重用生山药两半、滑石一两、生杭芍六钱、甘草三钱，一剂泻止。上焦烦热不退，仍作谵语，爰用玄参、沙参诸凉润之药清之，仍复滑泻，再投以前方一剂泻又止，而上焦之烦热益甚，精神亦益昏愦，毫无知觉。此时其家人毕至，皆以为不可复治。诊其脉虽不实，仍有根柢，至数虽数，不过六至，知犹可治，遂慨切谓其家人曰：「果信服余药，此病尚可为也」，其家人似领悟。为疏方，用大剂白虎加人参汤，更以生山药一两代粳米，大生地一两代知母，煎汤一大碗，嘱其药须热饮，一次止饮一口，限以六句钟内服完，尽剂而愈。", "19716": "治李姓妇人膨胀证。先经他医用苍术、槟榔、厚朴、枳实、香附、紫蔻之类辛燥开破，初服觉轻，七八剂后病转增剧，烦渴泄泻。又更他医，投以紫朴琥珀丸，烦渴益甚，一日夜泄泻十五六次，再诊时，医者辞不治。又延医数人，皆诿为不治。后乃一息奄奄，舁至床上两次，待时而已。其姻家有知生者强生往视。其脉如水上浮麻，不分至数，按之即无，惟两尺犹似有根，言语不真，仿佛可辨，自言心中大渴，少饮水即疼不可忍，盖不食者已三日矣。先投以滋阴清燥汤，为脉象虚甚，且气息有将脱之意，又加野台参、净萸肉，一剂，诸病皆愈，可以进食。遂俾用一味薯蓣粥，送服生鸡内金细末及西药百布圣，取其既可作药，又可作饭也。又即前方加减，日服一剂，旬日全愈。", "19717": "治胸中素蕴实热，又受外感。内热为外感所束，不能发泄。时觉烦躁，或喘、或胸胁疼，其脉洪滑而长者。", "19718": "一妇，年三十余。胸疼连胁，心中发热。服开胸、理气、清火之药不效。后愚诊视，其脉浮洪而长。知其上焦先有郁热，又为风寒所束，则风寒与郁热相搏而作疼也。治以此汤，加没药、川楝子各四钱，一剂得汗而愈。", "19719": "一叟，年过七旬。素有劳病。因冬令伤寒，劳病复发，喘而且咳，两三日间，痰涎壅盛，上焦烦热。诊其脉，洪长浮数。投以此汤，加玄参、潞参各四钱，一剂汗出而愈。", "19720": "门人刘××，曾治一人，年四十。外感痰喘甚剧。四五日间，脉象洪滑，舌苔白而微黄。刘××投以此汤，方中石膏用一两，连翘用三钱。一剂周身得汗，外感之热已退，而喘未全愈。再诊其脉，平和如常，微嫌无力。遂用拙拟从龙汤，去苏子，加潞参三钱，一剂全愈。愚闻之喜曰：外感痰喘，小青龙汤所主之证也。拙拟犹龙汤，原以代大青龙汤，今并可代小青龙汤，此愚之不及料也。将方中药味轻重，略为加减，即能另建奇功，以斯知方之运用在人，慧心者自能变通也。", "19721": "治寒温阳明证，表里俱热，心中热，嗜凉水，而不至燥渴，脉象洪滑，而不至甚实，舌苔白厚，或白而微黄，或有时背微恶寒者。", "19722": "一叟年七十有一，因感冒风寒，头疼异常，彻夜不寝。其脉洪大有力，表里俱发热，喜食凉物，大便三日未行，舌有白苔甚厚。知系伤寒之热，已入阳明之府。因头疼甚剧，且舌苔犹白，疑犹可汗解。治以拙拟寒解汤，加薄荷叶一钱。头疼如故，亦未出汗，脉益洪实。恍悟曰：此非外感表证之头疼，乃阳明经府之热，相并上逆，而冲头部也。为制此汤，分三次温饮下，头疼愈强半，夜间能安睡，大便亦通。复诊之，脉象余火犹炽，遂用仲景竹叶石膏汤，生石膏仍用三两，煎汁一大碗，分三次温饮下，尽剂而愈。", "19723": "按：竹叶石膏汤，原寒温大热退后，涤余热、复真阴之方。故其方不列于六经，而附载于六经之后。其所以能退余热者，不恃能用石膏，而恃石膏与参并用。盖寒温余热，在大热铄涸之余，其中必兼有虚热。石膏得人参，能使寒温后之真阴顿复，而余热自消，此仲景制方之妙也。又麦冬甘寒黏滞，虽能为滋阴之佐使，实能留邪不散，致成劳嗽。而惟与石膏、半夏并用，则无忌，诚以石膏能散邪，半夏能化滞也。或疑炙甘草汤（亦名复脉汤）中亦有麦冬，却无石膏、半夏。然有桂枝、生姜之辛温宣通者，以驾驭之，故亦不至留邪。彼惟知以甘寒退寒温之余热者，安能援以为口实哉！", "19724": "温病中，有当日得之，即宜服仙露汤者。一童子，年十六。暑日力田于烈日之中，午饭后，陡觉发热，无汗，烦渴引饮。诊其脉，洪而长，知其暑而兼温也。投以此汤，未尽剂而愈。", "19725": "上焦烦热太甚者，原非轻剂所能疗。而投以重剂，又恐药过病所，而病转不愈。惟用重剂，徐徐饮下，乃为合法。曾治一人，年四十余。素吸鸦片，于仲冬得伤寒，两三日间，烦躁无汗。原是大青龙汤证，因误服桂枝汤，烦躁益甚。迎愚诊视，其脉关前洪滑，两尺无力。为开仙露汤，因其尺弱，嘱其徐徐饮下，一次只饮药一口，防其寒凉侵下焦也。病家忽愚所嘱，竟顿饮之，遂致滑泻数次，多带冷沫。上焦益觉烦躁，鼻如烟熏，面如火炙。其关前脉，大于前一倍，又数至七至。知其已成戴阳之证，急用人参一两，煎好兑童便半茶蛊，将药碗置凉水盆中，候冷顿饮之。又急用玄参、生地、知母各一两，煎汤一大碗，候用。自服参后，屡诊其脉，过半点钟，脉象渐渐收敛，至数似又加数。遂急将候用之药炖热，徐徐饮下，一次饮药一口，阅两点钟尽剂，周身微汗而愈。此因病家不听所嘱，致有如此之失，幸而救愈，然亦险矣。审是，则凡药宜作数次服者，慎勿顿服也。盖愚自临证以来，无论内伤、外感，凡遇险证，皆煎一大剂，分多次服下。此以小心行其放胆，乃万全之策，非孤注之一掷也。", "19726": "《伤寒论》阳明篇中，白虎汤后，继以承气汤，以攻下肠中燥结，而又详载不可攻下诸证。诚以承气力猛，倘或审证不确，即足误事。愚治寒温三十余年，得一避难就易之法。凡遇阳明应下证，亦先投以大剂白虎汤一两剂。大便往往得通，病亦即愈。即间有服白虎汤数剂，大便犹不通者，而实火既消，津液自生，肠中不致干燥，大便自易降下。用玄明粉三钱，加蜂蜜或柿霜两许，开水冲调服下，大便即通。若仍有余火未尽，而大便不通者，单用生大黄末一钱（若凉水调服生大黄末一钱，可抵煮服者一两），蜜水调服，通其大便亦可。且通大便于服白虎汤后，更无下后不解之虞。盖下证略具，而脉近虚数者，遽以承气下之，原多有下后不解者，以其真阴亏、元气虚也。惟先服白虎汤或先服白虎加人参汤，去其实火，即以复其真阴，培其元气，而后微用降药通之，下后又何至不解乎。此亦愚百用不至一失之法也。", "19727": "间有用白虎汤润下大便，病仍不解，用大黄降之而后解者，以其肠中有匿藏之结粪也。曾治一媪，年七十余，季冬得伤寒证，七八日间，延愚诊视。其脉洪长有力，表里俱热，烦渴异常，大便自病后未行。投以白虎加人参汤二剂，大便遂通，一日降下三次，病稍见愈，而脉仍洪长。细审病情，当有结粪未下，遂单用大黄三钱，煮数沸服之，下结粪四五枚，病遂见愈，仍非脉净身凉，又用拙拟白虎加人参以山药代粳米汤，服未尽剂而愈。然此乃百中之一二也。临证者，不可因此生平仅遇之证，遂执为成法，轻视白虎，而重视承气也。", "19728": "重用石膏以退火之后，大便间有不通者，即可少用通利之药通之。此固愚常用之法，而随证制宜，又不可拘执成见。曾治一少年，伤寒已过旬日，阳明火实，大便燥结，投一大剂白虎汤，一日连进二剂，共用生石膏六两，至晚九点钟，火似见退，而精神恍惚，大便亦未通行，再诊其脉，变为弦象，夫弦主火衰，亦主气虚。知此证清解已过，而其大便仍不通者，因其元气亏损，不能运行白虎汤凉润之力也。遂单用人参五钱，煎汤俾服之，须臾大便即通，病亦遂愈。盖治此证的方，原是白虎加人参汤，因临证时审脉不确，但投以白虎汤，遂致病有变更。幸迷途未远，犹得急用人参，继所服白虎汤后以成功。诚以日间所服白虎汤，尽在腹中，得人参以助之，始能运化。是人参与白虎汤，前后分用之，亦无异于一时同用之也。益叹南阳制方之神妙，诚有令人不可思议者也。吴又可谓：「如人方肉食而病适来，以致停积在胃，用承气下之，惟是臭水稀粪而已，于承气汤中，单加人参一味，虽三四十日停积之物于是方下。盖承气借人参之力鼓舞胃气，宿物始动也。」又可此论，亦即愚用人参于白虎汤后，以通大便之理也。", "19729": "治温病初得，其脉浮而有力，身体壮热。并治一切感冒初得，身不恶寒而心中发热者。若其热已入阳明之腑，亦可用代白虎汤。", "19730": "沈阳朱姓妇，年五旬。于戊午季秋，得温病甚剧。时愚初至奉天，求为诊治。见其以冰囊作枕，复悬冰囊，贴面之上侧。盖从前求东人调治，如此治法，东人之所为也。合目昏昏似睡，大声呼之，毫无知觉。其脉洪大无伦，按之甚实。愚谓其夫曰：此病阳明腑热，已至极点。外治以冰，热愈内陷。然此病尚可为，非重用生石膏不可。其夫韪愚言，遂用生石膏细末四两、粳米八钱，煎取清汁四茶杯，徐徐温灌下。约历十点钟，将药服尽，豁然顿醒。后又用知母、花粉、玄参、白芍诸药，少加连翘以清其余热，服两剂全愈。", "19731": "季秋，敝处张氏之女得瘟病甚剧，服药无效，医言不治，病家以为无望。其母求人强仆往视，见其神昏如睡，高呼不觉；脉甚洪实。用先生所拟之石膏粳米汤，生石膏用三两，粳米用五钱。见者莫不惊讶诽笑。且有一老医扬言于人曰：「蔡某年仅二十，看书不过年余，竟大胆若此！石膏重用三两，纵煅透用之亦不可，况生者乎？此药下咽，人即死矣。」有人闻此言，急来相告，仆曰：「此方若用煅石膏，无须三两，即一两亦断送人命而有余。若用生者，即再多数两亦无碍，况仅三两乎。」遂急催病家购药，亲自监视，煎取清汤一大碗，徐徐温灌下。病人霍然顿醒。其家人惊喜异常，直以为死后重生矣。继而热疟流行，经仆重用生石膏治愈者不胜计。", "19732": "一妇人，年三十余，得温证。始则呕吐，五六日间，心下满闷，热而且渴。脉洪滑有力，舌苔黄厚。闻其未病之先，曾有郁怒未伸，因得斯证，俗名夹恼伤寒。然时当春杪，一得即不恶寒，乃温病，非伤寒也。为疏此方，有一医者在座，疑而问曰：此证因胃气上逆作胀满，始将白虎汤方，另为更定。何以方中不用开通气分之药，若承气汤之用厚朴、枳实，而惟用半夏、竹茹乎？答曰：白虎汤用意，与承气迥异。盖承气汤，乃导邪下行之药，白虎汤乃托邪外出之药。故服白虎汤后，多有得汗而解者。间有服后未即得汗，而大热既消，其饮食之时，恒得微汗，余热亦由此尽解。若因气逆胀满，恣用破气之药，伤其气分，不能托邪外出，将邪陷愈深，胀满转不能消，或更增剧。试观《伤寒论》多有因误下伤其气分，成结胸，成心下痞硬证，不可不知也。再试观诸泻心，不轻用破气之品，却有半夏泻心汤。又仲景治「伤寒解后，气逆欲呕」有竹叶石膏汤，半夏与石膏并用；治「妇人乳、中虚、烦乱、呕逆」有竹皮大丸，竹茹与石膏并用，是半夏、竹茹善降逆气可知也。今师二方之意，用之以易白虎汤中之甘草、粳米，降逆气而不伤正气，服后仍可托邪外出，由汗而解，而胀满之证，亦即消解无余。此方愚用之屡矣，未有不随手奏效者。医者闻言省悟，听愚用药，服后，病人自觉胀满之处，如以手推排下行，病亦遂愈。", "19733": "治寒温实热已入阳明之府，燥渴嗜饮凉水，脉象细数者。", "19734": "伤寒法，白虎汤用于汗、吐、下后当加人参。究之脉虚者，即宜加之，不必在汗、吐、下后也。愚自临证以来，遇阳明热炽，而其人素有内伤，或元气素弱，其脉或虚数，或细微者，皆投以白虎加人参汤。实验既久，知以生山药代粳米，则其方愈稳妥，见效亦愈速。盖粳米不过调和胃气，而山药兼能固摄下焦元气，使元气素虚者，不至因服石膏、知母而作滑泻。且山药多含有蛋白之汁，最善滋阴。白虎汤得此，既祛实火，又清虚热，内伤外感，须臾同愈。愚用此方救人多矣。略列数案于下，以资参考。", "19735": "一叟，年近六旬。素羸弱，劳嗽，得伤寒证，三日，昏愦不知人。诊其脉甚虚数，而肌肤烙手，确有实热。知其脉虚证实，邪火横恣，元气又不能支持，故传经犹未深入，而即昏愦若斯也。踌躇再四，乃放胆投以此汤。将药煎成，乘热徐徐灌之，一次只灌下两茶匙。阅三点钟，灌药两盅，豁然顿醒。再尽其余，而病愈矣。", "19736": "一叟，年六旬。素亦羸弱多病，得伤寒证，绵延十余日。舌苔黄厚而干，心中热渴，时觉烦躁。其不烦躁之时，即昏昏似睡，呼之，眼微开，精神之衰惫可知。脉象细数，按之无力。投以凉润之剂，因其脉虚，又加野台参佐之。大便忽滑泻，日下数次。因思此证，略用清火之药，即滑泻者，必其下焦之气化不固。先用药固其下焦，再清其上焦、中焦未晚也。遂用熟地黄二两，酸石榴一个，连皮捣烂，同煎汤一大碗。分三次温饮下，大便遂固。间日投以此方，将山药改用一两，以生地黄代知母，煎汤成，徐徐温饮下，一次只饮药一大口。阅八点钟，始尽剂，病愈强半。翌日，又按原方，如法煎服，病又愈强半。第三日，又按其方服之，尽剂而愈。", "19737": "按：熟地黄原非治寒温之药，而病至极危时，不妨用之，以救一时之急。故仲景治脉结代，有炙甘草汤，亦用干地黄（即今生地），结代亦险脉也。如无酸石榴时，可用龙骨（煅捣）、牡蛎（煅捣）各五钱代之。", "19738": "一叟，年六旬余。素吸鸦片，羸弱多病，于孟冬感冒风寒，其脉微弱而浮。愚用生黄耆数钱，同表散之药治之，得汗而愈。间日，因有紧务事，冒寒出门，汗后重感，比前较剧。病卧旅邸，不能旋里。因延彼处医者诊治，时身热饮水，病在阳明之府。医者因其脉微弱，转进温补，病益进。更延他医，以为上有浮热，下有实寒，用附子、吴茱萸，加黄连治之。服后，齿龈尽肿，且甚疼痛，时觉烦躁，频频饮水，不能解渴。不得已复来迎。愚至，诊其脉细而数，按之略实。遂投以此汤，加玄参六钱，以散其浮游之热。一剂牙疼即愈，烦躁与渴亦见轻。翌日，用原方去玄参，将药煎成，调入生鸡子黄三枚，作三次温饮下，大便得通而愈。", "19739": "一人，年二十，资禀素弱。偶觉气分不舒，医者用三棱、延胡等药破之。自觉短气，遂停药不敢服。隔两日，忽发喘逆，筋惕肉动，精神恍惚。脉数至六至，浮分摇摇，按之若无。肌肤甚热，上半身时出热汗，自言心为热迫，甚觉怔忡。其舌上微有白苔，中心似黄。统观此病情状，虽陡发于一日，其受外感，已非一日。盖其气分不舒时，即受外感之时，特其初不自觉耳。为其怔忡太甚，不暇取药，急用生鸡子黄四枚，温开水调和，再将其碗置开水盆中，候温服之，喘遂止，怔忡亦见愈。继投以此汤，煎汁一大碗，仍调入生鸡子黄三枚，徐徐温饮下。自晚十点钟至早七点钟，尽剂而病若失。因其从前服药伤气，俾用玄参一两、潞参五钱，连服数剂以善其后。", "19740": "一童子，年十七。于孟夏得温证，八九日间，呼吸迫促，频频咳吐，痰血相杂。其咳吐之时，疼连胸胁，上焦微嫌发闷。诊其脉，确有实热，而数至七至，摇摇无根。盖其资禀素弱，又兼读书劳心，其受外感又甚剧，故脉象若是之危险也。为其胸胁疼闷兼吐血，遂减方中人参之半，加竹茹、三七（捣细冲服）各二钱。用三七者，不但治吐血，实又兼治胸胁之疼也。一剂血即不吐，诸病亦见愈。又服一剂全愈。", "19741": "一农家孺子，年十一。因麦秋农家忙甚，虽幼童亦作劳田间，力薄不堪重劳，遂得温病。手足扰动，不能安卧，谵语不休，所言者皆劳力之事，昼夜目不能瞑。脉象虽实，却非洪滑。拟投以此汤，又虑小儿少阳之体，外邪方炽，不宜遽用人参，遂用生石膏两半、蝉蜕一钱，煎服后，诸病如故。复来询方，且言其苦于服药，昨所服者，呕吐将半。愚曰，单用生石膏二两，煎取清汁，徐徐温饮之，即可不吐。乃如言服之，病仍不愈。再为诊视，脉微热退，谵语益甚，精神昏昏，不省人事。急用野台参两半、生石膏二两，煎汁一大碗，分数次温饮下。身热脉起，目遂得瞑，手足稍安，仍作谵语。又于原渣加生石膏、麦冬各一两，煎汁二盅，分两次温饮下。降大便一次，其色甚黑，病遂愈。", "19742": "白虎汤者，宜常存一加人参之想也。又按：此案与前案观之，凡用白虎汤而宜加人参者，不必其脉现虚弱之象也。凡谂知其人劳心过度，或劳力过度，或在老年，或有宿疾，或热已入阳明之府，脉象虽实，而无洪滑之象，或脉有实热，而至数甚数者，用白虎汤时，皆宜酌加人参。", "19743": "寒温证表里皆虚，汗出淋漓，阳明胃腑，仍有实热者，用此汤时，宜加龙骨、牡蛎。一童子，年十六，于季冬得伤寒证。因医者用发表药太过，周身时时出汗，仍表里大热，心中怔忡，精神恍惚。脉象洪数，按之无力。遂用此汤，加龙骨、牡蛎（皆不煅）各一两，煎汁一大碗，分数次温饮下，尽剂而愈。", "19744": "仲景治伤寒脉结代者，用炙甘草汤，诚佳方也。愚治寒温，若其外感之热不盛，遇此等脉，即遵仲景之法。若其脉虽结代，而外感之火甚实者，亦用白虎加人参以山药代粳米汤。曾治一叟，年六旬余。于孟冬得伤寒证，五六日间，延愚诊视。其脉洪滑，按之亦似有力。表里俱觉发热，间作呻吟，又兼喘逆，然不甚剧。投以白虎汤，一剂大热稍减。再诊其脉，或七八动一止，或十余动一止，两手皆然，而重按无力。遂于原方中加人参八钱，兼师炙甘草汤中用干地黄之意，以生地代知母。煎汁两盅，分二次温饮下。脉即调匀，且较前有力，而热仍如故。从前方中生石膏二两遂加倍为四两，煎汁一大碗，俾徐徐温饮下，尽剂而愈。", "19745": "按：治此证时，愚习用白虎汤，而犹未习用白虎汤加参也。自此以后，凡年过六旬之人，即脉甚洪实，用白虎汤时，亦必少加人参二三钱。", "19746": "结代之脉虽并论，究之结脉轻于代脉，故结脉间有宜开通者。曾治一叟，年六十余，大便下血，医治三十余日，病益进。日下血十余次，且多血块，精神昏愦。延为诊视，脉洪实异常，至数不数，惟右部有止时，其止无定数，乃结脉也。其舌苔纯黑，知系温病大实之证。从前医者，但知治其便血，不知治其温病可异也。投以白虎加人参以山药代粳米汤，将石膏改用四两，煎汤三盅，分三次温饮下。每次送服旱三七细末一钱。如此日服一剂，两日血止，大便仍滑泻，脉象之洪实减半，而其结益甚，且腹中觉胀。询其病因，知得诸恼怒之后。遂改用莱菔子六钱，而佐以白芍、滑石、花粉、茅根、甘草诸药，一剂胀消。脉之至数调匀，仍稍有洪实之象，滑泻亦减。再投以滋阴清燥汤，一剂泻止，脉亦平和。", "19747": "寒温之证，最忌舌干。至舌苔薄而干，或干而且缩者，尤为险证。而究其原因，却非一致。有因真阴亏损者，有因气虚不上潮者，有因气虚更下陷者，皆可治以白虎加人参以山药代粳米汤。盖人参之性，大能补气，元气旺而上升，自无下陷之虞。而与石膏同用，又大能治外感中之真阴亏损，况又有山药、知母，以濡润之乎。若脉象虚数者，又宜多用人参，减石膏一两，再加玄参、生地滋阴之品。煎汁三四茶盅，徐徐温饮下，一次只饮一大口，防其寒凉下侵致大便滑泻。又欲其药力息息上达，助元气以生津液，饮完一剂，再煎一剂，使药力昼夜相继，数日舌润火退，其病自愈。一人年二十余，素劳力太过，即觉气分下陷。一岁之间，为治愈三次。至秋杪感冒时气，胸中烦热满闷，燥渴引饮，滑泻不止，微兼喘促。舌上无苔，其色鲜红，兼有砂粒。延医调治，投以半补半破之剂。意欲止其滑泻兼治其满闷也。服药二剂，滑泻不止。后愚为诊视，其脉似有实热，重按无力。遂先用拙拟加味天水散止其滑泻。方中生山药用两半、滑石用一两，一剂泻止。继服滋阴清火之剂，数剂喘促亦愈，火亦见退。唯舌干连喉，几不能言，频频饮水，不少濡润，胸中仍觉满闷。愚恍悟曰：此乃外感时气，挟旧病复发，故其脉象虽热，按之不实。其舌干如斯者，津液因气分下陷而不上潮也。其胸中满闷者，气分下陷，胸中必觉短气，病人不善言病情，故漫言满闷也。此时大便不行已五日。遂投以白虎加人参以山药代粳米汤，一剂病愈十之七八，而舌之干亦减半。又服一剂，大便得通，病觉全愈。舌上仍无津液，又用潞参一两、玄参两半，日服一剂，三日后舌上津液滋润矣。", "19748": "一童子，年十三，于孟冬得伤寒证。七八日间，喘息鼻煽动，精神昏愦，时作谵语，所言者皆劳力之事。其脉微细而数，按之无力。欲视其舌，干缩不能外伸，启齿探视，舌皮有瘢点作黑色，似苔非苔，频饮凉水，毫无濡润之意。愚曰：此病必得之劳力之余，胸中大气下陷，故津液不能上潮，气陷不能托火外出，故脉道瘀塞。不然，何以脉象若是，恣饮凉水而不滑泻乎？遂治以白虎加人参以山药代粳米汤，煎汁一大碗，徐徐温饮下，一昼夜间连进二剂，其病遂愈。", "19749": "按：脉虚数而舌干者，大便虽多日不行，断无可下之理，即舌苔黄而且黑亦不可下。惟按上所载治法，使其大便徐徐自通，方为稳善。若大便通后，而火犹炽，舌仍干者，可用潞参一两、玄参二两煮汁，徐徐饮之，以舌润火退为度。若或因服药失宜，大便通后，遂滑泻，其虚火上逆，舌仍干者，可用拙拟滋阴固下汤去滑石，加沙参数钱。若其为日既久，外感之火全消，而舌干神昏，或呼吸之间，常若气不舒，而时作太息者，此大气因服药下陷，病虽愈而不能自复也。宜单用人参两许煎汤服之，或少加柴胡亦可（此证有案在升陷汤下宜参观）。若微有余热，可加玄参佐之。", "19750": "寒温下后不解，医者至此，恒多束手。不知《伤寒论》原有治此证的方，即白虎加人参汤也。其一百六十八节云：「伤寒病，若吐、若下后，七、八日不解，热结在里，表里俱热，时时恶风，大渴、舌上干燥而烦，欲饮水数升者，白虎加人参汤主之。」愚生平治寒温，未有下后不解者，于仙露汤后曾详论之。然恒有经他医下后不解，更延愚为诊治者，其在下后多日，大便未行，脉象不虚弱者，即按《伤寒论》原方。若在甫下之后，或脉更兼虚弱，即以山药代粳米，或更以生地代知母，莫不随手奏效。盖甫下之后，大便不实，骤用寒凉，易至滑泻。而山药收涩，地黄黏润，以之代粳米、知母，实有固下之力，而于脉之兼虚弱者，则尤宜也。况二药皆能滋真阴，下后不解，多系阴分素虚之人，阴分充足，自能胜外感之余热也。", "19751": "白虎汤加人参，又以山药代粳米，既能补助气分托邪外出，更能生津止渴，滋阴退热，洵为完善之方。间有真阴太虚，又必重用滋阴之药以辅翼之，始能成功者。一媪，年过七旬，于孟夏得温证，五六日间，身热燥渴，精神昏愦，舌似无苔，而舌皮数处作黑色，干而且缩。脉细数，按之无力。当此高年，审证论脉，似在不治。而愚生平临证，明明见不可治之证，亦必苦心研究而设法治之，此诚热肠所迫，不能自已，然亦往往多有能救者。踌躇再四，为疏两方。一方即白虎加人参以山药代粳米汤，一方用熟地黄二两，生山药、枸杞各一两，真阿胶（不炒）五钱，煎汤后，调入生鸡子黄四枚。二方各煎汁一大碗，徐徐轮流温服，阅十点钟，尽剂而愈。自言从前服药，皆不知觉，此时则犹如梦醒。视其舌上犹干黑，然不缩矣。其脉至数仍数，似有余热。又用玄参二两、潞参一两煎汤一大碗，徐徐温服，一日一剂，两日大便得通。再视其舌，津液满布，黑皮有脱去者矣。", "19752": "隔数日，其夫年与相等，亦受温病。四五日间，烦热燥渴。遣人于八十里外致冰一担，日夜食之，烦渴如故。复迎愚诊治，其脉洪滑而长，重按有力，舌苔白厚，中心微黄。知其年虽高而火甚实也。遂投以白虎加人参以山药代粳米汤，将方中石膏改用四两，连进两剂，而热渴俱愈。其家人疑而问曰：此证从前日食冰若干，热渴分毫不退，今方中用生石膏数两，连进两剂而热渴俱愈，是石膏之性凉于冰远矣。愚曰：非也。石膏原不甚凉，然尽量食冰不愈而重用生石膏即愈者，因石膏生用能使寒温之热有出路也。西人不善治寒温，故遇寒温实热证最喜用冰，然多有不愈者。至石膏生用，性能发汗，其热可由汗解。即使服后无汗，亦可宣通内蕴之热，由腠理毛孔息息达出，人自不觉耳。", "19753": "按：此证与前证，年岁同，受病之时亦同。而一则辅以熟地、枸杞之类，以滋真阴；一则重加生石膏，以清大热。此乃随病、脉之虚实，活泼加减，所以投之辄效也。", "19754": "忆五年前，族家姊，年七旬有三，忽得瘫痪证，迎愚诊视。既至见有医者在座。用药一剂，其方系散风补气理痰之品，甚为稳善，愚亦未另立方。翌日，脉变洪长，知其已成伤寒证。先时，愚外祖家近族有病者，订于斯日迎愚，其车适至，愚将行，谓医者曰：此证乃瘫痪基础预伏于内，今因伤寒而发，乃两病偕来之证。然瘫痪病缓，伤寒病急。此证阳明实热，已现于脉，非投以白虎加人参汤不可，君须放胆用之，断无差谬。后医者终畏石膏寒凉，又疑瘫痪证不可轻用凉药。迟延二日，病势垂危，复急迎愚。及至，则已夜半矣。诊其脉，洪而且数，力能搏指，喘息甚促，舌强直，几不能言。幸喜药坊即在本村，急取白虎加人参汤一剂，方中生石膏用三两，煎汤两盅，分二次温饮下，病稍愈。又单取生石膏四两，煮汁一大碗，亦徐徐饮下，至正午尽剂而愈。后瘫痪证调治不愈，他医竟归咎于愚。谓从前用过若干石膏，所以不能调治。吁！年过七旬而瘫痪者，愈者几人？独不思愚用石膏之时，乃挽回已尽之人命也。且《金匮》治热瘫痫，有风引汤，原石膏与寒水石并用。彼谤愚者，生平盖未见《金匮》也。", "19755": "尝治一少年，素羸弱多病。于初夏得温证，表里俱热，延医调治不愈。适愚自他处治病归，经过其处，因与其父素稔，入视之。其脉数近六至，虽非洪滑鼓指，而确有实热。舌苔微黄，虽不甚干，毫无津液。有煎就药一剂未服，仍系发表之剂，乃当日延医所疏方，其医则已去矣。愚因谓其父曰：此病外感实热，已入阳明之府。其脉象不洪滑者，元气素虚故也。阳明府热之证，断无发表之理。况其脉数液短，兼有真阴虚损之象尤忌发汗乎。其父似有会悟，求愚另为疏方。本拟用白虎加人参汤，又思用人参，即须多用石膏，其父素小心过度，又恐其生疑不敢服，遂但为开白虎汤，方中生石膏用二两。嘱其煎汁两茶盅，分二次温饮下，服后若余火不净，仍宜再服清火之药。言毕，愚即旋里。后闻其服药后，病亦遂愈。迟十余日，大便又燥结，两腿微肿，将再迎愚诊治。而其父友人有自谓知医者，言其腿肿，系多服生石膏之过。而孰知系服石膏犹少之过哉！病家竟误听其言，改延他医，投以大剂承气汤，服后其人即不语矣，迁延数日而亡。夫自谓知医者，不过欲炫己之长，而妄指他人之短。岂知其言之一出，即足误人性命哉！", "19756": "至产后之证，忌用寒凉。而果系产后温证，心中燥热，舌苔黄厚，脉象洪实，亦宜投以白虎加人参以山药代粳米汤，而更以玄参代知母则尤妥善。盖愚于产后温证之轻者，其热虽入阳明之府，脉象不甚洪实，恒重用玄参一两或至二两，辄能应手奏效；若系剧者，必白虎加人参以山药代粳米汤，而更以玄参代知母方能有效。诚以石膏、玄参，《神农本草经》皆明载其治产乳。故于产后温病之轻者，可单用玄参。至温病之剧者，不妨石膏、玄参并用也。然用石膏必须佐以人参，因其时当产后，其热虽实，而体则虚也。不用知母者，《神农本草经》未载其治产乳，不敢师心自用，漫以凉药治产后也。", "19757": "友人吴××，深通医学，其侄××亦知医，有戚家延之治产后病。临行，吴××嘱之曰：果系产后温热，阳明胃府大实，非用《衷中参西录》中白虎加人参以山药代粳米汤，更以玄参代知母不可。及至诊之，果系产后温证，病脉皆甚实。××遵所嘱，开方取药。而药坊皆不肯与，谓产后断无用生石膏之理，病家因此生疑，××辞归。病家又延医治数日，病势垂危，复求为诊治。携药而往，如法服之，一剂而愈。", "19758": "赵××，患温病。医者投以桂枝汤，觉热渴气促。又与柴胡汤，热尤甚，且增喘嗽，频吐痰涎，不得卧者六七日。医者谓病甚重，不能为矣。举家闻之，惶恐无措。伊弟××延为诊治。既至，见病人喘促肩息，头汗自出，表里皆热，舌苔深灰，缩不能言。急诊其脉，浮数有力，重按甚空。因思此证阳明热极，阴分将竭，实为误服桂枝、柴胡之坏证。急投以白虎加人参以山药代粳米汤，更以玄参代知母。连服两剂，渴愈喘止，脉不浮数，仍然有力，舌伸能言，而痰嗽不甚见轻。继投以从龙汤，去苏子，加人参四钱，天冬八钱，服七剂全愈。", "19759": "又：一赵姓妇，年二十余，产后八九日，忽得温病。因误用热药发汗，致热渴喘促，舌苔干黑，循衣摸床，呼索凉水，病家不敢与。脉弦数有力，一息七至。急投以白虎加人参以山药代粳米汤，为系产后，更以玄参代知母。方中生石膏，重用至四两。又加生地、白芍各数钱。煎汤一大碗，分四次温饮下，尽剂而愈。当时有知医者在座，疑而问曰：「产后忌用寒凉，何以如此放胆，重用生石膏？且知母、玄参皆系寒凉之品，何以必用玄参易知母？」答曰：「此理俱在《衷中参西录》中」，遂于行箧中出书示知，医者细观移时，始喟然叹服。", "19760": "又：外祖家表妹，因产后病温，服补药二十余剂，致大热、大渴、大汗，屡索凉水。医者禁勿与饮，急欲投井。及生视之，舌黑唇焦，目睛直视，谵语发狂。诊其脉，细数有力。问其小便赤涩，大便紫黑黏滞，不甚通利。盖以产后血虚，又得温病，兼为补药所误，以致外邪无由而出，内热如焚，阴血转瞬告罄。急投以白虎加人参汤，仍用山药、玄参代粳米、知母。服后，一夜安稳。黎明，旋又反复，热渴又如从前。细思产后血室空虚，邪热乘虚而入，故大便紫黑，宜调以桃仁承气汤，以下其瘀血，邪热当随之俱下。因小便赤涩，膀胱蓄热，又加滑石四钱，甘草钱半。乃开药房者系其本族，谓此药断不可服。病家疑甚，复延前医相质。前医谓，此病余连治三次，投以温补药转剧，昨服白虎加人参汤，既稍见轻，想服承气汤亦无妨也。病家闻之，始敢煎服。因方中大黄重用六钱，俾煎汤一盅半，分三次温饮下。逾三点钟，降下大便如胶漆者二次，鲜红色者一次，小便亦清利，脉净身凉而愈。", "19761": "又：赵××之子，年十九岁，偶得温病，医者下之太早，大便转不通者十八日，热渴喘满，舌苔干黑，牙龈出血，目盲谵语，腹胀如鼓，脐突出二寸，屡治不效。忽大便自利，完谷不化，随食随即泻出。诊其脉，尽伏。身冷厥逆，气息将无。乍临茫然不知所措，细询从前病状及所服之药，始悟为阳极似阴，热深厥亦深也。然须用药将其滑泻止住，不复热邪旁流，而后能治其热厥。遂急用野台参三钱，大熟地、生山药、滑石各六钱。煎服后，泻止脉出，洪长滑数，右部尤甚。继拟以大剂白虎加人参汤，生石膏重用至八两。竟身热厥回，一夜甚安。至明晨，病又如故。试按其腹中，有坚块，重按眉皱似疼，且其腹胀脐突若此，知其内有燥粪甚多。遂改用大黄一两，芒硝六钱，赭石、蒌仁各八钱，煎汤一大盅，分两次温饮下。下燥粪二十七枚而愈。", "19762": "本村张氏妇，得温病，继而小产，犹不以为意。越四五日，其病大发。遍请医生，均谓瘟病小产，又兼邪热太甚，无方可治。其夫造门求为诊治。生至其家，见病人目不识人；神气恍惚；渴嗜饮水，大便滑泻；脉数近八至，且微细无力；舌苔边黄中黑，缩不能伸。为其燥热，又兼滑泻，先投以滋阴清燥汤，一剂泻止，热稍见愈。继投以大剂白虎加人参以山药代粳米汤，为其产后，以玄参代知母，为其舌缩脉数，阴分大亏，又加枸杞、生地。煎汤一大碗，调入生鸡子黄三枚，分数次徐徐温饮下。精神清爽，舌能伸出，连服三剂全愈。", "19763": "一周姓叟，年近七旬，素有劳疾，且又有鸦片嗜好，于季秋患温病，阳明府热炽盛，脉象数而不实，喘而兼嗽，吐痰稠黏。投以白虎加人参汤，以生山药代粳米，一剂，大热已退，而喘嗽仍不愈，且气息微弱，似不接续。其家属惶恐，以为难愈。且言如此光景，似难再进药。愚曰：勿须用药，寻常服食之物即可治愈矣。为开此方，病家视之，果系寻常食物，知虽不对证，亦无妨碍。遂如法服之，二剂全愈。", "19764": "一媪，年六十余。当孟夏晨饭之际，忽闻乡邻有斗者，出视之，见强者凌弱太甚，心甚不平；又兼饭后有汗受风，遂得温证。表里俱热，胃口杜塞，腹中疼痛，饮水须臾仍吐出。七八日间，大便不通。其脉细数，按之略实。自言心中燥渴，饮水又不能受，从前服药止吐，其药亦皆吐出。若果能令饮水不吐，病犹可望愈。愚曰：易耳。为开此汤，加生石膏二两、野台参五钱，煎汤一大碗，分三次温饮下。晚间服药，翌晨大便得通而愈。当大便未通时，曾俾用山萸肉（去净核）二两煎汤，以备下后心中怔忡及虚脱，及大便通后，微觉怔忡，服之即安。", "19765": "一室女得温病。两三日间，痰涎郁塞，胸膈满闷异常，频频咳吐，黏若胶漆，且有喘促之意，饮水停滞胃口，间或吐出，其脉浮滑。问之微觉头疼，知其表证犹未罢也。遂师河间双解散之意，于荡胸汤中加连翘、蝉蜕各三钱。服后微汗，大便得通而愈。", "19766": "奉天许××，年二十余。得温病。三四日觉中脘郁结，饮食至其处不下行，仍上逆吐出。来院求为诊治。其脉沉滑而实，舌苔白而微黄。表里俱觉发热，然不甚剧。自言素多痰饮，受外感益甚。因知其中脘之郁结，确系外感之邪与痰饮相凝滞也。先投以荡胸汤，两点钟后，仍复吐出。为拟此方，一剂结开，可受饮食。继投以清火理痰之品，两剂全愈。", "19767": "一邻妇，年二十余。得温病已过十日，上焦燥热，呕吐，大便燥结，自病后未行。延医数次服药皆吐出。适愚自他处归，诊其脉，关前甚洪实，一息五至余，其脉上盛于下一倍，所以作呕吐。其至数数者，吐久伤津液也。为拟此汤，一剂热退呕止，大便得通而愈。", "19768": "一妇人，年四十许，得大头瘟证。头面肿大疼痛，两目肿不能开，上焦烦热，心中怔忡。彼家误为疮毒，竟延疡医治疗。医者自出药末，敷头面，疼稍愈。求其出方治烦热怔忡，彼言专习外科，不管心中之病。时愚应他家延请，适至其村，求为诊治。其脉洪滑有力，关前益甚，投以清盂汤，将方中石膏改用二两，煎汁两茶盅，分二次温饮下，尽剂而愈。", "19769": "一人，年二十余，得温疫。三四日间头面悉肿，其肿处，皮肤内含黄水，破后且溃烂。身上间有斑点，闻人言，此证名大头瘟。其溃烂之状，又似瓜瓤瘟，最不易治。惧甚，求为诊视。其脉洪滑而长，舌苔白而微黄。问其心中，惟觉烦热，嗜食凉物。遂晓之曰，此证不难治。头面之肿烂，周身之斑点，无非热毒入胃而随胃气外现之象。能放胆服生石膏，可保全愈。遂投以青盂汤，方中石膏改用三两，知母改用八钱，煎汁一大碗，分数次温饮下。一剂病愈强半。翌日，于方中减去荷叶、蝉蜕，又服一剂全愈。", "19770": "吕沧洲云：一人伤寒十余日，身热而静，两手脉尽伏。医者以为坏证，弗与药。余诊之，三部脉举按皆无，舌苔滑，两颧赤如火，语言不乱，因告之曰：此子必大发赤斑，周身如锦纹。夫血脉之波澜也，今血为邪热所搏，掉而为斑，外现于皮肤，呼吸之气无形可倚，犹沟渠之水虽有风不能成波澜也，斑消则脉出矣。及揭其衾，而赤斑烂然。与白虎加人参汤，化其斑脉乃复常。按：发斑至于无脉，其证可谓险矣。即遇有识者，细诊病情，以为可治，亦必谓毒火郁热盘踞经络之间以阻塞脉道之路耳。而沧洲独断为发斑则伤血，血伤则脉不见。是诚沧洲之创论，然其言固信而有征也。忆己亥春，尝治一少年吐血证。其人大口吐血，数日不止，脉若有若无，用药止其血后，脉因火退，转分毫不见。愚放胆用药调补之，竟得无恙（此证详案在寒降汤下）。夫吐血过多可至无脉，以征沧洲血伤无脉之说确乎可信。此阳毒发斑也。", "19771": "许叔微治一人，内寒外热而发斑。六脉沉细，肩背胸胁斑出数点，随出随隐，旋更发出，语言狂乱，非谵语也，肌表虽热，以手按之，须臾冷透如冰。与姜附等药数服后，得大汗而愈。此阴毒发斑也。", "19772": "吴仁斋治一人，伤寒七八日，因服凉药太过，遂变身冷，手足厥逆，通身黑斑，惟心头温暖，乃伏火也。诊其六脉沉细，昏沉不知人事，亦不能言语，状似尸厥。遂用人参三白汤，加熟附子半枚、干姜二钱，水煎服下。待一时许，斑色渐红，手足渐暖。而苏醒后，复有余热不清，此伏火后作也。以黄连解毒汤、竹叶石膏汤调之而愈。此阴毒发斑中有伏阳也。", "19773": "瘟疫之毒，随呼吸之气传入，原可入肺。心与肺同居膈上，且左心房之血脉管与右心房之回血管，又皆与肺循环相通，其相传似甚易。而此证不常有者，因有包络护于心上代心受邪，由包络下传三焦，为手厥阴，少阳脏腑之相传，此心所以不易受邪也。愚临证二十余年，仅遇一媪患此证，为拟此方，服之而愈。", "19774": "奉天友人朱××之子，年五岁。于庚申立夏后，周身壮热，出疹甚稠密，脉甚洪数，舌苔白厚，知其疹而兼瘟也。欲以凉药清解之，因其素有心下作疼之病，出疹后，贪食鲜果，前一日犹觉疼，又不敢投以重剂。遂勉用生石膏、玄参各六钱，薄荷叶、蝉蜕各一钱，连翘二钱。晚间服药，至翌日午后视之，其热益甚，喉疼，气息甚粗，鼻翅煽动，且自鼻中出血少许，有烦躁不安之意。愚不得已，重用生石膏三两，玄参、麦冬（带心）各四钱，仍少佐以薄荷叶、连翘诸药。俾煎汤二茶盅，分三次温饮下。至翌日视之，则诸证皆轻减矣。然余热犹炽，而大便虽下一次，仍系燥粪。询其心犹发热，脉仍有力。遂于凉解药中，仍用生石膏一两，连服两剂，壮热始退。继用凉润清解之剂调之全愈。", "19775": "治久疟不愈，脉象弦而无力。", "19776": "疟邪不专在少阳，而实以少阳为主，故其六脉恒露弦象。其先寒者，少阳之邪外与太阳并也，其后热者，少阳之邪内与阳明并也。故方中用柴胡以升少阳之邪，草果、生姜以祛太阳之寒，黄芩、知母以清阳明之热。又疟之成也，多挟痰挟食，故用半夏、常山以豁痰，酒曲以消食也。用人参，因其疟久气虚，扶其正即所以逐邪外出。用鳖甲者，因疟久则胁下结有痞积（方书名疟母实由肝脾胀大），消其痞积，然后能断疟根株。用甘草、大枣者，所以化常山之猛烈而服之不至瞑眩也。", "19777": "或问：叶氏治疟，遇其人阴虚燥热者，恒以青蒿代柴胡。后之论者，皆赞其用药，得化裁通变之妙。不知青蒿果可以代柴胡乎？答曰：疟邪伏于胁下两板油中，乃足少阳经之大都会。柴胡之力，能入其中，升提疟邪透膈上出，而青蒿无斯力也。若遇阴虚者，或热入于血分者，不妨多用滋阴凉血之药佐之。若遇燥热者，或热盛于气分者，不妨多用清燥散火之药佐之。曾治一人，疟间日一发，热时若燔，即不发疟之日，亦觉心中发热，舌燥口干，脉象弦长（凡疟脉皆弦）重按甚实，知其阳明火盛也。投以大剂白虎汤，加柴胡三钱。服后顿觉心中清爽，翌晨疟即未发。又煎前剂之半，加生姜三钱，服之而愈。", "19778": "又尝治一人得温病，热入阳明之府，舌苔黄厚，脉象洪长，又间日一作寒热，此温而兼疟也。然其人素有鸦片嗜好，病虽实，而身体素虚。投以拙拟白虎加人参以麦冬代知母、山药代粳米汤，亦少加柴胡，两剂而愈。", "19779": "方书谓冬冷多温病，夏热多疟疾。此言冬日过冷，人身有伏寒，至春随春阳化热，即多成温病；夏日过热，人身有伏暑，至秋为薄寒所激发，即多生疟疾也。丁卯季夏，暑热异常，京津一带因热而死者甚多，至秋果多疟疾。服西药金鸡纳霜亦可愈，而愈后恒屡次反复。姻家王姓少年，寄居津门，服金鸡纳霜愈疟三次后，又反复。连服前药数次，竟毫无效验。诊其脉，左右皆弦长有力。夫弦为疟脉，其长而有力者，显系有伏暑之热也。为开白虎汤方，重用生石膏二两，又加柴胡、何首乌各二钱，一剂而疟愈。恐未除根，即原方又服一剂，从此而病不反复矣。此方用白虎汤以解伏暑，而又加柴胡、何首乌者，凡外感之证其脉有弦象者，必兼有少阳之病，宜用柴胡清之；而外邪久在少阳，其经必虚，又宜用何首乌补之。二药并用，一扶正，一逐邪也。少阳与阳明并治，是以伏暑愈而疟亦随愈也。", "19780": "一媪，年近六旬。资禀素弱，又兼家务劳心，遂致心中怔忡，肝气郁结，胸腹胀满，不能饮食，舌有黑苔，大便燥结，十数日一行。广延医者为治，半载无效，而羸弱支离，病势转增。后愚诊视，脉细如丝，微有弦意，幸至数如常，知犹可治。遂投以升降汤，为舌黑便结，加鲜地骨皮一两，数剂后，舌黑与便结渐愈，而地骨皮亦渐减。至十剂病愈强半，共服百剂，病愈而体转健康。", "19781": "族侄妇，年二十余，素性谨言，情志抑郁。因气分不舒，致四肢痉挛颤动，呼吸短促，胸中胀闷，约一昼夜。先延针科医治，云是鸡爪风，为刺囟门及十指尖，稍愈，旋即复作如故。其脉左部弦细，右部似有似无，一分钟数至百至。其两肩抬动，气逆作喘。询知其素不健壮，廉于饮食。盖肝属木而主筋，肝郁不舒则筋挛，肝郁恒侮其所胜，故脾土受伤而食少。遂为开培脾舒肝汤。为有逆气上干，又加生赭石细末五钱。嘱服二剂。痉挛即愈，气息亦平。遂去赭石，照原方又服数剂，以善其后。", "19782": "仲冬，刘××兄，病左胁掀疼，诸治无效，询方于弟。授以活络效灵丹方，服之不应，因延为诊视。脉象他部皆微弱，惟左关沉而有力。治以金铃泻肝汤，加当归数钱。服一剂，翌日降下若干绿色黏滞之物，遂豁然而愈。盖此汤原注明治胁下掀疼，由此知兄所拟方各有主治，方病相投，莫不神效也。", "19783": "高××年近五旬。资禀素羸弱。一日访友邻村，饮酒谈宴，彻夜不眠，时当季冬，复清晨冒寒，步行旋里。行至中途，觉两腿酸麻，且出汗，不能行步，因坐凉地歇息，至家，遂觉腿痛，用热砖熨之疼益甚。其人素知医，遂自服发汗之药数剂，病又增剧，因服药过热，吐血数口，大便燥结，延愚诊视。见其仰卧屈膝，令两人各以手托其两腿，忽歌忽哭，疼楚之态万状，脉弦细，至数微数。因思此证，热砖熨而益疼者，逼寒内陷也；服发汗药而益疼者，因所服之药，散肌肉之寒，不能散筋骨之寒，且过汗必伤气血，血气伤，愈不能胜病也。遂用活络效灵丹，加京鹿角胶四钱（另炖兑服）、明天麻二钱，煎汤饮下，左腿遂愈。而右腿疼如故，遂复用原方，以虎骨胶易鹿角胶，右腿亦出凉气如左而愈。", "19784": "一妇人，年五十余。项后筋缩作疼，头向后仰，不能平视，腰背强直，下连膝后及足跟大筋皆疼，并牵周身皆有疼意。广延医者诊治，所用之药，不外散风、和血、润筋、通络之品。两载无效，病转增剧，卧不能起，起不能坐，饮食懒进。后愚诊视，其脉数而有力，微有弦意，知其为宗筋受病。治以活络效灵丹，加生薏米八钱，知母、玄参、白芍各三钱，连服三十剂而愈。", "19785": "盖筋属于肝，独宗筋属胃，此证因胃腑素有燥热，致津液短少，不能荣养宗筋。夫宗筋为筋之主，故宗筋拘挛，而周身牵引作疼也。薏米性味冲和，善能清补脾胃，即能荣养宗筋。又加知母、玄参，以生津滋液，活络效灵丹，以活血舒筋，因其脉微弦，恐其木盛侮土，故又加芍药以和肝，即以扶脾胃也。", "19786": "活络效灵丹，治心腹疼痛，无论因凉、因热、气郁、血郁皆效。同里有一少年，脐下疼甚剧。医者投以温药益甚，昼夜号呼不止。又延他医，以药下之稍轻，然仍昼夜呻吟，继又服药数剂，亦不见效。适愚自津门旋里，诊其脉，两尺洪实。询其得病之由，言夜晚将寝觉饥，因食冷饼一块，眠起遂疼。晓之曰，此虽由于食凉物，然其疼非凉疼，乃下焦先有蕴热，又为凉物所迫，其热愈结而不散也。投以活络效灵丹，加龙胆草、川楝子各四钱，一剂而愈。", "19787": "族兄×，年三十余，素强壮无病。壬戌中秋，因在田间掘壑，劳苦过甚，自觉气力不支，即在壑中吃烟休息，少缓须臾又复力作。至晚归家时，途中步行，觉两腿酸木不仁。及至夜间，两腿抽疼甚剧。适生在里，其弟扣门求为往治。诊其脉，迟滞而细，号呼不已，气逆不顺，身冷，小溲不利。遂用活络效灵丹方，加白芍三钱、桂枝尖二钱、生姜三片。一剂腿疼大减，小便即利，身冷亦退。再剂，霍然全愈。", "19788": "又：天津王媪，年五十七岁，右膝盖部发炎，红热肿疼，食减不眠。其嗣××延为诊视。至其家，闻病者呼号不止，口称救命。其右脉洪数有力，心悸头眩，舌苔白而腻，大便三日未行，小便赤热。此足征湿热下注。予以活络效灵丹，加生石膏六钱，知母、怀牛膝、生薏米冬四钱，甘草梢一钱，嘱服一剂。次日自能来寓，其疼减肿消，夜已成寐，尚云右臂酸疼。又即原方加青连翘、金银花、油松节各二钱，服之全愈。", "19789": "证寒在经络，不在脏腑。经络多行于肌肉之间，故用黄耆之温补肌肉者为君，俾其形体壮旺，自能胜邪。又佐以温经络、通经络诸药品，不但能祛寒，且能散风，此所谓血活风自去也。风寒既去，血脉活泼，其搐焉有不止者乎？", "19790": "一室女腿疼，几不能步，治以拙拟健运汤而愈。次年旧病复发，又兼腰疼，再服前方不效。诊其脉，右关甚濡弱，询其饮食减少，为制此汤，数剂，饮食加多，二十剂后，腰疼腿疼皆愈。", "19791": "一媪，年近七旬。陡然腿疼，不能行动，夜间疼不能寐。其家人迎愚调治，谓脉象有力，当是火郁作疼。及诊其脉，大而且弦，问其心中亦无热意。愚曰：此脉非有火之象，其大也，乃脾胃过虚，真气外泄也。其弦也，乃肝胆失和，木盛侮土也。治以振中汤，加人参、白芍、山萸肉（去净核）各数钱，补脾胃之虚，即以抑肝胆之盛，数剂而愈。", "19792": "治肝虚腿疼，左部脉微弱者。", "19793": "服药数剂后，左脉仍不起者，可加续断三钱，或更加生黄耆三钱，以助气分亦可。觉凉者，可减知母。", "19794": "脾虚可令人腿疼，前方已详其理，深于医学者大抵皆能知之。至肝虚可令人腿疼，方书罕言，即深于医学者，亦恒不知。曾治一人，年三十许，当大怒之后，渐觉腿疼，日甚一日，两月后，卧床不能转侧。医者因其得之恼怒之余，皆用舒肝理气之药，病转加剧。后愚诊视，其左脉甚微弱，自言凡疼甚之处皆热。因恍悟《内经》谓「过怒则伤肝」，所谓伤肝者，乃伤肝经之气血，非必郁肝经之气血也，气血伤，则虚弱随之，故其脉象如斯也。其所以腿疼且觉热者，因肝主疏泄，中藏相火（相火生于命门寄于肝胆），肝虚不能疏泄，相火即不能逍遥流行于周身，以致郁于经络之间，与气血凝滞，而作热作疼，所以热剧之处，疼亦剧也。为制此汤，以萸肉补肝，以知母泻热，更以当归、乳香诸流通血气之药佐之，连服十剂，热愈疼止，步履如常。", "19795": "安东友人刘××，年五十许。其左臂常觉发热，且有酸软之意。医者屡次投以凉剂，发热如故，转觉脾胃消化力减少。后愚诊之，右脉和平如常，左脉微弱，较差于右脉一倍。询其心中，不觉凉热。知其肝木之气虚弱，不能条畅敷荣，其中所寄之相火，郁于左臂之经络，而作热也。遂治以曲直汤，加生黄耆八钱，佐萸肉以壮旺肝气，赤芍药三钱，佐当归、丹参诸药以流通经络，服两剂，左脉即见起，又服十剂全愈。", "19796": "奉天王××，年四十余，两胁下连腿作疼，其疼剧之时，有如锥刺，且尿道艰涩，滴沥不能成溜，每小便一次，须多半点钟，其脉亦右部如常，左部微弱。亦投以曲直汤，加生黄耆八钱，续断三钱，一剂其疼减半，小便亦觉顺利。再诊之，左脉较前有力。又按原方略为加减，连服二十余剂，胁与腿之疼皆愈，小便亦通利如常。盖两胁为肝之部位，肝气壮旺上达，自不下郁而作疼。至其小便亦通利者，因肾为二便之关，肝气既旺，自能为肾行气也（古方书有肝行肾之气之语）。", "19797": "铁锈乃铁与养气化合而成。人身之血得养气而赤。铁锈中含养气，而又色赤似血，且嗅之兼有血腥之气，故能荣养血分，流通经脉。且人之血中，实有铁锈，以铁锈补血更有以铁补铁之妙也。金鸡纳霜有治疟之功用。此方中亦用之者，为其善治贫血，且又能入手、足少阳之经，以调和寒热也。又佐以花椒者，恐金鸡纳霜之性，偏于寒凉，而以辛热济之，使归于和平也。", "19798": "东亚人有中将汤，以调妇女经脉，恒有效验。门人高××曾开其方相寄，药品下未有分量。愚为酌定其分量，用之甚有功效。今将其方开列于下，以备选用。", "19799": "延胡索醋炒三钱、当归六钱、官桂二钱、甘草二钱、丁香二钱、山楂核醋炒三钱、郁金醋炒二钱、沙参四钱、续断酒炒三钱、肉蔻赤石脂炒三钱（去石脂不用）、苦参三钱、怀牛膝三钱，共十二味，轧作粗渣，分三剂。每用一剂，开水浸盖碗中约半点钟，将其汤饮下。如此浸服二次至第三次用水煎服。日用一剂，数剂经脉自调。此方中凉热、补破、涩滑之药皆有，愚所酌分量，俾其力亦适相当，故凡妇女经脉不调证，皆可服之，而以治白带证尤效。", "19800": "服之觉闷者，减去于术。觉气弱者，减三棱、莪术各一钱。泻者，以白芍代知母，于术改用四钱。热者，加生地、天冬各数钱。凉者，知母、花粉各减半，或皆不用。凉甚者，加肉桂（捣细冲服）、乌附子各二钱。瘀血坚甚者，加生水蛭（不用炙）二钱。若其人坚壮无他病，惟用以消症瘕积聚者，宜去山药。室女与妇人未产育者，若用此方，三棱、莪术宜斟酌少用，减知母之半，加生地黄数钱，以濡血分之枯。若其人血分虽瘀，而未见症瘕或月信犹未闭者，虽在已产育之妇人，亦少用三棱、莪术。若病人身体羸弱，脉象虚数者，去三棱、莪术，将鸡内金改用四钱，因此药能化瘀血，又不伤气分也。迨气血渐壮，瘀血未尽消者，再用三棱、莪术未晚。若男子劳瘵，三棱、莪术亦宜少用或用鸡内金代之亦可。初拟此方时，原专治产后瘀血成症瘕，后以治室女月闭血枯亦效，又间用以治男子劳瘵亦效验，大有开胃进食，扶羸起衰之功。《内经》有四乌鲗鱼骨一茹芦丸，原是男女并治，为调血补虚之良方。此方窃师《内经》之意也。", "19801": "一妇人，年三十余。症瘕起于少腹，渐长而上。其当年长者稍软，隔年即硬如石。七年之间，上至心口，旁塞两肋，饮食减少，时觉昏愦，剧时昏睡一昼夜，不饮不食，屡次服药竟分毫无效。后愚为诊视，脉虽虚弱，至数不数，许为治愈，授以此方。病人自揣其病，断无可治之理，竟置不服。次年病益进，昏睡四日不醒。愚用药救醒之，遂恳切告之曰：去岁若用愚方，病愈已久，何至危困若斯。然此病尚可为，甚勿再迟延也，仍为开前方。病人喜，信愚言，连服三十余剂，磊块皆消。惟最初所结之病根，大如核桃之巨者尚在。又加生水蛭（不宜炙）一钱，服数剂全愈。", "19802": "一媪，年六旬。气弱而且郁，心腹满闷，不能饮食，一日所进谷食，不过两许，如此已月余矣。愚诊视之，其脉甚微细，犹喜至数调匀，知其可治。遂用此汤，将三棱、莪术各减一钱，连服数剂，即能进饮食。又服数剂，病遂全愈。", "19803": "奉天孙姓妇，年四十许。自幼时有症瘕结于下脘，历二十余年。症瘕之积，竟至满腹，常常作疼，心中怔忡，不能饮食，求为诊治。因思此证，久而且剧，非轻剂所能疗。幸脉有根柢，犹可调治。遂投以理冲汤，加水蛭三钱。恐开破之力太过，参、耆又各加一钱，又加天冬三钱，以解参、耆之热。数剂后，遂能进食。服至四十余剂，下瘀积若干，症瘕消有强半。因有事还籍，药遂停止。阅一载，腹中之积，又将复旧，复来院求为诊治。仍照前方加减，俾其补破凉热之间，与病体适宜。仍服四十余剂，积下数块。又继服三十余剂，瘀积大下。其中或片或块且有膜甚厚，若胞形。此时身体觉弱，而腹中甚松畅。恐瘀犹未净，又调以补正活血之药，以善其后。", "19804": "一少年，因治吐血，服药失宜，痃癖结于少腹（在女子为症瘕在男子为痃癖）大如锦瓜。按之甚坚硬，其上相连有如瓜蔓一条，斜冲心口，饮食减少，形体羸弱。其脉微细稍数。治以此汤，服十余剂痃癖全消。", "19805": "一妇人，年三十余。夫妻反目，恼怒之余，经行不止，且又甚多。医者用十灰散加减，连服四剂不效。后愚诊视，其右脉弱而且濡。询其饮食多寡，言分毫不敢多食，多即泄泻。遂投以此汤，去黄耆，将白术改用一两。一剂血止，而泻亦愈。又服一剂，以善其后。", "19806": "一妇人，年二十余。小产后数日，恶露已尽，至七八日，忽又下血。延医服药，二十余日不止。诊其脉，洪滑有力，心中热而且渴。疑其夹杂外感，询之身不觉热，又疑其血热妄行，遂将方中生地改用一两，又加知母一两，服后血不止，而热渴亦如故。因思此证，实兼外感无疑。遂改用白虎加人参汤以山药代粳米。方中石膏重用生者三两。煎汤两盅，分两次温饮下。外感之火遂消，血亦见止。仍与安冲汤，一剂遂全愈。又服数剂，以善其后。", "19807": "王氏妇，年十九岁，因殇子过痛，肝气不畅，经水行时多而且久，或不时漏下。前服逍遥、归脾等药，皆无效。诊其脉，左关尺及右尺皆浮弦，一息五至强。口干不思食，腰疼无力，乃血亏而有热也。遵将女科方安冲汤去耆、术，加麦冬、霍石斛、香附米，俾服之。二剂血止，六剂后食量增加，口干腰疼皆愈。继将汤剂制作丸药，徐徐服之，月事亦从此调矣。", "19808": "一九二四年七月，友人张××之母，因筹办娶儿媳事劳心过度，小便下血不止，其血之来沥沥有声，请为诊视，举止不定，气息微弱，右脉弦细，左脉弦硬。为开安冲汤，服后稍愈。翌日晨起，忽然昏迷，其家人甚恐，又请诊视。其脉尚和平，知其昏迷系黄耆升补之力稍过，遂仍用原方，加赭石八钱，一剂而愈。", "19809": "斯年初秋，李姓之女，年十七岁，下血不止，面唇皆白，六脉细数。治以安冲汤，重用山萸肉，三剂而愈。", "19810": "脉象热者加大生地一两；凉者加乌附子二钱；大怒之后，因肝气冲激血崩者，加柴胡二钱。若服两剂不愈，去棕边炭，加真阿胶五钱，另炖同服。服药觉热者宜酌加生地。", "19811": "一妇人，年三十余。陡然下血，两日不止。及愚诊视，已昏愦不语，周身皆凉，其脉微弱而迟。知其气血将脱，而元阳亦脱也。遂急用此汤，去白芍，加野台参八钱、乌附子三钱。一剂血止，周身皆热，精神亦复。仍将白芍加入，再服一剂，以善其后。", "19812": "子××曾治一妇人，年四十许。骤得下血证甚剧，半日之间，即气息奄奄，不省人事。其脉右寸关微见，如水上浮麻，不分至数，左部脉皆不见。急用生黄耆一两，大火煎数沸灌之，六部脉皆出。然微细异常，血仍不止。观其形状，呼气不能外出，又时有欲大便之意，知其为大气下陷也。遂为开固冲汤方，将方中黄耆改用一两。早十一点钟，将药服下，至晚三点钟，即愈如平时（后子××在京，又治一血崩证，先用固冲汤不效，加柴胡二钱，一剂即愈，足见柴胡升提之力，可为治崩要药）。", "19813": "族姊适徐姓，年三十余。有妊流产，已旬日矣。忽然下血甚多，头晕腹胀，脉小无力。知为冲脉滑脱之征证，予以固冲汤，加柴胡钱半，归身二钱。服药三剂即止。俾继服坤顺至宝丹以善其后。", "19814": "天津赵××妻，年四十余岁，行经过期不止，诸治不效，延弟诊视。见两部之脉皆微细无力，为开固冲汤原方予之，服数剂即全收功。因思如此年岁，血分又如此受伤，谅从此断生育矣。不意年余又产一子，安然无恙。盖因固冲汤止血兼有补血之功也。", "19815": "又：天津张××妻，年二十四岁，因小产后血不止者绵延月余，屡经医治无效。诊其脉象，微细而数，为开固冲汤方，因其脉数，加生地一两。服药后，病虽见轻，而不见大功。反复思索，莫得其故。细询其药价过贱，忽忆人言此地药房所鬻黄耆，有真有假，今此方无显著之功效，或其黄耆过劣也。改用口黄耆，连服两剂全愈。由斯知药物必须地道真正方效也。", "19816": "人之血海，其名曰冲。在血室之两旁，与血室相通。上隶于胃阳明经，下连于肾少阴经。有任脉以为之担任，督脉为之督摄，带脉为之约束。阳维、阴维、阳跷、阴跷，为之拥护，共为奇经八脉。此八脉与血室，男女皆有。在男子则冲与血室为化精之所，在女子则冲与血室实为受胎之处。《内经》上古通天论所谓「太冲脉盛，月事以时下，故有子」者是也。是以女子不育，多责之冲脉。郁者理之，虚者补之，风袭者祛之，湿胜者渗之，气化不固者固摄之，阴阳偏胜者调剂之。冲脉无病，未有不生育者。而愚临证实验以来，凡其人素无他病，而竟不育者，大抵因相火虚衰，以致冲不温暖者居多。因为制温冲汤一方。其人若平素畏坐凉处，畏食凉物，经脉调和，而艰于生育者，即与以此汤服之。或十剂或数十剂，遂能生育者多矣。", "19817": "一妇人，自二十出嫁，至三十未育子女。其夫商治于愚。因细询其性质禀赋，言生平最畏寒凉，热时亦不敢食瓜果。至经脉则大致调和，偶或后期两三日。知其下焦虚寒，因思《神农本草经》谓紫石英「气味甘温，治女子风寒在子宫，绝孕十年无子」。遂为拟此汤，方中重用紫石英六钱，取其性温质重，能引诸药直达于冲中，而温暖之。服药三十余剂，而畏凉之病除。后数月遂孕，连生子女。益信《神农本草经》所谓治十年无子者，诚不误也。", "19818": "带下为冲任之证。而名谓带者，盖以奇经带脉，原主约束诸脉，冲任有滑脱之疾，责在带脉不能约束，故名为带也。然其病非仅滑脱也，若滞下然，滑脱之中，实兼有瘀滞。其所瘀滞者，不外气血，而实有因寒因热之不同。此方用龙骨、牡蛎以固脱，用茜草、海螵蛸以化滞，更用生山药以滋真阴固元气。至临证时，遇有因寒者，加温热之药，因热者，加寒凉之药，此方中意也。而愚拟此方，则又别有会心也。尝考《神农本草经》龙骨善开症瘕，牡蛎善消癙瘘，是二药为收涩之品，而兼具开通之力也。乌鲗鱼骨即海螵蛸，茹芦即茜草，是二药为开通之品，而实具收涩之力也。四药汇集成方，其能开通者，兼能收涩，能收涩者，兼能开通，相助为理，相得益彰。", "19819": "一妇人，年二十余，患白带甚剧，医治年余不愈。后愚诊视，脉甚微弱。自言下焦凉甚，遂用此方，加干姜六钱，鹿角霜三钱，连服十剂全愈。", "19820": "又：一媪年六旬。患赤、白带下，而赤带多于白带，亦医治年余不愈。诊其脉甚洪滑，自言心热头昏，时觉眩晕，已半载未起床矣。遂用此方，加白芍六钱，数剂白带不见，而赤带如故，心热、头眩晕亦如故。又加苦参、龙胆草、白头翁各数钱。连服七八剂，赤带亦愈，而诸疾亦遂全愈。自拟此方以来，用治带下，愈者不可胜数。而独载此两则者，诚以二证病因，寒热悬殊。且年少者用此方，反加大热之药，年老者用此方，反加苦寒之药。欲临证者，当知审证用药，不可拘于年岁之老少也。", "19821": "赤白二带，赤者多热，白者多凉。而辨其凉热，又不可尽在赤白也，宜细询其自觉或凉或热，参以脉之或迟或数，有力无力，则凉热可辨矣。治法宜用收涩之品，而以化瘀通滞之药佐之。清带汤，证偏热者，加生杭芍、生地黄；热甚者，加苦参、黄柏，或兼用防腐之药，若金银花、旱三七、鸦胆子仁皆可酌用；证偏凉者，加白术、鹿角胶；凉甚者，加干姜、桂附、小茴香。", "19822": "或问，《金匮》麦门冬汤所主之病，与妇人倒经之病迥别，何以能借用之而有效验？答曰：冲为血海，居少腹之两旁。其脉上隶阳明，下连少阴。少阴肾虚，其气化不能闭藏以收摄冲气，则冲气易于上干。阳明胃虚，其气化不能下行以镇安冲气，则冲气亦易于上干。冲中之气既上干，冲中之血自随之上逆，此倒经所由来也。麦门冬汤，于大补中气以生津液药中，用半夏一味，以降胃安冲，且以山药代粳米，以补肾敛冲，于是冲中之气安其故宅，冲中之血，自不上逆，而循其故道矣。特是经脉所以上行者，固多因冲气之上干，实亦下行之路，有所壅塞。观其每至下行之期，而后上行可知也。故又加芍药、丹参、桃仁以开其下行之路，使至期下行，毫无滞碍。是以其方非为治倒经而设，而略为加减，即以治倒经甚效，愈以叹经方之函盖无穷也。", "19823": "用此方治倒经大抵皆效，而间有不效者，以其兼他证也。曾治一室女，倒经年余不愈，其脉象微弱。投以此汤，服药后甚觉短气。再诊其脉，微弱益甚。自言素有短气之病，今则益加重耳。恍悟其胸中大气，必然下陷，故不任半夏之降也。遂改用拙拟升陷汤，连服十剂。短气愈，而倒经之病亦愈。", "19824": "一少妇，倒经半载不愈。诊其脉微弱而迟，两寸不起，呼吸自觉短气，知其亦胸中大气下陷。亦投以升陷汤，连服数剂，短气即愈。身体较前强壮，即停药不服。其月经水即顺，逾十月举男矣。", "19825": "胎在母腹，若果善吸其母之气化，自无下坠之虞。且男女生育，皆赖肾脏作强。菟丝大能补肾，肾旺自能荫胎也。寄生能养血、强筋骨，大能使胎气强壮，故《神农本草经》载其能安胎。续断亦补肾之药。阿胶系驴皮所熬，最善伏藏血脉，滋阴补肾，故《神农本草经》亦载其能安胎也。至若气虚者，加人参以补气。大气陷者，加黄耆以升补大气。饮食减少者，加白术以健补脾胃。凉者，加补骨脂以助肾中之阳（补骨脂善保胎修园曾详论之）。热者，加生地黄以滋肾中之阴。临时斟酌适宜，用之无不效者。", "19826": "一妇人，产后发汗过多，覆被三层皆湿透，因致心中怔忡，精神恍惚，时觉身飘飘上至屋顶，此虚极将脱，而神魂飞越也。延愚诊视，见其汗出犹不止，六脉皆虚浮，按之即无。急用生山药、净萸肉各一两，生杭芍四钱，煎服。汗止精神亦定。翌日药力歇，又病而反复。时愚已旋里，病家复持方来询，为添龙骨、牡蛎（皆不用煅）各八钱，且嘱其服药数剂，其病必愈。孰意药坊中，竟谓方中药性过凉，产后断不宜用，且言此证系产后风，彼有治产后风成方，屡试屡验，怂恿病家用之。病家竟误用其方，汗出不止而脱。夫其证原属过汗所致，而再以治产后风发表之药，何异鸩毒。斯可为发汗不审虚实者之炯戒矣。", "19827": "《傅青主女科》曰：产后气血暴虚，百骸少血濡养，忽然口紧牙紧，手足筋脉拘搐，类中风痫痉，虽虚火泛上有痰，皆当以末治之。勿执偏门，而用治风消痰方，以重虚产妇也。当用生化汤，加参、耆以益其气。又曰，产后妇人，恶寒恶心，身体颤动，发热作渴，人以为产后伤寒也，谁知其气血两虚，正不敌邪而然乎？大抵人之气不虚，则邪断难入。产妇失血过多，其气必大虚，气虚则皮毛无卫，邪原易入。不必户外之风来袭体也，即一举一动，风可乘虚而入。然产后之风，易入亦易出，凡有外感之邪，俱不必祛风。况产后之恶寒者，寒由内生也。发热者，热由内弱也。身颤者，颤由气虚也。治其内寒，外寒自散。治其内弱，外热自解。壮其元气，而身颤自除也。", "19828": "按：傅氏之论甚超。特其虽有外感，不必祛风二句，不无可议。夫产后果有外感，原当治以外感之药，惟宜兼用补气生血之药，以辅翼之耳。若其风热已入阳明之府，表里俱热，脉象洪实者，虽生石膏亦可用。故《金匮》有竹皮大丸，治妇人乳中虚，烦乱呕逆，方中原有石膏。《神农本草经》石膏治产乳，原有明文。特不宜与知母并用，又宜仿白虎加人参汤之意，重用人参，以大补元气，更以玄参代知母，始能托邪外出，则石膏之寒凉，得人参之温补，能逗留胃中，以化燥热，不至直趋下焦，而与产妇有碍也（石膏解下曾详论之）。", "19829": "肝主筋，肝脉络阴器，肝又为肾行气。阴挺自阴中挺出，形状类筋之所结。病之原因，为肝气郁而下陷无疑也。故方中黄耆与柴胡、芎䓖并用，补肝即以舒肝，而肝气之陷者可升。当归与乳香、没药并用，养肝即以调肝，而肝气之郁者可化。又恐黄耆性热，与肝中所寄之相火不宜，故又加知母之凉润者，以解其热也。", "19830": "17．资生通脉汤", "19831": "《内经》谓「二阳之病发心脾，有不得隐曲，在女子为不月。」夫二阳者，阳明胃腑也。胃腑有病，不能消化饮食，推其病之所发，在于心脾。又推其心脾病之所发，在于有不得隐曲（凡不能自如者皆为不得隐曲）。盖心主神脾主思，人有不得隐曲，其神思郁结，胃腑必减少酸汁（化食赖酸汁，欢喜则酸汁生者多，忧思则酸汁生者少），不能消化饮食，以生血液，所以在女子为不月也。夫女子不月，既由于胃腑有病，不能消化饮食。治之者，自当调其脾胃，使之多进饮食，以为生血之根本。故方中用白术以健胃之阳，使之𥆧动有力（饮食之消亦仗胃有𥆧动）。山药、龙眼肉，以滋胃之阴，俾其酸汁多生。鸡内金原含有酸汁，且能运化诸补药之力，使之补而不滞。血虚者必多灼热，故用玄参、芍药以退热。又血虚者，其肝肾必虚，故用萸肉、枸杞以补其肝肾。甘草为补脾胃之正药，与方中萸肉并用，更有酸甘化阴之妙。桃仁、红花为破血之要品，方中少用之，非取其破血，欲借之以活血脉通经络也。至方后附载，因证加减诸药，不过粗陈梗概，至于证之变更多端，尤贵临证者，因时制宜耳。", "19832": "沧州曹姓女，年十六岁，天癸犹未至。饮食减少，身体羸瘦，渐觉灼热。其脉五至，细而无力。治以资生通脉汤，服至五剂，灼热已退，饮食加多。遂将方中玄参、芍药各减一钱，又加当归、怀牛膝各三钱。服至十剂，身体较前胖壮，脉象亦大有起色。又于方中加樗鸡（俗名红娘虫）十枚，服至七八剂，天癸遂至。遂减去樗鸡，再服数剂，以善其后。", "19833": "奉天马氏女，自十四岁，月事已通，至十五岁秋际，因食瓜果过多，泄泻月余方愈，从此月事遂闭。延医诊治，至十六岁季夏，病浸增剧，因求为诊治。其身形瘦弱异常，气息微喘，干嗽无痰，过午潮热，夜间尤甚，饮食减少，大便泄泻。其脉数近六至，微细无力。俾先用生怀山药细末八钱，水调煮作粥，又将熟鸡子黄四枚，捻碎搀粥中，再煮一两沸，空心时服。服后须臾，又服西药百布圣二瓦，以助其消化。每日如此两次，用作点心，服至四日，其泻已止。又服数日，诸病亦稍见轻。遂投以资生通脉汤，去玄参加生地黄五钱、川贝三钱，连服十余剂，灼热减十分之八，饮食加多，喘嗽亦渐愈。遂将生地黄换作熟地黄，又加怀牛膝五钱，服至十剂，自觉身体爽健，诸病皆无，惟月事犹未见。又于方中加䗪虫（即土鳖虫，背多横纹者真，背光滑者非是）五枚、樗鸡十枚，服至四剂，月事已通。遂去䗪虫、樗鸡，俾再服数剂，以善其后。", "19834": "马姓女十七岁。自十六岁秋际，因患右目生内障，服药不愈，忧思过度，以致月闭。自腊月服药，直至次年孟秋月底不愈，求为诊治。其人体质瘦弱，五心烦热，过午两颧色红，灼热益甚，心中满闷，饮食少许，即停滞不下，夜不能寐。脉搏五至，弦细无力。为其饮食停滞，夜不能寐，投以资生通脉汤，加生赭石（研细）四钱，熟枣仁三钱，服至四剂，饮食加多，夜已能寐，灼热稍退，遂去枣仁，减赭石一钱，又加地黄五钱，丹皮三钱，服约十剂，灼热大减。又去丹皮，将龙眼肉改用八钱，再加怀牛膝五钱。连服十余剂，身体浸壮健。因其月事犹未通下，又加䗪虫五枚、樗鸡十枚。服至五剂，月事已通。然下者不多，遂去樗鸡、地黄，加当归五钱，俾服数剂，以善其后。", "19835": "治眼疾肿疼，或胬肉遮睛，或赤脉络目，或目睛胀疼，或目疼连脑，或羞明多泪，一切虚火实热之证。", "19836": "治目睛胀疼，或微生云翳，或赤脉络目，或目眦溃烂，或偶因有火视物不真。", "19837": "一妇人，年三旬。瞳子散大，视物不真，不能针黹。屡次服药无效，其脉大而无力。为制此丸，服两月全愈。", "19838": "白喉之证，间有服《白喉忌表抉微》诸方不效，而反加剧者。曾治一贵州人，孙××，年二十，得白喉证。屡经医治，不外《白喉忌表抉微》诸方加减。病日增重，医者诿谓不治。后愚为诊视，其脉细弱而数，黏涎甚多，须臾满口，即得吐出。知系脾肾两虚，肾虚气化不摄，则阴火上逆，痰水上泛。而脾土虚损，又不能制之（若脾土不虚，不但能制痰水上泛，并能制阴火上逆），故其咽喉肿疼，黏涎若是之多也。投以六味地黄汤，加于术，又少加苏子，连服十剂全愈。", "19839": "咽喉之证，热者居多。然亦兼有寒者，不可不知。王洪绪曰：「咽喉之间，素分毫无病，顷刻之间，或疼或闷，此系虚寒阴火之证。用肉桂、炮姜、甘草各五分，置碗内浸以滚水，仍将碗置于滚水中，饮药一口，徐徐咽下立愈。或用乌附之片，涂以鲜蜜，火炙透至黑，取一片口含咽津，至片不甜时，再换一片，亦立愈。」按王氏之说，咽喉陡然疼闷者，皆系因寒。然亦有因热者，或其人素有蕴热，陡然为外感所束，或劳碌过度，或暴怒过度，皆能使咽喉骤觉疼闷。斯在临证者，于其人之身体、性情、动作之际，细心考验，再参以脉象之虚实凉热，自无差谬。若仍恐审证不确，察其病因似寒，而尤恐病因是热，可用蜜炙附子片试含一片，以细验其病之进退亦可。", "19840": "按：走马牙疳之原因，有内伤外感之殊。得于由内伤者轻而缓，由外感者重而急。此幼童得于麻疹之后，其胃中蕴有瘟毒上攻，是以三日之间，即腐烂如此。幸内服石膏、寒水石，外敷藤黄，内外夹攻，皆中要肯，是以其毒易消，结痂亦在三日内也。若当牙疳初起之时，但能用药消其内蕴之毒热，即外不敷药，亦可治愈。曾治天津于氏幼童，年六七岁，身出麻疹，旬日之外热不退，牙龈微见腐烂。其家人惧甚，恐成走马牙疳，延愚诊视。脉象有力而微弦，知毒热虽实，因病久者，气分有伤也。问其大便，三日未行。遂投以大剂白虎加人参汤，方中生石膏用三两，野党参用四钱，又加连翘数钱，以托疹毒外出。煎汤三茶盅，俾分三次温饮下。又用羚羊角一钱，煎水一大茶盅，分数次当茶饮之，尽剂热退而病愈。牙龈腐烂之处，亦遂自愈。", "19841": "一人年二十余。因抬物用力过度，腰疼半年不愈。忽于疼处发出一疮，在脊梁之旁，微似红肿，状若复盂，大径七寸。疡医以为腰疼半年，始现此疮，其根蒂必深而难治。且其内外发热，饮食懒进，舌苔黄厚，脉象滑数。知其证兼外感实热，投以白虎加人参汤，热退能食。数日，又复虚汗淋漓，昼夜不止，遂用龙骨、牡蛎（皆不用煅）、生杭芍、生山药各一两为方，两剂汗止。继治以清火、消肿、解毒之药，若拙拟消乳汤，去栝蒌加金线重楼、三七（冲服）之类，更加鹿角霜钱许，以引经。惟消乳汤以知母为君重八钱，兹则所用不过五六钱。外用五倍子、三七、枯矾、金线重楼、白芨为末，以束其根；乳香、没药、雄黄、金线重楼、三七为末，以敷其顶，皆用醋调之。旬日疮消三分之二，其顶甚软。遂以乌金膏（以雄黄炒巴豆仁至黑色研细名乌金膏）调香油敷其软处。二日，疮破出稠脓若干。将此内托生肌散改作汤剂，投之，外敷拙拟化腐生肌散。七八日间疮口长平，结痂而愈。", "19842": "石膏医者多误认为大寒而煅用之，则宣散之性变为收敛（点豆腐者必煅用，取其能收敛也），以治外感有实热者，竟将其痰火敛住，凝结不散，用至一两即足伤人，是变金丹为鸩毒也。迨至误用煅石膏偾事，流俗之见，不知其咎在煅不在石膏，转谓石膏煅用之其猛烈犹足伤人，而不煅者更可知矣。于是一倡百和，遂视用石膏为畏途，即有放胆用者，亦不过七八钱而止。夫石膏之质甚重，七八钱不过一大撮耳。以微寒之药，欲用一大撮扑灭寒温燎原之热，又何能有大效。是以愚用生石膏以治外感实热，轻证亦必至两许；若实热炽盛，又恒重用至四五两，或七八两，或单用，或与他药同用，必煎汤三四茶杯，分四五次徐徐温饮下，热退不必尽剂。如此多煎徐服者，欲以免病家之疑惧，且欲其药力常在上焦、中焦，而寒凉不至下侵致滑泻也。盖石膏生用以治外感实热，断无伤人之理，且放胆用之，亦断无不退热之理。惟热实脉虚者，其人必实热兼有虚热，仿白虎加人参汤之义，以人参佐石膏亦必能退热。盖诸药之退热，以寒胜热也，而石膏之退热，逐热外出也。是以将石膏煎服之后，能使内蕴之热息息自毛孔透出，且因其含有硫养轻，原具发表之性，以之煮汤又直如清水，服后其寒凉之力俱随发表之力外出，而毫无汁浆留中以伤脾胃，是以遇寒温之大热势若燎原，而放胆投以大剂白虎汤，莫不随手奏效。其邪实正虚者，投以白虎加人参汤，亦能奏效。", "19843": "盖石膏之所以善治寒温者，原恃其原质中之硫养轻也。若煅之，其硫养轻皆飞去，所余之钙经煅即变质，若误服之，能将人外感之痰火及周身之血脉皆为凝结锢闭。是以见有服煅石膏数钱脉变结代，浸至言语不遂，肢体痿废者；有服煅石膏数钱其证变结胸，满闷异常，永不开通者；有服煅石膏数钱其周身肌肉似分界限，且又突起者。盖自有石膏煅不伤胃之语，医者轻信其说以误人性命者实不胜计矣。故凡用生石膏者，宜买其整块明亮者，自监视轧细（凡石质之药不轧细，则煎不透）方的。若购自药房中难辨其煅与不煅，迨将药煎成，石膏凝结药壶之底，倾之不出者，必系煅石膏，其药汤即断不可服。", "19844": "同邑友人赵××之妻，年近六旬得温病，脉数而洪实，舌苔黄而干，闻药气即呕吐。俾单用生石膏细末六两，以作饭小锅（不用药甑，恐有药味复呕吐）煎取清汤一大碗，恐其呕吐，一次只温饮一口，药下咽后，觉烦躁异常，病家疑药不对证。愚曰：「非也，病重药轻故也」，饮至三次，遂不烦躁，阅四点钟尽剂而愈。", "19845": "同邑友人毛××之三子××，年三十二岁，素有痰饮，得伤寒证，服药调治而愈。后因饮食过度而复，服药又愈。后数日又因饮食过度而复，医治无效。四五日间，延愚诊视，其脉洪长有力，而舌苔淡白，亦不燥渴，食梨一口即觉凉甚，食石榴子一粒，心亦觉凉。愚舍证从脉，为开大剂白虎汤方，因其素有痰饮，加清半夏数钱，其表兄高××在座，邑中之宿医也，疑而问曰：「此证心中不渴不热，而畏食寒凉如此，以余视之虽清解药亦不宜用，子何所据而用生石膏数两乎？」答曰：「此脉之洪实，原是阳明实热之证，其不觉渴与热者，因其素有痰饮湿胜故也。其畏食寒凉者，因胃中痰饮与外感之热互相胶漆，致胃府转从其化与凉为敌也。」毛××素晓医学，信用愚言，两日夜间服药十余次，共用生石膏斤余，脉始和平，愚遂旋里。隔两日复来相迎，言病人反复甚剧，形状异常，有危在顷刻之虑。因思此证治愈甚的，何至如此反复。既至（相隔三里强），见其痰涎壅盛，连连咳吐不竭，精神恍惚，言语错乱，身体颤动，诊其脉平和无病，惟右关胃气稍弱。愚恍然会悟，急谓其家人曰：「此证万无闪失，前因饮食过度而复，此次又因戒饮食过度而复也。」其家人果谓有鉴前失，数日之间，所与饮食甚少。愚曰：「此无须用药，饱食即可愈矣。」其家人虑其病状若此，不能进食。愚曰：「无庸如此多虑，果系由饿而得之病，见饮食必然思食。」其家人依愚言，时已届晚八句钟，至黎明进食三次，每次撙节与之，其病遂愈。", "19846": "友人毛××妻，年近七旬，于正月中旬，伤寒无汗。原是麻黄汤证，因误服桂枝汤，汗未得出，上焦陡觉烦热恶心，闻药气即呕吐，但饮石膏所煮清水及白开水亦呕吐。惟昼夜吞小冰块可以不吐，两日之间，吞冰若干，而烦热不减，其脉关前洪滑异常。俾用鲜梨片，蘸生石膏细末嚼咽之，遂受药不吐，服尽二两而病愈。", "19847": "一人患梅毒，在东人医院治疗二十余日，头面肿大，下体溃烂，周身壮热，谵语不省人事，东人谓毒已走丹不可治。其友人孙××，邀愚往东人院中为诊视。疑其证夹杂温病，遂用生石膏细末半斤，煮水一大瓶，伪作葡萄酒携之至其院中，托言探友，盖不欲东人知为疗治也。及入视病人，其头面肿而且红，诊其脉洪而实，知系夹杂温病无疑，嘱将石膏水徐徐温服。翌日，又往视，其头面红肿见退，脉之洪实亦减半，而较前加数，仍然昏愦谵语，分毫不省人事。所饮石膏之水尚余一半，俾自购潞党参五钱，煎汤兑所余之石膏水饮之。翌日，又往视之，则人事大清，脉亦和平。病人遂决意出彼院来院中调治，后十余日其梅毒亦愈。此证用潞党参者，取其性平不热也。", "19848": "一人，年五十，周身发冷，两腿疼痛。医者投以温补之药，其冷益甚，欲作寒战。诊其脉，甚沉伏，重按有力。其舌苔黄厚，小便赤涩。当时仲春，知其春温之热，郁于阳明而未发，故现此假象也。欲用白虎汤加连翘治之，病人闻之，骇然。愚曰：但预购生石膏四两，迨热难忍时，煎汤饮之可乎？病者曰：恐无其时耳。愚曰：若取鲜白茅根，煎汤饮之，则冷变为热，且变为大热矣。病者仍不确信，然欲试其验否，遂剖取鲜白茅根，去净皮，细锉一大碗，煮数沸，取其汤，当茶饮之。有顷热发，若难忍。须臾再诊其脉，则洪大无伦矣。愚将所预购之四两生石膏煎汤，分三次温饮下，其热遂消。", "19849": "外感痰喘，宜投以《金匮》小青龙加石膏汤。若其外感之热，已入阳明之府，而小青龙中之麻、桂、姜、辛诸药，实不宜用。曾治刘××，年八岁。孟秋患温病，医治十余日，病益加剧。表里大热，喘息迫促，脉象洪数，重按有力，知犹可治。问其大便，两日未行，投以大剂白虎汤，重用生石膏二两半，用生山药一两以代方中粳米。且为其喘息迫促、肺中伏邪，又加薄荷叶一钱半以清之。俾煎汤两茶盅，作两次温饮下，一剂病愈强半，又服一剂全愈。", "19850": "从来产后之证，最忌寒凉。而果系产后温病，心中燥热，舌苔黄厚，脉象洪实，寒凉亦在所不忌。然所用寒凉之药，须审慎斟酌，不可漫然相投也。愚治产后温证之轻者，其热虽入阳明之府，而脉象不甚洪实，恒重用玄参一两，或至二两，辄能应手奏效。若系剧者，必用白虎加人参汤方能退热。然用时须以生山药代粳米，玄参代知母，方为稳妥。医方篇中白虎加人参以山药代粳米汤下附有验案可参观。盖以石膏、玄参，《神农本草经》皆明言其治产乳，至知母条下则未尝言之，不敢师心自用也。", "19851": "友人毛××曾治一少妇，产后十余日，周身大热，无汗，心中热，而且渴。延医调治，病势转增。甚属危急。毛××诊其脉，甚洪实，舌苔黄而欲黑，撮空摸床，内风已动。治以生石膏三两，玄参一两，野台参五钱，甘草二钱。为服药多呕，取竹皮大丸之义，加竹茹二钱，煎汤一大碗，徐徐温饮下，尽剂而愈。观此案，则外感之热，直如燎原，虽在产后，岂能从容治疗乎？孙思邈曰：智欲圆而行欲方，胆欲大而心欲小。世俗医者，遇此等证，但知心小，而不知胆大。岂病人危急之状，漠不关于心乎？", "19852": "在女子有因外感之热内迫，致下血不止者，亦可重用白虎加人参汤治之。邻村李氏妇，产后数日，恶露已尽，至七八日，忽又下血。延医服药，二十余日不止，其脉洪滑有力，心中热而且渴。疑其夹杂外感，询之身不觉热，舌上无苔，色似微白，又疑其血热妄行，投以凉血兼止血之药，血不止而热渴亦如故。因思此证实夹杂外感无疑，遂改用白虎加人参汤，方中生石膏重用三两，更以生山药代粳米煎汤三盅，分三次温饮下，热渴遂愈，血亦见止。又改用凉血兼止血之药而愈。", "19853": "表兄张××之妻高氏。年五十余，素多疾病。于季夏晨起偶下白痢，至暮十余次，秉烛后，忽然浑身大热，不省人事，循衣摸床，呼之不应。其脉洪而无力，肌肤之热烙手。知其系气分热痢，又兼受暑，多病之身不能支持，故精神昏愦如是也。急用生石膏三两、野党参四钱，煎汤一大碗，徐徐温饮下。至夜半尽剂而醒，痢亦遂愈，诘朝煎渣再服，其病脱然。", "19854": "上所载痢证医案，皆兼外感之热者也。故皆重用生石膏治之，非概以其方治痢证也。拙著《衷中参西录》中，治痢共有七方，皆随证变通用之，确有把握，前案所用之方，乃七方之一也。愚用此方治人多矣，脉证的确，用之自无差忒也。", "19855": "疟疾虽在少阳，而阳明兼有实热者，亦宜重用生石膏。曾治邻村李××，年四十许，疟疾间日一发，热时若燔，即不发之日亦觉表里俱热，舌燥口干，脉象弦长，重按甚实。此少阳邪盛，阳明热盛，疟而兼温之脉也。投以大剂白虎汤加柴胡三钱，服后顿觉清爽。翌晨疟即未发，又煎服前剂之半，加生姜三钱，温、疟从此皆愈。至脉象虽不至甚实，而按之有力，常觉发热懒食者，愚皆于治疟剂中，加生石膏两许以清之，亦莫不随手奏效也。", "19856": "石膏之性，又善治脑漏。方书治脑漏之证，恒用辛夷、苍耳。然此证病因，有因脑为风袭者，又因肝移热于脑者。若因脑为风袭而得，其初得之时，或可用此辛温之品散之，若久而化热，此辛温之药即不宜用，至为肝移热于脑，则辛温之药尤所必戒也。近治奉天郭××，得此证半载不愈。鼻中时流浊涕，其气腥臭，心热神昏，恒觉眩晕。其脉左右皆弦而有力，其大便恒干燥，知其肝移热于脑，其胃亦移热于脑矣。恐其病因原系风袭，先与西药阿斯匹林瓦许以发其汗，头目即觉清爽，继为疏方，用生石膏两半，龙胆草、生杭芍、玄参、知母、花粉各四钱，连翘、金银花、甘草各二钱，薄荷叶一钱。连服十剂，石膏皆用两半，他药则少有加减，其病遂脱然全愈。", "19857": "奉天一人得此证，七八日，其脉浮而有力，知其因风束生热也。亦先用阿斯匹林瓦许汗之。汗后，其鼻中浊涕即减，亦投以前方，连服三剂全愈。", "19858": "《神农本草经》谓石膏能治腹痛，诚有效验。曾治奉天刘××腹疼，三年不愈。其脉洪长有力，右部尤甚，舌心红而无皮，时觉头疼眩晕，大便干燥，小便黄涩，此乃伏气化热，阻塞奇经之经络，故作疼也。为疏方：生石膏两半，知母、花粉、玄参、生杭芍、川楝子各五钱，乳香、没药各四钱，甘草二钱，一剂疼愈强半。即原方略为加减，又服数剂全愈。", "19859": "愚弱冠，有本村刘氏少年，因腹疼卧病月余，昼夜号呼，势极危险。延医数人，皆束手无策。闻愚归，求为诊视，其脉洪长有力，盖从前之疼犹不至如斯，为屡次为热药所误，故疼益加剧耳。亦投以前方，惟生石膏重用二两，一剂病大轻减。后又加鲜茅根数钱，连服两剂全愈。盖此等证，大抵皆由外感伏邪窜入奇经，久而生热。其热无由宣散，遂郁而作疼。医者为其腹疼，不敢投以凉药，甚或以热治热，是以益治益剧。然证之凉热，脉自有分，即病人细心体验，亦必自觉。临证者尽心询问考究，自能得其实际也。", "19860": "石膏之性，又最宜与西药阿斯匹林并用。盖石膏清热之力虽大，而发表之力稍轻。阿斯匹林味酸性凉，最善达表，使内郁之热由表解散，与石膏相助为理，实有相得益彰之妙也。如外感之热，已入阳明胃腑，其人头疼舌苔犹白者，是仍带表证。愚恒用阿斯匹林一瓦，白蔗糖化水送服以汗之。迨其汗出遍体之时，复用生石膏两许，煎汤乘热饮之（宜当汗正出时饮之），在表之热解，在里之热亦随汗而解矣。若其头已不疼，舌苔微黄，似无表证矣，而脉象犹浮，虽洪滑而按之不实者，仍可用阿斯匹林汗之。然宜先用生石膏七八钱，或两许，煮汤服之，俾热势少衰，然后投以阿斯匹林，则汗既易出，汗后病亦易解也。若其热未随汗全解，仍可徐饮以生石膏汤，清其余热。不但此也，若斑疹之毒，郁而未发，其人表里俱热，大便不滑泻者，可用生石膏五六钱，煎汤冲服阿斯匹林半瓦许，俾服后，微似有汗，内毒透彻，斑疹可全然托出。若出后壮热不退，胃腑燥实，大便燥结者，又可多用生石膏至二三两许，煎汤一大碗（约有三四茶杯），冲阿斯匹林一瓦，或一瓦强，一次温饮数羹匙。初饮略促其期，迨热见退，或大便通下，尤宜徐徐少饮，以壮热全消，仍不至滑泻为度。如此斟酌适宜，斑疹无难愈之证矣。石膏与阿斯匹林，或前后互用，或一时并用，通变化裁，存乎其人，果能息息与病机相赴，功效岂有穷哉！", "19861": "用阿斯匹林治关节肿疼之挟有外感实热者，又必与石膏并用，方能立见奇效。奉天赵××之侄，年六岁。脑后生疮，漫肿作疼，继而头面皆肿，若赤游丹毒。继而作抽掣，日甚一日。浸至周身僵直，目不能合，亦不能瞬，气息若断若续，呻吟全无。其家人以为无药可治，待时而已。阅两昼夜，形状如故，试灌以勺水，似犹知下咽。因转念或犹可治，而彼处医者，咸皆从前延请而屡次服药无效者也。来院求为诊治。其脉洪数而实，肌肤发热，知其夹杂温病，阳明腑证已实，势虽垂危，犹可挽回。遂用生石膏细末四两，以蒸汽水煎汤两茶杯，徐徐温灌之。周十二时，剂尽，脉见和缓，微能作声。又用阿斯匹林瓦半，仍以汽水所煎石膏汤，分五次送下，限一日夜服完。服至末二次，皆周身微见汗，其精神稍明了，肢体能微动。从先七八日不食，且不大便，至此可少进茶汤，大便亦通下矣。继用生山药细末煮作稀粥，调以白蔗糖，送服阿斯匹林三分之一瓦，日两次，若见有热，即间饮汽水所煮石膏汤。又以蜜调黄连末，少加薄荷冰，敷其头面肿处，生肌散敷其疮口破处，如此调养数日，病势减退，可以能言。其左边手足仍不能动，试略为屈伸，则疼不能忍。细验之，关节处皆微肿，按之觉疼，知其关节之间，因外感之热而生炎也。遂又用鲜茅根煎浓汤（无鲜茅根可代以鲜芦根），调以白蔗糖，送服阿斯匹林半瓦，日两次。俾服药后周身微似有汗，亦间有不出汗之时，令其关节中之炎热，徐徐随发表之药透出。又佐以健补脾胃之药，俾其多进饮食。如此旬余，左手足皆能运动，关节能屈伸。以后饮食复常，停药勿服，静养半月，行动如常矣。此证共用生石膏三斤，阿斯匹林三十瓦，始能完全治愈。愚用阿斯匹林治热性关节肿疼者多矣，为此证最险，故详记之。", "19862": "友人张××，曾治京都阎姓叟。年近七旬，素有劳疾，发则喘而且嗽。于冬日感冒风寒，上焦烦热，劳疾大作，痰涎胶滞，喘促异常。其脉关前洪滑，按之有力。张××治以生石膏二两以清时气之热，因其劳疾，加沉香五钱，以引气归肾。且以痰涎太盛，石膏能润痰之燥，不能行痰之滞，故又借其辛温之性，以为石膏之反佐也。一日连服二剂，于第二剂加清竹沥二钱，病若失。劳疾亦从此除根永不反复。夫劳疾至年近七旬，本属不治之证，而事出无心，竟以重用石膏治愈之，石膏之功用，何其神哉！愚因闻此案，心有会悟，拟得治肺劳黄耆膏方，其中亦用生石膏，服者颇有功效。", "19863": "寒温阳明府病，原宜治以白虎汤。医者畏不敢用，恒以甘寒之药清之，遇病之轻者，亦可治愈，而恒至稽留余热（甘寒药滞泥，故能闭塞外感热邪），变生他证。迨至病久不愈，其脉之有力者，仍可用白虎汤治之，其脉之有力而不甚实者，可用白虎加人参汤治之。曾治奉天一学徒。年十四五，得劳热喘嗽证。初原甚轻，医治数月，病势浸增，医者诿谓不治。遂来院求为诊视，其人羸弱已甚，而脉象有力，数近六至，疑其有外感伏热，询之果数月之前，曾患温病，经医治愈。乃知其决系外感留邪，问其心中时觉发热，大便干燥，小便黄涩，遂投以白虎加人参汤，去粳米加生怀山药一两，连服数剂，病若失。见者讶为奇异，不知此乃治其外感，非治其内伤，而能若是之速效也。", "19864": "《内经》谓「冬伤于寒，春必病温」，是言伏气为病也。乃有伏气伏于膈膜之下（《内经》所谓横连膜原也），逼近胃口，久而化热，不外发为温病，转上透膈膜，熏蒸肺脏，致成肺病者。若其脉有力，亦宜重用生石膏治之。曾治奉天赵某年四十许。始则发热懒食，继则咳嗽吐痰腥臭，医治三月，浸至不能起床。脉象滑实，右脉尤甚（伏邪之热，亦如寒温之脉，多右盛于左），舌有黄苔，大便数日一行。知系伏气为病，投以大剂白虎汤，以生山药代粳米，又加利痰解毒之品，三剂后病愈强半。又即其方加减，服至十余剂全愈。", "19865": "有伏气下陷于奇经诸脉中，久而化热，其热亦不能外发为温。有时随奇经之脉上升者。在女子又有热入血室而子宫溃烂者，爰录两案于下以证之。", "19866": "安东尉××，年二十余。时觉有热，起自下焦，上冲脑部。其脑部为热冲激，头巅有似肿胀，时作眩晕，心中亦时发热，大便干燥，小便黄涩。经医调治，年余无效。求其处医士李××寄函来问治法，其开来病案如此。曰：「其脉象洪实，饮食照常，身体亦不软弱。」知其伏有外感热邪，因其身体不弱，俾日用生石膏细末四两，煮水当茶饮之，若觉凉时即停服。后二十余日，其人忽来奉，言遵示服石膏六七斤，上冲之热见轻，而大便微溏，因停药不服。诊其脉仍然有力，问其心中仍然发热，大便自停药后即不溏矣。为开白虎加人参汤，方中生石膏重用三两，以生怀山药代粳米，连服六七剂，上冲之热大减，因出院还家。嘱其至家，按原方服五六剂，病当除根矣。", "19867": "南皮张××妻年三十余。十年前，恒觉少腹切疼。英女医谓系子宫炎证，用药数次无效。继乃谓此病如欲除根，须用手术剖割，将生炎之处其腐烂者去净，然后敷药能愈。病人惧而辞之。后至奉，又延东女医治疗，用坐药兼内服药，数年稍愈，至壬戌夏令，病浸增剧，时时疼痛，间下脓血。癸亥正初，延愚诊治。其脉弦而有力，尺脉尤甚。自言疼处觉热，以凉手熨之稍愈，上焦亦时觉烦躁。恍悟此证，当系曾受外感热入血室，医者不知，治以小柴胡汤加石膏，外感虽解，而血室之热未清。或伏气下陷入于血室，阻塞气化，久而生热，以致子宫生炎，浸至溃烂，脓血下注。为疏方，用金银花、乳香、没药、甘草以解其毒，天花粉，知母、玄参以清其热，复本小柴胡汤之义，少加柴胡提其下陷之热上出，诸药煎汤，送服三七细末二钱，以化腐生新。连服三剂病似稍轻，其热仍不少退。因思此证，原系外感稽留之热，非石膏不能解也。遂于原方中加生石膏一两，后渐加至二两，连服数剂，热退强半，疼亦大减。遂去石膏，服数剂渐将凉药减少，复少加健胃之品，共服药三十剂全愈。后在天津治冯氏妇此证，亦用此方。中有柴胡，即觉脓血不下行，后减去柴胡，为之治愈。", "19868": "石膏生用之功效，不但能治病，且善于治疮，且善于解毒。奉天赵××之父，年过六旬，在脐旁生痈，大径三寸，五六日间烦躁异常，自觉屋隘莫容。其脉左关弦硬，右关洪实，知系伏气之热与疮毒俱发也。问其大便数日未行，投以大剂白虎汤加金银花、连翘、龙胆草，煎汤一大碗，徐徐温饮下，连服三剂，烦躁与疮皆愈。", "19869": "近治一伏温病，壮热烦渴，脉来洪实兼数，大解十日未行。欲透其邪，则津液已衰，恐有汗脱之虞，欲通其便，则并无承气确征。细思此证，乃阳明热久，真阴铄耗。遵先生重用生石膏之训，即用生石膏二两，合增液汤，加鲜金钗石斛、香青蒿各三钱。病家疑忌，见者皆以为药性过寒凉。余愤然曰：「择医宜慎，任医宜专。既不信余药，请余何为？」病家不得已，购药一剂，俾煎汤两盅，作两次服下。而热势益炽，病家疑药不对证。余曰：「此非药不对证，乃药轻不胜病耳。」遂俾将两剂并作一剂，煎汤一大碗，徐徐温饮下。移时汗出便通，病若失。", "19870": "【附案】邑中高某年四十许，于季春得温病。屡经医者调治，大热已退，精神益惫，医者诿为不治。病家亦以为气息奄奄，待时而已。乃迟旬日而病状如故，始转念或可挽回。迎愚诊视，其两目清白无火，竟昏愦不省人事，舌干如磋，却无舌苔，问之亦不能言，抚其周身皆凉，其五六呼吸之顷，必长出气一口，其脉左右皆微弱，至数稍迟，知其胸中大气因服开破降下药太过而下陷也。盖大气不达于脑中则神昏，大气不潮于舌本则舌干。神昏舌干，故问之不能言也；其周身皆凉者，大气陷后不能宣布营卫也；其五六呼吸之顷必长出气者，大气陷后胸中必觉短气，故太息以舒其气也。遂用野台参一两、柴胡二钱，煎汤灌之，一剂见轻，两剂全愈。", "19871": "外甥王××年二十时，卧病数月不愈，精神昏愦，肢体酸懒，微似短气，屡次延医服药莫审病因，用药亦无效验。一日忽然不能喘息，张口呼气外出而气不上达，其气蓄极下迫肛门突出，约二十呼吸之顷，气息方通，一昼夜间如是者八九次。诊其脉关前微弱不起，知其胸中大气下陷，不能司肺脏呼吸之枢机也。遂投以人参一两，柴胡三钱，知母二钱，一剂而呼吸顺，又将柴胡改用二钱，知母改用四钱，再服数剂宿病亦愈。", "19872": "【附案】沧州董氏女，年二十余。胸胁满闷，心中怔忡，动则自汗，其脉沉迟微弱，右部尤甚，为其脉迟，疑是心肺阳虚，询之不觉寒凉，知其为胸中大气下陷也。其家适有预购黄耆一包，俾用一两煎汤服之。其族兄××在座，其人颇知医学，疑药不对证。愚曰：「勿多疑，倘有差错，余职其咎。」服后，果诸病皆愈。其族兄疑而问曰：「《神农本草经》黄耆原主大风，有透表之力，生用则透表之力益大，与自汗证不宜，其性升而能补，有膨胀之力，与满闷证不宜，今单用生黄耆两许，而两证皆愈，并心中怔忡亦愈，其义何居？」答曰：「黄耆诚有透表之力，气虚不能逐邪外出者，用于发表药中，即能得汗，若其阳强阴虚者，误用之则大汗如雨不可遏抑。惟胸中大气下陷，致外卫之气无所统摄而自汗者，投以黄耆则其效如神。至于证兼满闷而亦用之者，确知其为大气下陷，呼吸不利而作闷，非气郁而作闷也。至于心与肺同悬胸中，皆大气之所包举，大气升则心有所依，故怔忡自止也。」继加桔梗二钱，知母三钱，又服两剂以善其后。", "19873": "一妇人产后四五日，大汗淋漓，数日不止，形势危急，气息奄奄，其脉微弱欲无，问其短气乎？心中怔忡且发热乎？病人不能言而颔之。知其大气下陷，不能吸摄卫气，而产后阴分暴虚，又不能维系阳分，故其汗若斯之脱出也。遂用生黄耆六钱，玄参一两，净萸肉、生杭芍各五钱，桔梗二钱，一剂汗减，至三剂诸病皆愈。从前五六日未大便，至此大便亦通下。", "19874": "邑王氏女，年二十余，心中寒凉，饮食减少，延医服药，年余无效，且益羸瘦。后愚诊视，其左脉微弱不起，断为肝虚证。其父知医，疑而问曰：「向延医诊治，皆言脾胃虚弱，相火衰损，故所用之方皆健脾养胃，补助相火，曾未有言及肝虚者，先生独言肝虚，但因左脉之微弱乎？抑别有所见而云然乎？」答曰：「肝脏之位置虽居于右，而其气化实先行于左，试问病人，其左半身必觉有不及右半身处，是其明征也。」询之，果觉坐时左半身下坠，卧时不敢向左侧，其父方信愚言，求为疏方。遂用生黄耆八钱，柴胡、川芎各一钱，干姜三钱，煎汤饮下，须臾左侧即可安卧，又服数剂，诸病皆愈。惟素有带证尚未除，又于原方加牡蛎数钱，服数剂带证亦愈。其父复疑而问曰：「黄耆为补肺脾之药，今先生用以补肝，竟能随手奏效，其义何居？」答曰：「肝属木而应春令，其气温而性喜条达，黄耆之性温而上升，以之补肝原有同气相求之妙用。愚自临证以来，凡遇肝气虚弱不能条达，用一切补肝之药皆不效，重用黄耆为主，而少佐以理气之品，服之复杯即见效验，彼谓肝虚无补法者，原非见道之言也。」", "19875": "黄耆不但能补气，用之得当，又能滋阴。本村张媪年近五旬，身热劳嗽，脉数至八至，先用六味地黄丸加减煎汤服不效，继用左归饮加减亦不效。踌躇再四忽有会悟，改用生黄耆六钱，知母八钱，煎汤服数剂，见轻，又加丹参、当归各三钱，连服十剂全愈。盖虚劳者多损肾，黄耆能大补肺气以益肾水之上源，使气旺自能生水，而知母又大能滋肺中津液，俾阴阳不至偏胜，而生水之功益普也。至数剂后，又加丹参、当归者，因血痹虚劳，《金匮》合为一门，治虚劳者当防其血有痹而不行之处，故加丹参、当归以流行之也。", "19876": "黄耆之性，又善治肢体痿废，然须细审其脉之强弱，其脉之甚弱而痿废者，西人所谓脑贫血证也。盖人之肢体运动虽脑髓神经司之，而其所以能司肢体运动者，实赖上注之血以涵养之。其脉弱者，胸中大气虚损，不能助血上升以养其脑髓神经，遂致脑髓神经失其所司，《内经》所谓「上气不足，脑为之不满」也。拙拟有加味补血汤、干颓汤，方中皆重用黄耆。凡脉弱无力而痿废者，多服皆能奏效。若其脉强有力而痿废者，西人所谓脑充血证，又因上升之血过多，排挤其脑髓神经，俾失所司，《内经》所谓「血菀（同郁）于上，为薄厥」也。如此等证，初起最忌黄耆，误用之即凶危立见。迨至用镇坠收敛之品，若拙拟之镇肝熄风汤、建瓴汤治之。其脉柔和而其痿废仍不愈者，亦可少用黄耆助活血之品以通经络，若服药后，其脉又见有力，又必须仍辅以镇坠之品，若拙拟之起痿汤，黄耆与赭石、䗪虫诸药并用也。", "19877": "沈阳朱××，黎明时来院扣门，言其妻因行经下血不止，精神昏愦，气息若无。急往诊视，六脉不全仿佛微动，急用生黄耆、野台参、净萸肉各一两，煅龙骨、煅牡蛎各八钱，煎汤灌下，血止强半，精神见复，过数点钟将药剂减半，又加生怀山药一两，煎服全愈。", "19878": "邑刘氏妇，年二十余，身体羸弱，心中常觉寒凉，下白带甚剧，屡治不效，脉甚细弱，左部尤甚。投以生黄耆、生牡蛎各八钱，干姜、白术、当归各四钱，甘草二钱，数剂全愈。盖此证因肝气太虚，肝中所寄之相火亦虚，因而气化下陷，湿寒下注而为白带。故重用黄耆以补肝气，干姜以助相火，白术扶土以胜湿，牡蛎收涩以固下，更加以当归之温滑，与黄耆并用，则气血双补，且不至有收涩太过之弊（在下者因而竭之），甘草之甘缓，与干姜并用，则热力绵长，又不至有过热僭上之患，所以服之有捷效也。", "19879": "山萸肉：味酸性温。大能收敛元气，振作精神，固涩滑脱。因得木气最厚，收涩之中兼具条畅之性，故又通利九窍，流通血脉，治肝虚自汗，肝虚胁疼腰疼，肝虚内风萌动，且敛正气而不敛邪气，与他酸敛之药不同，是以《神农本草经》谓其逐寒湿痹也。其核与肉之性相反，用时务须将核去净，近阅医报有言核味涩，性亦主收敛，服之恒使小便不利，椎破尝之，果有有涩味者，其说或可信。", "19880": "【附案】一人年四十余，外感痰喘，愚为治愈。但脉浮力微，按之即无。愚曰：「脉象无根，当服峻补之剂，以防意外之变。」病家谓病人从来不受补药，服之则发狂疾，峻补之药，实不敢用。愚曰：「既畏补药如是，备用亦可。」病家依愚言。迟半日忽发喘逆，又似无气以息，汗出遍体，四肢逆冷，身躯后挺，危在顷刻。急用净萸肉四两，爆火煎一沸，即饮下，汗与喘皆微止。又添水再煎数沸饮下，病又见愈。复添水将原渣煎透饮下，遂汗止喘定，四肢之厥逆亦回。", "19881": "邻村李××，年二十余，素伤烟色，偶感风寒，医者用表散药数剂治愈。间日，忽遍身冷汗，心怔忡异常，自言气息将断，急求为调治。诊其脉浮弱无根，左右皆然。愚曰：「此证虽危易治，得萸肉数两，可保无虞。」急取净萸肉四两，人参五钱。先用萸肉二两煎数沸，急服之，心定汗止，气亦接续，又将人参切作小块，用所余萸肉煎浓汤，送下病若失。", "19882": "一人年四十八，大汗淋漓，数日不止，衾褥皆湿，势近垂危，询方于愚。俾用净萸肉二两，煎汤饮之，汗遂止。翌晨，迎愚诊视，其脉沉迟细弱，而右部之沉细尤甚，虽无大汗，遍体犹湿。疑其胸中大气下陷，询之，果觉胸中气不上升，有类巨石相压，乃恍悟前次之大汗淋漓，实系大气陷后，卫气无所统摄而外泄也，遂用生黄耆一两，萸肉、知母各三钱，一剂胸次豁然，汗亦尽止，又服数剂以善其后。", "19883": "至外感之邪不净而出汗者，亦可重用山萸肉以敛之。邑张××之子，年十八九，因伤寒服表药太过，汗出不止，心中怔忡，脉洪数不实，大便数日未行。为疏方，用净萸肉、生山药、生石膏各一两，知母、生龙骨、生牡蛎各六钱，甘草二钱，煎服两剂全愈。", "19884": "门生万××，曾治一壮年男子，因屡经恼怒之余，腹中常常作疼。他医用通气、活血、消食、祛寒之药，皆不效。诊其脉左关微弱，知系怒久伤肝，肝虚不能疏泄也。遂用净萸肉二两，佐以当归、丹参、柏子仁各数钱，连服数剂，腹疼遂愈。后凡遇此等证，投以此方皆效。", "19885": "【附案】一妇人年三十许，泄泻半载，百药不效，脉象濡弱，右关尤甚，知其脾胃虚也，俾用生白术轧细焙熟，再用熟枣肉六两，和为小饼，炉上炙干，当点心服之，细细嚼咽，未尽剂而愈。", "19886": "一妇人因行经下血不止，服药旬余无效，势极危殆。诊其脉象浮缓，按之即无，问其饮食不消，大便滑泻。知其脾胃虚甚，中焦之气化不能健运统摄，下焦之气化因之不固也。遂于治下血药中加白术一两，生鸡内金一两，服一剂血即止，又服数剂以善其后。", "19887": "一人年二十二，喘逆甚剧，脉数至七至，投以滋阴兼纳气降气之剂，不效。后于方中加白术数钱，将药煎出，其喘促亦至极点，不能服药，将药重温三次，始强服下，一剂喘即见轻，连服数剂全愈。后屡用其方以治喘证之剧者，多有效验。", "19888": "一少年咽喉常常发干，饮水连连不能解渴。诊其脉微弱迟濡，当系脾胃湿寒，不能健运，以致气化不升也。投以四君子汤加干姜、桂枝尖，方中白术重用两许，一剂其渴即止。", "19889": "周姓妇，年三十许，连连呕吐，五六日间，勺水不存，大便亦不通行，自觉下脘之处疼而且结，凡药之有味者入口即吐，其无味者须臾亦复吐出，医者辞不治。后愚诊视其脉有滑象，上盛下虚，疑其有妊，询之月信不见者五十日矣，然结证不开，危在目前，《内经》谓「有故无殒亦无殒也」。遂单用赭石二两，煎汤饮下，觉药至结处不能下行，复返而吐出。继用赭石四两，又重罗出细末两许，将余三两煎汤，调细末服下，其结遂开，大便亦通，自此安然无恙，至期方产。", "19890": "广平县吕××妻，年二十余，因恶阻呕吐甚剧。九日之间饮水或少存，食物则尽吐出。延为诊视，脉象有力，舌有黄苔，询其心中发热，知系夹杂外感，遂先用生石膏两半，煎汤一茶杯，防其呕吐，徐徐温饮下，热稍退。继用生赭石二两，煎汤一大茶杯，分两次温饮下，觉行至下脘作疼，不复下行转而上逆吐出，知其下脘所结甚坚，原非轻剂所能通。亦用生赭石细末四两，从中再罗出极细末一两，将余三两煎汤，送服其极细末，其结遂开，从此饮食顺利，及期而产。", "19891": "一室女，中秋节后，感冒风寒，三四日间，胸膈满闷，不受饮食，饮水一口亦吐出，剧时恒以手自挠其胸。脉象滑实，右部尤甚，遂单用生赭石细末两半，俾煎汤温饮下，顿饭顷仍吐出。盖其胃口皆为痰涎壅滞，药不胜病，下行不通复转而吐出也。遂更用赭石四两，煎汤一大碗，分三次陆续温饮下，胸次遂通，饮水不吐。翌日，脉象洪长，其舌苔从先微黄，忽变黑色，又重用白虎汤连进两大剂，每剂用生石膏四两，分数次温饮下，大便得通而愈。", "19892": "曲××，年三十余，得瘟病，两三日恶心呕吐，五日之间饮食不能下咽，来院求为诊治。其脉浮弦，数近六至，重按无力，口苦心热，舌苔微黄。因思其脉象浮弦者，阳明与少阳合病也，二经之病机相并上冲，故作呕吐也，心热口苦者，内热已实也，其脉无力而数者，无谷气相助又为内热所迫也。因思但用生赭石煮水饮之，既无臭味，且有凉镇之力，或可不吐。遂用生赭石二两，煎水两茶杯，分二次温饮下，饮完仍复吐出，病人甚觉惶恐，加以久不饮食，形状若莫可支持。愚曰：「无恐，再用药末数钱，必能立止呕吐。」遂单用生赭石细末五钱，开水送服，觉恶心立止，须臾胸次通畅，进薄粥一杯，下行顺利。从此饮食不复呕吐，而心中犹发热，舌根肿胀，言语不利，又用生石膏一两，丹参、乳香、没药、连翘各三钱，连服两剂全愈。", "19893": "癸亥秋，李××之族姊，周身灼热，脉象洪实，心中烦躁怔忡，饮食下咽即呕吐，屡次所服之药，亦皆呕吐不受。视其舌苔黄厚，大便数日未行，知其外感之热已入阳明之府，又挟胃气上逆，冲气上冲也。为疏方，用生赭石细末八钱，生石膏细末两半，蒌仁一两，玄参、天冬各六钱，甘草二钱，将后五味煎汤一大茶杯，先用开水送服赭石细末，继将汤药服下，遂受药不吐，再服一剂全愈。", "19894": "一妇人，年近五旬，得温病，七八日表里俱热，舌苔甚薄作黑色，状类舌斑，此乃外感兼内亏之证。医者用降药两次下之，遂发喘逆。令其子两手按其心口，即可不喘。须臾又喘，又令以手紧紧按住，喘又少停。诊其脉尺部无根，寸部摇摇，此将脱之候也。时当仲夏，俾用生鸡子黄四枚，调新汲井泉水服之，喘稍定。可容取药。遂用赭石细末二钱同生鸡子黄二枚，温水调和服之，喘遂愈，脉亦安定。继服参赭镇气汤以善其后。", "19895": "门人高××曾治一叟，年七十余，得呃逆证，兼小便不通，剧时觉杜塞咽喉，息不能通，两目上翻，身躯后挺，更医数人治不效。高××诊其脉浮而无力，遂用赭石、台参、生山药、生芡实、牛蒡子为方投之，呃逆顿愈。又加竹茹服一剂，小便亦通利。", "19896": "奉天张××，年近四旬，陡然鼻中衄血甚剧，脉象关前洪滑，两尺不任重按，知系上盛下虚之证，自言头目恒不清爽，每睡醒舌干无津，大便甚燥，数日一行。为疏方：赭石、生地黄、生山药各一两，当归、白芍、生龙骨、生牡蛎、怀牛膝各五钱，煎汤送服旱三七细末二钱（凡用生地治吐衄者，皆宜佐以三七，血止后不至淤血留于经络），一剂血顿止。后将生地减去四钱，加熟地、枸杞各五钱，连服数剂，脉亦平和。", "19897": "至寒温之证，不至结胸及心下满闷，惟逆气挟胃热上冲，不能饮食，并不能受药者，宜赭石与清热之药并用。曾治奉天安××之妻，年四十余，临产双生，异常劳顿，恶心呕吐，数日不能饮食，服药亦恒呕吐，精神昏愦，形势垂危，群医辞不治。延愚诊视，其脉洪实，面有火，舌苔黄厚，知系产后温病，其呕吐若是者，阳明府热已实，胃气因热而上逆也。遂俾用玄参两半，赭石一两，同煎服，一剂即热退呕止，可以受食。继用玄参、白芍、连翘以清其余热，病遂全愈。至放胆用玄参而无所顾忌者，以玄参原宜于产乳，《神农本草经》有明文也。", "19898": "下有实寒，上有浮热之证，欲用温热之药以祛其寒，上焦恒格拒不受，惟佐以赭石使之速于下行，直达病所，上焦之浮热转能因之下降。曾治邻村刘某，因房事后恣食生冷，忽然少腹抽疼，肾囊紧缩，大便不通，上焦兼有烦热。医者投以大黄附子细辛汤，上焦烦热益甚，两胁疼胀，便结囊缩，腹疼如故。病家甚觉惶恐，求为诊视。其脉弦而沉，两尺之沉尤甚，先用醋炒葱白熨其脐及脐下，腹中作响，大有开通之意，囊缩腹疼亦见愈，便仍未通。遂用赭石二两，乌附子五钱，当归、苏子各一两，煎汤饮下，即觉药力下行，过两句钟俾煎渣饮之，有顷，降下结粪若干，诸病皆愈。", "19899": "头疼之证，西人所谓脑气筋病也。然恒可重用赭石治愈。近在奉天曾治何姓女，年二十余岁，每日至巳头疼异常，左边尤甚，过午则愈。先经东人治之，投以麻醉脑筋之品不效。后求为诊视，其左脉浮弦有力者，系少阳之火挟心经之热，乘阳旺之时而上升以冲突脑部也。为疏方：赭石、龙骨、牡蛎、龟板、萸肉、白芍各六钱，龙胆草二钱，药料皆用生者，煎服一剂，病愈强半，又服两剂全愈。隔数日，又治鞠姓妇，头疼亦如前状，仍投以此方两剂全愈。", "19900": "癫狂之证，亦西人所谓脑气筋病也，而其脑气筋之所以病者，因心与脑相通之道路（心有四支血脉管通脑）为痰火所充塞也。愚恒重用赭石二两，佐以大黄、朴硝、半夏、郁金，其痰火甚实者，间或加甘遂二钱（为末送服），辄能随手奏效。诚以赭石重坠之力，能引痰火下行，俾心脑相通之路毫无滞碍，则脑中元神，心中识神自能相助为理，而不至有神明瞀乱之时也。在奉天曾治一人，年近三旬，癫狂失心，屡经中、西医治疗，四载分毫无效。来院求为诊治，其脉象沉实，遂投以上所拟方，每剂加甘遂二钱五分，间两日一服（凡药中有甘遂，不可连服）。其不服汤药之二日，仍用赭石、朴硝细末各五钱，分两次服下，如此旬余而愈。", "19901": "内中风之证，忽然昏倒不省人事，《内经》所谓「血之与气并走于上」之大厥也。亦即《史记》扁鹊传所谓「上有绝阳之络下有破阴之纽」之尸厥也。此其风非外来，诚以肝火暴动与气血相并，上冲脑部（西人剖验此证谓脑部皆有死血，或兼积水），惟用药镇敛肝火，宁熄内风，将其上冲之气血引还，其证犹可挽回，此《金匮》风引汤所以用龙骨、牡蛎也。然龙骨、牡蛎，虽能敛火熄风，而其性皆涩，欠下达之力，惟佐以赭石则下达之力速，上逆之气血即可随之而下。曾治奉天杜××，忽然头目眩晕，口眼歪斜，舌强直不能发言，脉象弦长有力，左右皆然，视其舌苔白厚微黄，且大便数日不行，知其证兼内外中风也。俾先用阿斯匹林瓦半，白糖水送下以发其汗，再用赭石、生龙骨、生牡蛎、蒌仁各一两，生石膏两半，菊花、连翘各二钱，煎汤，趁其正出汗时服之，一剂病愈强半，大便亦通。又按其方加减，连服数剂全愈。", "19902": "邻村韩姓媪，年六旬。于外感病愈后，忽然胸膈连心下突胀，腹脐塌陷，头晕项强，妄言妄见，状若疯狂，其脉两尺不见，关前摇摇无根，数至六至，此下焦虚惫，冲气不摄，挟肝胆浮热上干脑部乱其神明也。遂用赭石、龙骨、牡蛎、山药、地黄（皆用生者）各一两，野台参、净萸肉各八钱，煎服一剂而愈。又少为加减再服一剂以善其后。", "19903": "邻村刘××，年三十许，因有恼怒，忽然昏倒不省人事，牙关紧闭，唇齿之间有痰涎随呼气外吐，六脉闭塞若无。急用作嚏之药吹鼻中，须臾得嚏，其牙关遂开。继用香油两余，炖温调麝香末一分，灌下，半句钟时稍醒悟能作呻吟，其脉亦出，至数五至余，而两尺弱甚，不堪重按。知其肾阴亏损，故肝胆之火易上冲也。遂用赭石、熟地、生山药各一两，龙骨、牡蛎、净萸肉各六钱，煎服后豁然顿愈。继投以理肝补肾之药数剂，以善其后。", "19904": "族嫂年三十余岁，身体甚弱，于季春忽患头疼，右边疼尤剧，以致上下眼睑皆疼，口中时溢涎沫，唾吐满地，经血两月未见，舌苔黏腻，左脉弦硬而浮，右脉沉滑。知系气血两虚，内有蕴热，挟肝胆之火上冲头目，且有热痰杜塞中焦也。为疏方用赭石解下所载治何姓女之方加减，生赭石细末六钱，净山萸肉五钱，野台参、生杭芍、生龟板、当归身各三钱。一剂左边疼顿减，而右边之疼如故。遂用前方加丹皮二钱，赭石改用八钱。服后不但头疼悉愈，且口内涎沫亦无，惟月经仍未见，又改用赭石至一两，加川芎二钱。服下，翌日月事亦通。夫赭石向在药物中为罕用之品，而此方用之以治头疼，以治痰涎杜塞，以治月事不见，皆能随手奏效，实赭石之力居多。", "19905": "山药：色白入肺，味甘归脾，液浓益肾。能滋润血脉，固摄气化，宁嗽定喘，强志育神，性平可以常服多服。宜用生者煮汁饮之，不可炒用，以其含蛋白质甚多，炒之则其蛋白质焦枯，服之无效。若作丸散，可轧细蒸熟用之（医方篇一味薯蓣饮后，附有用山药治愈之验案数则可参观）。", "19906": "干地黄（即药房中生地黄）：经日晒干，性凉而不寒，生血脉，益精髓，聪明耳目，治骨蒸劳热，肾虚生热。", "19907": "一童子，年十四五，伤寒已过旬日，大便滑泻不止，心中怔忡异常，似有不能支持之状。脉至七至，按之不实。医者辞不治。投以熟地、生山药、生杭芍各一两，滑石八钱，甘草五钱，煎汤一大碗，徐徐温饮下，亦尽剂而愈。", "19908": "用熟地治寒温，恒为医家所訾。然遇其人真阴太亏，不能支持外感之热者，于治寒温药中，放胆加熟地以滋真阴，恒能挽回人命于顷刻。曾治一室女，资禀素羸弱，得温病五六日，痰喘甚剧。治以《金匮》小青龙汤加石膏，一剂喘顿止。时届晚八点钟，一夜安稳。至寅时喘复作，不若从前之剧，而精神恍惚，心中怔忡。再诊其脉，如水上浮麻不分至数，按之即无，此将脱之候也。取药不暇，幸有预购山药两许，急煎服之，病少愈。此际已疏方取药，方系熟地四两、生山药一两、野台参五钱。而近处药房无野台参，并他参亦鬻尽。再至他处，又恐误事。遂单煎熟地、山药饮之，病愈强半。一日之内，按其方连进三剂，病遂全愈。", "19909": "按：此证原当用拙拟来复汤，其方重用山萸肉以收脱。而当时愚在少年，其方犹未拟出，亦不知重用萸肉。而自晨至暮，共服熟地十二两，竟能救此垂危之证，熟地之功用诚伟哉。又此证初次失处，在服小青龙汤后，未用补药。愚经此证后，凡遇当用小青龙汤而脉稍弱者，服后即以补药继之。或加人参于汤中，恐其性热，可将所加之石膏加重。", "19910": "又：冯氏所著本草，谓熟地能大补肾中元气，此亦确论。凡下焦虚损，大便滑泻，服他药不效者，单服熟地即可止泻。然须日用四五两，煎浓汤服之亦不作闷（熟地少用则作闷多用转不闷），少用则无效。至陈修园则一概抹倒，直视熟地为不可用，岂能知熟地哉。寒温传里之后，其人下焦虚惫太甚者，外邪恒直趋下焦作泄泻，亦非重用熟地不能愈。癸巳秋，一女年三十许，得温病，十余日，势至垂危，将舁于外。同坐贾××谓愚知医，主家延为诊视。其证昼夜泄泻，昏不知人，呼之不应，其脉数至七至，按之即无。遂用熟地黄二两，生山药、生杭芍各一两，甘草三钱，煎汤一大碗，趁温徐徐灌之，尽剂而愈。", "19911": "甘草：性微温，其味至甘。能解一切毒性。甘者主和，故有调和脾胃之功，甘者主缓，故虽补脾胃而实非峻补。炙用则补力较大，是以方书谓胀满证忌之。若轧末生服，转能通利二便，消胀除满。若治疮疡亦宜生用，或用生者煎服亦可。仲景有甘草泻心汤，用连、苓、半夏以泻心下之痞，即用甘草以保护心主，不为诸药所伤损也。至白虎汤用之，是借其甘缓之性以缓寒药之侵下。通脉汤、四逆汤用之，是借其甘缓之性，以缓热药之僭上。与芍药同用，能育阴缓中止疼，仲景有甘草芍药汤。与干姜同用，能逗留其热力使之绵长，仲景有甘草干姜汤。与半夏、细辛诸药同用，能解其辛而且麻之味，使归和平。惟与大戟、芫花、甘遂、海藻相反，余药则皆相宜也。", "19912": "邹润安曰：凡药所以致生气于病中，化病气为生气也。凡用药取其禀赋之偏，以救人阴阳之偏胜也。是故药物之性，未有不偏者。徐洄溪曰：药之用，或取其气，或取其味，或取其色，或取其形，或取其质，或取其性情，或取其所生之时，或取其所成之地。愚谓：丹砂，则取其质与气与色为用者也。质之刚是阳，内含汞则阴气之寒是阴，色纯赤则阳，故其义为阳抱阴，阴承阳，禀自先天，不假作为。人之有生以前，两精相搏即有神，神依于精乃有气，有气而后有生，有生而后知识具以成其魂，鉴别昭以成其魄，故凡精气失其所养，则魂魄遂不安，欲养之安之，则舍阴阳紧相抱持，密相承接之丹砂又奚取乎？然谓主身体五脏百病，养精神，安魂魄，益气明目何也？夫固以气寒，非温煦生生之具，故仅能于身体五脏百病中，养精神安魂魄益气明目耳。若身体五脏百病中，其不必养精神安魂魄益气明目者，则不必用丹砂也。血脉不通者，水中之火不继续也，烦满消渴者，火中之水失滋泽也，中恶腹痛阴阳不相保抱，邪得乘间以入，毒气疥瘘诸疮，阳不畜阴而反灼阴，得惟药之阳抱阴，阴涵阳者治之，斯阳不为阴贼，阴不为阳累，诸疾均可已矣。按此为邹氏释《神农本草经》之文，可谓精细入微矣。", "19913": "愚于忽然中风肢体不遂之证，其脉甚弦硬者，知系肝火肝风内动，恒用龙骨同牡蛎加于所服药中以敛戢之，至脉象柔和其病自愈，拙拟镇肝熄风汤、建瓴汤，皆重用龙骨，方后皆有验案可参观。", "19914": "龙骨若生用之，凡心中怔忡、虚汗淋漓、经脉滑脱、神魂浮荡诸疾，皆因元阳不能固摄，重用龙骨，借其所含之元阴以翕收此欲涣之元阳，则功效立见。若煅用之，其元阴之气因煅伤损，纵其质本黏涩，煅后其黏涩增加，而其翕收之力则顿失矣。用龙骨者用其黏涩，诚不如用其吸收也。明乎此理，则龙骨之不宜煅益明矣。王洪绪《外科证治全生集》谓：「用龙骨者宜悬之井中经宿而后用之」，是可谓深知龙骨之性，而善于用之者矣。愚用龙骨约皆生用，惟治女子血崩，或将流产，至极危时恒用煅者，取其涩力稍胜以收一时之功也。", "19915": "【附案】一童子年十五六岁，于季春得温病，经医调治，八九日间大热已退，而心犹发热，怔忡莫支，小便不利，大便滑泻，脉象虚数，仍似外邪未净，为疏方，用生杭芍二两，炙甘草一两半，煎汤一大碗徐徐温饮下，尽剂而愈。夫《神农本草经》谓芍药益气，元素谓其止泻利，即此案观之洵不误也。然必以炙草辅之，其功效乃益显。", "19916": "邻村周××，年二十余，得温病，医者用药清解之，旬日其热不退。诊其脉左大于右者一倍，按之且有力。夫寒温之热传入阳明，其脉皆右大于左，以阳明之脉在右也。即传入少阳厥阴，其脉亦右大于左，因既挟有外感实热，纵兼他经，仍以阳明为主也。此证独左大于右，乃温病之变证，遂投以小剂白虎汤（方中生石膏止用五钱），重加生杭芍两半，煎汤两茶杯顿饮之，须臾小便一次甚多，病若失。", "19917": "邻村霍氏妇，周身漫肿，腹胀小便不利，医者治以五皮饮不效。其脉数而有力，心中常觉发热，知其阴分亏损，阳分又偏盛也。为疏方，用生杭芍两半，玄参、滑石、地肤子、甘草各三钱，煎服一剂即见效验，后即方略为加减，连服数剂全愈。", "19918": "奉天陈某，年四十余，自正月中旬，觉心中发热懒食，延至暮春，其热益甚，常常腹疼，时或泄泻，其脉右部弦硬异常，按之甚实，舌苔微黄。知系外感伏邪，因春萌动，传入胃府，久而化热，而肝木复乘时令之旺以侮克胃土，是以腹疼且泄泻也。其脉象不为洪实而现弦硬之象者，因胃土受侮，亦从肝木之化也。为疏方，用生杭芍、生怀山药、滑石、玄参各一两，甘草、连翘各三钱，煎服一剂，热与腹疼皆愈强半，可以进食，自服药后大便犹下两次。诊其脉象已近和平，遂将方中芍药、滑石、玄参各减半，又服一剂全愈。", "19919": "陈姓妇，年二十余，于季春得温病，四五日间延为诊治。其证表里俱热，脉象左右皆洪实，腹中时时切疼，大便日下两三次、舌苔厚而微黄，知外感邪热已入阳明之府，而肝胆乘时令木气之旺，又挟实热以侮克中土，故腹疼而又大便勤也。亦投以前方，加鲜茅根三钱，一剂腹疼便泻即止，又服一剂全愈。观此二案，《伤寒论》诸方，腹痛皆加芍药，不待疏解而自明也。至于茅根入药必须鲜者方效，若无鲜者可不用。", "19920": "一人年三十余，头疼数年，服药或愈，仍然反复，其脉弦而有力，左关尤甚，知其肝血亏损肝火炽盛也。投以熟地、柏实各一两，生龙骨、生牡蛎、龙胆草、生杭芍、枸杞各四钱，甘草、芎䓖各二钱，一剂疼止，又服数剂永不反复。", "19921": "《金匮》泻心汤，诚为治吐血、衄血良方，惟脉象有实热者宜之。若脉象微似有热者，愚恒用大黄三钱，煎汤送服赤石脂细末四五钱。若脉象分毫无热，且心中不觉热者，愚恒用大黄细末、肉桂细末各六七分，用开水送服即愈。", "19922": "大黄之力虽猛，然有病则病当之，恒有多用不妨者。是以治癫狂其脉实者，可用至二两，治疔毒之毒热甚盛者，亦可用至两许。盖用药以胜病为准，不如此则不能胜病，不得不放胆多用也。", "19923": "奉天于姓妇，年近五旬，因心热生痰，痰火瘀滞，烦躁不眠，五心潮热，其脉象洪实。遂用朴硝和炒熟麦面炼蜜为丸，三钱重，每丸中约有朴硝一钱，早晚各服一丸，半月全愈。盖人多思虑则心热气结，其津液亦恒随气结于心下，经心火灼炼而为热痰。朴硝咸且寒，原为心经对宫之药，其咸也属水，力能胜火，而又寒能胜热，且其性善消，又能开结，故以治心热有痰者最宜。至于必同麦面为丸者，以麦为心谷，心脏有病以朴硝泻之，即以麦面补之，补破相济为用，则药性归于和平，而后可久服也。", "19924": "厚朴：味苦辛，性温。治胃气上逆，恶心呕哕，胃气郁结胀满疼痛，为温中下气之要药。为其性温味又兼辛，其力不但下行，又能上升外达，故《神农本草经》谓其主中风伤寒头痛，《金匮》厚朴麻黄汤，用治咳而脉浮。与橘、夏并用，善除湿满；与姜、术并用，善开寒痰凝结；与硝、黄并用，善通大便燥结；与乌药并用，善治小便因寒白浊。味之辛者属金，又能入肺以治外感咳逆；且金能制木，又能入肝、平肝木之横恣以愈胁下掀疼；其色紫而含有油质，故兼入血分，甄权谓其破宿血，古方治月闭亦有单用之者。诸家多谓其误服能脱元气，独叶香岩谓「多用则破气，少用则通阳」，诚为确当之论。", "19925": "东人××博士，用麻黄十瓦，煎成水一百瓦，为一日之量，分三次服下，治慢性肾炎小便不利及肾脏萎缩小便不利，用之有效有不效，以其证之凉热虚实不同，不知用他药佐之以尽麻黄之长也。试观《金匮》水气门越婢汤，麻黄辅以石膏，因其脉浮有热也（脉浮故系有风实亦有热），麻黄附子汤辅以附子，因其脉沉而寒也。通变化裁，息息与病机相符，是真善用麻黄者矣。", "19926": "【附案】一人年过四旬，胁下掀疼，大便七八日未行，医者投以大承气汤，大便未通而胁下之疼转甚。其脉弦而有力，知系肝气胆火恣盛也，投以拙拟金铃泻肝汤加柴胡、龙胆草各四钱，服后须臾大便通下，胁疼顿愈。审是，则《神农本草经》谓「柴胡主肠胃中饮食积聚，推陈致新」者，诚非虚语也。且不但能通大便也，方书通小便亦多有用之者，愚试之亦颇效验。盖小便之下通，必由手少阳三焦，三焦之气化能升而后能降，柴胡不但升足少阳实兼能升手少阳也。", "19927": "桂枝非发汗之品，亦非止汗之品，其宣通表散之力，旋转于表里之间，能和营卫、暖肌肉、活血脉，俾风寒自解，麻痹自开，因其味辛而且甘，辛者能散，甘者能补，其功用在于半散半补之间也。故服桂枝汤欲得汗者，必啜热粥，其不能发汗可知；若阳强阴虚者，误服之则汗即脱出，其不能止汗可知。", "19928": "本庄黄氏妇，年过四旬，因行经下血不止，彼时愚甫弱冠，为近在比邻，延为诊视，投以寻常治血崩之药不效，病势浸至垂危。后延邻村宿医高××，投以《傅青主女科》中治老妇血崩方，一剂而愈。其方系黄耆、当归各一两，桑叶十四片，煎汤送服三七细末三钱。后愚用此方治少年女子血崩亦效，惟心中觉热，或脉象有热者，宜加生地黄一两。", "19929": "天津刘××，偶患大便下血甚剧。西医注射以止血药针，其血立止。而血止之后，月余不能起床，身体酸软，饮食减少。其脉芤而无力，重按甚涩。因谓病家曰：「西人所注射者，流动麦角膏也。其收缩血管之力甚大，故注射之后，其血顿止。然止后宜急服化瘀血之药，则不归经之血，始不至凝结于经络之间为恙。今但知止血，而不知化血，积之日久必成劳瘵，不仅酸软减食已也。然此时尚不难治，下其瘀血即愈矣。」俾日用三七细末三钱，空心时分两次服下。服至三次后，自大便下瘀血若干，色紫黑。从此每大便时，必有瘀血随下。至第五日，所下渐少。至第七日，即不见瘀血矣。于斯停药不服。旬日之间，身体复初。由斯观之，是三七一味即可代《金匮》之下瘀血汤，且较下瘀血汤更稳妥也。", "19930": "仲夏，杨姓女，年七岁，患疳疾兼大便下血，身形羸弱，不思饮食，甚为危险。前所服中西治疳积之药若干，均无效，来寓求治。后学检视腹部，其回血管现露，色青微紫，腹胀且疼，两颧发赤，潮热有汗，目睛白处有赤丝，口干不渴，六脉沉数，肌肤甲错，毛发焦枯。审证辨脉，知系瘀血为恙也。踌躇再四，忽忆及向阅《衷中参西录》，见先生论用三七之特殊功能，历数诸多奇效，不但善于止血，且更善化瘀血。遂俾用三七研为精粉，每服七分，朝夕空心时各服一次，服至五日，而大便下血愈。又服数日，疳疾亦愈。用三七一味，治愈中、西诸医不能治之大病，药性之妙用，真令人不可思议矣。", "19931": "外感大热已退而阴亏脉数不能自复者，可于大滋真阴药中（若熟地黄、生山药、枸杞之类）少加滑石，则外感余热不至为滋补之药逗留，仍可从小便泻出，则其病必易愈。若与甘草为末（滑石六钱，甘草一钱，名六一散，亦名天水散）服之，善治受暑及热痢；若与赭石为末服之，善治因热吐血、衄血；若其人蕴有湿热、周身漫肿、心腹膨胀、小便不利者，可用滑石与土狗研为散服之，小便通利肿胀自消，至内伤阴虚作热，宜用六味地黄汤以滋阴者，亦可少加滑石以代苓、泽，则退热较速。盖滑石虽为石类，而其质甚软，无论汤剂丸散，皆与脾胃相宜，故可加于六味汤中以代苓、泽。其渗湿之力，原可如苓、泽行熟地之滞泥，而其性凉于苓、泽，故又善佐滋阴之品以退热也。", "19932": "友人袁××，素知医，时当季春，牙疼久不愈，屡次服药无效。其脉两寸甚实，俾用怀牛膝、生赭石各一两，煎服后，疼愈强半，又为加生地黄一两，又服两剂，遂霍然全愈。", "19933": "【附案】邻村高××子，年十三岁，于数日之间，痰涎郁于胸中，烦闷异常，剧时气不上达，呼吸即停，目翻身挺，有危在顷刻之状。连次用药，分毫无效，敢乞往为诊视，施以良方。时愚有急务未办，欲迟数点钟再去，彼谓此病已至极点，若稍迟延恐无及矣。于是遂与急往诊视，其脉关前浮滑，舌苔色白，肌肤有热，知其为温病结胸，俾用栝蒌仁四两，炒熟（新炒者其气香而能通）捣碎，煎汤两茶盅，分两次温饮下，其病顿愈。隔数日，其邻高姓童子，亦得斯证，俾用新炒蒌仁三两，苏子五钱，煎服，亦一剂而愈。盖伤寒下早成结胸，温病未经下亦可成结胸，有谓栝蒌力弱，故小陷胸汤中必须伍以黄连、半夏始能建功者，不知栝蒌力虽稍弱，重用之则转弱为强，是以重用至四两，即能随手奏效，挽回人命于顷刻也。", "19934": "【附案】邻村高某年四十余，小便下血，久不愈。其脉微细而迟，身体虚弱恶寒，饮食减少。知其脾胃虚寒，中气下陷，黄坤载所谓血之亡于便溺者，太阴不升也。为疏方：干姜、于术各四钱，生山药、熟地各六钱，乌附子、炙甘草各三钱，煎服一剂血见少，连服十余剂全愈。", "19935": "附子：味辛，性大热。为补助元阳之主药，其力能升能降，能内达能外散，凡凝寒锢冷之结于脏腑、著于筋骨、痹于经络血脉者，皆能开之，通之。而温通之中，又大具收敛之力，故治汗多亡阳（汗多有亡阳亡阴之殊，亡阳者身凉，亡阴者身热，临证时当审辨。凉亡阳者，宜附子与萸肉、人参并用；热亡阴者，宜生地与萸肉、人参并用），肠冷泄泻，下焦阳虚阴走，精寒自遗，论者谓善补命门相火，而服之能使心脉跳动加速，是于君相二火皆能大有补益也。", "19936": "【附案】一少妇上焦满闷烦躁，不能饮食，绕脐板硬，月信两月未见。其脉左右皆弦细。仲景谓双弦者寒，偏弦者饮，脉象如此，其为上有寒饮、下有寒积无疑。其烦躁者腹中寒气充溢，迫其元阳浮越也。投以理饮汤，去桂枝加附子三钱，方中芍药改用五钱，一剂满闷烦躁皆见愈。又服一剂能进饮食，且觉腹中凉甚，遂去芍药将附子改用五钱，后来又将干姜减半，附子加至八钱，服逾十剂，大便日行四五次，所下者多白色冷积，汤药仍日进一剂，如此五日，冷积泻尽，大便自止。再诊其脉，见有滑象，尺部较甚，疑其有妊，俾停药勿服，后至期果生子。夫附子原有殒胎之说，此证服附子如此之多，而胎固安然无恙，诚所谓「有故无殒亦无殒也」。", "19937": "肉桂：味辛而甘，气香而窜，性大热纯阳。为其为树身近下之皮，故性能下达，暖丹田，壮元阳，补相火。其色紫赤，又善补助君火，温通血脉，治周身血脉因寒而痹，故治关节腰肢疼痛及疮家白疽。木得桂则枯，且又味辛属金，故善平肝木，治肝气横恣多怒，若肝有热者，可以龙胆草、芍药诸药佐之。《神农本草经》谓其为诸药之先聘通使，盖因其香窜之气内而脏腑筋骨，外而经络腠理，倏忽之间莫不周遍，故诸药不能透达之处，有肉桂引之，则莫不透达也。", "19938": "知母原不甚寒，亦不甚苦，尝以之与黄耆等分并用，即分毫不觉凉热，其性非大寒可知。又以知母一两加甘草二钱煮饮之，即甘胜于苦，其味非大苦可知。寒苦皆非甚大，而又多液是以能滋阴也。有谓知母但能退热，不能滋阴者，犹浅之乎视知母也。是以愚治热实脉数之证，必用知母，若用黄耆补气之方，恐其有热不受者，亦恒辅以知母，惟有液滑能通大便，其人大便不实者忌之。", "19939": "天冬：味甘微辛，性凉，津液浓厚滑润。其色黄兼白，能入肺以清燥热，故善利痰宁嗽；入胃以消实热，故善生津止渴。津浓液滑之性，能通利二便、流通血脉、畅达经络，虽为滋阴之品，实兼能补益气分。", "19940": "濒湖又曰：「余年二十时，因感冒咳嗽既久，且犯戒，遂病骨蒸发热，肤如火燎，每日吐痰碗许，暑月烦渴，寝食俱废，六脉浮洪，遍服柴胡、麦冬、荆沥诸药，月余益剧，皆以为必死矣。先君偶思李东垣治肺热如火燎，烦躁引饮而昼盛者气分热也，宜一味黄芩汤，以泻肺经气分之火。遂按方用片芩一两，水二盅煎一盅顿服，次日身热尽退，而痰嗽皆愈，药中肯棨，如鼓应桴，医中之妙有如此哉。」观濒湖二段云云，其善清气分之热，可为黄芩独具之良能矣。", "19941": "【附案】一人年近五旬，受温疹之毒传染，痧疹遍身，表里壮热，心中烦躁不安，证实脉虚，六部不起，屡服清解之药无效，其清解之药稍重，大便即溏。俾用鲜茅根六两，煮汤一大碗顿服之，病愈强半，又服一次全愈。", "19942": "一西医得温病，头疼壮热，心中烦躁，自服西药退热之品，服后热见退，旋又反复。其脉似有力，惟在浮分、中分，俾用鲜茅根四两、滑石一两，煎三四沸，取汤服之，周身得微汗，一剂而诸病皆愈。", "19943": "一妇人年近四旬，因阴虚发热，渐觉小便不利，积成水肿，服一切通利小便之药皆无效。其脉数近六至，重按似有力，问其心中常觉烦躁，知其阴虚作热，又兼有实热，以致小便不利而成水肿也。俾用鲜茅根半斤，煎汤两大碗，以之当茶徐徐温饮之，使药力昼夜相继，连服五日，热退便利，肿遂尽消。", "19944": "一少年每年吐血，反复三四次，数年不愈。诊其脉，血热火盛，俾日用鲜小蓟根二两，煮汤数盅，当茶饮之，连饮二十余日，其病从此除根。", "19945": "一少年常患头疼，诊其脉肝胆火盛，治以茵陈、川芎、菊花各二钱，一剂疼即止。又即原方为加龙胆草二钱，服两剂觉头部轻爽异常，又减去川芎，连服四剂，病遂除根。", "19946": "【附案】忆在籍时，曾治沧州董姓妇人，患血崩甚剧。其脉象虚而无力，遂重用黄耆、白术，辅以龙骨、牡蛎、萸肉诸收涩之品，服后病稍见愈，遂即原方加海螵蛸四钱，茜草二钱，服后其病顿愈，而分毫不见血矣。愚于斯深知二药止血之能力，遂拟得安冲汤、固冲汤二方，于方中皆用此二药。", "19947": "本邑一少妇，累年多病，身形羸弱，继又下白带甚剧，屡经医治不效。诊其脉迟弱无力，自觉下焦凉甚，治以清带汤，为加干姜六钱、鹿角胶三钱、炙甘草三钱，连服十剂全愈。统以上经验观之，则海螵蛸、茜草之治带下不又确有把握哉。至其能消症瘕与否，因未尝单重用之，实犹欠此经验而不敢遽定也。", "19948": "【附案】族家婶母，年四旬，足大指隐白穴处，忽然破裂出血，且色紫甚多，外科家以为疔毒，屡次服药不效。时愚甫习医，诊其脉洪滑有力，知系血热妄行，遂用生地黄两半、碎竹茹六钱，煎汤服之，一剂血止，又服数剂，脉亦平和。盖生地黄凉血之力，虽能止血，然恐止后血瘀经络致生他病，辅以竹茹宣通消瘀，且其性亦能凉血止血，是以有益而无弊也。", "19949": "友人刘××之女，得温病，邀愚往视。其证表里俱热，胃口满闷，时欲呕吐，舌苔白而微黄，脉象洪滑，重按未实，问其大便，昨行一次微燥，一医者欲投以调胃承气汤，疏方尚未取药。愚曰：「此证用承气汤尚早」，遂另为疏方，用生石膏一两、碎竹茹六钱、青连翘四钱，煎汤服后，周身微汗，满闷立减，亦不复欲呕吐，从前小便短少，自此小便如常，其病顿愈。", "19950": "【附案】近族曾孙女××，自动失乳，身形羸弱，自六七岁时恒发咳嗽，后至十一二岁嗽浸增剧，概服治嗽药不效。愚俾用生怀山药细末熬粥，调以白糖令适口，送服生鸡内金细末二三分，或西药百布圣二瓦，当点心服之，年余未间断。劳嗽虽见愈，而终不能除根。诊其脉，肺胃似皆有热，遂俾用北沙参轧为细末，每服二钱，日两次。服至旬余，咳嗽全愈。然恐其沙参久服或失于凉，改用沙参三两、甘草二两，共轧细，亦每服二钱，以善其后。", "19951": "连翘善理肝气，既能舒肝气之郁，又能平肝气之盛。曾治一媪，年过七旬，其手连臂肿疼数年不愈，其脉弦而有力，遂于清热消肿药中，每剂加连翘四钱，旬日肿消疼愈，其家人谓媪从前最易愤怒，自服此药后不但病愈，而愤怒全无，何药若是之灵妙也！由是观之，连翘可为理肝气要药矣。", "19952": "【附录】友人竹××曰：「嵊县吴氏一家，以种苓为业。春间吴氏之媳病，盖产后月余，壮热口渴不引饮，汗出不止，心悸不寐，延余往治。病人面现红色，脉有滑象，急用甘草、麦冬、竹叶、柏子仁、浮小麦、大枣煎饮不效；继用酸枣仁汤，减川芎加浮小麦、大枣，亦不效；又用归脾汤加龙骨、牡蛎、萸肉则仍然如故。当此之时，余束手无策，忽一人进而言曰：『何不用补药以缓之』，余思此无稽之谈，所云补药者，心无见识也，姑漫应之。时已届晚寝之时，至次日早起，其翁奔告曰：『予媳之病昨夜用补药医痊矣。』余将信将疑，不识补药究系何物。乃翁持渣来见，钵中有茯苓四五两，噫！茯苓焉，胡为云补药哉？余半晌不能言。危坐思之，凡病有一线生机，皆可医治。茯苓固治心悸之要药，亦治汗出之主药。仲景治伤寒汗出而渴者五苓散，不渴者茯苓甘草汤。伤寒厥而心下悸者宜先治水，当服茯苓甘草汤。可知心悸者汗出过多，心液内涸，肾水上救入心则悸，余药不能治水，故用茯苓以镇之。是证心悸不寐，其不寐由心悸而来，即心悸亦从汗出而来，其壮热口渴不引饮、脉滑，皆有水气之象，今幸遇种苓家，否则汗出不止，终当亡阳，水气凌心，必当灭火，是谁之过欤？余引咎而退。」观竹××此论，不惜暴一己之失，以为医界说法，其疏解经文之处，能将仲景用茯苓之深意，彰彰表出，固其析理之精，亦见其居心之厚也。", "19953": "湖北天门县崔××来函云：一九三。年，李姓妇，头目眩晕、心中怔忡、呕吐涎沫，有时觉气上冲，昏愦不省人事。他医治以安神之药无效，继又延医十余人皆服药无效，危险已至极点。生诊其脉，浮而无力，视其形状无可下药。恍悟《衷中参西录》茯苓解中，所论重用茯苓之法，当可挽回此证。遂俾单用茯苓一两煎汤服之，服后甫五分钟，病即轻减，旋即煎渣再服，益神清气爽，连服数剂，病即全愈。后每遇类此证者，投此方皆可奏效。", "19954": "【附案】一少年心中怔忡，夜不能寐，其脉弦硬微数，知其心脾血液短也，俾购龙眼肉，饭甑蒸熟，随便当点心，食之至斤余，病遂除根。", "19955": "《神农本草经》谓柏实能安五脏，而实于肝脏尤宜也。曾治邻村毛姓少年，其肝脏素有伤损，左关脉独微弱，一日忽胁下作疼，俾单用柏子仁一两，煎汤服之立愈。观此，则柏子仁善于理肝可知矣。", "19956": "大枣：味甘微辛，性温。其津液浓厚滑润，最能滋养血脉、润泽肌肉、强健脾胃、固肠止泻、调和百药能缓猛药健悍之性，使不伤脾胃。是以十枣汤、葶苈大枣汤诸方用之。若与生姜并用，为调和营卫之妙品，是以桂枝汤、柴胡汤诸方用之。《内经》谓其能安中者，因其味至甘能守中也。又谓其能通九窍者，因其津液滑润且微有辛味，故兼有通利之能也。谓其补少气少津液者，为其味甘能益气，其津液浓厚滑润，又能补人身津液之不足也。虽为寻常食品，用之得当能建奇功。", "19957": "上方加杜仲一斤，生姜炒蒜四两，同为丸，名青娥丸。治肾虚腰疼，而此方不但治肾虚腰疼也，以治虚寒腿疼亦极效验。曾治一媪年过六旬，腿疼年余不愈，其脉两尺沉细，俾日服青娥丸月余全愈。若虚寒之甚者，可于方中加生硫黄三两。", "19958": "萆薢为治失溺要药不可用之治淋。《名医别录》谓萆薢治阴萎、失溺、老人五缓。盖失溺之证实因膀胱之括约筋少约束之力，此系筋缓之病，实为五缓之一，萆薢善治五缓，所以治之。拙拟醒脾升陷汤中，曾重用萆薢以治小便频数不禁，屡次奏效，是萆薢为治失溺之要药可知矣。乃萆薢分清饮竟用之以治膏淋，何其背谬若是？愚在籍时，邻村有病淋者，医者投以萆薢分清饮，两剂，其人小便滴沥不通。再服各种利小便药，皆无效。后延愚诊治，已至十日，精神昏愦，毫无知觉，脉数近十至，按之即无，因谓其家人曰：「据此脉论，即小便通下，亦恐不救。」其家人恳求甚切，遂投以大滋真阴之剂，以利水之药佐之。灌下移时，小便即通，床褥皆湿。再诊其脉，微细欲无，愚急辞归。后闻其人当日即亡。近又在津治一淋证，服药十剂已愈，隔两月病又反复，时值愚回籍，遂延他医治疗，方中亦重用萆薢。服两剂，小便亦滴沥不通，服利小便药亦无效。遂屡用西法引溺管兼服利小便之药，治近一旬，小便少通滴沥，每小便一次，必须两小时。继又服滋阴利水之药十剂始全愈。", "19959": "女子干血劳之证，最为难治之证也，是以愈者恒少。惟善用鸡内金者，则治之多能奏效。愚向为妇女治病，其廉于饮食者，恒白术与鸡内金并用。乃有两次遇有此药者，一月间月信来三次，恍悟此过用鸡内金之弊也。盖鸡内金善化瘀血，即能催月信速于下行也。然月信通者服之，或至过通，而月信之不通者服之，即不难下通。况《内经》谓「中焦受气取汁，变化而赤，是为血。」血之来源，原在脾胃能多消饮食。鸡内金与白术并用，原能健脾胃以消饮食也。况脾为后天资生之本，居中央以灌溉四旁。此证之多发劳嗽者，脾虚肺亦虚也，多兼灼热者，脾虚而肾亦虚也。再加山药、地黄、枸杞诸药以补肺滋肾，有鸡内金以运化之，自能变其浓厚之汁浆为精液，以灌注于肺肾也。迨至服药日久，脏腑诸病皆愈，身体已渐复原，而月信仍不至者，不妨再加䗪虫、水蛭诸药。如嫌诸药之猛悍，若桃仁、红花亦可以替代。然又须多用补正之药品以驾驭之，始能有益而无害也。愚向曾本此意拟一方，名资生通脉汤，后列用其方治愈之案数则，可参观也。", "19960": "至于病又加重，身体虚弱劳嗽，宜用拙拟资生通脉汤。此方之后，载有数案，且用此方各有加减，若服资生通脉汤，病虽见愈月信仍不至者，可参观所附案中加减诸方。", "19961": "上所论诸方之外，愚有新拟之方，凡服资生通脉汤病见愈而月信不见者，可用生怀山药四两，煮浓汁，送眼生鸡内金细末三钱。所余山药之渣，仍可水煮数次，当茶饮之。久之月信必至，盖鸡内金生用，为通月信最要之药，而多用又恐稍损气分，故又多用山药至四两，以培气分也。", "19962": "【附案】沈阳龚××，年三十岁，胃脘有硬物杜塞，已数年矣。饮食减少，不能下行，来院求为诊治，其脉象沉而微弦，右部尤甚，为疏方，用鸡内金一两，生酒曲五钱，服数剂硬物全消。", "19963": "奉天史××，年近四旬，为腹有积聚，久治不愈，来院求为诊治。其积在左胁下大径三寸，按之甚硬，时或作疼，呃逆气短，饮食减少，脉象沉弦。此乃肝积肥气之类。俾用生鸡内金三两，柴胡一两，共为末，每服一钱半，日服三次，旬余全愈。", "19964": "奉天秦××，年三十余，胃中满闷，不能饮食，自觉贲门有物窒碍，屡经医治，分毫无效。脉象沉牢，为疏方：鸡内金六钱，白术、赭石各五钱，乳香、没药、丹参各四钱，生桃仁二钱，连服八剂全愈。", "19965": "奉天宋氏女，年十九岁，自十七岁时，胃有瘀滞作疼，调治无效，浸至不能饮食。脉象沉而无力，右部尤甚，为疏方：鸡内金一两，生酒曲、党参各五钱，三棱、莪术、知母各三钱，樗鸡（俗名红娘子）十五个，服至八剂，大小二便皆下血，胃中豁然，其疼遂愈。", "19966": "盐山李氏妇，年三旬，胃脘旧有停积数年不愈，渐大如拳甚硬，不能饮食。左脉弦细，右脉沉濡，为疏方：鸡内金八钱，生箭耆六钱，三棱、莪术、乳香、没药各三钱，当归、知母各四钱，连服二十余剂积全消。", "19967": "凡破血之药，多伤气分，惟水蛭味咸专入血分，于气分丝毫无损。且服后腹不觉疼，并不觉开破，而瘀血默消于无形，真良药也。愚治妇女月闭症瘕之证，其脉不虚弱者，恒但用水蛭轧细，开水送服一钱，日两次。虽数年瘀血坚结，一月可以尽消。", "19968": "【附案】壬寅之岁，季春夜半，表弟刘××之子，年六岁，于数日间出疹，因其苦于服药，强与之即作呕吐，所以未求诊视。今夜忽大喘不止，有危在顷刻之势，不知还可救否。遂与同往视之，见其不但喘息迫促，且精神恍惚，肢体骚扰不安；脉象摇摇而动，按之无根；其疹出第三日即靥，微有紫痕，知其毒火内攻，肝风已动也。因思熄风、清火，且托毒外出，惟羚羊角一味能兼擅其长，且色味俱无，煎汤直如清水，孺子亦不苦服。遂急取羚羊角三钱煎汤，视其服下，过十余分钟即安然矣。", "19969": "奉天韩姓媪，年六十余，臂上生疔毒，外科不善治疗，致令毒火内攻，热痰上壅，填塞胸臆，昏不知人。有东医数人为治移时不愈，气息益微。延为诊视，知系痰厥。急用蓬砂五钱，煮至融化，灌下三分之二，须臾呕出痰涎若干，豁然顿醒。而患处仍肿疼，其疔生于左臂，且左脉较右脉洪紧，知系肝火炽盛，发为肿毒也。遂投以清火解毒之剂，又单将羚羊角二钱煎汤兑服，一剂而愈。", "19970": "奉天王××之幼女，年五岁，因出疹倒靥过急，毒火内郁，已过旬日，犹大热不止，其形体病久似弱，而脉象确有实热，且其大便干燥，小便黄赤，知非轻剂所能治愈。将为疏方，为开羚羊角二钱，生石膏二两，煎汤一大盅，俾徐徐饮下。连服两剂，全愈。", "19971": "奉天陈姓女，年六七岁，疹后旬余灼热不退，屡服西药不效。后愚视之，脉象数而有力，知其疹毒之余热未清也。俾单用羚羊角一钱煎汤饮之，其热顿愈。", "19972": "天津俞××之幼子，年四岁，出疹三日，似靥非靥，周身壮热，渴嗜饮水，其精神似有恍惚不稳之意，其脉象有力，摇摇而动。恐其因热发痉，为开清热托毒之方，加羚羊角一钱以防其发痉，购药至，未及煎而痉发，且甚剧，遂将羚羊角与诸药同时各煎，取汤混合，连连灌下，其痉即愈。又将其方去羚羊角，再煎服一剂，全愈。", "19973": "沧州赵××幼子，年五岁，因感受温病发痉，昏昏似睡，呼之不应，举家惧甚，恐不能救。其脉甚有力，肌肤发热。因晓之曰：「此证因温病之气循督脉上行，伤其脑部，是以发痉，昏昏若睡，即西人所谓脑脊髓炎也。病状虽危，易治也。」遂单用羚羊角二钱，煎汤一盅，连次灌下，发痉遂愈，而精神亦明了矣。继用生石膏、玄参各一两，薄荷叶、连翘各一钱，煎汤一大盅，分数次温饮下，一剂而脉静身凉矣。盖痉之发由于督脉，因督脉上统脑髓神经也（督脉实为脑髓神经之根本）。羚羊之角乃其督脉所生，是以善清督脉与神经之热也。", "19974": "沧州李氏妇，年二十余，因在西医院割瘰疬，住其院中，得伤寒证甚剧，西医不能治。延往诊视，其喘息迫促，脉数近七至，确有外感实热，而重诊无力，因其割瘰疬已至三次，屡次闻麻药，大伤气分故也，其心中觉热甚难支，其胁下疼甚。急用羚羊角二钱，煎一大盅，调入生鸡子黄三枚，服下，心热与胁疼顿止。继投以大剂白虎加人参汤，每剂煎汤一大碗，仍调入生鸡子黄三枚，分数次温服下，连服二剂全愈。", "19975": "阳经为阴经之表，而太阳经又为表中之表。其经之大都会在背，而实则为周身之外廓，周身之营血卫气皆赖其卫护保合，且具有充分之热力，为营卫御外感之内侵，是以《内经》名之为巨阳。推原其热力之由来，不外君、相二火，君火生于心之血脉与肺相循环，而散热于胸中大气（一名宗气）以外通于营卫，此如日丽中天有阳光下济之热也，是以其经名为太阳。相火生于肾中命门，肾原属水，中藏相火，其水火蒸热之气，由膀胱连三焦之脂膜以透达于身之外表，此犹地心水火之气（地中心有水火之气）应春令上透地面以生热也，为其热力发于水中，故太阳之经又名太阳寒水之经也。为太阳经之热力生于君、相二火，是以其经不但以膀胱为府，而亦以胸中为府，观《伤寒论》陷胸诸汤、丸及泻心诸汤，皆列于太阳篇中可知也。至于人病伤寒，其六经相传之次第，详于《内经》素问热论篇，谓「人之伤于寒也则为病热，一日巨阳受之，故头项痛、腰脊强；二日阳明受之，阳明主肌肉，其脉侠（同夹）鼻络于目，故身热目疼，而鼻干不得卧也；三日少阳受之，少阳主胆，其脉循胁络于耳，故胸胁痛而耳聋；三阳经络皆受其病而未入于脏者故可汗而已；四日太阴受之，太阴脉布胃中络于嗌（咽喉），故腹满而嗌干；五日少阴受之，少阴脉贯肾络于肺，系舌本，故口燥舌干而渴，六日厥阴受之，厥阴之脉循阴器而络于肝，故烦满而囊缩。」经络受病入于府者，故可下而已，此《内经》论六经相传之次第也。至《伤寒论》六经之次序，皆以《内经》为法，而未明言其日传一经，至愚生平临证之实验，见有伤寒至旬日，病犹在太阳之府者，至他经相传之日期，亦无一定，盖《内经》言其常，而病情之变化恒有出于常例之外者，至传至某经，即现某经之病状，此又不尽然，推原其所以然之故，且加以生平临证之实验，知传至某经即现某经之病状者，多系因其经先有内伤也。若无内伤则传至某经恒有不即现某经之病时，此在临证者细心体察耳。", "19976": "《伤寒论》原文：太阳病，发热，汗出，恶风，脉缓者（缓脉与迟脉不同，脉搏以一息四至为准，脉迟者不足四至，若缓脉则至数不改似有懒动之意），名为中风。", "19977": "《伤寒论》原文：太阳中风，阳浮而阴弱（脉法关前为阳，关后为阴，其浮脉见于关前，弱脉见于关后，浮者著手即得，弱者不任重按）。阳浮者热自发，阴弱者汗自出，啬啬恶寒。（单弱不胜寒之意），淅淅恶风（为风所伤恒畏风声之意），翕翕发热（其热蕴而不散之意），鼻鸣干呕者，桂枝汤主之。", "19978": "或问：桂枝汤提纲中原谓阴弱者汗自出，未尝言阳弱者汗自出也。夫关后为阴主血，关前为阳主气，桂枝汤证，其弱脉惟见于关后，至关前之脉则见有浮象，未见其弱，而先生竟谓桂枝汤证之出汗，实由于胸中大气之弱，不显与提纲中之言相背乎？答曰：凡受风之脉多见于关前，提纲中所谓阳浮者，其关前之脉因受风而浮也，所谓阴弱者，知其未病之先其脉原弱，至病后而仍不改其弱也，由斯而论，其未病之先，不但关后之脉弱，即关前之脉亦弱，既病之后，其关前脉之弱者转为浮脉所掩，而不见其弱耳。然其脉虽浮，必不任重按，是浮中仍有弱也，特古人立言尚简，未尝细细明言耳。", "19979": "《伤寒论》原文：太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名曰伤寒。", "19980": "脉象阴阳俱紧，实为伤寒之确征。然紧脉之状最难形容，惟深明其病理，自不难想象而得。脉生于心，心一动而外输其血，周身之脉即一动，动则如波浪之有起伏，以理言之，凡脉之力大者，其起伏之势自应愈大。至紧脉其跳动若有力而转若无所起伏，究其所以然之故，实因太阳为外卫之阳，因为寒所袭，逼之内陷与脉相并，则脉得太阳蕴蓄之热，原当起伏有力以成反应之势，而寒气紧缩之力，又复逼压其脉道使不能起伏，是以指下诊之似甚有力而竟直穿而过，且因其不得起伏，蓄极而有左右弹之势，此紧脉真象也。", "19981": "至麻黄汤证，全体作疼痛者，以筋骨不禁寒气之紧缩也（铁条经严寒则缩短寒气紧缩之力可知）。其发热者，身中之元阳为寒气闭塞不能宣散而增热也。其无汗恶风者，汗为寒闭内蕴之热原欲借汗透出，是以恶风也。其作喘者，因手太阴肺经与卫共主皮毛，寒气由皮毛入肺，闭其肺中气管，是以不纳气而作喘。然深究其作喘之由，犹不但此也，人之胸中亦太阳之部位也，其中间所积大气，原与外表之卫气息息相通，然大气即宗气，《灵枢》谓：「宗气积于胸中，出于喉咙，以贯心脉而行呼吸。」夫大气既能以贯心脉，是营血之中亦大气所流通也，伤寒之证，其营卫皆为外寒所束，则大气内郁必膨胀而上逆冲肺，此又喘之所由来也。", "19982": "一人年近四旬，身体素羸弱，于季冬得伤寒证，医者投以麻黄汤汗无分毫，求为诊治，其脉似紧而不任重按，遂于麻黄汤中加生黄耆、天花粉各五钱，一剂得汗而愈。", "19983": "一人亦年近四旬，初得外感，经医甫治愈，即出门作事，又重受外感，内外俱觉寒凉，头疼气息微喘，周身微形寒战，诊其脉六部皆无，重按亦不见，愚不禁骇然，问其心中除觉寒凉外别无所苦，知犹可治，不至有意外之虑，遂于麻黄汤原方中为加生黄耆一两，服药后六脉皆出，周身得微汗，病遂愈。", "19984": "一人，年过三旬，身形素羸弱，又喜吸鸦片。于冬令得伤寒证，因粗通医学，自服麻黄汤，分毫无汗。求为诊视，脉甚微细，无紧象。遂即所用原方，为加生黄耆五钱。服后得汗而愈。此二证皆用麻黄汤是不宜加知母，宜加黄耆者也。", "19985": "尝治一少年，于季冬得伤寒证，其人阴分素亏，脉近六至，且甚弦细，身冷恶寒，舌苔淡白。延医诊视，医者谓脉数而弱，伤寒虽在初得，恐不可用麻黄强发其汗。此时愚应其近邻之聘，因邀愚至其家，与所延之医相商。愚曰：「麻黄发汗之力虽猛，然少用则无妨，再辅以补正之品，自能稳妥奏功矣。」遂为疏方：麻黄钱半，桂枝尖一钱，杏仁、甘草各钱半，又为加生怀山药、北沙参各六钱。嘱其煎汤服后，若至两点钟不出汗，宜服西药阿斯匹林二分许以助其出汗。后果如此服之，周身得汗而愈矣。", "19986": "曾治邻村李姓少年，得伤寒证已过旬日，表证未罢，时或恶寒，头犹微疼，舌苔犹白，心中微觉发热，小便色黄，脉象浮弦，重按似有力，此热入太阳之腑（膀胱）也。投以麻黄汤，为加知母八钱，滑石六钱，服后一汗而愈。", "19987": "《伤寒论》原文：太阳病，发热而渴，不恶寒者，为温病。若发汗已，身灼热者，名曰风温。风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，息必鼾，语言难出。", "19988": "论温病之开端，亦冠以太阳病三字者，因温病亦必自太阳（此是足太阳非手太阳，彼谓温病入手经不入足经者，果何所据也）入也。然其化热最速，不过数小时即侵入阳明，是以不觉恶寒转发热而渴也。治之者不知其为温病，而误以热药发之，竟至汗出不解而转增其灼热，则即此不受热药之发表，可确定其名为风温矣。其脉阴阳俱浮者象风之飘扬也，自汗出者热随浮脉外透也，身重者身体经热酸软也，多眠睡者精神经热昏沉也，语言难出者，上焦有热而舌肿胀也。", "19989": "【附记】林××，年近五旬，因受风温，虽经医治愈，而肺中余热未清，致肺阴铄耗，酿成肺病，屡经医治无效。其脉一息五至，浮沉皆有力，自言喉连肺际，若觉痒则咳嗽顿发，剧时连嗽数十声，周身汗出，必吐出若干稠痰其嗽始止。问其心中常觉发热，大便燥甚，四五日一行。因悟其肺际作痒，即顿发咳嗽者，必其从前病时风邪由皮毛袭入肺中者，至今犹未尽除也。因其肺中风热相助为虐，宜以麻黄祛其风，石膏清其热，遂为开麻杏甘石汤方，麻黄用钱半，生石膏用两半，杏仁三钱，甘草二钱，煎服一剂，咳嗽顿愈。诊其脉仍有力，又为开善后之方，用生山药一两，北沙参、天花粉、天冬各五钱，川贝、射干、苏子、甘草各二钱，嘱其多服数剂，肺病可从此除根。后阅旬日，林××又求诊视，言先生去后，余服所开善后方，肺痒咳嗽仍然反复，遂仍服第一次方，至今已连服十剂，心中热已退，仍分毫不觉药凉，肺痒咳嗽皆愈，且饮食增加，大便亦不甚干燥。闻其所言，诚出愚意料之外也。再诊其脉已不数，仍似有力，遂将方中麻黄改用一钱，石膏改用一两，杏仁改用二钱，又加生怀山药六钱，俾煎汤接续服之，若服之稍觉凉时，即速停止，后连服七八剂似稍觉凉，遂停服，肺病从此竟愈。", "19990": "（附：脉微弱汗出恶风及筋惕肉𥆧治法）", "19991": "有太阳中风之脉，兼见太阳伤寒之脉者，大青龙汤所主之证是也。", "19992": "《伤寒论》原文：太阳中风，脉浮紧，发热，恶寒，身疼痛，不汗出而烦躁，大青龙汤主之。若脉微弱，汗出恶风者，不可服，服则厥逆，筋惕肉𥆧，此为逆也。", "19993": "此大青龙汤所主之证，原系胸中先有蕴热，又为风寒锢其外表，致其胸中之蕴热有蓄极外越之势。而其锢闭之风寒，而犹恐芍药苦降酸敛之性，似于发汗不宜，而代以石膏，且多用之以厚其力，其辛散凉润之性，既能助麻、桂达表，又善化胸中蕴蓄之热为汗，随麻、桂透表而出也，为有云腾致雨之象，是以名为大青龙也。至于脉微弱汗出恶风者，原系胸中大气虚损，不能固摄卫气，即使有热亦是虚阳外浮，若误投以大青龙汤，人必至虚者益虚，其人之元阳因气分虚极而欲脱，遂致肝风萌动而筋惕肉𥆧也。夫大青龙汤既不可用，遇此证者自当另有治法，拟用生黄耆、生杭芍各五钱，麻黄钱半，煎汤一次服下，此用麻黄以逐其外感，黄耆以补其气虚，芍药以清其虚热也。为方中有黄耆以补助气分，故麻黄仍可少用也。若其人已误服大青龙汤，而大汗亡阳，筋惕肉𥆧者，宜去方中麻黄加净萸肉一两。", "19994": "《伤寒论》原文：伤寒脉浮缓，身不疼，但重，乍有轻时，无少阴证者，大青龙汤发之。", "19995": "细思此节之文，知所言之证原系温病，而节首冠以伤寒二字者，因中风、温病在本书之定例，均可名为伤寒也。凡外感之脉多浮，以其多兼中风也。前节言伤寒脉浮紧，是所中者为凛冽之寒风，是中风兼伤寒也。后节言伤寒脉浮缓，知所中者非凛冽之寒风，当为柔和之温风，既中柔和之温风，则即成风温矣。是以病为伤寒必胸中烦躁而后可用石膏，至温病其胸中不烦躁，亦恒可用石膏，且其身不疼但重，伤寒第六节温病提纲中，原明言身重此明征也。况其证乍有轻时，若在伤寒必不复重用石膏，惟温病虽有轻时，亦可重用石膏。又伤寒初得有少阴证，若温病则始终无少阴证（少阴证有寒有热，此言无少阴证，指少阴之寒证而言，少阴寒证断不可用大青龙汤，至少阴热证，原为伏气化热窜入少阴，虽在初得亦可治以大青龙汤，此又不可不知），此尤不为伤寒而为温病之明征也。由此观之，是此节原为治温病者说法，欲其急清燥热以存真阴为先务也。至愚用此方治温病时，恒以薄荷代方中桂枝，尤为稳妥。", "19996": "曾治一人冬日得伤寒证，胸中异常烦躁，医者不识为大青龙汤证，竟投以麻黄汤，服后分毫无汗，胸中烦躁益甚，自觉屋隘莫能容，诊其脉洪滑而浮，治以大青龙汤，为加天花粉八钱，服后五分钟，周身汗出如洗，病若失。", "19997": "愚初为人诊病时，亦不知用也。犹忆岁在乙酉，邻村李××，三十余，得外感痰喘证，求为诊治。其人体丰，素有痰饮，偶因感冒风寒，遂致喘促不休，表里俱无大热，而精神不振，略一合目即昏昏如睡，胸膈又似满闷，不能饮食，舌苔白腻，其脉滑而濡，至数如常。投以散风清火利痰之剂，数次无效。继延他医数人诊治，皆无效。迁延日久，势渐危险，复商治于愚。愚谂一老医皮××，年近八旬，隐居渤海之滨，为之介绍延至。诊视毕，曰：「此易治，小青龙汤证也。」遂开小青龙汤原方，加杏仁三钱，仍用麻黄一钱。一剂喘定。继用苓桂术甘汤加天冬、厚朴，服两剂全愈。", "19998": "愚从此知小青龙汤之神妙。自咎看书未到，遂广阅《伤寒论》诸家注疏，至喻嘉言《尚论篇》论小青龙汤处，不觉狂喜起舞，因叹曰：「使愚早见此名论，何至不知用小青龙汤也。」从此以后，凡遇外感喘证可治以小青龙汤者，莫不投以小青龙汤。而临证细心品验，知外感痰喘之挟热者，其肺必胀，当仿《金匮》用小青龙汤之加石膏，且必重加生石膏方效。迨至癸巳，李××又患外感痰喘，复求愚为诊治，其证脉大略如前，而较前热盛。投以小青龙汤去麻黄，加杏仁三钱，为其有热又加生石膏一两。服后，其喘立止。药力歇后，而喘仍如故。连服两剂皆然。此时皮姓老医已没，无人可以质正，愚方竭力筹思，将为变通其方，其岳家沧州为送医至，愚即告退。后经医数人，皆延自远方，服药月余，竟至不起。", "19999": "平均小青龙汤之药性，当以热论。而外感痰喘之证又有热者十之八九，是以愚用小青龙汤三十余年，未尝一次不加生石膏。即所遇之证分毫不觉热，亦必加生石膏五六钱，使药性之凉热归于平均。若遇证之觉热，或脉象有热者，则必加生石膏两许或一两强。若因其脉虚用人参于汤中者，即其脉分毫无热，亦必加生石膏两许以辅之，始能受人参温补之力。至其证之或兼烦躁，或表里壮热者，又宜加生石膏至两半或至二两，方能奏效。盖如此多用石膏，不惟治外感之热且以解方中药性之热也。为有石膏以监制麻黄，若遇脉之实者，仍宜用麻黄一钱，试举一案以征明之。"});